    private static int RunScalar8Scalar8DataKernelSanity(string[] args)
    {
        DataKernelBackingKind backing = GetBackingOption(args);
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-dk-sanity.lbdx"));
        if (backing == DataKernelBackingKind.File)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.Delete(path);
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: DefaultReservedPrefixBytes,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Create(GetIntOption(args, "--shelf-size", Scalar8Scalar8Profile.Default32KiB.ShelfExtentSize));
        using (DataKernel kernel = OpenKernel(backing, path, FileMode.Create, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            RawDataReservation reservation = kernel.Reserve(profile.ShelfExtentSize);
            Scalar8Scalar8 shelf = new(reservation.Span, profile);
            shelf.Initialize();
            PopulateScalar8Scalar8Shelf(ref shelf, 256);

            DataKernelCommitTelemetry createCommit = kernel.Commit();
            ValidateScalar8Scalar8CommitShape("ss8-8 create", backing, createCommit, profile);

            byte[] readBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, readBack);
            ValidateScalar8Scalar8Sorted(new Scalar8Scalar8ReadOnly(readBack, profile));
            PrintRead("ss8-8 read", kernel.GetAndResetReadTelemetry());

            RawDataReservation rewrite = kernel.ReserveAt(reservation.Extent.Offset, profile.ShelfExtentSize);
            readBack.CopyTo(rewrite.Span);
            Scalar8Scalar8 rewrittenShelf = new(rewrite.Span, profile);
            Scalar8Scalar8InsertResult insertResult = rewrittenShelf.Insert(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(128),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(999_999),
                allowDuplicateKeys: true);
            if (insertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 fixed-offset rewrite insert, got {insertResult}.");
            }

            DataKernelCommitTelemetry rewriteCommit = kernel.Commit();
            ValidateScalar8Scalar8CommitShape("ss8-8 rewrite", backing, rewriteCommit, profile);

            byte[] rewrittenReadBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, rewrittenReadBack);
            Scalar8Scalar8ReadOnly rewrittenReadOnly = new(rewrittenReadBack, profile);
            ValidateScalar8Scalar8Sorted(rewrittenReadOnly);
            if (!rewrittenReadOnly.Contains(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(128),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(999_999)))
            {
                throw new InvalidDataException("SS8-8 fixed-offset rewrite did not persist the inserted tuple.");
            }

            PrintRead("ss8-8 rewrite read", kernel.GetAndResetReadTelemetry());
            Console.WriteLine(backing == DataKernelBackingKind.File
                ? $"ss8-8-dk-sanity ok backing=file path={path} offset={reservation.Extent.Offset}"
                : $"ss8-8-dk-sanity ok backing=memory offset={reservation.Extent.Offset}");
        }

        return 0;
    }

    /// <summary>
    /// Validates `SS16-8` primitive shelf bytes through `DataKernel` append, readback, fixed-offset rewrite, and readback again.<br/>
    /// This keeps the widened-key shape below routing while proving the persisted shelf extent behaves like a fixed-size storage unit.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the `SS16-8` shelf roundtrip and fixed-offset rewrite validate.</returns>
    private static int RunScalar16Scalar8DataKernelSanity(string[] args)
    {
        DataKernelBackingKind backing = GetBackingOption(args);
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss16-8-dk-sanity.lbdx"));
        if (backing == DataKernelBackingKind.File)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.Delete(path);
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: DefaultReservedPrefixBytes,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        Scalar16Scalar8Profile profile = Scalar16Scalar8Profile.Create(GetIntOption(args, "--shelf-size", Scalar16Scalar8Profile.Default32KiB.ShelfExtentSize));
        using (DataKernel kernel = OpenKernel(backing, path, FileMode.Create, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            RawDataReservation reservation = kernel.Reserve(profile.ShelfExtentSize);
            Scalar16Scalar8 shelf = new(reservation.Span, profile);
            shelf.Initialize();
            PopulateScalar16Scalar8Shelf(ref shelf, 256);

            DataKernelCommitTelemetry createCommit = kernel.Commit();
            ValidateScalar16Scalar8CommitShape("ss16-8 create", backing, createCommit, profile);

            byte[] readBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, readBack);
            Scalar16Scalar8ReadOnly readOnly = new(readBack, profile);
            ValidateScalar16Scalar8Sorted(readOnly);
            ValidateScalar16Scalar8ReadbackWindow(readOnly);
            PrintRead("ss16-8 read", kernel.GetAndResetReadTelemetry());

            RawDataReservation rewrite = kernel.ReserveAt(reservation.Extent.Offset, profile.ShelfExtentSize);
            readBack.CopyTo(rewrite.Span);
            Scalar16Scalar8 rewrittenShelf = new(rewrite.Span, profile);
            Scalar16Scalar8InsertResult insertResult = rewrittenShelf.Insert(
                encodedKeyHigh: 1,
                encodedKeyLow: 128,
                encodedIdentity: Scalar16Scalar8Layout.EncodeUnsignedScalar8(999_999),
                allowDuplicateKeys: true);
            if (insertResult != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-8 fixed-offset rewrite insert, got {insertResult}.");
            }

            DataKernelCommitTelemetry rewriteCommit = kernel.Commit();
            ValidateScalar16Scalar8CommitShape("ss16-8 rewrite", backing, rewriteCommit, profile);

            byte[] rewrittenReadBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, rewrittenReadBack);
            Scalar16Scalar8ReadOnly rewrittenReadOnly = new(rewrittenReadBack, profile);
            ValidateScalar16Scalar8Sorted(rewrittenReadOnly);
            if (!rewrittenReadOnly.Contains(1, 128, Scalar16Scalar8Layout.EncodeUnsignedScalar8(999_999)))
            {
                throw new InvalidDataException("SS16-8 fixed-offset rewrite did not persist inserted tuple.");
            }

            ValidateScalar16Scalar8ReadbackWindow(rewrittenReadOnly);
            PrintRead("ss16-8 rewrite read", kernel.GetAndResetReadTelemetry());
            Console.WriteLine(backing == DataKernelBackingKind.File
                ? $"ss16-8-dk-sanity ok backing=file path={path} offset={reservation.Extent.Offset}"
                : $"ss16-8-dk-sanity ok backing=memory offset={reservation.Extent.Offset}");
        }

        return 0;
    }

