    /// <summary>
    /// Validates `SS8-16` primitive shelf bytes through `DataKernel` append, readback, fixed-offset rewrite, and readback again.<br/>
    /// This keeps the widened-identity shape below routing while proving the persisted shelf extent behaves like a fixed-size storage unit.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the `SS8-16` shelf roundtrip and fixed-offset rewrite validate.</returns>
    private static int RunScalar8Scalar16DataKernelSanity(string[] args)
    {
        DataKernelBackingKind backing = GetBackingOption(args);
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-16-dk-sanity.lbdx"));
        if (backing == DataKernelBackingKind.File)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.Delete(path);
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: DefaultReservedPrefixBytes,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        Scalar8Scalar16Profile profile = Scalar8Scalar16Profile.Create(GetIntOption(args, "--shelf-size", Scalar8Scalar16Profile.Default32KiB.ShelfExtentSize));
        using (DataKernel kernel = OpenKernel(backing, path, FileMode.Create, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            RawDataReservation reservation = kernel.Reserve(profile.ShelfExtentSize);
            Scalar8Scalar16 shelf = new(reservation.Span, profile);
            shelf.Initialize();
            PopulateScalar8Scalar16Shelf(ref shelf, 256);

            DataKernelCommitTelemetry createCommit = kernel.Commit();
            ValidateScalar8Scalar16CommitShape("ss8-16 create", backing, createCommit, profile);

            byte[] readBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, readBack);
            Scalar8Scalar16ReadOnly readOnly = new(readBack, profile);
            ValidateScalar8Scalar16Sorted(readOnly);
            ValidateScalar8Scalar16ReadbackWindow(readOnly);
            PrintRead("ss8-16 read", kernel.GetAndResetReadTelemetry());

            RawDataReservation rewrite = kernel.ReserveAt(reservation.Extent.Offset, profile.ShelfExtentSize);
            readBack.CopyTo(rewrite.Span);
            Scalar8Scalar16 rewrittenShelf = new(rewrite.Span, profile);
            Scalar8Scalar16InsertResult insertResult = rewrittenShelf.Insert(
                encodedKey: Scalar8Scalar16Layout.EncodeUnsignedScalar8(128),
                encodedIdentityHigh: 1,
                encodedIdentityLow: 999_999,
                allowDuplicateKeys: true);
            if (insertResult != Scalar8Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-16 fixed-offset rewrite insert, got {insertResult}.");
            }

            DataKernelCommitTelemetry rewriteCommit = kernel.Commit();
            ValidateScalar8Scalar16CommitShape("ss8-16 rewrite", backing, rewriteCommit, profile);

            byte[] rewrittenReadBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, rewrittenReadBack);
            Scalar8Scalar16ReadOnly rewrittenReadOnly = new(rewrittenReadBack, profile);
            ValidateScalar8Scalar16Sorted(rewrittenReadOnly);
            if (!rewrittenReadOnly.Contains(Scalar8Scalar16Layout.EncodeUnsignedScalar8(128), 1, 999_999))
            {
                throw new InvalidDataException("SS8-16 fixed-offset rewrite did not persist inserted tuple.");
            }

            ValidateScalar8Scalar16ReadbackWindow(rewrittenReadOnly);
            PrintRead("ss8-16 rewrite read", kernel.GetAndResetReadTelemetry());
            Console.WriteLine(backing == DataKernelBackingKind.File
                ? $"ss8-16-dk-sanity ok backing=file path={path} offset={reservation.Extent.Offset}"
                : $"ss8-16-dk-sanity ok backing=memory offset={reservation.Extent.Offset}");
        }

        return 0;
    }

