    /// <summary>
    /// Validates the first persisted root-router to `SS8-8` shelf integration path.<br/>
    /// The command creates a root router, appends one 32 KiB shelf, links prefix byte `0x00` to it, and reads it back through routing.<br/>
    /// It checks seek-one, range-walk, scoop behavior, and DataKernel read/write syscall shape for the composed path.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed shelf validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RouteSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-route-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--item-count", 512);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        if (itemCount <= 0 || itemCount > profile.MaxItemCount)
        {
            Console.Error.WriteLine($"ss8-8-route-sanity item count must be between 1 and {profile.MaxItemCount}.");
            return 1;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteSanity",
            DevCustomText: "ss8-8 routed shelf",
            DevGuid: Guid.Parse("a7971228-7fdf-49af-9baa-0ac376dc0e6f"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 3);

        long rootOffset;
        long shelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8route", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("ss8-8 route root create", rootCommit);
            ValidateRootRouter(session, root);
            rootOffset = root.Offset;
            _ = session.GetAndResetReadTelemetry();

            (shelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(rootOffset, 0x00, profile, itemCount);
            PrintCommit("ss8-8 route shelf link", linkCommit);
            ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile);
            PrintRead("ss8-8 route link read", session.GetAndResetReadTelemetry());

            ValidateRoutedScalar8Scalar8Shelf(session, rootOffset, shelfOffset, profile, itemCount);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ReadOnlySpan<IndexDirectorySlotSnapshot> activeSlots = reopened.IndexDirectory.ActiveSlots;
            if (activeSlots.Length != 1 || activeSlots[0].RootRouterOffset != rootOffset)
            {
                throw new InvalidDataException("Reopened routed SS8-8 index directory did not preserve the root-router offset.");
            }

            ValidateRoutedScalar8Scalar8Shelf(reopened, rootOffset, shelfOffset, profile, itemCount);
        }

        Console.WriteLine($"ss8-8-route-sanity ok path={path} root={rootOffset} shelf={shelfOffset} size={profile.ShelfExtentSize} items={itemCount}");
        return 0;
    }

