    /// <summary>
    /// Validates the first routed `SS8-8` no-split insert mutation path.<br/>
    /// The command creates one routed shelf, inserts one new tuple through the route, and verifies that only the shelf extent is rewritten.<br/>
    /// It intentionally avoids split handling so the no-split dirty/write contract is proven before structural split behavior is added.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed no-split insert validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RouteInsertSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-route-insert-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--item-count", 512);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        if (itemCount <= 0 || itemCount + 1 > profile.MaxItemCount)
        {
            Console.Error.WriteLine($"ss8-8-route-insert-sanity item count must be between 1 and {profile.MaxItemCount - 1}.");
            return 1;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteInsertSanity",
            DevCustomText: "ss8-8 routed insert",
            DevGuid: Guid.Parse("1d79a163-9aa9-46f8-88a6-bc344bd33b77"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 4);

        long rootOffset;
        long shelfOffset;
        ulong insertedKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(itemCount + 128));
