            rootOffset = root.Offset;

            (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar16Scalar8ShelfAndLinkRootRoutes(
                rootOffset,
                profile,
                encodedKeyHighs,
                encodedKeyLows,
                encodedIdentities,
                [0x00]);
            PrintCommit("ss16-8 transform source shelf link", linkCommit);
            ValidateScalar16Scalar8RouteLinkCommit(linkCommit, profile);
            _ = session.GetAndResetReadTelemetry();

            (
                long transformedOffset,
                long splitLeftOffset,
                long splitRightOffset,
                int splitLeftCount,
                int splitRightCount,
                Scalar16Scalar8InsertResult insertResult,
                DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar16Scalar8ByShelfTransform(
                    rootOffset,
                    0x00,
                    0x80,
                    profile,
                    insertedKeyHigh,
                    insertedKeyLow,
                    insertedIdentity);

            if (transformedOffset != sourceShelfOffset || insertResult != Scalar16Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-8 transform split to reuse shelf offset {sourceShelfOffset}, got offset {transformedOffset} result {insertResult}.");
            }

            childRouterOffset = transformedOffset;
            leftShelfOffset = splitLeftOffset;
            rightShelfOffset = splitRightOffset;
            if (leftShelfOffset == 0 || rightShelfOffset == 0 || leftShelfOffset == rightShelfOffset)
            {
                throw new InvalidDataException("SS16-8 transform split did not allocate distinct replacement shelves.");
            }

