        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            key0s[index] = 0;
            key1s[index] = 0;
            key2s[index] = 0;
            key3s[index] = (ulong)i;
            encodedIdentities[index] = Fixed32Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            index++;
        }

        const ulong secondByteRightBase0 = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            key0s[index] = secondByteRightBase0;
            key1s[index] = 0;
            key2s[index] = 0;
            key3s[index] = (ulong)i;
            encodedIdentities[index] = Fixed32Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            index++;
        }

        ulong insertedKey0 = secondByteRightBase0;
        ulong insertedKey1 = 0;
        ulong insertedKey2 = 0;
