            ValidateTwoLevelRoutedFixed32Scalar8ShelfShape(session, rootOffset, 0x00, 0x00, childRouterOffset, leftShelfOffset, profile, leftCount, 0, 0, 0, 128, Fixed32Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateTwoLevelRoutedFixed32Scalar8ShelfShape(session, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 1, insertedKey0, insertedKey1, insertedKey2, insertedKey3, insertedIdentity);
