    /// <summary>
    /// Validates the unified internal routed `SS8-8` insert decision path across the three currently supported structural outcomes.<br/>
    /// The command uses separate files for no-split, root-prefix split, and same-prefix transform split so each scenario has deterministic route state and telemetry.<br/>
    /// This is an orchestration sanity check, not a replacement for the narrower mutation-shape tests.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all routed insert decision scenarios succeed; otherwise one.</returns>
    private static int RunScalar8Scalar8RoutedInsertDecisionSanity(string[] args)
    {
        string basePath = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-routed-insert-decision-sanity.lbdx"));
        string directory = Path.GetDirectoryName(basePath)!;
        string fileName = Path.GetFileNameWithoutExtension(basePath);
        Directory.CreateDirectory(directory);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        string noSplitPath = Path.Combine(directory, fileName + "-nosplit.lbdx");
        string rootSplitPath = Path.Combine(directory, fileName + "-rootsplit.lbdx");
        string transformPath = Path.Combine(directory, fileName + "-transform.lbdx");
        File.Delete(noSplitPath);
        File.Delete(rootSplitPath);
        File.Delete(transformPath);

        RunScalar8Scalar8RoutedInsertDecisionNoSplit(noSplitPath, profile);
        RunScalar8Scalar8RoutedInsertDecisionRootSplit(rootSplitPath, profile);
        RunScalar8Scalar8RoutedInsertDecisionTransform(transformPath, profile);

        Console.WriteLine($"ss8-8-routed-insert-decision-sanity ok basePath={basePath} size={profile.ShelfExtentSize}");
        return 0;
    }

