            if (childRouterOffset != sourceShelfOffset || splitResult != Scalar16Scalar16InsertResult.Inserted || splitRightCount != rightCount + 1)
            {
                throw new InvalidDataException("Two-level SS16-16 insert setup transform split did not produce the expected right shelf.");
            }

            PrintRead("ss16-16 two-level transform read", session.GetAndResetReadTelemetry());
            PrintCommit("ss16-16 two-level transform commit", transformCommit);
            ValidateScalar16Scalar16TransformCommit(transformCommit, profile);
            _ = session.GetAndResetReadTelemetry();

            (long routedChildOffset, long routedShelfOffset, Scalar16Scalar16InsertResult insertResult, DataKernelCommitTelemetry insertCommit) = session.InsertTwoLevelRoutedScalar16Scalar16NoSplit(
                rootOffset,
                0x00,
                0x80,
                profile,
                insertedKeyHigh,
                insertedKeyLow,
                insertedIdentityHigh,
                insertedIdentityLow,
                allowDuplicateKeys: true);
            if (routedChildOffset != childRouterOffset || routedShelfOffset != rightShelfOffset || insertResult != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected two-level SS16-16 no-split insert at child/shelf {childRouterOffset}/{rightShelfOffset}, got {routedChildOffset}/{routedShelfOffset} result {insertResult}.");
            }

            PrintRead("ss16-16 two-level insert read", session.GetAndResetReadTelemetry());
            PrintCommit("ss16-16 two-level insert commit", insertCommit);
            ValidateScalar16Scalar16RouteInsertCommit(insertCommit, profile);
            ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(session, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 2, insertedKeyHigh, insertedKeyLow, insertedIdentityHigh, insertedIdentityLow);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(reopened, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 2, insertedKeyHigh, insertedKeyLow, insertedIdentityHigh, insertedIdentityLow);
        }

        Console.WriteLine($"ss16-16-two-level-insert-sanity ok path={path} root={rootOffset} child={childRouterOffset} shelf={rightShelfOffset} size={profile.ShelfExtentSize} items={rightCount + 2}");
        return 0;
    }

