    /// <summary>
    /// Validates the first deeper `SS8-8` split reached through the classified route walker.<br/>
    /// The full shelf sits below a child router, and the mutation transforms that full shelf into a next-depth router without rewriting the parent router.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the walked transform split validates; otherwise one.</returns>
    private static int RunScalar8Scalar8WalkedTransformSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-walked-transform-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        CreateDeeperTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexWalkedTransform",
            DevCustomText: "ss8-8 walked transform split",
            DevGuid: Guid.Parse("a838b3d2-4169-42d9-b25d-82f6cf5b0e68"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 15);

        const ulong thirdByteRightBase = 0x0000_8000_0000_0000UL;
        ulong insertedKey = thirdByteRightBase + 10_000UL;
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8wtx0", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss8-8 walked transform root create", rootCommit);
        (
            long childRouterOffset,
            long sourceShelfOffset,
            DataKernelCommitTelemetry setupCommit) = session.CreateScalar8Scalar8ShelfBehindChildRouter(
                root.Offset,
                0x00,
                0x00,
                profile,
                keys,
                identities);
        PrintCommit("ss8-8 walked transform setup", setupCommit);
        _ = session.GetAndResetReadTelemetry();

        Scalar8Scalar8RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar8(
            root.Offset,
            profile,
            insertedKey,
            insertedKey,
            allowDuplicateKeys: true,
            maxRouterHops: 8);
        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss8-8 walked transform read", readTelemetry);
        PrintCommit("ss8-8 walked transform commit", result.Commit);
        if (result.Kind != Scalar8Scalar8RoutedInsertKind.WalkedShelfTransformSplit || result.PrimaryOffset != sourceShelfOffset || result.LeftShelfOffset == 0 || result.RightShelfOffset == 0 || result.InsertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Walked transform split did not return the expected storage-facing result.");
        }

        if (readTelemetry.ReadCallCount != 5 || readTelemetry.BytesRead != RouterLayout.Size + sizeof(uint) + RouterLayout.Size + sizeof(uint) + profile.ShelfExtentSize)
        {
            throw new InvalidDataException("Walked transform split should read root router, child classifier, child router, shelf classifier, and one full shelf.");
        }

        ValidateScalar8Scalar8TransformCommit(result.Commit, profile);
        long rootTargetAfter = session.FindRouterTarget(root.Offset, 0x00);
        long childTargetAfter = session.FindRouterTarget(childRouterOffset, 0x00);
        if (rootTargetAfter != childRouterOffset || childTargetAfter != sourceShelfOffset)
        {
            throw new InvalidDataException("Walked transform split dirtied a parent route unexpectedly.");
        }

        Scalar8Scalar8RouteTarget routedTarget = session.WalkScalar8Scalar8RouteTarget(root.Offset, insertedKey, maxRouterHops: 8);
        if (routedTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf || routedTarget.Offset != result.RightShelfOffset || routedTarget.RouterDepth != 2)
        {
            throw new InvalidDataException("Walked transform split did not route inserted key through the new next-depth router.");
        }

        _ = session.GetAndResetReadTelemetry();
        ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(
            session,
            childRouterOffset,
            0x00,
            0x80,
            result.PrimaryOffset,
            result.RightShelfOffset,
            profile,
            profile.MaxItemCount / 2 + 1,
            insertedKey,
            insertedKey);

        Console.WriteLine($"ss8-8-walked-transform-sanity ok path={path} root={root.Offset} child={childRouterOffset} transformed={result.PrimaryOffset} left={result.LeftShelfOffset} right={result.RightShelfOffset} size={profile.ShelfExtentSize}");
        return 0;
    }

