        CreateFixed32Scalar8DeeperTransformSplitVectors(profile, out ulong[] key0s, out ulong[] key1s, out ulong[] key2s, out ulong[] key3s, out ulong[] identities, out int _, out int rightCount);
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexF328WalkedTransform",
            DevCustomText: "fs32-8 walked transform split",
            DevGuid: Guid.Parse("c488fbbd-1ef4-4a2f-a736-95df562b9971"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 18);

        const ulong insertedKey0 = 0x0000_8000_0000_0000UL;
        const ulong insertedKey1 = 0;
        const ulong insertedKey2 = 0;
        const ulong insertedKey3 = 10_000UL;
        ulong insertedIdentity = Fixed32Scalar8Layout.EncodeUnsignedScalar8(10_000UL);
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "f328wtx", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("fs32-8 walked transform root create", rootCommit);
        (
            long childRouterOffset,
            long sourceShelfOffset,
            DataKernelCommitTelemetry setupCommit) = session.CreateFixed32Scalar8ShelfBehindChildRouter(
                root.Offset,
                0x00,
                0x00,
                profile,
                key0s,
                key1s,
                key2s,
                key3s,
                identities);
        PrintCommit("fs32-8 walked transform setup", setupCommit);
        _ = session.GetAndResetReadTelemetry();

        (
            long transformedRouterOffset,
            long leftShelfOffset,
            long rightShelfOffset,
            _,
            _,
            Fixed32Scalar8InsertResult insertResult,
            DataKernelCommitTelemetry commit) = session.SplitWalkedRoutedFixed32Scalar8ByShelfTransform(
                root.Offset,
                profile,
                insertedKey0,
                insertedKey1,
                insertedKey2,
                insertedKey3,
                insertedIdentity,
                maxRouterHops: 8);
        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("fs32-8 walked transform read", readTelemetry);
        PrintCommit("fs32-8 walked transform commit", commit);
        if (transformedRouterOffset != sourceShelfOffset || leftShelfOffset == 0 || rightShelfOffset == 0 || insertResult != Fixed32Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Walked FS32-8 transform split did not return the expected storage-facing result.");
        }

        if (readTelemetry.ReadCallCount != 5 || readTelemetry.BytesRead != RouterLayout.Size + sizeof(uint) + RouterLayout.Size + sizeof(uint) + profile.ShelfExtentSize)
        {
            throw new InvalidDataException("Walked FS32-8 transform split should read root router, child classifier, child router, shelf classifier, and one full shelf.");
        }

        ValidateFixed32Scalar8TransformCommit(commit, profile);
        long rootTargetAfter = session.FindRouterTarget(root.Offset, 0x00);
        long childTargetAfter = session.FindRouterTarget(childRouterOffset, 0x00);
        if (rootTargetAfter != childRouterOffset || childTargetAfter != sourceShelfOffset)
        {
            throw new InvalidDataException("Walked FS32-8 transform split dirtied a parent route unexpectedly.");
        }

        Fixed32Scalar8RouteTarget routedTarget = session.WalkFixed32Scalar8RouteTarget(root.Offset, insertedKey0, insertedKey1, insertedKey2, insertedKey3, maxRouterHops: 8);
        if (routedTarget.Kind != Fixed32Scalar8RouteTargetKind.Shelf || routedTarget.Offset != rightShelfOffset || routedTarget.RouterDepth != 2)
        {
            throw new InvalidDataException("Walked FS32-8 transform split did not route inserted key through the new next-depth router.");
        }

        _ = session.GetAndResetReadTelemetry();
        ValidateTwoLevelRoutedFixed32Scalar8ShelfShape(
            session,
            childRouterOffset,
            0x00,
            0x80,
            transformedRouterOffset,
            rightShelfOffset,
            profile,
            rightCount + 1,
            insertedKey0,
            insertedKey1,
            insertedKey2,
            insertedKey3,
            insertedIdentity);

        Console.WriteLine($"fs32-8-walked-transform-sanity ok path={path} root={root.Offset} child={childRouterOffset} transformed={transformedRouterOffset} left={leftShelfOffset} right={rightShelfOffset} size={profile.ShelfExtentSize}");
        return 0;
    }

