    /// <summary>
    /// Measures the currently validated `SS8-8` routed mutation shapes as isolated design-performance scenarios.<br/>
    /// This is not a full bulk-load benchmark; it measures the mutation slice after deterministic setup so syscall shape and route depth costs remain visible.<br/>
    /// Each sample uses a fresh file to avoid carrying unimplemented deeper split behavior into the first design-level performance numbers.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all scenario measurements complete.</returns>
    private static int RunScalar8Scalar8DesignPerf(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SS8-8DesignPerf"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int runs = GetIntOption(args, "--runs", 30);
        if (runs <= 0)
        {
            Console.Error.WriteLine("ss8-8-design-perf requires a positive run count.");
            return 1;
        }

        Directory.CreateDirectory(directory);
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        Scalar8Scalar8DesignPerfResult[] results =
        [
            MeasureScalar8Scalar8DesignScenario("direct no-split", runs, static (path, profile) => MeasureScalar8Scalar8DesignDirectNoSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("root-prefix split", runs, static (path, profile) => MeasureScalar8Scalar8DesignRootPrefixSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("transform split", runs, static (path, profile) => MeasureScalar8Scalar8DesignTransformSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("direct two-level no-split", runs, static (path, profile) => MeasureScalar8Scalar8DesignDirectTwoLevelNoSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("walked two-level no-split", runs, static (path, profile) => MeasureScalar8Scalar8DesignWalkedTwoLevelNoSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("walked transform split", runs, static (path, profile) => MeasureScalar8Scalar8DesignWalkedTransformSplit(path, profile), directory, profile)
        ];

        Console.WriteLine("ss8-8 design perf");
        Console.WriteLine($"runs {runs:N0}");
        Console.WriteLine($"shelfSize {profile.ShelfExtentSize:N0}");
        PrintScalar8Scalar8DesignPerfHeader();
        for (int i = 0; i < results.Length; i++)
        {
            PrintScalar8Scalar8DesignPerf(results[i]);
        }

        string reportPath = WriteScalar8Scalar8DesignPerfReport(artifactDirectory, runs, profile, results);
        Console.WriteLine($"ss8-8 design perf report {Path.GetFullPath(reportPath)}");
        return 0;
    }

