    /// <summary>
    /// Sweeps `SS16-16` shelf sizes across the validated unified walked-decision mutation outcomes.<br/>
    /// Each row uses the same measured mutation paths as `ss16-16-design-perf`, varying only the `Scalar16Scalar16Profile` shelf extent.<br/>
    /// This is intended to identify whether the 32 KiB default remains a good working anchor before optimizing or drying the shape.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all shelf-size measurements complete.</returns>
    private static int RunScalar16Scalar16SizeSweep(string[] args)
    {
        int[] shelfSizes = ParseIntList(GetOption(args, "--shelf-sizes", "16384,24576,32768,49152,65536"));
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SS16-16SizeSweep"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int runs = GetIntOption(args, "--runs", 30);
        if (runs <= 0 || shelfSizes.Length == 0)
        {
            Console.Error.WriteLine("ss16-16-size-sweep requires a positive run count and at least one shelf size.");
            return 1;
        }

        Directory.CreateDirectory(directory);
        Scalar16Scalar16Profile[] profiles = new Scalar16Scalar16Profile[shelfSizes.Length];
        for (int i = 0; i < shelfSizes.Length; i++)
        {
            profiles[i] = Scalar16Scalar16Profile.Create(shelfSizes[i]);
        }

        const int scenariosPerProfile = 3;
        Scalar8Scalar8DesignPerfResult[] results = new Scalar8Scalar8DesignPerfResult[profiles.Length * scenariosPerProfile];
        int resultIndex = 0;
        for (int profileIndex = 0; profileIndex < profiles.Length; profileIndex++)
        {
            Scalar16Scalar16Profile profile = profiles[profileIndex];
            string profileDirectory = Path.Combine(directory, profile.ShelfExtentSize.ToString(CultureInfo.InvariantCulture));
            Directory.CreateDirectory(profileDirectory);
            results[resultIndex++] = MeasureScalar16Scalar16DesignScenario("walked no-split", runs, static (path, profile) => MeasureScalar16Scalar16DesignWalkedNoSplit(path, profile), profileDirectory, profile);
            results[resultIndex++] = MeasureScalar16Scalar16DesignScenario("walked transform split", runs, static (path, profile) => MeasureScalar16Scalar16DesignWalkedTransformSplit(path, profile), profileDirectory, profile);
            results[resultIndex++] = MeasureScalar16Scalar16DesignScenario("walked parent-route split", runs, static (path, profile) => MeasureScalar16Scalar16DesignWalkedParentRouteSplit(path, profile), profileDirectory, profile);
        }

        Console.WriteLine("ss16-16 size sweep");
        Console.WriteLine($"runs {runs:N0}");
        Console.WriteLine("shelf   maxItems scenario                      avg ms    sd ms     reads  bytes/read  writes  bytes/write  writeB/maxItem setlen");
        Console.WriteLine("------- -------- ---------------------------- -------- -------- -------- ----------- ------- ------------ -------------- -------");
        resultIndex = 0;
        for (int profileIndex = 0; profileIndex < profiles.Length; profileIndex++)
        {
            Scalar16Scalar16Profile profile = profiles[profileIndex];
            for (int scenarioIndex = 0; scenarioIndex < scenariosPerProfile; scenarioIndex++)
            {
                PrintScalar16Scalar16SizeSweep(profile, results[resultIndex++]);
            }
        }

        string reportPath = WriteScalar16Scalar16SizeSweepReport(artifactDirectory, runs, profiles, results);
        Console.WriteLine($"ss16-16 size sweep report {Path.GetFullPath(reportPath)}");
        return 0;
    }

