    /// <summary>
    /// Validates that transformed `SS8-8` shelf extent slack can host additional 4 KiB router pages before appending new file data.<br/>
    /// The command fills the `28 KiB` remainder of a transformed 32 KiB shelf extent with seven routers, then confirms the next router appends normally.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when router arena allocation validates; otherwise one.</returns>
    private static int RunScalar8Scalar8RouterArenaSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-router-arena-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        CreateTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        long transformedRouterOffset;
        long lengthAfterTransform;
        long lengthAfterArenaFill;
        long lengthAfterAppend;
        DataKernelCommitTelemetry arenaCommit;
        DataKernelCommitTelemetry appendCommit;
        int arenaRouterCount = (profile.ShelfExtentSize - RouterLayout.Size) / RouterLayout.Size;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(41), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8arena", 0));
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
            const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
            ulong insertedKey = secondByteRightBase + 10_000UL;
            (
                transformedRouterOffset,
                _,
                _,
                _,
                _,
                _,
                _) = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x00, 0x80, profile, insertedKey, insertedKey);
            lengthAfterTransform = GetFileLength(path);

            long firstArenaRouterOffset = transformedRouterOffset + RouterLayout.Size;
            (RouterSnapshot[] arenaRouters, DataKernelCommitTelemetry fillCommit) = session.CreateExpandedOneByteRoutersAt(
                firstArenaRouterOffset,
                arenaRouterCount,
                keyDepth: 2,
                allocationClassId: 0,
                arenaBaseOffset: transformedRouterOffset,
                arenaLength: profile.ShelfExtentSize);
            arenaCommit = fillCommit;
            lengthAfterArenaFill = GetFileLength(path);
            if (lengthAfterArenaFill != lengthAfterTransform)
            {
                throw new InvalidDataException("Router arena fill unexpectedly grew the file.");
            }

            if (arenaRouters.Length != arenaRouterCount || arenaRouters[0].Offset != firstArenaRouterOffset || arenaRouters[^1].Offset != firstArenaRouterOffset + ((arenaRouterCount - 1L) * RouterLayout.Size))
            {
                throw new InvalidDataException("Router arena offsets did not occupy the expected transformed shelf slack.");
            }

            RouterSnapshot transformedRouter = session.ReadRouterSnapshot(transformedRouterOffset);
            if (!transformedRouter.IsArenaMember || transformedRouter.ArenaBaseDelta != 0 || transformedRouter.ArenaLength != profile.ShelfExtentSize || transformedRouter.ArenaRouterPageIndex != 0 || transformedRouter.ArenaRouterPageCount != profile.ShelfExtentSize / RouterLayout.Size)
            {
                throw new InvalidDataException("Transformed router arena metadata did not match the expected arena base.");
            }

            for (int i = 0; i < arenaRouters.Length; i++)
            {
                RouterSnapshot arenaRouter = session.ReadRouterSnapshot(arenaRouters[i].Offset);
                int expectedDelta = checked((int)(transformedRouterOffset - arenaRouter.Offset));
                ushort expectedIndex = checked((ushort)(i + 1));
                if (!arenaRouter.IsArenaMember || arenaRouter.ArenaBaseDelta != expectedDelta || arenaRouter.ArenaLength != profile.ShelfExtentSize || arenaRouter.ArenaRouterPageIndex != expectedIndex || arenaRouter.ArenaRouterPageCount != profile.ShelfExtentSize / RouterLayout.Size)
                {
                    throw new InvalidDataException("Arena router relative metadata did not match the expected transformed shelf arena.");
                }
            }

            (RouterSnapshot appendedRouter, DataKernelCommitTelemetry normalAppendCommit) = session.CreateExpandedOneByteRouter(keyDepth: 2, allocationClassId: 0);
            appendCommit = normalAppendCommit;
            lengthAfterAppend = GetFileLength(path);
            if (appendedRouter.Offset != lengthAfterArenaFill || lengthAfterAppend != lengthAfterArenaFill + RouterLayout.Size)
            {
                throw new InvalidDataException("Router allocation after arena exhaustion did not append exactly one router page.");
            }
        }

        Console.WriteLine("ss8-8 router arena");
        Console.WriteLine($"transformedRouterOffset {transformedRouterOffset}");
        Console.WriteLine($"arenaRouterCount {arenaRouterCount}");
        Console.WriteLine($"lengthAfterTransform {lengthAfterTransform}");
        Console.WriteLine($"lengthAfterArenaFill {lengthAfterArenaFill}");
        Console.WriteLine($"lengthAfterAppend {lengthAfterAppend}");
        PrintCommit("ss8-8 router arena fill", arenaCommit);
        PrintCommit("ss8-8 router arena exhausted append", appendCommit);
        Console.WriteLine($"ss8-8-router-arena-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates the first router micro-arena allocation policy: local arena first, then another same-index arena, then append fallback.<br/>
    /// This command uses two transformed shelf arenas in one session so the allocator can exercise all three policy branches deterministically.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the router arena policy validates; otherwise one.</returns>
    private static int RunScalar8Scalar8RouterArenaPolicySanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-router-arena-policy-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        CreateTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        int arenaExtraRouterCount = (profile.ShelfExtentSize / RouterLayout.Size) - 1;
        long firstArenaBase;
        long secondArenaBase;
        RouterArenaAllocationResult localResult;
        RouterArenaAllocationResult indexResult;
        RouterArenaAllocationResult appendResult;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(42), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8arpol", 0));
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
            const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
            ulong insertedKey = secondByteRightBase + 10_000UL;
            (
                firstArenaBase,
                _,
                _,
                _,
                _,
                _,
                _) = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x00, 0x80, profile, insertedKey, insertedKey);

            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x01]);
            ulong secondInsertedKey = 0x0180_0000_0000_0000UL + 10_000UL;
            (
                secondArenaBase,
                _,
                _,
                _,
                _,
                _,
                _) = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x01, 0x80, profile, secondInsertedKey, secondInsertedKey);

            localResult = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: firstArenaBase);
            if (localResult.Kind != RouterArenaAllocationKind.LocalArena || localResult.ArenaBaseOffset != firstArenaBase || localResult.ArenaPageIndex != 1)
            {
                throw new InvalidDataException("Router arena policy did not allocate from the preferred local arena first.");
            }

            for (int i = 1; i < arenaExtraRouterCount; i++)
            {
                RouterArenaAllocationResult fill = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: firstArenaBase);
                if (fill.Kind != RouterArenaAllocationKind.LocalArena || fill.ArenaBaseOffset != firstArenaBase || fill.ArenaPageIndex != i + 1)
                {
                    throw new InvalidDataException("Router arena policy did not continue filling the local arena in order.");
                }
            }

            indexResult = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: firstArenaBase);
            if (indexResult.Kind != RouterArenaAllocationKind.IndexArena || indexResult.ArenaBaseOffset != secondArenaBase || indexResult.ArenaPageIndex != 1)
            {
                throw new InvalidDataException("Router arena policy did not fall back to another same-index arena after local exhaustion.");
            }

            for (int i = 1; i < arenaExtraRouterCount; i++)
            {
                RouterArenaAllocationResult fill = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: firstArenaBase);
                if (fill.Kind != RouterArenaAllocationKind.IndexArena || fill.ArenaBaseOffset != secondArenaBase || fill.ArenaPageIndex != i + 1)
                {
                    throw new InvalidDataException("Router arena policy did not continue filling the index fallback arena in order.");
                }
            }

            long lengthBeforeAppend = GetFileLength(path);
            appendResult = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: firstArenaBase);
            long lengthAfterAppend = GetFileLength(path);
            if (appendResult.Kind != RouterArenaAllocationKind.Append || appendResult.Router.Offset != lengthBeforeAppend || lengthAfterAppend != lengthBeforeAppend + RouterLayout.Size)
            {
                throw new InvalidDataException("Router arena policy did not append after all registered arenas were exhausted.");
            }
        }

        Console.WriteLine("ss8-8 router arena policy");
        Console.WriteLine($"firstArenaBase {firstArenaBase}");
        Console.WriteLine($"secondArenaBase {secondArenaBase}");
        Console.WriteLine($"extraRoutersPerArena {arenaExtraRouterCount}");
        Console.WriteLine($"localResult kind={localResult.Kind} page={localResult.ArenaPageIndex} offset={localResult.Router.Offset}");
        Console.WriteLine($"indexResult kind={indexResult.Kind} page={indexResult.ArenaPageIndex} offset={indexResult.Router.Offset}");
        Console.WriteLine($"appendResult kind={appendResult.Kind} offset={appendResult.Router.Offset}");
        Console.WriteLine($"ss8-8-router-arena-policy-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates the first arena-aware router read cache for transformed `SS8-8` shelf arenas.<br/>
    /// The scenario compares the existing uncached classified walker with an arena-aware walker over the same two-level route graph.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the arena read-cache shape validates; otherwise one.</returns>
    private static int RunScalar8Scalar8RouterArenaReadCacheSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-router-arena-read-cache-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        CreateTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        DataKernelReadTelemetry uncachedRead;
        DataKernelReadTelemetry firstCachedRead;
        DataKernelReadTelemetry secondCachedRead;
        DataKernelReadTelemetry nonEntryCachedRead;
        long childRouterOffset;
        long rightShelfOffset;
        long nonEntryRouterOffset;
        long nonEntryShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(43), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8arcache", 0));
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
            const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
            ulong insertedKey = secondByteRightBase + 10_000UL;
            (
                childRouterOffset,
                _,
                rightShelfOffset,
                _,
                _,
                _,
                _) = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x00, 0x80, profile, insertedKey, insertedKey);

            _ = session.GetAndResetReadTelemetry();
            Scalar8Scalar8RouteTarget uncachedTarget = session.WalkScalar8Scalar8RouteTarget(root.Offset, insertedKey, maxRouterHops: 8);
            if (uncachedTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf || uncachedTarget.Offset != rightShelfOffset || uncachedTarget.RouterDepth != 1)
            {
                throw new InvalidDataException("Uncached walker did not resolve the expected two-level shelf target.");
            }

            uncachedRead = session.GetAndResetReadTelemetry();
            if (uncachedRead.ReadCallCount != 4 || uncachedRead.BytesRead != RouterLayout.Size + profile.ShelfExtentSize + (sizeof(uint) * 2))
            {
                throw new InvalidDataException($"Default walker should use router arena metadata to load the transformed child arena on first touch; actual reads={uncachedRead.ReadCallCount}, bytes={uncachedRead.BytesRead}.");
            }

            session.ClearRouterArenaReadCacheForValidation();
            Scalar8Scalar8RouteTarget firstCachedTarget = session.WalkScalar8Scalar8RouteTarget(root.Offset, insertedKey, maxRouterHops: 8, Scalar8Scalar8RouteReadPolicy.PreferArenaCache);
            if (firstCachedTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf || firstCachedTarget.Offset != rightShelfOffset || firstCachedTarget.RouterDepth != 1)
            {
                throw new InvalidDataException("First arena-cached walker did not resolve the expected two-level shelf target.");
            }

            firstCachedRead = session.GetAndResetReadTelemetry();
            if (firstCachedRead.ReadCallCount != 3 || firstCachedRead.BytesRead != RouterLayout.Size + profile.ShelfExtentSize + sizeof(uint))
            {
                throw new InvalidDataException($"First arena-cached walker should read root router, classify/read the child router, load the full child arena, and classify the shelf; actual reads={firstCachedRead.ReadCallCount}, bytes={firstCachedRead.BytesRead}.");
            }

            Scalar8Scalar8RouteTarget secondCachedTarget = session.WalkScalar8Scalar8RouteTarget(root.Offset, insertedKey, maxRouterHops: 8, Scalar8Scalar8RouteReadPolicy.PreferArenaCache);
            if (secondCachedTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf || secondCachedTarget.Offset != rightShelfOffset || secondCachedTarget.RouterDepth != 1)
            {
                throw new InvalidDataException("Second arena-cached walker did not resolve the expected two-level shelf target.");
            }

            secondCachedRead = session.GetAndResetReadTelemetry();
            if (secondCachedRead.ReadCallCount != 2 || secondCachedRead.BytesRead != RouterLayout.Size + sizeof(uint))
            {
                throw new InvalidDataException("Second arena-cached walker should reuse the cached child-router arena and read only root router plus shelf classifier magic.");
            }

            (nonEntryShelfOffset, _) = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(root.Offset, 0x7F, profile, itemCount: 512);
            RouterArenaAllocationResult nonEntryRouter = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 1, allocationClassId: 0, preferredArenaBaseOffset: childRouterOffset);
            if (nonEntryRouter.Kind != RouterArenaAllocationKind.LocalArena || nonEntryRouter.ArenaPageIndex != 1)
            {
                throw new InvalidDataException("Expected the non-entry test router to use arena page 1.");
            }

            nonEntryRouterOffset = nonEntryRouter.Router.Offset;
            _ = session.UpdateRouterRoute(nonEntryRouterOffset, 0x22, 0x22, 0x22, nonEntryShelfOffset);
            _ = session.UpdateRouterRoute(root.Offset, 0x7E, 0x7E, 0x7E, nonEntryRouterOffset);

            const ulong nonEntryKey = 0x7E22_0000_0000_0000UL;
            _ = session.GetAndResetReadTelemetry();
            session.ClearRouterArenaReadCacheForValidation();
            Scalar8Scalar8RouteTarget nonEntryCachedTarget = session.WalkScalar8Scalar8RouteTarget(root.Offset, nonEntryKey, maxRouterHops: 8, Scalar8Scalar8RouteReadPolicy.PreferArenaCache);
            if (nonEntryCachedTarget.Kind != Scalar8Scalar8RouteTargetKind.Shelf || nonEntryCachedTarget.Offset != nonEntryShelfOffset || nonEntryCachedTarget.RouterDepth != 1)
            {
                throw new InvalidDataException("Non-entry arena page cached walker did not resolve the expected shelf target.");
            }

            nonEntryCachedRead = session.GetAndResetReadTelemetry();
            if (nonEntryCachedRead.ReadCallCount != 3 || nonEntryCachedRead.BytesRead != RouterLayout.Size + profile.ShelfExtentSize + sizeof(uint))
            {
                throw new InvalidDataException($"Non-entry arena page first touch should use page metadata to load the whole router arena; actual reads={nonEntryCachedRead.ReadCallCount}, bytes={nonEntryCachedRead.BytesRead}.");
            }
        }

        Console.WriteLine("ss8-8 router arena read cache");
        Console.WriteLine($"childRouterOffset {childRouterOffset}");
        Console.WriteLine($"rightShelfOffset {rightShelfOffset}");
        Console.WriteLine($"nonEntryRouterOffset {nonEntryRouterOffset}");
        Console.WriteLine($"nonEntryShelfOffset {nonEntryShelfOffset}");
        PrintRead("ss8-8 router arena read uncached", uncachedRead);
        PrintRead("ss8-8 router arena read first cached", firstCachedRead);
        PrintRead("ss8-8 router arena read second cached", secondCachedRead);
        PrintRead("ss8-8 router arena non-entry cached", nonEntryCachedRead);
        Console.WriteLine($"ss8-8-router-arena-read-cache-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Measures explicit arena-aware router walking against the existing classified walker across route-locality scenarios.<br/>
    /// This keeps read-cache integration evidence separate from the default walker until the default policy is chosen.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the read-cache perf matrix completes; otherwise one.</returns>
    private static int RunScalar8Scalar8RouterArenaReadCachePerf(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-router-arena-read-cache-perf.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int iterations = GetIntOption(args, "--iterations", 1000);
        if (iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), iterations, "Router arena read-cache perf iterations must be positive.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(44), DataKernelTelemetryOptions.EnabledOptions);
        RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);

        RouterArenaReadCachePerfResult[] results =
        [
            MeasureRouterArenaReadCacheScenario("cold one-off uncached", session, setup, 1, RouterArenaReadCachePerfPattern.SameArena, useArenaCache: false),
            MeasureRouterArenaReadCacheScenario("cold one-off cached", session, setup, 1, RouterArenaReadCachePerfPattern.SameArena, useArenaCache: true),
            MeasureRouterArenaReadCacheScenario("repeated same-arena uncached", session, setup, iterations, RouterArenaReadCachePerfPattern.SameArena, useArenaCache: false),
            MeasureRouterArenaReadCacheScenario("repeated same-arena cached", session, setup, iterations, RouterArenaReadCachePerfPattern.SameArena, useArenaCache: true),
            MeasureRouterArenaReadCacheScenario("alternating arenas uncached", session, setup, iterations, RouterArenaReadCachePerfPattern.AlternatingArenas, useArenaCache: false),
            MeasureRouterArenaReadCacheScenario("alternating arenas cached", session, setup, iterations, RouterArenaReadCachePerfPattern.AlternatingArenas, useArenaCache: true),
            MeasureRouterArenaReadCacheScenario("mixed direct+arena uncached", session, setup, iterations, RouterArenaReadCachePerfPattern.MixedDirectAndArena, useArenaCache: false),
            MeasureRouterArenaReadCacheScenario("mixed direct+arena cached", session, setup, iterations, RouterArenaReadCachePerfPattern.MixedDirectAndArena, useArenaCache: true)
        ];

        Console.WriteLine("ss8-8 router arena read-cache perf");
        Console.WriteLine($"iterations {iterations}");
        PrintRouterArenaReadCachePerf(results);
        string reportPath = WriteRouterArenaReadCachePerfReport(artifactDirectory, iterations, results);
        Console.WriteLine($"ss8-8 router arena read-cache perf report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Creates one direct shelf route plus two transformed-shelf router arenas for read-cache policy measurement.<br/>
    /// The setup intentionally mixes a route that cannot benefit from router arena caching with two routes that can.<br/>
    /// </summary>
    /// <param name="session">The active file session.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The root offset and encoded keys used by the perf scenarios.</returns>
    private static RouterArenaReadCachePerfSetup CreateScalar8Scalar8RouterArenaReadCachePerfSetup(
        LibraDexFileSession session,
        Scalar8Scalar8Profile profile)
    {
        CreateTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8arcpf", 0));
        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(root.Offset, 0x7F, profile, itemCount: 512);

        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
        const ulong firstArenaKey = 0x0080_0000_0000_0000UL + 10_000UL;
        _ = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x00, 0x80, profile, firstArenaKey, firstArenaKey);

        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x01]);
        const ulong secondArenaKey = 0x0180_0000_0000_0000UL + 10_000UL;
        _ = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x01, 0x80, profile, secondArenaKey, secondArenaKey);

        const ulong directKey = 0x7F00_0000_0000_0080UL;
        _ = session.GetAndResetReadTelemetry();
        return new RouterArenaReadCachePerfSetup(root.Offset, firstArenaKey, secondArenaKey, directKey);
    }

    /// <summary>
    /// Measures one router arena read-cache scenario over a deterministic key pattern.<br/>
    /// The checksum prevents the route walk loop from becoming observationally irrelevant while keeping output compact.<br/>
    /// </summary>
    /// <param name="name">The scenario name.</param>
    /// <param name="session">The active file session.</param>
    /// <param name="setup">The route setup keys and root offset.</param>
    /// <param name="iterations">The number of route walks to perform.</param>
    /// <param name="pattern">The route key pattern to use.</param>
    /// <param name="useArenaCache">Whether to call the explicit arena-aware walker.</param>
    /// <returns>The measured perf scenario result.</returns>
    private static RouterArenaReadCachePerfResult MeasureRouterArenaReadCacheScenario(
        string name,
        LibraDexFileSession session,
        RouterArenaReadCachePerfSetup setup,
        int iterations,
        RouterArenaReadCachePerfPattern pattern,
        bool useArenaCache)
    {
        session.ClearRouterArenaReadCacheForValidation();
        _ = session.GetAndResetReadTelemetry();
        long checksum = 0;
        Stopwatch stopwatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            ulong key = pattern switch
            {
                RouterArenaReadCachePerfPattern.SameArena => setup.FirstArenaKey,
                RouterArenaReadCachePerfPattern.AlternatingArenas => (i & 1) == 0 ? setup.FirstArenaKey : setup.SecondArenaKey,
                RouterArenaReadCachePerfPattern.MixedDirectAndArena => (i & 1) == 0 ? setup.FirstArenaKey : setup.DirectKey,
                _ => throw new InvalidOperationException($"Unsupported router arena read-cache perf pattern {pattern}.")
            };

            Scalar8Scalar8RouteReadPolicy readPolicy = useArenaCache
                ? Scalar8Scalar8RouteReadPolicy.PreferArenaCache
                : Scalar8Scalar8RouteReadPolicy.Uncached;
            Scalar8Scalar8RouteTarget target = session.WalkScalar8Scalar8RouteTarget(setup.RootRouterOffset, key, maxRouterHops: 8, readPolicy);
            checksum ^= target.Offset + target.RouterDepth + (int)target.Kind;
        }

        stopwatch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        return new RouterArenaReadCachePerfResult(name, iterations, stopwatch.Elapsed, telemetry.ReadCallCount, telemetry.BackingReadCallCount, telemetry.BytesRead, checksum);
    }

    /// <summary>
    /// Prints the router arena read-cache perf matrix to the console.<br/>
    /// </summary>
    /// <param name="results">The measured scenario results.</param>
    private static void PrintRouterArenaReadCachePerf(ReadOnlySpan<RouterArenaReadCachePerfResult> results)
    {
        Console.WriteLine("| scenario | iterations | elapsed ms | ns/route | reads | backing reads | bytes | bytes/route | checksum |");
        Console.WriteLine("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            RouterArenaReadCachePerfResult result = results[i];
            double nsPerRoute = result.Elapsed.TotalSeconds * 1_000_000_000d / result.Iterations;
            double bytesPerRoute = result.BytesRead / (double)result.Iterations;
            Console.WriteLine($"| {result.Name} | {result.Iterations} | {result.Elapsed.TotalMilliseconds:N3} | {nsPerRoute:N2} | {result.ReadCallCount} | {result.BackingReadCallCount} | {result.BytesRead} | {bytesPerRoute:N2} | {result.Checksum} |");
        }
    }

    /// <summary>
    /// Writes the current router arena read-cache perf matrix and archives any previous current report by timestamp.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The report directory.</param>
    /// <param name="iterations">The configured iteration count.</param>
    /// <param name="results">The measured scenario results.</param>
    /// <returns>The current report path.</returns>
    private static string WriteRouterArenaReadCachePerfReport(
        string artifactDirectory,
        int iterations,
        ReadOnlySpan<RouterArenaReadCachePerfResult> results)
    {
        string currentPath = Path.Combine(artifactDirectory, "ss8-8-router-arena-read-cache-perf-current.md");
        ArchiveCurrentReport(currentPath, "ss8-8-router-arena-read-cache-perf");
        string timestamp = DateTimeOffset.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        string timestampPath = Path.Combine(artifactDirectory, $"ss8-8-router-arena-read-cache-perf-{timestamp}.md");

        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Router Arena Read-Cache Perf - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine($"- Iterations: `{iterations}`");
        builder.AppendLine("- Existing walker is the baseline route classifier.");
        builder.AppendLine("- Cached walker is the explicit arena-aware route classifier.");
        builder.AppendLine();
        builder.AppendLine("| scenario | iterations | elapsed ms | ns/route | reads | backing reads | bytes | bytes/route | checksum |");
        builder.AppendLine("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            RouterArenaReadCachePerfResult result = results[i];
            double nsPerRoute = result.Elapsed.TotalSeconds * 1_000_000_000d / result.Iterations;
            double bytesPerRoute = result.BytesRead / (double)result.Iterations;
            builder.AppendLine($"| {result.Name} | {result.Iterations} | {result.Elapsed.TotalMilliseconds:N3} | {nsPerRoute:N2} | {result.ReadCallCount} | {result.BackingReadCallCount} | {result.BytesRead} | {bytesPerRoute:N2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- Cold cached reads intentionally spend one full 32 KiB arena read to seed the cache.");
        builder.AppendLine("- Same-arena repeated reads show whether that first-touch cost amortizes.");
        builder.AppendLine("- Alternating arenas shows the cost of a single-entry cache under poor locality.");
        builder.AppendLine("- Mixed direct+arena routes show whether direct shelf routes disturb arena locality.");

        File.WriteAllText(currentPath, builder.ToString());
        File.WriteAllText(timestampPath, builder.ToString());
        return currentPath;
    }

    /// <summary>
    /// Validates the first locality-heavy batched route-walk operation with explicit route-read policy selection.<br/>
    /// The scenario routes many keys through the same transformed router arena, comparing uncached and arena-aware read shapes while requiring identical targets.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when batched route policy validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RouteBatchPolicySanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-route-batch-policy-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        const int batchCount = 16;
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        DataKernelReadTelemetry uncachedRead;
        DataKernelReadTelemetry cachedRead;
        long rightShelfOffset;
        long uncachedChecksum;
        long cachedChecksum;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(45), DataKernelTelemetryOptions.EnabledOptions))
        {
            RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);
            rightShelfOffset = session.WalkScalar8Scalar8RouteTarget(setup.RootRouterOffset, setup.FirstArenaKey, maxRouterHops: 8).Offset;

            ulong[] keys = new ulong[batchCount];
            for (int i = 0; i < keys.Length; i++)
            {
                keys[i] = setup.FirstArenaKey + (ulong)i;
            }

            Scalar8Scalar8RouteTarget[] uncachedTargets = new Scalar8Scalar8RouteTarget[batchCount];
            Scalar8Scalar8RouteTarget[] cachedTargets = new Scalar8Scalar8RouteTarget[batchCount];

            _ = session.GetAndResetReadTelemetry();
            session.ClearRouterArenaReadCacheForValidation();
            session.WalkScalar8Scalar8RouteTargets(setup.RootRouterOffset, keys, maxRouterHops: 8, Scalar8Scalar8RouteReadPolicy.Uncached, uncachedTargets);
            uncachedRead = session.GetAndResetReadTelemetry();

            session.ClearRouterArenaReadCacheForValidation();
            session.WalkScalar8Scalar8RouteTargets(setup.RootRouterOffset, keys, maxRouterHops: 8, Scalar8Scalar8RouteReadPolicy.PreferArenaCache, cachedTargets);
            cachedRead = session.GetAndResetReadTelemetry();

            uncachedChecksum = CheckScalar8Scalar8RouteTargets(uncachedTargets, rightShelfOffset);
            cachedChecksum = CheckScalar8Scalar8RouteTargets(cachedTargets, rightShelfOffset);
            if (uncachedChecksum != cachedChecksum)
            {
                throw new InvalidDataException("Batched route policies resolved different target checksums.");
            }

            long expectedUncachedReads = 2L + (batchCount * 2L);
            long expectedUncachedBytes = (RouterLayout.Size * 2L) + (batchCount * (sizeof(uint) * 2L));
            long expectedCachedReads = 3 + ((batchCount - 1L) * 2L);
            long expectedCachedBytes = RouterLayout.Size + profile.ShelfExtentSize + sizeof(uint) + ((batchCount - 1L) * (RouterLayout.Size + sizeof(uint)));
            if (uncachedRead.ReadCallCount != expectedUncachedReads || uncachedRead.BytesRead != expectedUncachedBytes)
            {
                throw new InvalidDataException($"Uncached batched route walk did not preserve the expected read shape. expectedReads={expectedUncachedReads} actualReads={uncachedRead.ReadCallCount} expectedBytes={expectedUncachedBytes} actualBytes={uncachedRead.BytesRead}.");
            }

            if (cachedRead.ReadCallCount != expectedCachedReads || cachedRead.BytesRead != expectedCachedBytes)
            {
                throw new InvalidDataException($"Arena-aware batched route walk did not preserve the expected read shape. expectedReads={expectedCachedReads} actualReads={cachedRead.ReadCallCount} expectedBytes={expectedCachedBytes} actualBytes={cachedRead.BytesRead}.");
            }
        }

        Console.WriteLine("ss8-8 route batch policy");
        Console.WriteLine($"batchCount {batchCount}");
        Console.WriteLine($"rightShelfOffset {rightShelfOffset}");
        Console.WriteLine($"uncachedChecksum {uncachedChecksum}");
        Console.WriteLine($"cachedChecksum {cachedChecksum}");
        PrintRead("ss8-8 route batch uncached", uncachedRead);
        PrintRead("ss8-8 route batch cached", cachedRead);
        Console.WriteLine($"ss8-8-route-batch-policy-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates that each batched route target resolved to the expected shelf and returns a compact checksum.<br/>
    /// </summary>
    /// <param name="targets">The route targets produced by one batch route policy.</param>
    /// <param name="expectedShelfOffset">The expected shelf offset for every target.</param>
    /// <returns>A checksum over the target offsets, depths, and kinds.</returns>
    private static long CheckScalar8Scalar8RouteTargets(
        ReadOnlySpan<Scalar8Scalar8RouteTarget> targets,
        long expectedShelfOffset)
    {
        long checksum = 0;
        for (int i = 0; i < targets.Length; i++)
        {
            Scalar8Scalar8RouteTarget target = targets[i];
            if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf || target.Offset != expectedShelfOffset || target.RouterDepth != 1)
            {
                throw new InvalidDataException($"Unexpected batched route target at index {i}: {target.Kind} offset {target.Offset} depth {target.RouterDepth}.");
            }

            checksum ^= target.Offset + target.RouterDepth + (int)target.Kind + i;
        }

        return checksum;
    }

    /// <summary>
    /// Validates the first routed `SS8-8` batched point lookup over encoded keys.<br/>
    /// The command compares uncached routing with arena-aware routing, then requires both policies to return the same identity results from the same shelf data.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when batched lookup validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8BatchLookupSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-batch-lookup-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        const int batchCount = 16;
        const ulong rightPrefixBase = 0x0080_0000_0000_0000UL;
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        DataKernelReadTelemetry uncachedRead;
        DataKernelReadTelemetry cachedRead;
        long uncachedChecksum;
        long cachedChecksum;
        long rightShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(46), DataKernelTelemetryOptions.EnabledOptions))
        {
            RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);
            rightShelfOffset = session.WalkScalar8Scalar8RouteTarget(setup.RootRouterOffset, rightPrefixBase, maxRouterHops: 8).Offset;

            ulong[] keys = new ulong[batchCount];
            for (int i = 0; i < keys.Length; i++)
            {
                keys[i] = rightPrefixBase + (ulong)i;
            }

            ulong[] uncachedIdentities = new ulong[batchCount];
            ulong[] cachedIdentities = new ulong[batchCount];
            byte[] uncachedFound = new byte[batchCount];
            byte[] cachedFound = new byte[batchCount];
            Scalar8Scalar8RouteTarget[] routeTargets = new Scalar8Scalar8RouteTarget[batchCount];
            byte[] shelfBuffer = new byte[profile.ShelfExtentSize];

            _ = session.GetAndResetReadTelemetry();
            session.ClearRouterArenaReadCacheForValidation();
            session.LookupScalar8Scalar8Identities(
                setup.RootRouterOffset,
                profile,
                keys,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.Uncached,
                uncachedIdentities,
                uncachedFound,
                routeTargets,
                shelfBuffer);
            uncachedRead = session.GetAndResetReadTelemetry();

            Array.Clear(routeTargets);
            Array.Clear(shelfBuffer);
            session.ClearRouterArenaReadCacheForValidation();
            session.LookupScalar8Scalar8Identities(
                setup.RootRouterOffset,
                profile,
                keys,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
                cachedIdentities,
                cachedFound,
                routeTargets,
                shelfBuffer);
            cachedRead = session.GetAndResetReadTelemetry();

            uncachedChecksum = CheckScalar8Scalar8BatchLookup(keys, uncachedIdentities, uncachedFound);
            cachedChecksum = CheckScalar8Scalar8BatchLookup(keys, cachedIdentities, cachedFound);
            if (uncachedChecksum != cachedChecksum)
            {
                throw new InvalidDataException("Batched lookup policies returned different checksums.");
            }

            long expectedUncachedReads = 3L + (batchCount * 2L);
            long expectedUncachedBytes = (RouterLayout.Size * 2L) + (batchCount * (sizeof(uint) * 2L)) + profile.ShelfExtentSize;
            long expectedCachedReads = 4 + ((batchCount - 1L) * 2L);
            long expectedCachedBytes = RouterLayout.Size + profile.ShelfExtentSize + sizeof(uint) + ((batchCount - 1L) * (RouterLayout.Size + sizeof(uint))) + profile.ShelfExtentSize;
            if (uncachedRead.ReadCallCount != expectedUncachedReads || uncachedRead.BytesRead != expectedUncachedBytes)
            {
                throw new InvalidDataException($"Uncached batched lookup did not preserve the expected read shape. expectedReads={expectedUncachedReads} actualReads={uncachedRead.ReadCallCount} expectedBytes={expectedUncachedBytes} actualBytes={uncachedRead.BytesRead}.");
            }

            if (cachedRead.ReadCallCount != expectedCachedReads || cachedRead.BytesRead != expectedCachedBytes)
            {
                throw new InvalidDataException($"Arena-aware batched lookup did not preserve the expected read shape. expectedReads={expectedCachedReads} actualReads={cachedRead.ReadCallCount} expectedBytes={expectedCachedBytes} actualBytes={cachedRead.BytesRead}.");
            }
        }

        Console.WriteLine("ss8-8 batch lookup");
        Console.WriteLine($"batchCount {batchCount}");
        Console.WriteLine($"rightShelfOffset {rightShelfOffset}");
        Console.WriteLine($"uncachedChecksum {uncachedChecksum}");
        Console.WriteLine($"cachedChecksum {cachedChecksum}");
        PrintRead("ss8-8 batch lookup uncached", uncachedRead);
        PrintRead("ss8-8 batch lookup cached", cachedRead);
        Console.WriteLine($"ss8-8-batch-lookup-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates batched point-lookup results and returns a compact checksum.<br/>
    /// The current vector uses keys whose first matching identity equals the encoded key, making misses or wrong shelf reads immediately visible.<br/>
    /// </summary>
    /// <param name="keys">The encoded keys that were looked up.</param>
    /// <param name="identities">The encoded identities returned by the lookup.</param>
    /// <param name="foundFlags">The found flags returned by the lookup.</param>
    /// <returns>A checksum over the found identities.</returns>
    private static long CheckScalar8Scalar8BatchLookup(
        ReadOnlySpan<ulong> keys,
        ReadOnlySpan<ulong> identities,
        ReadOnlySpan<byte> foundFlags)
    {
        long checksum = 0;
        for (int i = 0; i < keys.Length; i++)
        {
            if (foundFlags[i] != 1 || identities[i] != keys[i])
            {
                throw new InvalidDataException($"Unexpected batched lookup result at index {i}: found={foundFlags[i]} identity={identities[i]} key={keys[i]}.");
            }

            checksum += unchecked((long)((identities[i] >> 32) ^ identities[i] ^ (ulong)(i + 1)));
        }

        return checksum;
    }

    /// <summary>
    /// Measures the first routed `SS8-8` batched point lookup operation with uncached and arena-aware routing policies.<br/>
    /// Each iteration performs one batch lookup over the same right-side transformed shelf so the run measures route-to-shelf bridging plus shelf lower-bound lookup.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the perf report is written.</returns>
    private static int RunScalar8Scalar8BatchLookupPerf(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-batch-lookup-perf.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int iterations = GetIntOption(args, "--iterations", 1000);
        int batchCount = GetIntOption(args, "--batch-count", 16);
        if (iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), iterations, "Batch lookup perf iterations must be positive.");
        }

        if (batchCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), batchCount, "Batch lookup perf batch count must be positive.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(47), DataKernelTelemetryOptions.EnabledOptions);
        RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);
        ulong[] keys = CreateScalar8Scalar8RightShelfLookupKeys(batchCount);
        ulong[] identities = new ulong[batchCount];
        byte[] foundFlags = new byte[batchCount];
        Scalar8Scalar8RouteTarget[] routeTargets = new Scalar8Scalar8RouteTarget[batchCount];
        byte[] shelfBuffer = new byte[profile.ShelfExtentSize];

        Scalar8Scalar8BatchLookupPerfResult uncached = MeasureScalar8Scalar8BatchLookupScenario(
            "same-shelf uncached",
            session,
            setup.RootRouterOffset,
            profile,
            keys,
            iterations,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            identities,
            foundFlags,
            routeTargets,
            shelfBuffer);

        Scalar8Scalar8BatchLookupPerfResult cached = MeasureScalar8Scalar8BatchLookupScenario(
            "same-shelf cached",
            session,
            setup.RootRouterOffset,
            profile,
            keys,
            iterations,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            identities,
            foundFlags,
            routeTargets,
            shelfBuffer);

        Scalar8Scalar8BatchLookupPerfResult[] results = [uncached, cached];
        Console.WriteLine("ss8-8 batch lookup perf");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"batchCount {batchCount}");
        PrintScalar8Scalar8BatchLookupPerf(results);
        string reportPath = WriteScalar8Scalar8BatchLookupPerfReport(artifactDirectory, iterations, batchCount, results);
        Console.WriteLine($"ss8-8 batch lookup perf report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Creates deterministic encoded lookup keys that are known to live in the right shelf after the router-arena setup transform.<br/>
    /// The selected keys keep this first benchmark focused on same-shelf locality rather than miss behavior or cross-shelf reads.<br/>
    /// </summary>
    /// <param name="batchCount">The number of encoded keys to create.</param>
    /// <returns>The encoded lookup keys.</returns>
    private static ulong[] CreateScalar8Scalar8RightShelfLookupKeys(int batchCount)
    {
        const ulong rightPrefixBase = 0x0080_0000_0000_0000UL;
        ulong[] keys = new ulong[batchCount];
        for (int i = 0; i < keys.Length; i++)
        {
            keys[i] = rightPrefixBase + (ulong)i;
        }

        return keys;
    }

    /// <summary>
    /// Measures one routed batched point lookup scenario.<br/>
    /// The scratch arrays are reused across iterations to keep the measured operation close to the allocation-free library path.<br/>
    /// </summary>
    /// <param name="name">The scenario name.</param>
    /// <param name="session">The active file session.</param>
    /// <param name="rootRouterOffset">The root router offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <param name="keys">The encoded keys to look up on every iteration.</param>
    /// <param name="iterations">The number of batch lookups to perform.</param>
    /// <param name="readPolicy">The route-read policy to apply.</param>
    /// <param name="identities">The reusable identity result buffer.</param>
    /// <param name="foundFlags">The reusable found-flag result buffer.</param>
    /// <param name="routeTargets">The reusable route-target scratch buffer.</param>
    /// <param name="shelfBuffer">The reusable shelf read buffer.</param>
    /// <param name="validationKind">The compact result validator selector: `0` same-shelf, `1` same-parent cross-shelf, `2` generalized traversal.</param>
    /// <returns>The measured perf result.</returns>
    private static Scalar8Scalar8BatchLookupPerfResult MeasureScalar8Scalar8BatchLookupScenario(
        string name,
        LibraDexFileSession session,
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        ReadOnlySpan<ulong> keys,
        int iterations,
        Scalar8Scalar8RouteReadPolicy readPolicy,
        Span<ulong> identities,
        Span<byte> foundFlags,
        Span<Scalar8Scalar8RouteTarget> routeTargets,
        Span<byte> shelfBuffer)
    {
        session.ClearRouterArenaReadCacheForValidation();
        _ = session.GetAndResetReadTelemetry();
        long checksum = 0;
        Stopwatch stopwatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            session.LookupScalar8Scalar8Identities(
                rootRouterOffset,
                profile,
                keys,
                maxRouterHops: 8,
                readPolicy,
                identities,
                foundFlags,
                routeTargets,
                shelfBuffer);
            checksum += CheckScalar8Scalar8BatchLookup(keys, identities, foundFlags);
        }

        stopwatch.Stop();
        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        return new Scalar8Scalar8BatchLookupPerfResult(name, iterations, keys.Length, stopwatch.Elapsed, readTelemetry.ReadCallCount, readTelemetry.BackingReadCallCount, readTelemetry.BytesRead, checksum);
    }

    /// <summary>
    /// Prints the `SS8-8` batched point lookup perf table to the console.<br/>
    /// </summary>
    /// <param name="results">The measured lookup results.</param>
    private static void PrintScalar8Scalar8BatchLookupPerf(ReadOnlySpan<Scalar8Scalar8BatchLookupPerfResult> results)
    {
        Console.WriteLine("| scenario | iterations | batch | elapsed ms | ns/key | reads | backing reads | bytes | bytes/key | checksum |");
        Console.WriteLine("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8BatchLookupPerfResult result = results[i];
            double keyCount = (double)result.Iterations * result.BatchCount;
            double nsPerKey = result.Elapsed.TotalSeconds * 1_000_000_000d / keyCount;
            double bytesPerKey = result.BytesRead / keyCount;
            Console.WriteLine($"| {result.Name} | {result.Iterations} | {result.BatchCount} | {result.Elapsed.TotalMilliseconds:N3} | {nsPerKey:N2} | {result.ReadCallCount} | {result.BackingReadCallCount} | {result.BytesRead} | {bytesPerKey:N2} | {result.Checksum} |");
        }
    }

    /// <summary>
    /// Writes the current `SS8-8` batched point lookup perf report and archives the previous current report by timestamp.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The report directory.</param>
    /// <param name="iterations">The configured iteration count.</param>
    /// <param name="batchCount">The configured lookup batch size.</param>
    /// <param name="results">The measured lookup results.</param>
    /// <returns>The current report path.</returns>
    private static string WriteScalar8Scalar8BatchLookupPerfReport(
        string artifactDirectory,
        int iterations,
        int batchCount,
        ReadOnlySpan<Scalar8Scalar8BatchLookupPerfResult> results)
    {
        string currentPath = Path.Combine(artifactDirectory, "ss8-8-batch-lookup-perf-current.md");
        ArchiveCurrentReport(currentPath, "ss8-8-batch-lookup-perf");
        string timestamp = DateTimeOffset.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        string timestampPath = Path.Combine(artifactDirectory, $"ss8-8-batch-lookup-perf-{timestamp}.md");

        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Batch Lookup Perf - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine($"- Iterations: `{iterations}`");
        builder.AppendLine($"- Batch count: `{batchCount}`");
        builder.AppendLine("- Scenario: same transformed-shelf right-side keys, route then read one shelf extent per batch lookup.");
        builder.AppendLine();
        builder.AppendLine("| scenario | iterations | batch | elapsed ms | ns/key | reads | backing reads | bytes | bytes/key | checksum |");
        builder.AppendLine("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8BatchLookupPerfResult result = results[i];
            double keyCount = (double)result.Iterations * result.BatchCount;
            double nsPerKey = result.Elapsed.TotalSeconds * 1_000_000_000d / keyCount;
            double bytesPerKey = result.BytesRead / keyCount;
            builder.AppendLine($"| {result.Name} | {result.Iterations} | {result.BatchCount} | {result.Elapsed.TotalMilliseconds:N3} | {nsPerKey:N2} | {result.ReadCallCount} | {result.BackingReadCallCount} | {result.BytesRead} | {bytesPerKey:N2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- This measures the first route-to-shelf read bridge, not range scoop yet.");
        builder.AppendLine("- One shelf extent is read per batch lookup in both scenarios.");
        builder.AppendLine("- Arena-aware routing should reduce router reads and bytes when batch keys share the same transformed router arena.");

        File.WriteAllText(currentPath, builder.ToString());
        File.WriteAllText(timestampPath, builder.ToString());
        return currentPath;
    }

    /// <summary>
    /// Validates the first routed `SS8-8` range/scoop operation over one shelf.<br/>
    /// The command compares uncached routing with arena-aware routing and requires both policies to return the same inclusive key-range identity span.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when routed range scoop validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RangeScoopSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-range-scoop-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        const int rangeStart = 32;
        const int rangeLength = 64;
        const ulong rightPrefixBase = 0x0080_0000_0000_0000UL;
        ulong lowerKey = rightPrefixBase + (ulong)rangeStart;
        ulong upperKey = lowerKey + (ulong)(rangeLength - 1);
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        DataKernelReadTelemetry uncachedRead;
        DataKernelReadTelemetry cachedRead;
        DataKernelReadTelemetry crossUncachedRead;
        DataKernelReadTelemetry crossCachedRead;
        DataKernelReadTelemetry traversalUncachedRead;
        DataKernelReadTelemetry traversalCachedRead;
        long uncachedChecksum;
        long cachedChecksum;
        long crossUncachedChecksum;
        long crossCachedChecksum;
        long traversalUncachedChecksum;
        long traversalCachedChecksum;
        int uncachedCount;
        int cachedCount;
        int crossUncachedCount;
        int crossCachedCount;
        int traversalUncachedCount;
        int traversalCachedCount;
        long rightShelfOffset;
        long traversalRightShelfOffset;
        long traversalDirectShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(48), DataKernelTelemetryOptions.EnabledOptions))
        {
            RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);
            rightShelfOffset = session.WalkScalar8Scalar8RouteTarget(setup.RootRouterOffset, lowerKey, maxRouterHops: 8).Offset;

            ulong[] uncachedIdentities = new ulong[rangeLength];
            ulong[] cachedIdentities = new ulong[rangeLength];
            byte[] shelfBuffer = new byte[profile.ShelfExtentSize];

            _ = session.GetAndResetReadTelemetry();
            session.ClearRouterArenaReadCacheForValidation();
            uncachedCount = session.ScoopScalar8Scalar8IdentityRange(
                setup.RootRouterOffset,
                profile,
                lowerKey,
                upperKey,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.Uncached,
                uncachedIdentities,
                shelfBuffer);
            uncachedRead = session.GetAndResetReadTelemetry();

            Array.Clear(shelfBuffer);
            session.ClearRouterArenaReadCacheForValidation();
            cachedCount = session.ScoopScalar8Scalar8IdentityRange(
                setup.RootRouterOffset,
                profile,
                lowerKey,
                upperKey,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
                cachedIdentities,
                shelfBuffer);
            cachedRead = session.GetAndResetReadTelemetry();

            uncachedChecksum = CheckScalar8Scalar8RangeScoop(lowerKey, uncachedIdentities, uncachedCount, rangeLength);
            cachedChecksum = CheckScalar8Scalar8RangeScoop(lowerKey, cachedIdentities, cachedCount, rangeLength);
            if (uncachedChecksum != cachedChecksum)
            {
                throw new InvalidDataException("Routed range scoop policies returned different checksums.");
            }

            long expectedUncachedReads = 5;
            long expectedUncachedBytes = (RouterLayout.Size * 2L) + (2L * sizeof(uint)) + profile.ShelfExtentSize;
            long expectedCachedReads = 5;
            long expectedCachedBytes = RouterLayout.Size + profile.ShelfExtentSize + RouterLayout.Size + sizeof(uint) + profile.ShelfExtentSize;
            if (uncachedRead.ReadCallCount != expectedUncachedReads || uncachedRead.BytesRead != expectedUncachedBytes)
            {
                throw new InvalidDataException($"Uncached routed range scoop did not preserve the expected read shape. expectedReads={expectedUncachedReads} actualReads={uncachedRead.ReadCallCount} expectedBytes={expectedUncachedBytes} actualBytes={uncachedRead.BytesRead}.");
            }

            if (cachedRead.ReadCallCount != expectedCachedReads || cachedRead.BytesRead != expectedCachedBytes)
            {
                throw new InvalidDataException($"Arena-aware routed range scoop did not preserve the expected read shape. expectedReads={expectedCachedReads} actualReads={cachedRead.ReadCallCount} expectedBytes={expectedCachedBytes} actualBytes={cachedRead.BytesRead}.");
            }

            const ulong crossLowerKey = 900UL;
            const ulong crossUpperKey = rightPrefixBase + 31UL;
            const int crossExpectedCount = 41;
            ulong[] crossUncachedIdentities = new ulong[crossExpectedCount];
            ulong[] crossCachedIdentities = new ulong[crossExpectedCount];

            Array.Clear(shelfBuffer);
            session.ClearRouterArenaReadCacheForValidation();
            crossUncachedCount = session.ScoopScalar8Scalar8IdentityRange(
                setup.RootRouterOffset,
                profile,
                crossLowerKey,
                crossUpperKey,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.Uncached,
                crossUncachedIdentities,
                shelfBuffer);
            crossUncachedRead = session.GetAndResetReadTelemetry();

            Array.Clear(shelfBuffer);
            session.ClearRouterArenaReadCacheForValidation();
            crossCachedCount = session.ScoopScalar8Scalar8IdentityRange(
                setup.RootRouterOffset,
                profile,
                crossLowerKey,
                crossUpperKey,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
                crossCachedIdentities,
                shelfBuffer);
            crossCachedRead = session.GetAndResetReadTelemetry();

            crossUncachedChecksum = CheckScalar8Scalar8CrossShelfRangeScoop(crossUncachedIdentities, crossUncachedCount);
            crossCachedChecksum = CheckScalar8Scalar8CrossShelfRangeScoop(crossCachedIdentities, crossCachedCount);
            if (crossUncachedChecksum != crossCachedChecksum)
            {
                throw new InvalidDataException("Cross-shelf routed range scoop policies returned different checksums.");
            }

            long expectedCrossUncachedReads = 8;
            long expectedCrossUncachedBytes = (3L * RouterLayout.Size) + (3L * sizeof(uint)) + (2L * profile.ShelfExtentSize);
            long expectedCrossCachedReads = 7;
            long expectedCrossCachedBytes = RouterLayout.Size + profile.ShelfExtentSize + sizeof(uint) + RouterLayout.Size + sizeof(uint) + (2L * profile.ShelfExtentSize);
            if (crossUncachedRead.ReadCallCount != expectedCrossUncachedReads || crossUncachedRead.BytesRead != expectedCrossUncachedBytes)
            {
                throw new InvalidDataException($"Uncached cross-shelf routed range scoop did not preserve the expected read shape. expectedReads={expectedCrossUncachedReads} actualReads={crossUncachedRead.ReadCallCount} expectedBytes={expectedCrossUncachedBytes} actualBytes={crossUncachedRead.BytesRead}.");
            }

            if (crossCachedRead.ReadCallCount != expectedCrossCachedReads || crossCachedRead.BytesRead != expectedCrossCachedBytes)
            {
                throw new InvalidDataException($"Arena-aware cross-shelf routed range scoop did not preserve the expected read shape. expectedReads={expectedCrossCachedReads} actualReads={crossCachedRead.ReadCallCount} expectedBytes={expectedCrossCachedBytes} actualBytes={crossCachedRead.BytesRead}.");
            }

            (RouterSnapshot traversalRoot, _) = session.CreateRootRouterIndex(CreateHarnessSlot(1, "ss8rngtr", 0));
            CreateTransformSplitVectors(profile, out ulong[] traversalKeys, out ulong[] traversalIdentities, out int _, out int _);
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(traversalRoot.Offset, profile, traversalKeys, traversalIdentities, [0x00]);
            const ulong traversalSplitKey = rightPrefixBase + 10_000UL;
            _ = session.SplitRoutedScalar8Scalar8ByShelfTransform(traversalRoot.Offset, 0x00, 0x80, profile, traversalSplitKey, traversalSplitKey);
            traversalRightShelfOffset = session.WalkScalar8Scalar8RouteTarget(traversalRoot.Offset, rightPrefixBase + 900UL, maxRouterHops: 8).Offset;

            ulong[] directKeys = new ulong[32];
            ulong[] directIdentities = new ulong[directKeys.Length];
            const ulong directPrefixBase = 0x0100_0000_0000_0000UL;
            for (int i = 0; i < directKeys.Length; i++)
            {
                directKeys[i] = directPrefixBase + (ulong)i;
                directIdentities[i] = directKeys[i];
            }

            (traversalDirectShelfOffset, _) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(traversalRoot.Offset, profile, directKeys, directIdentities, [0x01]);
            const ulong traversalLowerKey = rightPrefixBase + 900UL;
            const ulong traversalUpperKey = directPrefixBase + 31UL;
            const int traversalExpectedCount = 42;
            ulong[] traversalUncachedIdentities = new ulong[traversalExpectedCount];
            ulong[] traversalCachedIdentities = new ulong[traversalExpectedCount];

            Array.Clear(shelfBuffer);
            session.ClearRouterArenaReadCacheForValidation();
            _ = session.GetAndResetReadTelemetry();
            traversalUncachedCount = session.ScoopScalar8Scalar8IdentityRange(
                traversalRoot.Offset,
                profile,
                traversalLowerKey,
                traversalUpperKey,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.Uncached,
                traversalUncachedIdentities,
                shelfBuffer);
            traversalUncachedRead = session.GetAndResetReadTelemetry();

            Array.Clear(shelfBuffer);
            session.ClearRouterArenaReadCacheForValidation();
            traversalCachedCount = session.ScoopScalar8Scalar8IdentityRange(
                traversalRoot.Offset,
                profile,
                traversalLowerKey,
                traversalUpperKey,
                maxRouterHops: 8,
                Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
                traversalCachedIdentities,
                shelfBuffer);
            traversalCachedRead = session.GetAndResetReadTelemetry();

            traversalUncachedChecksum = CheckScalar8Scalar8TraversalRangeScoop(traversalUncachedIdentities, traversalUncachedCount);
            traversalCachedChecksum = CheckScalar8Scalar8TraversalRangeScoop(traversalCachedIdentities, traversalCachedCount);
            if (traversalUncachedChecksum != traversalCachedChecksum)
            {
                throw new InvalidDataException("Generalized routed range traversal policies returned different checksums.");
            }

            long expectedTraversalUncachedReads = 7;
            long expectedTraversalUncachedBytes = 73740;
            long expectedTraversalCachedReads = 6;
            long expectedTraversalCachedBytes = 102408;
            if (traversalUncachedRead.ReadCallCount != expectedTraversalUncachedReads || traversalUncachedRead.BytesRead != expectedTraversalUncachedBytes)
            {
                throw new InvalidDataException($"Uncached generalized routed range traversal did not preserve the expected read shape. expectedReads={expectedTraversalUncachedReads} actualReads={traversalUncachedRead.ReadCallCount} expectedBytes={expectedTraversalUncachedBytes} actualBytes={traversalUncachedRead.BytesRead}.");
            }

            if (traversalCachedRead.ReadCallCount != expectedTraversalCachedReads || traversalCachedRead.BytesRead != expectedTraversalCachedBytes)
            {
                throw new InvalidDataException($"Arena-aware generalized routed range traversal did not preserve the expected read shape. expectedReads={expectedTraversalCachedReads} actualReads={traversalCachedRead.ReadCallCount} expectedBytes={expectedTraversalCachedBytes} actualBytes={traversalCachedRead.BytesRead}.");
            }
        }

        Console.WriteLine("ss8-8 range scoop");
        Console.WriteLine($"rangeStart {rangeStart}");
        Console.WriteLine($"rangeLength {rangeLength}");
        Console.WriteLine($"rightShelfOffset {rightShelfOffset}");
        Console.WriteLine($"uncachedCount {uncachedCount}");
        Console.WriteLine($"cachedCount {cachedCount}");
        Console.WriteLine($"uncachedChecksum {uncachedChecksum}");
        Console.WriteLine($"cachedChecksum {cachedChecksum}");
        Console.WriteLine($"crossUncachedCount {crossUncachedCount}");
        Console.WriteLine($"crossCachedCount {crossCachedCount}");
        Console.WriteLine($"crossUncachedChecksum {crossUncachedChecksum}");
        Console.WriteLine($"crossCachedChecksum {crossCachedChecksum}");
        Console.WriteLine($"traversalRightShelfOffset {traversalRightShelfOffset}");
        Console.WriteLine($"traversalDirectShelfOffset {traversalDirectShelfOffset}");
        Console.WriteLine($"traversalUncachedCount {traversalUncachedCount}");
        Console.WriteLine($"traversalCachedCount {traversalCachedCount}");
        Console.WriteLine($"traversalUncachedChecksum {traversalUncachedChecksum}");
        Console.WriteLine($"traversalCachedChecksum {traversalCachedChecksum}");
        PrintRead("ss8-8 range scoop uncached", uncachedRead);
        PrintRead("ss8-8 range scoop cached", cachedRead);
        PrintRead("ss8-8 range scoop cross uncached", crossUncachedRead);
        PrintRead("ss8-8 range scoop cross cached", crossCachedRead);
        PrintRead("ss8-8 range scoop traversal uncached", traversalUncachedRead);
        PrintRead("ss8-8 range scoop traversal cached", traversalCachedRead);
        Console.WriteLine($"ss8-8-range-scoop-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates that an `SS8-8` runtime index handle can be resolved from reopened index-directory metadata and used for encoded range reads.<br/>
    /// The setup creates a root router and one routed shelf, closes the session, reopens the file, resolves the handle from slot metadata, and reads the same range through explicit and pooled handle APIs.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when reopened handle resolution and range reads succeed.</returns>
    private static int RunScalar8Scalar8HandleReopenSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-handle-reopen-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        const int slotIndex = 0;
        const int itemCount = 128;
        const int rangeStart = 16;
        const int rangeLength = 32;
        ulong[] keys = new ulong[itemCount];
        ulong[] identities = new ulong[itemCount];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = (ulong)i;
            identities[i] = keys[i];
        }

        long createdRootOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(51), DataKernelTelemetryOptions.EnabledOptions))
        {
            (Scalar8Scalar8IndexHandle index, RouterSnapshot root, _) = session.CreateScalar8Scalar8RootRouterIndex(CreateHarnessSlot(slotIndex, "ss8reopen", 0));
            if (index.RootRouterOffset != root.Offset || index.Profile != profile)
            {
                throw new InvalidDataException("Created SS8-8 handle did not match the root router or default profile.");
            }

            createdRootOffset = root.Offset;
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
        }

        ulong lowerKey = (ulong)rangeStart;
        ulong upperKey = lowerKey + (ulong)(rangeLength - 1);
        ulong[] explicitIdentities = new ulong[rangeLength];
        ulong[] pooledIdentities = new ulong[rangeLength];
        DataKernelReadTelemetry explicitRead;
        DataKernelReadTelemetry pooledRead;
        Scalar8Scalar8RangeReadResult explicitResult;
        Scalar8Scalar8RangeReadResult pooledResult;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            Scalar8Scalar8IndexHandle slotHandle = reopened.GetScalar8Scalar8IndexHandle(slotIndex);
            Scalar8Scalar8IndexHandle offsetHandle = reopened.GetScalar8Scalar8IndexHandleByRootRouterOffset(createdRootOffset);
            if (slotHandle != offsetHandle || slotHandle.RootRouterOffset != createdRootOffset || slotHandle.Profile != profile)
            {
                throw new InvalidDataException("Reopened SS8-8 handle resolution did not preserve root offset and profile.");
            }

            byte[] shelfScratch = new byte[profile.ShelfExtentSize];
            byte[] rangeScratch = new byte[profile.ShelfExtentSize * Scalar8Scalar8RangeReadOptions.CoalescingCached.CoalescedShelfScratchCount];
            Scalar8Scalar8RangeReadScratch scratch = new(shelfScratch, rangeScratch);
            reopened.ClearRouterArenaReadCacheForValidation();
            _ = reopened.GetAndResetReadTelemetry();
            explicitResult = reopened.ReadEncodedScalar8Scalar8IdentityRange(
                slotHandle,
                lowerKey,
                upperKey,
                Scalar8Scalar8RangeReadOptions.CoalescingCached,
                explicitIdentities,
                scratch);
            explicitRead = reopened.GetAndResetReadTelemetry();

            reopened.ClearRouterArenaReadCacheForValidation();
            pooledResult = reopened.ReadEncodedScalar8Scalar8IdentityRangePooled(
                slotHandle,
                lowerKey,
                upperKey,
                Scalar8Scalar8RangeReadOptions.CoalescingCached,
                pooledIdentities);
            pooledRead = reopened.GetAndResetReadTelemetry();
        }

        long explicitChecksum = CheckScalar8Scalar8RangeScoop(lowerKey, explicitIdentities, explicitResult.IdentityCount, rangeLength);
        long pooledChecksum = CheckScalar8Scalar8RangeScoop(lowerKey, pooledIdentities, pooledResult.IdentityCount, rangeLength);
        if (explicitChecksum != pooledChecksum)
        {
            throw new InvalidDataException("Reopened SS8-8 handle explicit and pooled reads returned different identity checksums.");
        }

        if (explicitResult.UsedPooledScratch || !pooledResult.UsedPooledScratch)
        {
            throw new InvalidDataException("Reopened SS8-8 handle range results did not report scratch ownership correctly.");
        }

        Console.WriteLine("ss8-8 handle reopen");
        Console.WriteLine($"rootOffset {createdRootOffset}");
        Console.WriteLine($"rangeStart {rangeStart}");
        Console.WriteLine($"rangeLength {rangeLength}");
        Console.WriteLine($"explicitCount {explicitResult.IdentityCount}");
        Console.WriteLine($"pooledCount {pooledResult.IdentityCount}");
        Console.WriteLine($"explicitChecksum {explicitChecksum}");
        Console.WriteLine($"pooledChecksum {pooledChecksum}");
        PrintRead("ss8-8 handle reopen explicit", explicitRead);
        PrintRead("ss8-8 handle reopen pooled", pooledRead);
        Console.WriteLine($"ss8-8-handle-reopen-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates the first public `LibraDex.Indexes.SS88` factory and encoded index wrapper shape.<br/>
    /// The scenario covers file create, file open, file create-or-open, and memory-backed create-or-open without adding developer-facing codecs.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the public facade preserves encoded insert/read behavior across backing modes.</returns>
    private static int RunScalar8Scalar8IndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-index-api-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        ulong key = Scalar8Scalar8Layout.EncodeUnsignedScalar8(42);
        ulong identity = Scalar8Scalar8Layout.EncodeUnsignedScalar8(4200);
        ulong secondKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8(43);
        ulong secondIdentity = Scalar8Scalar8Layout.EncodeUnsignedScalar8(4300);
        ulong[] identities = new ulong[4];
        ulong[] manyIdentities = new ulong[4096];

        using (Scalar8Scalar8Index created = Indexes.SS88.Create(
            path,
            DataKernelBackingKind.File,
            name: "api",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(71),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (created.BackingKind != DataKernelBackingKind.File || created.SlotIndex != 0 || created.Name != "api")
            {
                throw new InvalidDataException("Created SS8-8 public index did not preserve backing, slot, or name metadata.");
            }

            Scalar8Scalar8EncodedInsertResult insert = created.InsertEncoded(key, identity);
            if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted || !insert.CreatedInitialShelfRoute)
            {
                throw new InvalidDataException("Created SS8-8 public index did not report first route creation and insert.");
            }

            Scalar8Scalar8EncodedRangeReadResult read = created.ReadEncodedRange(key, key, identities);
            if (read.IdentityCount != 1 || identities[0] != identity)
            {
                throw new InvalidDataException("Created SS8-8 public index did not read back the inserted encoded identity.");
            }
        }

        Array.Clear(identities);
        using (Scalar8Scalar8Index opened = Indexes.SS88.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            Scalar8Scalar8EncodedRangeReadResult read = opened.ReadEncodedRange(key, key, identities);
            if (opened.BackingKind != DataKernelBackingKind.File || read.IdentityCount != 1 || identities[0] != identity)
            {
                throw new InvalidDataException("Opened SS8-8 public index did not preserve file-backed range-read behavior.");
            }
        }

        using (Scalar8Scalar8Index createOrOpen = Indexes.SS88.CreateOrOpen(
            path,
            DataKernelBackingKind.File,
            name: "ignored",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(72),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            Scalar8Scalar8EncodedInsertResult insert = createOrOpen.InsertEncoded(secondKey, secondIdentity);
            if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted || insert.CreatedInitialShelfRoute)
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 public index did not open the existing file-backed slot.");
            }

            Array.Clear(identities);
            Scalar8Scalar8EncodedRangeReadResult materialized = createOrOpen.ReadEncodedRange(key, secondKey, identities);
            using Scalar8Scalar8RangeReader reader = createOrOpen.OpenEncodedRangeReader(key, secondKey);
            if (reader.Count != materialized.IdentityCount || reader.Count != 2)
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 range reader did not report the same count as materialized range read.");
            }

            if (!reader.MoveNext() || reader.CurrentEncodedKey != key || reader.CurrentEncodedIdentity != identity)
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 range reader did not expose the first encoded tuple in sorted order.");
            }

            if (reader.Skip(1) != 1 || reader.CurrentEncodedKey != secondKey || reader.CurrentEncodedIdentity != secondIdentity)
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 range reader did not skip to the second encoded tuple.");
            }

            if (reader.MoveNext())
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 range reader returned extra rows after the expected range.");
            }

            const int routedReaderExtraItems = 2300;
            for (int i = 0; i < routedReaderExtraItems; i++)
            {
                ulong extraValue = (ulong)(1000 + i);
                Scalar8Scalar8EncodedInsertResult extraInsert = createOrOpen.InsertEncoded(
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(extraValue),
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(extraValue + 100_000));
                if (extraInsert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted)
                {
                    throw new InvalidDataException($"CreateOrOpen SS8-8 routed range reader setup insert {i} did not insert.");
                }
            }

            ulong routedLowerKey = key;
            ulong routedUpperKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8(1000 + routedReaderExtraItems - 1);
            Array.Clear(manyIdentities);
            Scalar8Scalar8EncodedRangeReadResult routedMaterialized = createOrOpen.ReadEncodedRange(routedLowerKey, routedUpperKey, manyIdentities);
            using Scalar8Scalar8RangeReader routedReader = createOrOpen.OpenEncodedRangeReader(routedLowerKey, routedUpperKey);
            if (routedReader.Count != routedMaterialized.IdentityCount || routedReader.Count != routedReaderExtraItems + 2)
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 routed range reader did not report the same count as routed materialized range read.");
            }

            int routedOrdinal = 0;
            while (routedReader.MoveNext())
            {
                if (routedReader.CurrentEncodedIdentity != manyIdentities[routedOrdinal])
                {
                    throw new InvalidDataException($"CreateOrOpen SS8-8 routed range reader identity mismatch at ordinal {routedOrdinal}.");
                }

                routedOrdinal++;
            }

            if (routedOrdinal != routedMaterialized.IdentityCount)
            {
                throw new InvalidDataException("CreateOrOpen SS8-8 routed range reader did not iterate the materialized count.");
            }
        }

        Array.Clear(identities);
        using (Scalar8Scalar8Index memory = Indexes.SS88.CreateOrOpen(
            backingKind: DataKernelBackingKind.Memory,
            name: "memory",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(73),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (memory.BackingKind != DataKernelBackingKind.Memory)
            {
                throw new InvalidDataException("Memory-backed SS8-8 public index did not report memory backing.");
            }

            Scalar8Scalar8EncodedInsertResult insert = memory.InsertEncoded(key, identity);
            Scalar8Scalar8EncodedRangeReadResult read = memory.ReadEncodedRange(key, key, identities);
            if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted || !insert.CreatedInitialShelfRoute || read.IdentityCount != 1 || identities[0] != identity)
            {
                throw new InvalidDataException("Memory-backed SS8-8 public index did not insert and read encoded identity.");
            }
        }

        Array.Clear(identities);
        using (UnsignedScalar8Scalar8Index unsigned = Indexes.SS88.Unsigned.Create(
            backingKind: DataKernelBackingKind.Memory,
            name: "unsigned-reader",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(74),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = unsigned.Insert(10, 1000);
            _ = unsigned.Insert(11, 1100);
            _ = unsigned.Insert(12, 1200);
            UnsignedScalar8Scalar8RangeReadResult unsignedRead = unsigned.ReadRange(10, 12, identities);
            using UnsignedScalar8Scalar8RangeReader unsignedReader = unsigned.OpenRangeReader(10, 12);
            if (unsignedRead.IdentityCount != 3 || unsignedReader.Count != 3)
            {
                throw new InvalidDataException("Unsigned SS8-8 range reader count did not match typed materialized range read.");
            }

            if (!unsignedReader.TryReadNextIdentity(out ulong firstUnsignedIdentity) || firstUnsignedIdentity != 1000)
            {
                throw new InvalidDataException("Unsigned SS8-8 range reader identity-only path did not return the first identity.");
            }

            if (unsignedReader.Skip(1) != 1 || unsignedReader.CurrentKey != 11 || unsignedReader.CurrentIdentity != 1100)
            {
                throw new InvalidDataException("Unsigned SS8-8 range reader skip did not advance to the second tuple.");
            }

            if (!unsignedReader.TryReadNext(out ulong finalUnsignedKey, out ulong finalUnsignedIdentity) || finalUnsignedKey != 12 || finalUnsignedIdentity != 1200)
            {
                throw new InvalidDataException("Unsigned SS8-8 range reader tuple path did not return the final tuple.");
            }

            if (unsignedReader.MoveNext())
            {
                throw new InvalidDataException("Unsigned SS8-8 range reader returned extra rows.");
            }

            using UnsignedScalar8Scalar8RangeReader unsignedKeyReader = unsigned.OpenRangeReader(10, 12);
            if (!unsignedKeyReader.TryReadNextKey(out ulong firstUnsignedKey) || firstUnsignedKey != 10)
            {
                throw new InvalidDataException("Unsigned SS8-8 range reader key-only path did not return the first key.");
            }
        }

        Console.WriteLine("ss8-8 index api sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine("fileCreate ok");
        Console.WriteLine("fileOpen ok");
        Console.WriteLine("fileCreateOrOpen ok");
        Console.WriteLine("encodedRangeReader ok");
        Console.WriteLine("routedEncodedRangeReader ok");
        Console.WriteLine("memoryCreateOrOpen ok");
        Console.WriteLine("unsignedRangeReader ok");
        Console.WriteLine($"ss8-8-index-api-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates public/reopenable `SS8-8` shelf-profile selection without changing the encoded tuple shape.<br/>
    /// The scenario keeps 32 KiB as the control profile, creates a requested smaller shelf extent, reopens it from index-directory metadata, and verifies memory-backed creation uses the same profile path.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the supported profile survives public creation, reopen, range read, and memory-backed creation.</returns>
    private static int RunScalar8Scalar8ProfileSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-profile-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        int shelfExtentSize = GetIntOption(args, "--shelf-size", Scalar8Scalar8Profile.Default24KiB.ShelfExtentSize);
        Scalar8Scalar8Profile requestedProfile = Scalar8Scalar8Profile.FromSupportedShelfExtentSize(shelfExtentSize);
        Scalar8Scalar8Profile controlProfile = Scalar8Scalar8Profile.Default32KiB;
        if (requestedProfile.ShelfExtentSize == controlProfile.ShelfExtentSize)
        {
            throw new InvalidDataException("SS8-8 profile sanity should exercise a non-default shelf extent.");
        }

        DataKernelOptions options = CreateDesignPerfOptions();
        ulong[] identities = new ulong[4];
        ulong firstKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8(100);
        ulong firstIdentity = Scalar8Scalar8Layout.EncodeUnsignedScalar8(1000);
        ulong secondKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8(101);
        ulong secondIdentity = Scalar8Scalar8Layout.EncodeUnsignedScalar8(1010);

        using (Scalar8Scalar8Index created = Indexes.SS88.Create(
            path,
            DataKernelBackingKind.File,
            name: "profile24",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(91),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions,
            shelfExtentSize: requestedProfile.ShelfExtentSize))
        {
            if (created.Handle.Profile != requestedProfile)
            {
                throw new InvalidDataException("Created SS8-8 public index did not use the requested shelf profile.");
            }

            Scalar8Scalar8EncodedInsertResult insert = created.InsertEncoded(firstKey, firstIdentity);
            Scalar8Scalar8EncodedRangeReadResult read = created.ReadEncodedRange(firstKey, firstKey, identities);
            if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted || !insert.CreatedInitialShelfRoute || read.IdentityCount != 1 || identities[0] != firstIdentity)
            {
                throw new InvalidDataException("Created profiled SS8-8 public index did not insert and read the first encoded identity.");
            }
        }

        Array.Clear(identities);
        using (Scalar8Scalar8Index opened = Indexes.SS88.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (opened.Handle.Profile != requestedProfile)
            {
                throw new InvalidDataException("Reopened SS8-8 public index did not resolve the persisted shelf profile.");
            }

            Scalar8Scalar8EncodedRangeReadResult read = opened.ReadEncodedRange(firstKey, firstKey, identities);
            if (read.IdentityCount != 1 || identities[0] != firstIdentity)
            {
                throw new InvalidDataException("Reopened profiled SS8-8 public index did not read the first encoded identity.");
            }
        }

        using (Scalar8Scalar8Index createOrOpen = Indexes.SS88.CreateOrOpen(
            path,
            DataKernelBackingKind.File,
            name: "ignored",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(92),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions,
            shelfExtentSize: controlProfile.ShelfExtentSize))
        {
            if (createOrOpen.Handle.Profile != requestedProfile)
            {
                throw new InvalidDataException("CreateOrOpen changed an existing SS8-8 shelf profile instead of using persisted metadata.");
            }

            Scalar8Scalar8EncodedInsertResult insert = createOrOpen.InsertEncoded(secondKey, secondIdentity);
            if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted || insert.CreatedInitialShelfRoute)
            {
                throw new InvalidDataException("CreateOrOpen profiled SS8-8 public index did not open and mutate the existing slot.");
            }
        }

        Array.Clear(identities);
        using (Scalar8Scalar8Index memory = Indexes.SS88.CreateOrOpen(
            backingKind: DataKernelBackingKind.Memory,
            name: "profile-memory",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(93),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions,
            shelfExtentSize: requestedProfile.ShelfExtentSize))
        {
            if (memory.Handle.Profile != requestedProfile || memory.BackingKind != DataKernelBackingKind.Memory)
            {
                throw new InvalidDataException("Memory-backed profiled SS8-8 public index did not use the requested shelf profile.");
            }

            Scalar8Scalar8EncodedInsertResult insert = memory.InsertEncoded(firstKey, firstIdentity);
            Scalar8Scalar8EncodedRangeReadResult read = memory.ReadEncodedRange(firstKey, firstKey, identities);
            if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted || !insert.CreatedInitialShelfRoute || read.IdentityCount != 1 || identities[0] != firstIdentity)
            {
                throw new InvalidDataException("Memory-backed profiled SS8-8 public index did not insert and read encoded identity.");
            }
        }

        Console.WriteLine("ss8-8 profile sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine($"controlShelfSize {controlProfile.ShelfExtentSize}");
        Console.WriteLine($"profileShelfSize {requestedProfile.ShelfExtentSize}");
        Console.WriteLine($"profileMaxItems {requestedProfile.MaxItemCount}");
        Console.WriteLine($"profileUnusedTail {requestedProfile.UnusedTailBytes}");
        Console.WriteLine("fileCreate ok");
        Console.WriteLine("fileOpen ok");
        Console.WriteLine("fileCreateOrOpenPreservesExistingProfile ok");
        Console.WriteLine("memoryCreateOrOpen ok");
        Console.WriteLine($"ss8-8-profile-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates the first typed unsigned scalar `SS8-8` factory and index wrapper shape.<br/>
    /// The scenario covers file create, file open, file create-or-open, memory-backed create-or-open, typed inserts, typed range reads, and typed batch commit.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the typed public facade preserves unsigned scalar insert/read behavior across backing modes.</returns>
    private static int RunUnsignedScalar8Scalar8IndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-typed-api-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        ulong[] identities = new ulong[8];

        using (UnsignedScalar8Scalar8Index created = Indexes.SS88.Unsigned.Create(
            path,
            DataKernelBackingKind.File,
            name: "typed",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(74),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (created.BackingKind != DataKernelBackingKind.File || created.SlotIndex != 0 || created.Name != "typed")
            {
                throw new InvalidDataException("Created unsigned SS8-8 public index did not preserve backing, slot, or name metadata.");
            }

            UnsignedScalar8Scalar8InsertResult insert = created.Insert(42, 4200);
            if (insert.Outcome != UnsignedScalar8Scalar8InsertOutcome.Inserted || !insert.CreatedInitialShelfRoute)
            {
                throw new InvalidDataException("Created unsigned SS8-8 public index did not report first route creation and insert.");
            }

            UnsignedScalar8Scalar8InsertResult duplicate = created.Insert(42, 4200);
            UnsignedScalar8Scalar8InsertResult keyConflict = created.Insert(42, 4201, allowDuplicateKeys: false);
            if (duplicate.Outcome != UnsignedScalar8Scalar8InsertOutcome.AlreadyPresent ||
                keyConflict.Outcome != UnsignedScalar8Scalar8InsertOutcome.KeyConflict)
            {
                throw new InvalidDataException("Created unsigned SS8-8 public index did not preserve typed duplicate and key-conflict outcomes.");
            }

            UnsignedScalar8Scalar8RangeReadResult read = created.ReadRange(42, 42, identities);
            if (read.IdentityCount != 1 || identities[0] != 4200)
            {
                throw new InvalidDataException("Created unsigned SS8-8 public index did not read back the inserted identity.");
            }
        }

        Array.Clear(identities);
        using (UnsignedScalar8Scalar8Index opened = Indexes.SS88.Unsigned.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            UnsignedScalar8Scalar8RangeReadResult read = opened.ReadRange(42, 42, identities);
            if (opened.BackingKind != DataKernelBackingKind.File || read.IdentityCount != 1 || identities[0] != 4200)
            {
                throw new InvalidDataException("Opened unsigned SS8-8 public index did not preserve file-backed range-read behavior.");
            }
        }

        using (UnsignedScalar8Scalar8Index createOrOpen = Indexes.SS88.Unsigned.CreateOrOpen(
            path,
            DataKernelBackingKind.File,
            name: "ignored",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(75),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using UnsignedScalar8Scalar8Batch batch = createOrOpen.BeginBatch();
            UnsignedScalar8Scalar8InsertResult first = batch.Insert(43, 4300);
            UnsignedScalar8Scalar8InsertResult second = batch.Insert(44, 4400);
            UnsignedScalar8Scalar8BatchCommitResult commit = batch.Commit();
            if (first.Outcome != UnsignedScalar8Scalar8InsertOutcome.Inserted ||
                second.Outcome != UnsignedScalar8Scalar8InsertOutcome.Inserted ||
                commit.InsertedCount != 2 ||
                commit.DeferredCommitRequests == 0)
            {
                throw new InvalidDataException("Typed unsigned SS8-8 batch did not insert and commit through CreateOrOpen.");
            }
        }

        Array.Clear(identities);
        using (UnsignedScalar8Scalar8Index reopened = Indexes.SS88.Unsigned.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            UnsignedScalar8Scalar8RangeReadResult read = reopened.ReadRange(42, 44, identities);
            if (read.IdentityCount != 3 || identities[0] != 4200 || identities[1] != 4300 || identities[2] != 4400)
            {
                throw new InvalidDataException("Reopened unsigned SS8-8 public index did not read typed batch identities in key order.");
            }
        }

        Array.Clear(identities);
        using (UnsignedScalar8Scalar8Index memory = Indexes.SS88.Unsigned.CreateOrOpen(
            backingKind: DataKernelBackingKind.Memory,
            name: "typed-memory",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(76),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (memory.BackingKind != DataKernelBackingKind.Memory)
            {
                throw new InvalidDataException("Memory-backed unsigned SS8-8 public index did not report memory backing.");
            }

            UnsignedScalar8Scalar8InsertResult insert = memory.Insert(7, 70);
            UnsignedScalar8Scalar8RangeReadResult read = memory.ReadRange(7, 7, identities);
            if (insert.Outcome != UnsignedScalar8Scalar8InsertOutcome.Inserted || !insert.CreatedInitialShelfRoute || read.IdentityCount != 1 || identities[0] != 70)
            {
                throw new InvalidDataException("Memory-backed unsigned SS8-8 public index did not insert and read identity.");
            }
        }

        Console.WriteLine("ss8-8 typed api sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine("typedFileCreate ok");
        Console.WriteLine("typedFileOpen ok");
        Console.WriteLine("typedFileCreateOrOpen ok");
        Console.WriteLine("typedInsertOutcomes ok");
        Console.WriteLine("typedBatchCommit ok");
        Console.WriteLine("typedMemoryCreateOrOpen ok");
        Console.WriteLine($"ss8-8-typed-api-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates the first generic public index factory and batch insertion surface across the four current physical scalar shapes.<br/>
    /// The scenario covers generic type routing for numeric and `Guid` pairs plus explicit-width `byte[]`, file-backed `CreateOrOpen`, file-backed `Open`, memory-backed create, and batch commit counts.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when generic public API creation, opening, and insertion preserve the expected shape routing.</returns>
    private static int RunGenericIndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "generic-index-api-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        Guid guidKey = Guid.Parse("00112233-4455-6677-8899-aabbccddeeff");
        Guid guidIdentity = Guid.Parse("10213243-5465-7687-98a9-bacbdcedfe0f");
        byte[] bytes16 = Convert.FromHexString("00112233445566778899AABBCCDDEEFF");
        byte[] bytes8 = Convert.FromHexString("0102030405060708");
        byte[] bytes32 = Convert.FromHexString("00112233445566778899AABBCCDDEEFF102132435465768798A9BACBDCEDFE0F");

        using (LibraDexIndex<long, long> index = Indexes.CreateOrOpen<long, long>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 0,
            name: "long-long",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(901),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(42, 4200), "long/long single insert");
            using LibraDexBatch<long, long> batch = index.BeginBatch();
            ValidateGenericInsert(batch.Insert(43, 4300), "long/long batch insert");
            LibraDexGenericBatchCommitResult commit = batch.Commit();
            if (commit.InsertedCount != 1 || commit.DeferredCommitRequests == 0)
            {
                throw new InvalidDataException("Generic long/long batch did not commit one inserted tuple with deferred requests.");
            }

            long[] identities = new long[4];
            LibraDexGenericRangeReadResult read = index.ReadRange(42, 43, identities);
            ValidateGenericRead(read, identities, new long[] { 4200, 4300 }, "long/long same-session read");
            using LibraDexRangeReader<long, long> reader = index.OpenRangeReader(42, 43);
            ValidateGenericLongReader(reader, new long[] { 4200, 4300 }, "long/long same-session reader", skipAfterFirst: true);
        }

        using (LibraDexIndex<Guid, long> index = Indexes.CreateOrOpen<Guid, long>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 1,
            name: "guid-long",
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(guidKey, 1001), "Guid/long insert");
            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(guidKey, guidKey, identities);
            ValidateGenericRead(read, identities, new long[] { 1001 }, "Guid/long same-session read");
            using LibraDexRangeReader<Guid, long> reader = index.OpenRangeReader(guidKey, guidKey);
            ValidateGenericLongReader(reader, new long[] { 1001 }, "Guid/long same-session reader");
        }

        using (LibraDexIndex<long, Guid> index = Indexes.CreateOrOpen<long, Guid>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 2,
            name: "long-guid",
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(1002, guidIdentity), "long/Guid insert");
            Guid[] identities = new Guid[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(1002, 1002, identities);
            ValidateGenericGuidRead(read, identities, new Guid[] { guidIdentity }, "long/Guid same-session read");
            using LibraDexRangeReader<long, Guid> reader = index.OpenRangeReader(1002, 1002);
            ValidateGenericGuidReader(reader, new Guid[] { guidIdentity }, "long/Guid same-session reader");
        }

        using (LibraDexIndex<Guid, Guid> index = Indexes.CreateOrOpen<Guid, Guid>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 3,
            name: "guid-guid",
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(guidKey, guidIdentity), "Guid/Guid insert");
            Guid[] identities = new Guid[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(guidKey, guidKey, identities);
            ValidateGenericGuidRead(read, identities, new Guid[] { guidIdentity }, "Guid/Guid same-session read");
            using LibraDexRangeReader<Guid, Guid> reader = index.OpenRangeReader(guidKey, guidKey);
            ValidateGenericGuidReader(reader, new Guid[] { guidIdentity }, "Guid/Guid same-session reader");
        }

        using (LibraDexIndex<byte[], byte[]> index = Indexes.CreateOrOpen<byte[], byte[]>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 4,
            name: "bytes-bytes",
            keyWidth: LibraDexScalarWidth.Bytes16,
            identityWidth: LibraDexScalarWidth.Bytes8,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(bytes16, bytes8), "byte[]/byte[] insert");
            byte[][] identities = new byte[2][];
            LibraDexGenericRangeReadResult read = index.ReadRange(bytes16, bytes16, identities);
            ValidateGenericByteArrayRead(read, identities, new byte[][] { bytes8 }, "byte[]/byte[] same-session read");
            using LibraDexRangeReader<byte[], byte[]> reader = index.OpenRangeReader(bytes16, bytes16);
            ValidateGenericByteArrayReader(reader, new byte[][] { bytes8 }, "byte[]/byte[] same-session reader");
        }

        using (LibraDexIndex<byte[], long> index = Indexes.CreateOrOpen<byte[], long>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 5,
            name: "bytes-long",
            keyWidth: LibraDexScalarWidth.Bytes16,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(bytes16, 5001), "byte[]/long insert");
            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(bytes16, bytes16, identities);
            ValidateGenericRead(read, identities, new long[] { 5001 }, "byte[]/long same-session read");
            using LibraDexRangeReader<byte[], long> reader = index.OpenRangeReader(bytes16, bytes16);
            ValidateGenericLongReader(reader, new long[] { 5001 }, "byte[]/long same-session reader");
        }

        using (LibraDexIndex<long, byte[]> index = Indexes.CreateOrOpen<long, byte[]>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 6,
            name: "long-bytes",
            identityWidth: LibraDexScalarWidth.Bytes16,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(6001, bytes16), "long/byte[] insert");
            using LibraDexRangeReader<long, byte[]> reader = index.OpenRangeReader(6001, 6001);
            ValidateGenericByteArrayReader(reader, new byte[][] { bytes16 }, "long/byte[] same-session reader");
        }

        using (LibraDexIndex<Guid, byte[]> index = Indexes.CreateOrOpen<Guid, byte[]>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 7,
            name: "guid-bytes",
            identityWidth: LibraDexScalarWidth.Bytes16,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(guidKey, bytes16), "Guid/byte[] insert");
            using LibraDexRangeReader<Guid, byte[]> reader = index.OpenRangeReader(guidKey, guidKey);
            ValidateGenericByteArrayReader(reader, new byte[][] { bytes16 }, "Guid/byte[] same-session reader");
        }

        using (LibraDexIndex<byte[], Guid> index = Indexes.CreateOrOpen<byte[], Guid>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 8,
            name: "bytes-guid",
            keyWidth: LibraDexScalarWidth.Bytes16,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(bytes16, guidIdentity), "byte[]/Guid insert");
            using LibraDexRangeReader<byte[], Guid> reader = index.OpenRangeReader(bytes16, bytes16);
            ValidateGenericGuidReader(reader, new Guid[] { guidIdentity }, "byte[]/Guid same-session reader");
        }

        using (LibraDexIndex<byte[], long> index = Indexes.CreateOrOpen<byte[], long>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 9,
            name: "bytes32-long",
            keyWidth: LibraDexScalarWidth.Bytes32,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(bytes32, 9001), "byte32[]/long insert");
            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(bytes32, bytes32, identities);
            ValidateGenericRead(read, identities, new long[] { 9001 }, "byte32[]/long same-session read");
            using LibraDexRangeReader<byte[], long> reader = index.OpenRangeReader(bytes32, bytes32);
            ValidateGenericLongReader(reader, new long[] { 9001 }, "byte32[]/long same-session reader");
        }

        using (LibraDexIndex<byte[], Guid> index = Indexes.CreateOrOpen<byte[], Guid>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 10,
            name: "bytes32-guid",
            keyWidth: LibraDexScalarWidth.Bytes32,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(index.Insert(bytes32, guidIdentity), "byte32[]/Guid insert");
            Guid[] identities = new Guid[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(bytes32, bytes32, identities);
            ValidateGenericGuidRead(read, identities, new Guid[] { guidIdentity }, "byte32[]/Guid same-session read");
            using LibraDexRangeReader<byte[], Guid> reader = index.OpenRangeReader(bytes32, bytes32);
            ValidateGenericGuidReader(reader, new Guid[] { guidIdentity }, "byte32[]/Guid same-session reader");
        }

        using (LibraDexIndex<TimeSpan, long> index = Indexes.CreateOrOpen<TimeSpan, long>(
            path,
            DataKernelBackingKind.File,
            slotIndex: 11,
            name: "timespan-long",
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            TimeSpan duration = TimeSpan.FromMinutes(90);
            ValidateGenericInsert(index.Insert(duration, 11001), "TimeSpan/long insert");
            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = index.ReadRange(TimeSpan.FromHours(1), TimeSpan.FromHours(2), identities);
            ValidateGenericRead(read, identities, new long[] { 11001 }, "TimeSpan/long same-session range read");
            using LibraDexRangeReader<TimeSpan, long> reader = index.OpenRangeReader(duration, duration);
            ValidateGenericLongReader(reader, new long[] { 11001 }, "TimeSpan/long same-session reader");
        }

        using (LibraDexIndex<long, long> opened = Indexes.Open<long, long>(path, slotIndex: 0, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (opened.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the long/long root-router offset.");
            }

            long[] identities = new long[4];
            LibraDexGenericRangeReadResult read = opened.ReadRange(42, 43, identities);
            ValidateGenericRead(read, identities, new long[] { 4200, 4300 }, "long/long reopened read");
        }

        using (LibraDexIndex<Guid, long> openedGuid = Indexes.Open<Guid, long>(path, slotIndex: 1, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedGuid.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the Guid/long root-router offset.");
            }
        }

        using (LibraDexIndex<byte[], byte[]> openedBytes = Indexes.Open<byte[], byte[]>(path, slotIndex: 4, keyWidth: LibraDexScalarWidth.Bytes16, identityWidth: LibraDexScalarWidth.Bytes8, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedBytes.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the byte[]/byte[] root-router offset.");
            }
        }

        using (LibraDexIndex<byte[], long> openedBytesLong = Indexes.Open<byte[], long>(path, slotIndex: 5, keyWidth: LibraDexScalarWidth.Bytes16, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedBytesLong.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the byte[]/long root-router offset.");
            }
        }

        using (LibraDexIndex<byte[], long> openedBytes32Long = Indexes.Open<byte[], long>(path, slotIndex: 9, keyWidth: LibraDexScalarWidth.Bytes32, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedBytes32Long.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the byte32[]/long root-router offset.");
            }

            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = openedBytes32Long.ReadRange(bytes32, bytes32, identities);
            ValidateGenericRead(read, identities, new long[] { 9001 }, "byte32[]/long reopened read");
        }

        using (LibraDexIndex<byte[], Guid> openedBytes32Guid = Indexes.Open<byte[], Guid>(path, slotIndex: 10, keyWidth: LibraDexScalarWidth.Bytes32, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedBytes32Guid.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the byte32[]/Guid root-router offset.");
            }

            Guid[] identities = new Guid[2];
            LibraDexGenericRangeReadResult read = openedBytes32Guid.ReadRange(bytes32, bytes32, identities);
            ValidateGenericGuidRead(read, identities, new Guid[] { guidIdentity }, "byte32[]/Guid reopened read");
        }

        using (LibraDexIndex<TimeSpan, long> openedTimeSpan = Indexes.Open<TimeSpan, long>(path, slotIndex: 11, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedTimeSpan.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the TimeSpan/long root-router offset.");
            }

            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = openedTimeSpan.ReadRange(TimeSpan.FromMinutes(90), TimeSpan.FromMinutes(90), identities);
            ValidateGenericRead(read, identities, new long[] { 11001 }, "TimeSpan/long reopened read");
        }

        using (LibraDexIndex<long, byte[]> openedLongBytes = Indexes.Open<long, byte[]>(path, slotIndex: 6, identityWidth: LibraDexScalarWidth.Bytes16, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedLongBytes.RootRouterOffset == 0)
            {
                throw new InvalidDataException("Generic Open did not resolve the long/byte[] root-router offset.");
            }
        }

        using (LibraDexIndex<int, Guid> memory = Indexes.Create<int, Guid>(
            backingKind: DataKernelBackingKind.Memory,
            name: "memory-generic",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(902),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (memory.BackingKind != DataKernelBackingKind.Memory)
            {
                throw new InvalidDataException("Generic memory-backed index did not report memory backing.");
            }

            ValidateGenericInsert(memory.Insert(7, guidIdentity), "memory int/Guid insert");
        }

        using (LibraDexIndex<long, long> memoryRead = Indexes.Create<long, long>(
            backingKind: DataKernelBackingKind.Memory,
            name: "memory-generic-read",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(903),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateGenericInsert(memoryRead.Insert(77, 7700), "memory long/long read insert");
            long[] identities = new long[2];
            LibraDexGenericRangeReadResult read = memoryRead.ReadRange(77, 77, identities);
            ValidateGenericRead(read, identities, new long[] { 7700 }, "memory long/long read");
        }

        Console.WriteLine("generic index api sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine("genericLongLong ok");
        Console.WriteLine("genericGuidLong ok");
        Console.WriteLine("genericLongGuid ok");
        Console.WriteLine("genericGuidGuid ok");
        Console.WriteLine("genericBytesExplicitWidth ok");
        Console.WriteLine("genericMixedByteScalar ok");
        Console.WriteLine("genericOpen ok");
        Console.WriteLine("genericRead ok");
        Console.WriteLine("genericRangeReader ok");
        Console.WriteLine("genericWideRead ok");
        Console.WriteLine("genericBytes32Long ok");
        Console.WriteLine("genericBytes32Guid ok");
        Console.WriteLine("genericTimeSpanLong ok");
        Console.WriteLine("genericMemory ok");
        Console.WriteLine($"generic-index-api-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Validates the catalog-first public API draft using the intended low-friction call shape.<br/>
    /// The scenario covers memory-backed catalog creation, grouped scalar factory discovery, normal insert/read, index-global batch manager commit cadence, and explicit close semantics.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the catalog-first API behaves as expected.</returns>
    private static int RunCatalogApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine("artifacts", "tmp-catalog-api-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
        File.Delete(path);

        using Catalog catalog = Catalog.CreateMemory();
        if (catalog.BackingKind != DataKernelBackingKind.Memory)
        {
            throw new InvalidDataException("Catalog.CreateMemory did not produce a memory-backed catalog.");
        }

        LibraDexIndex<long, long> index = catalog.Indexes.Scalar.Scalar.Create<long, long>(
            "primary",
            keys: IndexKeys.NonUnique);
        if (index.KeyContract != IndexKeys.NonUnique)
        {
            throw new InvalidDataException("Catalog-created index did not preserve the requested key contract.");
        }

        if (!catalog.Indexes.Exists(0) ||
            !catalog.Indexes.Exists("primary") ||
            !catalog.Indexes.TryGetInfo(0, out CatalogIndexInfo primaryInfo) ||
            primaryInfo.Name != "primary" ||
            primaryInfo.KeyFamily != CatalogIndexKeyFamily.Scalar ||
            primaryInfo.IdentityFamily != CatalogIndexIdentityFamily.Scalar ||
            primaryInfo.KeyContract != IndexKeys.NonUnique ||
            string.IsNullOrWhiteSpace(primaryInfo.KeyTypeName) ||
            string.IsNullOrWhiteSpace(primaryInfo.IdentityTypeName) ||
            catalog.Indexes.List().Length != 1)
        {
            throw new InvalidDataException("Catalog index discovery did not report the created index.");
        }

        ValidateGenericInsert(index.Insert(10, 1000), "catalog normal insert");

        index.Batch.Enable(new LibraDexWriteIntent(
            LibraDexWriteOrder.Sorted,
            LibraDexWriteVolume.Thousands,
            LibraDexWriteLocality.Clustered,
            LibraDexWritePriority.WriteSpeed));
        if (!index.Batch.IsEnabled)
        {
            throw new InvalidDataException("Batch did not report enabled after Enable.");
        }

        ValidateGenericInsert(index.Insert(11, 1100), "catalog batch insert 11");
        ValidateGenericInsert(index.Insert(12, 1200), "catalog batch insert 12");
        LibraDexGenericBatchCommitResult firstCommit = index.Batch.Commit();
        if (!index.Batch.IsEnabled || firstCommit.InsertedCount != 2 || firstCommit.DeferredCommitRequests == 0)
        {
            throw new InvalidDataException("Batch.Commit did not publish two inserts and remain enabled.");
        }

        ValidateGenericInsert(index.Insert(13, 1300), "catalog batch insert 13");
        LibraDexGenericBatchCommitResult finalCommit = index.Batch.CommitAndDisable();
        if (index.Batch.IsEnabled || finalCommit.InsertedCount != 1 || finalCommit.DeferredCommitRequests == 0)
        {
            throw new InvalidDataException("Batch.CommitAndDisable did not publish one insert and disable batching.");
        }

        long[] identities = new long[8];
        LibraDexGenericRangeReadResult read = index.ReadRange(10, 13, identities);
        ValidateGenericRead(read, identities, new long[] { 1000, 1100, 1200, 1300 }, "catalog read");
        using LibraDexRangeReader<long, long> reader = index.OpenRangeReader(10, 13);
        ValidateGenericLongReader(reader, new long[] { 1000, 1100, 1200, 1300 }, "catalog reader");

        index.Close();

        using Catalog catalogWithDisposeCommit = Catalog.CreateMemory();
        LibraDexIndex<long, long> disposeCommitIndex = catalogWithDisposeCommit.Indexes.Scalar.Scalar.Create<long, long>(
            "dispose-commit");
        disposeCommitIndex.Batch.Enable();
        ValidateGenericInsert(disposeCommitIndex.Insert(21, 2100), "catalog dispose commit insert");
        disposeCommitIndex.Close();

        using (Catalog distinctScopeCatalog = Catalog.CreateMemory())
        {
            LibraDexIndex<int, long> duplicateIndex = distinctScopeCatalog.Indexes["scope"]["dups"].Create<int, long>(
                keys: IndexKeys.NonUnique);
            ValidateGenericInsert(duplicateIndex.Insert(1, 100), "distinct scope insert 1/100");
            ValidateGenericInsert(duplicateIndex.Insert(1, 101), "distinct scope insert 1/101");
            ValidateGenericInsert(duplicateIndex.Insert(2, 200), "distinct scope insert 2/200");
            ValidateGenericInsert(duplicateIndex.Insert(2, 201), "distinct scope insert 2/201");
            ValidateGenericInsert(duplicateIndex.Insert(3, 300), "distinct scope insert 3/300");
            Func<string, IIndex> duplicateResolver = indexName => string.Equals(indexName, "dups", StringComparison.Ordinal)
                ? duplicateIndex
                : throw new KeyNotFoundException(indexName);
            LibraDexConditionEndCondition duplicateRangeCondition = LibraDexCondition
                .ForGroup("scope")
                .Index("dups").AsInt32.Between(1, 2)
                .EndCondition;
            LibraDexConditionEndCondition duplicateMembershipCondition = LibraDexCondition
                .ForGroup("scope")
                .Index("dups").AsInt32.InSet(new[] { 1, 2 })
                .EndCondition;
            LibraDexConditionEndCondition duplicateNotFindCondition = LibraDexCondition
                .ForGroup("scope")
                .Index("dups").AsInt32.NotEqualTo(1)
                .EndCondition;
            IReadOnlyList<long> duplicateRangeIds = duplicateRangeCondition.ToList<long>(duplicateResolver, deduplication: IdentityDeduplication.Preserve);
            IReadOnlyList<long> pagedRangeIds = duplicateRangeCondition.ToList<long>(
                duplicateResolver,
                deduplication: IdentityDeduplication.Preserve,
                skip: 2,
                take: 1);
            IReadOnlyList<long> duplicateMembershipIds = duplicateMembershipCondition.ToList<long>(duplicateResolver, deduplication: IdentityDeduplication.Preserve);
            IReadOnlyList<long> notFindIds = duplicateNotFindCondition.ToList<long>(duplicateResolver, deduplication: IdentityDeduplication.Preserve);
            if (duplicateRangeIds.Count != 4 ||
                duplicateRangeIds[0] != 100 ||
                duplicateRangeIds[3] != 201 ||
                pagedRangeIds.Count != 1 ||
                pagedRangeIds[0] != 200 ||
                duplicateMembershipIds.Count != 4 ||
                duplicateMembershipIds[0] != 100 ||
                duplicateMembershipIds[3] != 201 ||
                notFindIds.Count != 3 ||
                notFindIds[0] != 200 ||
                notFindIds[1] != 201 ||
                notFindIds[2] != 300 ||
                duplicateRangeCondition.Count(duplicateResolver, IdentityDeduplication.Preserve) != 4 ||
                duplicateRangeCondition.Count(duplicateResolver, IdentityDeduplication.Distinct) != 4 ||
                duplicateMembershipCondition.Count(duplicateResolver, IdentityDeduplication.Preserve) != 4)
            {
                throw new InvalidDataException("Condition-builder duplicate-key retrieval did not return expected identities.");
            }

            try
            {
                _ = duplicateRangeCondition.ToList<long>(duplicateResolver, bookmark: new LibraDexBookmark(0, -1));
                throw new InvalidDataException("Condition range retrieval accepted a negative bookmark position.");
            }
            catch (ArgumentOutOfRangeException)
            {
            }

            LibraDexConditionEndCondition duplicateAllCondition = LibraDexCondition
                .ForGroup("scope")
                .Index("dups").AsInt32.Between(1, 3)
                .EndCondition;
            LibraDexConditionGroupQuery<int, long> duplicateGroups = duplicateAllCondition.Groups(duplicateResolver).By(duplicateIndex);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> duplicateGroupMetadata = duplicateGroups.Metadata(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroup<int, long>> duplicateGroupList = duplicateGroups.ToList(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyDictionary<int, long> duplicateGroupCounts = duplicateGroups.Counts(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyDictionary<int, long> duplicateFirstRepresentatives = duplicateGroups.FirstIdentities(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyDictionary<int, long> duplicateLastRepresentatives = duplicateGroups.LastIdentities(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> duplicateOnlyMetadata = duplicateGroups.Duplicates().Metadata(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> singletonMetadata = duplicateGroups.Singletons().Metadata(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> atMostTwoMetadata = duplicateGroups.WhereCountAtMost(2).Metadata(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> descendingGroupMetadata = duplicateGroups
                .OrderBy(LibraDexGroupOrder.KeyDescending)
                .Metadata(IdentityResultOrdering.PlanNatural, IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> countDescendingMetadata = duplicateGroups
                .OrderBy(LibraDexGroupOrder.CountDescending)
                .Metadata(IdentityResultOrdering.PlanNatural, IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroup<int, long>> descendingItemsGroups = duplicateGroups
                .OrderItemsBy(QueryDirection.Descending)
                .ToList(IdentityResultOrdering.PlanNatural, IdentityDeduplication.Preserve);
            IReadOnlyList<LibraDexGroupMetadata<int, long>> topDuplicateMetadata = duplicateGroups
                .TopDuplicates(1)
                .Metadata(IdentityResultOrdering.PlanNatural, IdentityDeduplication.Preserve);
            LibraDexGroup<int, long>? firstDuplicateGroup = duplicateGroups.FirstGroup(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            LibraDexGroup<int, long>? lastDuplicateGroup = duplicateGroups.LastGroup(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            LibraDexGroupMetadata<int, long>? firstDuplicateMetadata = duplicateGroups.FirstMetadata(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            LibraDexGroupMetadata<int, long>? lastDuplicateMetadata = duplicateGroups.LastMetadata(
                IdentityResultOrdering.PlanNatural,
                IdentityDeduplication.Preserve);
            if (duplicateGroupMetadata.Count != 3 ||
                duplicateGroupMetadata[0].Key != 1 ||
                duplicateGroupMetadata[0].Count != 2 ||
                duplicateGroupMetadata[0].FirstIdentity != 100 ||
                duplicateGroupMetadata[0].LastIdentity != 101 ||
                duplicateGroupList.Count != 3 ||
                duplicateGroupList[0].Key != 1 ||
                duplicateGroupList[0].Items.Count != 2 ||
                duplicateGroupCounts[1] != 2 ||
                duplicateGroupCounts[2] != 2 ||
                duplicateGroupCounts[3] != 1 ||
                duplicateFirstRepresentatives[1] != 100 ||
                duplicateLastRepresentatives[1] != 101 ||
                duplicateFirstRepresentatives[2] != 200 ||
                duplicateLastRepresentatives[2] != 201 ||
                duplicateOnlyMetadata.Count != 2 ||
                singletonMetadata.Count != 1 ||
                singletonMetadata[0].Key != 3 ||
                singletonMetadata[0].FirstIdentity != 300 ||
                atMostTwoMetadata.Count != 3 ||
                descendingGroupMetadata.Count != 3 ||
                descendingGroupMetadata[0].Key != 3 ||
                descendingGroupMetadata[2].Key != 1 ||
                countDescendingMetadata.Count != 3 ||
                countDescendingMetadata[0].Count != 2 ||
                countDescendingMetadata[2].Count != 1 ||
                descendingItemsGroups[0].Items[0] != 101 ||
                descendingItemsGroups[0].Items[1] != 100 ||
                topDuplicateMetadata.Count != 1 ||
                topDuplicateMetadata[0].Count != 2 ||
                firstDuplicateGroup is null ||
                firstDuplicateGroup.Key != 1 ||
                firstDuplicateGroup.Count != 2 ||
                firstDuplicateGroup.Items[0] != 100 ||
                firstDuplicateGroup.Items[1] != 101 ||
                lastDuplicateGroup is null ||
                lastDuplicateGroup.Key != 3 ||
                lastDuplicateGroup.Items[0] != 300 ||
                firstDuplicateMetadata is null ||
                firstDuplicateMetadata.Value.Key != 1 ||
                firstDuplicateMetadata.Value.FirstIdentity != 100 ||
                lastDuplicateMetadata is null ||
                lastDuplicateMetadata.Value.Key != 3 ||
                lastDuplicateMetadata.Value.LastIdentity != 300)
            {
                throw new InvalidDataException("Condition grouping did not preserve duplicate-key group metadata or representatives.");
            }
        }

        using (Catalog fileCatalog = Catalog.Create(path))
        {
            _ = fileCatalog.Indexes.Scalar.Scalar.Create<long, long>(
                "file-primary",
                keys: IndexKeys.Unique);
            LibraDexIndex<int, long> age = fileCatalog.Indexes["people"]["age"].Scalar.Scalar<int, long>().Create(
                keys: IndexKeys.NonUnique);
            ValidateGenericInsert(age.Insert(42, 4200), "grouped age insert");
            LibraDexIndex<int, long> gender = fileCatalog.Indexes["people"]["gender"].Create<int, long>(
                keys: IndexKeys.NonUnique);
            LibraDexIndexShapeSpec scoreShape = fileCatalog.Indexes["people"]["score"].Shape.Scalar<long, long>(
                keys: IndexKeys.NonUnique,
                sortOrder: LibraDexIndexSortOrder.Descending,
                directions: LibraDexProjectionDirectionSet.ForwardAndReversed);
            IIndex score = fileCatalog.Indexes.Create(scoreShape);
            _ = score.Insert(900L, 4200L);
            LibraDexIndex<int, long> status = fileCatalog.Indexes["people"]["status"].Create<int, long>(
                keys: IndexKeys.NonUnique);
            ValidateGenericInsert(status.Insert(7, 9900), "grouped status insert for identity-universe complement");
            using LibraDexStringScalar8Index displayName = fileCatalog.Indexes["people"]["displayName"].String.Create(
                stringKeys: StringKeys.ExactFoldedAndSortKey,
                directions: LibraDexProjectionDirectionSet.ForwardAndReversed,
                sortKeyCulture: "en-US");
            ValidateGenericInsert(displayName.Insert("Eric", 501UL), "grouped displayName insert Eric");
            ValidateGenericInsert(displayName.Insert("erin", 502UL), "grouped displayName insert erin");
            ValidateGenericInsert(displayName.Insert("Alice", 503UL), "grouped displayName insert Alice");
            using LibraDexStringScalar8Index policyName = fileCatalog.Indexes["people"]["policyName"].String.Create(
                stringKeys: StringKeys.Exact,
                stringComparisonPolicy: LibraDexStringComparisonPolicy.Custom(StringComparer.OrdinalIgnoreCase));
            ValidateGenericInsert(policyName.Insert("Casey", 901UL), "grouped policyName insert Casey");
            using LibraDexStringScalar8Index persistedPolicyName = fileCatalog.Indexes["people"]["persistedPolicyName"].String.Create(
                stringKeys: StringKeys.Exact,
                stringComparisonPolicy: LibraDexStringComparisonPolicy.OrdinalIgnoreCase);
            ValidateGenericInsert(persistedPolicyName.Insert("Jordan", 902UL), "grouped persistedPolicyName insert Jordan");
            using LibraDexStringScalar8Index exactSuffixName = fileCatalog.Indexes["people"]["exactSuffixName"].String.Create(
                stringKeys: StringKeys.Exact,
                directions: LibraDexProjectionDirectionSet.ForwardAndReversed);
            ValidateGenericInsert(exactSuffixName.Insert("Topic", 903UL), "grouped exactSuffixName insert Topic");
            IIndex tenantUserCompositeMetadata = fileCatalog.Indexes["people"]["tenantUser"].Composite<long>(
                C.Guid("tenantId"),
                C.Text("username", StringKeys.ExactFoldedAndSortKey))
                .Create(C.Unique);
            if (tenantUserCompositeMetadata.LogicalShape is null ||
                tenantUserCompositeMetadata.LogicalShape.KeyFamily != CatalogIndexKeyFamily.Composite ||
                tenantUserCompositeMetadata.LogicalShape.CompositeParts.Count != 2)
            {
                throw new InvalidDataException("Composite create did not expose logical shape metadata.");
            }
            Guid persistedTenant = Guid.Parse("cccccccc-cccc-cccc-cccc-cccccccccccc");
            ValidateGenericInsert(tenantUserCompositeMetadata.Insert(Key.Of(persistedTenant, "Cora"), 7301L), "persisted routed composite tenant/Cora insert");
            ValidateGenericInsert(tenantUserCompositeMetadata.Insert(Key.Of(persistedTenant, "Cole"), 7302L), "persisted routed composite tenant/Cole insert");

            CatalogIdentityGroupBatchManager peopleBatch = fileCatalog.Indexes["people"].Batch;
            peopleBatch.Enable(new LibraDexWriteIntent(
                LibraDexWriteOrder.Sorted,
