            if (ids.Count != 2 ||
                ids[0] != 7302L ||
                ids[1] != 7301L)
            {
                throw new InvalidDataException($"Composite condition delete did not survive second catalog reopen. ids={string.Join(",", ids)}");
            }
        }

        using (Catalog mismatchCatalog = Catalog.CreateMemory())
        {
