            LibraDexIndex<int, long> ordersTotal = mismatchCatalog.Indexes["orders"]["total"].Create<int, long>();
            try
            {
                _ = LibraDexCondition
                    .ForGroup("people")
                    .Index("age").AsInt32.EqualTo(1)
                    .AND.Index("total").AsInt32.EqualTo(1)
