        ValidateGenericInsert(peoplePolicyAlias.Insert("Alice", 702UL), "policy alias string insert Alice");
        if (peopleAge.Group != "people" ||
            peopleAge.Name != "age" ||
            peopleAge.KeyType != typeof(long) ||
