    private static FixedReaderPerfRow MeasureFixedReaderPerf<TKey, TIdentity>(
        LibraDexIndex<TKey, TIdentity> index,
        string shape,
        TKey lowerKey,
        TKey upperKey,
        TIdentity[] materializedIdentities,
        int rangeCount,
        int iterations,
        int repeatCount)
    {
        FixedReaderPerfSample[] samples = new FixedReaderPerfSample[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureFixedReaderPerfSample(index, lowerKey, upperKey, materializedIdentities, rangeCount, iterations);
        }

        FixedReaderPerfSample sample = SelectMedianFixedReaderPerfSample(samples);
        return new FixedReaderPerfRow(
            shape,
            rangeCount,
            iterations,
            repeatCount,
            sample.MaterializedNsPerIdentity,
            sample.CursorIdentityNsPerIdentity,
            sample.CursorKeyNsPerIdentity,
            sample.CursorTupleNsPerIdentity,
            sample.CountNsPerCall,
            sample.SkipNsPerIdentity,
            sample.Checksum);
    }

    private static FixedReaderPerfSample MeasureFixedReaderPerfSample<TKey, TIdentity>(
        LibraDexIndex<TKey, TIdentity> index,
        TKey lowerKey,
        TKey upperKey,
        TIdentity[] materializedIdentities,
        int rangeCount,
        int iterations)
    {
        long checksum = 0;
        long totalIdentities = (long)rangeCount * iterations;

        Stopwatch materializedWatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            LibraDexGenericRangeReadResult read = index.ReadRange(lowerKey, upperKey, materializedIdentities);
            if (read.IdentityCount != rangeCount)
            {
                throw new InvalidDataException($"Fixed reader perf materialized read returned {read.IdentityCount} identities; expected {rangeCount}.");
            }

            for (int j = 0; j < read.IdentityCount; j++)
            {
                checksum += HashFixedReaderValue(materializedIdentities[j]);
            }
        }

        materializedWatch.Stop();

        Stopwatch identityWatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            using LibraDexRangeReader<TKey, TIdentity> reader = index.OpenRangeReader(lowerKey, upperKey);
            int count = 0;
            while (reader.TryReadNextIdentity(out TIdentity identity))
            {
                checksum += HashFixedReaderValue(identity);
                count++;
            }

            if (count != rangeCount)
            {
                throw new InvalidDataException($"Fixed reader perf identity cursor returned {count} identities; expected {rangeCount}.");
            }
        }

        identityWatch.Stop();

        Stopwatch keyWatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            using LibraDexRangeReader<TKey, TIdentity> reader = index.OpenRangeReader(lowerKey, upperKey);
            int count = 0;
            while (reader.TryReadNextKey(out TKey key))
            {
                checksum += HashFixedReaderValue(key);
                count++;
            }

            if (count != rangeCount)
            {
                throw new InvalidDataException($"Fixed reader perf key cursor returned {count} keys; expected {rangeCount}.");
            }
        }

        keyWatch.Stop();

        Stopwatch tupleWatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            using LibraDexRangeReader<TKey, TIdentity> reader = index.OpenRangeReader(lowerKey, upperKey);
            int count = 0;
            while (reader.TryReadNext(out TKey key, out TIdentity identity))
            {
                checksum += HashFixedReaderValue(key);
                checksum += HashFixedReaderValue(identity);
                count++;
            }

            if (count != rangeCount)
            {
                throw new InvalidDataException($"Fixed reader perf tuple cursor returned {count} tuples; expected {rangeCount}.");
            }
        }

        tupleWatch.Stop();

        Stopwatch countWatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            using LibraDexRangeReader<TKey, TIdentity> reader = index.OpenRangeReader(lowerKey, upperKey);
            int count = reader.Count;
            if (count != rangeCount)
            {
                throw new InvalidDataException($"Fixed reader perf count cursor returned {count}; expected {rangeCount}.");
            }

            checksum += count;
        }

        countWatch.Stop();

        Stopwatch skipWatch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            using LibraDexRangeReader<TKey, TIdentity> reader = index.OpenRangeReader(lowerKey, upperKey);
            int skipped = 0;
            while (skipped < rangeCount)
            {
                int current = reader.Skip(Math.Min(16, rangeCount - skipped));
                if (current == 0)
                {
                    break;
                }

                skipped += current;
            }

            if (skipped != rangeCount)
            {
                throw new InvalidDataException($"Fixed reader perf skip cursor skipped {skipped}; expected {rangeCount}.");
            }

            checksum += skipped;
        }

        skipWatch.Stop();

        double materializedNs = ElapsedNsPerIdentity(materializedWatch.ElapsedTicks, totalIdentities);
        double identityNs = ElapsedNsPerIdentity(identityWatch.ElapsedTicks, totalIdentities);
        double keyNs = ElapsedNsPerIdentity(keyWatch.ElapsedTicks, totalIdentities);
        double tupleNs = ElapsedNsPerIdentity(tupleWatch.ElapsedTicks, totalIdentities);
        double countNs = ElapsedNsPerCall(countWatch.ElapsedTicks, iterations);
        double skipNs = ElapsedNsPerIdentity(skipWatch.ElapsedTicks, totalIdentities);
        return new FixedReaderPerfSample(materializedNs, identityNs, keyNs, tupleNs, countNs, skipNs, checksum);
    }

    private static FixedReaderPerfSample SelectMedianFixedReaderPerfSample(ReadOnlySpan<FixedReaderPerfSample> samples)
    {
        FixedReaderPerfSample[] sorted = samples.ToArray();
        Array.Sort(sorted, static (left, right) => left.CursorIdentityNsPerIdentity.CompareTo(right.CursorIdentityNsPerIdentity));
        return sorted[sorted.Length / 2];
    }

    private static byte[][] CreateFixedReaderByteKeys(int itemCount, int width)
    {
        byte[][] keys = new byte[itemCount][];
        int prefixStride = Math.Max(1, itemCount / 16);
        for (int i = 0; i < itemCount; i++)
        {
            byte[] key = new byte[width];
            key[0] = (byte)Math.Min(255, i / prefixStride);
            BinaryPrimitives.WriteUInt64BigEndian(key.AsSpan(width - sizeof(ulong), sizeof(ulong)), (ulong)i);
            keys[i] = key;
        }

        return keys;
    }

    private static Guid CreateFixedReaderGuid(int value)
    {
        Span<byte> bytes = stackalloc byte[16];
        BinaryPrimitives.WriteInt32BigEndian(bytes.Slice(12, sizeof(int)), value);
        return new Guid(bytes);
    }

    private static long HashFixedReaderValue<T>(T value)
    {
        if (value is byte[] bytes)
        {
            long hash = bytes.Length;
            for (int i = 0; i < bytes.Length; i += 8)
            {
                hash = unchecked((hash * 397) ^ bytes[i]);
            }

            return hash;
        }

        return value?.GetHashCode() ?? 0;
    }

    private static double ElapsedNsPerIdentity(long elapsedTicks, long identityCount)
    {
        return elapsedTicks * 1_000_000_000d / Stopwatch.Frequency / Math.Max(identityCount, 1);
    }

    private static double ElapsedNsPerCall(long elapsedTicks, int callCount)
    {
        return elapsedTicks * 1_000_000_000d / Stopwatch.Frequency / Math.Max(callCount, 1);
    }

    private static void PrintFixedReaderPerfRows(IReadOnlyList<FixedReaderPerfRow> rows)
    {
        Console.WriteLine("shape | range | materialized ns/id | cursor id ns/id | cursor key ns/id | cursor tuple ns/id | count ns/call | skip ns/id");
        for (int i = 0; i < rows.Count; i++)
        {
            FixedReaderPerfRow row = rows[i];
            Console.WriteLine(FormattableString.Invariant($"{row.Shape} | {row.RangeCount} | {row.MaterializedNsPerIdentity:F2} | {row.CursorIdentityNsPerIdentity:F2} | {row.CursorKeyNsPerIdentity:F2} | {row.CursorTupleNsPerIdentity:F2} | {row.CountNsPerCall:F2} | {row.SkipNsPerIdentity:F2}"));
        }
    }

    private static string WriteFixedReaderPerfReport(string directory, int itemCount, int startIndex, int rangeCount, int iterations, int repeatCount, IReadOnlyList<FixedReaderPerfRow> rows)
    {
        string artifactDirectory = Path.Combine(directory, "artifacts");
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "fixed-reader-perf-current.md");
        StringBuilder builder = new();
        builder.AppendLine("# Fixed Reader Perf");
        builder.AppendLine();
        builder.AppendLine($"- Items: `{itemCount}`");
        builder.AppendLine($"- Range start: `{startIndex}`");
        builder.AppendLine($"- Range count: `{rangeCount}`");
        builder.AppendLine($"- Iterations: `{iterations}`");
        builder.AppendLine($"- Repeat count: `{repeatCount}`");
        builder.AppendLine();
        builder.AppendLine("| Shape | Range | Materialized ns/id | Cursor identity ns/id | Cursor key ns/id | Cursor tuple ns/id | Count ns/call | Skip ns/id |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Count; i++)
        {
            FixedReaderPerfRow row = rows[i];
            builder.AppendLine(FormattableString.Invariant($"| {row.Shape} | {row.RangeCount} | {row.MaterializedNsPerIdentity:F2} | {row.CursorIdentityNsPerIdentity:F2} | {row.CursorKeyNsPerIdentity:F2} | {row.CursorTupleNsPerIdentity:F2} | {row.CountNsPerCall:F2} | {row.SkipNsPerIdentity:F2} |"));
        }

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    private readonly record struct FixedReaderPerfSample(
        double MaterializedNsPerIdentity,
        double CursorIdentityNsPerIdentity,
        double CursorKeyNsPerIdentity,
        double CursorTupleNsPerIdentity,
        double CountNsPerCall,
        double SkipNsPerIdentity,
        long Checksum);

    private readonly record struct FixedReaderPerfRow(
        string Shape,
        int RangeCount,
        int Iterations,
        int RepeatCount,
        double MaterializedNsPerIdentity,
        double CursorIdentityNsPerIdentity,
        double CursorKeyNsPerIdentity,
        double CursorTupleNsPerIdentity,
        double CountNsPerCall,
        double SkipNsPerIdentity,
        long Checksum);

    /// <summary>
    /// Compares public varlen-identity cursor streaming against disconnected identity-buffer reads for `SV8`, `SV16`, and `VV`.<br/>
    /// The benchmark isolates the new public buffer-manager DX from SQLite and write-path variables by creating each shape once, reopening through the public API, and timing repeated reads of the same range.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the buffer comparison completes and writes a compact report.</returns>
    private static int RunVarIdentityBufferPerf(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VarIdentityBufferPerf"));
        int itemCount = GetIntOption(args, "--items", 8192);
        int prefixCount = GetIntOption(args, "--prefix-count", 64);
        int rangePrefixCount = GetIntOption(args, "--range-prefix-count", 8);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        int iterations = GetIntOption(args, "--iterations", 200);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        if (itemCount <= 0 || prefixCount <= 0 || prefixCount > 256 || rangePrefixCount <= 0 || rangePrefixCount > prefixCount ||
            keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "var-identity-buffer-perf requires positive item/read parameters, prefix counts within 1-256, and key/identity lengths within 1-1024.");
        }

        Directory.CreateDirectory(directory);
        DataKernelOptions options = CreateDesignPerfOptions();
        List<VarIdentityBufferPerfRow> rows = [];
        rows.Add(MeasureVarIdentityBufferPerfSv8(Path.Combine(directory, "var-identity-buffer-sv8.lbdx"), options, itemCount, prefixCount, rangePrefixCount, identityLength, iterations, repeatCount));
        rows.Add(MeasureVarIdentityBufferPerfSv16(Path.Combine(directory, "var-identity-buffer-sv16.lbdx"), options, itemCount, prefixCount, rangePrefixCount, identityLength, iterations, repeatCount));
        rows.Add(MeasureVarIdentityBufferPerfVv(Path.Combine(directory, "var-identity-buffer-vv.lbdx"), options, itemCount, prefixCount, rangePrefixCount, keyLength, identityLength, iterations, repeatCount));

        string reportPath = WriteVarIdentityBufferPerfReport(directory, itemCount, prefixCount, rangePrefixCount, keyLength, identityLength, iterations, repeatCount, rows);
        Console.WriteLine("var identity buffer perf");
        Console.WriteLine($"directory {directory}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"rangePrefixCount {rangePrefixCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"identityLength {identityLength}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"repeatCount {repeatCount}");
        PrintVarIdentityBufferPerfRows(rows);
        Console.WriteLine($"report {reportPath}");
        Console.WriteLine("var-identity-buffer-perf ok");
        return 0;
    }

    private static VarIdentityBufferPerfRow MeasureVarIdentityBufferPerfSv8(string path, DataKernelOptions options, int itemCount, int prefixCount, int rangePrefixCount, int identityLength, int iterations, int repeatCount)
    {
        File.Delete(path);
        using (Scalar8VarIdentityIndex index = Indexes.SV8.Create(
            path,
            name: "sv8-buffer-perf",
            maxIdentityLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9301),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using Scalar8VarIdentityBatch batch = index.BeginBatch(new LibraDexWriteIntent(Volume: LibraDexWriteVolume.Thousands, Locality: LibraDexWriteLocality.Broad, Priority: LibraDexWritePriority.WriteSpeed));
            for (int i = 0; i < itemCount; i++)
            {
                _ = batch.Insert(CreateScalar8VarIdentityKey(i, prefixCount), CreateScalar8VarIdentity(i, identityLength));
            }

            _ = batch.Commit();
        }

        using Scalar8VarIdentityIndex opened = Indexes.SV8.Open(path, 0, 1024, options, DataKernelTelemetryOptions.EnabledOptions);
        ulong lower = CreateScalar8VarIdentityKey(0, prefixCount);
        ulong upper = CreateScalar8VarIdentityKey(rangePrefixCount - 1, prefixCount);
        int expected = CountScalar8VarIdentityKeyRange(itemCount, prefixCount, 0, rangePrefixCount - 1);
        VarIdentityBufferPerfSample[] samples = new VarIdentityBufferPerfSample[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureVarIdentityBufferPerfSample(
                "SV8",
                expected,
                iterations,
                () => opened.OpenRangeReader(lower, upper),
                () => opened.ReadIdentityBuffer(lower, upper, expected * identityLength));
        }

        return CreateVarIdentityBufferPerfRow("SV8", expected, SelectMedianVarIdentityBufferPerfSample(samples));
    }

