    /// <summary>
    /// Validates one generic insert result and fails with a scenario-specific message.<br/>
    /// This keeps the generic API sanity command compact while still checking first-route creation and successful insertion.<br/>
    /// </summary>
    /// <param name="result">The generic insert result.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    private static void ValidateGenericInsert(LibraDexGenericInsertResult result, string scenario)
    {
        if (!result.Inserted)
        {
            throw new InvalidDataException($"Generic API sanity failed to insert during {scenario}.");
        }
    }

    private static byte[] CreateTypedBinaryKey(int number, DateTime dateTime, string text)
    {
        if (Encoding.UTF8.GetByteCount(text) != 4)
        {
            throw new ArgumentException("Typed binary harness keys require exactly four UTF-8 bytes.", nameof(text));
        }

        byte[] key = new byte[16];
        BinaryPrimitives.WriteInt32LittleEndian(key.AsSpan(0, 4), number);
        BinaryPrimitives.WriteInt64LittleEndian(key.AsSpan(4, 8), dateTime.Ticks);
        _ = Encoding.UTF8.GetBytes(text, key.AsSpan(12, 4));
        return key;
    }

    private static byte[] CreateDecimalBinaryKey(decimal value)
    {
        byte[] key = new byte[16];
        decimal local = value;
        System.Runtime.InteropServices.MemoryMarshal.Write(key, in local);
        return key;
    }

    private static byte[] CreateInt128BinaryKey(Int128 value)
    {
        byte[] key = new byte[16];
        Int128 local = value;
        System.Runtime.InteropServices.MemoryMarshal.Write(key, in local);
        return key;
    }

    private static byte[] CreateUInt128BinaryKey(UInt128 value)
    {
        byte[] key = new byte[16];
        UInt128 local = value;
        System.Runtime.InteropServices.MemoryMarshal.Write(key, in local);
        return key;
    }

    private static byte[] CreateDateTimeOffsetBinaryKey(DateTimeOffset value)
    {
        byte[] key = new byte[16];
        BinaryPrimitives.WriteInt64LittleEndian(key.AsSpan(0, 8), value.Ticks);
        BinaryPrimitives.WriteInt64LittleEndian(key.AsSpan(8, 8), value.Offset.Ticks);
        return key;
    }

    private static byte[] CreateMixedDateTimeBinaryKey(DateOnly date, TimeOnly time, string ascii)
    {
        if (Encoding.ASCII.GetByteCount(ascii) != 4)
        {
            throw new ArgumentException("Mixed binary harness keys require exactly four ASCII bytes.", nameof(ascii));
        }

        byte[] key = new byte[16];
        BinaryPrimitives.WriteInt32LittleEndian(key.AsSpan(0, 4), date.DayNumber);
        BinaryPrimitives.WriteInt64LittleEndian(key.AsSpan(4, 8), time.Ticks);
        _ = Encoding.ASCII.GetBytes(ascii, key.AsSpan(12, 4));
        return key;
    }

    private static byte[] CreateEncodedTextBinaryKey()
    {
        byte[] key = new byte[16];
        _ = Encoding.Latin1.GetBytes("cafe", key.AsSpan(0, 4));
        _ = Encoding.Unicode.GetBytes("OK", key.AsSpan(4, 4));
        BinaryPrimitives.WriteInt32LittleEndian(key.AsSpan(8, 4), 'A');
        _ = Encoding.Unicode.GetBytes("Z", key.AsSpan(12, 2));
        return key;
    }

    private static byte[] CreateCustomEncodedTextBinaryKey(Encoding encoding, string text)
    {
        byte[] key = new byte[16];
        byte[] encoded = encoding.GetBytes(text);
        if (encoded.Length > key.Length)
        {
            throw new ArgumentException("Custom encoded text fixture must fit in the fixed 16-byte key.", nameof(text));
        }

        encoded.CopyTo(key.AsSpan());
        return key;
    }

    private static byte[] CreateFloatingBinaryKey(float single, double value)
    {
        byte[] key = new byte[16];
        BinaryPrimitives.WriteInt32LittleEndian(key.AsSpan(0, 4), BitConverter.SingleToInt32Bits(single));
        BinaryPrimitives.WriteInt64LittleEndian(key.AsSpan(4, 8), BitConverter.DoubleToInt64Bits(value));
        return key;
    }

    /// <summary>
    /// Validates one generic read result against an expected identity sequence.<br/>
    /// The helper keeps the first generic read slice focused on public API semantics instead of benchmark reporting.<br/>
    /// </summary>
    /// <param name="result">The generic range-read result.</param>
    /// <param name="actual">The caller-owned destination buffer populated by the read.</param>
    /// <param name="expected">The expected identity sequence.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    private static void ValidateGenericRead(LibraDexGenericRangeReadResult result, ReadOnlySpan<long> actual, ReadOnlySpan<long> expected, string scenario)
    {
        if (result.IdentityCount != expected.Length)
        {
            throw new InvalidDataException($"Generic API sanity read returned {result.IdentityCount} identities during {scenario}; expected {expected.Length}.");
        }

        for (int i = 0; i < expected.Length; i++)
        {
            if (actual[i] != expected[i])
            {
                throw new InvalidDataException($"Generic API sanity read returned identity {actual[i]} at position {i} during {scenario}; expected {expected[i]}.");
            }
        }
    }

    /// <summary>
    /// Validates one generic `Guid` read result against an expected identity sequence.<br/>
    /// This covers widened identity decode paths while keeping failure messages tied to public API behavior.<br/>
    /// </summary>
    /// <param name="result">The generic range-read result.</param>
    /// <param name="actual">The caller-owned destination buffer populated by the read.</param>
    /// <param name="expected">The expected identity sequence.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    private static void ValidateGenericGuidRead(LibraDexGenericRangeReadResult result, ReadOnlySpan<Guid> actual, ReadOnlySpan<Guid> expected, string scenario)
    {
        if (result.IdentityCount != expected.Length)
        {
            throw new InvalidDataException($"Generic API sanity read returned {result.IdentityCount} Guid identities during {scenario}; expected {expected.Length}.");
        }

        for (int i = 0; i < expected.Length; i++)
        {
            if (actual[i] != expected[i])
            {
                throw new InvalidDataException($"Generic API sanity read returned Guid identity {actual[i]} at position {i} during {scenario}; expected {expected[i]}.");
            }
        }
    }

    /// <summary>
    /// Validates one generic `byte[]` read result against an expected identity sequence.<br/>
    /// The helper compares byte-array identities structurally because public decoding returns new arrays.<br/>
    /// </summary>
    /// <param name="result">The generic range-read result.</param>
    /// <param name="actual">The caller-owned destination buffer populated by the read.</param>
    /// <param name="expected">The expected identity sequence.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    private static void ValidateGenericByteArrayRead(LibraDexGenericRangeReadResult result, ReadOnlySpan<byte[]> actual, ReadOnlySpan<byte[]> expected, string scenario)
    {
        if (result.IdentityCount != expected.Length)
        {
            throw new InvalidDataException($"Generic API sanity read returned {result.IdentityCount} byte-array identities during {scenario}; expected {expected.Length}.");
        }

        for (int i = 0; i < expected.Length; i++)
        {
            if (actual[i] is null || !actual[i].AsSpan().SequenceEqual(expected[i]))
            {
                throw new InvalidDataException($"Generic API sanity read returned a mismatched byte-array identity at position {i} during {scenario}.");
            }
        }
    }

    /// <summary>
    /// Validates one generic cursor reader against an expected `long` identity sequence.<br/>
    /// The helper checks non-materialized count, forward iteration, optional shelf-range skip behavior, and end-of-reader handling.<br/>
    /// </summary>
    /// <typeparam name="TKey">The public key type of the reader under test.</typeparam>
    /// <param name="reader">The generic range reader to validate.</param>
    /// <param name="expected">The expected identity sequence.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    /// <param name="skipAfterFirst">Whether to validate `Skip(1)` after the first row instead of moving to the second row normally.</param>
    private static void ValidateGenericLongReader<TKey>(LibraDexRangeReader<TKey, long> reader, ReadOnlySpan<long> expected, string scenario, bool skipAfterFirst = false)
    {
        if (reader.Count != expected.Length)
        {
            throw new InvalidDataException($"Generic API sanity reader returned count {reader.Count} during {scenario}; expected {expected.Length}.");
        }

        int i = 0;
        while (i < expected.Length)
        {
            if (!reader.MoveNext())
            {
                throw new InvalidDataException($"Generic API sanity reader ended early at position {i} during {scenario}.");
            }

            if (reader.CurrentIdentity != expected[i])
            {
                throw new InvalidDataException($"Generic API sanity reader returned identity {reader.CurrentIdentity} at position {i} during {scenario}; expected {expected[i]}.");
            }

            if (skipAfterFirst && i == 0 && expected.Length > 1)
            {
                int skipped = reader.Skip(1);
                if (skipped != 1 || reader.CurrentIdentity != expected[1])
                {
                    throw new InvalidDataException($"Generic API sanity reader skip failed during {scenario}.");
                }

                i = 2;
                continue;
            }

            i++;
        }

        if (reader.MoveNext())
        {
            throw new InvalidDataException($"Generic API sanity reader returned extra rows during {scenario}.");
        }
    }

    /// <summary>
    /// Validates one generic cursor reader against an expected `Guid` identity sequence.<br/>
    /// The helper checks non-materialized count, forward iteration, and end-of-reader handling for widened identity shapes.<br/>
    /// </summary>
    /// <typeparam name="TKey">The public key type of the reader under test.</typeparam>
    /// <param name="reader">The generic range reader to validate.</param>
    /// <param name="expected">The expected identity sequence.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    private static void ValidateGenericGuidReader<TKey>(LibraDexRangeReader<TKey, Guid> reader, ReadOnlySpan<Guid> expected, string scenario)
    {
        if (reader.Count != expected.Length)
        {
            throw new InvalidDataException($"Generic API sanity reader returned count {reader.Count} during {scenario}; expected {expected.Length}.");
        }

        for (int i = 0; i < expected.Length; i++)
        {
            if (!reader.MoveNext())
            {
                throw new InvalidDataException($"Generic API sanity reader ended early at position {i} during {scenario}.");
            }

            if (reader.CurrentIdentity != expected[i])
            {
                throw new InvalidDataException($"Generic API sanity reader returned Guid identity {reader.CurrentIdentity} at position {i} during {scenario}; expected {expected[i]}.");
            }
        }

        if (reader.MoveNext())
        {
            throw new InvalidDataException($"Generic API sanity reader returned extra rows during {scenario}.");
        }
    }

    /// <summary>
    /// Validates one generic cursor reader against an expected byte-array identity sequence.<br/>
    /// The helper compares decoded identity arrays structurally because cursor decoding returns caller-owned materialized arrays for byte-array identities.<br/>
    /// </summary>
    /// <typeparam name="TKey">The public key type of the reader under test.</typeparam>
    /// <param name="reader">The generic range reader to validate.</param>
    /// <param name="expected">The expected identity sequence.</param>
    /// <param name="scenario">The scenario label to include in failures.</param>
    private static void ValidateGenericByteArrayReader<TKey>(LibraDexRangeReader<TKey, byte[]> reader, ReadOnlySpan<byte[]> expected, string scenario)
    {
        if (reader.Count != expected.Length)
        {
            throw new InvalidDataException($"Generic API sanity reader returned count {reader.Count} during {scenario}; expected {expected.Length}.");
        }

        for (int i = 0; i < expected.Length; i++)
        {
            if (!reader.MoveNext())
            {
                throw new InvalidDataException($"Generic API sanity reader ended early at position {i} during {scenario}.");
            }

            byte[] identity = reader.CurrentIdentity;
            if (identity is null || !identity.AsSpan().SequenceEqual(expected[i]))
            {
                throw new InvalidDataException($"Generic API sanity reader returned a mismatched byte-array identity at position {i} during {scenario}.");
            }
        }

        if (reader.MoveNext())
        {
            throw new InvalidDataException($"Generic API sanity reader returned extra rows during {scenario}.");
        }
    }

    /// <summary>
    /// Validates the first `SV8` scalar-key/variable-identity shelf primitive without routing.<br/>
    /// The command inserts scalar keys with raw byte identities, verifies key-primary tuple ordering, checks that identity ordering is active only inside duplicate-key runs, and validates key-range reads.<br/>
    /// This is the clone-first shelf proof before routed/session integration for the reverse varlen family.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the shelf primitive validates.</returns>
    private static int RunScalar8VarIdentityShelfSanity(string[] args)
    {
        int itemCount = GetIntOption(args, "--items", 1800);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 6);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        if (itemCount <= 0 || duplicateModulo <= 0 || identityLength < 16 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV8 shelf sanity requires positive items, duplicate modulo, and identity length 16-1024.");
        }

        Scalar8VarIdentityProfile profile = Scalar8VarIdentityProfile.DefaultInitial;
        byte[] shelfBytes = Scalar8VarIdentity.CreateEmpty(profile);
        for (int i = 0; i < itemCount; i++)
        {
            ulong key = CreateScalar8VarIdentityKey(i, duplicateModulo);
            byte[] identity = CreateScalar8VarIdentity(i, identityLength);
            Scalar8VarIdentityInsertResult result = Scalar8VarIdentity.Insert(shelfBytes, profile, key, identity, allowDuplicateKeys: true, out byte[] rewritten);
            if (result == Scalar8VarIdentityInsertResult.Full &&
                Scalar8VarIdentity.TryGrowAndInsert(shelfBytes, profile, key, identity, allowDuplicateKeys: true, out Scalar8VarIdentityProfile grownProfile, out rewritten, out result))
            {
                profile = grownProfile;
            }

            if (result != Scalar8VarIdentityInsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SV8 insert {i}, got {result} at profile {profile.ShelfExtentSize}.");
            }

            shelfBytes = rewritten;
        }

        Scalar8VarIdentityReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid || readOnly.ItemCount != itemCount)
        {
            throw new InvalidDataException($"SV8 shelf sanity produced invalid shelf or wrong count. valid={readOnly.IsValid} count={readOnly.ItemCount} expected={itemCount}.");
        }

        for (int i = 1; i < readOnly.ItemCount; i++)
        {
            ulong previousKey = readOnly.ReadKeyAt(i - 1);
            ulong currentKey = readOnly.ReadKeyAt(i);
            if (previousKey > currentKey)
            {
                throw new InvalidDataException($"SV8 key ordering drifted at slot {i}.");
            }

            if (previousKey == currentKey &&
                readOnly.ReadIdentityAt(i - 1).SequenceCompareTo(readOnly.ReadIdentityAt(i)) > 0)
            {
                throw new InvalidDataException($"SV8 duplicate-key identity ordering drifted at slot {i}.");
            }
        }

        int slotStreamLength = Scalar8VarIdentityLayout.ReadSlotStreamLength(shelfBytes);
        int slotCapacityBytes = Scalar8VarIdentityLayout.ReadSlotCapacityBytes(shelfBytes);
        int expectedSlotStreamLength = checked(readOnly.ItemCount * Scalar8VarIdentityLayout.SlotSize);
        int expectedSlotCapacityBytes = Scalar8VarIdentityLayout.CalculateSlotCapacityBytes(profile.ShelfExtentSize);
        int expectedFirstRecordOffset = Scalar8VarIdentityLayout.HeaderSize + slotCapacityBytes;
        int recordArenaEnd = Scalar8VarIdentityLayout.ReadRecordArenaEnd(shelfBytes);
        uint minRecordOffset = uint.MaxValue;
        uint maxRecordEnd = 0;
        for (int i = 0; i < readOnly.ItemCount; i++)
        {
            uint recordOffset = readOnly.ReadRecordOffsetAt(i);
            minRecordOffset = Math.Min(minRecordOffset, recordOffset);
            maxRecordEnd = Math.Max(maxRecordEnd, checked(recordOffset + (uint)Scalar8VarIdentityLayout.GetRecordLength(shelfBytes, checked((int)recordOffset))));
        }

        if (slotStreamLength != expectedSlotStreamLength ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            minRecordOffset != expectedFirstRecordOffset ||
            maxRecordEnd != recordArenaEnd)
        {
            throw new InvalidDataException($"SV8 shelf reserved-slot record layout failed. slots={slotStreamLength}/{expectedSlotStreamLength} slotCapacity={slotCapacityBytes}/{expectedSlotCapacityBytes} firstRecord={minRecordOffset}/{expectedFirstRecordOffset} arenaEnd={recordArenaEnd}/{maxRecordEnd}.");
        }

        ulong duplicateKey = CreateScalar8VarIdentityKey(0, duplicateModulo);
        byte[] duplicateIdentity = CreateScalar8VarIdentity(0, identityLength);
        Scalar8VarIdentityInsertResult duplicate = Scalar8VarIdentity.Insert(shelfBytes, profile, duplicateKey, duplicateIdentity, allowDuplicateKeys: true, out _);
        if (duplicate != Scalar8VarIdentityInsertResult.AlreadyPresent)
        {
            throw new InvalidDataException($"Expected SV8 duplicate tuple no-op, got {duplicate}.");
        }

        Scalar8VarIdentityInsertResult keyConflict = Scalar8VarIdentity.Insert(shelfBytes, profile, duplicateKey, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false, out _);
        if (keyConflict != Scalar8VarIdentityInsertResult.KeyConflict)
        {
            throw new InvalidDataException($"Expected SV8 unique-key conflict, got {keyConflict}.");
        }

        ulong lower = CreateScalar8VarIdentityKey(0, duplicateModulo);
        ulong upper = CreateScalar8VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo);
        int identityCount = 0;
        int rangeSlotIndex = readOnly.LowerBoundKey(lower);
        for (int i = rangeSlotIndex; i < readOnly.ItemCount; i++)
        {
            if (readOnly.ReadKeyAt(i) > upper)
            {
                break;
            }

            identityCount++;
        }

        int expected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, Math.Min(2, duplicateModulo - 1));
        if (identityCount != expected)
        {
            throw new InvalidDataException($"SV8 range read returned {identityCount} identities; expected {expected}.");
        }

        bool hasPreviousExactIdentity = false;
        ReadOnlySpan<byte> previousExactIdentity = default;
        for (int i = readOnly.LowerBoundKey(lower); i < readOnly.ItemCount; i++)
        {
            if (readOnly.ReadKeyAt(i) != lower)
            {
                break;
            }

            ReadOnlySpan<byte> currentExactIdentity = readOnly.ReadIdentityAt(i);
            if (hasPreviousExactIdentity && previousExactIdentity.SequenceCompareTo(currentExactIdentity) > 0)
            {
                throw new InvalidDataException("SV8 exact-key range returned identities out of order.");
            }

            previousExactIdentity = currentExactIdentity;
            hasPreviousExactIdentity = true;
        }

        Console.WriteLine($"sv8-shelf-sanity ok items={itemCount} duplicateModulo={duplicateModulo} identityLength={identityLength} shelfSize={profile.ShelfExtentSize} rangeCount={identityCount}");
        return 0;
    }

    /// <summary>
    /// Validates the first routed `SV8` scalar-key/variable-identity path.<br/>
    /// The command creates a root route, inserts enough rows to force growth and key-byte shelf splitting, reopens the file, and validates key-range identity reads against the generated population.<br/>
    /// It deliberately uses a splittable scalar-key distribution; all-same-key varlen identity overflow remains a later duplicate-run strategy.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when routed insertion and range reads validate.</returns>
    private static int RunScalar8VarIdentityRoutedSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "sv8-routed-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 1400);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 32);
        int identityLength = GetIntOption(args, "--identity-length", 96);
        if (itemCount <= 0 || duplicateModulo <= 0 || identityLength < 16 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV8 routed sanity requires positive items, positive duplicate modulo, and identity length 16-1024.");
        }

        File.Delete(path);
        Directory.CreateDirectory(Path.GetDirectoryName(path) ?? ".");
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        int growCount = 0;
        int splitCount = 0;
        int duplicateRunOverflowCount = 0;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(829), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "sv8route", 0));
            rootOffset = root.Offset;
            _ = session.CreateScalar8VarIdentityShelfAndLinkRootRoute(rootOffset, 0, Scalar8VarIdentityProfile.DefaultInitial);
            for (int i = 0; i < itemCount; i++)
            {
                ulong key = CreateScalar8VarIdentityKey(i, duplicateModulo);
                byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                Scalar8VarIdentityRoutedInsertResult result = session.InsertWalkedRoutedScalar8VarIdentity(rootOffset, identityLength, key, identity, allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != Scalar8VarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed SV8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == Scalar8VarIdentityRoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }
                else if (result.Kind == Scalar8VarIdentityRoutedInsertKind.WalkedShelfSplit)
                {
                    splitCount++;
                }
                else if (result.Kind == Scalar8VarIdentityRoutedInsertKind.WalkedDuplicateRunOverflow)
                {
                    duplicateRunOverflowCount++;
                }
            }
        }

        if (itemCount >= 1400 && duplicateModulo > 1 && identityLength >= 96 && splitCount == 0)
        {
            throw new InvalidDataException("Routed SV8 sanity did not exercise a shelf split.");
        }

        if (itemCount >= 1400 && duplicateModulo == 1 && identityLength >= 96 && duplicateRunOverflowCount == 0)
        {
            throw new InvalidDataException("Routed SV8 sanity did not exercise duplicate-run overflow.");
        }

        using LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions);
        ulong lower = CreateScalar8VarIdentityKey(0, duplicateModulo);
        ulong upper = CreateScalar8VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo);
        using Scalar8VarIdentityRangeReader identitiesReader = reopened.OpenScalar8VarIdentityRangeReader(rootOffset, identityLength, lower, upper);
        int identityCount = identitiesReader.Count;
        int expected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, Math.Min(2, duplicateModulo - 1));
        if (identityCount != expected)
        {
            throw new InvalidDataException($"Routed SV8 range read returned {identityCount}; expected {expected}.");
        }

        using Scalar8VarIdentityRangeReader exactReader = reopened.OpenScalar8VarIdentityRangeReader(rootOffset, identityLength, lower, lower);
        int exactCount = exactReader.Count;
        byte[] previousIdentity = new byte[identityLength];
        byte[] currentIdentity = new byte[identityLength];
        if (exactReader.MoveNext())
        {
            exactReader.CopyCurrentIdentityTo(previousIdentity);
            while (exactReader.MoveNext())
            {
                exactReader.CopyCurrentIdentityTo(currentIdentity);
                if (previousIdentity.AsSpan().SequenceCompareTo(currentIdentity) > 0)
                {
                    throw new InvalidDataException("Routed SV8 exact-key range returned identities out of order.");
                }

                byte[] swap = previousIdentity;
                previousIdentity = currentIdentity;
                currentIdentity = swap;
            }
        }

        bool deletedExact = reopened.DeleteScalar8VarIdentityExactTuple(rootOffset, identityLength, lower, CreateScalar8VarIdentity(0, identityLength));
        if (!deletedExact)
        {
            throw new InvalidDataException("Routed SV8 exact tuple delete did not delete the expected tuple.");
        }

        using (Scalar8VarIdentityRangeReader afterExactDeleteReader = reopened.OpenScalar8VarIdentityRangeReader(rootOffset, identityLength, lower, lower))
        {
            if (afterExactDeleteReader.Count != exactCount - 1)
            {
                throw new InvalidDataException($"Routed SV8 exact tuple delete left {afterExactDeleteReader.Count} rows for the exact key; expected {exactCount - 1}.");
            }
        }

        long rangeDeleted = reopened.DeleteScalar8VarIdentityKeyRange(rootOffset, identityLength, lower, upper);
        if (rangeDeleted != expected - 1)
        {
            throw new InvalidDataException($"Routed SV8 range delete removed {rangeDeleted}; expected {expected - 1} after the exact delete.");
        }

        using (Scalar8VarIdentityRangeReader afterRangeDeleteReader = reopened.OpenScalar8VarIdentityRangeReader(rootOffset, identityLength, lower, upper))
        {
            if (afterRangeDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Routed SV8 range delete left {afterRangeDeleteReader.Count} rows in the deleted range.");
            }
        }

        Console.WriteLine($"sv8-routed-sanity ok items={itemCount} duplicateModulo={duplicateModulo} identityLength={identityLength} grows={growCount} splits={splitCount} duplicateRunOverflows={duplicateRunOverflowCount} rangeCount={identityCount} exactCount={exactCount} rangeDeleted={rangeDeleted}");
        return 0;
    }

    /// <summary>
    /// Validates the first public raw-byte `SV8` index facade.<br/>
    /// The command creates a public `Indexes.SV8` index, inserts through the public batch API with lazy root-prefix shelves, verifies duplicate no-op and duplicate-key conflict behavior, reads a range before and after reopen, and checks `CreateOrOpen` returns the existing slot.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when public create, batch insert, range read, reopen, and create-or-open behavior validate.</returns>
    private static int RunScalar8VarIdentityIndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "sv8-index-api-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 512);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 16);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        if (itemCount <= 0 || duplicateModulo <= 0 || duplicateModulo > 256 || identityLength <= 0 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV8 public API sanity requires positive items, duplicate modulo 1-256, and identity length 1-1024.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long lazyRouteCreates;
        long deferredCommitRequests;
        int expected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, Math.Min(2, duplicateModulo - 1));
        using (Scalar8VarIdentityIndex index = Indexes.SV8.Create(
            path,
            name: "sv8-api",
            maxIdentityLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9178),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            rootOffset = index.RootRouterOffset;
            using (Scalar8VarIdentityBatch batch = index.BeginBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.WriteSpeed)))
            {
                lazyRouteCreates = 0;
                for (int i = 0; i < itemCount; i++)
                {
                    ulong key = CreateScalar8VarIdentityKey(i, duplicateModulo);
                    byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                    Scalar8VarIdentityInsertOutcome result = batch.Insert(key, identity);
                    if (!result.Inserted)
                    {
                        throw new InvalidDataException($"Expected public SV8 insert {i}, got inserted={result.Inserted} already={result.AlreadyPresent} conflict={result.KeyConflict}.");
                    }

                    if (result.CreatedInitialShelfRoute)
                    {
                        lazyRouteCreates++;
                    }
                }

                ulong duplicateKey = CreateScalar8VarIdentityKey(0, duplicateModulo);
                Scalar8VarIdentityInsertOutcome duplicate = batch.Insert(duplicateKey, CreateScalar8VarIdentity(0, identityLength));
                if (!duplicate.AlreadyPresent)
                {
                    throw new InvalidDataException("Expected public SV8 duplicate tuple to be reported as already present.");
                }

                Scalar8VarIdentityInsertOutcome conflict = batch.Insert(duplicateKey, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false);
                if (!conflict.KeyConflict)
                {
                    throw new InvalidDataException("Expected public SV8 duplicate key to be rejected when duplicate keys are disabled.");
                }

                ScalarVarIdentityBatchCommitResult commit = batch.Commit();
                deferredCommitRequests = commit.DeferredCommitRequests;
                if (commit.AttemptedInsertCount != itemCount + 2 || commit.InsertedCount != itemCount || commit.AlreadyPresentCount != 1 || commit.KeyConflictCount != 1)
                {
                    throw new InvalidDataException($"Unexpected public SV8 batch counts: attempted={commit.AttemptedInsertCount} inserted={commit.InsertedCount} already={commit.AlreadyPresentCount} conflicts={commit.KeyConflictCount}.");
                }
            }

            ulong lower = CreateScalar8VarIdentityKey(0, duplicateModulo);
            ulong upper = CreateScalar8VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo);
            using Scalar8VarIdentityRangeReader reader = index.OpenRangeReader(lower, upper);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public SV8 reader before reopen returned {reader.Count}; expected {expected}.");
            }
        }

        long checksum = 0;
        using (Scalar8VarIdentityIndex reopened = Indexes.SV8.Open(
            path,
            maxIdentityLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (reopened.RootRouterOffset != rootOffset || reopened.Name != "sv8-api")
            {
                throw new InvalidDataException("Reopened public SV8 index did not preserve root offset and name.");
            }

            ulong lower = CreateScalar8VarIdentityKey(0, duplicateModulo);
            ulong upper = CreateScalar8VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo);
            using Scalar8VarIdentityRangeReader reader = reopened.OpenRangeReader(lower, upper);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public SV8 reader after reopen returned {reader.Count}; expected {expected}.");
            }

            using Scalar8VarIdentityRangeReader skipReader = reopened.OpenRangeReader(lower, upper);
            int expectedSkip = Math.Min(2, expected);
            if (skipReader.Skip(2) != expectedSkip)
            {
                throw new InvalidDataException("Public SV8 reader did not report the expected skipped row count.");
            }

            int readCount = 0;
            Span<byte> identityScratch = stackalloc byte[1024];
            while (reader.MoveNext())
            {
                if (reader.CurrentIdentityLength <= 0 || reader.CurrentIdentityLength > identityLength)
                {
                    throw new InvalidDataException("Public SV8 reader returned an identity length outside the expected bounds.");
                }

                if (readCount == 0 && reader.CopyCurrentIdentityTo(identityScratch) != reader.CurrentIdentityLength)
                {
                    throw new InvalidDataException("Public SV8 reader copied an unexpected identity length.");
                }

                checksum += ChecksumBytes(reader.CurrentIdentity);
                readCount++;
            }

            if (readCount != expected)
            {
                throw new InvalidDataException($"Public SV8 reader enumerated {readCount}; expected {expected}.");
            }

            using LibraDexVarIdentityBuffer identityBuffer = reopened.ReadIdentityBuffer(lower, upper);
            if (identityBuffer.Count != expected || identityBuffer.PayloadLength <= 0)
            {
                throw new InvalidDataException("Public SV8 identity buffer did not report the expected count and payload length.");
            }

            long bufferChecksum = 0;
            long enumeratorChecksum = 0;
            for (int i = 0; i < identityBuffer.Count; i++)
            {
                ReadOnlySpan<byte> identity = identityBuffer[i];
                if (identity.Length <= 0 || identity.Length > identityLength)
                {
                    throw new InvalidDataException("Public SV8 identity buffer returned an identity length outside the expected bounds.");
                }

                int identityOffset = identityBuffer.GetOffset(i);
                int reportedLength = identityBuffer.GetLength(i);
                if (reportedLength != identity.Length || identityOffset < 0 || identityOffset + reportedLength > identityBuffer.PayloadLength)
                {
                    throw new InvalidDataException("Public SV8 identity buffer returned inconsistent offset/length metadata.");
                }

                if (!identityBuffer.PayloadSpan.Slice(identityOffset, reportedLength).SequenceEqual(identity))
                {
                    throw new InvalidDataException("Public SV8 identity buffer flat payload did not match indexed identity access.");
                }

                if (i == 0 && !identityBuffer.TryCopyTo(i, identityScratch))
                {
                    throw new InvalidDataException("Public SV8 identity buffer failed to copy the first identity to caller storage.");
                }

                if (i == 0)
                {
                    identityBuffer.CopyTo(i, identityScratch);
                }

                bufferChecksum += ChecksumBytes(identity);
            }

            foreach (ReadOnlySpan<byte> identity in identityBuffer)
            {
                enumeratorChecksum += ChecksumBytes(identity);
            }

            if (bufferChecksum != checksum || enumeratorChecksum != checksum || identityBuffer.GetMemory(0).Length != identityBuffer[0].Length || identityBuffer.PayloadMemory.Length != identityBuffer.PayloadLength)
            {
                throw new InvalidDataException("Public SV8 identity buffer did not match streaming reader results.");
            }

            if (!reopened.DeleteExactTuple(lower, CreateScalar8VarIdentity(0, identityLength)))
            {
                throw new InvalidDataException("Internal SV8 exact tuple delete did not remove the expected tuple.");
            }

            long rangeDeleted = reopened.DeleteRange(lower, upper);
            if (rangeDeleted != expected - 1)
            {
                throw new InvalidDataException($"Internal SV8 range delete removed {rangeDeleted}; expected {expected - 1} after exact delete.");
            }

            using Scalar8VarIdentityRangeReader afterDeleteReader = reopened.OpenRangeReader(lower, upper);
            if (afterDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Internal SV8 range delete left {afterDeleteReader.Count} rows in the deleted range.");
            }
        }

        using (Scalar8VarIdentityIndex openedAgain = Indexes.SV8.CreateOrOpen(
            path,
            maxIdentityLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedAgain.RootRouterOffset != rootOffset)
            {
                throw new InvalidDataException("CreateOrOpen public SV8 did not return the existing root router offset.");
            }
        }

        Console.WriteLine($"sv8-index-api-sanity ok path={path} root={rootOffset} items={itemCount} duplicateModulo={duplicateModulo} identityLength={identityLength} lazyCreates={lazyRouteCreates} deferredCommits={deferredCommitRequests} rangeCount={expected} checksum={checksum}");
        return 0;
    }

    /// <summary>
    /// Compares routed `SV8` against SQLite for the same scalar-key/raw-variable-identity physical meaning.<br/>
    /// LibraDex writes use the real routed session path, including shelf growth, scalar-key splits, same-depth parent-route splits, and duplicate-run overflow when the key distribution is unsplittable.<br/>
    /// SQLite writes use one transaction against a `WITHOUT ROWID` table keyed by `(INTEGER key, BLOB identity)`, so both rows measure a batched identity index rather than one fsync per insert.<br/>
    /// Reads reopen the LibraDex file and scan the same scalar-key range through the routed `SV8` reader, then run the equivalent ordered SQLite range query.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunScalar8VarIdentityRoutedSqliteComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SV8RoutedSqliteComparison"));
        int itemCount = GetIntOption(args, "--items", 12000);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 256);
        int identityLength = GetIntOption(args, "--identity-length", 96);
        int iterations = GetIntOption(args, "--iterations", 200);
        int rangeKeyCount = GetIntOption(args, "--range-key-count", Math.Min(16, Math.Max(1, duplicateModulo)));
        string order = GetOption(args, "--order", "natural");
        string keyDistribution = GetOption(args, "--key-distribution", "low");
        string iterationModeText = GetOption(args, "--iteration-mode", "identities");
        bool fixedIdentityLength = GetBoolOption(args, "--fixed-identity-length", false);
        bool includeAttribution = GetBoolOption(args, "--include-attribution", false);
        int initialShelfKiB = GetIntOption(args, "--initial-shelf-kib", Scalar8VarIdentityProfile.DefaultInitial.ShelfExtentSize / 1024);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (itemCount <= 0 || duplicateModulo <= 0 || identityLength <= 0 || identityLength > 1024 || iterations <= 0 || rangeKeyCount <= 0 || rangeKeyCount > duplicateModulo)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV8 routed SQLite comparison requires positive items, duplicate modulo, iterations, range key count within the duplicate modulo, and identity length 1-1024.");
        }

        if (!order.Equals("natural", StringComparison.OrdinalIgnoreCase) &&
            !order.Equals("key-major", StringComparison.OrdinalIgnoreCase) &&
            !order.Equals("tuple-major", StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV8 routed SQLite comparison order must be 'natural', 'key-major', or 'tuple-major'.");
        }

        if (!keyDistribution.Equals("low", StringComparison.OrdinalIgnoreCase) &&
            !keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV8 routed SQLite comparison key distribution must be 'low' or 'high-byte'.");
        }

        VarIdentityIterationMode iterationMode = ParseVarIdentityIterationMode(iterationModeText);
        Scalar8VarIdentityProfile initialProfile = CreateScalar8VarIdentityComparisonProfile(initialShelfKiB, identityLength);
        int[] writeOrder = CreateScalar8VarIdentityWriteOrder(itemCount, duplicateModulo, order, identityLength, fixedIdentityLength, keyDistribution);

        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "sv8-routed.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-sv8-routed.db");
        File.Delete(libraPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        long rootOffset;
        long libraGrowths = 0;
        long libraSplits = 0;
        long libraDuplicateRunOverflows = 0;
        Scalar8VarIdentityWalkedWriteAttribution libraAttribution = default;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(8301), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "sv8rcmp", 0));
            rootOffset = root.Offset;
            int rootShelfCount = keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase)
                ? Math.Min(duplicateModulo, 256)
                : 1;
            for (int prefix = 0; prefix < rootShelfCount; prefix++)
            {
                _ = session.CreateScalar8VarIdentityShelfAndLinkRootRoute(rootOffset, (byte)prefix, initialProfile);
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int orderIndex = 0; orderIndex < itemCount; orderIndex++)
            {
                int i = writeOrder[orderIndex];
                ulong key = CreateScalar8VarIdentityKey(i, duplicateModulo, keyDistribution);
                byte[] identity = CreateScalar8VarIdentity(i, identityLength, fixedIdentityLength);
                Scalar8VarIdentityRoutedInsertResult result;
                if (includeAttribution)
                {
                    result = session.InsertWalkedRoutedScalar8VarIdentity(rootOffset, identityLength, key, identity, allowDuplicateKeys: true, maxRouterHops: 8, out Scalar8VarIdentityWalkedWriteAttribution attribution);
                    libraAttribution += attribution;
                }
                else
                {
                    result = session.InsertWalkedRoutedScalar8VarIdentity(rootOffset, identityLength, key, identity, allowDuplicateKeys: true, maxRouterHops: 8);
                }

                if (result.InsertResult != Scalar8VarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed SV8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == Scalar8VarIdentityRoutedInsertKind.WalkedGrow)
                {
                    libraGrowths++;
                }
                else if (result.Kind == Scalar8VarIdentityRoutedInsertKind.WalkedShelfSplit)
                {
                    libraSplits++;
                }
                else if (result.Kind == Scalar8VarIdentityRoutedInsertKind.WalkedDuplicateRunOverflow)
                {
                    libraDuplicateRunOverflows++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteScalar8VarIdentitySchema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Integer);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Blob);
            for (int orderIndex = 0; orderIndex < itemCount; orderIndex++)
            {
                int i = writeOrder[orderIndex];
                keyParameter.Value = unchecked((long)CreateScalar8VarIdentitySqliteKey(i, duplicateModulo, keyDistribution));
                identityParameter.Value = CreateScalar8VarIdentity(i, identityLength, fixedIdentityLength);
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        int lowerKey = 0;
        int upperKey = rangeKeyCount - 1;
        VarKeyScalar8ReadMeasurement libraRead;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraRead = MeasureScalar8VarIdentityRangeReads(reopened, rootOffset, identityLength, duplicateModulo, keyDistribution, lowerKey, upperKey, itemCount, iterations, iterationMode);
        }

        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteScalar8VarIdentityRangeReads(connection, duplicateModulo, keyDistribution, identityLength, lowerKey, upperKey, itemCount, iterations, iterationMode);
        }

        long libraBytes = new FileInfo(libraPath).Length;
        long sqliteBytes = GetSqliteScalar8Scalar8StorageBytes(sqlitePath);
        double libraWriteItemsPerSecond = itemCount / Math.Max(libraWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double sqliteWriteItemsPerSecond = itemCount / Math.Max(sqliteWriteWatch.Elapsed.TotalSeconds, 0.000001);
        Console.WriteLine("sv8 routed sqlite comparison");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"duplicateModulo {duplicateModulo}");
        Console.WriteLine($"identityLength {identityLength}");
        Console.WriteLine($"initialShelfKiB {initialShelfKiB}");
        Console.WriteLine($"fixedIdentityLength {fixedIdentityLength}");
        Console.WriteLine($"includeAttribution {includeAttribution}");
        Console.WriteLine($"iterationMode {iterationModeText}");
        Console.WriteLine($"order {order}");
        Console.WriteLine($"keyDistribution {keyDistribution}");
        Console.WriteLine($"rangeKeys {lowerKey}-{upperKey}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"libraGrowths {libraGrowths}");
        Console.WriteLine($"libraSplits {libraSplits}");
        Console.WriteLine($"libraDuplicateRunOverflows {libraDuplicateRunOverflows}");
        Console.WriteLine("| row | items/sec | ids/sec | ns/id | readCalls | backingReads | readBytes | cacheArenas | cacheBytes | bytes | bytes/item | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| SV8 routed write/read | {libraWriteItemsPerSecond:F2} | {libraRead.IdentitiesPerSecond:F2} | {libraRead.NsPerIdentity:F2} | {libraRead.ReadTelemetry.ReadCallCount} | {libraRead.ReadTelemetry.BackingReadCallCount} | {libraRead.ReadTelemetry.BytesRead} | {libraRead.RouterArenaCacheCount} | {libraRead.RouterArenaCacheBytes} | {libraBytes} | {(double)libraBytes / itemCount:F2} | {libraRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| SQLite write/read | {sqliteWriteItemsPerSecond:F2} | {sqliteRead.IdentitiesPerSecond:F2} | {sqliteRead.NsPerIdentity:F2} | 0 | 0 | 0 | 0 | 0 | {sqliteBytes} | {(double)sqliteBytes / itemCount:F2} | {sqliteRead.Checksum} |"));
        Console.WriteLine($"SV8/SQLite read {FormatMultiplier(libraRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"SV8/SQLite write {FormatMultiplier(libraWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        if (includeAttribution)
        {
            double ticksToNsPerItem = 1_000_000_000d / Stopwatch.Frequency / itemCount;
            long attributedTicks =
                libraAttribution.RouteWalkTicks +
                libraAttribution.ShelfReadTicks +
                libraAttribution.DuplicateChainTicks +
                libraAttribution.MutationTicks +
                libraAttribution.StageTicks +
                libraAttribution.StructuralTicks;
            Console.WriteLine("| attribution | ticks | ns/item | percent |");
            Console.WriteLine("|---|---:|---:|---:|");
            PrintScalar8VarIdentityAttributionRow("route walk", libraAttribution.RouteWalkTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar8VarIdentityAttributionRow("shelf read", libraAttribution.ShelfReadTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar8VarIdentityAttributionRow("duplicate chain", libraAttribution.DuplicateChainTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar8VarIdentityAttributionRow("mutation", libraAttribution.MutationTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar8VarIdentityAttributionRow("stage", libraAttribution.StageTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar8VarIdentityAttributionRow("structural", libraAttribution.StructuralTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar8VarIdentityAttributionRow("attributed total", attributedTicks, attributedTicks, ticksToNsPerItem);
        }

        return 0;
    }

    /// <summary>
    /// Prints one `SV8` walked-write attribution row in the routed SQLite comparison output.<br/>
    /// The method keeps unit conversion and percent math centralized so all buckets use the same denominator.<br/>
    /// </summary>
    /// <param name="name">The attribution bucket name.</param>
    /// <param name="ticks">The elapsed Stopwatch ticks attributed to the bucket.</param>
    /// <param name="totalTicks">The sum of all attributed Stopwatch ticks.</param>
    /// <param name="ticksToNsPerItem">The precomputed Stopwatch-tick to nanoseconds-per-written-item multiplier.</param>
    private static void PrintScalar8VarIdentityAttributionRow(
        string name,
        long ticks,
        long totalTicks,
        double ticksToNsPerItem)
    {
        double percent = totalTicks == 0 ? 0 : ticks * 100d / totalTicks;
        Console.WriteLine(FormattableString.Invariant($"| {name} | {ticks} | {ticks * ticksToNsPerItem:F2} | {percent:F2} |"));
    }

    /// <summary>
    /// Prints one `SV16` walked-write attribution row in the routed SQLite comparison output.<br/>
    /// The method mirrors the `SV8` attribution printer so the widened scalar-key shape can be compared bucket-for-bucket.<br/>
    /// </summary>
    /// <param name="name">The attribution bucket name.</param>
    /// <param name="ticks">The elapsed Stopwatch ticks attributed to the bucket.</param>
    /// <param name="totalTicks">The sum of all attributed Stopwatch ticks.</param>
    /// <param name="ticksToNsPerItem">The precomputed Stopwatch-tick to nanoseconds-per-written-item multiplier.</param>
    private static void PrintScalar16VarIdentityAttributionRow(
        string name,
        long ticks,
        long totalTicks,
        double ticksToNsPerItem)
    {
        double percent = totalTicks == 0 ? 0 : ticks * 100d / totalTicks;
        Console.WriteLine(FormattableString.Invariant($"| {name} | {ticks} | {ticks * ticksToNsPerItem:F2} | {percent:F2} |"));
    }

    /// <summary>
    /// Creates the `SV8` shelf profile requested by a routed SQLite comparison run.<br/>
    /// The harness keeps this selection explicit so shelf-size experiments do not change production defaults while write/read parity is being measured.<br/>
    /// </summary>
    /// <param name="initialShelfKiB">The initial shelf extent size in KiB; supported values are 16, 32, 64, and 128.</param>
    /// <param name="maxIdentityLength">The maximum raw identity byte length allowed by the generated comparison workload.</param>
    /// <returns>The `SV8` profile used to create the comparison index.</returns>
    private static Scalar8VarIdentityProfile CreateScalar8VarIdentityComparisonProfile(int initialShelfKiB, int maxIdentityLength)
    {
        return initialShelfKiB switch
        {
            16 => Scalar8VarIdentityProfile.Create(Scalar8VarIdentityProfile.Default16KiB.ShelfExtentSize, maxIdentityLength),
            32 => Scalar8VarIdentityProfile.Create(Scalar8VarIdentityProfile.Default32KiB.ShelfExtentSize, maxIdentityLength),
            64 => Scalar8VarIdentityProfile.Create(Scalar8VarIdentityProfile.Default64KiB.ShelfExtentSize, maxIdentityLength),
            128 => Scalar8VarIdentityProfile.Create(Scalar8VarIdentityProfile.Default128KiB.ShelfExtentSize, maxIdentityLength),
            _ => throw new ArgumentOutOfRangeException(nameof(initialShelfKiB), initialShelfKiB, "SV8 comparison initial shelf KiB must be 16, 32, 64, or 128.")
        };
    }

    /// <summary>
    /// Creates the `SV16` shelf profile requested by a routed SQLite comparison run.<br/>
    /// The harness keeps this selection explicit so shelf-size experiments do not change production defaults while write/read parity is being measured.<br/>
    /// </summary>
    /// <param name="initialShelfKiB">The initial shelf extent size in KiB; supported values are 16, 32, 64, and 128.</param>
    /// <param name="maxIdentityLength">The maximum raw identity byte length allowed by the generated comparison workload.</param>
    /// <returns>The `SV16` profile used to create the comparison index.</returns>
    private static Scalar16VarIdentityProfile CreateScalar16VarIdentityComparisonProfile(int initialShelfKiB, int maxIdentityLength)
    {
        return initialShelfKiB switch
        {
            16 => Scalar16VarIdentityProfile.Create(Scalar16VarIdentityProfile.Default16KiB.ShelfExtentSize, maxIdentityLength),
            32 => Scalar16VarIdentityProfile.Create(Scalar16VarIdentityProfile.Default32KiB.ShelfExtentSize, maxIdentityLength),
            64 => Scalar16VarIdentityProfile.Create(Scalar16VarIdentityProfile.Default64KiB.ShelfExtentSize, maxIdentityLength),
            128 => Scalar16VarIdentityProfile.Create(Scalar16VarIdentityProfile.Default128KiB.ShelfExtentSize, maxIdentityLength),
            _ => throw new ArgumentOutOfRangeException(nameof(initialShelfKiB), initialShelfKiB, "SV16 comparison initial shelf KiB must be 16, 32, 64, or 128.")
        };
    }

    private enum VarIdentityIterationMode
    {
        Identities = 0,
        Keys = 1,
        Tuples = 2
    }

    /// <summary>
    /// Parses the range-read iteration payload mode used by varlen identity comparison commands.<br/>
    /// `identities` models the most common LibraDex use case, `keys` isolates key-only cursor overhead, and `tuples` measures callers that read both sides of the matching tuple.<br/>
    /// </summary>
    /// <param name="value">The command-line mode value.</param>
    /// <returns>The parsed iteration mode.</returns>
    private static VarIdentityIterationMode ParseVarIdentityIterationMode(string value)
    {
        if (value.Equals("identities", StringComparison.OrdinalIgnoreCase))
        {
            return VarIdentityIterationMode.Identities;
        }

        if (value.Equals("keys", StringComparison.OrdinalIgnoreCase))
        {
            return VarIdentityIterationMode.Keys;
        }

        if (value.Equals("tuples", StringComparison.OrdinalIgnoreCase))
        {
            return VarIdentityIterationMode.Tuples;
        }

        throw new ArgumentOutOfRangeException(nameof(value), value, "Varlen identity iteration mode must be 'identities', 'keys', or 'tuples'.");
    }

    /// <summary>
    /// Builds the SQLite `SV16` range-read projection matching the requested iteration payload mode.<br/>
    /// Keeping the projection narrow prevents key-only and identity-only measurements from accidentally timing tuple materialization work.<br/>
    /// </summary>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The SQLite command text for the requested projection.</returns>
    private static string CreateSqliteScalar16VarIdentityRangeReadCommandText(VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => "SELECT k FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            VarIdentityIterationMode.Tuples => "SELECT k, i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            _ => "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;"
        };
    }

    /// <summary>
    /// Adds the current `SV16` reader row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The helper intentionally reads only the fields implied by the mode so the harness measures identities, keys, and full tuples as distinct access patterns.<br/>
    /// </summary>
    /// <param name="reader">The positioned `SV16` range reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumScalar16VarIdentityCurrent(Scalar16VarIdentityRangeReader reader, VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => ChecksumScalar16Key(reader.CurrentEncodedKeyHigh, reader.CurrentEncodedKeyLow),
            VarIdentityIterationMode.Tuples => ChecksumScalar16Key(reader.CurrentEncodedKeyHigh, reader.CurrentEncodedKeyLow) + ChecksumBytes(reader.CurrentIdentity),
            _ => ChecksumBytes(reader.CurrentIdentity)
        };
    }

    /// <summary>
    /// Adds the current SQLite `SV16` row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The selected column positions match <see cref="CreateSqliteScalar16VarIdentityRangeReadCommandText(VarIdentityIterationMode)"/>.<br/>
    /// </summary>
    /// <param name="reader">The positioned SQLite data reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumSqliteScalar16VarIdentityCurrent(SqliteDataReader reader, VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => ChecksumBytes((byte[])reader.GetValue(0)),
            VarIdentityIterationMode.Tuples => ChecksumBytes((byte[])reader.GetValue(0)) + ChecksumBytes((byte[])reader.GetValue(1)),
            _ => ChecksumBytes((byte[])reader.GetValue(0))
        };
    }

    /// <summary>
    /// Creates the generated `SV8` write order used by routed and SQLite comparison rows.<br/>
    /// `natural` preserves generator order, `key-major` groups all duplicate-key identities together, and `tuple-major` sorts by the full generated tuple.<br/>
    /// </summary>
    /// <param name="itemCount">The total generated item count.</param>
    /// <param name="duplicateModulo">The generated scalar-key modulo.</param>
    /// <param name="order">The requested order name.</param>
    /// <param name="identityLength">The generated identity length used when tuple sorting is requested.</param>
    /// <param name="fixedIdentityLength">Whether identities are generated at exactly <paramref name="identityLength"/> bytes.</param>
    /// <param name="keyDistribution">The scalar-key distribution used by the comparison.</param>
    /// <returns>The generated source indexes in write order.</returns>
    private static int[] CreateScalar8VarIdentityWriteOrder(
        int itemCount,
        int duplicateModulo,
        string order,
        int identityLength,
        bool fixedIdentityLength,
        string keyDistribution)
    {
        int[] result = new int[itemCount];
        if (order.Equals("tuple-major", StringComparison.OrdinalIgnoreCase))
        {
            for (int i = 0; i < itemCount; i++)
            {
                result[i] = i;
            }

            Array.Sort(result, (left, right) =>
            {
                ulong leftKey = CreateScalar8VarIdentityKey(left, duplicateModulo, keyDistribution);
                ulong rightKey = CreateScalar8VarIdentityKey(right, duplicateModulo, keyDistribution);
                int keyComparison = leftKey.CompareTo(rightKey);
                if (keyComparison != 0)
                {
                    return keyComparison;
                }

                return Scalar8VarIdentityLayout.CompareIdentityBytes(
                    CreateScalar8VarIdentity(left, identityLength, fixedIdentityLength),
                    CreateScalar8VarIdentity(right, identityLength, fixedIdentityLength));
            });
            return result;
        }

        if (order.Equals("key-major", StringComparison.OrdinalIgnoreCase))
        {
            int cursor = 0;
            for (int key = 0; key < duplicateModulo; key++)
            {
                for (int sourceIndex = key; sourceIndex < itemCount; sourceIndex += duplicateModulo)
                {
                    result[cursor++] = sourceIndex;
                }
            }

            return result;
        }

        for (int i = 0; i < itemCount; i++)
        {
            result[i] = i;
        }

        return result;
    }

    /// <summary>
    /// Validates the first `SV16` scalar16-key/variable-identity shelf primitive without routing.<br/>
    /// The command mirrors `sv8-shelf-sanity` while checking that both high and low key halves participate in tuple ordering and duplicate detection.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the shelf primitive validates.</returns>
    private static int RunScalar16VarIdentityShelfSanity(string[] args)
    {
        int itemCount = GetIntOption(args, "--items", 900);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 6);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        if (itemCount <= 0 || duplicateModulo <= 0 || identityLength < 16 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV16 shelf sanity requires positive items, duplicate modulo, and identity length 16-1024.");
        }

        Scalar16VarIdentityProfile profile = Scalar16VarIdentityProfile.DefaultInitial;
        byte[] shelfBytes = Scalar16VarIdentity.CreateEmpty(profile);
        for (int i = 0; i < itemCount; i++)
        {
            CreateScalar16VarIdentityKey(i, duplicateModulo, "low", out ulong keyHigh, out ulong keyLow);
            byte[] identity = CreateScalar8VarIdentity(i, identityLength);
            Scalar16VarIdentityInsertResult result = Scalar16VarIdentity.Insert(shelfBytes, profile, keyHigh, keyLow, identity, allowDuplicateKeys: true, out byte[] rewritten);
            if (result == Scalar16VarIdentityInsertResult.Full &&
                Scalar16VarIdentity.TryGrowAndInsert(shelfBytes, profile, keyHigh, keyLow, identity, allowDuplicateKeys: true, out Scalar16VarIdentityProfile grownProfile, out rewritten, out result))
            {
                profile = grownProfile;
            }

            if (result != Scalar16VarIdentityInsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SV16 insert {i}, got {result} at profile {profile.ShelfExtentSize}.");
            }

            shelfBytes = rewritten;
        }

        Scalar16VarIdentityReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid || readOnly.ItemCount != itemCount)
        {
            throw new InvalidDataException($"SV16 shelf sanity produced invalid shelf or wrong count. valid={readOnly.IsValid} count={readOnly.ItemCount} expected={itemCount}.");
        }

        for (int i = 1; i < readOnly.ItemCount; i++)
        {
            int keyComparison = CompareScalar16VarIdentityKey(readOnly.ReadKeyHighAt(i - 1), readOnly.ReadKeyLowAt(i - 1), readOnly.ReadKeyHighAt(i), readOnly.ReadKeyLowAt(i));
            if (keyComparison > 0)
            {
                throw new InvalidDataException($"SV16 key ordering drifted at slot {i}.");
            }

            if (keyComparison == 0 &&
                readOnly.ReadIdentityAt(i - 1).SequenceCompareTo(readOnly.ReadIdentityAt(i)) > 0)
            {
                throw new InvalidDataException($"SV16 duplicate-key identity ordering drifted at slot {i}.");
            }
        }

        int slotStreamLength = Scalar16VarIdentityLayout.ReadSlotStreamLength(shelfBytes);
        int slotCapacityBytes = Scalar16VarIdentityLayout.ReadSlotCapacityBytes(shelfBytes);
        int expectedSlotStreamLength = checked(readOnly.ItemCount * Scalar16VarIdentityLayout.SlotSize);
        int expectedSlotCapacityBytes = Scalar16VarIdentityLayout.CalculateSlotCapacityBytes(profile.ShelfExtentSize);
        int expectedFirstRecordOffset = Scalar16VarIdentityLayout.HeaderSize + slotCapacityBytes;
        int recordArenaEnd = Scalar16VarIdentityLayout.ReadRecordArenaEnd(shelfBytes);
        uint minRecordOffset = uint.MaxValue;
        uint maxRecordEnd = 0;
        for (int i = 0; i < readOnly.ItemCount; i++)
        {
            uint recordOffset = readOnly.ReadRecordOffsetAt(i);
            minRecordOffset = Math.Min(minRecordOffset, recordOffset);
            maxRecordEnd = Math.Max(maxRecordEnd, checked(recordOffset + (uint)Scalar16VarIdentityLayout.GetRecordLength(shelfBytes, checked((int)recordOffset))));
        }

        if (slotStreamLength != expectedSlotStreamLength ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            minRecordOffset != expectedFirstRecordOffset ||
            maxRecordEnd != recordArenaEnd)
        {
            throw new InvalidDataException($"SV16 shelf reserved-slot record layout failed. slots={slotStreamLength}/{expectedSlotStreamLength} slotCapacity={slotCapacityBytes}/{expectedSlotCapacityBytes} firstRecord={minRecordOffset}/{expectedFirstRecordOffset} arenaEnd={recordArenaEnd}/{maxRecordEnd}.");
        }

        CreateScalar16VarIdentityKey(0, duplicateModulo, "low", out ulong duplicateHigh, out ulong duplicateLow);
        Scalar16VarIdentityInsertResult duplicate = Scalar16VarIdentity.Insert(shelfBytes, profile, duplicateHigh, duplicateLow, CreateScalar8VarIdentity(0, identityLength), allowDuplicateKeys: true, out _);
        if (duplicate != Scalar16VarIdentityInsertResult.AlreadyPresent)
        {
            throw new InvalidDataException($"Expected SV16 duplicate tuple no-op, got {duplicate}.");
        }

        Scalar16VarIdentityInsertResult keyConflict = Scalar16VarIdentity.Insert(shelfBytes, profile, duplicateHigh, duplicateLow, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false, out _);
        if (keyConflict != Scalar16VarIdentityInsertResult.KeyConflict)
        {
            throw new InvalidDataException($"Expected SV16 unique-key conflict, got {keyConflict}.");
        }

        CreateScalar16VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo, "low", out ulong upperHigh, out ulong upperLow);
        int identityCount = 0;
        int rangeSlotIndex = readOnly.LowerBoundKey(duplicateHigh, duplicateLow);
        for (int i = rangeSlotIndex; i < readOnly.ItemCount; i++)
        {
            ulong keyHigh = readOnly.ReadKeyHighAt(i);
            ulong keyLow = readOnly.ReadKeyLowAt(i);
            if (LibraDexFileSession.CompareScalar16VarIdentityKey(keyHigh, keyLow, upperHigh, upperLow) > 0)
            {
                break;
            }

            identityCount++;
        }

        int expected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, Math.Min(2, duplicateModulo - 1));
        if (identityCount != expected)
        {
            throw new InvalidDataException($"SV16 range read returned {identityCount} identities; expected {expected}.");
        }

        Console.WriteLine($"sv16-shelf-sanity ok items={itemCount} duplicateModulo={duplicateModulo} identityLength={identityLength} shelfSize={profile.ShelfExtentSize} rangeCount={identityCount}");
        return 0;
    }

    /// <summary>
    /// Validates routed `SV16` insertion, split/grow behavior, duplicate-run overflow, reopen, and range reads.<br/>
    /// This is intentionally cloned from the `SV8` routed sanity with scalar keys widened to high/low halves.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when routed insertion and range reads validate.</returns>
    private static int RunScalar16VarIdentityRoutedSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "sv16-routed-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 1400);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 32);
        int identityLength = GetIntOption(args, "--identity-length", 96);
        string keyDistribution = GetOption(args, "--key-distribution", "low");
        if (itemCount <= 0 || duplicateModulo <= 0 || identityLength < 16 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV16 routed sanity requires positive items, positive duplicate modulo, and identity length 16-1024.");
        }

        File.Delete(path);
        Directory.CreateDirectory(Path.GetDirectoryName(path) ?? ".");
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        int growCount = 0;
        int splitCount = 0;
        int duplicateRunOverflowCount = 0;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(831), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "sv16route", 0));
            rootOffset = root.Offset;
            int rootShelfCount = keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase)
                ? Math.Min(duplicateModulo, 256)
                : 1;
            for (int prefix = 0; prefix < rootShelfCount; prefix++)
            {
                _ = session.CreateScalar16VarIdentityShelfAndLinkRootRoute(rootOffset, (byte)prefix, Scalar16VarIdentityProfile.DefaultInitial);
            }

            for (int i = 0; i < itemCount; i++)
            {
                CreateScalar16VarIdentityKey(i, duplicateModulo, keyDistribution, out ulong keyHigh, out ulong keyLow);
                byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                Scalar16VarIdentityRoutedInsertResult result = session.InsertWalkedRoutedScalar16VarIdentity(rootOffset, identityLength, keyHigh, keyLow, identity, allowDuplicateKeys: true, maxRouterHops: 16);
                if (result.InsertResult != Scalar16VarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed SV16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == Scalar16VarIdentityRoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }
                else if (result.Kind == Scalar16VarIdentityRoutedInsertKind.WalkedShelfSplit)
                {
                    splitCount++;
                }
                else if (result.Kind == Scalar16VarIdentityRoutedInsertKind.WalkedDuplicateRunOverflow)
                {
                    duplicateRunOverflowCount++;
                }
            }
        }

        if (!keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase) &&
            itemCount >= 1400 &&
            duplicateModulo > 1 &&
            identityLength >= 96 &&
            splitCount == 0)
        {
            throw new InvalidDataException("Routed SV16 sanity did not exercise a shelf split.");
        }

        using LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions);
        CreateScalar16VarIdentityKey(0, duplicateModulo, keyDistribution, out ulong lowerHigh, out ulong lowerLow);
        CreateScalar16VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo, keyDistribution, out ulong upperHigh, out ulong upperLow);
        using Scalar16VarIdentityRangeReader identitiesReader = reopened.OpenScalar16VarIdentityRangeReader(rootOffset, identityLength, lowerHigh, lowerLow, upperHigh, upperLow);
        int identityCount = identitiesReader.Count;
        int expected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, Math.Min(2, duplicateModulo - 1));
        if (identityCount != expected)
        {
            throw new InvalidDataException($"Routed SV16 range read returned {identityCount}; expected {expected}.");
        }

        bool deletedExact = reopened.DeleteScalar16VarIdentityExactTuple(rootOffset, identityLength, lowerHigh, lowerLow, CreateScalar8VarIdentity(0, identityLength));
        if (!deletedExact)
        {
            throw new InvalidDataException("Routed SV16 exact tuple delete did not delete the expected tuple.");
        }

        using (Scalar16VarIdentityRangeReader afterExactDeleteReader = reopened.OpenScalar16VarIdentityRangeReader(rootOffset, identityLength, lowerHigh, lowerLow, lowerHigh, lowerLow))
        {
            int exactExpected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, 0) - 1;
            if (afterExactDeleteReader.Count != exactExpected)
            {
                throw new InvalidDataException($"Routed SV16 exact tuple delete left {afterExactDeleteReader.Count} rows for the exact key; expected {exactExpected}.");
            }
        }

        long rangeDeleted = reopened.DeleteScalar16VarIdentityKeyRange(rootOffset, identityLength, lowerHigh, lowerLow, upperHigh, upperLow);
        if (rangeDeleted != expected - 1)
        {
            throw new InvalidDataException($"Routed SV16 range delete removed {rangeDeleted}; expected {expected - 1} after the exact delete.");
        }

        using (Scalar16VarIdentityRangeReader afterRangeDeleteReader = reopened.OpenScalar16VarIdentityRangeReader(rootOffset, identityLength, lowerHigh, lowerLow, upperHigh, upperLow))
        {
            if (afterRangeDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Routed SV16 range delete left {afterRangeDeleteReader.Count} rows in the deleted range.");
            }
        }

        Console.WriteLine($"sv16-routed-sanity ok items={itemCount} duplicateModulo={duplicateModulo} identityLength={identityLength} grows={growCount} splits={splitCount} duplicateRunOverflows={duplicateRunOverflowCount} rangeCount={identityCount} rangeDeleted={rangeDeleted}");
        return 0;
    }

    /// <summary>
    /// Validates the first public raw-byte `SV16` index facade.<br/>
    /// The command creates a public `Indexes.SV16` index, inserts through the public batch API with lazy root-prefix shelves, verifies duplicate no-op and duplicate-key conflict behavior, reads a range before and after reopen, and checks `CreateOrOpen` returns the existing slot.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when public create, batch insert, range read, reopen, and create-or-open behavior validate.</returns>
    private static int RunScalar16VarIdentityIndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "sv16-index-api-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 512);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 16);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        if (itemCount <= 0 || duplicateModulo <= 0 || duplicateModulo > 256 || identityLength <= 0 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV16 public API sanity requires positive items, duplicate modulo 1-256, and identity length 1-1024.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long lazyRouteCreates;
        long deferredCommitRequests;
        int expected = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, Math.Min(2, duplicateModulo - 1));
        using (Scalar16VarIdentityIndex index = Indexes.SV16.Create(
            path,
            name: "sv16-api",
            maxIdentityLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9179),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            rootOffset = index.RootRouterOffset;
            using (Scalar16VarIdentityBatch batch = index.BeginBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.WriteSpeed)))
            {
                lazyRouteCreates = 0;
                for (int i = 0; i < itemCount; i++)
                {
                    CreateScalar16VarIdentityKey(i, duplicateModulo, "low", out ulong keyHigh, out ulong keyLow);
                    byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                    Scalar16VarIdentityInsertOutcome result = batch.Insert(keyHigh, keyLow, identity);
                    if (!result.Inserted)
                    {
                        throw new InvalidDataException($"Expected public SV16 insert {i}, got inserted={result.Inserted} already={result.AlreadyPresent} conflict={result.KeyConflict}.");
                    }

                    if (result.CreatedInitialShelfRoute)
                    {
                        lazyRouteCreates++;
                    }
                }

                CreateScalar16VarIdentityKey(0, duplicateModulo, "low", out ulong duplicateHigh, out ulong duplicateLow);
                Scalar16VarIdentityInsertOutcome duplicate = batch.Insert(duplicateHigh, duplicateLow, CreateScalar8VarIdentity(0, identityLength));
                if (!duplicate.AlreadyPresent)
                {
                    throw new InvalidDataException("Expected public SV16 duplicate tuple to be reported as already present.");
                }

                Scalar16VarIdentityInsertOutcome conflict = batch.Insert(duplicateHigh, duplicateLow, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false);
                if (!conflict.KeyConflict)
                {
                    throw new InvalidDataException("Expected public SV16 duplicate key to be rejected when duplicate keys are disabled.");
                }

                ScalarVarIdentityBatchCommitResult commit = batch.Commit();
                deferredCommitRequests = commit.DeferredCommitRequests;
                if (commit.AttemptedInsertCount != itemCount + 2 || commit.InsertedCount != itemCount || commit.AlreadyPresentCount != 1 || commit.KeyConflictCount != 1)
                {
                    throw new InvalidDataException($"Unexpected public SV16 batch counts: attempted={commit.AttemptedInsertCount} inserted={commit.InsertedCount} already={commit.AlreadyPresentCount} conflicts={commit.KeyConflictCount}.");
                }
            }

            CreateScalar16VarIdentityKey(0, duplicateModulo, "low", out ulong lowerHigh, out ulong lowerLow);
            CreateScalar16VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo, "low", out ulong upperHigh, out ulong upperLow);
            using Scalar16VarIdentityRangeReader reader = index.OpenRangeReader(lowerHigh, lowerLow, upperHigh, upperLow);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public SV16 reader before reopen returned {reader.Count}; expected {expected}.");
            }
        }

        long checksum = 0;
        using (Scalar16VarIdentityIndex reopened = Indexes.SV16.Open(
            path,
            maxIdentityLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (reopened.RootRouterOffset != rootOffset || reopened.Name != "sv16-api")
            {
                throw new InvalidDataException("Reopened public SV16 index did not preserve root offset and name.");
            }

            CreateScalar16VarIdentityKey(0, duplicateModulo, "low", out ulong lowerHigh, out ulong lowerLow);
            CreateScalar16VarIdentityKey(Math.Min(2, duplicateModulo - 1), duplicateModulo, "low", out ulong upperHigh, out ulong upperLow);
            using Scalar16VarIdentityRangeReader reader = reopened.OpenRangeReader(lowerHigh, lowerLow, upperHigh, upperLow);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public SV16 reader after reopen returned {reader.Count}; expected {expected}.");
            }

            using Scalar16VarIdentityRangeReader skipReader = reopened.OpenRangeReader(lowerHigh, lowerLow, upperHigh, upperLow);
            int expectedSkip = Math.Min(2, expected);
            if (skipReader.Skip(2) != expectedSkip)
            {
                throw new InvalidDataException("Public SV16 reader did not report the expected skipped row count.");
            }

            int readCount = 0;
            Span<byte> identityScratch = stackalloc byte[1024];
            while (reader.MoveNext())
            {
                if (reader.CurrentIdentityLength <= 0 || reader.CurrentIdentityLength > identityLength)
                {
                    throw new InvalidDataException("Public SV16 reader returned an identity length outside the expected bounds.");
                }

                if (readCount == 0 && reader.CopyCurrentIdentityTo(identityScratch) != reader.CurrentIdentityLength)
                {
                    throw new InvalidDataException("Public SV16 reader copied an unexpected identity length.");
                }

                checksum += ChecksumBytes(reader.CurrentIdentity);
                readCount++;
            }

            if (readCount != expected)
            {
                throw new InvalidDataException($"Public SV16 reader enumerated {readCount}; expected {expected}.");
            }

            using LibraDexVarIdentityBuffer identityBuffer = reopened.ReadIdentityBuffer(lowerHigh, lowerLow, upperHigh, upperLow);
            if (identityBuffer.Count != expected || identityBuffer.PayloadLength <= 0)
            {
                throw new InvalidDataException("Public SV16 identity buffer did not report the expected count and payload length.");
            }

            long bufferChecksum = 0;
            long enumeratorChecksum = 0;
            for (int i = 0; i < identityBuffer.Count; i++)
            {
                ReadOnlySpan<byte> identity = identityBuffer[i];
                if (identity.Length <= 0 || identity.Length > identityLength)
                {
                    throw new InvalidDataException("Public SV16 identity buffer returned an identity length outside the expected bounds.");
                }

                int identityOffset = identityBuffer.GetOffset(i);
                int reportedLength = identityBuffer.GetLength(i);
                if (reportedLength != identity.Length || identityOffset < 0 || identityOffset + reportedLength > identityBuffer.PayloadLength)
                {
                    throw new InvalidDataException("Public SV16 identity buffer returned inconsistent offset/length metadata.");
                }

                if (!identityBuffer.PayloadSpan.Slice(identityOffset, reportedLength).SequenceEqual(identity))
                {
                    throw new InvalidDataException("Public SV16 identity buffer flat payload did not match indexed identity access.");
                }

                if (i == 0 && !identityBuffer.TryCopyTo(i, identityScratch))
                {
                    throw new InvalidDataException("Public SV16 identity buffer failed to copy the first identity to caller storage.");
                }

                if (i == 0)
                {
                    identityBuffer.CopyTo(i, identityScratch);
                }

                bufferChecksum += ChecksumBytes(identity);
            }

            foreach (ReadOnlySpan<byte> identity in identityBuffer)
            {
                enumeratorChecksum += ChecksumBytes(identity);
            }

            if (bufferChecksum != checksum || enumeratorChecksum != checksum || identityBuffer.GetMemory(0).Length != identityBuffer[0].Length || identityBuffer.PayloadMemory.Length != identityBuffer.PayloadLength)
            {
                throw new InvalidDataException("Public SV16 identity buffer did not match streaming reader results.");
            }

            if (!reopened.DeleteExactTuple(lowerHigh, lowerLow, CreateScalar8VarIdentity(0, identityLength)))
            {
                throw new InvalidDataException("Internal SV16 exact tuple delete did not remove the expected tuple.");
            }

            long rangeDeleted = reopened.DeleteRange(lowerHigh, lowerLow, upperHigh, upperLow);
            if (rangeDeleted != expected - 1)
            {
                throw new InvalidDataException($"Internal SV16 range delete removed {rangeDeleted}; expected {expected - 1} after exact delete.");
            }

            using Scalar16VarIdentityRangeReader afterDeleteReader = reopened.OpenRangeReader(lowerHigh, lowerLow, upperHigh, upperLow);
            if (afterDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Internal SV16 range delete left {afterDeleteReader.Count} rows in the deleted range.");
            }
        }

        using (Scalar16VarIdentityIndex openedAgain = Indexes.SV16.CreateOrOpen(
            path,
            maxIdentityLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedAgain.RootRouterOffset != rootOffset)
            {
                throw new InvalidDataException("CreateOrOpen public SV16 did not return the existing root router offset.");
            }
        }

        Console.WriteLine($"sv16-index-api-sanity ok path={path} root={rootOffset} items={itemCount} duplicateModulo={duplicateModulo} identityLength={identityLength} lazyCreates={lazyRouteCreates} deferredCommits={deferredCommitRequests} rangeCount={expected} checksum={checksum}");
        return 0;
    }

    /// <summary>
    /// Compares routed `SV16` against SQLite for the same scalar16-key/raw-variable-identity physical meaning.<br/>
    /// SQLite stores the widened scalar key as one fixed 16-byte big-endian BLOB plus identity blob in a `WITHOUT ROWID` primary key so the comparison is semantic rather than a literal two-column decomposition.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunScalar16VarIdentityRoutedSqliteComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SV16RoutedSqliteComparison"));
        int itemCount = GetIntOption(args, "--items", 12000);
        int duplicateModulo = GetIntOption(args, "--duplicate-modulo", 256);
        int identityLength = GetIntOption(args, "--identity-length", 96);
        int iterations = GetIntOption(args, "--iterations", 200);
        int rangeKeyCount = GetIntOption(args, "--range-key-count", Math.Min(16, Math.Max(1, duplicateModulo)));
        string order = GetOption(args, "--order", "natural");
        string keyDistribution = GetOption(args, "--key-distribution", "low");
        string iterationModeText = GetOption(args, "--iteration-mode", "identities");
        bool fixedIdentityLength = GetBoolOption(args, "--fixed-identity-length", false);
        bool includeAttribution = GetBoolOption(args, "--include-attribution", false);
        int initialShelfKiB = GetIntOption(args, "--initial-shelf-kib", Scalar16VarIdentityProfile.DefaultInitial.ShelfExtentSize / 1024);
        if (itemCount <= 0 || duplicateModulo <= 0 || identityLength <= 0 || identityLength > 1024 || iterations <= 0 || rangeKeyCount <= 0 || rangeKeyCount > duplicateModulo)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SV16 routed SQLite comparison requires positive items, duplicate modulo, iterations, range key count within the duplicate modulo, and identity length 1-1024.");
        }

        VarIdentityIterationMode iterationMode = ParseVarIdentityIterationMode(iterationModeText);
        Scalar16VarIdentityProfile initialProfile = CreateScalar16VarIdentityComparisonProfile(initialShelfKiB, identityLength);
        int[] writeOrder = CreateScalar16VarIdentityWriteOrder(itemCount, duplicateModulo, order, identityLength, fixedIdentityLength, keyDistribution);
        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "sv16-routed.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-sv16-routed.db");
        File.Delete(libraPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        long rootOffset;
        long libraGrowths = 0;
        long libraSplits = 0;
        long libraDuplicateRunOverflows = 0;
        Scalar16VarIdentityWalkedWriteAttribution libraAttribution = default;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(8311), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "sv16rcmp", 0));
            rootOffset = root.Offset;
            int rootShelfCount = keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase)
                ? Math.Min(duplicateModulo, 256)
                : 1;
            for (int prefix = 0; prefix < rootShelfCount; prefix++)
            {
                _ = session.CreateScalar16VarIdentityShelfAndLinkRootRoute(rootOffset, (byte)prefix, initialProfile);
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int orderIndex = 0; orderIndex < itemCount; orderIndex++)
            {
                int i = writeOrder[orderIndex];
                CreateScalar16VarIdentityKey(i, duplicateModulo, keyDistribution, out ulong keyHigh, out ulong keyLow);
                byte[] identity = CreateScalar8VarIdentity(i, identityLength, fixedIdentityLength);
                Scalar16VarIdentityRoutedInsertResult result;
                if (includeAttribution)
                {
                    result = session.InsertWalkedRoutedScalar16VarIdentity(rootOffset, identityLength, keyHigh, keyLow, identity, allowDuplicateKeys: true, maxRouterHops: 16, out Scalar16VarIdentityWalkedWriteAttribution attribution);
                    libraAttribution += attribution;
                }
                else
                {
                    result = session.InsertWalkedRoutedScalar16VarIdentity(rootOffset, identityLength, keyHigh, keyLow, identity, allowDuplicateKeys: true, maxRouterHops: 16);
                }

                if (result.InsertResult != Scalar16VarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed SV16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == Scalar16VarIdentityRoutedInsertKind.WalkedGrow)
                {
                    libraGrowths++;
                }
                else if (result.Kind == Scalar16VarIdentityRoutedInsertKind.WalkedShelfSplit)
                {
                    libraSplits++;
                }
                else if (result.Kind == Scalar16VarIdentityRoutedInsertKind.WalkedDuplicateRunOverflow)
                {
                    libraDuplicateRunOverflows++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, new SqliteScalar8Scalar8Options("wal", "normal")))
        {
            using SqliteCommand create = connection.CreateCommand();
            create.CommandText = "CREATE TABLE items(k BLOB NOT NULL CHECK(length(k)=16), i BLOB NOT NULL, PRIMARY KEY(k, i)) WITHOUT ROWID;";
            create.ExecuteNonQuery();
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Blob);
            for (int orderIndex = 0; orderIndex < itemCount; orderIndex++)
            {
                int i = writeOrder[orderIndex];
                CreateScalar16VarIdentityKey(i, duplicateModulo, keyDistribution, out ulong keyHigh, out ulong keyLow);
                keyParameter.Value = CreateSqliteScalar16Scalar16Blob(keyHigh, keyLow);
                identityParameter.Value = CreateScalar8VarIdentity(i, identityLength, fixedIdentityLength);
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        CreateScalar16VarIdentityKey(0, duplicateModulo, keyDistribution, out ulong lowerHigh, out ulong lowerLow);
        CreateScalar16VarIdentityKey(rangeKeyCount - 1, duplicateModulo, keyDistribution, out ulong upperHigh, out ulong upperLow);
        int expectedReadIdentities = CountScalar8VarIdentityKeyRange(itemCount, duplicateModulo, 0, rangeKeyCount - 1);
        long libraReadIdentities = 0;
        long libraChecksum = 0;
        Stopwatch libraReadWatch = Stopwatch.StartNew();
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            for (int i = 0; i < iterations; i++)
            {
                using Scalar16VarIdentityRangeReader reader = reopened.OpenScalar16VarIdentityRangeReader(rootOffset, identityLength, lowerHigh, lowerLow, upperHigh, upperLow);
                int rangeCount = 0;
                while (reader.MoveNext())
                {
                    libraChecksum += ChecksumScalar16VarIdentityCurrent(reader, iterationMode);
                    rangeCount++;
                }

                if (rangeCount != expectedReadIdentities)
                {
                    throw new InvalidDataException($"SV16 range expected {expectedReadIdentities} identities, got {rangeCount}.");
                }

                libraReadIdentities += rangeCount;
            }
        }

        libraReadWatch.Stop();

        long sqliteReadIdentities = 0;
        long sqliteChecksum = 0;
        Stopwatch sqliteReadWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, new SqliteScalar8Scalar8Options("wal", "normal")))
        using (SqliteCommand command = connection.CreateCommand())
        {
            command.CommandText = CreateSqliteScalar16VarIdentityRangeReadCommandText(iterationMode);
            command.Parameters.AddWithValue("$lower", CreateSqliteScalar16Scalar16Blob(lowerHigh, lowerLow));
            command.Parameters.AddWithValue("$upper", CreateSqliteScalar16Scalar16Blob(upperHigh, upperLow));
            for (int i = 0; i < iterations; i++)
            {
                using SqliteDataReader reader = command.ExecuteReader();
                while (reader.Read())
                {
                    sqliteChecksum += ChecksumSqliteScalar16VarIdentityCurrent(reader, iterationMode);
                    sqliteReadIdentities++;
                }
            }
        }

        sqliteReadWatch.Stop();
        if (libraChecksum != sqliteChecksum)
        {
            throw new InvalidDataException($"SV16 comparison checksum mismatch. libra={libraChecksum} sqlite={sqliteChecksum}.");
        }

        double libraWriteItemsPerSecond = itemCount / libraWriteWatch.Elapsed.TotalSeconds;
        double sqliteWriteItemsPerSecond = itemCount / sqliteWriteWatch.Elapsed.TotalSeconds;
        double libraReadIdentitiesPerSecond = libraReadIdentities / libraReadWatch.Elapsed.TotalSeconds;
        double sqliteReadIdentitiesPerSecond = sqliteReadIdentities / sqliteReadWatch.Elapsed.TotalSeconds;
        Console.WriteLine($"iterationMode {iterationModeText}");
        Console.WriteLine("| engine | write items/sec | read identities/sec | write ratio vs sqlite | read ratio vs sqlite | growths | splits | duplicateRunOverflows | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| LibraDex SV16 | {libraWriteItemsPerSecond:F2} | {libraReadIdentitiesPerSecond:F2} | {libraWriteItemsPerSecond / sqliteWriteItemsPerSecond:F2} | {libraReadIdentitiesPerSecond / sqliteReadIdentitiesPerSecond:F2} | {libraGrowths} | {libraSplits} | {libraDuplicateRunOverflows} | {libraChecksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| SQLite | {sqliteWriteItemsPerSecond:F2} | {sqliteReadIdentitiesPerSecond:F2} | 1.00 | 1.00 | 0 | 0 | 0 | {sqliteChecksum} |"));
        if (includeAttribution)
        {
            double ticksToNsPerItem = 1_000_000_000d / Stopwatch.Frequency / itemCount;
            long attributedTicks =
                libraAttribution.RouteWalkTicks +
                libraAttribution.ShelfReadTicks +
                libraAttribution.DuplicateChainTicks +
                libraAttribution.MutationTicks +
                libraAttribution.StageTicks +
                libraAttribution.StructuralTicks;
            Console.WriteLine("| attribution | ticks | ns/item | percent |");
            Console.WriteLine("|---|---:|---:|---:|");
            PrintScalar16VarIdentityAttributionRow("route walk", libraAttribution.RouteWalkTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar16VarIdentityAttributionRow("shelf read", libraAttribution.ShelfReadTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar16VarIdentityAttributionRow("duplicate chain", libraAttribution.DuplicateChainTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar16VarIdentityAttributionRow("mutation", libraAttribution.MutationTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar16VarIdentityAttributionRow("stage", libraAttribution.StageTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar16VarIdentityAttributionRow("structural", libraAttribution.StructuralTicks, attributedTicks, ticksToNsPerItem);
            PrintScalar16VarIdentityAttributionRow("attributed total", attributedTicks, attributedTicks, ticksToNsPerItem);
        }

        return 0;
    }

    /// <summary>
    /// Creates one deterministic 16-byte scalar key for `SV16` harness populations.<br/>
    /// The duplicate modulo determines the logical key, while the distribution selects whether routing pressure starts in the low half or fans out by the first high byte.<br/>
    /// </summary>
    /// <param name="index">The source item index.</param>
    /// <param name="duplicateModulo">The number of generated duplicate-key groups.</param>
    /// <param name="keyDistribution">The key distribution name.</param>
    /// <param name="keyHigh">Receives the encoded high key half.</param>
    /// <param name="keyLow">Receives the encoded low key half.</param>
    private static void CreateScalar16VarIdentityKey(int index, int duplicateModulo, string keyDistribution, out ulong keyHigh, out ulong keyLow)
    {
        ulong logicalKey = checked((ulong)(index % duplicateModulo));
        if (keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase))
        {
            keyHigh = (logicalKey & 0xFFUL) << 56;
            keyLow = logicalKey;
            return;
        }

        keyHigh = 0;
        keyLow = logicalKey;
    }

    private static int CompareScalar16VarIdentityKey(ulong leftHigh, ulong leftLow, ulong rightHigh, ulong rightLow)
    {
        int high = leftHigh.CompareTo(rightHigh);
        return high != 0 ? high : leftLow.CompareTo(rightLow);
    }

    private static int[] CreateScalar16VarIdentityWriteOrder(
        int itemCount,
        int duplicateModulo,
        string order,
        int identityLength,
        bool fixedIdentityLength,
        string keyDistribution)
    {
        int[] result = new int[itemCount];
        for (int i = 0; i < itemCount; i++)
        {
            result[i] = i;
        }

        if (order.Equals("key-major", StringComparison.OrdinalIgnoreCase) ||
            order.Equals("tuple-major", StringComparison.OrdinalIgnoreCase))
        {
            Array.Sort(result, (left, right) =>
            {
                CreateScalar16VarIdentityKey(left, duplicateModulo, keyDistribution, out ulong leftHigh, out ulong leftLow);
                CreateScalar16VarIdentityKey(right, duplicateModulo, keyDistribution, out ulong rightHigh, out ulong rightLow);
                int keyComparison = CompareScalar16VarIdentityKey(leftHigh, leftLow, rightHigh, rightLow);
                if (keyComparison != 0 || order.Equals("key-major", StringComparison.OrdinalIgnoreCase))
                {
                    return keyComparison;
                }

                return Scalar16VarIdentityLayout.CompareIdentityBytes(
                    CreateScalar8VarIdentity(left, identityLength, fixedIdentityLength),
                    CreateScalar8VarIdentity(right, identityLength, fixedIdentityLength));
            });
        }

        return result;
    }

    /// <summary>
    /// Validates the first `VS8` varlen-key shelf primitive without routing.<br/>
    /// The command inserts raw byte keys through the growable shelf path, verifies sorted range reads, and checks duplicate/key-conflict behavior.<br/>
    /// This is intentionally inside-out: it proves persisted compact slots, runtime decoded slots, 7-bit key lengths, and shelf growth before route integration.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the shelf primitive validates.</returns>
    private static int RunVarKeyScalar8ShelfSanity(string[] args)
    {
        int itemCount = GetIntOption(args, "--items", 1800);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 shelf sanity requires positive items, key length 1-1024, and prefix count 1-256.");
        }

        VarKeyScalar8Profile profile = VarKeyScalar8Profile.DefaultInitial;
        byte[] shelfBytes = VarKeyScalar8.CreateEmpty(profile);
        for (int i = 0; i < itemCount; i++)
        {
            byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
            ulong identity = CreateVarKeyScalar8Identity(i);
            VarKeyScalar8InsertResult result = VarKeyScalar8.Insert(shelfBytes, profile, key, identity, allowDuplicateKeys: true, out byte[] rewritten);
            if (result == VarKeyScalar8InsertResult.Full &&
                VarKeyScalar8.TryGrowAndInsert(shelfBytes, profile, key, identity, allowDuplicateKeys: true, out VarKeyScalar8Profile grownProfile, out rewritten, out result))
            {
                profile = grownProfile;
            }

            if (result != VarKeyScalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected VS8 insert {i}, got {result} at profile {profile.ShelfExtentSize}.");
            }

            shelfBytes = rewritten;
        }

        VarKeyScalar8ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid || readOnly.ItemCount != itemCount)
        {
            throw new InvalidDataException($"VS8 shelf sanity produced invalid shelf or wrong count. valid={readOnly.IsValid} count={readOnly.ItemCount} expected={itemCount}.");
        }

        for (int i = 1; i < readOnly.ItemCount; i++)
        {
            if (readOnly.ReadKeyAt(i - 1).SequenceCompareTo(readOnly.ReadKeyAt(i)) > 0)
            {
                throw new InvalidDataException($"VS8 shelf order drifted at slot {i}.");
            }
        }

        int slotStreamLength = VarKeyScalar8Layout.ReadSlotStreamLength(shelfBytes);
        int slotCapacityBytes = VarKeyScalar8Layout.ReadSlotCapacityBytes(shelfBytes);
        int expectedSlotStreamLength = checked(readOnly.ItemCount * VarKeyScalar8Layout.SlotSize);
        int expectedSlotCapacityBytes = VarKeyScalar8Layout.CalculateSlotCapacityBytes(profile.ShelfExtentSize);
        int expectedFirstRecordOffset = VarKeyScalar8Layout.HeaderSize + slotCapacityBytes;
        int recordArenaEnd = VarKeyScalar8Layout.ReadRecordArenaEnd(shelfBytes);
        uint minRecordOffset = uint.MaxValue;
        uint maxRecordEnd = 0;
        for (int i = 0; i < readOnly.ItemCount; i++)
        {
            uint recordOffset = readOnly.ReadRecordOffsetAt(i);
            minRecordOffset = Math.Min(minRecordOffset, recordOffset);
            maxRecordEnd = Math.Max(maxRecordEnd, checked(recordOffset + (uint)VarKeyScalar8Layout.GetRecordLength(shelfBytes, checked((int)recordOffset))));
        }

        if (slotStreamLength != expectedSlotStreamLength ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            minRecordOffset != expectedFirstRecordOffset ||
            maxRecordEnd != recordArenaEnd)
        {
            throw new InvalidDataException($"VS8 shelf reserved-slot record layout failed. slots={slotStreamLength}/{expectedSlotStreamLength} slotCapacity={slotCapacityBytes}/{expectedSlotCapacityBytes} firstRecord={minRecordOffset}/{expectedFirstRecordOffset} arenaEnd={recordArenaEnd}/{maxRecordEnd}.");
        }

        byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
        VarKeyScalar8InsertResult duplicate = VarKeyScalar8.Insert(shelfBytes, profile, duplicateKey, CreateVarKeyScalar8Identity(0), allowDuplicateKeys: true, out _);
        if (duplicate != VarKeyScalar8InsertResult.AlreadyPresent)
        {
            throw new InvalidDataException($"Expected VS8 duplicate tuple no-op, got {duplicate}.");
        }

        VarKeyScalar8InsertResult keyConflict = VarKeyScalar8.Insert(shelfBytes, profile, duplicateKey, ulong.MaxValue, allowDuplicateKeys: false, out _);
        if (keyConflict != VarKeyScalar8InsertResult.KeyConflict)
        {
            throw new InvalidDataException($"Expected VS8 unique-key conflict, got {keyConflict}.");
        }

        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        ulong[] identities = new ulong[itemCount];
        int copied = readOnly.CopyIdentitiesInKeyRange(lower, upper, identities);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        if (copied != expected)
        {
            throw new InvalidDataException($"VS8 range read returned {copied} identities; expected {expected}.");
        }

        Console.WriteLine($"vs8-shelf-sanity ok items={itemCount} keyLength={keyLength} prefixCount={prefixCount} shelfSize={profile.ShelfExtentSize} rangeCount={copied}");
        return 0;
    }

    /// <summary>
    /// Validates the first `VV` variable-key/variable-identity shelf primitive without routing.<br/>
    /// The command inserts raw byte keys with raw byte identities, verifies key-primary tuple ordering, duplicate-key identity ordering, duplicate tuple no-op, unique-key conflict, reserved-slot layout, growth, and key-range identity reads.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the shelf primitive validates.</returns>
    private static int RunVarKeyVarIdentityShelfSanity(string[] args)
    {
        int itemCount = GetIntOption(args, "--items", 1500);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VV shelf sanity requires positive items, key length 1-1024, identity length 1-1024, and prefix count 1-256.");
        }

        VarKeyVarIdentityProfile profile = VarKeyVarIdentityProfile.DefaultInitial;
        byte[] shelfBytes = VarKeyVarIdentity.CreateEmpty(profile);
        for (int i = 0; i < itemCount; i++)
        {
            byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
            byte[] identity = CreateScalar8VarIdentity(i, identityLength);
            VarKeyVarIdentityInsertResult result = VarKeyVarIdentity.Insert(shelfBytes, profile, key, identity, allowDuplicateKeys: true, out byte[] rewritten);
            if (result == VarKeyVarIdentityInsertResult.Full &&
                VarKeyVarIdentity.TryGrowAndInsert(shelfBytes, profile, key, identity, allowDuplicateKeys: true, out VarKeyVarIdentityProfile grownProfile, out rewritten, out result))
            {
                profile = grownProfile;
            }

            if (result != VarKeyVarIdentityInsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected VV insert {i}, got {result} at profile {profile.ShelfExtentSize}.");
            }

            shelfBytes = rewritten;
        }

        VarKeyVarIdentityReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid || readOnly.ItemCount != itemCount)
        {
            throw new InvalidDataException($"VV shelf sanity produced invalid shelf or wrong count. valid={readOnly.IsValid} count={readOnly.ItemCount} expected={itemCount}.");
        }

        for (int i = 1; i < readOnly.ItemCount; i++)
        {
            int keyComparison = readOnly.ReadKeyAt(i - 1).SequenceCompareTo(readOnly.ReadKeyAt(i));
            if (keyComparison > 0)
            {
                throw new InvalidDataException($"VV key ordering drifted at slot {i}.");
            }

            if (keyComparison == 0 &&
                VarKeyVarIdentityLayout.CompareIdentityBytes(readOnly.ReadIdentityAt(i - 1), readOnly.ReadIdentityAt(i)) > 0)
            {
                throw new InvalidDataException($"VV duplicate-key identity ordering drifted at slot {i}.");
            }
        }

        int slotStreamLength = VarKeyVarIdentityLayout.ReadSlotStreamLength(shelfBytes);
        int slotCapacityBytes = VarKeyVarIdentityLayout.ReadSlotCapacityBytes(shelfBytes);
        int expectedSlotStreamLength = checked(readOnly.ItemCount * VarKeyVarIdentityLayout.SlotSize);
        int expectedSlotCapacityBytes = VarKeyVarIdentityLayout.CalculateSlotCapacityBytes(profile.ShelfExtentSize);
        int expectedFirstRecordOffset = VarKeyVarIdentityLayout.HeaderSize + slotCapacityBytes;
        int recordArenaEnd = VarKeyVarIdentityLayout.ReadRecordArenaEnd(shelfBytes);
        uint minRecordOffset = uint.MaxValue;
        uint maxRecordEnd = 0;
        for (int i = 0; i < readOnly.ItemCount; i++)
        {
            uint recordOffset = readOnly.ReadRecordOffsetAt(i);
            minRecordOffset = Math.Min(minRecordOffset, recordOffset);
            maxRecordEnd = Math.Max(maxRecordEnd, checked(recordOffset + (uint)VarKeyVarIdentityLayout.GetRecordLength(shelfBytes, checked((int)recordOffset))));
        }

        if (slotStreamLength != expectedSlotStreamLength ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            minRecordOffset != expectedFirstRecordOffset ||
            maxRecordEnd != recordArenaEnd)
        {
            throw new InvalidDataException($"VV shelf reserved-slot record layout failed. slots={slotStreamLength}/{expectedSlotStreamLength} slotCapacity={slotCapacityBytes}/{expectedSlotCapacityBytes} firstRecord={minRecordOffset}/{expectedFirstRecordOffset} arenaEnd={recordArenaEnd}/{maxRecordEnd}.");
        }

        byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
        byte[] duplicateIdentity = CreateScalar8VarIdentity(0, identityLength);
        VarKeyVarIdentityInsertResult duplicate = VarKeyVarIdentity.Insert(shelfBytes, profile, duplicateKey, duplicateIdentity, allowDuplicateKeys: true, out _);
        if (duplicate != VarKeyVarIdentityInsertResult.AlreadyPresent)
        {
            throw new InvalidDataException($"Expected VV duplicate tuple no-op, got {duplicate}.");
        }

        VarKeyVarIdentityInsertResult keyConflict = VarKeyVarIdentity.Insert(shelfBytes, profile, duplicateKey, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false, out _);
        if (keyConflict != VarKeyVarIdentityInsertResult.KeyConflict)
        {
            throw new InvalidDataException($"Expected VV unique-key conflict, got {keyConflict}.");
        }

        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int identityCount = 0;
        int rangeSlotIndex = readOnly.LowerBoundKey(lower);
        for (int i = rangeSlotIndex; i < readOnly.ItemCount; i++)
        {
            if (readOnly.ReadKeyAt(i).SequenceCompareTo(upper) > 0)
            {
                break;
            }

            identityCount++;
        }

        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        if (identityCount != expected)
        {
            throw new InvalidDataException($"VV range read returned {identityCount} identities; expected {expected}.");
        }

        Console.WriteLine($"vv-shelf-sanity ok items={itemCount} keyLength={keyLength} identityLength={identityLength} prefixCount={prefixCount} shelfSize={profile.ShelfExtentSize} rangeCount={identityCount}");
        return 0;
    }

    /// <summary>
    /// Validates the first session-backed routed `VV` path.<br/>
    /// The command inserts raw byte keys and raw byte identities through `LibraDexFileSession`, optionally creating root-prefix shelves lazily, then reopens the file and range-reads across prefixes.<br/>
    /// This is the routed correctness proof for variable-length keys and identities together, including growth, transform splits, and lazy first-prefix creation.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when routed persistence, duplicate no-op, key-conflict detection, reopen, and range read validate.</returns>
    private static int RunVarKeyVarIdentityRoutedSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vv-routed-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 2600);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int precreatePrefixCount = GetIntOption(args, "--precreate-prefix-count", prefixCount);
        int maxRouterHops = GetIntOption(args, "--max-router-hops", 8);
        LibraDexWriteIntent writeIntent = GetWriteIntentOption(args);
        bool hasExplicitInitialShelfKiB = HasOption(args, "--initial-shelf-kib");
        int requestedInitialShelfKiB = GetIntOption(args, "--initial-shelf-kib", 0);
        bool lazyRootPrefixes = GetBoolOption(args, "--lazy-root-prefixes", true);
        bool expectTransform = GetBoolOption(args, "--expect-transform", false);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024 || prefixCount <= 0 || prefixCount > 256 || precreatePrefixCount < prefixCount || precreatePrefixCount > 256 || maxRouterHops <= 0 || (hasExplicitInitialShelfKiB && requestedInitialShelfKiB <= 0))
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VV routed sanity requires positive items, key length 1-1024, identity length 1-1024, prefix count 1-256, precreate prefix count at least prefix count and at most 256, positive max router hops, and positive initial shelf KiB.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        VarKeyVarIdentityProfile initialProfile = hasExplicitInitialShelfKiB
            ? VarKeyVarIdentityProfile.Create(checked(requestedInitialShelfKiB * 1024), 1024, 1024)
            : VarKeyVarIdentityProfile.SelectInitial(writeIntent);
        int initialShelfKiB = initialProfile.ShelfExtentSize / 1024;
        long rootOffset;
        long lazyCreateCount = 0;
        long growCount = 0;
        long transformCount = 0;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(9171), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vvroute", 0));
            rootOffset = root.Offset;
            if (!lazyRootPrefixes)
            {
                for (int prefix = 0; prefix < precreatePrefixCount; prefix++)
                {
                    _ = session.CreateVarKeyVarIdentityShelfAndLinkRootRoute(rootOffset, (byte)prefix, initialProfile);
                }
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch(writeIntent);
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                VarKeyVarIdentityRoutedInsertResult result = session.InsertWalkedRoutedVarKeyVarIdentity(rootOffset, maxKeyLength: 1024, maxIdentityLength: 1024, key, identity, allowDuplicateKeys: true, maxRouterHops: maxRouterHops);
                if (result.InsertResult != VarKeyVarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed VV insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyVarIdentityRoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyVarIdentityRoutedInsertKind.WalkedCreatedInitialShelf)
                {
                    lazyCreateCount++;
                }

                if (result.Kind == VarKeyVarIdentityRoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                }
            }

            byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
            byte[] duplicateIdentity = CreateScalar8VarIdentity(0, identityLength);
            VarKeyVarIdentityRoutedInsertResult duplicate = session.InsertWalkedRoutedVarKeyVarIdentity(rootOffset, 1024, 1024, duplicateKey, duplicateIdentity, allowDuplicateKeys: true, maxRouterHops: maxRouterHops);
            if (duplicate.InsertResult != VarKeyVarIdentityInsertResult.AlreadyPresent)
            {
                throw new InvalidDataException($"Expected routed VV duplicate no-op, got {duplicate.Kind}/{duplicate.InsertResult}.");
            }

            VarKeyVarIdentityRoutedInsertResult conflict = session.InsertWalkedRoutedVarKeyVarIdentity(rootOffset, 1024, 1024, duplicateKey, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false, maxRouterHops: maxRouterHops);
            if (conflict.InsertResult != VarKeyVarIdentityInsertResult.KeyConflict)
            {
                throw new InvalidDataException($"Expected routed VV key conflict, got {conflict.Kind}/{conflict.InsertResult}.");
            }

            _ = durabilityBatch.Commit();
        }

        if (expectTransform && transformCount == 0)
        {
            throw new InvalidDataException("Expected at least one routed VV shelf transform split, but the insert run completed with zero transforms.");
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            using VarKeyVarIdentityRangeReader reader = reopened.OpenVarKeyVarIdentityRangeReader(rootOffset, maxKeyLength: 1024, maxIdentityLength: 1024, lower, upper);
            int identityCount = reader.Count;
            int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
            if (identityCount != expected)
            {
                throw new InvalidDataException($"Routed VV range returned {identityCount} identities; expected {expected}.");
            }

            long checksum = 0;
            while (reader.MoveNext())
            {
                checksum += ChecksumBytes(reader.CurrentIdentity);
            }

            byte[] exactKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
            bool deletedExact = reopened.DeleteVarKeyVarIdentityExactTuple(rootOffset, maxKeyLength: 1024, maxIdentityLength: 1024, exactKey, CreateScalar8VarIdentity(0, identityLength));
            if (!deletedExact)
            {
                throw new InvalidDataException("Routed VV exact tuple delete did not delete the expected tuple.");
            }

            using (VarKeyVarIdentityRangeReader afterExactDeleteReader = reopened.OpenVarKeyVarIdentityRangeReader(rootOffset, 1024, 1024, exactKey, exactKey))
            {
                if (afterExactDeleteReader.Count != 0)
                {
                    throw new InvalidDataException($"Routed VV exact tuple delete left {afterExactDeleteReader.Count} rows for the exact key.");
                }
            }

            long rangeDeleted = reopened.DeleteVarKeyVarIdentityKeyRange(rootOffset, maxKeyLength: 1024, maxIdentityLength: 1024, lower, upper);
            if (rangeDeleted != expected - 1)
            {
                throw new InvalidDataException($"Routed VV range delete removed {rangeDeleted}; expected {expected - 1} after the exact delete.");
            }

            using (VarKeyVarIdentityRangeReader afterRangeDeleteReader = reopened.OpenVarKeyVarIdentityRangeReader(rootOffset, 1024, 1024, lower, upper))
            {
                if (afterRangeDeleteReader.Count != 0)
                {
                    throw new InvalidDataException($"Routed VV range delete left {afterRangeDeleteReader.Count} rows in the deleted range.");
                }
            }

            Console.WriteLine($"vv-routed-sanity ok path={path} items={itemCount} keyLength={keyLength} identityLength={identityLength} prefixCount={prefixCount} precreatePrefixCount={precreatePrefixCount} initialShelfKiB={initialShelfKiB} writeIntent={DescribeWriteIntent(writeIntent)} lazyRootPrefixes={lazyRootPrefixes} lazyCreates={lazyCreateCount} growths={growCount} transforms={transformCount} rangeCount={identityCount} rangeDeleted={rangeDeleted} checksum={checksum}");
        }

        return 0;
    }

    /// <summary>
    /// Validates that lazy `VV` root-prefix shelf creation is scoped to the active durability batch.<br/>
    /// The command inserts one tuple into an unset root prefix, aborts the batch, verifies the route is unset after abort, then repeats the insert and commits so reopen proves the lazy route and shelf publish normally.<br/>
    /// This guards the create-on-first-prefix path against leaking pending shelf/router writes when callers dispose or abort a batch before publication.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when abort discards the lazy-created route and commit persists the later lazy-created route.</returns>
    private static int RunVarKeyVarIdentityLazyRootAbortSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vv-lazy-root-abort-sanity.lbdx"));
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        if (keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VV lazy root abort sanity requires key and identity lengths from 1-1024.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        byte[] key = CreateVarKeyScalar8Key(0, keyLength, prefixCount: 16);
        byte[] identity = CreateScalar8VarIdentity(0, identityLength);
        byte rootPrefix = key[0];
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long committedShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(9174), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vvlabort", 0));
            rootOffset = root.Offset;
            using (LibraDexFileSessionDurabilityBatch abortBatch = session.BeginDurabilityBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.Compactness)))
            {
                VarKeyVarIdentityRoutedInsertResult result = session.InsertWalkedRoutedVarKeyVarIdentity(rootOffset, 1024, 1024, key, identity, allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.Kind != VarKeyVarIdentityRoutedInsertKind.WalkedCreatedInitialShelf || result.InsertResult != VarKeyVarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected aborted lazy VV insert to create an initial shelf, got {result.Kind}/{result.InsertResult}.");
                }

                _ = abortBatch.Abort();
            }

            long abortedTarget = session.FindRouterTarget(rootOffset, rootPrefix);
            if (abortedTarget != 0)
            {
                throw new InvalidDataException("Aborted lazy VV root-prefix creation left a route target behind.");
            }

            using (LibraDexFileSessionDurabilityBatch commitBatch = session.BeginDurabilityBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.Compactness)))
            {
                VarKeyVarIdentityRoutedInsertResult result = session.InsertWalkedRoutedVarKeyVarIdentity(rootOffset, 1024, 1024, key, identity, allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.Kind != VarKeyVarIdentityRoutedInsertKind.WalkedCreatedInitialShelf || result.InsertResult != VarKeyVarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected committed lazy VV insert to create an initial shelf, got {result.Kind}/{result.InsertResult}.");
                }

                _ = commitBatch.Commit();
                committedShelfOffset = result.NewOffset;
            }
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            long reopenedTarget = reopened.FindRouterTarget(rootOffset, rootPrefix);
            if (reopenedTarget != committedShelfOffset)
            {
                throw new InvalidDataException($"Reopened lazy VV route target {reopenedTarget} did not match committed shelf {committedShelfOffset}.");
            }

            using VarKeyVarIdentityRangeReader reader = reopened.OpenVarKeyVarIdentityRangeReader(rootOffset, 1024, 1024, key, key);
            if (reader.Count != 1 || !reader.MoveNext() || !VarKeyVarIdentityLayout.IdentityBytesEqual(reader.CurrentIdentity, identity))
            {
                throw new InvalidDataException("Reopened lazy VV range did not return the committed identity.");
            }
        }

        Console.WriteLine($"vv-lazy-root-abort-sanity ok path={path} root={rootOffset} prefix={rootPrefix:X2} committedShelf={committedShelfOffset}");
        return 0;
    }

    /// <summary>
    /// Validates the first public raw-byte `VV` index facade.<br/>
    /// The command creates a public `Indexes.VV` index, inserts through the public batch API, verifies duplicate no-op and duplicate-key conflict behavior, reads a range before and after reopen, and checks `CreateOrOpen` returns the existing slot.<br/>
    /// This keeps API promotion covered without moving codec or generic decisions into the raw varlen shape.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when public create, batch insert, range read, reopen, and create-or-open behavior validate.</returns>
    private static int RunVarKeyVarIdentityIndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vv-index-api-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 512);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VV public API sanity requires positive items, key length 1-1024, identity length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long lazyRouteCreates;
        long deferredCommitRequests;
        using (VarKeyVarIdentityIndex index = Indexes.VV.Create(
            path,
            name: "vv-api",
            maxKeyLength: 1024,
            maxIdentityLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9175),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            rootOffset = index.RootRouterOffset;
            using (VarKeyVarIdentityBatch batch = index.BeginBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.WriteSpeed)))
            {
                lazyRouteCreates = 0;
                for (int i = 0; i < itemCount; i++)
                {
                    byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                    byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                    VarKeyVarIdentityIndexInsertResult result = batch.Insert(key, identity);
                    if (!result.Inserted)
                    {
                        throw new InvalidDataException($"Expected public VV insert {i}, got inserted={result.Inserted} already={result.AlreadyPresent} conflict={result.KeyConflict}.");
                    }

                    if (result.CreatedInitialShelfRoute)
                    {
                        lazyRouteCreates++;
                    }
                }

                byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
                byte[] duplicateIdentity = CreateScalar8VarIdentity(0, identityLength);
                VarKeyVarIdentityIndexInsertResult duplicate = batch.Insert(duplicateKey, duplicateIdentity);
                if (!duplicate.AlreadyPresent)
                {
                    throw new InvalidDataException("Expected public VV duplicate tuple to be reported as already present.");
                }

                VarKeyVarIdentityIndexInsertResult conflict = batch.Insert(duplicateKey, CreateScalar8VarIdentity(itemCount + 1, identityLength), allowDuplicateKeys: false);
                if (!conflict.KeyConflict)
                {
                    throw new InvalidDataException("Expected public VV duplicate key to be rejected when duplicate keys are disabled.");
                }

                VarKeyVarIdentityBatchCommitResult commit = batch.Commit();
                deferredCommitRequests = commit.DeferredCommitRequests;
                if (commit.AttemptedInsertCount != itemCount + 2 || commit.InsertedCount != itemCount || commit.AlreadyPresentCount != 1 || commit.KeyConflictCount != 1)
                {
                    throw new InvalidDataException($"Unexpected public VV batch counts: attempted={commit.AttemptedInsertCount} inserted={commit.InsertedCount} already={commit.AlreadyPresentCount} conflicts={commit.KeyConflictCount}.");
                }
            }

            _ = index.Insert((byte[]?)null, new byte[] { 0x91, 0x01 });
            _ = index.Insert(Array.Empty<byte>(), new byte[] { 0x91, 0x02 });
            _ = index.Insert(new byte[] { 0x00 }, new byte[] { 0x91, 0x03 });

            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            using VarKeyVarIdentityRangeReader reader = index.OpenRangeReader(lower, upper);
            int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public VV reader before reopen returned {reader.Count}; expected {expected}.");
            }
        }

        using (VarKeyVarIdentityIndex reopened = Indexes.VV.Open(
            path,
            maxKeyLength: 1024,
            maxIdentityLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (reopened.RootRouterOffset != rootOffset || reopened.Name != "vv-api")
            {
                throw new InvalidDataException("Reopened public VV index did not preserve root offset and name.");
            }

            using (VarKeyVarIdentityRangeReader sentinelReader = reopened.OpenRangeReader((byte[]?)null, new byte[] { 0x00 }))
            {
                if (sentinelReader.Count != 3)
                {
                    throw new InvalidDataException($"Public VV sentinel range returned {sentinelReader.Count}; expected 3.");
                }

                if (!sentinelReader.MoveNext() || !sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 0 || !sentinelReader.CurrentIdentity.SequenceEqual(new byte[] { 0x91, 0x01 }))
                {
                    throw new InvalidDataException("Public VV sentinel reader did not expose the null key first.");
                }

                if (!sentinelReader.MoveNext() || sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 0 || !sentinelReader.CurrentIdentity.SequenceEqual(new byte[] { 0x91, 0x02 }))
                {
                    throw new InvalidDataException("Public VV sentinel reader did not distinguish empty key from null key.");
                }

                if (!sentinelReader.MoveNext() || sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 1 || sentinelReader.CurrentKey[0] != 0x00 || !sentinelReader.CurrentIdentity.SequenceEqual(new byte[] { 0x91, 0x03 }))
                {
                    throw new InvalidDataException("Public VV sentinel reader did not expose the non-empty key after null and empty.");
                }
            }

            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            using VarKeyVarIdentityRangeReader reader = reopened.OpenRangeReader(lower, upper);
            int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public VV reader after reopen returned {reader.Count}; expected {expected}.");
            }

            using VarKeyVarIdentityRangeReader skipReader = reopened.OpenRangeReader(lower, upper);
            int expectedSkip = Math.Min(2, expected);
            if (skipReader.Skip(2) != expectedSkip)
            {
                throw new InvalidDataException("Public VV reader did not report the expected skipped row count.");
            }

            long checksum = 0;
            long keyChecksum = 0;
            int readCount = 0;
            Span<byte> keyScratch = stackalloc byte[keyLength];
            Span<byte> identityScratch = stackalloc byte[1024];
            while (reader.MoveNext())
            {
                if (reader.CurrentIdentityLength <= 0 || reader.CurrentIdentityLength > identityLength)
                {
                    throw new InvalidDataException("Public VV reader returned an identity length outside the expected bounds.");
                }

                if (readCount == 0 &&
                    (reader.CopyCurrentKeyTo(keyScratch) != reader.CurrentKeyLength ||
                     reader.CopyCurrentIdentityTo(identityScratch) != reader.CurrentIdentityLength))
                {
                    throw new InvalidDataException("Public VV reader copied an unexpected key or identity length.");
                }

                keyChecksum += ChecksumBytes(reader.CurrentKey);
                checksum += ChecksumBytes(reader.CurrentIdentity);
                readCount++;
            }

            if (readCount != expected)
            {
                throw new InvalidDataException($"Public VV reader enumerated {readCount}; expected {expected}.");
            }

            using LibraDexVarIdentityBuffer identityBuffer = reopened.ReadIdentityBuffer(lower, upper);
            if (identityBuffer.Count != expected || identityBuffer.PayloadLength <= 0)
            {
                throw new InvalidDataException("Public VV identity buffer did not report the expected count and payload length.");
            }

            long bufferChecksum = 0;
            long enumeratorChecksum = 0;
            for (int i = 0; i < identityBuffer.Count; i++)
            {
                ReadOnlySpan<byte> identity = identityBuffer[i];
                if (identity.Length <= 0 || identity.Length > identityLength)
                {
                    throw new InvalidDataException("Public VV identity buffer returned an identity length outside the expected bounds.");
                }

                int identityOffset = identityBuffer.GetOffset(i);
                int reportedLength = identityBuffer.GetLength(i);
                if (reportedLength != identity.Length || identityOffset < 0 || identityOffset + reportedLength > identityBuffer.PayloadLength)
                {
                    throw new InvalidDataException("Public VV identity buffer returned inconsistent offset/length metadata.");
                }

                if (!identityBuffer.PayloadSpan.Slice(identityOffset, reportedLength).SequenceEqual(identity))
                {
                    throw new InvalidDataException("Public VV identity buffer flat payload did not match indexed identity access.");
                }

                if (i == 0 && !identityBuffer.TryCopyTo(i, identityScratch))
                {
                    throw new InvalidDataException("Public VV identity buffer failed to copy the first identity to caller storage.");
                }

                if (i == 0)
                {
                    identityBuffer.CopyTo(i, identityScratch);
                }

                bufferChecksum += ChecksumBytes(identity);
            }

            foreach (ReadOnlySpan<byte> identity in identityBuffer)
            {
                enumeratorChecksum += ChecksumBytes(identity);
            }

            if (bufferChecksum != checksum || enumeratorChecksum != checksum || identityBuffer.GetMemory(0).Length != identityBuffer[0].Length || identityBuffer.PayloadMemory.Length != identityBuffer.PayloadLength)
            {
                throw new InvalidDataException("Public VV identity buffer did not match streaming reader results.");
            }

            using LibraDexVarKeyBuffer keyBuffer = reopened.ReadKeyBuffer(lower, upper, expected * keyLength);
            if (keyBuffer.Count != expected || keyBuffer.PayloadLength != expected * keyLength)
            {
                throw new InvalidDataException("Public VV key buffer did not report the expected count and payload length.");
            }

            long keyBufferChecksum = 0;
            long keyEnumeratorChecksum = 0;
            for (int i = 0; i < keyBuffer.Count; i++)
            {
                ReadOnlySpan<byte> key = keyBuffer[i];
                if (key.Length != keyLength)
                {
                    throw new InvalidDataException("Public VV key buffer returned an unexpected key length.");
                }

                int keyOffset = keyBuffer.GetOffset(i);
                int reportedLength = keyBuffer.GetLength(i);
                if (reportedLength != key.Length || keyOffset < 0 || keyOffset + reportedLength > keyBuffer.PayloadLength)
                {
                    throw new InvalidDataException("Public VV key buffer returned inconsistent offset/length metadata.");
                }

                if (!keyBuffer.PayloadSpan.Slice(keyOffset, reportedLength).SequenceEqual(key))
                {
                    throw new InvalidDataException("Public VV key buffer flat payload did not match indexed key access.");
                }

                if (i == 0 && !keyBuffer.TryCopyTo(i, keyScratch))
                {
                    throw new InvalidDataException("Public VV key buffer failed to copy the first key to caller storage.");
                }

                if (i == 0)
                {
                    keyBuffer.CopyTo(i, keyScratch);
                }

                keyBufferChecksum += ChecksumBytes(key);
            }

            foreach (ReadOnlySpan<byte> key in keyBuffer)
            {
                keyEnumeratorChecksum += ChecksumBytes(key);
            }

            if (keyBufferChecksum != keyChecksum || keyEnumeratorChecksum != keyChecksum || keyBuffer.GetMemory(0).Length != keyBuffer[0].Length || keyBuffer.PayloadMemory.Length != keyBuffer.PayloadLength)
            {
                throw new InvalidDataException("Public VV key buffer did not match streaming reader results.");
            }

            using LibraDexVarKeyIdentityBuffer tupleBuffer = reopened.ReadTupleBuffer(lower, upper, expected * keyLength, expected * identityLength);
            if (tupleBuffer.Count != expected || tupleBuffer.KeyPayloadLength != expected * keyLength || tupleBuffer.IdentityPayloadLength <= 0)
            {
                throw new InvalidDataException("Public VV tuple buffer did not report the expected count and payload lengths.");
            }

            if (tupleBuffer.Keys.Count != expected || tupleBuffer.Identities.Count != expected)
            {
                throw new InvalidDataException("Public VV tuple buffer child buffers did not preserve the tuple count.");
            }

            long tupleKeyChecksum = 0;
            long tupleIdentityChecksum = 0;
            for (int i = 0; i < tupleBuffer.Count; i++)
            {
                tupleBuffer.GetTuple(i, out ReadOnlySpan<byte> tupleKey, out ReadOnlySpan<byte> tupleIdentity);
                if (tupleKey.Length != keyLength || tupleIdentity.Length <= 0 || tupleIdentity.Length > identityLength)
                {
                    throw new InvalidDataException("Public VV tuple buffer returned an unexpected tuple component length.");
                }

                if (!tupleKey.SequenceEqual(keyBuffer[i]) || !tupleIdentity.SequenceEqual(identityBuffer[i]))
                {
                    throw new InvalidDataException("Public VV tuple buffer did not match independent key and identity buffers.");
                }

                if (i == 0 && !tupleBuffer.TryCopyTo(i, keyScratch, identityScratch))
                {
                    throw new InvalidDataException("Public VV tuple buffer failed to copy the first tuple to caller storage.");
                }

                if (i == 0)
                {
                    tupleBuffer.CopyTo(i, keyScratch, identityScratch);
                }

                tupleKeyChecksum += ChecksumBytes(tupleBuffer.GetKeySpan(i));
                tupleIdentityChecksum += ChecksumBytes(tupleBuffer.GetIdentitySpan(i));
            }

            long tupleEnumeratorKeyChecksum = 0;
            long tupleEnumeratorIdentityChecksum = 0;
            foreach (LibraDexVarKeyIdentitySpan tuple in tupleBuffer)
            {
                tupleEnumeratorKeyChecksum += ChecksumBytes(tuple.Key);
                tupleEnumeratorIdentityChecksum += ChecksumBytes(tuple.Identity);
            }

            if (tupleKeyChecksum != keyChecksum ||
                tupleIdentityChecksum != checksum ||
                tupleEnumeratorKeyChecksum != keyChecksum ||
                tupleEnumeratorIdentityChecksum != checksum)
            {
                throw new InvalidDataException("Public VV tuple buffer did not match streaming reader checksums.");
            }

            byte[] exactDeleteKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
            if (!reopened.DeleteExactTuple(exactDeleteKey, CreateScalar8VarIdentity(0, identityLength)))
            {
                throw new InvalidDataException("Internal VV exact tuple delete did not remove the expected tuple.");
            }

            long rangeDeleted = reopened.DeleteRange(lower, upper);
            if (rangeDeleted != expected - 1)
            {
                throw new InvalidDataException($"Internal VV range delete removed {rangeDeleted}; expected {expected - 1} after exact delete.");
            }

            using VarKeyVarIdentityRangeReader afterDeleteReader = reopened.OpenRangeReader(lower, upper);
            if (afterDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Internal VV range delete left {afterDeleteReader.Count} rows in the deleted range.");
            }

            Console.WriteLine($"vv-index-api-sanity ok path={path} root={rootOffset} items={itemCount} keyLength={keyLength} identityLength={identityLength} prefixCount={prefixCount} lazyCreates={lazyRouteCreates} deferredCommits={deferredCommitRequests} rangeCount={reader.Count} checksum={checksum}");
        }

        using (VarKeyVarIdentityIndex openedAgain = Indexes.VV.CreateOrOpen(
            path,
            maxKeyLength: 1024,
            maxIdentityLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedAgain.RootRouterOffset != rootOffset)
            {
                throw new InvalidDataException("CreateOrOpen public VV did not return the existing root router offset.");
            }
        }

        return 0;
    }

    /// <summary>
    /// Validates the first `VS16` varlen-key and 16-byte identity shelf primitive without routing.<br/>
    /// This is a clone-first sanity layer for `VarKeyScalar16`: it proves persisted high/low identity bytes, tuple ordering, duplicate detection, key-conflict detection, reserved slots, and range copying before session/routing integration starts.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the shelf primitive validates.</returns>
    private static int RunVarKeyScalar16ShelfSanity(string[] args)
    {
        int itemCount = GetIntOption(args, "--items", 1500);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS16 shelf sanity requires positive items, key length 1-1024, and prefix count 1-256.");
        }

        VarKeyScalar16Profile profile = VarKeyScalar16Profile.DefaultInitial;
        byte[] shelfBytes = VarKeyScalar16.CreateEmpty(profile);
        for (int i = 0; i < itemCount; i++)
        {
            byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
            CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
            VarKeyScalar16InsertResult result = VarKeyScalar16.Insert(shelfBytes, profile, key, identityHigh, identityLow, allowDuplicateKeys: true, out byte[] rewritten);
            if (result == VarKeyScalar16InsertResult.Full &&
                VarKeyScalar16.TryGrowAndInsert(shelfBytes, profile, key, identityHigh, identityLow, allowDuplicateKeys: true, out VarKeyScalar16Profile grownProfile, out rewritten, out result))
            {
                profile = grownProfile;
            }

            if (result != VarKeyScalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected VS16 insert {i}, got {result} at profile {profile.ShelfExtentSize}.");
            }

            shelfBytes = rewritten;
        }

        VarKeyScalar16ReadOnly readOnly = new(shelfBytes, profile);
        if (!readOnly.IsValid || readOnly.ItemCount != itemCount)
        {
            throw new InvalidDataException($"VS16 shelf sanity produced invalid shelf or wrong count. valid={readOnly.IsValid} count={readOnly.ItemCount} expected={itemCount}.");
        }

        for (int i = 1; i < readOnly.ItemCount; i++)
        {
            readOnly.ReadIdentityAt(i - 1, out ulong previousHigh, out ulong previousLow);
            readOnly.ReadIdentityAt(i, out ulong currentHigh, out ulong currentLow);
            if (CompareVarKeyScalar16Tuple(readOnly.ReadKeyAt(i - 1), previousHigh, previousLow, readOnly.ReadKeyAt(i), currentHigh, currentLow) >= 0)
            {
                throw new InvalidDataException($"VS16 shelf tuple order drifted at slot {i}.");
            }
        }

        int slotStreamLength = VarKeyScalar16Layout.ReadSlotStreamLength(shelfBytes);
        int slotCapacityBytes = VarKeyScalar16Layout.ReadSlotCapacityBytes(shelfBytes);
        int expectedSlotStreamLength = checked(readOnly.ItemCount * VarKeyScalar16Layout.SlotSize);
        int expectedSlotCapacityBytes = VarKeyScalar16Layout.CalculateSlotCapacityBytes(profile.ShelfExtentSize);
        int expectedFirstRecordOffset = VarKeyScalar16Layout.HeaderSize + slotCapacityBytes;
        int recordArenaEnd = VarKeyScalar16Layout.ReadRecordArenaEnd(shelfBytes);
        uint minRecordOffset = uint.MaxValue;
        uint maxRecordEnd = 0;
        for (int i = 0; i < readOnly.ItemCount; i++)
        {
            uint recordOffset = readOnly.ReadRecordOffsetAt(i);
            minRecordOffset = Math.Min(minRecordOffset, recordOffset);
            maxRecordEnd = Math.Max(maxRecordEnd, checked(recordOffset + (uint)VarKeyScalar16Layout.GetRecordLength(shelfBytes, checked((int)recordOffset))));
        }

        if (slotStreamLength != expectedSlotStreamLength ||
            slotCapacityBytes != expectedSlotCapacityBytes ||
            minRecordOffset != expectedFirstRecordOffset ||
            maxRecordEnd != recordArenaEnd)
        {
            throw new InvalidDataException($"VS16 shelf reserved-slot record layout failed. slots={slotStreamLength}/{expectedSlotStreamLength} slotCapacity={slotCapacityBytes}/{expectedSlotCapacityBytes} firstRecord={minRecordOffset}/{expectedFirstRecordOffset} arenaEnd={recordArenaEnd}/{maxRecordEnd}.");
        }

        byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
        CreateVarKeyScalar16Identity(0, out ulong duplicateHigh, out ulong duplicateLow);
        VarKeyScalar16InsertResult duplicate = VarKeyScalar16.Insert(shelfBytes, profile, duplicateKey, duplicateHigh, duplicateLow, allowDuplicateKeys: true, out _);
        if (duplicate != VarKeyScalar16InsertResult.AlreadyPresent)
        {
            throw new InvalidDataException($"Expected VS16 duplicate tuple no-op, got {duplicate}.");
        }

        VarKeyScalar16InsertResult keyConflict = VarKeyScalar16.Insert(shelfBytes, profile, duplicateKey, ulong.MaxValue, ulong.MaxValue, allowDuplicateKeys: false, out _);
        if (keyConflict != VarKeyScalar16InsertResult.KeyConflict)
        {
            throw new InvalidDataException($"Expected VS16 unique-key conflict, got {keyConflict}.");
        }

        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        ulong[] identityHighs = new ulong[itemCount];
        ulong[] identityLows = new ulong[itemCount];
        int copied = readOnly.CopyIdentitiesInKeyRange(lower, upper, identityHighs, identityLows);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        if (copied != expected)
        {
            throw new InvalidDataException($"VS16 range read returned {copied} identities; expected {expected}.");
        }

        Console.WriteLine($"vs16-shelf-sanity ok items={itemCount} keyLength={keyLength} prefixCount={prefixCount} shelfSize={profile.ShelfExtentSize} rangeCount={copied}");
        return 0;
    }

    /// <summary>
    /// Validates the first session-backed routed `VS16` path before transform splits are cloned from `VS8`.<br/>
    /// The command intentionally uses a no-split/grow-sized workload so it proves root linking, walked route lookup, mutable shelf staging, batch commit, reopen, and range copying for 16-byte identities without depending on the later full-shelf transform path.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when routed persistence, reopen, and range read validate.</returns>
    private static int RunVarKeyScalar16RoutedSanity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS16RoutedSanity"));
        int itemCount = GetIntOption(args, "--items", 1200);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int progressInterval = GetIntOption(args, "--progress-interval", 0);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS16 routed sanity requires positive items, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(directory);
        string path = Path.Combine(directory, "vs16-routed-sanity.lbdx");
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long growCount = 0;
        long transformCount = 0;
        TimeSpan insertElapsed;
        TimeSpan commitElapsed;
        TimeSpan rangeElapsed;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(916), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16rt", 0));
            rootOffset = root.Offset;
            for (int prefix = 0; prefix < prefixCount; prefix++)
            {
                _ = session.CreateVarKeyScalar16ShelfAndLinkRootRoute(rootOffset, (byte)prefix, VarKeyScalar16Profile.DefaultInitial);
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            Stopwatch insertWatch = Stopwatch.StartNew();
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(rootOffset, maxKeyLength: 1024, key, identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected VS16 routed insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                }

                if (progressInterval > 0 && ((i + 1) % progressInterval == 0 || i + 1 == itemCount))
                {
                    Console.WriteLine(FormattableString.Invariant($"progress inserted {i + 1} growths {growCount} transforms {transformCount} insertMs {insertWatch.Elapsed.TotalMilliseconds:F2}"));
                }
            }

            insertWatch.Stop();
            insertElapsed = insertWatch.Elapsed;
            Stopwatch commitWatch = Stopwatch.StartNew();
            _ = durabilityBatch.Commit();
            commitWatch.Stop();
            commitElapsed = commitWatch.Elapsed;
        }

        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        ulong[] identityHighs = new ulong[itemCount];
        ulong[] identityLows = new ulong[itemCount];
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            Stopwatch rangeWatch = Stopwatch.StartNew();
            int copied = reopened.ReadVarKeyScalar16IdentityRange(rootOffset, maxKeyLength: 1024, lower, upper, identityHighs, identityLows);
            rangeWatch.Stop();
            rangeElapsed = rangeWatch.Elapsed;
            if (copied != expected)
            {
                throw new InvalidDataException($"VS16 routed range copied {copied} identities, expected {expected}.");
            }

            for (int i = 0; i < copied; i++)
            {
                if (identityHighs[i] == 0 || identityLows[i] == 0)
                {
                    throw new InvalidDataException("VS16 routed range returned an unset identity half.");
                }
            }
        }

        Console.WriteLine("vs16 routed sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"growths {growCount}");
        Console.WriteLine($"transforms {transformCount}");
        Console.WriteLine(FormattableString.Invariant($"insertMs {insertElapsed.TotalMilliseconds:F2}"));
        Console.WriteLine(FormattableString.Invariant($"commitMs {commitElapsed.TotalMilliseconds:F2}"));
        Console.WriteLine(FormattableString.Invariant($"rangeMs {rangeElapsed.TotalMilliseconds:F2}"));
        Console.WriteLine($"rangeCount {expected}");
        Console.WriteLine("vs16-routed-sanity ok");
        return 0;
    }

    /// <summary>
    /// Validates the first public raw-byte `VS8` index facade.<br/>
    /// The command creates a public `Indexes.VS8` index, inserts through the public batch API with lazy root-prefix shelves, verifies duplicate no-op and duplicate-key conflict behavior, reads a range before and after reopen, and checks `CreateOrOpen` returns the existing slot.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when public create, batch insert, range read, reopen, and create-or-open behavior validate.</returns>
    private static int RunVarKeyScalar8IndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs8-index-api-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 512);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 public API sanity requires positive items, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long lazyRouteCreates;
        long deferredCommitRequests;
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        using (VarKeyScalar8Index index = Indexes.VS8.Create(
            path,
            name: "vs8-api",
            maxKeyLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9176),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            rootOffset = index.RootRouterOffset;
            using (VarKeyScalar8Batch batch = index.BeginBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.WriteSpeed)))
            {
                lazyRouteCreates = 0;
                for (int i = 0; i < itemCount; i++)
                {
                    byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                    VarKeyScalar8InsertOutcome result = batch.Insert(key, CreateVarKeyScalar8Identity(i));
                    if (!result.Inserted)
                    {
                        throw new InvalidDataException($"Expected public VS8 insert {i}, got inserted={result.Inserted} already={result.AlreadyPresent} conflict={result.KeyConflict}.");
                    }

                    if (result.CreatedInitialShelfRoute)
                    {
                        lazyRouteCreates++;
                    }
                }

                byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
                VarKeyScalar8InsertOutcome duplicate = batch.Insert(duplicateKey, CreateVarKeyScalar8Identity(0));
                if (!duplicate.AlreadyPresent)
                {
                    throw new InvalidDataException("Expected public VS8 duplicate tuple to be reported as already present.");
                }

                VarKeyScalar8InsertOutcome conflict = batch.Insert(duplicateKey, ulong.MaxValue, allowDuplicateKeys: false);
                if (!conflict.KeyConflict)
                {
                    throw new InvalidDataException("Expected public VS8 duplicate key to be rejected when duplicate keys are disabled.");
                }

                VarKeyScalarBatchCommitResult commit = batch.Commit();
                deferredCommitRequests = commit.DeferredCommitRequests;
                if (commit.AttemptedInsertCount != itemCount + 2 || commit.InsertedCount != itemCount || commit.AlreadyPresentCount != 1 || commit.KeyConflictCount != 1)
                {
                    throw new InvalidDataException($"Unexpected public VS8 batch counts: attempted={commit.AttemptedInsertCount} inserted={commit.InsertedCount} already={commit.AlreadyPresentCount} conflicts={commit.KeyConflictCount}.");
                }
            }

            _ = index.Insert((byte[]?)null, 9_000_001UL);
            _ = index.Insert(Array.Empty<byte>(), 9_000_002UL);
            _ = index.Insert(new byte[] { 0x00 }, 9_000_003UL);

            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            ulong[] identities = new ulong[itemCount];
            int copied = index.ReadRange(lower, upper, identities);
            if (copied != expected)
            {
                throw new InvalidDataException($"Public VS8 range before reopen returned {copied}; expected {expected}.");
            }

            using VarKeyScalar8RangeReader reader = index.OpenRangeReader(lower, upper);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public VS8 reader count before reopen returned {reader.Count}; expected {expected}.");
            }
        }

        long checksum = 0;
        using (VarKeyScalar8Index reopened = Indexes.VS8.Open(
            path,
            maxKeyLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (reopened.RootRouterOffset != rootOffset || reopened.Name != "vs8-api")
            {
                throw new InvalidDataException("Reopened public VS8 index did not preserve root offset and name.");
            }

            using (VarKeyScalar8RangeReader sentinelReader = reopened.OpenRangeReader((byte[]?)null, new byte[] { 0x00 }))
            {
                if (sentinelReader.Count != 3)
                {
                    throw new InvalidDataException($"Public VS8 sentinel range returned {sentinelReader.Count}; expected 3.");
                }

                if (!sentinelReader.MoveNext() || !sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 0 || sentinelReader.CurrentEncodedIdentity != 9_000_001UL)
                {
                    throw new InvalidDataException("Public VS8 sentinel reader did not expose the null key first.");
                }

                if (!sentinelReader.MoveNext() || sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 0 || sentinelReader.CurrentEncodedIdentity != 9_000_002UL)
                {
                    throw new InvalidDataException("Public VS8 sentinel reader did not distinguish empty key from null key.");
                }

                if (!sentinelReader.MoveNext() || sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 1 || sentinelReader.CurrentKey[0] != 0x00 || sentinelReader.CurrentEncodedIdentity != 9_000_003UL)
                {
                    throw new InvalidDataException("Public VS8 sentinel reader did not expose the non-empty key after null and empty.");
                }
            }

            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            ulong[] identities = new ulong[itemCount];
            int copied = reopened.ReadRange(lower, upper, identities);
            if (copied != expected)
            {
                throw new InvalidDataException($"Public VS8 range after reopen returned {copied}; expected {expected}.");
            }

            for (int i = 0; i < copied; i++)
            {
                checksum += unchecked((long)identities[i]);
            }

            using VarKeyScalar8RangeReader reader = reopened.OpenRangeReader(lower, upper);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public VS8 reader count after reopen returned {reader.Count}; expected {expected}.");
            }

            int readCount = 0;
            byte[] keyScratch = new byte[keyLength];
            long readerChecksum = 0;
            long keyChecksum = 0;
            while (reader.MoveNext())
            {
                if (reader.CurrentKeyLength != keyLength)
                {
                    throw new InvalidDataException($"Public VS8 reader key length was {reader.CurrentKeyLength}; expected {keyLength}.");
                }

                if (readCount == 0)
                {
                    if (reader.CopyCurrentKeyTo(keyScratch) != reader.CurrentKeyLength)
                    {
                        throw new InvalidDataException("Public VS8 reader failed to copy the current key.");
                    }

                    byte[] materializedKey = reader.MaterializeCurrentKey();
                    if (!materializedKey.AsSpan().SequenceEqual(reader.CurrentKey))
                    {
                        throw new InvalidDataException("Public VS8 reader materialized key did not match the current key span.");
                    }
                }

                keyChecksum += ChecksumBytes(reader.CurrentKey);
                readerChecksum += unchecked((long)reader.CurrentEncodedIdentity);
                readCount++;
            }

            if (readCount != expected || readerChecksum != checksum)
            {
                throw new InvalidDataException($"Public VS8 reader after reopen returned count={readCount} checksum={readerChecksum}; expected count={expected} checksum={checksum}.");
            }

            using LibraDexVarKeyBuffer keyBuffer = reopened.ReadKeyBuffer(lower, upper, expected * keyLength);
            if (keyBuffer.Count != expected || keyBuffer.PayloadLength != expected * keyLength)
            {
                throw new InvalidDataException("Public VS8 key buffer did not report the expected count and payload length.");
            }

            long keyBufferChecksum = 0;
            long keyEnumeratorChecksum = 0;
            for (int i = 0; i < keyBuffer.Count; i++)
            {
                ReadOnlySpan<byte> key = keyBuffer[i];
                if (key.Length != keyLength)
                {
                    throw new InvalidDataException("Public VS8 key buffer returned an unexpected key length.");
                }

                int keyOffset = keyBuffer.GetOffset(i);
                int reportedLength = keyBuffer.GetLength(i);
                if (reportedLength != key.Length || keyOffset < 0 || keyOffset + reportedLength > keyBuffer.PayloadLength)
                {
                    throw new InvalidDataException("Public VS8 key buffer returned inconsistent offset/length metadata.");
                }

                if (!keyBuffer.PayloadSpan.Slice(keyOffset, reportedLength).SequenceEqual(key))
                {
                    throw new InvalidDataException("Public VS8 key buffer flat payload did not match indexed key access.");
                }

                if (i == 0 && !keyBuffer.TryCopyTo(i, keyScratch))
                {
                    throw new InvalidDataException("Public VS8 key buffer failed to copy the first key to caller storage.");
                }

                if (i == 0)
                {
                    keyBuffer.CopyTo(i, keyScratch);
                }

                keyBufferChecksum += ChecksumBytes(key);
            }

            foreach (ReadOnlySpan<byte> key in keyBuffer)
            {
                keyEnumeratorChecksum += ChecksumBytes(key);
            }

            if (keyBufferChecksum != keyChecksum || keyEnumeratorChecksum != keyChecksum || keyBuffer.GetMemory(0).Length != keyBuffer[0].Length || keyBuffer.PayloadMemory.Length != keyBuffer.PayloadLength)
            {
                throw new InvalidDataException("Public VS8 key buffer did not match streaming reader results.");
            }

            using VarKeyScalar8RangeReader skipReader = reopened.OpenRangeReader(lower, upper);
            int skipped = skipReader.Skip(expected / 2);
            int remaining = 0;
            while (skipReader.MoveNext())
            {
                remaining++;
            }

            if (skipped != expected / 2 || remaining != expected - skipped)
            {
                throw new InvalidDataException($"Public VS8 reader skip returned skipped={skipped} remaining={remaining}; expected skipped={expected / 2} remaining={expected - skipped}.");
            }

            byte[] exactDeleteKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
            if (!reopened.DeleteExactTuple(exactDeleteKey, CreateVarKeyScalar8Identity(0)))
            {
                throw new InvalidDataException("Internal VS8 exact tuple delete did not remove the expected tuple.");
            }

            long rangeDeleted = reopened.DeleteRange(lower, upper);
            if (rangeDeleted != expected - 1)
            {
                throw new InvalidDataException($"Internal VS8 range delete removed {rangeDeleted}; expected {expected - 1} after exact delete.");
            }

            using VarKeyScalar8RangeReader afterDeleteReader = reopened.OpenRangeReader(lower, upper);
            if (afterDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Internal VS8 range delete left {afterDeleteReader.Count} rows in the deleted range.");
            }
        }

        using (VarKeyScalar8Index openedAgain = Indexes.VS8.CreateOrOpen(
            path,
            maxKeyLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedAgain.RootRouterOffset != rootOffset)
            {
                throw new InvalidDataException("CreateOrOpen public VS8 did not return the existing root router offset.");
            }
        }

        Console.WriteLine($"vs8-index-api-sanity ok path={path} root={rootOffset} items={itemCount} keyLength={keyLength} prefixCount={prefixCount} lazyCreates={lazyRouteCreates} deferredCommits={deferredCommitRequests} rangeCount={expected} checksum={checksum}");
        return 0;
    }

    /// <summary>
    /// Validates the first public raw-byte `VS16` index facade.<br/>
    /// The command creates a public `Indexes.VS16` index, inserts through the public batch API with lazy root-prefix shelves, verifies duplicate no-op and duplicate-key conflict behavior, reads a range before and after reopen, and checks `CreateOrOpen` returns the existing slot.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when public create, batch insert, range read, reopen, and create-or-open behavior validate.</returns>
    private static int RunVarKeyScalar16IndexApiSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs16-index-api-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 512);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS16 public API sanity requires positive items, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long lazyRouteCreates;
        long deferredCommitRequests;
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        using (VarKeyScalar16Index index = Indexes.VS16.Create(
            path,
            name: "vs16-api",
            maxKeyLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9177),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            rootOffset = index.RootRouterOffset;
            using (VarKeyScalar16Batch batch = index.BeginBatch(new LibraDexWriteIntent(
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.WriteSpeed)))
            {
                lazyRouteCreates = 0;
                for (int i = 0; i < itemCount; i++)
                {
                    byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                    CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                    VarKeyScalar16InsertOutcome result = batch.Insert(key, identityHigh, identityLow);
                    if (!result.Inserted)
                    {
                        throw new InvalidDataException($"Expected public VS16 insert {i}, got inserted={result.Inserted} already={result.AlreadyPresent} conflict={result.KeyConflict}.");
                    }

                    if (result.CreatedInitialShelfRoute)
                    {
                        lazyRouteCreates++;
                    }
                }

                byte[] duplicateKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
                CreateVarKeyScalar16Identity(0, out ulong duplicateHigh, out ulong duplicateLow);
                VarKeyScalar16InsertOutcome duplicate = batch.Insert(duplicateKey, duplicateHigh, duplicateLow);
                if (!duplicate.AlreadyPresent)
                {
                    throw new InvalidDataException("Expected public VS16 duplicate tuple to be reported as already present.");
                }

                VarKeyScalar16InsertOutcome conflict = batch.Insert(duplicateKey, ulong.MaxValue, ulong.MaxValue, allowDuplicateKeys: false);
                if (!conflict.KeyConflict)
                {
                    throw new InvalidDataException("Expected public VS16 duplicate key to be rejected when duplicate keys are disabled.");
                }

                VarKeyScalarBatchCommitResult commit = batch.Commit();
                deferredCommitRequests = commit.DeferredCommitRequests;
                if (commit.AttemptedInsertCount != itemCount + 2 || commit.InsertedCount != itemCount || commit.AlreadyPresentCount != 1 || commit.KeyConflictCount != 1)
                {
                    throw new InvalidDataException($"Unexpected public VS16 batch counts: attempted={commit.AttemptedInsertCount} inserted={commit.InsertedCount} already={commit.AlreadyPresentCount} conflicts={commit.KeyConflictCount}.");
                }
            }

            _ = index.Insert((byte[]?)null, 9_100_001UL, 9_100_101UL);
            _ = index.Insert(Array.Empty<byte>(), 9_100_002UL, 9_100_102UL);
            _ = index.Insert(new byte[] { 0x00 }, 9_100_003UL, 9_100_103UL);

            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            ulong[] identityHighs = new ulong[itemCount];
            ulong[] identityLows = new ulong[itemCount];
            int copied = index.ReadRange(lower, upper, identityHighs, identityLows);
            if (copied != expected)
            {
                throw new InvalidDataException($"Public VS16 range before reopen returned {copied}; expected {expected}.");
            }

            using VarKeyScalar16RangeReader reader = index.OpenRangeReader(lower, upper);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public VS16 reader count before reopen returned {reader.Count}; expected {expected}.");
            }
        }

        long checksum = 0;
        using (VarKeyScalar16Index reopened = Indexes.VS16.Open(
            path,
            maxKeyLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (reopened.RootRouterOffset != rootOffset || reopened.Name != "vs16-api")
            {
                throw new InvalidDataException("Reopened public VS16 index did not preserve root offset and name.");
            }

            using (VarKeyScalar16RangeReader sentinelReader = reopened.OpenRangeReader((byte[]?)null, new byte[] { 0x00 }))
            {
                if (sentinelReader.Count != 3)
                {
                    throw new InvalidDataException($"Public VS16 sentinel range returned {sentinelReader.Count}; expected 3.");
                }

                if (!sentinelReader.MoveNext() || !sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 0)
                {
                    throw new InvalidDataException("Public VS16 sentinel reader did not expose the null key first.");
                }

                sentinelReader.ReadCurrentIdentity(out ulong nullHigh, out ulong nullLow);
                if (nullHigh != 9_100_001UL || nullLow != 9_100_101UL)
                {
                    throw new InvalidDataException("Public VS16 sentinel reader returned an unexpected null-key identity.");
                }

                if (!sentinelReader.MoveNext() || sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 0)
                {
                    throw new InvalidDataException("Public VS16 sentinel reader did not distinguish empty key from null key.");
                }

                sentinelReader.ReadCurrentIdentity(out ulong emptyHigh, out ulong emptyLow);
                if (emptyHigh != 9_100_002UL || emptyLow != 9_100_102UL)
                {
                    throw new InvalidDataException("Public VS16 sentinel reader returned an unexpected empty-key identity.");
                }

                if (!sentinelReader.MoveNext() || sentinelReader.CurrentKeyIsNull || sentinelReader.CurrentKeyLength != 1 || sentinelReader.CurrentKey[0] != 0x00)
                {
                    throw new InvalidDataException("Public VS16 sentinel reader did not expose the non-empty key after null and empty.");
                }

                sentinelReader.ReadCurrentIdentity(out ulong valueHigh, out ulong valueLow);
                if (valueHigh != 9_100_003UL || valueLow != 9_100_103UL)
                {
                    throw new InvalidDataException("Public VS16 sentinel reader returned an unexpected non-empty-key identity.");
                }
            }

            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            ulong[] identityHighs = new ulong[itemCount];
            ulong[] identityLows = new ulong[itemCount];
            int copied = reopened.ReadRange(lower, upper, identityHighs, identityLows);
            if (copied != expected)
            {
                throw new InvalidDataException($"Public VS16 range after reopen returned {copied}; expected {expected}.");
            }

            for (int i = 0; i < copied; i++)
            {
                checksum += unchecked((long)identityHighs[i]);
                checksum += unchecked((long)identityLows[i]);
            }

            using VarKeyScalar16RangeReader reader = reopened.OpenRangeReader(lower, upper);
            if (reader.Count != expected)
            {
                throw new InvalidDataException($"Public VS16 reader count after reopen returned {reader.Count}; expected {expected}.");
            }

            int readCount = 0;
            byte[] keyScratch = new byte[keyLength];
            long readerChecksum = 0;
            long keyChecksum = 0;
            while (reader.MoveNext())
            {
                if (reader.CurrentKeyLength != keyLength)
                {
                    throw new InvalidDataException($"Public VS16 reader key length was {reader.CurrentKeyLength}; expected {keyLength}.");
                }

                if (readCount == 0)
                {
                    if (reader.CopyCurrentKeyTo(keyScratch) != reader.CurrentKeyLength)
                    {
                        throw new InvalidDataException("Public VS16 reader failed to copy the current key.");
                    }

                    byte[] materializedKey = reader.MaterializeCurrentKey();
                    if (!materializedKey.AsSpan().SequenceEqual(reader.CurrentKey))
                    {
                        throw new InvalidDataException("Public VS16 reader materialized key did not match the current key span.");
                    }
                }

                keyChecksum += ChecksumBytes(reader.CurrentKey);
                reader.ReadCurrentIdentity(out ulong currentHigh, out ulong currentLow);
                readerChecksum += unchecked((long)currentHigh);
                readerChecksum += unchecked((long)currentLow);
                readCount++;
            }

            if (readCount != expected || readerChecksum != checksum)
            {
                throw new InvalidDataException($"Public VS16 reader after reopen returned count={readCount} checksum={readerChecksum}; expected count={expected} checksum={checksum}.");
            }

            using LibraDexVarKeyBuffer keyBuffer = reopened.ReadKeyBuffer(lower, upper, expected * keyLength);
            if (keyBuffer.Count != expected || keyBuffer.PayloadLength != expected * keyLength)
            {
                throw new InvalidDataException("Public VS16 key buffer did not report the expected count and payload length.");
            }

            long keyBufferChecksum = 0;
            long keyEnumeratorChecksum = 0;
            for (int i = 0; i < keyBuffer.Count; i++)
            {
                ReadOnlySpan<byte> key = keyBuffer[i];
                if (key.Length != keyLength)
                {
                    throw new InvalidDataException("Public VS16 key buffer returned an unexpected key length.");
                }

                int keyOffset = keyBuffer.GetOffset(i);
                int reportedLength = keyBuffer.GetLength(i);
                if (reportedLength != key.Length || keyOffset < 0 || keyOffset + reportedLength > keyBuffer.PayloadLength)
                {
                    throw new InvalidDataException("Public VS16 key buffer returned inconsistent offset/length metadata.");
                }

                if (!keyBuffer.PayloadSpan.Slice(keyOffset, reportedLength).SequenceEqual(key))
                {
                    throw new InvalidDataException("Public VS16 key buffer flat payload did not match indexed key access.");
                }

                if (i == 0 && !keyBuffer.TryCopyTo(i, keyScratch))
                {
                    throw new InvalidDataException("Public VS16 key buffer failed to copy the first key to caller storage.");
                }

                if (i == 0)
                {
                    keyBuffer.CopyTo(i, keyScratch);
                }

                keyBufferChecksum += ChecksumBytes(key);
            }

            foreach (ReadOnlySpan<byte> key in keyBuffer)
            {
                keyEnumeratorChecksum += ChecksumBytes(key);
            }

            if (keyBufferChecksum != keyChecksum || keyEnumeratorChecksum != keyChecksum || keyBuffer.GetMemory(0).Length != keyBuffer[0].Length || keyBuffer.PayloadMemory.Length != keyBuffer.PayloadLength)
            {
                throw new InvalidDataException("Public VS16 key buffer did not match streaming reader results.");
            }

            using VarKeyScalar16RangeReader skipReader = reopened.OpenRangeReader(lower, upper);
            int skipped = skipReader.Skip(expected / 2);
            int remaining = 0;
            while (skipReader.MoveNext())
            {
                remaining++;
            }

            if (skipped != expected / 2 || remaining != expected - skipped)
            {
                throw new InvalidDataException($"Public VS16 reader skip returned skipped={skipped} remaining={remaining}; expected skipped={expected / 2} remaining={expected - skipped}.");
            }

            byte[] exactDeleteKey = CreateVarKeyScalar8Key(0, keyLength, prefixCount);
            CreateVarKeyScalar16Identity(0, out ulong exactDeleteHigh, out ulong exactDeleteLow);
            if (!reopened.DeleteExactTuple(exactDeleteKey, exactDeleteHigh, exactDeleteLow))
            {
                throw new InvalidDataException("Internal VS16 exact tuple delete did not remove the expected tuple.");
            }

            long rangeDeleted = reopened.DeleteRange(lower, upper);
            if (rangeDeleted != expected - 1)
            {
                throw new InvalidDataException($"Internal VS16 range delete removed {rangeDeleted}; expected {expected - 1} after exact delete.");
            }

            using VarKeyScalar16RangeReader afterDeleteReader = reopened.OpenRangeReader(lower, upper);
            if (afterDeleteReader.Count != 0)
            {
                throw new InvalidDataException($"Internal VS16 range delete left {afterDeleteReader.Count} rows in the deleted range.");
            }
        }

        using (VarKeyScalar16Index openedAgain = Indexes.VS16.CreateOrOpen(
            path,
            maxKeyLength: 1024,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            if (openedAgain.RootRouterOffset != rootOffset)
            {
                throw new InvalidDataException("CreateOrOpen public VS16 did not return the existing root router offset.");
            }
        }

        Console.WriteLine($"vs16-index-api-sanity ok path={path} root={rootOffset} items={itemCount} keyLength={keyLength} prefixCount={prefixCount} lazyCreates={lazyRouteCreates} deferredCommits={deferredCommitRequests} rangeCount={expected} checksum={checksum}");
        return 0;
    }

    /// <summary>
    /// Compares the first raw varlen-key shelf primitive against SQLite for the same `BLOB key -> INTEGER identity` shape.<br/>
    /// LibraDex rows build one compact sorted shelf image and measure range scans over decoded runtime slot arrays.<br/>
    /// SQLite rows insert the same raw byte keys into a `WITHOUT ROWID` primary-key table and measure ordered range scans.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunVarKeyScalar8SqliteComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS8SqliteComparison"));
        int itemCount = GetIntOption(args, "--items", 4096);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int iterations = GetIntOption(args, "--iterations", 200);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256 || iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 SQLite comparison requires positive items/iterations, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(directory);
        byte[][] keys = CreateSortedVarKeyScalar8Keys(itemCount, keyLength, prefixCount);
        ulong[] identities = new ulong[itemCount];
        for (int i = 0; i < itemCount; i++)
        {
            identities[i] = CreateVarKeyScalar8Identity(i);
        }

        Stopwatch libraBuildWatch = Stopwatch.StartNew();
        VarKeyScalar8ComparisonShelf[] shelves = BuildVarKeyScalar8ComparisonShelves(keys, identities, prefixCount);
        libraBuildWatch.Stop();

        string sqlitePath = Path.Combine(directory, "sqlite-vs8.db");
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        ResetSqliteScalar8Scalar8Files(sqlitePath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteVarKeyScalar8Schema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Integer);
            for (int i = 0; i < itemCount; i++)
            {
                keyParameter.Value = keys[i];
                identityParameter.Value = EncodeSqliteSortableUnsignedScalar8(identities[i]);
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        VarKeyScalar8ReadMeasurement libraRead = MeasureVarKeyScalar8RangeReads(shelves, keyLength, prefixCount, itemCount, iterations);
        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteVarKeyScalar8RangeReads(connection, keyLength, prefixCount, itemCount, iterations, VarIdentityIterationMode.Identities);
        }

        long sqliteBytes = GetSqliteScalar8Scalar8StorageBytes(sqlitePath);
        long libraBytes = shelves.Sum(static shelf => (long)shelf.Profile.ShelfExtentSize);
        double libraBuildItemsPerSecond = itemCount / Math.Max(libraBuildWatch.Elapsed.TotalSeconds, 0.000001);
        double sqliteWriteItemsPerSecond = itemCount / Math.Max(sqliteWriteWatch.Elapsed.TotalSeconds, 0.000001);
        Console.WriteLine("vs8 sqlite comparison");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine("| row | items/sec | ids/sec | ns/id | bytes | bytes/item | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| VS8 compact build/read | {libraBuildItemsPerSecond:F2} | {libraRead.IdentitiesPerSecond:F2} | {libraRead.NsPerIdentity:F2} | {libraBytes} | {(double)libraBytes / itemCount:F2} | {libraRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| SQLite write/read | {sqliteWriteItemsPerSecond:F2} | {sqliteRead.IdentitiesPerSecond:F2} | {sqliteRead.NsPerIdentity:F2} | {sqliteBytes} | {(double)sqliteBytes / itemCount:F2} | {sqliteRead.Checksum} |"));
        Console.WriteLine($"VS8/SQLite read {FormatMultiplier(libraRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS8/SQLite write {FormatMultiplier(libraBuildItemsPerSecond, sqliteWriteItemsPerSecond)}");
        return 0;
    }

    private static VarKeyScalar8ComparisonShelf[] BuildVarKeyScalar8ComparisonShelves(byte[][] keys, ulong[] identities, int prefixCount)
    {
        List<VarKeyScalar8ComparisonShelf> shelves = [];
        for (int prefix = 0; prefix < prefixCount; prefix++)
        {
            List<byte[]> prefixKeys = [];
            List<ulong> prefixIdentities = [];
            for (int i = 0; i < keys.Length; i++)
            {
                if (keys[i][0] == prefix)
                {
                    prefixKeys.Add(keys[i]);
                    prefixIdentities.Add(identities[i]);
                }
            }

            if (prefixKeys.Count == 0)
            {
                continue;
            }

            byte[][] keyArray = prefixKeys.ToArray();
            ulong[] identityArray = prefixIdentities.ToArray();
            VarKeyScalar8Profile profile = SelectVarKeyScalar8BuildProfile(keyArray, identityArray);
            if (!VarKeyScalar8.TryBuildFromSorted(keyArray, identityArray, profile, out byte[] shelfBytes))
            {
                throw new InvalidDataException($"VS8 comparison could not build prefix {prefix} shelf at {profile.ShelfExtentSize} bytes.");
            }

            VarKeyScalar8ReadOnly readOnly = new(shelfBytes, profile);
            if (!readOnly.IsValid)
            {
                throw new InvalidDataException($"VS8 comparison built an invalid prefix {prefix} shelf.");
            }

            shelves.Add(new VarKeyScalar8ComparisonShelf(prefix, profile, readOnly));
        }

        return shelves.ToArray();
    }

    private static byte[][] CreateSortedVarKeyScalar8Keys(int itemCount, int keyLength, int prefixCount)
    {
        byte[][] keys = new byte[itemCount][];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
        }

        Array.Sort(keys, static (left, right) => left.AsSpan().SequenceCompareTo(right));
        return keys;
    }

    private static ulong CreateScalar8VarIdentityKey(int index, int duplicateModulo)
    {
        return Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(index % duplicateModulo));
    }

    /// <summary>
    /// Creates an encoded `SV8` scalar key for comparison scenarios.<br/>
    /// The default `low` distribution models ordinary small integer property values; `high-byte` spreads generated keys across the first persisted route byte to isolate shelf cost from prefix-depth clustering.<br/>
    /// </summary>
    /// <param name="index">The generated source index.</param>
    /// <param name="duplicateModulo">The generated duplicate-key modulo.</param>
    /// <param name="keyDistribution">The requested key distribution.</param>
    /// <returns>The encoded sortable scalar key.</returns>
    private static ulong CreateScalar8VarIdentityKey(int index, int duplicateModulo, string keyDistribution)
    {
        return Scalar8Scalar8Layout.EncodeUnsignedScalar8(CreateScalar8VarIdentitySqliteKey(index, duplicateModulo, keyDistribution));
    }

    /// <summary>
    /// Creates the unencoded SQLite scalar key matching the generated `SV8` comparison key.<br/>
    /// Keeping this helper paired with `CreateScalar8VarIdentityKey` guarantees LibraDex and SQLite compare the same logical key distribution.<br/>
    /// </summary>
    /// <param name="index">The generated source index.</param>
    /// <param name="duplicateModulo">The generated duplicate-key modulo.</param>
    /// <param name="keyDistribution">The requested key distribution.</param>
    /// <returns>The logical unsigned scalar key.</returns>
    private static ulong CreateScalar8VarIdentitySqliteKey(int index, int duplicateModulo, string keyDistribution)
    {
        ulong logical = (ulong)(index % duplicateModulo);
        if (keyDistribution.Equals("high-byte", StringComparison.OrdinalIgnoreCase))
        {
            return (logical & 0xFFUL) << 56;
        }

        return logical;
    }

    private static byte[] CreateScalar8VarIdentity(int index, int identityLength)
    {
        return CreateScalar8VarIdentity(index, identityLength, fixedLength: false);
    }

    /// <summary>
    /// Creates a generated raw `SV8` identity payload.<br/>
    /// Variable-length mode preserves the original stress pattern; fixed-length mode keeps tiny mirror-test identities unique by writing the source index into the payload tail.<br/>
    /// </summary>
    /// <param name="index">The generated source index.</param>
    /// <param name="identityLength">The requested maximum or fixed identity length.</param>
    /// <param name="fixedLength">Whether to produce exactly <paramref name="identityLength"/> bytes.</param>
    /// <returns>The generated raw identity bytes.</returns>
    private static byte[] CreateScalar8VarIdentity(int index, int identityLength, bool fixedLength)
    {
        if (fixedLength)
        {
            byte[] fixedIdentity = new byte[identityLength];
            for (int i = 0; i < fixedIdentity.Length; i++)
            {
                fixedIdentity[i] = (byte)((index * 193 + i * 29) & 0xFF);
            }

            int bytesToWrite = Math.Min(sizeof(int), fixedIdentity.Length);
            int firstIndexByte = fixedIdentity.Length - bytesToWrite;
            for (int i = 0; i < bytesToWrite; i++)
            {
                int shift = (bytesToWrite - 1 - i) * 8;
                fixedIdentity[firstIndexByte + i] = (byte)(index >> shift);
            }

            return fixedIdentity;
        }

        string prefix = string.Create(CultureInfo.InvariantCulture, $"item/{index:X8}/");
        int lengthVariation = index % Math.Min(identityLength, 11);
        byte[] identity = new byte[identityLength - lengthVariation];
        byte[] prefixBytes = Encoding.ASCII.GetBytes(prefix);
        prefixBytes.AsSpan(0, Math.Min(prefixBytes.Length, identity.Length)).CopyTo(identity);
        for (int i = prefixBytes.Length; i < identity.Length; i++)
        {
            identity[i] = (byte)((index * 193 + i * 29) & 0xFF);
        }

        return identity;
    }

    private static int CountScalar8VarIdentityKeyRange(int itemCount, int duplicateModulo, int lowerKey, int upperKey)
    {
        int count = 0;
        for (int i = 0; i < itemCount; i++)
        {
            int key = i % duplicateModulo;
            if (key >= lowerKey && key <= upperKey)
            {
                count++;
            }
        }

        return count;
    }

    private static byte[] CreateVarKeyScalar8Key(int index, int keyLength, int prefixCount)
    {
        byte[] key = new byte[keyLength];
        int prefix = index % prefixCount;
        key[0] = (byte)prefix;
        if (keyLength > 1)
        {
            key[1] = (byte)(index / Math.Max(prefixCount, 1));
        }

        if (keyLength > 2)
        {
            key[2] = (byte)(index >> 8);
        }

        if (keyLength > 3)
        {
            key[3] = (byte)index;
        }

        for (int i = 4; i < key.Length; i++)
        {
            key[i] = (byte)((index * 131 + i * 17) & 0xFF);
        }

        return key;
    }

    private static byte[] CreateVarKeyScalar8PrefixLower(int prefix, int keyLength)
    {
        byte[] key = new byte[keyLength];
        key[0] = (byte)prefix;
        return key;
    }

    private static byte[] CreateVarKeyScalar8PrefixUpper(int prefix, int keyLength)
    {
        byte[] key = new byte[keyLength];
        key[0] = (byte)prefix;
        key.AsSpan(1).Fill(0xFF);
        return key;
    }

    private static byte[] CreateVarKeyScalar8LongSharedPrefixKey(int index, int keyLength, int sharedPrefixLength)
    {
        byte[] key = new byte[keyLength];
        key.AsSpan(0, Math.Min(sharedPrefixLength, keyLength)).Fill(0x35);
        if (keyLength > sharedPrefixLength)
        {
            key[sharedPrefixLength] = (byte)(index >> 8);
        }

        if (keyLength > sharedPrefixLength + 1)
        {
            key[sharedPrefixLength + 1] = (byte)index;
        }

        for (int i = sharedPrefixLength + 2; i < key.Length; i++)
        {
            key[i] = (byte)((index * 197 + i * 23) & 0xFF);
        }

        return key;
    }

    private static byte[] CreateVarKeyScalar8HierarchicalKey(int index, int sharedPrefixLength, int branchCount, int maxKeyLength)
    {
        string sharedPrefix = CreateVarKeyScalar8HierarchicalSharedPrefix(sharedPrefixLength);
        int branch = index % branchCount;
        int subBranch = (index / Math.Max(branchCount, 1)) % Math.Max(branchCount, 1);
        string path = string.Create(
            CultureInfo.InvariantCulture,
            $"{sharedPrefix}/dept{branch:X2}/zone{subBranch:X2}/file{index:X8}");
        byte[] key = Encoding.ASCII.GetBytes(path);
        if (key.Length > maxKeyLength)
        {
            throw new ArgumentOutOfRangeException(nameof(maxKeyLength), maxKeyLength, $"Generated hierarchical key length {key.Length} exceeds the requested maximum.");
        }

        return key;
    }

    private static byte[] CreateVarKeyScalar8HierarchicalRangeLower(int sharedPrefixLength)
    {
        return Encoding.ASCII.GetBytes(CreateVarKeyScalar8HierarchicalSharedPrefix(sharedPrefixLength));
    }

    private static byte[] CreateVarKeyScalar8HierarchicalRangeUpper(int sharedPrefixLength)
    {
        byte[] lower = CreateVarKeyScalar8HierarchicalRangeLower(sharedPrefixLength);
        byte[] upper = new byte[lower.Length + 1];
        lower.CopyTo(upper, 0);
        upper[^1] = 0xFF;
        return upper;
    }

    private static string CreateVarKeyScalar8HierarchicalSharedPrefix(int sharedPrefixLength)
    {
        if (sharedPrefixLength < 1)
        {
            throw new ArgumentOutOfRangeException(nameof(sharedPrefixLength), sharedPrefixLength, "The hierarchical shared prefix must contain at least one byte.");
        }

        string root = "/tenant/acme/repository";
        if (sharedPrefixLength <= root.Length)
        {
            return root[..sharedPrefixLength];
        }

        StringBuilder builder = new(root);
        int segment = 0;
        while (builder.Length < sharedPrefixLength)
        {
            builder.Append('/');
            builder.Append("common");
            builder.Append(segment.ToString("X2", CultureInfo.InvariantCulture));
            segment++;
        }

        return builder.ToString(0, sharedPrefixLength);
    }

    private static ulong CreateVarKeyScalar8Identity(int index)
    {
        return unchecked(0x8100_0000_0000_0000UL | (uint)index);
    }

    private static void CreateVarKeyScalar16Identity(int index, out ulong identityHigh, out ulong identityLow)
    {
        identityHigh = unchecked(0xA100_0000_0000_0000UL | (uint)(index / 1024));
        identityLow = unchecked(0xB100_0000_0000_0000UL | (uint)index);
    }

    private static int CompareVarKeyScalar16Tuple(
        ReadOnlySpan<byte> leftKey,
        ulong leftIdentityHigh,
        ulong leftIdentityLow,
        ReadOnlySpan<byte> rightKey,
        ulong rightIdentityHigh,
        ulong rightIdentityLow)
    {
        int keyComparison = leftKey.SequenceCompareTo(rightKey);
        if (keyComparison != 0)
        {
            return keyComparison;
        }

        if (leftIdentityHigh < rightIdentityHigh)
        {
            return -1;
        }

        if (leftIdentityHigh > rightIdentityHigh)
        {
            return 1;
        }

        if (leftIdentityLow < rightIdentityLow)
        {
            return -1;
        }

        return leftIdentityLow > rightIdentityLow ? 1 : 0;
    }

    private static int CountVarKeyScalar8PrefixRange(int itemCount, int prefixCount, int lowerPrefix, int upperPrefix)
    {
        int count = 0;
        for (int i = 0; i < itemCount; i++)
        {
            int prefix = i % prefixCount;
            if (prefix >= lowerPrefix && prefix <= upperPrefix)
            {
                count++;
            }
        }

        return count;
    }

    private static VarKeyScalar8Profile SelectVarKeyScalar8BuildProfile(ReadOnlySpan<byte[]> keys, ReadOnlySpan<ulong> identities)
    {
        VarKeyScalar8Profile profile = VarKeyScalar8Profile.DefaultInitial;
        while (!VarKeyScalar8.TryBuildFromSorted(keys, identities, profile, out _))
        {
            VarKeyScalar8Profile next = profile.NextGrowthClass();
            if (next.ShelfExtentSize == profile.ShelfExtentSize)
            {
                throw new InvalidDataException("VS8 comparison input does not fit in the maximum first-pass shelf profile.");
            }

            profile = next;
        }

        return profile;
    }

    /// <summary>
    /// Selects the smallest `VS16` shelf profile that can hold an already-sorted key and identity batch.<br/>
    /// This mirrors the `VS8` comparison helper and changes only the widened identity lanes, preserving the clone-first benchmark contract.<br/>
    /// The helper throws when even the maximum configured `VS16` shelf extent cannot hold the supplied prefix group, which means the comparison input needs more routing fanout rather than silent truncation.<br/>
    /// </summary>
    /// <param name="keys">The sorted raw key byte arrays.</param>
    /// <param name="identityHighs">The sorted high identity lanes aligned with <paramref name="keys"/>.</param>
    /// <param name="identityLows">The sorted low identity lanes aligned with <paramref name="keys"/>.</param>
    /// <returns>The smallest `VS16` profile that can build the supplied shelf.</returns>
    private static VarKeyScalar16Profile SelectVarKeyScalar16BuildProfile(ReadOnlySpan<byte[]> keys, ReadOnlySpan<ulong> identityHighs, ReadOnlySpan<ulong> identityLows)
    {
        VarKeyScalar16Profile profile = VarKeyScalar16Profile.DefaultInitial;
        while (!VarKeyScalar16.TryBuildFromSorted(keys, identityHighs, identityLows, profile, out _))
        {
            VarKeyScalar16Profile next = profile.NextGrowthClass();
            if (next.ShelfExtentSize == profile.ShelfExtentSize)
            {
                throw new InvalidDataException("VS16 comparison input does not fit in the maximum first-pass shelf profile.");
            }

            profile = next;
        }

        return profile;
    }

    /// <summary>
    /// Selects the smallest `VV` shelf profile that can hold an already-sorted key and identity batch.<br/>
    /// This mirrors the `VS8` and `VS16` comparison helpers while preserving byte-ordinal identity ordering for duplicate-key stability.<br/>
    /// The helper throws when even the maximum configured `VV` shelf extent cannot hold the supplied prefix group, which means the comparison input needs more routing fanout rather than silent truncation.<br/>
    /// </summary>
    /// <param name="keys">The sorted raw key byte arrays.</param>
    /// <param name="identities">The sorted raw identity byte arrays aligned with <paramref name="keys"/>.</param>
    /// <returns>The smallest `VV` profile that can build the supplied shelf.</returns>
    private static VarKeyVarIdentityProfile SelectVarKeyVarIdentityBuildProfile(
        ReadOnlySpan<byte[]> keys,
        ReadOnlySpan<byte[]> identities,
        VarKeyVarIdentityProfile initialProfile)
    {
        VarKeyVarIdentityProfile profile = initialProfile;
        while (!VarKeyVarIdentity.TryBuildFromSorted(keys, identities, profile, out _))
        {
            VarKeyVarIdentityProfile next = profile.NextGrowthClass();
            if (next.ShelfExtentSize == profile.ShelfExtentSize)
            {
                throw new InvalidDataException("VV comparison input does not fit in the maximum first-pass shelf profile.");
            }

            profile = next;
        }

        return profile;
    }

    private static VarKeyScalar8ReadMeasurement MeasureVarKeyScalar8RangeReads(VarKeyScalar8ComparisonShelf[] shelves, int keyLength, int prefixCount, int itemCount, int iterations)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        ulong[] identities = new ulong[itemCount];
        long checksum = 0;
        long total = 0;
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            for (int shelfIndex = 0; shelfIndex < shelves.Length; shelfIndex++)
            {
                VarKeyScalar8ComparisonShelf shelf = shelves[shelfIndex];
                if (shelf.Prefix > Math.Min(2, prefixCount - 1))
                {
                    continue;
                }

                count += shelf.ReadOnly.CopyIdentitiesInKeyRange(lower, upper, identities.AsSpan(count));
            }

            if (count != expected)
            {
                throw new InvalidDataException($"VS8 read comparison expected {expected} identities, got {count}.");
            }

            total += count;
            for (int j = 0; j < count; j++)
            {
                checksum += unchecked((long)identities[j]);
            }
        }

        watch.Stop();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum);
    }

    /// <summary>
    /// Builds the SQLite `VS8` range-read projection matching the requested iteration payload mode.<br/>
    /// Keeping the projection narrow prevents key-only and identity-only measurements from accidentally timing tuple materialization work.<br/>
    /// </summary>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The SQLite command text for the requested projection.</returns>
    private static string CreateSqliteVarKeyScalar8RangeReadCommandText(VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => "SELECT k FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            VarIdentityIterationMode.Tuples => "SELECT k, i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            _ => "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;"
        };
    }

    /// <summary>
    /// Builds the SQLite `VS16` range-read projection matching the requested iteration payload mode.<br/>
    /// The identity column remains a 16-byte BLOB so SQLite compares and projects the same semantic identity payload as the LibraDex shelf.<br/>
    /// </summary>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The SQLite command text for the requested projection.</returns>
    private static string CreateSqliteVarKeyScalar16RangeReadCommandText(VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => "SELECT k FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            VarIdentityIterationMode.Tuples => "SELECT k, i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            _ => "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;"
        };
    }

    /// <summary>
    /// Builds the SQLite `VV` range-read projection matching the requested iteration payload mode.<br/>
    /// Both projected columns are raw BLOB values when requested, matching the byte-ordinal tuple contract of the LibraDex `VV` shelf.<br/>
    /// </summary>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The SQLite command text for the requested projection.</returns>
    private static string CreateSqliteVarKeyVarIdentityRangeReadCommandText(VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => "SELECT k FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            VarIdentityIterationMode.Tuples => "SELECT k, i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;",
            _ => "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;"
        };
    }

    /// <summary>
    /// Adds the current `VS8` reader row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The helper intentionally reads only the fields implied by the mode so the harness measures identities, keys, and full tuples as distinct access patterns.<br/>
    /// </summary>
    /// <param name="reader">The positioned `VS8` range reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumVarKeyScalar8Current(VarKeyScalar8RangeReader reader, VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => ChecksumBytes(reader.CurrentKey),
            VarIdentityIterationMode.Tuples => ChecksumBytes(reader.CurrentKey) + unchecked((long)reader.CurrentEncodedIdentity),
            _ => unchecked((long)reader.CurrentEncodedIdentity)
        };
    }

    /// <summary>
    /// Adds the current `VS16` reader row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The helper reads both identity halves in one call for identity and tuple modes, keeping the measurement close to the fixed-width shelf primitive.<br/>
    /// </summary>
    /// <param name="reader">The positioned `VS16` range reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumVarKeyScalar16Current(VarKeyScalar16RangeReader reader, VarIdentityIterationMode iterationMode)
    {
        if (iterationMode == VarIdentityIterationMode.Keys)
        {
            return ChecksumBytes(reader.CurrentKey);
        }

        reader.ReadCurrentIdentity(out ulong identityHigh, out ulong identityLow);
        long identityChecksum = unchecked((long)identityHigh) + unchecked((long)identityLow);
        return iterationMode == VarIdentityIterationMode.Tuples
            ? ChecksumBytes(reader.CurrentKey) + identityChecksum
            : identityChecksum;
    }

    /// <summary>
    /// Adds the current `VV` reader row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The helper intentionally reads only the requested spans so identity-only iteration does not touch the key payload and key-only iteration does not touch the identity payload.<br/>
    /// </summary>
    /// <param name="reader">The positioned `VV` range reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumVarKeyVarIdentityCurrent(VarKeyVarIdentityRangeReader reader, VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => ChecksumBytes(reader.CurrentKey),
            VarIdentityIterationMode.Tuples => ChecksumBytes(reader.CurrentKey) + ChecksumBytes(reader.CurrentIdentity),
            _ => ChecksumBytes(reader.CurrentIdentity)
        };
    }

    /// <summary>
    /// Adds the current SQLite `VS8` row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The selected column positions match <see cref="CreateSqliteVarKeyScalar8RangeReadCommandText(VarIdentityIterationMode)"/>.<br/>
    /// </summary>
    /// <param name="reader">The positioned SQLite reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumSqliteVarKeyScalar8Current(SqliteDataReader reader, VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => ChecksumBytes((byte[])reader.GetValue(0)),
            VarIdentityIterationMode.Tuples => ChecksumBytes((byte[])reader.GetValue(0)) + unchecked((long)DecodeSqliteSortableUnsignedScalar8(reader.GetInt64(1))),
            _ => unchecked((long)DecodeSqliteSortableUnsignedScalar8(reader.GetInt64(0)))
        };
    }

    /// <summary>
    /// Adds the current SQLite `VS16` row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The helper decodes the 16-byte identity BLOB as two big-endian halves to match the LibraDex checksum semantics.<br/>
    /// </summary>
    /// <param name="reader">The positioned SQLite reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumSqliteVarKeyScalar16Current(SqliteDataReader reader, VarIdentityIterationMode iterationMode)
    {
        if (iterationMode == VarIdentityIterationMode.Keys)
        {
            return ChecksumBytes((byte[])reader.GetValue(0));
        }

        int identityOrdinal = iterationMode == VarIdentityIterationMode.Tuples ? 1 : 0;
        byte[] identity = (byte[])reader.GetValue(identityOrdinal);
        long identityChecksum =
            unchecked((long)BinaryPrimitives.ReadUInt64BigEndian(identity.AsSpan(0, 8))) +
            unchecked((long)BinaryPrimitives.ReadUInt64BigEndian(identity.AsSpan(8, 8)));
        return iterationMode == VarIdentityIterationMode.Tuples
            ? ChecksumBytes((byte[])reader.GetValue(0)) + identityChecksum
            : identityChecksum;
    }

    /// <summary>
    /// Adds the current SQLite `VV` row payload requested by the iteration mode to the comparison checksum.<br/>
    /// The selected column positions match <see cref="CreateSqliteVarKeyVarIdentityRangeReadCommandText(VarIdentityIterationMode)"/>.<br/>
    /// </summary>
    /// <param name="reader">The positioned SQLite reader.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The checksum contribution for the current row.</returns>
    private static long ChecksumSqliteVarKeyVarIdentityCurrent(SqliteDataReader reader, VarIdentityIterationMode iterationMode)
    {
        return iterationMode switch
        {
            VarIdentityIterationMode.Keys => ChecksumBytes((byte[])reader.GetValue(0)),
            VarIdentityIterationMode.Tuples => ChecksumBytes((byte[])reader.GetValue(0)) + ChecksumBytes((byte[])reader.GetValue(1)),
            _ => ChecksumBytes((byte[])reader.GetValue(0))
        };
    }

    private static VarKeyScalar8ReadMeasurement MeasureSqliteVarKeyScalar8RangeReads(SqliteConnection connection, int keyLength, int prefixCount, int itemCount, int iterations, VarIdentityIterationMode iterationMode)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        long checksum = 0;
        long total = 0;
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = CreateSqliteVarKeyScalar8RangeReadCommandText(iterationMode);
        command.Parameters.AddWithValue("$lower", lower);
        command.Parameters.AddWithValue("$upper", upper);
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            using SqliteDataReader reader = command.ExecuteReader();
            while (reader.Read())
            {
                checksum += ChecksumSqliteVarKeyScalar8Current(reader, iterationMode);
                count++;
            }

            if (count != expected)
            {
                throw new InvalidDataException($"SQLite VS8 read comparison expected {expected} identities, got {count}.");
            }

            total += count;
        }

        watch.Stop();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum);
    }

    /// <summary>
    /// Measures SQLite prefix-range reads for the `VS16` comparison schema.<br/>
    /// The key range is the same raw BLOB range used by `VS8`; only the selected identity column changes from integer to a 16-byte BLOB.<br/>
    /// The checksum decodes both big-endian identity halves so the SQLite row validates the same logical identity stream as the LibraDex `VS16` row.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="itemCount">The total generated identity count.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <returns>The SQLite range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureSqliteVarKeyScalar16RangeReads(SqliteConnection connection, int keyLength, int prefixCount, int itemCount, int iterations, VarIdentityIterationMode iterationMode)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        long checksum = 0;
        long total = 0;
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = CreateSqliteVarKeyScalar16RangeReadCommandText(iterationMode);
        command.Parameters.AddWithValue("$lower", lower);
        command.Parameters.AddWithValue("$upper", upper);
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            using SqliteDataReader reader = command.ExecuteReader();
            while (reader.Read())
            {
                checksum += ChecksumSqliteVarKeyScalar16Current(reader, iterationMode);
                count++;
            }

            if (count != expected)
            {
                throw new InvalidDataException($"SQLite VS16 read comparison expected {expected} identities, got {count}.");
            }

            total += count;
        }

        watch.Stop();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum);
    }

    private static VarKeyScalar8ReadMeasurement MeasureVarKeyScalar8ExplicitRangeReads(
        LibraDexFileSession session,
        long rootOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lower,
        ReadOnlySpan<byte> upper,
        int expected,
        int iterations)
    {
        ulong[] identities = new ulong[expected];
        long checksum = 0;
        long total = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = session.ReadVarKeyScalar8IdentityRange(rootOffset, maxKeyLength, lower, upper, identities);
            if (count != expected)
            {
                throw new InvalidDataException($"VS8 explicit range expected {expected} identities, got {count}.");
            }

            total += count;
            for (int j = 0; j < count; j++)
            {
                checksum += unchecked((long)identities[j]);
            }
        }

        watch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        (int cacheArenaCount, long cacheBytes) = session.GetRouterArenaReadCacheStatsForValidation();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum, telemetry, cacheArenaCount, cacheBytes);
    }

    /// <summary>
    /// Measures routed `VS16` explicit raw-key range reads through an opened session.<br/>
    /// This helper is used by hierarchical/path-like comparisons where the range is not a first-byte prefix range.<br/>
    /// The checksum folds both identity halves so high/low preservation is validated while measuring the same range-scoop path.<br/>
    /// </summary>
    /// <param name="session">The opened LibraDex session.</param>
    /// <param name="rootOffset">The root router offset for the `VS16` index.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the index.</param>
    /// <param name="lower">The inclusive lower raw key.</param>
    /// <param name="upper">The inclusive upper raw key.</param>
    /// <param name="expected">The expected number of identities per iteration.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <returns>The routed range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureVarKeyScalar16ExplicitRangeReads(
        LibraDexFileSession session,
        long rootOffset,
        int maxKeyLength,
        ReadOnlySpan<byte> lower,
        ReadOnlySpan<byte> upper,
        int expected,
        int iterations)
    {
        ulong[] identityHighs = new ulong[expected];
        ulong[] identityLows = new ulong[expected];
        long checksum = 0;
        long total = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = session.ReadVarKeyScalar16IdentityRange(rootOffset, maxKeyLength, lower, upper, identityHighs, identityLows);
            if (count != expected)
            {
                throw new InvalidDataException($"VS16 explicit range expected {expected} identities, got {count}.");
            }

            total += count;
            for (int j = 0; j < count; j++)
            {
                checksum += unchecked((long)identityHighs[j]);
                checksum += unchecked((long)identityLows[j]);
            }
        }

        watch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        (int cacheArenaCount, long cacheBytes) = session.GetRouterArenaReadCacheStatsForValidation();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum, telemetry, cacheArenaCount, cacheBytes);
    }

    /// <summary>
    /// Measures routed `VV` prefix-range reads through an opened session.<br/>
    /// The helper folds raw identity bytes into the checksum so reads validate both count and payload preservation while reporting logical identity throughput.<br/>
    /// </summary>
    /// <param name="session">The opened LibraDex session.</param>
    /// <param name="rootOffset">The root router offset for the `VV` index.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="itemCount">The total generated identity count.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <param name="maxRouterHops">The maximum number of router pages to follow during each measured routed read.</param>
    /// <returns>The routed range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureVarKeyVarIdentityRoutedRangeReads(
        LibraDexFileSession session,
        long rootOffset,
        int keyLength,
        int prefixCount,
        int itemCount,
        int iterations,
        VarIdentityIterationMode iterationMode,
        int maxRouterHops = 8)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        long checksum = 0;
        long total = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            long iterationChecksum = 0;
            using VarKeyVarIdentityRangeReader reader = session.OpenVarKeyVarIdentityRangeReader(rootOffset, maxKeyLength: 1024, maxIdentityLength: 1024, lower, upper, maxRouterHops);
            while (reader.MoveNext())
            {
                count++;
                iterationChecksum += ChecksumVarKeyVarIdentityCurrent(reader, iterationMode);
            }

            if (count != expected)
            {
                throw new InvalidDataException($"VV range expected {expected} identities, got {count}.");
            }

            total += count;
            checksum += iterationChecksum;
        }

        watch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        (int cacheArenaCount, long cacheBytes) = session.GetRouterArenaReadCacheStatsForValidation();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum, telemetry, cacheArenaCount, cacheBytes);
    }

    private static VarKeyScalar8ReadMeasurement MeasureSqliteVarKeyScalar8ExplicitRangeReads(
        SqliteConnection connection,
        ReadOnlySpan<byte> lower,
        ReadOnlySpan<byte> upper,
        int expected,
        int iterations)
    {
        long checksum = 0;
        long total = 0;
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;";
        command.Parameters.AddWithValue("$lower", lower.ToArray());
        command.Parameters.AddWithValue("$upper", upper.ToArray());
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            using SqliteDataReader reader = command.ExecuteReader();
            while (reader.Read())
            {
                checksum += unchecked((long)DecodeSqliteSortableUnsignedScalar8(reader.GetInt64(0)));
                count++;
            }

            if (count != expected)
            {
                throw new InvalidDataException($"SQLite VS8 explicit range expected {expected} identities, got {count}.");
            }

            total += count;
        }

        watch.Stop();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum);
    }

    /// <summary>
    /// Measures SQLite explicit raw-key range reads for the `VS16` comparison schema.<br/>
    /// This is the SQLite counterpart to `MeasureVarKeyScalar16ExplicitRangeReads`, using the same lower/upper raw byte keys and decoding the 16-byte identity BLOB.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    /// <param name="lower">The inclusive lower raw key.</param>
    /// <param name="upper">The inclusive upper raw key.</param>
    /// <param name="expected">The expected number of identities per iteration.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <returns>The SQLite range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureSqliteVarKeyScalar16ExplicitRangeReads(
        SqliteConnection connection,
        ReadOnlySpan<byte> lower,
        ReadOnlySpan<byte> upper,
        int expected,
        int iterations)
    {
        long checksum = 0;
        long total = 0;
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;";
        command.Parameters.AddWithValue("$lower", lower.ToArray());
        command.Parameters.AddWithValue("$upper", upper.ToArray());
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            using SqliteDataReader reader = command.ExecuteReader();
            while (reader.Read())
            {
                byte[] identity = (byte[])reader.GetValue(0);
                checksum += unchecked((long)BinaryPrimitives.ReadUInt64BigEndian(identity.AsSpan(0, 8)));
                checksum += unchecked((long)BinaryPrimitives.ReadUInt64BigEndian(identity.AsSpan(8, 8)));
                count++;
            }

            if (count != expected)
            {
                throw new InvalidDataException($"SQLite VS16 explicit range expected {expected} identities, got {count}.");
            }

            total += count;
        }

        watch.Stop();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum);
    }

    /// <summary>
    /// Measures SQLite prefix-range reads for the `VV` comparison schema.<br/>
    /// The query orders by raw key and raw identity bytes, matching the `VV` shelf tuple order used for duplicate-key stability.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="itemCount">The total generated identity count.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <returns>The SQLite range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureSqliteVarKeyVarIdentityRangeReads(SqliteConnection connection, int keyLength, int prefixCount, int itemCount, int iterations, VarIdentityIterationMode iterationMode)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        long checksum = 0;
        long total = 0;
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = CreateSqliteVarKeyVarIdentityRangeReadCommandText(iterationMode);
        command.Parameters.AddWithValue("$lower", lower);
        command.Parameters.AddWithValue("$upper", upper);
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            using SqliteDataReader reader = command.ExecuteReader();
            while (reader.Read())
            {
                checksum += ChecksumSqliteVarKeyVarIdentityCurrent(reader, iterationMode);
                count++;
            }

            if (count != expected)
            {
                throw new InvalidDataException($"SQLite VV read comparison expected {expected} identities, got {count}.");
            }

            total += count;
        }

        watch.Stop();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum);
    }

    private static VarKeyScalar8RouterShapeStats MeasureVarKeyScalar8RouterShapeStats(LibraDexFileSession session, long rootOffset)
    {
        VarKeyScalar8RouterShapeStatsBuilder builder = default;
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        VisitVarKeyScalar8RouterShape(session, rootOffset, depth: 0, visitedRouters, visitedShelves, ref builder);
        return builder.ToStats();
    }

    private static void VisitVarKeyScalar8RouterShape(
        LibraDexFileSession session,
        long routerOffset,
        int depth,
        RouteVisitedOffsetSet visitedRouters,
        RouteVisitedOffsetSet visitedShelves,
        ref VarKeyScalar8RouterShapeStatsBuilder builder)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return;
        }

        byte[] routerBytes = new byte[RouterLayout.Size];
        session.ReadRouterPageForRangeScan(routerOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        builder.RouterCount++;
        if (reader.HasDirectIndex)
        {
            builder.DirectRouterCount++;
        }

        if (reader.PrefixByteCount > 1)
        {
            builder.MultiByteRouterCount++;
        }

        for (int routeIndex = 0; routeIndex < reader.RouteCount; routeIndex++)
        {
            long targetOffset = reader.GetRouteTargetAt(routeIndex);
            if (targetOffset == 0)
            {
                continue;
            }

            if (TryVisitVarKeyScalar8ChildRouter(session, targetOffset, depth + 1, visitedRouters, visitedShelves, ref builder))
            {
                continue;
            }

            if (visitedShelves.Add(targetOffset))
            {
                builder.ShelfCount++;
                builder.LeafDepthTotal += depth + 1;
                builder.MaxRouteDepth = Math.Max(builder.MaxRouteDepth, depth + 1);
            }
        }
    }

    private static bool TryVisitVarKeyScalar8ChildRouter(
        LibraDexFileSession session,
        long targetOffset,
        int depth,
        RouteVisitedOffsetSet visitedRouters,
        RouteVisitedOffsetSet visitedShelves,
        ref VarKeyScalar8RouterShapeStatsBuilder builder)
    {
        try
        {
            byte[] routerBytes = new byte[RouterLayout.Size];
            session.ReadRouterPageForRangeScan(targetOffset, routerBytes);
        }
        catch (InvalidDataException)
        {
            return false;
        }

        VisitVarKeyScalar8RouterShape(session, targetOffset, depth, visitedRouters, visitedShelves, ref builder);
        return true;
    }

    /// <summary>
    /// Measures the bytes reachable from a `VS8` root router by summing distinct router pages and distinct shelf extents.<br/>
    /// This is a cold accounting helper for optimizer economics; it intentionally follows the currently reachable route graph rather than the whole file.<br/>
    /// Callers can subtract one router page when they need the reclaimable subtree below an unchanged root router.<br/>
    /// </summary>
    /// <param name="session">The opened or active session containing the route graph.</param>
    /// <param name="rootOffset">The root router offset to traverse.</param>
    /// <returns>The total bytes occupied by reachable router pages and `VS8` shelf extents.</returns>
    private static long MeasureVarKeyScalar8ReachableStorageBytes(LibraDexFileSession session, long rootOffset)
    {
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        return MeasureVarKeyScalar8ReachableStorageBytes(session, rootOffset, visitedRouters, visitedShelves);
    }

    private static long MeasureVarKeyScalar8ReachableStorageBytes(
        LibraDexFileSession session,
        long routerOffset,
        RouteVisitedOffsetSet visitedRouters,
        RouteVisitedOffsetSet visitedShelves)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        long total = RouterLayout.Size;
        byte[] routerBytes = new byte[RouterLayout.Size];
        session.ReadRouterPageForRangeScan(routerOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The VS8 reachable-storage traversal read an invalid router.");
        }

        for (int routeIndex = 0; routeIndex < reader.RouteCount; routeIndex++)
        {
            long targetOffset = reader.GetRouteTargetAt(routeIndex);
            if (targetOffset == 0)
            {
                continue;
            }

            VarKeyScalar8RouteTargetKind kind = session.ClassifyVarKeyScalar8RouteTarget(targetOffset);
            if (kind == VarKeyScalar8RouteTargetKind.Router)
            {
                total += MeasureVarKeyScalar8ReachableStorageBytes(session, targetOffset, visitedRouters, visitedShelves);
                continue;
            }

            if (kind == VarKeyScalar8RouteTargetKind.Shelf)
            {
                if (visitedShelves.Add(targetOffset))
                {
                    total += session.ReadVarKeyScalar8ShelfExtentSizeForValidation(targetOffset);
                }

                continue;
            }

            throw new InvalidDataException("The VS8 reachable-storage traversal found an unsupported route target.");
        }

        return total;
    }

    /// <summary>
    /// Measures the bytes reachable from a `VS16` root router by summing distinct router pages and distinct shelf extents.<br/>
    /// This is the widened-identity counterpart to the `VS8` optimizer economics helper and follows only the currently reachable route graph.<br/>
    /// Callers can subtract one router page when they need the reclaimable subtree below an unchanged root router.<br/>
    /// </summary>
    /// <param name="session">The opened or active session containing the route graph.</param>
    /// <param name="rootOffset">The root router offset to traverse.</param>
    /// <returns>The total bytes occupied by reachable router pages and `VS16` shelf extents.</returns>
    private static long MeasureVarKeyScalar16ReachableStorageBytes(LibraDexFileSession session, long rootOffset)
    {
        using RouteVisitedOffsetSet visitedRouters = RouteVisitedOffsetSet.Rent();
        using RouteVisitedOffsetSet visitedShelves = RouteVisitedOffsetSet.Rent();
        return MeasureVarKeyScalar16ReachableStorageBytes(session, rootOffset, visitedRouters, visitedShelves);
    }

    private static long MeasureVarKeyScalar16ReachableStorageBytes(
        LibraDexFileSession session,
        long routerOffset,
        RouteVisitedOffsetSet visitedRouters,
        RouteVisitedOffsetSet visitedShelves)
    {
        if (!visitedRouters.Add(routerOffset))
        {
            return 0;
        }

        long total = RouterLayout.Size;
        byte[] routerBytes = new byte[RouterLayout.Size];
        session.ReadRouterPageForRangeScan(routerOffset, routerBytes);
        RouterReader reader = new(routerBytes);
        if (!reader.IsValid)
        {
            throw new InvalidDataException("The VS16 reachable-storage traversal read an invalid router.");
        }

        for (int routeIndex = 0; routeIndex < reader.RouteCount; routeIndex++)
        {
            long targetOffset = reader.GetRouteTargetAt(routeIndex);
            if (targetOffset == 0)
            {
                continue;
            }

            VarKeyScalar16RouteTargetKind kind = session.ClassifyVarKeyScalar16RouteTarget(targetOffset);
            if (kind == VarKeyScalar16RouteTargetKind.Router)
            {
                total += MeasureVarKeyScalar16ReachableStorageBytes(session, targetOffset, visitedRouters, visitedShelves);
                continue;
            }

            if (kind == VarKeyScalar16RouteTargetKind.Shelf)
            {
                if (visitedShelves.Add(targetOffset))
                {
                    total += session.ReadVarKeyScalar16ShelfExtentSizeForValidation(targetOffset);
                }

                continue;
            }

            throw new InvalidDataException("The VS16 reachable-storage traversal found an unsupported route target.");
        }

        return total;
    }

    private static VarKeyScalar8HierarchicalBulkBuildResult CreateVarKeyScalar8HierarchicalBulkTree(
        LibraDexFileSession session,
        long rootOffset,
        ReadOnlySpan<byte[]> keys,
        int maxKeyLength,
        int requestedRouteCount)
    {
        (byte rootPrefix, long childRouterOffset, VarKeyScalar8HierarchicalBulkBuildResult result) = CreateVarKeyScalar8HierarchicalBulkSubtree(
            session,
            keys,
            maxKeyLength,
            requestedRouteCount);
        _ = session.UpdateRouterRoute(rootOffset, rootPrefix, rootPrefix, rootPrefix, childRouterOffset);
        return result;
    }

    private static (byte RootPrefix, long TargetOffset, VarKeyScalar8HierarchicalBulkBuildResult Build) CreateVarKeyScalar8HierarchicalBulkSubtree(
        LibraDexFileSession session,
        ReadOnlySpan<byte[]> keys,
        int maxKeyLength,
        int requestedRouteCount)
    {
        VarLenOptimizerReplacementSubtree subtree = session.CreateVarKeyScalar8OptimizerReplacementSubtree(keys, maxKeyLength, requestedRouteCount);
        VarKeyScalar8HierarchicalBulkBuildResult result = new(
            subtree.Build.FanoutDepth,
            subtree.Build.RouteCount,
            subtree.Build.RouterCount,
            subtree.Build.ShelfCount,
            subtree.Build.MaxPlannerDepth);
        return (subtree.RootPrefix, subtree.TargetOffset, result);
    }

    /// <summary>
    /// Builds one recursive `VS8` bulk node for a sorted contiguous item range.<br/>
    /// The method is a cold construction primitive: it first tries to pack the whole range into one shelf, and only creates a compressed multi-byte router when the range no longer fits the maximum shelf profile.<br/>
    /// Child targets are created before the parent router so route slots can persist final target offsets without later rewrites.<br/>
    /// </summary>
    /// <param name="session">The file session receiving shelves and routers.</param>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="keyDepth">The first key byte depth this node may consume.</param>
    /// <param name="maxKeyLength">The maximum raw key length supported by the target profile.</param>
    /// <param name="requestedRouteCount">The preferred route count cap for each compressed router.</param>
    /// <param name="state">The accumulated cold-planner shape telemetry.</param>
    /// <returns>The created shelf or router file offset for this node.</returns>
    private static long CreateVarKeyScalar8HierarchicalBulkNode(
        LibraDexFileSession session,
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        int keyDepth,
        int maxKeyLength,
        int requestedRouteCount,
        ref VarKeyScalar8HierarchicalBulkBuildState state)
    {
        if (TryBuildVarKeyScalar8BulkShelf(items, start, end, maxKeyLength, out VarKeyScalar8Profile profile, out byte[] shelfBytes))
        {
            (long shelfOffset, _) = session.CreateVarKeyScalar8Shelf(profile, shelfBytes);
            state.ShelfCount++;
            state.MaxPlannerDepth = Math.Max(state.MaxPlannerDepth, keyDepth);
            return shelfOffset;
        }

        int fanoutDepth = FindVarKeyScalar8FirstDivergenceDepth(items, start, end, keyDepth, maxKeyLength);
        if (state.FirstFanoutDepth == 0)
        {
            state.FirstFanoutDepth = fanoutDepth;
        }

        byte[] stem = CreateVarKeyScalar8BulkStem(items[start].Key, keyDepth, fanoutDepth);
        byte[] distinctFanoutBytes = CreateVarKeyScalar8DistinctFanoutBytes(items, start, end, fanoutDepth);
        int maxFittingRouteCount = CalculateVarKeyScalar8MaxBulkRouteCount(checked((byte)(fanoutDepth - keyDepth + 1)));
        int estimatedLeafCapacity = EstimateVarKeyScalar8BulkLeafCapacity(items, start, end, maxKeyLength);
        int minimumUsefulRouteCount = Math.Max(2, (end - start + estimatedLeafCapacity - 1) / estimatedLeafCapacity);
        int routeCount = Math.Min(Math.Min(Math.Min(Math.Max(1, requestedRouteCount), minimumUsefulRouteCount), distinctFanoutBytes.Length), maxFittingRouteCount);
        if (routeCount < distinctFanoutBytes.Length &&
            !DoVarKeyScalar8BulkRouteGroupsFitLeaves(items, start, end, fanoutDepth, distinctFanoutBytes, routeCount, maxKeyLength))
        {
            routeCount = Math.Min(distinctFanoutBytes.Length, maxFittingRouteCount);
        }

        if (routeCount <= 0)
        {
            throw new InvalidDataException("The hierarchical bulk route planner could not fit a compressed multi-byte route.");
        }

        RouterMultiByteRouteSnapshot[] routes = new RouterMultiByteRouteSnapshot[routeCount];
        int itemStart = start;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            int firstFanoutIndex = routeIndex * distinctFanoutBytes.Length / routeCount;
            int nextFanoutIndex = (routeIndex + 1) * distinctFanoutBytes.Length / routeCount;
            byte startByte = distinctFanoutBytes[firstFanoutIndex];
            byte endByte = routeIndex == routeCount - 1
                ? byte.MaxValue
                : checked((byte)(distinctFanoutBytes[nextFanoutIndex] - 1));
            int itemEnd = itemStart;
            while (itemEnd < end && GetVarKeyScalar8KeyByteOrZero(items[itemEnd].Key, fanoutDepth) <= endByte)
            {
                itemEnd++;
            }

            if (itemEnd == itemStart)
            {
                throw new InvalidDataException("The hierarchical bulk route planner produced an empty route.");
            }

            long targetOffset = CreateVarKeyScalar8HierarchicalBulkNode(
                session,
                items,
                itemStart,
                itemEnd,
                checked(fanoutDepth + 1),
                maxKeyLength,
                requestedRouteCount,
                ref state);
            routes[routeIndex] = new RouterMultiByteRouteSnapshot(stem, startByte, endByte, targetOffset);
            itemStart = itemEnd;
        }

        if (itemStart != end)
        {
            throw new InvalidDataException("The hierarchical bulk route planner did not consume every item in the current node.");
        }

        (RouterSnapshot router, _) = session.CreateCompressedMultiByteRouter(
            checked((byte)(fanoutDepth - keyDepth + 1)),
            checked((ushort)keyDepth),
            maxRouteCount: checked((ushort)routes.Length),
            allocationClassId: 0,
            routes);
        state.RouterCount++;
        state.RouteCount += routes.Length;
        state.MaxPlannerDepth = Math.Max(state.MaxPlannerDepth, fanoutDepth + 1);
        return router.Offset;
    }

    private static int FindVarKeyScalar8FirstDivergenceDepth(
        List<(byte[] Key, ulong Identity)> items,
        int startDepth,
        int maxKeyLength)
    {
        for (int depth = startDepth; depth < maxKeyLength; depth++)
        {
            byte first = GetVarKeyScalar8KeyByteOrZero(items[0].Key, depth);
            for (int i = 1; i < items.Count; i++)
            {
                if (GetVarKeyScalar8KeyByteOrZero(items[i].Key, depth) != first)
                {
                    return depth;
                }
            }
        }

        throw new InvalidDataException("The hierarchical bulk keys do not diverge within the maximum key length.");
    }

    /// <summary>
    /// Finds the first key byte depth where a sorted subrange diverges.<br/>
    /// This overload supports recursive cold bulk planning, where each child node has already consumed the parent route bytes and starts searching at a deeper byte position.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="startDepth">The first key byte depth to test.</param>
    /// <param name="maxKeyLength">The maximum supported key byte length.</param>
    /// <returns>The first divergent byte depth.</returns>
    private static int FindVarKeyScalar8FirstDivergenceDepth(
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        int startDepth,
        int maxKeyLength)
    {
        for (int depth = startDepth; depth < maxKeyLength; depth++)
        {
            byte first = GetVarKeyScalar8KeyByteOrZero(items[start].Key, depth);
            for (int i = start + 1; i < end; i++)
            {
                if (GetVarKeyScalar8KeyByteOrZero(items[i].Key, depth) != first)
                {
                    return depth;
                }
            }
        }

        throw new InvalidDataException("The hierarchical bulk keys do not diverge within the maximum key length.");
    }

    private static byte[] CreateVarKeyScalar8BulkStem(byte[] representativeKey, int keyDepth, int fanoutDepth)
    {
        byte[] stem = new byte[fanoutDepth - keyDepth];
        for (int i = 0; i < stem.Length; i++)
        {
            stem[i] = GetVarKeyScalar8KeyByteOrZero(representativeKey, keyDepth + i);
        }

        return stem;
    }

    private static byte[] CreateVarKeyScalar8DistinctFanoutBytes(
        List<(byte[] Key, ulong Identity)> items,
        int fanoutDepth)
    {
        List<byte> distinct = [];
        byte? previous = null;
        for (int i = 0; i < items.Count; i++)
        {
            byte current = GetVarKeyScalar8KeyByteOrZero(items[i].Key, fanoutDepth);
            if (previous is null || current != previous.Value)
            {
                distinct.Add(current);
                previous = current;
            }
        }

        return distinct.ToArray();
    }

    /// <summary>
    /// Creates the distinct sorted fanout bytes for a recursive item subrange.<br/>
    /// The caller uses these bytes to divide one cold-planned compressed router into non-overlapping final-byte ranges.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="fanoutDepth">The key byte depth that becomes the final consumed byte for the current router.</param>
    /// <returns>The distinct fanout bytes in sorted order.</returns>
    private static byte[] CreateVarKeyScalar8DistinctFanoutBytes(
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        int fanoutDepth)
    {
        List<byte> distinct = [];
        byte? previous = null;
        for (int i = start; i < end; i++)
        {
            byte current = GetVarKeyScalar8KeyByteOrZero(items[i].Key, fanoutDepth);
            if (previous is null || current != previous.Value)
            {
                distinct.Add(current);
                previous = current;
            }
        }

        return distinct.ToArray();
    }

    /// <summary>
    /// Calculates the maximum compressed multi-byte route count that fits in one router page for the supplied consumed byte count.<br/>
    /// This keeps recursive bulk planning from producing a valid logical route table that cannot be persisted inside the fixed router page.<br/>
    /// </summary>
    /// <param name="prefixByteCount">The number of key bytes consumed by the router.</param>
    /// <returns>The maximum persisted route count that fits inside the router page.</returns>
    private static int CalculateVarKeyScalar8MaxBulkRouteCount(byte prefixByteCount)
    {
        int routeCount = 256;
        while (routeCount > 0 &&
               RouterLayout.RoutesOffset + RouterLayout.GetMultiByteRouteStorageLength(routeCount, prefixByteCount) > RouterLayout.Size)
        {
            routeCount--;
        }

        return routeCount;
    }

    /// <summary>
    /// Estimates how many sorted `VS8` items from the current range fit in one maximum-size shelf.<br/>
    /// This cold planner helper intentionally measures with the real shelf builder instead of guessing from average key length, because varlen record overhead and slot reserve policy are part of the physical shape being planned.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="maxKeyLength">The maximum raw key length supported by the target profile.</param>
    /// <returns>The estimated maximum leaf item count, never less than one.</returns>
    private static int EstimateVarKeyScalar8BulkLeafCapacity(
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        int maxKeyLength)
    {
        int low = 1;
        int high = end - start;
        int best = 1;
        while (low <= high)
        {
            int mid = low + ((high - low) / 2);
            if (TryBuildVarKeyScalar8BulkShelf(items, start, start + mid, maxKeyLength, out _, out _))
            {
                best = mid;
                low = mid + 1;
            }
            else
            {
                high = mid - 1;
            }
        }

        return best;
    }

    /// <summary>
    /// Tests whether a compressed router grouping can terminate every route group as a shelf leaf.<br/>
    /// Grouping multiple final-byte fanout values is safe only for leaf targets, because a recursive child router would otherwise route on deeper bytes across a range whose primary full-key ordering is still dominated by the grouped parent byte.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="fanoutDepth">The final consumed key byte depth for the candidate router.</param>
    /// <param name="distinctFanoutBytes">The sorted distinct fanout bytes for the current item range.</param>
    /// <param name="routeCount">The candidate route count.</param>
    /// <param name="maxKeyLength">The maximum raw key length supported by the target profile.</param>
    /// <returns>True when every candidate route group fits in one shelf; otherwise, false.</returns>
    private static bool DoVarKeyScalar8BulkRouteGroupsFitLeaves(
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        int fanoutDepth,
        byte[] distinctFanoutBytes,
        int routeCount,
        int maxKeyLength)
    {
        int itemStart = start;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            int firstFanoutIndex = routeIndex * distinctFanoutBytes.Length / routeCount;
            int nextFanoutIndex = (routeIndex + 1) * distinctFanoutBytes.Length / routeCount;
            byte endByte = routeIndex == routeCount - 1
                ? byte.MaxValue
                : checked((byte)(distinctFanoutBytes[nextFanoutIndex] - 1));
            int itemEnd = itemStart;
            while (itemEnd < end && GetVarKeyScalar8KeyByteOrZero(items[itemEnd].Key, fanoutDepth) <= endByte)
            {
                itemEnd++;
            }

            if (itemEnd == itemStart ||
                !TryBuildVarKeyScalar8BulkShelf(items, itemStart, itemEnd, maxKeyLength, out _, out _))
            {
                return false;
            }

            itemStart = itemEnd;
        }

        return itemStart == end;
    }

    private static void BuildVarKeyScalar8BulkShelf(
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        out VarKeyScalar8Profile profile,
        out byte[] shelfBytes)
    {
        byte[][] shelfKeys = new byte[end - start][];
        ulong[] identities = new ulong[end - start];
        for (int i = start; i < end; i++)
        {
            shelfKeys[i - start] = items[i].Key;
            identities[i - start] = items[i].Identity;
        }

        profile = SelectVarKeyScalar8BuildProfile(shelfKeys, identities);
        if (!VarKeyScalar8.TryBuildFromSorted(shelfKeys, identities, profile, out shelfBytes))
        {
            throw new InvalidDataException("The hierarchical bulk shelf failed to build after profile selection.");
        }
    }

    /// <summary>
    /// Tries to build one `VS8` bulk shelf for a sorted item subrange.<br/>
    /// The method is used by the recursive bulk planner as the leaf test before it decides to introduce another compressed router level.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="maxKeyLength">The maximum raw key length supported by the target profile.</param>
    /// <param name="profile">The selected shelf profile when the range fits.</param>
    /// <param name="shelfBytes">The built shelf bytes when the range fits.</param>
    /// <returns>True when the range fits in one configured shelf; otherwise, false.</returns>
    private static bool TryBuildVarKeyScalar8BulkShelf(
        List<(byte[] Key, ulong Identity)> items,
        int start,
        int end,
        int maxKeyLength,
        out VarKeyScalar8Profile profile,
        out byte[] shelfBytes)
    {
        byte[][] shelfKeys = new byte[end - start][];
        ulong[] identities = new ulong[end - start];
        for (int i = start; i < end; i++)
        {
            shelfKeys[i - start] = items[i].Key;
            identities[i - start] = items[i].Identity;
        }

        profile = VarKeyScalar8Profile.DefaultInitial;
        if (profile.MaxKeyLength != maxKeyLength)
        {
            profile = VarKeyScalar8Profile.Create(profile.ShelfExtentSize, maxKeyLength);
        }

        while (!VarKeyScalar8.TryBuildFromSorted(shelfKeys, identities, profile, out shelfBytes))
        {
            VarKeyScalar8Profile next = profile.NextGrowthClass();
            if (next.ShelfExtentSize == profile.ShelfExtentSize)
            {
                shelfBytes = [];
                return false;
            }

            profile = next.MaxKeyLength == maxKeyLength
                ? next
                : VarKeyScalar8Profile.Create(next.ShelfExtentSize, maxKeyLength);
        }

        return true;
    }

    private static byte GetVarKeyScalar8KeyByteOrZero(byte[] key, int depth)
    {
        return depth >= 0 && depth < key.Length
            ? key[depth]
            : (byte)0;
    }

    private static VarKeyScalar16HierarchicalBulkBuildResult CreateVarKeyScalar16HierarchicalBulkTree(
        LibraDexFileSession session,
        long rootOffset,
        ReadOnlySpan<byte[]> keys,
        int maxKeyLength,
        int requestedRouteCount)
    {
        (byte rootPrefix, long childRouterOffset, VarKeyScalar16HierarchicalBulkBuildResult result) = CreateVarKeyScalar16HierarchicalBulkSubtree(
            session,
            keys,
            maxKeyLength,
            requestedRouteCount);
        _ = session.UpdateRouterRoute(rootOffset, rootPrefix, rootPrefix, rootPrefix, childRouterOffset);
        return result;
    }

    private static (byte RootPrefix, long TargetOffset, VarKeyScalar16HierarchicalBulkBuildResult Build) CreateVarKeyScalar16HierarchicalBulkSubtree(
        LibraDexFileSession session,
        ReadOnlySpan<byte[]> keys,
        int maxKeyLength,
        int requestedRouteCount)
    {
        VarLenOptimizerReplacementSubtree subtree = session.CreateVarKeyScalar16OptimizerReplacementSubtree(keys, maxKeyLength, requestedRouteCount);
        VarKeyScalar16HierarchicalBulkBuildResult result = new(
            subtree.Build.FanoutDepth,
            subtree.Build.RouteCount,
            subtree.Build.RouterCount,
            subtree.Build.ShelfCount,
            subtree.Build.MaxPlannerDepth);
        return (subtree.RootPrefix, subtree.TargetOffset, result);
    }

    /// <summary>
    /// Builds one recursive `VS16` bulk node for a sorted contiguous item range.<br/>
    /// The method is a cold construction primitive: it first tries to pack the whole range into one shelf, and only creates a compressed multi-byte router when the range no longer fits the maximum shelf profile.<br/>
    /// Child targets are created before the parent router so route slots can persist final target offsets without later rewrites.<br/>
    /// </summary>
    /// <param name="session">The file session receiving shelves and routers.</param>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="keyDepth">The first key byte depth this node may consume.</param>
    /// <param name="maxKeyLength">The maximum raw key length supported by the target profile.</param>
    /// <param name="requestedRouteCount">The preferred route count cap for each compressed router.</param>
    /// <param name="state">The accumulated cold-planner shape telemetry.</param>
    /// <returns>The created shelf or router file offset for this node.</returns>
    private static long CreateVarKeyScalar16HierarchicalBulkNode(
        LibraDexFileSession session,
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items,
        int start,
        int end,
        int keyDepth,
        int maxKeyLength,
        int requestedRouteCount,
        ref VarKeyScalar16HierarchicalBulkBuildState state)
    {
        if (TryBuildVarKeyScalar16BulkShelf(items, start, end, maxKeyLength, out VarKeyScalar16Profile profile, out byte[] shelfBytes))
        {
            (long shelfOffset, _) = session.CreateVarKeyScalar16Shelf(profile, shelfBytes);
            state.ShelfCount++;
            state.MaxPlannerDepth = Math.Max(state.MaxPlannerDepth, keyDepth);
            return shelfOffset;
        }

        int fanoutDepth = FindVarKeyScalar16FirstDivergenceDepth(items, start, end, keyDepth, maxKeyLength);
        if (state.FirstFanoutDepth == 0)
        {
            state.FirstFanoutDepth = fanoutDepth;
        }

        byte[] stem = CreateVarKeyScalar16BulkStem(items[start].Key, keyDepth, fanoutDepth);
        byte[] distinctFanoutBytes = CreateVarKeyScalar16DistinctFanoutBytes(items, start, end, fanoutDepth);
        int maxFittingRouteCount = CalculateVarKeyScalar16MaxBulkRouteCount(checked((byte)(fanoutDepth - keyDepth + 1)));
        int estimatedLeafCapacity = EstimateVarKeyScalar16BulkLeafCapacity(items, start, end, maxKeyLength);
        int minimumUsefulRouteCount = Math.Max(2, (end - start + estimatedLeafCapacity - 1) / estimatedLeafCapacity);
        int routeCount = Math.Min(Math.Min(Math.Min(Math.Max(1, requestedRouteCount), minimumUsefulRouteCount), distinctFanoutBytes.Length), maxFittingRouteCount);
        if (routeCount < distinctFanoutBytes.Length &&
            !DoVarKeyScalar16BulkRouteGroupsFitLeaves(items, start, end, fanoutDepth, distinctFanoutBytes, routeCount, maxKeyLength))
        {
            routeCount = Math.Min(distinctFanoutBytes.Length, maxFittingRouteCount);
        }

        if (routeCount <= 0)
        {
            throw new InvalidDataException("The hierarchical bulk route planner could not fit a compressed multi-byte route.");
        }

        RouterMultiByteRouteSnapshot[] routes = new RouterMultiByteRouteSnapshot[routeCount];
        int itemStart = start;
        for (int routeIndex = 0; routeIndex < routeCount; routeIndex++)
        {
            int firstFanoutIndex = routeIndex * distinctFanoutBytes.Length / routeCount;
            int nextFanoutIndex = (routeIndex + 1) * distinctFanoutBytes.Length / routeCount;
            byte startByte = distinctFanoutBytes[firstFanoutIndex];
            byte endByte = routeIndex == routeCount - 1
                ? byte.MaxValue
                : checked((byte)(distinctFanoutBytes[nextFanoutIndex] - 1));
            int itemEnd = itemStart;
            while (itemEnd < end && GetVarKeyScalar16KeyByteOrZero(items[itemEnd].Key, fanoutDepth) <= endByte)
            {
                itemEnd++;
            }

            if (itemEnd == itemStart)
            {
                throw new InvalidDataException("The hierarchical bulk route planner produced an empty route.");
            }

            long targetOffset = CreateVarKeyScalar16HierarchicalBulkNode(
                session,
                items,
                itemStart,
                itemEnd,
                checked(fanoutDepth + 1),
                maxKeyLength,
                requestedRouteCount,
                ref state);
            routes[routeIndex] = new RouterMultiByteRouteSnapshot(stem, startByte, endByte, targetOffset);
            itemStart = itemEnd;
        }

        if (itemStart != end)
        {
            throw new InvalidDataException("The hierarchical bulk route planner did not consume every item in the current node.");
        }

        (RouterSnapshot router, _) = session.CreateCompressedMultiByteRouter(
            checked((byte)(fanoutDepth - keyDepth + 1)),
            checked((ushort)keyDepth),
            maxRouteCount: checked((ushort)routes.Length),
            allocationClassId: 0,
            routes);
        state.RouterCount++;
        state.RouteCount += routes.Length;
        state.MaxPlannerDepth = Math.Max(state.MaxPlannerDepth, fanoutDepth + 1);
        return router.Offset;
    }

    private static int FindVarKeyScalar16FirstDivergenceDepth(
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items,
        int startDepth,
        int maxKeyLength)
    {
        for (int depth = startDepth; depth < maxKeyLength; depth++)
        {
            byte first = GetVarKeyScalar16KeyByteOrZero(items[0].Key, depth);
            for (int i = 1; i < items.Count; i++)
            {
                if (GetVarKeyScalar16KeyByteOrZero(items[i].Key, depth) != first)
                {
                    return depth;
                }
            }
        }

        throw new InvalidDataException("The hierarchical bulk keys do not diverge within the maximum key length.");
    }

    /// <summary>
    /// Finds the first key byte depth where a sorted subrange diverges.<br/>
    /// This overload supports recursive cold bulk planning, where each child node has already consumed the parent route bytes and starts searching at a deeper byte position.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="startDepth">The first key byte depth to test.</param>
    /// <param name="maxKeyLength">The maximum supported key byte length.</param>
    /// <returns>The first divergent byte depth.</returns>
    private static int FindVarKeyScalar16FirstDivergenceDepth(
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items,
        int start,
        int end,
        int startDepth,
        int maxKeyLength)
    {
        for (int depth = startDepth; depth < maxKeyLength; depth++)
        {
            byte first = GetVarKeyScalar16KeyByteOrZero(items[start].Key, depth);
            for (int i = start + 1; i < end; i++)
            {
                if (GetVarKeyScalar16KeyByteOrZero(items[i].Key, depth) != first)
                {
                    return depth;
                }
            }
        }

        throw new InvalidDataException("The hierarchical bulk keys do not diverge within the maximum key length.");
    }

    private static byte[] CreateVarKeyScalar16BulkStem(byte[] representativeKey, int keyDepth, int fanoutDepth)
    {
        byte[] stem = new byte[fanoutDepth - keyDepth];
        for (int i = 0; i < stem.Length; i++)
        {
            stem[i] = GetVarKeyScalar16KeyByteOrZero(representativeKey, keyDepth + i);
        }

        return stem;
    }

    private static byte[] CreateVarKeyScalar16DistinctFanoutBytes(
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items,
        int fanoutDepth)
    {
        List<byte> distinct = [];
        byte? previous = null;
        for (int i = 0; i < items.Count; i++)
        {
            byte current = GetVarKeyScalar16KeyByteOrZero(items[i].Key, fanoutDepth);
            if (previous is null || current != previous.Value)
            {
                distinct.Add(current);
                previous = current;
            }
        }

        return distinct.ToArray();
    }

    /// <summary>
    /// Creates the distinct sorted fanout bytes for a recursive item subrange.<br/>
    /// The caller uses these bytes to divide one cold-planned compressed router into non-overlapping final-byte ranges.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="fanoutDepth">The key byte depth that becomes the final consumed byte for the current router.</param>
    /// <returns>The distinct fanout bytes in sorted order.</returns>
    private static byte[] CreateVarKeyScalar16DistinctFanoutBytes(
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items,
        int start,
        int end,
        int fanoutDepth)
    {
        List<byte> distinct = [];
        byte? previous = null;
        for (int i = start; i < end; i++)
        {
            byte current = GetVarKeyScalar16KeyByteOrZero(items[i].Key, fanoutDepth);
            if (previous is null || current != previous.Value)
            {
                distinct.Add(current);
                previous = current;
            }
        }

        return distinct.ToArray();
    }

    /// <summary>
    /// Calculates the maximum compressed multi-byte route count that fits in one router page for the supplied consumed byte count.<br/>
    /// This keeps recursive bulk planning from producing a valid logical route table that cannot be persisted inside the fixed router page.<br/>
    /// </summary>
    /// <param name="prefixByteCount">The number of key bytes consumed by the router.</param>
    /// <returns>The maximum persisted route count that fits inside the router page.</returns>
    private static int CalculateVarKeyScalar16MaxBulkRouteCount(byte prefixByteCount)
    {
        int routeCount = 256;
        while (routeCount > 0 &&
               RouterLayout.RoutesOffset + RouterLayout.GetMultiByteRouteStorageLength(routeCount, prefixByteCount) > RouterLayout.Size)
        {
            routeCount--;
        }

        return routeCount;
    }

    /// <summary>
    /// Estimates how many sorted `VS16` items from the current range fit in one maximum-size shelf.<br/>
    /// This cold planner helper intentionally measures with the real shelf builder instead of guessing from average key length, because varlen record overhead and slot reserve policy are part of the physical shape being planned.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
    /// <param name="start">The inclusive start item index.</param>
    /// <param name="end">The exclusive end item index.</param>
    /// <param name="maxKeyLength">The maximum raw key length supported by the target profile.</param>
    /// <returns>The estimated maximum leaf item count, never less than one.</returns>
    private static int EstimateVarKeyScalar16BulkLeafCapacity(
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items,
        int start,
        int end,
        int maxKeyLength)
    {
        int low = 1;
        int high = end - start;
        int best = 1;
        while (low <= high)
        {
            int mid = low + ((high - low) / 2);
            if (TryBuildVarKeyScalar16BulkShelf(items, start, start + mid, maxKeyLength, out _, out _))
            {
                best = mid;
                low = mid + 1;
            }
            else
            {
                high = mid - 1;
            }
        }

        return best;
    }

    /// <summary>
    /// Tests whether a compressed router grouping can terminate every route group as a shelf leaf.<br/>
    /// Grouping multiple final-byte fanout values is safe only for leaf targets, because a recursive child router would otherwise route on deeper bytes across a range whose primary full-key ordering is still dominated by the grouped parent byte.<br/>
    /// </summary>
    /// <param name="items">The globally sorted key/identity pairs.</param>
