    /// <summary>
    /// Validates the version-checked route publish primitive used by cold `VS8` route optimization.<br/>
    /// The command first proves that a stale expected target cannot overwrite a route, then proves that the same replacement publishes when the observed target still matches.<br/>
    /// This models the short copy/build/publish coordination step needed for concurrent-friendly background route maintenance.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when stale publish is rejected and current publish succeeds.</returns>
    private static int RunVarKeyScalar8RouteVersionedPublishSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs8-route-versioned-publish-sanity.lbdx"));
        File.Delete(path);

        byte[][] keys =
        [
            Encoding.ASCII.GetBytes("/tenant/a/alpha"),
            Encoding.ASCII.GetBytes("/tenant/a/beta")
        ];

        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        long rootOffset;
        byte rootPrefix;
        long originalTargetOffset;
        long replacementTargetOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, libraOptions, CreateDesignPerfMetadata(818), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8vpub", 0));
            rootOffset = root.Offset;
            rootPrefix = keys[0][0];
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, rootPrefix, VarKeyScalar8Profile.DefaultInitial);
            originalTargetOffset = session.FindRouterTarget(rootOffset, rootPrefix);

            using (LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch())
            {
                (_, replacementTargetOffset, _) = CreateVarKeyScalar8HierarchicalBulkSubtree(session, keys, maxKeyLength: 64, requestedRouteCount: 4);
                bool stalePublished = session.TryUpdateRouterRouteTargetIfCurrent(
                    rootOffset,
                    rootPrefix,
                    expectedTargetOffset: originalTargetOffset + 1,
                    replacementTargetOffset,
                    out _);
                if (stalePublished)
                {
                    throw new InvalidDataException("The VS8 versioned publish accepted a stale expected target.");
                }

                long targetAfterRejectedPublish = session.FindRouterTarget(rootOffset, rootPrefix);
                if (targetAfterRejectedPublish != originalTargetOffset)
                {
                    throw new InvalidDataException("The VS8 versioned publish changed the route after rejecting a stale target.");
                }

                bool currentPublished = session.TryUpdateRouterRouteTargetIfCurrent(
                    rootOffset,
                    rootPrefix,
                    originalTargetOffset,
                    replacementTargetOffset,
                    out _);
                if (!currentPublished)
                {
                    throw new InvalidDataException("The VS8 versioned publish rejected the current expected target.");
                }

                _ = batch.Commit();
            }
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            long reopenedTargetOffset = reopened.FindRouterTarget(rootOffset, rootPrefix);
            if (reopenedTargetOffset != replacementTargetOffset)
            {
                throw new InvalidDataException("The VS8 versioned publish did not persist the replacement target.");
            }
        }

        Console.WriteLine($"vs8-route-versioned-publish-sanity ok path={path} root={rootOffset} prefix={rootPrefix:X2} original={originalTargetOffset} replacement={replacementTargetOffset}");
        return 0;
    }

    /// <summary>
    /// Validates that shared promoted compressed-router views preserve routed varlen writes for both `VS8` and `VS16`.<br/>
    /// The command bulk-builds an initial hierarchical subtree, reopens the file, then inserts additional rows through the walked route path so the session must route through a direct root and a compressed multi-byte child router.<br/>
    /// It proves the promoted view is shape-neutral by reading the complete range after reopen for both identity widths.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when both `VS8` and `VS16` promoted-router walked inserts persist and range-read correctly.</returns>
    private static int RunVarLenPromotedRouterViewSanity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VarLenPromotedRouterViewSanity"));
        int initialCount = GetIntOption(args, "--initial-items", 768);
        int additionalCount = GetIntOption(args, "--additional-items", 128);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 48);
        int branchCount = GetIntOption(args, "--branch-count", 16);
        if (initialCount <= 0 || additionalCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 1 || branchCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Varlen promoted-router sanity requires positive counts, max key length 1-1024, and branch count 2-256.");
        }

        Directory.CreateDirectory(directory);
        int totalCount = checked(initialCount + additionalCount);
        byte[][] keys = new byte[totalCount][];
        for (int i = 0; i < totalCount; i++)
        {
            keys[i] = CreateVarKeyScalar8HierarchicalKey(i, sharedPrefixLength, branchCount, maxKeyLength);
        }

        byte[] lower = CreateVarKeyScalar8HierarchicalRangeLower(sharedPrefixLength);
        byte[] upper = CreateVarKeyScalar8HierarchicalRangeUpper(sharedPrefixLength);
        DataKernelOptions options = CreateDesignPerfOptions();
        string vs8Path = Path.Combine(directory, "vs8-promoted-router-view-sanity.lbdx");
        string vs16Path = Path.Combine(directory, "vs16-promoted-router-view-sanity.lbdx");
        File.Delete(vs8Path);
        File.Delete(vs16Path);

        long vs8RootOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(vs8Path, options, CreateDesignPerfMetadata(819), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8prv", 0));
            vs8RootOffset = root.Offset;
            using LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch();
            _ = CreateVarKeyScalar8HierarchicalBulkTree(session, vs8RootOffset, keys.AsSpan(0, initialCount), maxKeyLength, branchCount);
            _ = batch.Commit();
        }

        using (LibraDexFileSession session = LibraDexFileSession.Open(vs8Path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            using LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch();
            for (int i = initialCount; i < totalCount; i++)
            {
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(vs8RootOffset, maxKeyLength, keys[i], CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 16);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected promoted-router VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }
            }

            _ = batch.Commit();
        }

        long vs8Checksum = 0;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(vs8Path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            ulong[] identities = new ulong[totalCount];
            int copied = reopened.ReadVarKeyScalar8IdentityRange(vs8RootOffset, maxKeyLength, lower, upper, identities);
            if (copied != totalCount)
            {
                throw new InvalidDataException($"Promoted-router VS8 range returned {copied} identities; expected {totalCount}.");
            }

            for (int i = 0; i < copied; i++)
            {
                vs8Checksum += unchecked((long)identities[i]);
            }
        }

        long vs16RootOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(vs16Path, options, CreateDesignPerfMetadata(820), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16prv", 0));
            vs16RootOffset = root.Offset;
            using LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch();
            _ = CreateVarKeyScalar16HierarchicalBulkTree(session, vs16RootOffset, keys.AsSpan(0, initialCount), maxKeyLength, branchCount);
            _ = batch.Commit();
        }

        using (LibraDexFileSession session = LibraDexFileSession.Open(vs16Path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            using LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch();
            for (int i = initialCount; i < totalCount; i++)
            {
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(vs16RootOffset, maxKeyLength, keys[i], identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 16);
                if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected promoted-router VS16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }
            }

            _ = batch.Commit();
        }

        long vs16Checksum = 0;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(vs16Path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            ulong[] identityHighs = new ulong[totalCount];
            ulong[] identityLows = new ulong[totalCount];
            int copied = reopened.ReadVarKeyScalar16IdentityRange(vs16RootOffset, maxKeyLength, lower, upper, identityHighs, identityLows);
            if (copied != totalCount)
            {
                throw new InvalidDataException($"Promoted-router VS16 range returned {copied} identities; expected {totalCount}.");
            }

            for (int i = 0; i < copied; i++)
            {
                vs16Checksum += unchecked((long)identityHighs[i]);
                vs16Checksum += unchecked((long)identityLows[i]);
            }
        }

        Console.WriteLine("varlen promoted router view sanity");
        Console.WriteLine($"directory {directory}");
        Console.WriteLine($"initialItems {initialCount}");
        Console.WriteLine($"additionalItems {additionalCount}");
        Console.WriteLine($"totalItems {totalCount}");
        Console.WriteLine($"maxKeyLength {maxKeyLength}");
        Console.WriteLine($"sharedPrefixLength {sharedPrefixLength}");
        Console.WriteLine($"branchCount {branchCount}");
        Console.WriteLine($"vs8Checksum {vs8Checksum}");
        Console.WriteLine($"vs16Checksum {vs16Checksum}");
        Console.WriteLine("varlen-promoted-router-view-sanity ok");
        return 0;
    }

    /// <summary>
    /// Validates queued varlen route maintenance against stale candidate targets for both `VS8` and `VS16`.<br/>
    /// The command performs a full walked hierarchical build, records the first optimizer queue candidate, proves that the candidate's stored target offset has gone stale by maintenance time, rejects a publish using that stale expected target, then refreshes the current route target and publishes successfully.<br/>
    /// This guards the design rule that optimizer queue entries are evidence/locators, not durable publish tokens.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when stale publish is rejected, refreshed publish succeeds, and both shapes reopen with complete range results.</returns>
    private static int RunVarLenQueuedMaintenanceSanity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VarLenQueuedMaintenanceSanity"));
        int itemCount = GetIntOption(args, "--items", 12000);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 48);
        int branchCount = GetIntOption(args, "--branch-count", 16);
        int candidateDepth = GetIntOption(args, "--candidate-depth", DefaultVarKeyScalar8ColdCandidateDepth);
        int candidateShelfItems = GetIntOption(args, "--candidate-shelf-items", DefaultVarKeyScalar8ColdCandidateShelfItems);
        int candidateHitCount = GetIntOption(args, "--candidate-hit-count", DefaultVarKeyScalar8ColdCandidateHitCount);
        if (itemCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 1 || branchCount > 256 || candidateDepth < 0 || candidateShelfItems < 0 || candidateHitCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Varlen queued maintenance sanity requires positive counts, max key length 1-1024, branch count 2-256, and positive candidate settings.");
        }

        Directory.CreateDirectory(directory);
        byte[][] keys = new byte[itemCount][];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = CreateVarKeyScalar8HierarchicalKey(i, sharedPrefixLength, branchCount, maxKeyLength);
        }

        byte[] lower = CreateVarKeyScalar8HierarchicalRangeLower(sharedPrefixLength);
        byte[] upper = CreateVarKeyScalar8HierarchicalRangeUpper(sharedPrefixLength);
        DataKernelOptions options = CreateDesignPerfOptions();
        string vs8Path = Path.Combine(directory, "vs8-queued-maintenance-sanity.lbdx");
        string vs16Path = Path.Combine(directory, "vs16-queued-maintenance-sanity.lbdx");
        File.Delete(vs8Path);
        File.Delete(vs16Path);

        (int Vs8EnqueueAt, long Vs8StaleTarget, long Vs8CurrentTarget, long Vs8Replacement, long Vs8Checksum) = ValidateVarKeyScalar8QueuedMaintenance(
            vs8Path,
            options,
            keys,
            maxKeyLength,
            branchCount,
            candidateDepth,
            candidateShelfItems,
            candidateHitCount,
            lower,
            upper);
        (int Vs16EnqueueAt, long Vs16StaleTarget, long Vs16CurrentTarget, long Vs16Replacement, long Vs16Checksum) = ValidateVarKeyScalar16QueuedMaintenance(
            vs16Path,
            options,
            keys,
            maxKeyLength,
            branchCount,
            candidateDepth,
            candidateShelfItems,
            candidateHitCount,
            lower,
            upper);

        Console.WriteLine("varlen queued maintenance sanity");
        Console.WriteLine($"directory {directory}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"maxKeyLength {maxKeyLength}");
        Console.WriteLine($"sharedPrefixLength {sharedPrefixLength}");
        Console.WriteLine($"branchCount {branchCount}");
        Console.WriteLine($"candidateDepth {candidateDepth}");
        Console.WriteLine($"candidateShelfItems {candidateShelfItems}");
        Console.WriteLine($"candidateHitCount {candidateHitCount}");
        Console.WriteLine($"vs8FirstEnqueueAt {Vs8EnqueueAt}");
        Console.WriteLine($"vs8StaleTarget {Vs8StaleTarget}");
        Console.WriteLine($"vs8CurrentTarget {Vs8CurrentTarget}");
        Console.WriteLine($"vs8ReplacementTarget {Vs8Replacement}");
        Console.WriteLine($"vs8Checksum {Vs8Checksum}");
        Console.WriteLine($"vs16FirstEnqueueAt {Vs16EnqueueAt}");
        Console.WriteLine($"vs16StaleTarget {Vs16StaleTarget}");
        Console.WriteLine($"vs16CurrentTarget {Vs16CurrentTarget}");
        Console.WriteLine($"vs16ReplacementTarget {Vs16Replacement}");
        Console.WriteLine($"vs16Checksum {Vs16Checksum}");
        Console.WriteLine("varlen-queued-maintenance-sanity ok");
        return 0;
    }

    /// <summary>
    /// Validates the two intended optimizer use modes for routed varlen shapes.<br/>
    /// The on-demand mode walks a full write set, drains one queued candidate after the write, and publishes by refreshing the current route target before replacement.<br/>
    /// The automatic mode drains the same bounded primitive between write batches immediately after the queue first identifies a repeated deep route.<br/>
    /// This remains harness-local until the planner and maintenance policy are promoted from proof code into the library surface.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when `VS8` and `VS16` both pass on-demand and between-batch optimizer validation.</returns>
    private static int RunVarLenOptimizerModesSanity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VarLenOptimizerModesSanity"));
        int itemCount = GetIntOption(args, "--items", 12000);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 48);
        int branchCount = GetIntOption(args, "--branch-count", 16);
        int candidateDepth = GetIntOption(args, "--candidate-depth", DefaultVarKeyScalar8ColdCandidateDepth);
        int candidateShelfItems = GetIntOption(args, "--candidate-shelf-items", DefaultVarKeyScalar8ColdCandidateShelfItems);
        int candidateHitCount = GetIntOption(args, "--candidate-hit-count", DefaultVarKeyScalar8ColdCandidateHitCount);
        if (itemCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 1 || branchCount > 256 || candidateDepth < 0 || candidateShelfItems < 0 || candidateHitCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Varlen optimizer mode sanity requires positive counts, max key length 1-1024, branch count 2-256, and positive candidate settings.");
        }

        Directory.CreateDirectory(directory);
        byte[][] keys = new byte[itemCount][];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = CreateVarKeyScalar8HierarchicalKey(i, sharedPrefixLength, branchCount, maxKeyLength);
        }

        byte[] lower = CreateVarKeyScalar8HierarchicalRangeLower(sharedPrefixLength);
        byte[] upper = CreateVarKeyScalar8HierarchicalRangeUpper(sharedPrefixLength);
        DataKernelOptions options = CreateDesignPerfOptions();
        VarLenOptimizerMaintenancePolicy onDemandPolicy = VarLenOptimizerMaintenancePolicy.OnDemand(candidateDepth, candidateShelfItems, candidateHitCount);
        VarLenOptimizerMaintenancePolicy automaticPolicy = VarLenOptimizerMaintenancePolicy.Automatic(candidateDepth, candidateShelfItems, candidateHitCount);
        if (onDemandPolicy.ShouldDrain(VarLenOptimizerMaintenanceBoundary.HotWrite, candidateQueued: true, alreadyPublishedAtBoundary: 0) ||
            onDemandPolicy.ShouldDrain(VarLenOptimizerMaintenanceBoundary.BetweenHotActions, candidateQueued: true, alreadyPublishedAtBoundary: 0) ||
            automaticPolicy.ShouldDrain(VarLenOptimizerMaintenanceBoundary.HotWrite, candidateQueued: true, alreadyPublishedAtBoundary: 0) ||
            automaticPolicy.ShouldDrain(VarLenOptimizerMaintenanceBoundary.OnDemand, candidateQueued: true, alreadyPublishedAtBoundary: 0))
        {
            throw new InvalidDataException("Varlen optimizer maintenance policy allowed maintenance at the wrong scheduler boundary.");
        }

        string vs8OnDemandPath = Path.Combine(directory, "vs8-optimizer-on-demand-sanity.lbdx");
        string vs8AutomaticPath = Path.Combine(directory, "vs8-optimizer-automatic-sanity.lbdx");
        string vs16OnDemandPath = Path.Combine(directory, "vs16-optimizer-on-demand-sanity.lbdx");
        string vs16AutomaticPath = Path.Combine(directory, "vs16-optimizer-automatic-sanity.lbdx");
        File.Delete(vs8OnDemandPath);
        File.Delete(vs8AutomaticPath);
        File.Delete(vs16OnDemandPath);
        File.Delete(vs16AutomaticPath);

        VarLenOptimizerModeShapeResult vs8OnDemand = ValidateVarKeyScalar8OptimizerOnDemandMode(
            vs8OnDemandPath,
            options,
            keys,
            maxKeyLength,
            branchCount,
            onDemandPolicy,
            lower,
            upper);
        VarLenOptimizerModeShapeResult vs8Automatic = ValidateVarKeyScalar8OptimizerAutomaticMode(
            vs8AutomaticPath,
            options,
            keys,
            maxKeyLength,
            branchCount,
            automaticPolicy,
            lower,
            upper);
        VarLenOptimizerModeShapeResult vs16OnDemand = ValidateVarKeyScalar16OptimizerOnDemandMode(
            vs16OnDemandPath,
            options,
            keys,
            maxKeyLength,
            branchCount,
            onDemandPolicy,
            lower,
            upper);
        VarLenOptimizerModeShapeResult vs16Automatic = ValidateVarKeyScalar16OptimizerAutomaticMode(
            vs16AutomaticPath,
            options,
            keys,
            maxKeyLength,
            branchCount,
            automaticPolicy,
            lower,
            upper);
        if (vs8OnDemand.CandidateCount < 2 || vs16OnDemand.CandidateCount < 2)
        {
            throw new InvalidDataException("Varlen optimizer mode sanity expected full-walk on-demand mode to retain later queued candidates after the first candidate.");
        }

        if (vs8OnDemand.Maintenance.ConsideredCount < 2 ||
            vs16OnDemand.Maintenance.ConsideredCount < 2 ||
            vs8OnDemand.Maintenance.CoveredCandidateCount < 1 ||
            vs16OnDemand.Maintenance.CoveredCandidateCount < 1)
        {
            throw new InvalidDataException("Varlen optimizer mode sanity expected on-demand maintenance to consider later queued candidates and mark same-root work as covered.");
        }

        if (vs8Automatic.Maintenance.ConsideredCount != 1 ||
            vs16Automatic.Maintenance.ConsideredCount != 1 ||
            vs8Automatic.Maintenance.CoveredCandidateCount != 0 ||
            vs16Automatic.Maintenance.CoveredCandidateCount != 0)
        {
            throw new InvalidDataException("Varlen optimizer mode sanity expected automatic maintenance to remain a one-candidate boundary.");
        }

        Console.WriteLine("varlen optimizer modes sanity");
        Console.WriteLine($"directory {directory}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"maxKeyLength {maxKeyLength}");
        Console.WriteLine($"sharedPrefixLength {sharedPrefixLength}");
        Console.WriteLine($"branchCount {branchCount}");
        Console.WriteLine($"candidateDepth {candidateDepth}");
        Console.WriteLine($"candidateShelfItems {candidateShelfItems}");
        Console.WriteLine($"candidateHitCount {candidateHitCount}");
        Console.WriteLine("policyBoundaryGuards ok");
        Console.WriteLine("candidateQueueRetention ok");
        Console.WriteLine("onDemandCoveredCandidateCoalescing ok");
        PrintVarLenOptimizerModeResult("vs8OnDemand", vs8OnDemand);
        PrintVarLenOptimizerModeResult("vs8Automatic", vs8Automatic);
        PrintVarLenOptimizerModeResult("vs16OnDemand", vs16OnDemand);
        PrintVarLenOptimizerModeResult("vs16Automatic", vs16Automatic);
        Console.WriteLine("varlen-optimizer-modes-sanity ok");
        return 0;
    }

    /// <summary>
    /// Prints one optimizer-mode validation row in a compact key/value form.<br/>
    /// The row is intentionally stable enough for quick visual comparison while remaining cheap to extend as the maintenance primitive grows.<br/>
    /// </summary>
    /// <param name="name">The row label.</param>
    /// <param name="result">The validation result to print.</param>
    private static void PrintVarLenOptimizerModeResult(string name, VarLenOptimizerModeShapeResult result)
    {
        Console.WriteLine(
            string.Create(
                CultureInfo.InvariantCulture,
                $"{name} firstEnqueueAt={result.FirstEnqueueAt} candidates={result.CandidateCount} considered={result.Maintenance.ConsideredCount} attempted={result.Maintenance.AttemptedCount} published={result.Maintenance.PublishedCount} covered={result.Maintenance.CoveredCandidateCount} staleCandidates={result.Maintenance.StaleCandidateTargetCount} rejected={result.Maintenance.RejectedCount} builtKeys={result.Maintenance.BuiltKeyCount} elapsedMs={result.Maintenance.Elapsed.TotalMilliseconds:F3} candidateTarget={result.Maintenance.CandidateTargetOffset} refreshedTarget={result.Maintenance.RefreshedTargetOffset} replacementTarget={result.Maintenance.ReplacementTargetOffset} routers={result.RouterStats.RouterCount} mbRouters={result.RouterStats.MultiByteRouterCount} shelves={result.RouterStats.ShelfCount} maxDepth={result.RouterStats.MaxRouteDepth} checksum={result.Checksum}"));
    }

    /// <summary>
