    private static (int FirstEnqueueAt, long StaleTarget, long CurrentTarget, long ReplacementTarget, long Checksum) ValidateVarKeyScalar8QueuedMaintenance(
        string path,
        DataKernelOptions options,
        byte[][] keys,
        int maxKeyLength,
        int branchCount,
        int candidateDepth,
        int candidateShelfItems,
        int candidateHitCount,
        byte[] lower,
        byte[] upper)
    {
        long rootOffset;
        VarLenRouteOptimizerState optimizerState;
        int firstEnqueueAt;
        long staleTarget;
        long refreshedTarget;
        long replacementTarget;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(821), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8qmnt", 0));
            rootOffset = root.Offset;
            optimizerState = session.GetOrCreateVarLenRouteOptimizerState(rootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, keys[0][0], VarKeyScalar8Profile.DefaultInitial);
            using (LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch())
            {
                for (int i = 0; i < keys.Length; i++)
                {
                    VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength, keys[i], CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 16);
                    if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected queued-maintenance VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                    }

                    optimizerState.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, rootOffset, result.PrimaryOffset);
                }

                _ = batch.Commit();
            }

            VarLenRouteOptimizerCandidate candidate = optimizerState.FirstCandidate;
            if (candidate.LastObservedAt == 0)
            {
                throw new InvalidDataException("The VS8 queued-maintenance sanity did not enqueue an optimizer candidate.");
            }

            byte rootPrefix = keys[candidate.LastObservedAt - 1][0];
            long currentTarget = session.FindRouterTarget(rootOffset, rootPrefix);
            if (currentTarget == candidate.CurrentTargetOffset)
            {
                throw new InvalidDataException("The VS8 queued-maintenance sanity expected the queued candidate target to be stale by maintenance time.");
            }

            using (LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch())
            {
                (byte subtreeRootPrefix, replacementTarget, _) = CreateVarKeyScalar8HierarchicalBulkSubtree(session, keys, maxKeyLength, branchCount);
                if (subtreeRootPrefix != rootPrefix)
                {
                    throw new InvalidDataException("The VS8 queued-maintenance sanity built a subtree for an unexpected root prefix.");
                }

                bool stalePublished = session.TryUpdateRouterRouteTargetIfCurrent(rootOffset, rootPrefix, candidate.CurrentTargetOffset, replacementTarget, out _);
                if (stalePublished)
                {
                    throw new InvalidDataException("The VS8 queued-maintenance sanity accepted a stale queued target as the publish expectation.");
                }

                long targetAfterRejectedPublish = session.FindRouterTarget(rootOffset, rootPrefix);
                if (targetAfterRejectedPublish != currentTarget)
                {
                    throw new InvalidDataException("The VS8 queued-maintenance sanity changed the route after rejecting the stale queued target.");
                }

                bool currentPublished = session.TryUpdateRouterRouteTargetIfCurrent(rootOffset, rootPrefix, currentTarget, replacementTarget, out _);
                if (!currentPublished)
                {
                    throw new InvalidDataException("The VS8 queued-maintenance sanity rejected the refreshed current target.");
                }

                _ = batch.Commit();
            }

            firstEnqueueAt = optimizerState.FirstEnqueueAt;
            staleTarget = candidate.CurrentTargetOffset;
            refreshedTarget = currentTarget;
        }

        long checksum = ReadVarKeyScalar8QueuedMaintenanceChecksum(path, options, rootOffset, maxKeyLength, lower, upper, keys.Length);
        return (firstEnqueueAt, staleTarget, refreshedTarget, replacementTarget, checksum);
    }

    private static long ReadVarKeyScalar8QueuedMaintenanceChecksum(
        string path,
        DataKernelOptions options,
        long rootOffset,
        int maxKeyLength,
        byte[] lower,
        byte[] upper,
        int expectedCount)
    {
        using LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions);
        ulong[] identities = new ulong[expectedCount];
        int copied = reopened.ReadVarKeyScalar8IdentityRange(rootOffset, maxKeyLength, lower, upper, identities);
        if (copied != expectedCount)
        {
            throw new InvalidDataException($"Reopened queued-maintenance VS8 range returned {copied} identities; expected {expectedCount}.");
        }

        long checksum = 0;
        for (int i = 0; i < copied; i++)
        {
            checksum += unchecked((long)identities[i]);
        }

        return checksum;
    }

