                    CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                    VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(rootOffset, maxKeyLength, keys[i], identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 16);
                    if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected queued-maintenance VS16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                    }

                    optimizerState.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, rootOffset, result.PrimaryOffset);
                }

                _ = batch.Commit();
            }

            VarLenRouteOptimizerCandidate candidate = optimizerState.FirstCandidate;
            if (candidate.LastObservedAt == 0)
            {
                throw new InvalidDataException("The VS16 queued-maintenance sanity did not enqueue an optimizer candidate.");
            }

            byte rootPrefix = keys[candidate.LastObservedAt - 1][0];
            long currentTarget = session.FindRouterTarget(rootOffset, rootPrefix);
            if (currentTarget == candidate.CurrentTargetOffset)
            {
                throw new InvalidDataException("The VS16 queued-maintenance sanity expected the queued candidate target to be stale by maintenance time.");
            }

            using (LibraDexFileSessionDurabilityBatch batch = session.BeginDurabilityBatch())
            {
                (byte subtreeRootPrefix, replacementTarget, _) = CreateVarKeyScalar16HierarchicalBulkSubtree(session, keys, maxKeyLength, branchCount);
                if (subtreeRootPrefix != rootPrefix)
                {
                    throw new InvalidDataException("The VS16 queued-maintenance sanity built a subtree for an unexpected root prefix.");
                }

                bool stalePublished = session.TryUpdateRouterRouteTargetIfCurrent(rootOffset, rootPrefix, candidate.CurrentTargetOffset, replacementTarget, out _);
                if (stalePublished)
                {
                    throw new InvalidDataException("The VS16 queued-maintenance sanity accepted a stale queued target as the publish expectation.");
                }

                long targetAfterRejectedPublish = session.FindRouterTarget(rootOffset, rootPrefix);
                if (targetAfterRejectedPublish != currentTarget)
                {
                    throw new InvalidDataException("The VS16 queued-maintenance sanity changed the route after rejecting the stale queued target.");
                }

                bool currentPublished = session.TryUpdateRouterRouteTargetIfCurrent(rootOffset, rootPrefix, currentTarget, replacementTarget, out _);
                if (!currentPublished)
                {
                    throw new InvalidDataException("The VS16 queued-maintenance sanity rejected the refreshed current target.");
                }

                _ = batch.Commit();
            }

            firstEnqueueAt = optimizerState.FirstEnqueueAt;
            staleTarget = candidate.CurrentTargetOffset;
            refreshedTarget = currentTarget;
        }

        long checksum = ReadVarKeyScalar16QueuedMaintenanceChecksum(path, options, rootOffset, maxKeyLength, lower, upper, keys.Length);
        return (firstEnqueueAt, staleTarget, refreshedTarget, replacementTarget, checksum);
    }

    private static long ReadVarKeyScalar16QueuedMaintenanceChecksum(
        string path,
        DataKernelOptions options,
        long rootOffset,
        int maxKeyLength,
        byte[] lower,
        byte[] upper,
        int expectedCount)
    {
        using LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions);
        ulong[] identityHighs = new ulong[expectedCount];
        ulong[] identityLows = new ulong[expectedCount];
        int copied = reopened.ReadVarKeyScalar16IdentityRange(rootOffset, maxKeyLength, lower, upper, identityHighs, identityLows);
        if (copied != expectedCount)
        {
            throw new InvalidDataException($"Reopened queued-maintenance VS16 range returned {copied} identities; expected {expectedCount}.");
        }

        long checksum = 0;
        for (int i = 0; i < copied; i++)
        {
            checksum += unchecked((long)identityHighs[i]);
            checksum += unchecked((long)identityLows[i]);
        }

        return checksum;
    }

    /// <summary>
    /// Validates the first session-backed routed `VS8` path.<br/>
    /// The command creates one root route per requested prefix, inserts raw byte keys through `LibraDexFileSession`, forces shelf growth when needed, reopens the file, and range-reads across prefixes.<br/>
    /// This is the first DataKernel-backed proof for varlen keys; deeper child-router split policy is intentionally outside this command.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when routed persistence, growth, reopen, and range read validate.</returns>
    private static int RunVarKeyScalar8RoutedSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs8-routed-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 1024);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 routed sanity requires positive items, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(808), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8route", 0));
            rootOffset = root.Offset;
            for (int prefix = 0; prefix < prefixCount; prefix++)
            {
                _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, (byte)prefix, VarKeyScalar8Profile.DefaultInitial);
            }

            long growCount = 0;
            long transformCount = 0;
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength: 1024, key, CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                }
            }

            Console.WriteLine($"vs8 routed insert growths {growCount}");
            Console.WriteLine($"vs8 routed insert transforms {transformCount}");
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
            byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
            ulong[] identities = new ulong[itemCount];
            int copied = reopened.ReadVarKeyScalar8IdentityRange(rootOffset, maxKeyLength: 1024, lower, upper, identities);
            int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
            if (copied != expected)
            {
                throw new InvalidDataException($"Routed VS8 range returned {copied} identities; expected {expected}.");
            }

            long checksum = 0;
            for (int i = 0; i < copied; i++)
            {
                checksum += unchecked((long)identities[i]);
            }

            Console.WriteLine($"vs8-routed-sanity ok path={path} items={itemCount} keyLength={keyLength} prefixCount={prefixCount} rangeCount={copied} checksum={checksum}");
        }

        return 0;
    }

    /// <summary>
    /// Validates that a full `VS8` shelf with a long shared raw-key prefix transforms into one multi-byte child router instead of an appended one-byte router chain.<br/>
    /// The command forces all inserted keys through a single root route, keeps several deeper key bytes identical, verifies the transformed child router consumes multiple bytes, then reopens and range-reads every inserted identity.<br/>
    /// This is the first correctness guard for route-limited multi-byte router prefixes before performance comparison work.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the multi-byte transform, reopen, and range read validate.</returns>
    private static int RunVarKeyScalar8MultiByteRouterTransformSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs8-mb-router-transform-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 2200);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 8);
        if (itemCount <= 0 || keyLength <= sharedPrefixLength + 1 || keyLength > 1024 || sharedPrefixLength < 1 || sharedPrefixLength > 250)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 mb-router transform sanity requires positive items, key length within 2-1024, and a shared prefix that leaves at least two varying bytes.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long childRouterOffset = 0;
        long growCount = 0;
        long transformCount = 0;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(813), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8mb", 0));
            rootOffset = root.Offset;
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, 0x35, VarKeyScalar8Profile.DefaultInitial);

            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8LongSharedPrefixKey(i, keyLength, sharedPrefixLength);
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength: 1024, key, CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected VS8 mb-router insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                    childRouterOffset = result.PrimaryOffset;
                }
            }

            if (transformCount != 1 || childRouterOffset == 0)
            {
                throw new InvalidDataException($"Expected exactly one VS8 mb-router transform, got {transformCount}.");
            }

            byte[] childRouterBytes = new byte[RouterLayout.Size];
            session.ReadRouterPageForRangeScan(childRouterOffset, childRouterBytes);
            RouterReader childReader = new(childRouterBytes);
            if (!childReader.IsValid || childReader.HasDirectIndex || childReader.PrefixByteCount <= 1 || childReader.RouteCount != 2)
            {
                throw new InvalidDataException($"Expected transformed VS8 child to be a two-route multi-byte router, got valid={childReader.IsValid} direct={childReader.HasDirectIndex} prefixBytes={childReader.PrefixByteCount} routes={childReader.RouteCount}.");
            }
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            byte[] lower = CreateVarKeyScalar8LongSharedPrefixKey(0, keyLength, sharedPrefixLength);
            lower.AsSpan(sharedPrefixLength).Clear();
            byte[] upper = CreateVarKeyScalar8LongSharedPrefixKey(0, keyLength, sharedPrefixLength);
            upper.AsSpan(sharedPrefixLength).Fill(0xFF);
            ulong[] identities = new ulong[itemCount];
            int copied = reopened.ReadVarKeyScalar8IdentityRange(rootOffset, maxKeyLength: 1024, lower, upper, identities);
            if (copied != itemCount)
            {
                throw new InvalidDataException($"Reopened VS8 mb-router range returned {copied} identities; expected {itemCount}.");
            }

            long checksum = 0;
            for (int i = 0; i < copied; i++)
            {
                checksum += unchecked((long)identities[i]);
            }

            Console.WriteLine("vs8 mb-router transform sanity");
            Console.WriteLine($"path {path}");
            Console.WriteLine($"rootOffset {rootOffset}");
            Console.WriteLine($"childRouterOffset {childRouterOffset}");
            Console.WriteLine($"growths {growCount}");
            Console.WriteLine($"transforms {transformCount}");
            Console.WriteLine($"items {itemCount}");
            Console.WriteLine($"keyLength {keyLength}");
            Console.WriteLine($"sharedPrefixLength {sharedPrefixLength}");
            Console.WriteLine($"rangeCount {copied}");
            Console.WriteLine($"checksum {checksum}");
            Console.WriteLine("vs8-mb-router-transform-sanity ok");
        }

        return 0;
    }

    /// <summary>
    /// Validates that a transformed 128 KiB `VS8` shelf exposes its full router arena across session reopen.<br/>
    /// The scenario forces a max-growth shelf transform, allocates one router into page 1 of that transformed extent, reopens the file, reads that mid-arena router page, and then proves the recovered arena map allocates page 2 before appending.<br/>
    /// This specifically validates page-count-derived arena length metadata and mid-arena base recovery from router page index/base-delta fields.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when transformed `VS8` router arena reuse survives reopen.</returns>
    private static int RunVarKeyScalar8RouterArenaReopenSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs8-router-arena-reopen-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 2200);
        int keyLength = GetIntOption(args, "--key-length", 48);
        if (itemCount <= 0 || keyLength <= 1 || keyLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 router arena reopen sanity requires positive items and key length 2-1024.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long childRouterOffset = 0;
        long pageOneRouterOffset;
        long lengthAfterTransform;
        long lengthAfterPageOne;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(811), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8arena", 0));
            rootOffset = root.Offset;
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, 0, VarKeyScalar8Profile.DefaultInitial);

            long transformCount = 0;
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount: 1);
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength: 1024, key, CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected VS8 arena insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                    childRouterOffset = result.PrimaryOffset;
                }
            }

            if (transformCount != 1 || childRouterOffset == 0)
            {
                throw new InvalidDataException($"Expected exactly one VS8 shelf transform, got {transformCount}.");
            }

            lengthAfterTransform = new FileInfo(path).Length;
            RouterArenaAllocationResult pageOne = session.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: childRouterOffset);
            if (pageOne.Kind != RouterArenaAllocationKind.LocalArena || pageOne.ArenaBaseOffset != childRouterOffset || pageOne.ArenaPageIndex != 1)
            {
                throw new InvalidDataException($"Expected VS8 transformed arena page 1 allocation, got {pageOne.Kind}/base={pageOne.ArenaBaseOffset}/page={pageOne.ArenaPageIndex}.");
            }

            pageOneRouterOffset = pageOne.Router.Offset;
            lengthAfterPageOne = new FileInfo(path).Length;
            if (lengthAfterPageOne != lengthAfterTransform)
            {
                throw new InvalidDataException("Allocating page 1 inside the transformed VS8 arena should not grow the file.");
            }
        }

        long lengthBeforeReopenAllocation = new FileInfo(path).Length;
        RouterArenaAllocationResult reopenedAllocation;
        long lengthAfterReopenAllocation;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.FindRouterTarget(pageOneRouterOffset, 0);
            reopenedAllocation = reopened.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: childRouterOffset);
            lengthAfterReopenAllocation = new FileInfo(path).Length;
        }

        if (reopenedAllocation.Kind != RouterArenaAllocationKind.LocalArena ||
            reopenedAllocation.ArenaBaseOffset != childRouterOffset ||
            reopenedAllocation.ArenaPageIndex != 2)
        {
            throw new InvalidDataException($"Expected reopened VS8 arena allocation to reuse page 2, got {reopenedAllocation.Kind}/base={reopenedAllocation.ArenaBaseOffset}/page={reopenedAllocation.ArenaPageIndex}.");
        }

        if (lengthAfterReopenAllocation != lengthBeforeReopenAllocation)
        {
            throw new InvalidDataException("Reopened VS8 arena allocation should not append while page 2 is free.");
        }

        Console.WriteLine("vs8 router arena reopen sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine($"rootOffset {rootOffset}");
        Console.WriteLine($"childRouterOffset {childRouterOffset}");
        Console.WriteLine($"pageOneRouterOffset {pageOneRouterOffset}");
        Console.WriteLine($"pageTwoRouterOffset {reopenedAllocation.Router.Offset}");
        Console.WriteLine($"lengthAfterTransform {lengthAfterTransform}");
        Console.WriteLine($"lengthAfterPageOne {lengthAfterPageOne}");
        Console.WriteLine($"lengthAfterReopenAllocation {lengthAfterReopenAllocation}");
        Console.WriteLine("vs8-router-arena-reopen-sanity ok");
        return 0;
    }

    /// <summary>
    /// Validates exhaustion behavior for the full transformed 128 KiB `VS8` router arena.<br/>
    /// The scenario consumes every free router page in the transformed extent, proves file length remains unchanged through page 31, and then proves the next allocation appends a new router page.<br/>
    /// This guards the large-arena page-count metadata path against silently falling back to 64 KiB reuse.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when transformed `VS8` router arena exhaustion occurs at the expected boundary.</returns>
    private static int RunVarKeyScalar8RouterArenaExhaustionSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "vs8-router-arena-exhaustion-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 2200);
        int keyLength = GetIntOption(args, "--key-length", 48);
        if (itemCount <= 0 || keyLength <= 1 || keyLength > 1024)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 router arena exhaustion sanity requires positive items and key length 2-1024.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        long childRouterOffset = 0;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(812), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8arex", 0));
            rootOffset = root.Offset;
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, 0, VarKeyScalar8Profile.DefaultInitial);

            long transformCount = 0;
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount: 1);
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength: 1024, key, CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected VS8 arena exhaustion insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                    childRouterOffset = result.PrimaryOffset;
                }
            }

            if (transformCount != 1 || childRouterOffset == 0)
            {
                throw new InvalidDataException($"Expected exactly one VS8 shelf transform, got {transformCount}.");
            }
        }

        long lengthAfterTransform = new FileInfo(path).Length;
        ushort lastArenaPage = 0;
        long lastArenaOffset = 0;
        long appendOffset;
        long lengthAfterArenaFill;
        long lengthAfterAppend;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.FindRouterTarget(childRouterOffset, 0);

            for (int expectedPage = 1; expectedPage < 32; expectedPage++)
            {
                RouterArenaAllocationResult result = reopened.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: childRouterOffset);
                if (result.Kind != RouterArenaAllocationKind.LocalArena ||
                    result.ArenaBaseOffset != childRouterOffset ||
                    result.ArenaPageIndex != expectedPage)
                {
                    throw new InvalidDataException($"Expected VS8 transformed arena page {expectedPage}, got {result.Kind}/base={result.ArenaBaseOffset}/page={result.ArenaPageIndex}.");
                }

                long currentLength = new FileInfo(path).Length;
                if (currentLength != lengthAfterTransform)
                {
                    throw new InvalidDataException($"VS8 transformed arena allocation page {expectedPage} should not grow the file.");
                }

                lastArenaPage = result.ArenaPageIndex;
                lastArenaOffset = result.Router.Offset;
            }

            lengthAfterArenaFill = new FileInfo(path).Length;
            RouterArenaAllocationResult appendResult = reopened.CreateExpandedOneByteRouterUsingArena(keyDepth: 2, allocationClassId: 0, preferredArenaBaseOffset: childRouterOffset);
            if (appendResult.Kind != RouterArenaAllocationKind.Append || appendResult.Router.Offset <= lastArenaOffset)
            {
                throw new InvalidDataException($"Expected VS8 transformed arena exhaustion to append after page 31, got {appendResult.Kind}/offset={appendResult.Router.Offset}.");
            }

            appendOffset = appendResult.Router.Offset;
            lengthAfterAppend = new FileInfo(path).Length;
            if (lengthAfterAppend <= lengthAfterArenaFill)
            {
                throw new InvalidDataException("VS8 transformed arena exhaustion append should grow the file.");
            }
        }

        Console.WriteLine("vs8 router arena exhaustion sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine($"rootOffset {rootOffset}");
        Console.WriteLine($"childRouterOffset {childRouterOffset}");
        Console.WriteLine($"lastArenaPage {lastArenaPage}");
        Console.WriteLine($"lastArenaOffset {lastArenaOffset}");
        Console.WriteLine($"appendOffset {appendOffset}");
        Console.WriteLine($"lengthAfterTransform {lengthAfterTransform}");
        Console.WriteLine($"lengthAfterArenaFill {lengthAfterArenaFill}");
        Console.WriteLine($"lengthAfterAppend {lengthAfterAppend}");
        Console.WriteLine("vs8-router-arena-exhaustion-sanity ok");
        return 0;
    }

    /// <summary>
    /// Compares routed `VS8` and SQLite using path-like raw byte keys with a long common hierarchy prefix.<br/>
    /// The workload is intended to expose whether route-limited multi-byte routers emerge when many values share directory-style bytes before useful fanout begins.<br/>
    /// The command reports write/read throughput, bytes per item, router shape counts, and route depth so mb-router behavior is visible instead of inferred from timings alone.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunVarKeyScalar8HierarchicalKeyComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS8HierarchicalKeyComparison"));
        int itemCount = GetIntOption(args, "--items", 4096);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 48);
        int branchCount = GetIntOption(args, "--branch-count", 16);
        int iterations = GetIntOption(args, "--iterations", 200);
        int candidateDepth = GetIntOption(args, "--candidate-depth", DefaultVarKeyScalar8ColdCandidateDepth);
        int candidateShelfItems = GetIntOption(args, "--candidate-shelf-items", DefaultVarKeyScalar8ColdCandidateShelfItems);
        int candidateHitCount = GetIntOption(args, "--candidate-hit-count", DefaultVarKeyScalar8ColdCandidateHitCount);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (itemCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 0 || branchCount > 256 || iterations <= 0 || candidateDepth < 0 || candidateShelfItems < 0 || candidateHitCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 hierarchical comparison requires positive items/iterations, max key length 1-1024, branch count 1-256, and positive candidate settings.");
        }

        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "vs8-hierarchical.lbdx");
        string libraEarlyOptimizedPath = Path.Combine(directory, "vs8-hierarchical-early-optimized.lbdx");
        string libraColdOptimizedPath = Path.Combine(directory, "vs8-hierarchical-cold-optimized.lbdx");
        string libraBulkPath = Path.Combine(directory, "vs8-hierarchical-bulk.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-vs8-hierarchical.db");
        File.Delete(libraPath);
        File.Delete(libraEarlyOptimizedPath);
        File.Delete(libraColdOptimizedPath);
        File.Delete(libraBulkPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        byte[][] keys = new byte[itemCount][];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = CreateVarKeyScalar8HierarchicalKey(i, sharedPrefixLength, branchCount, maxKeyLength);
        }

        byte[] lower = CreateVarKeyScalar8HierarchicalRangeLower(sharedPrefixLength);
        byte[] upper = CreateVarKeyScalar8HierarchicalRangeUpper(sharedPrefixLength);
        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        long rootOffset;
        long growCount = 0;
        long transformCount = 0;
        VarKeyScalar8WalkedColdTelemetry walkedTelemetry = default;
        VarKeyScalar8ColdCandidateTelemetry candidateTelemetry = new(candidateDepth, candidateShelfItems, candidateHitCount);
        VarLenRouteOptimizerState optimizerQueue;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(814), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8hier", 0));
            rootOffset = root.Offset;
            optimizerQueue = session.GetOrCreateVarLenRouteOptimizerState(rootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, keys[0][0], VarKeyScalar8Profile.DefaultInitial);

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int i = 0; i < itemCount; i++)
            {
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength, keys[i], CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 16);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected hierarchical VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                walkedTelemetry.Add(result);
                candidateTelemetry.Add(i + 1, keys[i], result);
                optimizerQueue.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, rootOffset, result.PrimaryOffset);
                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        long earlyOptimizedRootOffset;
        long earlyOptimizedGrowCount = 0;
        long earlyOptimizedTransformCount = 0;
        long earlyOptimizeReclaimableBytes = 0;
        TimeSpan earlyOptimizeElapsed = TimeSpan.Zero;
        TimeSpan earlyPreTriggerInsertElapsed = TimeSpan.Zero;
        TimeSpan earlyPostTriggerInsertElapsed = TimeSpan.Zero;
        TimeSpan earlyPreTriggerCommitElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizeReachableElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizeSubtreeBuildElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizePublishElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizeCommitElapsed = TimeSpan.Zero;
        TimeSpan earlyPostTriggerCommitElapsed = TimeSpan.Zero;
        DataKernelCommitTelemetry earlyPreTriggerCommitTelemetry = default;
        DataKernelCommitTelemetry earlyOptimizeCommitTelemetry = default;
        DataKernelCommitTelemetry earlyPostTriggerCommitTelemetry = default;
        VarKeyScalar8WalkedWriteAttribution earlyPreTriggerAttribution = default;
        VarKeyScalar8WalkedWriteAttribution earlyPostTriggerAttribution = default;
        long earlyAllocatedBytes = 0;
        long earlyOptimizeAllocatedBytes = 0;
        int earlyOptimizeTriggerAt = 0;
        bool earlyOptimizeVersionPublishSucceeded = false;
        VarKeyScalar8HierarchicalBulkBuildResult earlyOptimizeBuild = default;
        VarKeyScalar8ColdCandidateTelemetry earlyCandidateTelemetry = new(candidateDepth, candidateShelfItems, candidateHitCount);
        VarLenRouteOptimizerState earlyOptimizerQueue;
        long earlyAllocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        Stopwatch earlyOptimizedWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraEarlyOptimizedPath, libraOptions, CreateDesignPerfMetadata(817), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8hearly", 0));
            earlyOptimizedRootOffset = root.Offset;
            earlyOptimizerQueue = session.GetOrCreateVarLenRouteOptimizerState(earlyOptimizedRootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(earlyOptimizedRootOffset, keys[0][0], VarKeyScalar8Profile.DefaultInitial);

            LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            Stopwatch earlySegmentWatch = Stopwatch.StartNew();
            try
            {
                for (int i = 0; i < itemCount; i++)
                {
                    VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(earlyOptimizedRootOffset, maxKeyLength, keys[i], CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 16);
                    if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected early-optimized hierarchical VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                    }

                    if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                    {
                        earlyOptimizedGrowCount++;
                    }

                    if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                    {
                        earlyOptimizedTransformCount++;
                    }

                    if (earlyOptimizeTriggerAt == 0)
                    {
                        earlyPreTriggerAttribution += result.Attribution;
                    }
                    else
                    {
                        earlyPostTriggerAttribution += result.Attribution;
                    }

                    _ = earlyCandidateTelemetry.Add(i + 1, keys[i], result);
                    bool optimizerQueued = earlyOptimizerQueue.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, earlyOptimizedRootOffset, result.PrimaryOffset);
                    if (earlyOptimizeTriggerAt == 0 && optimizerQueued)
                    {
                        earlyOptimizeTriggerAt = i + 1;
                        earlySegmentWatch.Stop();
                        earlyPreTriggerInsertElapsed = earlySegmentWatch.Elapsed;
                        Stopwatch earlyCommitWatch = Stopwatch.StartNew();
                        (earlyPreTriggerCommitTelemetry, _) = durabilityBatch.Commit();
                        earlyCommitWatch.Stop();
                        earlyPreTriggerCommitElapsed = earlyCommitWatch.Elapsed;
                        durabilityBatch.Dispose();

                        long optimizeAllocatedBefore = GC.GetAllocatedBytesForCurrentThread();
                        Stopwatch earlyOptimizeWatch = Stopwatch.StartNew();
                        Stopwatch phaseWatch = Stopwatch.StartNew();
                        long preOptimizeReachableBytes = MeasureVarKeyScalar8ReachableStorageBytes(session, earlyOptimizedRootOffset);
                        phaseWatch.Stop();
                        earlyOptimizeReachableElapsed = phaseWatch.Elapsed;
                        earlyOptimizeReclaimableBytes = Math.Max(0, preOptimizeReachableBytes - RouterLayout.Size);
                        byte rootPrefix = keys[i][0];
                        long expectedTargetOffset = session.FindRouterTarget(earlyOptimizedRootOffset, rootPrefix);
                        using (LibraDexFileSessionDurabilityBatch optimizeBatch = session.BeginDurabilityBatch())
                        {
                            phaseWatch.Restart();
                            (byte subtreeRootPrefix, long replacementTargetOffset, earlyOptimizeBuild) = CreateVarKeyScalar8HierarchicalBulkSubtree(session, keys.AsSpan(0, i + 1), maxKeyLength, branchCount);
                            phaseWatch.Stop();
                            earlyOptimizeSubtreeBuildElapsed = phaseWatch.Elapsed;
                            if (subtreeRootPrefix != rootPrefix)
                            {
                                throw new InvalidDataException("The early VS8 optimizer built a subtree for an unexpected root prefix.");
                            }

                            phaseWatch.Restart();
                            earlyOptimizeVersionPublishSucceeded = session.TryUpdateRouterRouteTargetIfCurrent(
                                earlyOptimizedRootOffset,
                                rootPrefix,
                                expectedTargetOffset,
                                replacementTargetOffset,
                                out _);
                            phaseWatch.Stop();
                            earlyOptimizePublishElapsed = phaseWatch.Elapsed;
                            if (!earlyOptimizeVersionPublishSucceeded)
                            {
                                throw new InvalidDataException("The early VS8 optimizer publish was rejected by the route version check.");
                            }

                            phaseWatch.Restart();
                            (earlyOptimizeCommitTelemetry, _) = optimizeBatch.Commit();
                            phaseWatch.Stop();
                            earlyOptimizeCommitElapsed = phaseWatch.Elapsed;
                        }

                        earlyOptimizeWatch.Stop();
                        earlyOptimizeElapsed = earlyOptimizeWatch.Elapsed;
                        earlyOptimizeAllocatedBytes = GC.GetAllocatedBytesForCurrentThread() - optimizeAllocatedBefore;
                        durabilityBatch = session.BeginDurabilityBatch();
                        earlySegmentWatch.Restart();
                    }
                }

                earlySegmentWatch.Stop();
                earlyPostTriggerInsertElapsed = earlySegmentWatch.Elapsed;
                Stopwatch finalCommitWatch = Stopwatch.StartNew();
                (earlyPostTriggerCommitTelemetry, _) = durabilityBatch.Commit();
                finalCommitWatch.Stop();
                earlyPostTriggerCommitElapsed = finalCommitWatch.Elapsed;
            }
            finally
            {
                durabilityBatch.Dispose();
            }
        }

        earlyOptimizedWriteWatch.Stop();
        earlyAllocatedBytes = GC.GetAllocatedBytesForCurrentThread() - earlyAllocatedBefore;

        long coldOptimizedRootOffset;
        long coldOptimizedGrowCount = 0;
        long coldOptimizedTransformCount = 0;
        long coldOptimizeReclaimableBytes;
        TimeSpan coldOptimizeElapsed;
        VarKeyScalar8HierarchicalBulkBuildResult coldOptimizeBuild;
        VarLenRouteOptimizerState coldOptimizerQueue;
        bool coldOptimizeVersionPublishSucceeded = false;
        bool coldOptimizeCandidateTargetStillCurrent = false;
        Stopwatch coldOptimizedWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraColdOptimizedPath, libraOptions, CreateDesignPerfMetadata(816), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8hcold", 0));
            coldOptimizedRootOffset = root.Offset;
            coldOptimizerQueue = session.GetOrCreateVarLenRouteOptimizerState(coldOptimizedRootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(coldOptimizedRootOffset, keys[0][0], VarKeyScalar8Profile.DefaultInitial);

            using (LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch())
            {
                for (int i = 0; i < itemCount; i++)
                {
                    VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(coldOptimizedRootOffset, maxKeyLength, keys[i], CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 16);
                    if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected cold-optimized hierarchical VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                    }

                    if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                    {
                        coldOptimizedGrowCount++;
                    }

                    if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                    {
                        coldOptimizedTransformCount++;
                    }

                    coldOptimizerQueue.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, coldOptimizedRootOffset, result.PrimaryOffset);
                }

                _ = durabilityBatch.Commit();
            }

            Stopwatch coldOptimizeWatch = Stopwatch.StartNew();
            long preOptimizeReachableBytes = MeasureVarKeyScalar8ReachableStorageBytes(session, coldOptimizedRootOffset);
            coldOptimizeReclaimableBytes = Math.Max(0, preOptimizeReachableBytes - RouterLayout.Size);
            VarLenRouteOptimizerCandidate candidate = coldOptimizerQueue.FirstCandidate;
            byte rootPrefix = keys[Math.Max(0, candidate.LastObservedAt - 1)][0];
            long expectedTargetOffset = session.FindRouterTarget(coldOptimizedRootOffset, rootPrefix);
            coldOptimizeCandidateTargetStillCurrent = expectedTargetOffset == candidate.CurrentTargetOffset;
            using (LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch())
            {
                (byte subtreeRootPrefix, long replacementTargetOffset, coldOptimizeBuild) = CreateVarKeyScalar8HierarchicalBulkSubtree(session, keys, maxKeyLength, branchCount);
                if (subtreeRootPrefix != rootPrefix)
                {
                    throw new InvalidDataException("The queued VS8 optimizer built a subtree for an unexpected root prefix.");
                }

                coldOptimizeVersionPublishSucceeded = session.TryUpdateRouterRouteTargetIfCurrent(
                    coldOptimizedRootOffset,
                    rootPrefix,
                    expectedTargetOffset,
                    replacementTargetOffset,
                    out _);
                if (!coldOptimizeVersionPublishSucceeded)
                {
                    throw new InvalidDataException("The queued VS8 optimizer publish was rejected by the route version check.");
                }

                _ = durabilityBatch.Commit();
            }

            coldOptimizeWatch.Stop();
            coldOptimizeElapsed = coldOptimizeWatch.Elapsed;
        }

        coldOptimizedWriteWatch.Stop();

        long bulkRootOffset;
        Stopwatch libraBulkWriteWatch = Stopwatch.StartNew();
        VarKeyScalar8HierarchicalBulkBuildResult bulkBuild;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraBulkPath, libraOptions, CreateDesignPerfMetadata(815), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8hblk", 0));
            bulkRootOffset = root.Offset;
            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            bulkBuild = CreateVarKeyScalar8HierarchicalBulkTree(session, bulkRootOffset, keys, maxKeyLength, branchCount);
            _ = durabilityBatch.Commit();
        }

        libraBulkWriteWatch.Stop();

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteVarKeyScalar8Schema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Integer);
            for (int i = 0; i < itemCount; i++)
            {
                keyParameter.Value = keys[i];
                identityParameter.Value = EncodeSqliteSortableUnsignedScalar8(CreateVarKeyScalar8Identity(i));
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        VarKeyScalar8ReadMeasurement libraRead;
        VarKeyScalar8ReadMeasurement earlyOptimizedRead;
        VarKeyScalar8ReadMeasurement coldOptimizedRead;
        VarKeyScalar8ReadMeasurement libraBulkRead;
        VarKeyScalar8RouterShapeStats routerStats;
        VarKeyScalar8RouterShapeStats earlyOptimizedRouterStats;
        VarKeyScalar8RouterShapeStats coldOptimizedRouterStats;
        VarKeyScalar8RouterShapeStats bulkRouterStats;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            routerStats = MeasureVarKeyScalar8RouterShapeStats(reopened, rootOffset);
            libraRead = MeasureVarKeyScalar8ExplicitRangeReads(reopened, rootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraEarlyOptimizedPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            earlyOptimizedRouterStats = MeasureVarKeyScalar8RouterShapeStats(reopened, earlyOptimizedRootOffset);
            earlyOptimizedRead = MeasureVarKeyScalar8ExplicitRangeReads(reopened, earlyOptimizedRootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraColdOptimizedPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            coldOptimizedRouterStats = MeasureVarKeyScalar8RouterShapeStats(reopened, coldOptimizedRootOffset);
            coldOptimizedRead = MeasureVarKeyScalar8ExplicitRangeReads(reopened, coldOptimizedRootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraBulkPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            bulkRouterStats = MeasureVarKeyScalar8RouterShapeStats(reopened, bulkRootOffset);
            libraBulkRead = MeasureVarKeyScalar8ExplicitRangeReads(reopened, bulkRootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteVarKeyScalar8ExplicitRangeReads(connection, lower, upper, itemCount, iterations);
        }

        long libraBytes = new FileInfo(libraPath).Length;
        long earlyOptimizedBytes = new FileInfo(libraEarlyOptimizedPath).Length;
        long earlyOptimizedSimulatedReclaimBytes = Math.Max(RouterLayout.Size, earlyOptimizedBytes - earlyOptimizeReclaimableBytes);
        long coldOptimizedBytes = new FileInfo(libraColdOptimizedPath).Length;
        long coldOptimizedSimulatedReclaimBytes = Math.Max(RouterLayout.Size, coldOptimizedBytes - coldOptimizeReclaimableBytes);
        long libraBulkBytes = new FileInfo(libraBulkPath).Length;
        long sqliteBytes = GetSqliteScalar8Scalar8StorageBytes(sqlitePath);
        double libraWriteItemsPerSecond = itemCount / Math.Max(libraWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double earlyOptimizedWriteItemsPerSecond = itemCount / Math.Max(earlyOptimizedWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double coldOptimizedWriteItemsPerSecond = itemCount / Math.Max(coldOptimizedWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double libraBulkWriteItemsPerSecond = itemCount / Math.Max(libraBulkWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double sqliteWriteItemsPerSecond = itemCount / Math.Max(sqliteWriteWatch.Elapsed.TotalSeconds, 0.000001);
        Console.WriteLine("vs8 hierarchical key comparison");
