        Console.WriteLine($"maxRouteDepth {routerStats.MaxRouteDepth}");
        Console.WriteLine($"earlyOptimizedRouters {earlyOptimizedRouterStats.RouterCount}");
        Console.WriteLine($"earlyOptimizedMultiByteRouters {earlyOptimizedRouterStats.MultiByteRouterCount}");
        Console.WriteLine(FormattableString.Invariant($"earlyOptimizedAvgRouteDepth {earlyOptimizedRouterStats.AverageRouteDepth:F2}"));
        Console.WriteLine($"earlyOptimizedMaxRouteDepth {earlyOptimizedRouterStats.MaxRouteDepth}");
        Console.WriteLine($"coldOptimizedRouters {coldOptimizedRouterStats.RouterCount}");
        Console.WriteLine($"coldOptimizedMultiByteRouters {coldOptimizedRouterStats.MultiByteRouterCount}");
        Console.WriteLine(FormattableString.Invariant($"coldOptimizedAvgRouteDepth {coldOptimizedRouterStats.AverageRouteDepth:F2}"));
        Console.WriteLine($"coldOptimizedMaxRouteDepth {coldOptimizedRouterStats.MaxRouteDepth}");
        Console.WriteLine($"bulkFanoutDepth {bulkBuild.FanoutDepth}");
        Console.WriteLine($"bulkRoutes {bulkBuild.RouteCount}");
        Console.WriteLine($"bulkPlannedRouters {bulkBuild.RouterCount}");
        Console.WriteLine($"bulkShelves {bulkBuild.ShelfCount}");
        Console.WriteLine($"bulkMaxPlannerDepth {bulkBuild.MaxPlannerDepth}");
        Console.WriteLine($"bulkRouters {bulkRouterStats.RouterCount}");
        Console.WriteLine($"bulkMultiByteRouters {bulkRouterStats.MultiByteRouterCount}");
        Console.WriteLine(FormattableString.Invariant($"bulkAvgRouteDepth {bulkRouterStats.AverageRouteDepth:F2}"));
        Console.WriteLine("| row | items/sec | ids/sec | ns/id | readCalls | backingReads | readBytes | cacheArenas | cacheBytes | bytes | bytes/item | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| VS8 hierarchical write/read | {libraWriteItemsPerSecond:F2} | {libraRead.IdentitiesPerSecond:F2} | {libraRead.NsPerIdentity:F2} | {libraRead.ReadTelemetry.ReadCallCount} | {libraRead.ReadTelemetry.BackingReadCallCount} | {libraRead.ReadTelemetry.BytesRead} | {libraRead.RouterArenaCacheCount} | {libraRead.RouterArenaCacheBytes} | {libraBytes} | {(double)libraBytes / itemCount:F2} | {libraRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| VS8 early optimized write/read | {earlyOptimizedWriteItemsPerSecond:F2} | {earlyOptimizedRead.IdentitiesPerSecond:F2} | {earlyOptimizedRead.NsPerIdentity:F2} | {earlyOptimizedRead.ReadTelemetry.ReadCallCount} | {earlyOptimizedRead.ReadTelemetry.BackingReadCallCount} | {earlyOptimizedRead.ReadTelemetry.BytesRead} | {earlyOptimizedRead.RouterArenaCacheCount} | {earlyOptimizedRead.RouterArenaCacheBytes} | {earlyOptimizedBytes} | {(double)earlyOptimizedBytes / itemCount:F2} | {earlyOptimizedRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| VS8 early optimized simulated reclaim | {earlyOptimizedWriteItemsPerSecond:F2} | {earlyOptimizedRead.IdentitiesPerSecond:F2} | {earlyOptimizedRead.NsPerIdentity:F2} | {earlyOptimizedRead.ReadTelemetry.ReadCallCount} | {earlyOptimizedRead.ReadTelemetry.BackingReadCallCount} | {earlyOptimizedRead.ReadTelemetry.BytesRead} | {earlyOptimizedRead.RouterArenaCacheCount} | {earlyOptimizedRead.RouterArenaCacheBytes} | {earlyOptimizedSimulatedReclaimBytes} | {(double)earlyOptimizedSimulatedReclaimBytes / itemCount:F2} | {earlyOptimizedRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| VS8 cold optimized write/read | {coldOptimizedWriteItemsPerSecond:F2} | {coldOptimizedRead.IdentitiesPerSecond:F2} | {coldOptimizedRead.NsPerIdentity:F2} | {coldOptimizedRead.ReadTelemetry.ReadCallCount} | {coldOptimizedRead.ReadTelemetry.BackingReadCallCount} | {coldOptimizedRead.ReadTelemetry.BytesRead} | {coldOptimizedRead.RouterArenaCacheCount} | {coldOptimizedRead.RouterArenaCacheBytes} | {coldOptimizedBytes} | {(double)coldOptimizedBytes / itemCount:F2} | {coldOptimizedRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| VS8 cold optimized simulated reclaim | {coldOptimizedWriteItemsPerSecond:F2} | {coldOptimizedRead.IdentitiesPerSecond:F2} | {coldOptimizedRead.NsPerIdentity:F2} | {coldOptimizedRead.ReadTelemetry.ReadCallCount} | {coldOptimizedRead.ReadTelemetry.BackingReadCallCount} | {coldOptimizedRead.ReadTelemetry.BytesRead} | {coldOptimizedRead.RouterArenaCacheCount} | {coldOptimizedRead.RouterArenaCacheBytes} | {coldOptimizedSimulatedReclaimBytes} | {(double)coldOptimizedSimulatedReclaimBytes / itemCount:F2} | {coldOptimizedRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| VS8 hierarchical bulk build/read | {libraBulkWriteItemsPerSecond:F2} | {libraBulkRead.IdentitiesPerSecond:F2} | {libraBulkRead.NsPerIdentity:F2} | {libraBulkRead.ReadTelemetry.ReadCallCount} | {libraBulkRead.ReadTelemetry.BackingReadCallCount} | {libraBulkRead.ReadTelemetry.BytesRead} | {libraBulkRead.RouterArenaCacheCount} | {libraBulkRead.RouterArenaCacheBytes} | {libraBulkBytes} | {(double)libraBulkBytes / itemCount:F2} | {libraBulkRead.Checksum} |"));
        Console.WriteLine(FormattableString.Invariant($"| SQLite hierarchical write/read | {sqliteWriteItemsPerSecond:F2} | {sqliteRead.IdentitiesPerSecond:F2} | {sqliteRead.NsPerIdentity:F2} | 0 | 0 | 0 | 0 | 0 | {sqliteBytes} | {(double)sqliteBytes / itemCount:F2} | {sqliteRead.Checksum} |"));
        Console.WriteLine($"VS8/SQLite read {FormatMultiplier(libraRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS8/SQLite write {FormatMultiplier(libraWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        Console.WriteLine($"VS8 early optimized/SQLite read {FormatMultiplier(earlyOptimizedRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS8 early optimized/SQLite write {FormatMultiplier(earlyOptimizedWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        Console.WriteLine($"VS8 cold optimized/SQLite read {FormatMultiplier(coldOptimizedRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS8 cold optimized/SQLite write {FormatMultiplier(coldOptimizedWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        Console.WriteLine($"VS8 bulk/SQLite read {FormatMultiplier(libraBulkRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS8 bulk/SQLite write {FormatMultiplier(libraBulkWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        return 0;
    }

    /// <summary>
    /// Compares routed `VS16` and SQLite using path-like raw byte keys with a long common hierarchy prefix.<br/>
    /// This is the `VS16` walked-route counterpart to the `VS8` hierarchical comparison; it intentionally omits the `VS8` bulk planner row until a `VS16` bulk tree exists.<br/>
    /// The command keeps the generated keys and range shape identical to `VS8`, widening only the identity column to validate clone behavior on clustered hierarchical keys.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunVarKeyScalar16HierarchicalKeyComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS16HierarchicalKeyComparison"));
        int itemCount = GetIntOption(args, "--items", 4096);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 48);
        int branchCount = GetIntOption(args, "--branch-count", 16);
        int iterations = GetIntOption(args, "--iterations", 200);
        int candidateDepth = GetIntOption(args, "--candidate-depth", DefaultVarKeyScalar8ColdCandidateDepth);
        int candidateShelfItems = GetIntOption(args, "--candidate-shelf-items", DefaultVarKeyScalar8ColdCandidateShelfItems);
        int candidateHitCount = GetIntOption(args, "--candidate-hit-count", DefaultVarKeyScalar8ColdCandidateHitCount);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (itemCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 0 || branchCount > 256 || iterations <= 0 || candidateDepth < 0 || candidateShelfItems < 0 || candidateHitCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS16 hierarchical comparison requires positive items/iterations, max key length 1-1024, branch count 1-256, and positive candidate settings.");
        }

        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "vs16-hierarchical.lbdx");
        string libraEarlyOptimizedPath = Path.Combine(directory, "vs16-hierarchical-early-optimized.lbdx");
        string libraColdOptimizedPath = Path.Combine(directory, "vs16-hierarchical-cold-optimized.lbdx");
        string libraBulkPath = Path.Combine(directory, "vs16-hierarchical-bulk.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-vs16-hierarchical.db");
        File.Delete(libraPath);
        File.Delete(libraEarlyOptimizedPath);
        File.Delete(libraColdOptimizedPath);
        File.Delete(libraBulkPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        byte[][] keys = new byte[itemCount][];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = CreateVarKeyScalar8HierarchicalKey(i, sharedPrefixLength, branchCount, maxKeyLength);
        }

        byte[] lower = CreateVarKeyScalar8HierarchicalRangeLower(sharedPrefixLength);
        byte[] upper = CreateVarKeyScalar8HierarchicalRangeUpper(sharedPrefixLength);
        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        long rootOffset;
        long growCount = 0;
        long transformCount = 0;
        VarKeyScalar16WalkedColdTelemetry walkedTelemetry = default;
        VarKeyScalar16ColdCandidateTelemetry candidateTelemetry = new(candidateDepth, candidateShelfItems, candidateHitCount);
        VarLenRouteOptimizerState optimizerQueue;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(814), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16hier", 0));
            rootOffset = root.Offset;
            optimizerQueue = session.GetOrCreateVarLenRouteOptimizerState(rootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar16ShelfAndLinkRootRoute(rootOffset, keys[0][0], VarKeyScalar16Profile.DefaultInitial);

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int i = 0; i < itemCount; i++)
            {
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(rootOffset, maxKeyLength, keys[i], identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 16);
                if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected hierarchical VS16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                walkedTelemetry.Add(result);
                candidateTelemetry.Add(i + 1, keys[i], result);
                optimizerQueue.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, rootOffset, result.PrimaryOffset);
                if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        long earlyOptimizedRootOffset;
        long earlyOptimizedGrowCount = 0;
        long earlyOptimizedTransformCount = 0;
        long earlyOptimizeReclaimableBytes = 0;
        TimeSpan earlyOptimizeElapsed = TimeSpan.Zero;
        TimeSpan earlyPreTriggerInsertElapsed = TimeSpan.Zero;
        TimeSpan earlyPostTriggerInsertElapsed = TimeSpan.Zero;
        TimeSpan earlyPreTriggerCommitElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizeReachableElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizeSubtreeBuildElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizePublishElapsed = TimeSpan.Zero;
        TimeSpan earlyOptimizeCommitElapsed = TimeSpan.Zero;
        TimeSpan earlyPostTriggerCommitElapsed = TimeSpan.Zero;
        DataKernelCommitTelemetry earlyPreTriggerCommitTelemetry = default;
        DataKernelCommitTelemetry earlyOptimizeCommitTelemetry = default;
        DataKernelCommitTelemetry earlyPostTriggerCommitTelemetry = default;
        VarKeyScalar16WalkedWriteAttribution earlyPreTriggerAttribution = default;
        VarKeyScalar16WalkedWriteAttribution earlyPostTriggerAttribution = default;
        long earlyAllocatedBytes = 0;
        long earlyOptimizeAllocatedBytes = 0;
        int earlyOptimizeTriggerAt = 0;
        bool earlyOptimizeVersionPublishSucceeded = false;
        VarKeyScalar16HierarchicalBulkBuildResult earlyOptimizeBuild = default;
        VarKeyScalar16ColdCandidateTelemetry earlyCandidateTelemetry = new(candidateDepth, candidateShelfItems, candidateHitCount);
        VarLenRouteOptimizerState earlyOptimizerQueue;
        long earlyAllocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        Stopwatch earlyOptimizedWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraEarlyOptimizedPath, libraOptions, CreateDesignPerfMetadata(817), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16hearly", 0));
            earlyOptimizedRootOffset = root.Offset;
            earlyOptimizerQueue = session.GetOrCreateVarLenRouteOptimizerState(earlyOptimizedRootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar16ShelfAndLinkRootRoute(earlyOptimizedRootOffset, keys[0][0], VarKeyScalar16Profile.DefaultInitial);

            LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            Stopwatch earlySegmentWatch = Stopwatch.StartNew();
            try
            {
                for (int i = 0; i < itemCount; i++)
                {
                    CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                    VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(earlyOptimizedRootOffset, maxKeyLength, keys[i], identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 16);
                    if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected early-optimized hierarchical VS16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                    }

                    if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedGrow)
                    {
                        earlyOptimizedGrowCount++;
                    }

                    if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedShelfTransformSplit)
                    {
                        earlyOptimizedTransformCount++;
                    }

                    if (earlyOptimizeTriggerAt == 0)
                    {
                        earlyPreTriggerAttribution += result.Attribution;
                    }
                    else
                    {
                        earlyPostTriggerAttribution += result.Attribution;
                    }

                    _ = earlyCandidateTelemetry.Add(i + 1, keys[i], result);
                    bool optimizerQueued = earlyOptimizerQueue.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, earlyOptimizedRootOffset, result.PrimaryOffset);
                    if (earlyOptimizeTriggerAt == 0 && optimizerQueued)
                    {
                        earlyOptimizeTriggerAt = i + 1;
                        earlySegmentWatch.Stop();
                        earlyPreTriggerInsertElapsed = earlySegmentWatch.Elapsed;
                        Stopwatch earlyCommitWatch = Stopwatch.StartNew();
                        (earlyPreTriggerCommitTelemetry, _) = durabilityBatch.Commit();
                        earlyCommitWatch.Stop();
                        earlyPreTriggerCommitElapsed = earlyCommitWatch.Elapsed;
                        durabilityBatch.Dispose();

                        long optimizeAllocatedBefore = GC.GetAllocatedBytesForCurrentThread();
                        Stopwatch earlyOptimizeWatch = Stopwatch.StartNew();
                        Stopwatch phaseWatch = Stopwatch.StartNew();
                        long preOptimizeReachableBytes = MeasureVarKeyScalar16ReachableStorageBytes(session, earlyOptimizedRootOffset);
                        phaseWatch.Stop();
                        earlyOptimizeReachableElapsed = phaseWatch.Elapsed;
                        earlyOptimizeReclaimableBytes = Math.Max(0, preOptimizeReachableBytes - RouterLayout.Size);
                        byte rootPrefix = keys[i][0];
                        long expectedTargetOffset = session.FindRouterTarget(earlyOptimizedRootOffset, rootPrefix);
                        using (LibraDexFileSessionDurabilityBatch optimizeBatch = session.BeginDurabilityBatch())
                        {
                            phaseWatch.Restart();
                            (byte subtreeRootPrefix, long replacementTargetOffset, earlyOptimizeBuild) = CreateVarKeyScalar16HierarchicalBulkSubtree(session, keys.AsSpan(0, i + 1), maxKeyLength, branchCount);
                            phaseWatch.Stop();
                            earlyOptimizeSubtreeBuildElapsed = phaseWatch.Elapsed;
                            if (subtreeRootPrefix != rootPrefix)
                            {
                                throw new InvalidDataException("The early VS16 optimizer built a subtree for an unexpected root prefix.");
                            }

                            phaseWatch.Restart();
                            earlyOptimizeVersionPublishSucceeded = session.TryUpdateRouterRouteTargetIfCurrent(
                                earlyOptimizedRootOffset,
                                rootPrefix,
                                expectedTargetOffset,
                                replacementTargetOffset,
                                out _);
                            phaseWatch.Stop();
                            earlyOptimizePublishElapsed = phaseWatch.Elapsed;
                            if (!earlyOptimizeVersionPublishSucceeded)
                            {
                                throw new InvalidDataException("The early VS16 optimizer publish was rejected by the route version check.");
                            }

                            phaseWatch.Restart();
                            (earlyOptimizeCommitTelemetry, _) = optimizeBatch.Commit();
                            phaseWatch.Stop();
                            earlyOptimizeCommitElapsed = phaseWatch.Elapsed;
                        }

                        earlyOptimizeWatch.Stop();
                        earlyOptimizeElapsed = earlyOptimizeWatch.Elapsed;
                        earlyOptimizeAllocatedBytes = GC.GetAllocatedBytesForCurrentThread() - optimizeAllocatedBefore;
                        durabilityBatch = session.BeginDurabilityBatch();
                        earlySegmentWatch.Restart();
                    }
                }

                earlySegmentWatch.Stop();
                earlyPostTriggerInsertElapsed = earlySegmentWatch.Elapsed;
                Stopwatch finalCommitWatch = Stopwatch.StartNew();
                (earlyPostTriggerCommitTelemetry, _) = durabilityBatch.Commit();
                finalCommitWatch.Stop();
                earlyPostTriggerCommitElapsed = finalCommitWatch.Elapsed;
            }
            finally
            {
                durabilityBatch.Dispose();
            }
        }

        earlyOptimizedWriteWatch.Stop();
        earlyAllocatedBytes = GC.GetAllocatedBytesForCurrentThread() - earlyAllocatedBefore;

        long coldOptimizedRootOffset;
        long coldOptimizedGrowCount = 0;
        long coldOptimizedTransformCount = 0;
        long coldOptimizeReclaimableBytes;
        TimeSpan coldOptimizeElapsed;
        VarKeyScalar16HierarchicalBulkBuildResult coldOptimizeBuild;
        VarLenRouteOptimizerState coldOptimizerQueue;
        bool coldOptimizeVersionPublishSucceeded = false;
        bool coldOptimizeCandidateTargetStillCurrent = false;
        Stopwatch coldOptimizedWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraColdOptimizedPath, libraOptions, CreateDesignPerfMetadata(816), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16hcold", 0));
            coldOptimizedRootOffset = root.Offset;
            coldOptimizerQueue = session.GetOrCreateVarLenRouteOptimizerState(coldOptimizedRootOffset, candidateDepth, candidateShelfItems, candidateHitCount);
            _ = session.CreateVarKeyScalar16ShelfAndLinkRootRoute(coldOptimizedRootOffset, keys[0][0], VarKeyScalar16Profile.DefaultInitial);

            using (LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch())
            {
                for (int i = 0; i < itemCount; i++)
                {
                    CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                    VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(coldOptimizedRootOffset, maxKeyLength, keys[i], identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 16);
                    if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected cold-optimized hierarchical VS16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                    }

                    if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedGrow)
                    {
                        coldOptimizedGrowCount++;
                    }

                    if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedShelfTransformSplit)
                    {
                        coldOptimizedTransformCount++;
                    }

                    coldOptimizerQueue.Observe(i + 1, keys[i], result.TargetRouterDepth, result.TargetShelfItemCount, coldOptimizedRootOffset, result.PrimaryOffset);
                }

                _ = durabilityBatch.Commit();
            }

            Stopwatch coldOptimizeWatch = Stopwatch.StartNew();
            long preOptimizeReachableBytes = MeasureVarKeyScalar16ReachableStorageBytes(session, coldOptimizedRootOffset);
            coldOptimizeReclaimableBytes = Math.Max(0, preOptimizeReachableBytes - RouterLayout.Size);
            VarLenRouteOptimizerCandidate candidate = coldOptimizerQueue.FirstCandidate;
            byte rootPrefix = keys[Math.Max(0, candidate.LastObservedAt - 1)][0];
            long expectedTargetOffset = session.FindRouterTarget(coldOptimizedRootOffset, rootPrefix);
            coldOptimizeCandidateTargetStillCurrent = expectedTargetOffset == candidate.CurrentTargetOffset;
            using (LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch())
            {
                (byte subtreeRootPrefix, long replacementTargetOffset, coldOptimizeBuild) = CreateVarKeyScalar16HierarchicalBulkSubtree(session, keys, maxKeyLength, branchCount);
                if (subtreeRootPrefix != rootPrefix)
                {
                    throw new InvalidDataException("The queued VS16 optimizer built a subtree for an unexpected root prefix.");
                }

                coldOptimizeVersionPublishSucceeded = session.TryUpdateRouterRouteTargetIfCurrent(
                    coldOptimizedRootOffset,
                    rootPrefix,
                    expectedTargetOffset,
                    replacementTargetOffset,
                    out _);
                if (!coldOptimizeVersionPublishSucceeded)
                {
                    throw new InvalidDataException("The queued VS16 optimizer publish was rejected by the route version check.");
                }

                _ = durabilityBatch.Commit();
            }

            coldOptimizeWatch.Stop();
            coldOptimizeElapsed = coldOptimizeWatch.Elapsed;
        }

        coldOptimizedWriteWatch.Stop();

        long bulkRootOffset;
        Stopwatch libraBulkWriteWatch = Stopwatch.StartNew();
        VarKeyScalar16HierarchicalBulkBuildResult bulkBuild;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraBulkPath, libraOptions, CreateDesignPerfMetadata(815), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16hblk", 0));
            bulkRootOffset = root.Offset;
            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            bulkBuild = CreateVarKeyScalar16HierarchicalBulkTree(session, bulkRootOffset, keys, maxKeyLength, branchCount);
            _ = durabilityBatch.Commit();
        }

        libraBulkWriteWatch.Stop();

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteVarKeyScalar16Schema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Blob);
            for (int i = 0; i < itemCount; i++)
            {
                keyParameter.Value = keys[i];
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                identityParameter.Value = CreateSqliteScalar16Scalar16Blob(identityHigh, identityLow);
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        VarKeyScalar8ReadMeasurement libraRead;
        VarKeyScalar8ReadMeasurement earlyOptimizedRead;
        VarKeyScalar8ReadMeasurement coldOptimizedRead;
        VarKeyScalar8ReadMeasurement libraBulkRead;
        VarKeyScalar8RouterShapeStats routerStats;
        VarKeyScalar8RouterShapeStats earlyOptimizedRouterStats;
        VarKeyScalar8RouterShapeStats coldOptimizedRouterStats;
        VarKeyScalar8RouterShapeStats bulkRouterStats;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            routerStats = MeasureVarKeyScalar8RouterShapeStats(reopened, rootOffset);
            libraRead = MeasureVarKeyScalar16ExplicitRangeReads(reopened, rootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraEarlyOptimizedPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            earlyOptimizedRouterStats = MeasureVarKeyScalar8RouterShapeStats(reopened, earlyOptimizedRootOffset);
            earlyOptimizedRead = MeasureVarKeyScalar16ExplicitRangeReads(reopened, earlyOptimizedRootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraColdOptimizedPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            coldOptimizedRouterStats = MeasureVarKeyScalar8RouterShapeStats(reopened, coldOptimizedRootOffset);
            coldOptimizedRead = MeasureVarKeyScalar16ExplicitRangeReads(reopened, coldOptimizedRootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraBulkPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            bulkRouterStats = MeasureVarKeyScalar8RouterShapeStats(reopened, bulkRootOffset);
            libraBulkRead = MeasureVarKeyScalar16ExplicitRangeReads(reopened, bulkRootOffset, maxKeyLength, lower, upper, itemCount, iterations);
        }

        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteVarKeyScalar16ExplicitRangeReads(connection, lower, upper, itemCount, iterations);
        }

        long libraBytes = new FileInfo(libraPath).Length;
        long earlyOptimizedBytes = new FileInfo(libraEarlyOptimizedPath).Length;
        long earlyOptimizedSimulatedReclaimBytes = Math.Max(RouterLayout.Size, earlyOptimizedBytes - earlyOptimizeReclaimableBytes);
        long coldOptimizedBytes = new FileInfo(libraColdOptimizedPath).Length;
        long coldOptimizedSimulatedReclaimBytes = Math.Max(RouterLayout.Size, coldOptimizedBytes - coldOptimizeReclaimableBytes);
