    /// <summary>
    /// Identifies integer route-shape metrics available from repeated hierarchical varlen comparison samples.<br/>
    /// The current median summary uses only the first optimizer enqueue position, but the enum leaves the helper easy to extend.<br/>
    /// </summary>
    private enum VarLenHierarchicalIntMetric
    {
        FirstEnqueueAt,
        EarlyOptimizeTriggerAt
    }

    /// <summary>
    /// Runs repeated hierarchical varlen comparisons for `VS8` and `VS16`, then reports median SQLite-relative ratios.<br/>
    /// The single comparison commands intentionally print detailed one-run telemetry; this wrapper keeps that detailed command stable while reducing noise from one SQLite timing sample.<br/>
    /// Each sample is executed in an isolated subdirectory so files, SQLite journals, and routed optimizer artifacts cannot leak between samples.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when every sample completes and the median summary is printed.</returns>
    private static int RunVarLenHierarchicalMedianComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VarLenHierarchicalMedianComparison"));
        int samples = GetIntOption(args, "--samples", 5);
        int itemCount = GetIntOption(args, "--items", 12000);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 48);
        int branchCount = GetIntOption(args, "--branch-count", 16);
        int iterations = GetIntOption(args, "--iterations", 50);
        int candidateDepth = GetIntOption(args, "--candidate-depth", DefaultVarKeyScalar8ColdCandidateDepth);
        int candidateShelfItems = GetIntOption(args, "--candidate-shelf-items", DefaultVarKeyScalar8ColdCandidateShelfItems);
        int candidateHitCount = GetIntOption(args, "--candidate-hit-count", DefaultVarKeyScalar8ColdCandidateHitCount);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (samples <= 0 || itemCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 0 || branchCount > 256 || iterations <= 0 || candidateDepth < 0 || candidateShelfItems < 0 || candidateHitCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Varlen hierarchical median comparison requires positive samples/items/iterations, max key length 1-1024, branch count 1-256, and positive candidate settings.");
        }

        Directory.CreateDirectory(directory);
        VarLenHierarchicalMedianSample[] vs8Samples = new VarLenHierarchicalMedianSample[samples];
        VarLenHierarchicalMedianSample[] vs16Samples = new VarLenHierarchicalMedianSample[samples];
        for (int i = 0; i < samples; i++)
        {
            string sampleDirectory = Path.Combine(directory, string.Create(CultureInfo.InvariantCulture, $"sample-{i + 1:D2}"));
            vs8Samples[i] = RunCapturedVarLenHierarchicalComparison(
                "VS8",
                i + 1,
                CreateVarLenHierarchicalComparisonArgs(
                    "vs8-hierarchical-key-comparison",
                    Path.Combine(sampleDirectory, "vs8"),
                    itemCount,
                    maxKeyLength,
                    sharedPrefixLength,
                    branchCount,
                    iterations,
                    candidateDepth,
                    candidateShelfItems,
                    candidateHitCount,
                    journalMode,
                    synchronous));

            vs16Samples[i] = RunCapturedVarLenHierarchicalComparison(
                "VS16",
                i + 1,
                CreateVarLenHierarchicalComparisonArgs(
                    "vs16-hierarchical-key-comparison",
                    Path.Combine(sampleDirectory, "vs16"),
                    itemCount,
                    maxKeyLength,
                    sharedPrefixLength,
                    branchCount,
                    iterations,
                    candidateDepth,
                    candidateShelfItems,
                    candidateHitCount,
                    journalMode,
                    synchronous));
        }

        Console.WriteLine("varlen hierarchical median comparison");
        Console.WriteLine($"samples {samples}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"maxKeyLength {maxKeyLength}");
        Console.WriteLine($"sharedPrefixLength {sharedPrefixLength}");
        Console.WriteLine($"branchCount {branchCount}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"candidateDepth {candidateDepth}");
        Console.WriteLine($"candidateShelfItems {candidateShelfItems}");
        Console.WriteLine($"candidateHitCount {candidateHitCount}");
        Console.WriteLine("| shape | samples | median early read/sqlite | median early write/sqlite | median cold read/sqlite | median cold write/sqlite | early write min..max | cold write min..max | enqueue min..max | prefix | optimized routers | optimized mb routers | optimized max depth |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---|---:|---:|---:|");
        PrintVarLenHierarchicalMedianSummary("VS8", vs8Samples);
        PrintVarLenHierarchicalMedianSummary("VS16", vs16Samples);
        Console.WriteLine();
        Console.WriteLine("write attribution medians");
        Console.WriteLine("| shape | early items/sec | cold items/sec | sqlite items/sec | early/sqlite | cold/sqlite | pre route ms | pre shelf ms | pre mutate ms | pre stage ms | pre structural ms | post route ms | post shelf ms | post mutate ms | post stage ms | post structural ms | pre commit ms | optimize reachable ms | optimize subtree ms | optimize publish ms | optimize commit ms | post commit ms |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        PrintVarLenHierarchicalWriteAttributionSummary("VS8", vs8Samples);
        PrintVarLenHierarchicalWriteAttributionSummary("VS16", vs16Samples);
        Console.WriteLine();
        Console.WriteLine("hot insert segment medians");
        Console.WriteLine("| shape | trigger at | pre insert ms | pre insert items/sec | post insert ms | post insert items/sec | sqlite write items/sec |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|");
        PrintVarLenHierarchicalHotInsertSummary("VS8", vs8Samples, itemCount);
        PrintVarLenHierarchicalHotInsertSummary("VS16", vs16Samples, itemCount);
        Console.WriteLine();
        Console.WriteLine("production accounting medians");
        Console.WriteLine("| shape | hot durable ms | hot durable items/sec | sqlite write items/sec | hot/sqlite | optimizer maintenance ms | end-to-end early items/sec |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|");
        PrintVarLenHierarchicalProductionAccountingSummary("VS8", vs8Samples);
        PrintVarLenHierarchicalProductionAccountingSummary("VS16", vs16Samples);
        return 0;
    }

    /// <summary>
    /// Builds the argument array used to invoke one existing hierarchical comparison command.<br/>
    /// The median wrapper uses explicit per-sample directories and passes through the same workload controls as the underlying command so the one-run and repeated-run paths stay comparable.<br/>
    /// </summary>
    /// <param name="command">The existing harness command name to invoke.</param>
    /// <param name="directory">The isolated output directory for this sample.</param>
    /// <param name="itemCount">The number of generated hierarchical keys.</param>
    /// <param name="maxKeyLength">The maximum generated key byte length.</param>
    /// <param name="sharedPrefixLength">The common hierarchy prefix length.</param>
    /// <param name="branchCount">The number of generated branch values beneath the shared prefix.</param>
    /// <param name="iterations">The number of read iterations used by each comparison.</param>
    /// <param name="candidateDepth">The optimizer candidate route-depth threshold.</param>
    /// <param name="candidateShelfItems">The optimizer candidate landing-shelf item threshold.</param>
    /// <param name="candidateHitCount">The optimizer candidate hit threshold.</param>
    /// <param name="journalMode">The SQLite journal mode.</param>
    /// <param name="synchronous">The SQLite synchronous setting.</param>
    /// <returns>A command-line argument array accepted by the selected comparison command.</returns>
    private static string[] CreateVarLenHierarchicalComparisonArgs(
        string command,
        string directory,
        int itemCount,
        int maxKeyLength,
        int sharedPrefixLength,
        int branchCount,
        int iterations,
        int candidateDepth,
        int candidateShelfItems,
        int candidateHitCount,
        string journalMode,
        string synchronous)
    {
        return
        [
            command,
            "--directory",
            directory,
            "--items",
            itemCount.ToString(CultureInfo.InvariantCulture),
            "--max-key-length",
            maxKeyLength.ToString(CultureInfo.InvariantCulture),
            "--shared-prefix-length",
            sharedPrefixLength.ToString(CultureInfo.InvariantCulture),
            "--branch-count",
            branchCount.ToString(CultureInfo.InvariantCulture),
            "--iterations",
            iterations.ToString(CultureInfo.InvariantCulture),
            "--candidate-depth",
            candidateDepth.ToString(CultureInfo.InvariantCulture),
            "--candidate-shelf-items",
            candidateShelfItems.ToString(CultureInfo.InvariantCulture),
            "--candidate-hit-count",
            candidateHitCount.ToString(CultureInfo.InvariantCulture),
            "--journal-mode",
            journalMode,
            "--synchronous",
            synchronous
        ];
    }

    /// <summary>
    /// Captures one existing hierarchical comparison run and converts the printed telemetry into a compact median sample.<br/>
    /// This avoids duplicating the long comparison implementation while still giving repeated-sample reporting over the ratios and route-shape facts we care about here.<br/>
    /// </summary>
    /// <param name="shape">The shape label, currently `VS8` or `VS16`.</param>
    /// <param name="sampleIndex">The one-based sample index.</param>
    /// <param name="args">The command-line arguments for the underlying comparison command.</param>
    /// <returns>The parsed comparison sample.</returns>
    private static VarLenHierarchicalMedianSample RunCapturedVarLenHierarchicalComparison(string shape, int sampleIndex, string[] args)
    {
        TextWriter originalOut = Console.Out;
        using StringWriter writer = new(CultureInfo.InvariantCulture);
        Console.SetOut(writer);
        try
        {
            int result = shape == "VS8"
                ? RunVarKeyScalar8HierarchicalKeyComparison(args)
                : RunVarKeyScalar16HierarchicalKeyComparison(args);
            if (result != 0)
            {
                throw new InvalidOperationException($"The {shape} hierarchical comparison sample {sampleIndex} returned {result}.");
            }
        }
        finally
        {
            Console.SetOut(originalOut);
        }

        return ParseVarLenHierarchicalMedianSample(shape, sampleIndex, writer.ToString());
    }

    /// <summary>
    /// Parses the ratio and route-shape facts from one captured hierarchical comparison output.<br/>
    /// The parser intentionally targets stable summary lines instead of the markdown throughput table, which keeps it small and resilient to table-column additions.<br/>
    /// </summary>
    /// <param name="shape">The shape label, currently `VS8` or `VS16`.</param>
    /// <param name="sampleIndex">The one-based sample index.</param>
    /// <param name="output">The captured comparison output.</param>
    /// <returns>The parsed comparison sample.</returns>
    private static VarLenHierarchicalMedianSample ParseVarLenHierarchicalMedianSample(string shape, int sampleIndex, string output)
    {
        return new VarLenHierarchicalMedianSample(
            shape,
            sampleIndex,
            ReadIntLine(output, "items"),
            ReadMultiplierLine(output, $"{shape} early optimized/SQLite read"),
            ReadMultiplierLine(output, $"{shape} early optimized/SQLite write"),
            ReadMultiplierLine(output, $"{shape} cold optimized/SQLite read"),
            ReadMultiplierLine(output, $"{shape} cold optimized/SQLite write"),
            ReadIntLine(output, "optimizerQueueFirstEnqueueAt"),
            ReadStringLine(output, "optimizerQueueFirstCandidatePrefix"),
            ReadIntLine(output, "earlyOptimizedRouters"),
            ReadIntLine(output, "earlyOptimizedMultiByteRouters"),
            ReadIntLine(output, "earlyOptimizedMaxRouteDepth"),
            ReadIntLine(output, "coldOptimizedRouters"),
            ReadIntLine(output, "coldOptimizedMultiByteRouters"),
            ReadIntLine(output, "coldOptimizedMaxRouteDepth"),
            ReadMarkdownRowDouble(output, $"{shape} early optimized write/read", 1),
            ReadMarkdownRowDouble(output, $"{shape} cold optimized write/read", 1),
            ReadMarkdownRowDouble(output, "SQLite hierarchical write/read", 1),
            ReadDoubleLine(output, "earlyPreTriggerRouteWalkMs"),
            ReadDoubleLine(output, "earlyPreTriggerShelfReadMs"),
            ReadDoubleLine(output, "earlyPreTriggerMutationMs"),
            ReadDoubleLine(output, "earlyPreTriggerStageMs"),
            ReadDoubleLine(output, "earlyPreTriggerStructuralMs"),
            ReadDoubleLine(output, "earlyPostTriggerRouteWalkMs"),
            ReadDoubleLine(output, "earlyPostTriggerShelfReadMs"),
            ReadDoubleLine(output, "earlyPostTriggerMutationMs"),
            ReadDoubleLine(output, "earlyPostTriggerStageMs"),
            ReadDoubleLine(output, "earlyPostTriggerStructuralMs"),
            ReadDoubleLine(output, "earlyPreTriggerCommitMs"),
            ReadDoubleLine(output, "earlyOptimizeReachableMs"),
            ReadDoubleLine(output, "earlyOptimizeSubtreeBuildMs"),
            ReadDoubleLine(output, "earlyOptimizePublishMs"),
            ReadDoubleLine(output, "earlyOptimizeCommitMs"),
            ReadDoubleLine(output, "earlyPostTriggerCommitMs"),
            ReadIntLine(output, "earlyOptimizeTriggerAt"),
            ReadDoubleLine(output, "earlyPreTriggerInsertMs"),
            ReadDoubleLine(output, "earlyPostTriggerInsertMs"));
    }

    /// <summary>
    /// Prints one median summary row for a shape's repeated hierarchical comparison samples.<br/>
    /// The row keeps read and write parity separate, and includes the route-shape facts that should stay stable across samples for deterministic generated keys.<br/>
    /// </summary>
    /// <param name="shape">The shape label to print.</param>
    /// <param name="samples">The collected samples for the shape.</param>
    private static void PrintVarLenHierarchicalMedianSummary(string shape, ReadOnlySpan<VarLenHierarchicalMedianSample> samples)
    {
        double medianEarlyRead = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyReadVsSqlite);
        double medianEarlyWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyWriteVsSqlite);
        double medianColdRead = MedianVarLenMetric(samples, VarLenHierarchicalMetric.ColdReadVsSqlite);
        double medianColdWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.ColdWriteVsSqlite);
        (double minEarlyWrite, double maxEarlyWrite) = MinMaxVarLenMetric(samples, VarLenHierarchicalMetric.EarlyWriteVsSqlite);
        (double minColdWrite, double maxColdWrite) = MinMaxVarLenMetric(samples, VarLenHierarchicalMetric.ColdWriteVsSqlite);
        (int minEnqueue, int maxEnqueue) = MinMaxVarLenIntMetric(samples, VarLenHierarchicalIntMetric.FirstEnqueueAt);
        VarLenHierarchicalMedianSample representative = samples[0];
        Console.WriteLine(FormattableString.Invariant($"| {shape} | {samples.Length} | {medianEarlyRead:F2}x | {medianEarlyWrite:F2}x | {medianColdRead:F2}x | {medianColdWrite:F2}x | {minEarlyWrite:F2}x..{maxEarlyWrite:F2}x | {minColdWrite:F2}x..{maxColdWrite:F2}x | {minEnqueue}..{maxEnqueue} | {representative.CandidatePrefix} | {representative.EarlyRouters}/{representative.ColdRouters} | {representative.EarlyMultiByteRouters}/{representative.ColdMultiByteRouters} | {representative.EarlyMaxDepth}/{representative.ColdMaxDepth} |"));
    }

    /// <summary>
    /// Prints one median write-attribution row for a shape's repeated hierarchical comparison samples.<br/>
    /// The row separates SQLite-relative throughput from the early optimizer's pre-trigger, post-trigger, optimizer, and commit timing buckets so the next optimization target is evidence-led.<br/>
    /// </summary>
    /// <param name="shape">The shape label to print.</param>
    /// <param name="samples">The collected samples for the shape.</param>
    private static void PrintVarLenHierarchicalWriteAttributionSummary(string shape, ReadOnlySpan<VarLenHierarchicalMedianSample> samples)
    {
        double earlyWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyWriteItemsPerSecond);
        double coldWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.ColdWriteItemsPerSecond);
        double sqliteWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.SqliteWriteItemsPerSecond);
        double earlyWriteRatio = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyWriteVsSqlite);
        double coldWriteRatio = MedianVarLenMetric(samples, VarLenHierarchicalMetric.ColdWriteVsSqlite);
        Console.WriteLine(string.Create(CultureInfo.InvariantCulture,
            $"| {shape} | {earlyWrite:F2} | {coldWrite:F2} | {sqliteWrite:F2} | {earlyWriteRatio:F2}x | {coldWriteRatio:F2}x | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerRouteWalkMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerShelfReadMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerMutationMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerStageMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerStructuralMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerRouteWalkMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerShelfReadMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerMutationMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerStageMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerStructuralMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerCommitMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyOptimizeReachableMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyOptimizeSubtreeBuildMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyOptimizePublishMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyOptimizeCommitMs):F2} | " +
            $"{MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerCommitMs):F2} |"));
    }

    /// <summary>
    /// Prints one median row for the hot insert segments inside the early optimizer comparison.<br/>
    /// This separates insertion work before and after the first route optimization from the commit and maintenance costs that are also charged into the end-to-end write row.<br/>
    /// </summary>
    /// <param name="shape">The shape label to print.</param>
    /// <param name="samples">The collected samples for the shape.</param>
    /// <param name="itemCount">The total number of inserted items in each sample.</param>
    private static void PrintVarLenHierarchicalHotInsertSummary(string shape, ReadOnlySpan<VarLenHierarchicalMedianSample> samples, int itemCount)
    {
        int triggerAt = MedianVarLenIntMetric(samples, VarLenHierarchicalIntMetric.EarlyOptimizeTriggerAt);
        double preInsertMs = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerInsertMs);
        double postInsertMs = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerInsertMs);
        double preItemsPerSecond = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPreTriggerInsertItemsPerSecond);
        double postItemsPerSecond = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyPostTriggerInsertItemsPerSecond);
        double sqliteWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.SqliteWriteItemsPerSecond);
        Console.WriteLine(FormattableString.Invariant($"| {shape} | {triggerAt} | {preInsertMs:F2} | {preItemsPerSecond:F2} | {postInsertMs:F2} | {postItemsPerSecond:F2} | {sqliteWrite:F2} |"));
    }

    /// <summary>
    /// Prints production-style accounting for repeated hierarchical varlen write samples.<br/>
    /// Hot durable time includes inserts plus ordinary pre/post write commits, while optimizer analysis/build/publish/maintenance commit is kept in a separate column as schedulable maintenance work.<br/>
    /// </summary>
    /// <param name="shape">The shape label to print.</param>
    /// <param name="samples">The collected samples for the shape.</param>
    private static void PrintVarLenHierarchicalProductionAccountingSummary(string shape, ReadOnlySpan<VarLenHierarchicalMedianSample> samples)
    {
        double hotDurableMs = MedianVarLenMetric(samples, VarLenHierarchicalMetric.ProductionHotWriteMs);
        double hotDurableItemsPerSecond = MedianVarLenMetric(samples, VarLenHierarchicalMetric.ProductionHotWriteItemsPerSecond);
        double sqliteWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.SqliteWriteItemsPerSecond);
        double optimizerMaintenanceMs = MedianVarLenMetric(samples, VarLenHierarchicalMetric.OptimizerMaintenanceMs);
        double endToEndEarlyWrite = MedianVarLenMetric(samples, VarLenHierarchicalMetric.EarlyWriteItemsPerSecond);
        Console.WriteLine(FormattableString.Invariant($"| {shape} | {hotDurableMs:F2} | {hotDurableItemsPerSecond:F2} | {sqliteWrite:F2} | {hotDurableItemsPerSecond / sqliteWrite:F2}x | {optimizerMaintenanceMs:F2} | {endToEndEarlyWrite:F2} |"));
    }

    /// <summary>
    /// Reads a multiplier summary line from captured command output.<br/>
    /// The accepted line shape is `name 1.23x`; `n/a` is rejected because the median command needs numeric ratios to compare samples.<br/>
    /// </summary>
    /// <param name="output">The captured command output.</param>
    /// <param name="name">The summary line name before the multiplier value.</param>
    /// <returns>The numeric multiplier value.</returns>
    private static double ReadMultiplierLine(string output, string name)
    {
        string value = ReadStringLine(output, name);
        if (!value.EndsWith('x'))
        {
            throw new InvalidDataException($"Expected multiplier value for '{name}', got '{value}'.");
        }

        return double.Parse(value[..^1], CultureInfo.InvariantCulture);
    }

    /// <summary>
    /// Reads an integer summary line from captured command output.<br/>
    /// The parser is used only by repeated-sample harness reporting, not by the LibraDex hot path.<br/>
    /// </summary>
    /// <param name="output">The captured command output.</param>
    /// <param name="name">The summary line name before the integer value.</param>
    /// <returns>The parsed integer value.</returns>
    private static int ReadIntLine(string output, string name)
    {
        return int.Parse(ReadStringLine(output, name), CultureInfo.InvariantCulture);
    }

    /// <summary>
    /// Reads a floating-point summary line from captured command output.<br/>
    /// The parser expects `name value` lines produced with invariant formatting by the existing comparison commands.<br/>
    /// </summary>
    /// <param name="output">The captured command output.</param>
    /// <param name="name">The summary line name before the floating-point value.</param>
    /// <returns>The parsed floating-point value.</returns>
    private static double ReadDoubleLine(string output, string name)
    {
        return double.Parse(ReadStringLine(output, name), CultureInfo.InvariantCulture);
    }

    /// <summary>
    /// Reads a single `name value` summary line from captured command output.<br/>
    /// Matching requires the exact name plus one following space so similarly prefixed telemetry names do not collide.<br/>
    /// </summary>
    /// <param name="output">The captured command output.</param>
    /// <param name="name">The summary line name to locate.</param>
    /// <returns>The trimmed value after the summary name.</returns>
    private static string ReadStringLine(string output, string name)
    {
        using StringReader reader = new(output);
        string prefix = name + " ";
        while (reader.ReadLine() is { } line)
        {
            if (line.StartsWith(prefix, StringComparison.Ordinal))
            {
                return line[prefix.Length..].Trim();
            }
        }

        throw new InvalidDataException($"The captured varlen comparison output did not contain '{name}'.");
    }

    /// <summary>
    /// Reads a numeric column from one markdown table row in captured comparison output.<br/>
    /// The first value column after the row label is index `1`, matching the visible table layout where index `0` is the row name.<br/>
    /// </summary>
    /// <param name="output">The captured command output.</param>
    /// <param name="rowName">The exact row label to locate.</param>
    /// <param name="valueColumnIndex">The pipe-delimited column index to parse.</param>
    /// <returns>The parsed numeric column value.</returns>
    private static double ReadMarkdownRowDouble(string output, string rowName, int valueColumnIndex)
    {
        using StringReader reader = new(output);
        string prefix = "| " + rowName + " |";
        while (reader.ReadLine() is { } line)
        {
            if (!line.StartsWith(prefix, StringComparison.Ordinal))
            {
                continue;
            }

            string[] columns = line.Split('|', StringSplitOptions.TrimEntries);
            int rawColumnIndex = valueColumnIndex + 1;
            if (rawColumnIndex < 0 || rawColumnIndex >= columns.Length)
            {
                throw new InvalidDataException($"The captured varlen comparison row '{rowName}' does not contain column {valueColumnIndex}.");
            }

            return double.Parse(columns[rawColumnIndex], CultureInfo.InvariantCulture);
        }

        throw new InvalidDataException($"The captured varlen comparison output did not contain row '{rowName}'.");
    }

    /// <summary>
    /// Selects the median value for one repeated varlen comparison metric.<br/>
    /// Values are sorted by the selected ratio, and the upper-middle value is returned for even sample counts to match the harness's existing median-sample convention.<br/>
    /// </summary>
    /// <param name="samples">The collected samples.</param>
    /// <param name="metric">The metric to select.</param>
    /// <returns>The median metric value.</returns>
    private static double MedianVarLenMetric(ReadOnlySpan<VarLenHierarchicalMedianSample> samples, VarLenHierarchicalMetric metric)
    {
        double[] values = new double[samples.Length];
        for (int i = 0; i < samples.Length; i++)
        {
            values[i] = SelectVarLenMetric(samples[i], metric);
        }

        Array.Sort(values);
        return values[values.Length / 2];
    }

    /// <summary>
    /// Finds the minimum and maximum values for one repeated varlen comparison metric.<br/>
    /// This gives a small stability signal beside the median without printing every captured sample row.<br/>
    /// </summary>
    /// <param name="samples">The collected samples.</param>
    /// <param name="metric">The metric to inspect.</param>
    /// <returns>The minimum and maximum values for the selected metric.</returns>
    private static (double Min, double Max) MinMaxVarLenMetric(ReadOnlySpan<VarLenHierarchicalMedianSample> samples, VarLenHierarchicalMetric metric)
    {
        double min = double.PositiveInfinity;
        double max = double.NegativeInfinity;
        for (int i = 0; i < samples.Length; i++)
        {
            double value = SelectVarLenMetric(samples[i], metric);
            min = Math.Min(min, value);
            max = Math.Max(max, value);
        }

        return (min, max);
    }

    /// <summary>
    /// Finds the minimum and maximum values for one integer route-shape metric.<br/>
    /// The median report currently uses this for enqueue position stability across deterministic repeated samples.<br/>
    /// </summary>
    /// <param name="samples">The collected samples.</param>
    /// <param name="metric">The integer metric to inspect.</param>
    /// <returns>The minimum and maximum values for the selected metric.</returns>
    private static (int Min, int Max) MinMaxVarLenIntMetric(ReadOnlySpan<VarLenHierarchicalMedianSample> samples, VarLenHierarchicalIntMetric metric)
    {
        int min = int.MaxValue;
        int max = int.MinValue;
        for (int i = 0; i < samples.Length; i++)
        {
            int value = SelectVarLenIntMetric(samples[i], metric);
            min = Math.Min(min, value);
            max = Math.Max(max, value);
        }

        return (min, max);
    }

    /// <summary>
    /// Selects the median value for one integer varlen comparison metric.<br/>
    /// The upper-middle value is returned for even sample counts to match the floating-point median helper used by this report.<br/>
    /// </summary>
    /// <param name="samples">The collected samples.</param>
    /// <param name="metric">The integer metric to select.</param>
    /// <returns>The median integer metric value.</returns>
    private static int MedianVarLenIntMetric(ReadOnlySpan<VarLenHierarchicalMedianSample> samples, VarLenHierarchicalIntMetric metric)
    {
        int[] values = new int[samples.Length];
        for (int i = 0; i < samples.Length; i++)
        {
            values[i] = SelectVarLenIntMetric(samples[i], metric);
        }

        Array.Sort(values);
        return values[values.Length / 2];
    }

    /// <summary>
    /// Selects a ratio metric from one parsed varlen comparison sample.<br/>
    /// Keeping selection explicit avoids using delegates in this harness utility and makes the metric mapping readable at the call site.<br/>
    /// </summary>
    /// <param name="sample">The parsed comparison sample.</param>
    /// <param name="metric">The metric to select.</param>
    /// <returns>The selected ratio value.</returns>
    private static double SelectVarLenMetric(VarLenHierarchicalMedianSample sample, VarLenHierarchicalMetric metric)
    {
        return metric switch
        {
            VarLenHierarchicalMetric.EarlyReadVsSqlite => sample.EarlyReadVsSqlite,
            VarLenHierarchicalMetric.EarlyWriteVsSqlite => sample.EarlyWriteVsSqlite,
            VarLenHierarchicalMetric.ColdReadVsSqlite => sample.ColdReadVsSqlite,
            VarLenHierarchicalMetric.ColdWriteVsSqlite => sample.ColdWriteVsSqlite,
            VarLenHierarchicalMetric.EarlyWriteItemsPerSecond => sample.EarlyWriteItemsPerSecond,
            VarLenHierarchicalMetric.ColdWriteItemsPerSecond => sample.ColdWriteItemsPerSecond,
            VarLenHierarchicalMetric.SqliteWriteItemsPerSecond => sample.SqliteWriteItemsPerSecond,
            VarLenHierarchicalMetric.EarlyPreTriggerRouteWalkMs => sample.EarlyPreTriggerRouteWalkMs,
            VarLenHierarchicalMetric.EarlyPreTriggerShelfReadMs => sample.EarlyPreTriggerShelfReadMs,
            VarLenHierarchicalMetric.EarlyPreTriggerMutationMs => sample.EarlyPreTriggerMutationMs,
            VarLenHierarchicalMetric.EarlyPreTriggerStageMs => sample.EarlyPreTriggerStageMs,
            VarLenHierarchicalMetric.EarlyPreTriggerStructuralMs => sample.EarlyPreTriggerStructuralMs,
            VarLenHierarchicalMetric.EarlyPostTriggerRouteWalkMs => sample.EarlyPostTriggerRouteWalkMs,
            VarLenHierarchicalMetric.EarlyPostTriggerShelfReadMs => sample.EarlyPostTriggerShelfReadMs,
            VarLenHierarchicalMetric.EarlyPostTriggerMutationMs => sample.EarlyPostTriggerMutationMs,
            VarLenHierarchicalMetric.EarlyPostTriggerStageMs => sample.EarlyPostTriggerStageMs,
            VarLenHierarchicalMetric.EarlyPostTriggerStructuralMs => sample.EarlyPostTriggerStructuralMs,
            VarLenHierarchicalMetric.EarlyPreTriggerCommitMs => sample.EarlyPreTriggerCommitMs,
            VarLenHierarchicalMetric.EarlyOptimizeReachableMs => sample.EarlyOptimizeReachableMs,
            VarLenHierarchicalMetric.EarlyOptimizeSubtreeBuildMs => sample.EarlyOptimizeSubtreeBuildMs,
            VarLenHierarchicalMetric.EarlyOptimizePublishMs => sample.EarlyOptimizePublishMs,
            VarLenHierarchicalMetric.EarlyOptimizeCommitMs => sample.EarlyOptimizeCommitMs,
            VarLenHierarchicalMetric.EarlyPostTriggerCommitMs => sample.EarlyPostTriggerCommitMs,
            VarLenHierarchicalMetric.EarlyPreTriggerInsertItemsPerSecond => sample.EarlyOptimizeTriggerAt * 1000d / Math.Max(sample.EarlyPreTriggerInsertMs, 0.000001),
            VarLenHierarchicalMetric.EarlyPostTriggerInsertItemsPerSecond => (sample.ItemCount - sample.EarlyOptimizeTriggerAt) * 1000d / Math.Max(sample.EarlyPostTriggerInsertMs, 0.000001),
            VarLenHierarchicalMetric.EarlyPreTriggerInsertMs => sample.EarlyPreTriggerInsertMs,
            VarLenHierarchicalMetric.EarlyPostTriggerInsertMs => sample.EarlyPostTriggerInsertMs,
            VarLenHierarchicalMetric.ProductionHotWriteMs => sample.EarlyPreTriggerInsertMs + sample.EarlyPostTriggerInsertMs + sample.EarlyPreTriggerCommitMs + sample.EarlyPostTriggerCommitMs,
            VarLenHierarchicalMetric.ProductionHotWriteItemsPerSecond => sample.ItemCount * 1000d / Math.Max(sample.EarlyPreTriggerInsertMs + sample.EarlyPostTriggerInsertMs + sample.EarlyPreTriggerCommitMs + sample.EarlyPostTriggerCommitMs, 0.000001),
            VarLenHierarchicalMetric.OptimizerMaintenanceMs => sample.EarlyOptimizeReachableMs + sample.EarlyOptimizeSubtreeBuildMs + sample.EarlyOptimizePublishMs + sample.EarlyOptimizeCommitMs,
            _ => throw new ArgumentOutOfRangeException(nameof(metric))
        };
    }

    /// <summary>
    /// Selects an integer route-shape metric from one parsed varlen comparison sample.<br/>
    /// The helper mirrors the ratio selector so summary calculations do not need reflection, delegates, or ad hoc lambda captures.<br/>
    /// </summary>
    /// <param name="sample">The parsed comparison sample.</param>
    /// <param name="metric">The metric to select.</param>
    /// <returns>The selected integer value.</returns>
    private static int SelectVarLenIntMetric(VarLenHierarchicalMedianSample sample, VarLenHierarchicalIntMetric metric)
    {
        return metric switch
        {
            VarLenHierarchicalIntMetric.FirstEnqueueAt => sample.FirstEnqueueAt,
            VarLenHierarchicalIntMetric.EarlyOptimizeTriggerAt => sample.EarlyOptimizeTriggerAt,
            _ => throw new ArgumentOutOfRangeException(nameof(metric))
        };
    }

    /// <summary>
    /// Compares routed `VS16` and SQLite using path-like raw byte keys with a long common hierarchy prefix.<br/>
    /// This is the `VS16` walked-route counterpart to the `VS16` hierarchical comparison; it intentionally omits the `VS16` bulk planner row until a `VS16` bulk tree exists.<br/>
    /// The command keeps the generated keys and range shape identical to `VS16`, widening only the identity column to validate clone behavior on clustered hierarchical keys.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    /// <summary>
    /// Compares `VS8` write throughput across developer write-intent cases and matching SQLite transaction orders.<br/>
    /// The matrix separates default walked mutation, explicit clustered mutation, sorted append-like mutation, broad random mutation, and bulk tree construction so one uncommon write path does not dominate the performance interpretation.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when every write case completes and prints comparable write throughput rows.</returns>
    private static int RunVarKeyScalar8WriteIntentMatrix(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS8WriteIntentMatrix"));
        int itemCount = GetIntOption(args, "--items", 5000);
        int maxKeyLength = GetIntOption(args, "--max-key-length", 128);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 16);
        int branchCount = GetIntOption(args, "--branch-count", 8);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (itemCount <= 0 || maxKeyLength <= 0 || maxKeyLength > 1024 || sharedPrefixLength <= 0 || branchCount <= 0 || branchCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 write-intent matrix requires positive items, max key length 1-1024, and branch count 1-256.");
        }

        Directory.CreateDirectory(directory);
        byte[][] keys = new byte[itemCount][];
        for (int i = 0; i < itemCount; i++)
        {
            keys[i] = CreateVarKeyScalar8HierarchicalKey(i, sharedPrefixLength, branchCount, maxKeyLength);
        }

        int[] originalOrder = CreateSequentialOrder(itemCount);
        int[] sortedOrder = CreateSortedVarKeyScalar8Order(keys);
        int[] randomOrder = CreateDeterministicShuffledOrder(itemCount, seed: 0x5EED);
        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);

        VarKeyScalar8WriteMatrixResult defaultWalked = MeasureVarKeyScalar8WalkedWriteIntent(
            Path.Combine(directory, "vs8-default.lbdx"),
            keys,
            originalOrder,
            maxKeyLength,
            new LibraDexWriteIntent(),
            "vs8-default");
        VarKeyScalar8WriteMatrixResult clusteredWalked = MeasureVarKeyScalar8WalkedWriteIntent(
            Path.Combine(directory, "vs8-clustered.lbdx"),
            keys,
            originalOrder,
            maxKeyLength,
            new LibraDexWriteIntent(
                Order: LibraDexWriteOrder.Default,
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Clustered,
                Priority: LibraDexWritePriority.WriteSpeed),
            "vs8-clustered");
        VarKeyScalar8WriteMatrixResult sortedWalked = MeasureVarKeyScalar8WalkedWriteIntent(
            Path.Combine(directory, "vs8-sorted.lbdx"),
            keys,
            sortedOrder,
            maxKeyLength,
            new LibraDexWriteIntent(
                Order: LibraDexWriteOrder.Sorted,
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Clustered,
                Priority: LibraDexWritePriority.WriteSpeed),
            "vs8-sorted");
        VarKeyScalar8WriteMatrixResult randomWalked = MeasureVarKeyScalar8WalkedWriteIntent(
            Path.Combine(directory, "vs8-random.lbdx"),
            keys,
            randomOrder,
            maxKeyLength,
            new LibraDexWriteIntent(
                Order: LibraDexWriteOrder.Random,
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Broad,
                Priority: LibraDexWritePriority.WriteSpeed),
            "vs8-random");
        VarKeyScalar8WriteMatrixResult bulkBuild = MeasureVarKeyScalar8BulkWrite(
            Path.Combine(directory, "vs8-bulk.lbdx"),
            keys,
            maxKeyLength,
            branchCount,
            "vs8-bulk");

        VarKeyScalar8WriteMatrixResult sqliteOriginal = MeasureSqliteVarKeyScalar8Write(
            Path.Combine(directory, "sqlite-original.db"),
            keys,
            originalOrder,
            sqliteOptions,
            "sqlite-original");
        VarKeyScalar8WriteMatrixResult sqliteSorted = MeasureSqliteVarKeyScalar8Write(
            Path.Combine(directory, "sqlite-sorted.db"),
            keys,
            sortedOrder,
            sqliteOptions,
            "sqlite-sorted");
        VarKeyScalar8WriteMatrixResult sqliteRandom = MeasureSqliteVarKeyScalar8Write(
            Path.Combine(directory, "sqlite-random.db"),
            keys,
            randomOrder,
            sqliteOptions,
            "sqlite-random");

        Console.WriteLine("vs8 write intent matrix");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"maxKeyLength {maxKeyLength}");
        Console.WriteLine($"sharedPrefixLength {sharedPrefixLength}");
        Console.WriteLine($"branchCount {branchCount}");
        Console.WriteLine($"sqliteJournalMode {journalMode}");
        Console.WriteLine($"sqliteSynchronous {synchronous}");
        Console.WriteLine("| row | order | intent | items/sec | ms | allocKB | routeMs | shelfMs | mutateMs | stageMs | structuralMs | commitMs | dkWrites | dkBytes | bytes | bytes/item | growths | transforms | targetDepth | maxTargetDepth | transformDepth | maxTransformDepth | transformItems | maxTransformItems | routers | mbRouters | shelves | avgDepth | maxDepth |");
        Console.WriteLine("|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        PrintVarKeyScalar8WriteMatrixResult(defaultWalked, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(clusteredWalked, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(sortedWalked, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(randomWalked, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(bulkBuild, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(sqliteOriginal, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(sqliteSorted, itemCount);
        PrintVarKeyScalar8WriteMatrixResult(sqliteRandom, itemCount);
        Console.WriteLine($"clustered/default write {FormatMultiplier(clusteredWalked.ItemsPerSecond, defaultWalked.ItemsPerSecond)}");
        Console.WriteLine($"sorted/sqlite-sorted write {FormatMultiplier(sortedWalked.ItemsPerSecond, sqliteSorted.ItemsPerSecond)}");
        Console.WriteLine($"random/sqlite-random write {FormatMultiplier(randomWalked.ItemsPerSecond, sqliteRandom.ItemsPerSecond)}");
        Console.WriteLine($"bulk/sqlite-original write {FormatMultiplier(bulkBuild.ItemsPerSecond, sqliteOriginal.ItemsPerSecond)}");
        _ = libraOptions;
        return 0;
    }

    /// <summary>
    /// Measures one `VS8` walked write case using the requested insertion order and developer write intent.<br/>
    /// The method creates one file, runs all inserts inside one LibraDex durability batch, reopens the result for route-shape diagnostics, and returns write-only timing plus structural counters.<br/>
    /// </summary>
    /// <param name="path">The target LibraDex file path.</param>
    /// <param name="keys">The generated raw byte keys.</param>
    /// <param name="order">The insertion order expressed as indexes into <paramref name="keys"/>.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the VS8 profile family.</param>
    /// <param name="writeIntent">The developer write-intent hint to apply to the durability batch.</param>
    /// <param name="label">The row label to report.</param>
    /// <returns>The measured write-matrix row.</returns>
    private static VarKeyScalar8WriteMatrixResult MeasureVarKeyScalar8WalkedWriteIntent(
        string path,
        byte[][] keys,
        ReadOnlySpan<int> order,
        int maxKeyLength,
        LibraDexWriteIntent writeIntent,
        string label)
    {
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long growCount = 0;
        long transformCount = 0;
        long rootOffset;
        VarKeyScalar8WalkedColdTelemetry coldTelemetry = default;
        VarKeyScalar8WalkedWriteAttribution attribution = default;
        DataKernelCommitTelemetry commitTelemetry = default;
        TimeSpan commitElapsed = TimeSpan.Zero;
        long allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        Stopwatch watch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(917), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, label, 0));
            rootOffset = root.Offset;
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, keys[order[0]][0], VarKeyScalar8Profile.DefaultInitial);
            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch(writeIntent);
            for (int i = 0; i < order.Length; i++)
            {
                int sourceIndex = order[i];
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength, keys[sourceIndex], CreateVarKeyScalar8Identity(sourceIndex), allowDuplicateKeys: true, maxRouterHops: 16);
                attribution += result.Attribution;
                coldTelemetry.Add(result);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected {label} VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                {
                    growCount++;
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                }
            }

            Stopwatch commitWatch = Stopwatch.StartNew();
            (commitTelemetry, _) = durabilityBatch.Commit();
            commitWatch.Stop();
            commitElapsed = commitWatch.Elapsed;
        }

        watch.Stop();
        long allocatedBytes = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        using LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions);
        VarKeyScalar8RouterShapeStats stats = MeasureVarKeyScalar8RouterShapeStats(reopened, rootOffset);
        return VarKeyScalar8WriteMatrixResult.ForLibraDex(
            label,
            DescribeVarKeyScalar8WriteOrder(order, keys),
            DescribeWriteIntent(writeIntent),
            order.Length,
            watch.Elapsed,
            new FileInfo(path).Length,
            growCount,
            transformCount,
            stats,
            coldTelemetry,
            attribution,
            commitElapsed,
            commitTelemetry,
            allocatedBytes);
    }

    /// <summary>
    /// Measures one `VS8` bulk-tree construction row for the same generated hierarchical key set.<br/>
    /// This gives the matrix a planned-build case alongside walked mutation so bulk index creation is not inferred from incremental insert timing.<br/>
    /// </summary>
    /// <param name="path">The target LibraDex file path.</param>
    /// <param name="keys">The generated raw byte keys.</param>
    /// <param name="maxKeyLength">The maximum raw key length accepted by the VS8 profile family.</param>
    /// <param name="branchCount">The requested bulk fanout count.</param>
    /// <param name="label">The row label to report.</param>
    /// <returns>The measured write-matrix row.</returns>
    private static VarKeyScalar8WriteMatrixResult MeasureVarKeyScalar8BulkWrite(
        string path,
        byte[][] keys,
        int maxKeyLength,
        int branchCount,
        string label)
    {
        File.Delete(path);
        DataKernelOptions options = CreateDesignPerfOptions();
        long rootOffset;
        DataKernelCommitTelemetry commitTelemetry = default;
        TimeSpan commitElapsed = TimeSpan.Zero;
        long allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        Stopwatch watch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(918), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, label, 0));
            rootOffset = root.Offset;
            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch(new LibraDexWriteIntent(
                Order: LibraDexWriteOrder.Sorted,
                Volume: LibraDexWriteVolume.Thousands,
                Locality: LibraDexWriteLocality.Clustered,
                Priority: LibraDexWritePriority.WriteSpeed));
            _ = CreateVarKeyScalar8HierarchicalBulkTree(session, rootOffset, keys, maxKeyLength, branchCount);
            Stopwatch commitWatch = Stopwatch.StartNew();
            (commitTelemetry, _) = durabilityBatch.Commit();
            commitWatch.Stop();
            commitElapsed = commitWatch.Elapsed;
        }

        watch.Stop();
        long allocatedBytes = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        using LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions);
        VarKeyScalar8RouterShapeStats stats = MeasureVarKeyScalar8RouterShapeStats(reopened, rootOffset);
        return VarKeyScalar8WriteMatrixResult.ForLibraDex(
            label,
            "bulk",
            "Sorted/Clustered/WriteSpeed",
            keys.Length,
            watch.Elapsed,
            new FileInfo(path).Length,
            growths: 0,
            transforms: 0,
            stats,
            default,
            default,
            commitElapsed,
            commitTelemetry,
            allocatedBytes);
    }

    /// <summary>
    /// Measures one SQLite transaction write row using the requested key order.<br/>
    /// The SQLite case intentionally mirrors the LibraDex walked rows by inserting every item inside one transaction rather than committing per inserted identity.<br/>
    /// </summary>
    /// <param name="path">The target SQLite database path.</param>
    /// <param name="keys">The generated raw byte keys.</param>
    /// <param name="order">The insertion order expressed as indexes into <paramref name="keys"/>.</param>
    /// <param name="options">The SQLite journal and sync options.</param>
    /// <param name="label">The row label to report.</param>
    /// <returns>The measured write-matrix row.</returns>
    private static VarKeyScalar8WriteMatrixResult MeasureSqliteVarKeyScalar8Write(
        string path,
        byte[][] keys,
        ReadOnlySpan<int> order,
        SqliteScalar8Scalar8Options options,
        string label)
    {
        ResetSqliteScalar8Scalar8Files(path);
        long allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        Stopwatch watch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(path, options))
        {
            InitializeSqliteVarKeyScalar8Schema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Integer);
            for (int i = 0; i < order.Length; i++)
            {
                int sourceIndex = order[i];
                keyParameter.Value = keys[sourceIndex];
                identityParameter.Value = EncodeSqliteSortableUnsignedScalar8(CreateVarKeyScalar8Identity(sourceIndex));
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        watch.Stop();
        long allocatedBytes = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        return VarKeyScalar8WriteMatrixResult.ForSqlite(
            label,
            DescribeVarKeyScalar8WriteOrder(order, keys),
            order.Length,
            watch.Elapsed,
            GetSqliteScalar8Scalar8StorageBytes(path),
            TimeSpan.Zero,
            allocatedBytes);
    }

    /// <summary>
    /// Creates a sequential insertion order for generated key arrays.<br/>
    /// The returned indexes preserve generation order and let callers keep key and identity generation tied to the same source index.<br/>
    /// </summary>
    /// <param name="count">The number of item indexes to create.</param>
    /// <returns>A sequential order array.</returns>
    private static int[] CreateSequentialOrder(int count)
    {
        int[] order = new int[count];
        for (int i = 0; i < order.Length; i++)
        {
            order[i] = i;
        }

        return order;
    }

    /// <summary>
    /// Creates a deterministic lexical insertion order for generated VS8 keys.<br/>
    /// Sorting indexes instead of key arrays preserves the original identity source index for correctness checks and SQLite parity rows.<br/>
    /// </summary>
    /// <param name="keys">The generated raw byte keys.</param>
    /// <returns>An order array sorted by raw key bytes.</returns>
    private static int[] CreateSortedVarKeyScalar8Order(byte[][] keys)
    {
        int[] order = CreateSequentialOrder(keys.Length);
        Array.Sort(order, (left, right) => keys[left].AsSpan().SequenceCompareTo(keys[right]));
        return order;
    }

    /// <summary>
    /// Creates a deterministic shuffled insertion order for repeatable random-write comparisons.<br/>
    /// A fixed seed keeps benchmark rows comparable across runs while still breaking append-like key locality.<br/>
    /// </summary>
    /// <param name="count">The number of item indexes to create.</param>
    /// <param name="seed">The deterministic shuffle seed.</param>
    /// <returns>A shuffled order array.</returns>
    private static int[] CreateDeterministicShuffledOrder(int count, int seed)
    {
        int[] order = CreateSequentialOrder(count);
        Random random = new(seed);
        for (int i = order.Length - 1; i > 0; i--)
        {
            int selected = random.Next(i + 1);
            (order[i], order[selected]) = (order[selected], order[i]);
        }

        return order;
    }

    /// <summary>
    /// Describes the coarse insertion order for one write-matrix row.<br/>
    /// The label is diagnostic only and avoids overloading the developer write-intent value with how the harness arranged its input array.<br/>
    /// </summary>
    /// <param name="order">The insertion order expressed as indexes into <paramref name="keys"/>.</param>
    /// <param name="keys">The generated raw byte keys.</param>
    /// <returns>A short order label.</returns>
    private static string DescribeVarKeyScalar8WriteOrder(ReadOnlySpan<int> order, byte[][] keys)
    {
        bool sequential = true;
        bool sorted = true;
        for (int i = 0; i < order.Length; i++)
        {
            sequential &= order[i] == i;
            if (i > 0 && keys[order[i - 1]].AsSpan().SequenceCompareTo(keys[order[i]]) > 0)
            {
                sorted = false;
            }
        }

        if (sequential)
        {
            return "generated";
        }

        return sorted ? "sorted" : "shuffled";
    }

    /// <summary>
    /// Converts a write-intent value into a compact benchmark label.<br/>
    /// This keeps matrix rows readable while still exposing the developer hint tuple that drove the LibraDex batch policy.<br/>
    /// </summary>
    /// <param name="writeIntent">The write-intent value to describe.</param>
    /// <returns>A compact write-intent label.</returns>
    private static string DescribeWriteIntent(LibraDexWriteIntent writeIntent)
    {
        return $"{writeIntent.Order}/{writeIntent.Volume}/{writeIntent.Locality}/{writeIntent.Priority}";
    }

    /// <summary>
    /// Prints one VS8 write-intent matrix row using invariant numeric formatting.<br/>
    /// SQLite rows use zero structural counters because their comparable route shape is intentionally opaque to this harness.<br/>
    /// </summary>
    /// <param name="result">The measured write-matrix row.</param>
    /// <param name="itemCount">The logical item count used for bytes-per-item reporting.</param>
    private static void PrintVarKeyScalar8WriteMatrixResult(VarKeyScalar8WriteMatrixResult result, int itemCount)
    {
        Console.WriteLine(FormattableString.Invariant(
            $"| {result.Label} | {result.Order} | {result.Intent} | {result.ItemsPerSecond:F2} | {result.Elapsed.TotalMilliseconds:F2} | {result.AllocatedBytes / 1024.0:F2} | {TicksToMilliseconds(result.Attribution.RouteWalkTicks):F2} | {TicksToMilliseconds(result.Attribution.ShelfReadTicks):F2} | {TicksToMilliseconds(result.Attribution.MutationTicks):F2} | {TicksToMilliseconds(result.Attribution.StageTicks):F2} | {TicksToMilliseconds(result.Attribution.StructuralTicks):F2} | {result.CommitElapsed.TotalMilliseconds:F2} | {result.Commit.WriteCallCount} | {result.Commit.BytesWritten} | {result.Bytes} | {(double)result.Bytes / itemCount:F2} | {result.Growths} | {result.Transforms} | {result.ColdTelemetry.AverageTargetRouterDepth:F2} | {result.ColdTelemetry.MaxTargetRouterDepth} | {result.ColdTelemetry.AverageTransformRouterDepth:F2} | {result.ColdTelemetry.MaxTransformRouterDepth} | {result.ColdTelemetry.AverageTransformShelfItems:F2} | {result.ColdTelemetry.MaxTransformShelfItems} | {result.RouterCount} | {result.MultiByteRouterCount} | {result.ShelfCount} | {result.AverageRouteDepth:F2} | {result.MaxRouteDepth} |"));
    }

    /// <summary>
    /// Converts Stopwatch ticks to milliseconds for benchmark attribution output.<br/>
    /// Keeping the conversion centralized avoids mixing Stopwatch ticks with TimeSpan ticks in wide matrix rows.<br/>
    /// </summary>
    /// <param name="ticks">The Stopwatch tick count.</param>
    /// <returns>The equivalent elapsed milliseconds.</returns>
    private static double TicksToMilliseconds(long ticks)
    {
        return ticks * 1000.0 / Stopwatch.Frequency;
    }

    /// <summary>
    /// Holds one write-intent matrix measurement row.<br/>
    /// LibraDex rows include route-shape counters; SQLite rows keep those counters at zero because the physical B-tree shape is outside the harness contract.<br/>
    /// </summary>
    /// <param name="Label">The benchmark row label.</param>
    /// <param name="Order">The harness insertion-order label.</param>
    /// <param name="Intent">The developer write-intent label.</param>
    /// <param name="ItemsPerSecond">The measured logical write throughput.</param>
    /// <param name="Elapsed">The elapsed write time.</param>
    /// <param name="Bytes">The resulting backing storage bytes.</param>
    /// <param name="Growths">The number of walked shelf growth events.</param>
    /// <param name="Transforms">The number of walked shelf-to-router transform events.</param>
    /// <param name="RouterCount">The number of routed LibraDex routers after the write.</param>
    /// <param name="MultiByteRouterCount">The number of multi-byte LibraDex routers after the write.</param>
    /// <param name="ShelfCount">The number of reached LibraDex shelves after the write.</param>
    /// <param name="AverageRouteDepth">The average routed leaf depth after the write.</param>
    /// <param name="MaxRouteDepth">The maximum routed leaf depth after the write.</param>
    /// <param name="ColdTelemetry">The walked structural telemetry captured during LibraDex write loops.</param>
    /// <param name="Attribution">The walked-write attribution totals for LibraDex walked rows.</param>
    /// <param name="CommitElapsed">The wall-clock elapsed time spent in the final commit or transaction commit phase.</param>
    /// <param name="Commit">The DataKernel commit telemetry for LibraDex rows.</param>
    /// <param name="AllocatedBytes">The bytes allocated on the current managed thread during the measured write phase.</param>
    private readonly record struct VarKeyScalar8WriteMatrixResult(
        string Label,
        string Order,
        string Intent,
        double ItemsPerSecond,
        TimeSpan Elapsed,
        long Bytes,
        long Growths,
        long Transforms,
        long RouterCount,
        long MultiByteRouterCount,
        long ShelfCount,
        double AverageRouteDepth,
        int MaxRouteDepth,
        VarKeyScalar8WalkedColdTelemetry ColdTelemetry,
        VarKeyScalar8WalkedWriteAttribution Attribution,
        TimeSpan CommitElapsed,
        DataKernelCommitTelemetry Commit,
        long AllocatedBytes)
    {
        /// <summary>
        /// Creates a LibraDex matrix row from elapsed write time and route-shape diagnostics.<br/>
        /// The helper centralizes throughput calculation so row construction remains consistent across walked and bulk cases.<br/>
        /// </summary>
        /// <param name="label">The benchmark row label.</param>
        /// <param name="order">The harness insertion-order label.</param>
        /// <param name="intent">The developer write-intent label.</param>
        /// <param name="itemCount">The logical item count written.</param>
        /// <param name="elapsed">The elapsed write time.</param>
        /// <param name="bytes">The resulting backing storage bytes.</param>
        /// <param name="growths">The number of walked shelf growth events.</param>
        /// <param name="transforms">The number of walked shelf-to-router transform events.</param>
        /// <param name="stats">The route-shape diagnostics after reopen.</param>
        /// <param name="coldTelemetry">The walked structural telemetry captured during LibraDex write loops.</param>
        /// <param name="attribution">The elapsed-time attribution totals captured during walked writes.</param>
        /// <param name="commitElapsed">The measured final commit elapsed time.</param>
        /// <param name="commit">The final DataKernel commit telemetry.</param>
        /// <param name="allocatedBytes">The bytes allocated on the current managed thread during the measured row.</param>
        /// <returns>A populated LibraDex matrix row.</returns>
        public static VarKeyScalar8WriteMatrixResult ForLibraDex(
            string label,
            string order,
            string intent,
            int itemCount,
            TimeSpan elapsed,
            long bytes,
            long growths,
            long transforms,
            VarKeyScalar8RouterShapeStats stats,
            VarKeyScalar8WalkedColdTelemetry coldTelemetry,
            VarKeyScalar8WalkedWriteAttribution attribution,
            TimeSpan commitElapsed,
            DataKernelCommitTelemetry commit,
            long allocatedBytes)
        {
            return new VarKeyScalar8WriteMatrixResult(
                label,
                order,
                intent,
                itemCount / Math.Max(elapsed.TotalSeconds, 0.000001),
                elapsed,
                bytes,
                growths,
                transforms,
                stats.RouterCount,
                stats.MultiByteRouterCount,
                stats.ShelfCount,
                stats.AverageRouteDepth,
                stats.MaxRouteDepth,
                coldTelemetry,
                attribution,
                commitElapsed,
                commit,
                allocatedBytes);
        }

        /// <summary>
        /// Creates a SQLite matrix row from elapsed transaction write time.<br/>
        /// Structural counters are zero because SQLite route internals are deliberately not part of this LibraDex harness row.<br/>
        /// </summary>
        /// <param name="label">The benchmark row label.</param>
        /// <param name="order">The harness insertion-order label.</param>
        /// <param name="itemCount">The logical item count written.</param>
        /// <param name="elapsed">The elapsed write time.</param>
        /// <param name="bytes">The resulting SQLite storage bytes.</param>
        /// <returns>A populated SQLite matrix row.</returns>
        public static VarKeyScalar8WriteMatrixResult ForSqlite(
            string label,
            string order,
            int itemCount,
            TimeSpan elapsed,
            long bytes,
            TimeSpan commitElapsed,
            long allocatedBytes)
        {
            return new VarKeyScalar8WriteMatrixResult(
                label,
                order,
                "transaction",
                itemCount / Math.Max(elapsed.TotalSeconds, 0.000001),
                elapsed,
                bytes,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                default,
                default,
                commitElapsed,
                default,
                allocatedBytes);
        }
    }

    /// <summary>
    /// Compares the first session-backed routed `VS8` path against SQLite for the same raw `BLOB key -> INTEGER identity` index shape.<br/>
    /// LibraDex writes use the real `LibraDexFileSession` route walk, shelf rewrite, shelf growth, route repoint, and DataKernel publication path inside one durability batch.<br/>
    /// SQLite writes use one transaction against a `WITHOUT ROWID` primary-key table so both rows measure batched logical index construction rather than one fsync per inserted identity.<br/>
    /// Reads reopen the LibraDex file and scan a prefix-spanning range through the routed shelf reader, then run the equivalent ordered SQLite range query.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunVarKeyScalar8RoutedSqliteComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS8RoutedSqliteComparison"));
        int itemCount = GetIntOption(args, "--items", 2048);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int iterations = GetIntOption(args, "--iterations", 200);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        bool skipBulk = GetBoolOption(args, "--skip-bulk", false);
        string iterationModeText = GetOption(args, "--iteration-mode", "identities");
        VarIdentityIterationMode iterationMode = ParseVarIdentityIterationMode(iterationModeText);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256 || iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS8 routed SQLite comparison requires positive items/iterations, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "vs8-routed.lbdx");
        string libraBulkPath = Path.Combine(directory, "vs8-routed-bulk.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-vs8-routed.db");
        File.Delete(libraPath);
        File.Delete(libraBulkPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        long rootOffset;
        long libraGrowths = 0;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(809), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8rcmp", 0));
            rootOffset = root.Offset;
            for (int prefix = 0; prefix < prefixCount; prefix++)
            {
                _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, (byte)prefix, VarKeyScalar8Profile.DefaultInitial);
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength: 1024, key, CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedGrow)
                {
                    libraGrowths++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        long bulkShelfCount = 0;
        long bulkRootOffset = 0;
        TimeSpan libraBulkWriteElapsed = TimeSpan.Zero;
        if (!skipBulk)
        {
            Stopwatch libraBulkWriteWatch = Stopwatch.StartNew();
            using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraBulkPath, libraOptions, CreateDesignPerfMetadata(810), DataKernelTelemetryOptions.EnabledOptions))
            {
                (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8rblk", 0));
                bulkRootOffset = root.Offset;
                using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
                for (int prefix = 0; prefix < prefixCount; prefix++)
                {
                    CreateVarKeyScalar8PrefixShelf(itemCount, keyLength, prefixCount, prefix, out VarKeyScalar8Profile profile, out byte[] shelfBytes);
                    _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(bulkRootOffset, (byte)prefix, profile, shelfBytes);
                    bulkShelfCount++;
                }

                _ = durabilityBatch.Commit();
            }

            libraBulkWriteWatch.Stop();
            libraBulkWriteElapsed = libraBulkWriteWatch.Elapsed;
        }

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteVarKeyScalar8Schema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Integer);
            for (int i = 0; i < itemCount; i++)
            {
                keyParameter.Value = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                identityParameter.Value = EncodeSqliteSortableUnsignedScalar8(CreateVarKeyScalar8Identity(i));
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        VarKeyScalar8ReadMeasurement libraRead;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraRead = MeasureVarKeyScalar8RoutedRangeReads(reopened, rootOffset, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        VarKeyScalar8ReadMeasurement libraBulkRead = default;
        if (!skipBulk)
        {
            using LibraDexFileSession reopened = LibraDexFileSession.Open(libraBulkPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions);
            libraBulkRead = MeasureVarKeyScalar8RoutedRangeReads(reopened, bulkRootOffset, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteVarKeyScalar8RangeReads(connection, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        long libraBytes = new FileInfo(libraPath).Length;
        long libraBulkBytes = skipBulk ? 0 : new FileInfo(libraBulkPath).Length;
        long sqliteBytes = GetSqliteScalar8Scalar8StorageBytes(sqlitePath);
        double libraWriteItemsPerSecond = itemCount / Math.Max(libraWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double libraBulkWriteItemsPerSecond = skipBulk ? 0 : itemCount / Math.Max(libraBulkWriteElapsed.TotalSeconds, 0.000001);
        double sqliteWriteItemsPerSecond = itemCount / Math.Max(sqliteWriteWatch.Elapsed.TotalSeconds, 0.000001);
        Console.WriteLine("vs8 routed sqlite comparison");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"iterationMode {iterationModeText}");
        Console.WriteLine($"skipBulk {skipBulk}");
        Console.WriteLine($"libraGrowths {libraGrowths}");
        Console.WriteLine($"libraBulkShelves {bulkShelfCount}");
        Console.WriteLine("| row | items/sec | ids/sec | ns/id | readCalls | backingReads | readBytes | cacheArenas | cacheBytes | bytes | bytes/item | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| VS8 routed write/read | {libraWriteItemsPerSecond:F2} | {libraRead.IdentitiesPerSecond:F2} | {libraRead.NsPerIdentity:F2} | {libraRead.ReadTelemetry.ReadCallCount} | {libraRead.ReadTelemetry.BackingReadCallCount} | {libraRead.ReadTelemetry.BytesRead} | {libraRead.RouterArenaCacheCount} | {libraRead.RouterArenaCacheBytes} | {libraBytes} | {(double)libraBytes / itemCount:F2} | {libraRead.Checksum} |"));
        if (!skipBulk)
        {
            Console.WriteLine(FormattableString.Invariant($"| VS8 routed bulk build/read | {libraBulkWriteItemsPerSecond:F2} | {libraBulkRead.IdentitiesPerSecond:F2} | {libraBulkRead.NsPerIdentity:F2} | {libraBulkRead.ReadTelemetry.ReadCallCount} | {libraBulkRead.ReadTelemetry.BackingReadCallCount} | {libraBulkRead.ReadTelemetry.BytesRead} | {libraBulkRead.RouterArenaCacheCount} | {libraBulkRead.RouterArenaCacheBytes} | {libraBulkBytes} | {(double)libraBulkBytes / itemCount:F2} | {libraBulkRead.Checksum} |"));
        }

        Console.WriteLine(FormattableString.Invariant($"| SQLite write/read | {sqliteWriteItemsPerSecond:F2} | {sqliteRead.IdentitiesPerSecond:F2} | {sqliteRead.NsPerIdentity:F2} | 0 | 0 | 0 | 0 | 0 | {sqliteBytes} | {(double)sqliteBytes / itemCount:F2} | {sqliteRead.Checksum} |"));
        Console.WriteLine($"VS8/SQLite read {FormatMultiplier(libraRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS8/SQLite write {FormatMultiplier(libraWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        if (!skipBulk)
        {
            Console.WriteLine($"VS8 bulk/SQLite read {FormatMultiplier(libraBulkRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
            Console.WriteLine($"VS8 bulk/SQLite write {FormatMultiplier(libraBulkWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        }

        return 0;
    }

    /// <summary>
    /// Compares the routed `VS16` clone against routed `VS8`-style construction and a matching SQLite `BLOB key -> BLOB identity` table.<br/>
    /// This command intentionally mirrors `vs8-routed-sqlite-comparison` so shape drift is visible as timing or file-size drift rather than benchmark drift.<br/>
    /// SQLite writes use one transaction against a `WITHOUT ROWID` primary-key table, with the identity persisted as a 16-byte big-endian BLOB to match the `VS16` ordered high/low identity contract.<br/>
    /// Reads reopen the LibraDex file and scan the same prefix-spanning range through the routed shelf reader, then run the equivalent ordered SQLite range query.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunVarKeyScalar16RoutedSqliteComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VS16RoutedSqliteComparison"));
        int itemCount = GetIntOption(args, "--items", 2048);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int iterations = GetIntOption(args, "--iterations", 200);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        bool skipBulk = GetBoolOption(args, "--skip-bulk", false);
        string iterationModeText = GetOption(args, "--iteration-mode", "identities");
        VarIdentityIterationMode iterationMode = ParseVarIdentityIterationMode(iterationModeText);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || prefixCount <= 0 || prefixCount > 256 || iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VS16 routed SQLite comparison requires positive items/iterations, key length 1-1024, and prefix count 1-256.");
        }

        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "vs16-routed.lbdx");
        string libraBulkPath = Path.Combine(directory, "vs16-routed-bulk.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-vs16-routed.db");
        File.Delete(libraPath);
        File.Delete(libraBulkPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        long rootOffset;
        long libraGrowths = 0;
        long libraTransforms = 0;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(9161), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16rcmp", 0));
            rootOffset = root.Offset;
            for (int prefix = 0; prefix < prefixCount; prefix++)
            {
                _ = session.CreateVarKeyScalar16ShelfAndLinkRootRoute(rootOffset, (byte)prefix, VarKeyScalar16Profile.DefaultInitial);
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                VarKeyScalar16RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar16(rootOffset, maxKeyLength: 1024, key, identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar16InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed VS16 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedGrow)
                {
                    libraGrowths++;
                }

                if (result.Kind == VarKeyScalar16RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    libraTransforms++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        long bulkShelfCount = 0;
        long bulkRootOffset = 0;
        TimeSpan libraBulkWriteElapsed = TimeSpan.Zero;
        if (!skipBulk)
        {
            Stopwatch libraBulkWriteWatch = Stopwatch.StartNew();
            using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraBulkPath, libraOptions, CreateDesignPerfMetadata(9162), DataKernelTelemetryOptions.EnabledOptions))
            {
                (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs16rblk", 0));
                bulkRootOffset = root.Offset;
                using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
                for (int prefix = 0; prefix < prefixCount; prefix++)
                {
                    CreateVarKeyScalar16PrefixShelf(itemCount, keyLength, prefixCount, prefix, out VarKeyScalar16Profile profile, out byte[] shelfBytes);
                    _ = session.CreateVarKeyScalar16ShelfAndLinkRootRoute(bulkRootOffset, (byte)prefix, profile, shelfBytes);
                    bulkShelfCount++;
                }

                _ = durabilityBatch.Commit();
            }

            libraBulkWriteWatch.Stop();
            libraBulkWriteElapsed = libraBulkWriteWatch.Elapsed;
        }

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteVarKeyScalar16Schema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Blob);
            for (int i = 0; i < itemCount; i++)
            {
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                keyParameter.Value = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                identityParameter.Value = CreateSqliteScalar16Scalar16Blob(identityHigh, identityLow);
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        VarKeyScalar8ReadMeasurement libraRead;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraRead = MeasureVarKeyScalar16RoutedRangeReads(reopened, rootOffset, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        VarKeyScalar8ReadMeasurement libraBulkRead = default;
        if (!skipBulk)
        {
            using LibraDexFileSession reopened = LibraDexFileSession.Open(libraBulkPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions);
            libraBulkRead = MeasureVarKeyScalar16RoutedRangeReads(reopened, bulkRootOffset, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteVarKeyScalar16RangeReads(connection, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        long libraBytes = new FileInfo(libraPath).Length;
        long libraBulkBytes = skipBulk ? 0 : new FileInfo(libraBulkPath).Length;
        long sqliteBytes = GetSqliteScalar8Scalar8StorageBytes(sqlitePath);
        double libraWriteItemsPerSecond = itemCount / Math.Max(libraWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double libraBulkWriteItemsPerSecond = skipBulk ? 0 : itemCount / Math.Max(libraBulkWriteElapsed.TotalSeconds, 0.000001);
        double sqliteWriteItemsPerSecond = itemCount / Math.Max(sqliteWriteWatch.Elapsed.TotalSeconds, 0.000001);
        Console.WriteLine("vs16 routed sqlite comparison");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"iterationMode {iterationModeText}");
        Console.WriteLine($"skipBulk {skipBulk}");
        Console.WriteLine($"libraGrowths {libraGrowths}");
        Console.WriteLine($"libraTransforms {libraTransforms}");
        Console.WriteLine($"libraBulkShelves {bulkShelfCount}");
        Console.WriteLine("| row | items/sec | ids/sec | ns/id | readCalls | backingReads | readBytes | cacheArenas | cacheBytes | bytes | bytes/item | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| VS16 routed write/read | {libraWriteItemsPerSecond:F2} | {libraRead.IdentitiesPerSecond:F2} | {libraRead.NsPerIdentity:F2} | {libraRead.ReadTelemetry.ReadCallCount} | {libraRead.ReadTelemetry.BackingReadCallCount} | {libraRead.ReadTelemetry.BytesRead} | {libraRead.RouterArenaCacheCount} | {libraRead.RouterArenaCacheBytes} | {libraBytes} | {(double)libraBytes / itemCount:F2} | {libraRead.Checksum} |"));
        if (!skipBulk)
        {
            Console.WriteLine(FormattableString.Invariant($"| VS16 routed bulk build/read | {libraBulkWriteItemsPerSecond:F2} | {libraBulkRead.IdentitiesPerSecond:F2} | {libraBulkRead.NsPerIdentity:F2} | {libraBulkRead.ReadTelemetry.ReadCallCount} | {libraBulkRead.ReadTelemetry.BackingReadCallCount} | {libraBulkRead.ReadTelemetry.BytesRead} | {libraBulkRead.RouterArenaCacheCount} | {libraBulkRead.RouterArenaCacheBytes} | {libraBulkBytes} | {(double)libraBulkBytes / itemCount:F2} | {libraBulkRead.Checksum} |"));
        }

        Console.WriteLine(FormattableString.Invariant($"| SQLite write/read | {sqliteWriteItemsPerSecond:F2} | {sqliteRead.IdentitiesPerSecond:F2} | {sqliteRead.NsPerIdentity:F2} | 0 | 0 | 0 | 0 | 0 | {sqliteBytes} | {(double)sqliteBytes / itemCount:F2} | {sqliteRead.Checksum} |"));
        Console.WriteLine($"VS16/SQLite read {FormatMultiplier(libraRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VS16/SQLite write {FormatMultiplier(libraWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        if (!skipBulk)
        {
            Console.WriteLine($"VS16 bulk/SQLite read {FormatMultiplier(libraBulkRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
            Console.WriteLine($"VS16 bulk/SQLite write {FormatMultiplier(libraBulkWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        }

        return 0;
    }

    /// <summary>
    /// Compares the first routed `VV` path against SQLite for the same raw `BLOB key -> BLOB identity` index shape.<br/>
    /// LibraDex writes use the real walked routed path inside one session durability batch, defaulting to lazy root-prefix shelf creation so sparse-prefix workloads do not pay for unused shelves.<br/>
    /// SQLite writes use one transaction against a `WITHOUT ROWID` primary-key table so both rows measure batched logical index construction rather than one fsync per inserted identity.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the comparison completes and prints the measured rows.</returns>
    private static int RunVarKeyVarIdentityRoutedSqliteComparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VVRoutedSqliteComparison"));
        int itemCount = GetIntOption(args, "--items", 12000);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        int prefixCount = GetIntOption(args, "--prefix-count", 64);
        int precreatePrefixCount = GetIntOption(args, "--precreate-prefix-count", prefixCount);
        int iterations = GetIntOption(args, "--iterations", 100);
        int maxRouterHops = GetIntOption(args, "--max-router-hops", 8);
        LibraDexWriteIntent writeIntent = GetWriteIntentOption(args);
        bool hasExplicitInitialShelfKiB = HasOption(args, "--initial-shelf-kib");
        int requestedInitialShelfKiB = GetIntOption(args, "--initial-shelf-kib", 0);
        bool lazyRootPrefixes = GetBoolOption(args, "--lazy-root-prefixes", true);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        bool skipBulk = GetBoolOption(args, "--skip-bulk", false);
        string iterationModeText = GetOption(args, "--iteration-mode", "identities");
        VarIdentityIterationMode iterationMode = ParseVarIdentityIterationMode(iterationModeText);
        if (itemCount <= 0 || keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024 || prefixCount <= 0 || prefixCount > 256 || precreatePrefixCount < prefixCount || precreatePrefixCount > 256 || iterations <= 0 || maxRouterHops <= 0 || (hasExplicitInitialShelfKiB && requestedInitialShelfKiB <= 0))
        {
            throw new ArgumentOutOfRangeException(nameof(args), "VV routed SQLite comparison requires positive items/iterations, key length 1-1024, identity length 1-1024, prefix count 1-256, precreate prefix count at least prefix count and at most 256, positive max router hops, and positive initial shelf KiB.");
        }

        Directory.CreateDirectory(directory);
        string libraPath = Path.Combine(directory, "vv-routed.lbdx");
        string libraBulkPath = Path.Combine(directory, "vv-routed-bulk.lbdx");
        string sqlitePath = Path.Combine(directory, "sqlite-vv-routed.db");
        File.Delete(libraPath);
        File.Delete(libraBulkPath);
        ResetSqliteScalar8Scalar8Files(sqlitePath);

        DataKernelOptions libraOptions = CreateDesignPerfOptions();
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        VarKeyVarIdentityProfile initialProfile = hasExplicitInitialShelfKiB
            ? VarKeyVarIdentityProfile.Create(checked(requestedInitialShelfKiB * 1024), 1024, 1024)
            : VarKeyVarIdentityProfile.SelectInitial(writeIntent);
        int initialShelfKiB = initialProfile.ShelfExtentSize / 1024;
        long rootOffset;
        long libraLazyCreates = 0;
        long libraGrowths = 0;
        long libraTransforms = 0;
        Stopwatch libraWriteWatch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(9172), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vvrcmp", 0));
            rootOffset = root.Offset;
            if (!lazyRootPrefixes)
            {
                for (int prefix = 0; prefix < precreatePrefixCount; prefix++)
                {
                    _ = session.CreateVarKeyVarIdentityShelfAndLinkRootRoute(rootOffset, (byte)prefix, initialProfile);
                }
            }

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch(writeIntent);
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                byte[] identity = CreateScalar8VarIdentity(i, identityLength);
                VarKeyVarIdentityRoutedInsertResult result = session.InsertWalkedRoutedVarKeyVarIdentity(rootOffset, maxKeyLength: 1024, maxIdentityLength: 1024, key, identity, allowDuplicateKeys: true, maxRouterHops: maxRouterHops);
                if (result.InsertResult != VarKeyVarIdentityInsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected routed VV insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyVarIdentityRoutedInsertKind.WalkedGrow)
                {
                    libraGrowths++;
                }

                if (result.Kind == VarKeyVarIdentityRoutedInsertKind.WalkedCreatedInitialShelf)
                {
                    libraLazyCreates++;
                }

                if (result.Kind == VarKeyVarIdentityRoutedInsertKind.WalkedShelfTransformSplit)
                {
                    libraTransforms++;
                }
            }

            _ = durabilityBatch.Commit();
        }

        libraWriteWatch.Stop();

        long bulkShelfCount = 0;
        long bulkRootOffset = 0;
        TimeSpan libraBulkWriteElapsed = TimeSpan.Zero;
        if (!skipBulk)
        {
            Stopwatch libraBulkWriteWatch = Stopwatch.StartNew();
            using (LibraDexFileSession session = LibraDexFileSession.Initialize(libraBulkPath, libraOptions, CreateDesignPerfMetadata(9173), DataKernelTelemetryOptions.EnabledOptions))
            {
                (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vvrblk", 0));
                bulkRootOffset = root.Offset;
                using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch(writeIntent);
                for (int prefix = 0; prefix < prefixCount; prefix++)
                {
                    CreateVarKeyVarIdentityPrefixShelf(itemCount, keyLength, identityLength, prefixCount, prefix, initialProfile, out VarKeyVarIdentityProfile profile, out byte[] shelfBytes);
                    _ = session.CreateVarKeyVarIdentityShelfAndLinkRootRoute(bulkRootOffset, (byte)prefix, profile, shelfBytes);
                    bulkShelfCount++;
                }

                _ = durabilityBatch.Commit();
            }

            libraBulkWriteWatch.Stop();
            libraBulkWriteElapsed = libraBulkWriteWatch.Elapsed;
        }

        Stopwatch sqliteWriteWatch = Stopwatch.StartNew();
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteVarKeyVarIdentitySchema(connection);
            using SqliteTransaction transaction = connection.BeginTransaction();
            using SqliteCommand command = connection.CreateCommand();
            command.Transaction = transaction;
            command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
            SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
            SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Blob);
            for (int i = 0; i < itemCount; i++)
            {
                keyParameter.Value = CreateVarKeyScalar8Key(i, keyLength, prefixCount);
                identityParameter.Value = CreateScalar8VarIdentity(i, identityLength);
                command.ExecuteNonQuery();
            }

            transaction.Commit();
        }

        sqliteWriteWatch.Stop();

        VarKeyScalar8ReadMeasurement libraRead;
        using (LibraDexFileSession reopened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraRead = MeasureVarKeyVarIdentityRoutedRangeReads(reopened, rootOffset, keyLength, prefixCount, itemCount, iterations, iterationMode, maxRouterHops);
        }

        VarKeyScalar8ReadMeasurement libraBulkRead = default;
        if (!skipBulk)
        {
            using LibraDexFileSession reopened = LibraDexFileSession.Open(libraBulkPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions);
            libraBulkRead = MeasureVarKeyVarIdentityRoutedRangeReads(reopened, bulkRootOffset, keyLength, prefixCount, itemCount, iterations, iterationMode, maxRouterHops);
        }

        VarKeyScalar8ReadMeasurement sqliteRead;
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteRead = MeasureSqliteVarKeyVarIdentityRangeReads(connection, keyLength, prefixCount, itemCount, iterations, iterationMode);
        }

        long libraBytes = new FileInfo(libraPath).Length;
        long libraBulkBytes = skipBulk ? 0 : new FileInfo(libraBulkPath).Length;
        long sqliteBytes = GetSqliteScalar8Scalar8StorageBytes(sqlitePath);
        double libraWriteItemsPerSecond = itemCount / Math.Max(libraWriteWatch.Elapsed.TotalSeconds, 0.000001);
        double libraBulkWriteItemsPerSecond = skipBulk ? 0 : itemCount / Math.Max(libraBulkWriteElapsed.TotalSeconds, 0.000001);
        double sqliteWriteItemsPerSecond = itemCount / Math.Max(sqliteWriteWatch.Elapsed.TotalSeconds, 0.000001);
        Console.WriteLine("vv routed sqlite comparison");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"identityLength {identityLength}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"precreatePrefixCount {precreatePrefixCount}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"iterationMode {iterationModeText}");
        Console.WriteLine($"maxRouterHops {maxRouterHops}");
        Console.WriteLine($"initialShelfKiB {initialShelfKiB}");
        Console.WriteLine($"writeIntent {DescribeWriteIntent(writeIntent)}");
        Console.WriteLine($"skipBulk {skipBulk}");
        Console.WriteLine($"lazyRootPrefixes {lazyRootPrefixes}");
        Console.WriteLine($"libraLazyCreates {libraLazyCreates}");
        Console.WriteLine($"libraGrowths {libraGrowths}");
        Console.WriteLine($"libraTransforms {libraTransforms}");
        Console.WriteLine($"libraBulkShelves {bulkShelfCount}");
        Console.WriteLine("| row | items/sec | ids/sec | ns/id | readCalls | backingReads | readBytes | cacheArenas | cacheBytes | bytes | bytes/item | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        Console.WriteLine(FormattableString.Invariant($"| VV routed write/read | {libraWriteItemsPerSecond:F2} | {libraRead.IdentitiesPerSecond:F2} | {libraRead.NsPerIdentity:F2} | {libraRead.ReadTelemetry.ReadCallCount} | {libraRead.ReadTelemetry.BackingReadCallCount} | {libraRead.ReadTelemetry.BytesRead} | {libraRead.RouterArenaCacheCount} | {libraRead.RouterArenaCacheBytes} | {libraBytes} | {(double)libraBytes / itemCount:F2} | {libraRead.Checksum} |"));
        if (!skipBulk)
        {
            Console.WriteLine(FormattableString.Invariant($"| VV routed bulk build/read | {libraBulkWriteItemsPerSecond:F2} | {libraBulkRead.IdentitiesPerSecond:F2} | {libraBulkRead.NsPerIdentity:F2} | {libraBulkRead.ReadTelemetry.ReadCallCount} | {libraBulkRead.ReadTelemetry.BackingReadCallCount} | {libraBulkRead.ReadTelemetry.BytesRead} | {libraBulkRead.RouterArenaCacheCount} | {libraBulkRead.RouterArenaCacheBytes} | {libraBulkBytes} | {(double)libraBulkBytes / itemCount:F2} | {libraBulkRead.Checksum} |"));
        }

        Console.WriteLine(FormattableString.Invariant($"| SQLite write/read | {sqliteWriteItemsPerSecond:F2} | {sqliteRead.IdentitiesPerSecond:F2} | {sqliteRead.NsPerIdentity:F2} | 0 | 0 | 0 | 0 | 0 | {sqliteBytes} | {(double)sqliteBytes / itemCount:F2} | {sqliteRead.Checksum} |"));
        Console.WriteLine($"VV/SQLite read {FormatMultiplier(libraRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
        Console.WriteLine($"VV/SQLite write {FormatMultiplier(libraWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        if (!skipBulk)
        {
            Console.WriteLine($"VV bulk/SQLite read {FormatMultiplier(libraBulkRead.IdentitiesPerSecond, sqliteRead.IdentitiesPerSecond)}");
            Console.WriteLine($"VV bulk/SQLite write {FormatMultiplier(libraBulkWriteItemsPerSecond, sqliteWriteItemsPerSecond)}");
        }

        return 0;
    }

    /// <summary>
    /// Builds one sorted precompacted `VS8` shelf for a generated first-byte prefix.<br/>
    /// The helper keeps bulk-build comparison honest by using the same raw keys and identities as routed incremental and SQLite rows, then writing the final shelf image once.<br/>
    /// </summary>
    /// <param name="itemCount">The total generated item count.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="prefix">The prefix to materialize.</param>
    /// <param name="profile">The selected shelf profile that can contain the prefix rows.</param>
    /// <param name="shelfBytes">The prebuilt shelf bytes.</param>
    private static void CreateVarKeyScalar8PrefixShelf(
        int itemCount,
        int keyLength,
        int prefixCount,
        int prefix,
        out VarKeyScalar8Profile profile,
        out byte[] shelfBytes)
    {
        List<(byte[] Key, ulong Identity)> items = [];
        for (int i = 0; i < itemCount; i++)
        {
            if (i % prefixCount == prefix)
            {
                items.Add((CreateVarKeyScalar8Key(i, keyLength, prefixCount), CreateVarKeyScalar8Identity(i)));
            }
        }

        items.Sort(static (left, right) =>
        {
            int keyComparison = left.Key.AsSpan().SequenceCompareTo(right.Key);
            if (keyComparison != 0)
            {
                return keyComparison;
            }

            return left.Identity.CompareTo(right.Identity);
        });

        byte[][] keys = new byte[items.Count][];
        ulong[] identities = new ulong[items.Count];
        for (int i = 0; i < items.Count; i++)
        {
            keys[i] = items[i].Key;
            identities[i] = items[i].Identity;
        }

        profile = SelectVarKeyScalar8BuildProfile(keys, identities);
        if (!VarKeyScalar8.TryBuildFromSorted(keys, identities, profile, out shelfBytes))
        {
            throw new InvalidDataException($"VS8 routed bulk build could not build prefix {prefix} shelf at {profile.ShelfExtentSize} bytes.");
        }
    }

    /// <summary>
    /// Builds one sorted precompacted `VS16` shelf for a generated first-byte prefix.<br/>
    /// This is the fixed-identity-width counterpart to `CreateVarKeyScalar8PrefixShelf`, keeping key generation and sorted tuple ordering identical while widening only the identity payload.<br/>
    /// The resulting bytes are used by the routed bulk-build comparison row so the measured difference from `VS8` is shelf capacity and identity width, not construction policy.<br/>
    /// </summary>
    /// <param name="itemCount">The total generated item count.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="prefix">The prefix to materialize.</param>
    /// <param name="profile">The selected shelf profile that can contain the prefix rows.</param>
    /// <param name="shelfBytes">The prebuilt shelf bytes.</param>
    private static void CreateVarKeyScalar16PrefixShelf(
        int itemCount,
        int keyLength,
        int prefixCount,
        int prefix,
        out VarKeyScalar16Profile profile,
        out byte[] shelfBytes)
    {
        List<(byte[] Key, ulong IdentityHigh, ulong IdentityLow)> items = [];
        for (int i = 0; i < itemCount; i++)
        {
            if (i % prefixCount == prefix)
            {
                CreateVarKeyScalar16Identity(i, out ulong identityHigh, out ulong identityLow);
                items.Add((CreateVarKeyScalar8Key(i, keyLength, prefixCount), identityHigh, identityLow));
            }
        }

        items.Sort(static (left, right) =>
        {
            int keyComparison = left.Key.AsSpan().SequenceCompareTo(right.Key);
            if (keyComparison != 0)
            {
                return keyComparison;
            }

            int highComparison = left.IdentityHigh.CompareTo(right.IdentityHigh);
            return highComparison != 0
                ? highComparison
                : left.IdentityLow.CompareTo(right.IdentityLow);
        });

        byte[][] keys = new byte[items.Count][];
        ulong[] identityHighs = new ulong[items.Count];
        ulong[] identityLows = new ulong[items.Count];
        for (int i = 0; i < items.Count; i++)
        {
            keys[i] = items[i].Key;
            identityHighs[i] = items[i].IdentityHigh;
            identityLows[i] = items[i].IdentityLow;
        }

        profile = SelectVarKeyScalar16BuildProfile(keys, identityHighs, identityLows);
        if (!VarKeyScalar16.TryBuildFromSorted(keys, identityHighs, identityLows, profile, out shelfBytes))
        {
            throw new InvalidDataException($"VS16 routed bulk build could not build prefix {prefix} shelf at {profile.ShelfExtentSize} bytes.");
        }
    }

    /// <summary>
    /// Builds one sorted precompacted `VV` shelf for a generated first-byte prefix.<br/>
    /// The helper uses the same generated raw keys and raw identities as the routed incremental and SQLite rows, then writes the final shelf image once.<br/>
    /// This isolates bulk construction potential from walked insert costs without introducing split or optimizer behavior into the first `VV` comparison.<br/>
    /// </summary>
    /// <param name="itemCount">The total generated item count.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="identityLength">The generated identity length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="prefix">The prefix to materialize.</param>
    /// <param name="profile">The selected shelf profile that can contain the prefix rows.</param>
    /// <param name="shelfBytes">The prebuilt shelf bytes.</param>
    private static void CreateVarKeyVarIdentityPrefixShelf(
        int itemCount,
        int keyLength,
        int identityLength,
        int prefixCount,
        int prefix,
        VarKeyVarIdentityProfile initialProfile,
        out VarKeyVarIdentityProfile profile,
        out byte[] shelfBytes)
    {
        List<(byte[] Key, byte[] Identity)> items = [];
        for (int i = 0; i < itemCount; i++)
        {
            if (i % prefixCount == prefix)
            {
                items.Add((CreateVarKeyScalar8Key(i, keyLength, prefixCount), CreateScalar8VarIdentity(i, identityLength)));
            }
        }

        items.Sort(static (left, right) =>
        {
            int keyComparison = left.Key.AsSpan().SequenceCompareTo(right.Key);
            if (keyComparison != 0)
            {
                return keyComparison;
            }

            return VarKeyVarIdentityLayout.CompareIdentityBytes(left.Identity, right.Identity);
        });

        byte[][] keys = new byte[items.Count][];
        byte[][] identities = new byte[items.Count][];
        for (int i = 0; i < items.Count; i++)
        {
            keys[i] = items[i].Key;
            identities[i] = items[i].Identity;
        }

        profile = SelectVarKeyVarIdentityBuildProfile(keys, identities, initialProfile);
        if (!VarKeyVarIdentity.TryBuildFromSorted(keys, identities, profile, out shelfBytes))
        {
            throw new InvalidDataException($"VV routed bulk build could not build prefix {prefix} shelf at {profile.ShelfExtentSize} bytes.");
        }
    }

    /// <summary>
    /// Measures routed `VS8` prefix-range reads through an opened session.<br/>
    /// This exercises root-route enumeration, shelf byte loading, compact slot decoding, and cursor iteration for each iteration.<br/>
    /// </summary>
    /// <param name="session">The opened LibraDex session.</param>
    /// <param name="rootOffset">The root router offset for the `VS8` index.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="itemCount">The total generated identity count.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The routed range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureVarKeyScalar8RoutedRangeReads(LibraDexFileSession session, long rootOffset, int keyLength, int prefixCount, int itemCount, int iterations, VarIdentityIterationMode iterationMode)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        long checksum = 0;
        long total = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            long iterationChecksum = 0;
            using VarKeyScalar8RangeReader reader = session.OpenVarKeyScalar8RangeReader(rootOffset, maxKeyLength: 1024, lower, upper);
            while (reader.MoveNext())
            {
                count++;
                iterationChecksum += ChecksumVarKeyScalar8Current(reader, iterationMode);
            }

            if (count != expected)
            {
                throw new InvalidDataException($"Routed VS8 read comparison expected {expected} identities, got {count}.");
            }

            total += count;
            checksum += iterationChecksum;
        }

        watch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        (int cacheArenaCount, long cacheBytes) = session.GetRouterArenaReadCacheStatsForValidation();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum, telemetry, cacheArenaCount, cacheBytes);
    }

    /// <summary>
    /// Measures routed `VS16` prefix-range reads through an opened session.<br/>
    /// This intentionally matches the `VS8` routed read measurement and changes only the identity output lanes, so clone-fidelity regressions are visible in read telemetry and latency.<br/>
    /// The checksum folds both identity halves to catch unset or swapped high/low values without adding a separate validation pass inside the hot loop.<br/>
    /// </summary>
    /// <param name="session">The opened LibraDex session.</param>
    /// <param name="rootOffset">The root router offset for the `VS16` index.</param>
    /// <param name="keyLength">The generated key length in bytes.</param>
    /// <param name="prefixCount">The number of generated first-byte prefixes.</param>
    /// <param name="itemCount">The total generated identity count.</param>
    /// <param name="iterations">The number of measured range reads.</param>
    /// <param name="iterationMode">The comparison iteration payload mode.</param>
    /// <returns>The routed range-read measurement row.</returns>
    private static VarKeyScalar8ReadMeasurement MeasureVarKeyScalar16RoutedRangeReads(LibraDexFileSession session, long rootOffset, int keyLength, int prefixCount, int itemCount, int iterations, VarIdentityIterationMode iterationMode)
    {
        byte[] lower = CreateVarKeyScalar8PrefixLower(0, keyLength);
        byte[] upper = CreateVarKeyScalar8PrefixUpper(Math.Min(2, prefixCount - 1), keyLength);
        int expected = CountVarKeyScalar8PrefixRange(itemCount, prefixCount, 0, Math.Min(2, prefixCount - 1));
        long checksum = 0;
        long total = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = 0;
            long iterationChecksum = 0;
            using VarKeyScalar16RangeReader reader = session.OpenVarKeyScalar16RangeReader(rootOffset, maxKeyLength: 1024, lower, upper);
            while (reader.MoveNext())
            {
                count++;
                iterationChecksum += ChecksumVarKeyScalar16Current(reader, iterationMode);
            }

            if (count != expected)
            {
                throw new InvalidDataException($"Routed VS16 read comparison expected {expected} identities, got {count}.");
            }

            total += count;
            checksum += iterationChecksum;
        }

        watch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        (int cacheArenaCount, long cacheBytes) = session.GetRouterArenaReadCacheStatsForValidation();
        return CreateVarKeyScalar8ReadMeasurement(iterations, expected, total, watch.Elapsed, checksum, telemetry, cacheArenaCount, cacheBytes);
    }

    /// <summary>
    /// Validates the first public `SS8-8` durability batch API.<br/>
    /// The scenario proves same-batch staged reads are visible to follow-up mutations, commit folds per-item commit requests, and abort discards unpublished staged writes.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when batch commit and abort behavior match the durability-cadence contract.</returns>
    private static int RunScalar8Scalar8BatchSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-batch-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        ulong[] committedIdentities = new ulong[8];
        Scalar8Scalar8BatchCommitResult commit;
        using (Scalar8Scalar8Index index = Indexes.SS88.Create(
            path,
            DataKernelBackingKind.File,
            name: "batch",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(81),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using Scalar8Scalar8Batch batch = index.BeginBatch();
            bool nestedBatchRejected = false;
            try
            {
                using Scalar8Scalar8Batch nested = index.BeginBatch();
            }
            catch (InvalidOperationException)
            {
                nestedBatchRejected = true;
            }

            if (!nestedBatchRejected)
            {
                throw new InvalidDataException("SS8-8 index allowed a nested durability batch on the same session.");
            }

            for (ulong i = 1; i <= 4; i++)
            {
                Scalar8Scalar8EncodedInsertResult insert = batch.InsertEncoded(
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(i),
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(i * 10));
                if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted)
                {
                    throw new InvalidDataException($"Expected batch insert {i} to insert, got {insert.Outcome}.");
                }
            }

            Scalar8Scalar8EncodedInsertResult duplicate = batch.InsertEncoded(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(2),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(20));
            if (duplicate.Outcome != Scalar8Scalar8EncodedInsertOutcome.AlreadyPresent)
            {
                throw new InvalidDataException($"Expected same-batch duplicate insert to report AlreadyPresent, got {duplicate.Outcome}.");
            }

            commit = batch.Commit();
            if (commit.AttemptedInsertCount != 5 ||
                commit.InsertedCount != 4 ||
                commit.AlreadyPresentCount != 1 ||
                commit.InitialShelfRouteCreateCount != 1 ||
                commit.DeferredCommitRequests < 2 ||
                commit.Commit.StagedExtentCount == 0 ||
                commit.Commit.WriteCallCount == 0 ||
                commit.Commit.BytesWritten == 0 ||
                commit.Commit.SetLengthCallCount != 0)
            {
                throw new InvalidDataException("SS8-8 batch commit did not report expected insert counts or folded commit shape.");
            }

            Scalar8Scalar8EncodedRangeReadResult read = index.ReadEncodedRange(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(1),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(4),
                committedIdentities);
            if (read.IdentityCount != 4 ||
                committedIdentities[0] != Scalar8Scalar8Layout.EncodeUnsignedScalar8(10) ||
                committedIdentities[3] != Scalar8Scalar8Layout.EncodeUnsignedScalar8(40))
            {
                throw new InvalidDataException("SS8-8 batch commit did not publish readable encoded identities.");
            }
        }

        Array.Clear(committedIdentities);
        using (Scalar8Scalar8Index committedReopen = Indexes.SS88.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            Scalar8Scalar8EncodedRangeReadResult committedRead = committedReopen.ReadEncodedRange(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(1),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(4),
                committedIdentities);
            if (committedRead.IdentityCount != 4 ||
                committedIdentities[0] != Scalar8Scalar8Layout.EncodeUnsignedScalar8(10) ||
                committedIdentities[3] != Scalar8Scalar8Layout.EncodeUnsignedScalar8(40))
            {
                throw new InvalidDataException("SS8-8 batch commit did not persist encoded identities across reopen.");
            }
        }

        using (Scalar8Scalar8Index reopened = Indexes.SS88.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using Scalar8Scalar8Batch aborted = reopened.BeginBatch();
            _ = aborted.InsertEncoded(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(100),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(1000));
            Scalar8Scalar8BatchAbortResult abort = aborted.Abort();
            if (abort.AttemptedInsertCount != 1)
            {
                throw new InvalidDataException("SS8-8 batch abort did not report the abandoned staged insert.");
            }

            ulong[] abortedIdentities = new ulong[2];
            Scalar8Scalar8EncodedRangeReadResult abortedRead = reopened.ReadEncodedRange(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(100),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(100),
                abortedIdentities);
            if (abortedRead.IdentityCount != 0)
            {
                throw new InvalidDataException("SS8-8 batch abort left unpublished identity data visible.");
            }
        }

        using (Scalar8Scalar8Index abortReopen = Indexes.SS88.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            ulong[] abortedIdentities = new ulong[2];
            Scalar8Scalar8EncodedRangeReadResult abortedRead = abortReopen.ReadEncodedRange(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(100),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(100),
                abortedIdentities);
            if (abortedRead.IdentityCount != 0)
            {
                throw new InvalidDataException("SS8-8 batch abort persisted unpublished identity data across reopen.");
            }
        }

        using (Scalar8Scalar8Index memory = Indexes.SS88.CreateOrOpen(
            backingKind: DataKernelBackingKind.Memory,
            name: "memory-batch",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(82),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using (Scalar8Scalar8Batch memoryCommitBatch = memory.BeginBatch())
            {
                Scalar8Scalar8EncodedInsertResult insert = memoryCommitBatch.InsertEncoded(
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(7),
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(70));
                Scalar8Scalar8BatchCommitResult memoryCommit = memoryCommitBatch.Commit();
                if (insert.Outcome != Scalar8Scalar8EncodedInsertOutcome.Inserted ||
                    memoryCommit.InsertedCount != 1 ||
                    memoryCommit.Commit.BytesWritten == 0)
                {
                    throw new InvalidDataException("Memory-backed SS8-8 batch commit did not report the expected insert and commit shape.");
                }
            }

            ulong[] memoryIdentities = new ulong[2];
            Scalar8Scalar8EncodedRangeReadResult memoryRead = memory.ReadEncodedRange(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(7),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(7),
                memoryIdentities);
            if (memoryRead.IdentityCount != 1 || memoryIdentities[0] != Scalar8Scalar8Layout.EncodeUnsignedScalar8(70))
            {
                throw new InvalidDataException("Memory-backed SS8-8 batch commit did not publish readable identity data.");
            }

            using (Scalar8Scalar8Batch memoryAbortBatch = memory.BeginBatch())
            {
                _ = memoryAbortBatch.InsertEncoded(
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(8),
                    Scalar8Scalar8Layout.EncodeUnsignedScalar8(80));
                Scalar8Scalar8BatchAbortResult memoryAbort = memoryAbortBatch.Abort();
                if (memoryAbort.AttemptedInsertCount != 1)
                {
                    throw new InvalidDataException("Memory-backed SS8-8 batch abort did not report the abandoned staged insert.");
                }
            }

            Array.Clear(memoryIdentities);
            Scalar8Scalar8EncodedRangeReadResult memoryAbortRead = memory.ReadEncodedRange(
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(8),
                Scalar8Scalar8Layout.EncodeUnsignedScalar8(8),
                memoryIdentities);
            if (memoryAbortRead.IdentityCount != 0)
            {
                throw new InvalidDataException("Memory-backed SS8-8 batch abort left unpublished identity data visible.");
            }
        }

        Console.WriteLine("ss8-8 batch sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine("batchCommit ok");
        Console.WriteLine($"batchCommit attempted={commit.AttemptedInsertCount} inserted={commit.InsertedCount} alreadyPresent={commit.AlreadyPresentCount} deferredRequests={commit.DeferredCommitRequests} writeCalls={commit.Commit.WriteCallCount} bytesWritten={commit.Commit.BytesWritten} setLength={commit.Commit.SetLengthCallCount}");
        Console.WriteLine("batchCommitReopen ok");
        Console.WriteLine("batchAbort ok");
        Console.WriteLine("batchAbortReopen ok");
        Console.WriteLine("batchNestedGuard ok");
        Console.WriteLine("memoryBatchCommitAbort ok");
        Console.WriteLine($"ss8-8-batch-sanity ok path={path}");
        return 0;
    }

    /// <summary>
    /// Measures the first routed `SS8-8` range/scoop operation over one shelf.<br/>
    /// The range is intentionally same-shelf so the benchmark isolates routing policy plus one shelf extent read before cross-shelf continuation exists.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the perf report is written.</returns>
    private static int RunScalar8Scalar8RangeScoopPerf(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-range-scoop-perf.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int iterations = GetIntOption(args, "--iterations", 1000);
        int rangeLength = GetIntOption(args, "--range-length", 128);
        if (iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), iterations, "Range scoop perf iterations must be positive.");
        }

        if (rangeLength <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), rangeLength, "Range scoop perf range length must be positive.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        const int rangeStart = 32;
        const ulong rightPrefixBase = 0x0080_0000_0000_0000UL;
        ulong lowerKey = rightPrefixBase + (ulong)rangeStart;
        ulong upperKey = lowerKey + (ulong)(rangeLength - 1);
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(49), DataKernelTelemetryOptions.EnabledOptions);
        RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);
        ulong[] identities = new ulong[rangeLength];
        byte[] shelfBuffer = new byte[profile.ShelfExtentSize];

        Scalar8Scalar8RangeScoopPerfResult uncached = MeasureScalar8Scalar8RangeScoopScenario(
            "same-shelf uncached",
            session,
            setup.RootRouterOffset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            rangeLength,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            identities,
            shelfBuffer,
            validationKind: 0);

        Scalar8Scalar8RangeScoopPerfResult cached = MeasureScalar8Scalar8RangeScoopScenario(
            "same-shelf cached",
            session,
            setup.RootRouterOffset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            rangeLength,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            identities,
            shelfBuffer,
            validationKind: 0);

        const ulong crossLowerKey = 900UL;
        const ulong crossUpperKey = rightPrefixBase + 31UL;
        const int crossRangeLength = 41;
        ulong[] crossIdentities = new ulong[crossRangeLength];

        Scalar8Scalar8RangeScoopPerfResult crossUncached = MeasureScalar8Scalar8RangeScoopScenario(
            "cross-shelf uncached",
            session,
            setup.RootRouterOffset,
            profile,
            crossLowerKey,
            crossUpperKey,
            iterations,
            crossRangeLength,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            crossIdentities,
            shelfBuffer,
            validationKind: 1);

        Scalar8Scalar8RangeScoopPerfResult crossCached = MeasureScalar8Scalar8RangeScoopScenario(
            "cross-shelf cached",
            session,
            setup.RootRouterOffset,
            profile,
            crossLowerKey,
            crossUpperKey,
            iterations,
            crossRangeLength,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            crossIdentities,
            shelfBuffer,
            validationKind: 1);

        (RouterSnapshot traversalRoot, _) = session.CreateRootRouterIndex(CreateHarnessSlot(1, "ss8rngpf", 0));
        CreateTransformSplitVectors(profile, out ulong[] traversalKeys, out ulong[] traversalIdentities, out int _, out int _);
        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(traversalRoot.Offset, profile, traversalKeys, traversalIdentities, [0x00]);
        const ulong traversalSplitKey = rightPrefixBase + 10_000UL;
        _ = session.SplitRoutedScalar8Scalar8ByShelfTransform(traversalRoot.Offset, 0x00, 0x80, profile, traversalSplitKey, traversalSplitKey);
        ulong[] directKeys = new ulong[32];
        ulong[] directIdentities = new ulong[directKeys.Length];
        const ulong directPrefixBase = 0x0100_0000_0000_0000UL;
        for (int i = 0; i < directKeys.Length; i++)
        {
            directKeys[i] = directPrefixBase + (ulong)i;
            directIdentities[i] = directKeys[i];
        }

        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(traversalRoot.Offset, profile, directKeys, directIdentities, [0x01]);
        const ulong traversalLowerKey = rightPrefixBase + 900UL;
        const ulong traversalUpperKey = directPrefixBase + 31UL;
        const int traversalRangeLength = 42;
        ulong[] traversalIdentitiesBuffer = new ulong[traversalRangeLength];
        byte[] traversalCoalesceBuffer = new byte[profile.ShelfExtentSize * 4];

        Scalar8Scalar8RangeScoopPerfResult traversalUncached = MeasureScalar8Scalar8RangeScoopScenario(
            "traversal uncached",
            session,
            traversalRoot.Offset,
            profile,
            traversalLowerKey,
            traversalUpperKey,
            iterations,
            traversalRangeLength,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            traversalIdentitiesBuffer,
            shelfBuffer,
            validationKind: 2);

        Scalar8Scalar8RangeScoopPerfResult traversalCached = MeasureScalar8Scalar8RangeScoopScenario(
            "traversal cached",
            session,
            traversalRoot.Offset,
            profile,
            traversalLowerKey,
            traversalUpperKey,
            iterations,
            traversalRangeLength,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            traversalIdentitiesBuffer,
            shelfBuffer,
            validationKind: 2);

        Scalar8Scalar8RangeScoopPerfResult traversalApiCoalescingCached = MeasureScalar8Scalar8RangeReadApiScenario(
            "traversal api coalescing cached",
            session,
            traversalRoot.Offset,
            profile,
            traversalLowerKey,
            traversalUpperKey,
            iterations,
            traversalRangeLength,
            Scalar8Scalar8RangeReadOptions.CoalescingCached,
            traversalIdentitiesBuffer,
            shelfBuffer,
            traversalCoalesceBuffer,
            validationKind: 2);

        Scalar8Scalar8RangeScoopPerfResult traversalPooledCoalescingCached = MeasureScalar8Scalar8RangeReadPooledScenario(
            "traversal pooled coalescing cached",
            session,
            traversalRoot.Offset,
            profile,
            traversalLowerKey,
            traversalUpperKey,
            iterations,
            traversalRangeLength,
            Scalar8Scalar8RangeReadOptions.CoalescingCached,
            traversalIdentitiesBuffer,
            validationKind: 2);

        Scalar8Scalar8RangeScoopPerfResult[] results = [uncached, cached, crossUncached, crossCached, traversalUncached, traversalCached, traversalApiCoalescingCached, traversalPooledCoalescingCached];
        Console.WriteLine("ss8-8 range scoop perf");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"rangeLength {rangeLength}");
        PrintScalar8Scalar8RangeScoopPerf(results);
        string reportPath = WriteScalar8Scalar8RangeScoopPerfReport(artifactDirectory, iterations, rangeLength, results);
        Console.WriteLine($"ss8-8 range scoop perf report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Runs a routed `SS8-8` wide range/scoop perf probe across many direct root-prefix shelves.<br/>
    /// This command is intentionally separate from the guarded range perf command so experimental width/depth measurements do not blur the established small-shape baseline.<br/>
    /// The setup creates one shelf per consecutive root prefix, each with deterministic identities equal to encoded keys, then measures an inclusive range that crosses every created shelf.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the perf report is written.</returns>
    private static int RunScalar8Scalar8RangeScoopWidePerf(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-range-scoop-wide-perf.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int iterations = GetIntOption(args, "--iterations", 1000);
        int shelfCount = GetIntOption(args, "--shelf-count", 16);
        int itemsPerShelf = GetIntOption(args, "--items-per-shelf", 128);
        int startPrefix = GetIntOption(args, "--start-prefix", 32);
        int coalesceShelves = GetIntOption(args, "--coalesce-shelves", shelfCount);
        if (iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), iterations, "Wide range scoop perf iterations must be positive.");
        }

        if (shelfCount <= 0 || shelfCount > 64)
        {
            throw new ArgumentOutOfRangeException(nameof(args), shelfCount, "Wide range scoop shelf count must be between 1 and 64.");
        }

        if (itemsPerShelf <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), itemsPerShelf, "Wide range scoop items per shelf must be positive.");
        }

        if (startPrefix < 1 || startPrefix + shelfCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), startPrefix, "Wide range scoop start prefix plus shelf count must stay within one-byte root routing.");
        }

        if (coalesceShelves <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), coalesceShelves, "Wide range scoop coalesce shelf count must be positive.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        if (itemsPerShelf > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(args), itemsPerShelf, "Wide range scoop items per shelf exceeds the profiled shelf capacity.");
        }

        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(50), DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(2, "ss8rngwd", 0));
        ulong[] keys = new ulong[itemsPerShelf];
        ulong[] identities = new ulong[itemsPerShelf];
        for (int shelfIndex = 0; shelfIndex < shelfCount; shelfIndex++)
        {
            byte prefix = checked((byte)(startPrefix + shelfIndex));
            ulong prefixBase = (ulong)prefix << 56;
            for (int i = 0; i < itemsPerShelf; i++)
            {
                keys[i] = prefixBase + (ulong)i;
                identities[i] = keys[i];
            }

            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [prefix]);
        }

        int expectedCount = checked(shelfCount * itemsPerShelf);
        ulong lowerKey = (ulong)(byte)startPrefix << 56;
        ulong upperKey = ((ulong)(byte)(startPrefix + shelfCount - 1) << 56) + (ulong)(itemsPerShelf - 1);
        ulong[] output = new ulong[expectedCount];
        byte[] shelfBuffer = new byte[profile.ShelfExtentSize];
        byte[] coalesceBuffer = new byte[checked(profile.ShelfExtentSize * Math.Min(coalesceShelves, shelfCount))];

        Scalar8Scalar8RangeScoopPerfResult uncached = MeasureScalar8Scalar8RangeScoopScenario(
            "wide-root uncached",
            session,
            root.Offset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            expectedCount,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            output,
            shelfBuffer,
            validationKind: 3);

        Scalar8Scalar8RangeScoopPerfResult coalescedUncached = MeasureScalar8Scalar8RangeScoopCoalescedScenario(
            "wide-root coalesced uncached",
            session,
            root.Offset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            expectedCount,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            output,
            coalesceBuffer,
            validationKind: 3);

        Scalar8Scalar8RangeScoopPerfResult coalescedCached = MeasureScalar8Scalar8RangeScoopCoalescedScenario(
            "wide-root coalesced cached",
            session,
            root.Offset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            expectedCount,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            output,
            coalesceBuffer,
            validationKind: 3);

        Scalar8Scalar8RangeScoopPerfResult apiCoalescedCached = MeasureScalar8Scalar8RangeReadApiScenario(
            "wide-root api coalescing cached",
            session,
            root.Offset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            expectedCount,
            Scalar8Scalar8RangeReadOptions.CoalescingCached,
            output,
            shelfBuffer,
            coalesceBuffer,
            validationKind: 3);

        Scalar8Scalar8RangeReadOptions pooledOptions = Scalar8Scalar8RangeReadOptions.CoalescingCached with
        {
            CoalescedShelfScratchCount = Math.Min(coalesceShelves, shelfCount)
        };
        Scalar8Scalar8RangeScoopPerfResult pooledCoalescedCached = MeasureScalar8Scalar8RangeReadPooledScenario(
            "wide-root pooled coalescing cached",
            session,
            root.Offset,
            profile,
            lowerKey,
            upperKey,
            iterations,
            expectedCount,
            pooledOptions,
            output,
            validationKind: 3);

        Scalar8Scalar8RangeScoopPerfResult[] results = [uncached, coalescedUncached, coalescedCached, apiCoalescedCached, pooledCoalescedCached];
        Console.WriteLine("ss8-8 wide range scoop perf");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"shelfCount {shelfCount}");
        Console.WriteLine($"itemsPerShelf {itemsPerShelf}");
        Console.WriteLine($"coalesceShelves {Math.Min(coalesceShelves, shelfCount)}");
        PrintScalar8Scalar8RangeScoopPerf(results);
        string reportPath = WriteScalar8Scalar8RangeScoopPerfReport(artifactDirectory, iterations, expectedCount, results, "ss8-8-range-scoop-wide-perf", "SS8-8 Wide Range Scoop Perf");
        Console.WriteLine($"ss8-8 wide range scoop perf report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Runs a compact `SS8-8` checkpoint that normalizes current routed write and range-read behavior against raw `DataKernel` baselines.<br/>
    /// The report intentionally keeps raw-baseline percentages beside syscall and byte-shape metrics so design viability can be judged without mentally converting every table.<br/>
    /// Small mutation percentages are labeled as effective throughput only because they include routing, shelf mutation, and split work rather than pure sequential disk writes.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the normalized checkpoint report is written.</returns>
    private static int RunScalar8Scalar8NormalizedCheckpoint(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SS8-8NormalizedCheckpoint"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        string rangePath = GetOption(args, "--range-path", Path.Combine(@"T:\LibraDex", "ss8-8-normalized-range.lbdx"));
        int writeRuns = GetIntOption(args, "--write-runs", 30);
        int smallIterations = GetIntOption(args, "--small-iterations", 1000);
        int wideIterations = GetIntOption(args, "--wide-iterations", 500);
        int wideShelfCount = GetIntOption(args, "--wide-shelf-count", 16);
        int wideItemsPerShelf = GetIntOption(args, "--wide-items-per-shelf", 512);
        if (writeRuns <= 0 || smallIterations <= 0 || wideIterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Normalized checkpoint run counts must be positive.");
        }

        if (wideShelfCount <= 0 || wideShelfCount > 64)
        {
            throw new ArgumentOutOfRangeException(nameof(args), wideShelfCount, "Normalized checkpoint wide shelf count must be between 1 and 64.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(Path.GetDirectoryName(rangePath)!);
        Directory.CreateDirectory(artifactDirectory);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        if (wideItemsPerShelf <= 0 || wideItemsPerShelf > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(args), wideItemsPerShelf, "Normalized checkpoint wide items per shelf must fit the profiled shelf capacity.");
        }

        Scalar8Scalar8DesignPerfResult[] writeResults =
        [
            MeasureScalar8Scalar8DesignScenario("direct no-split", writeRuns, static (path, profile) => MeasureScalar8Scalar8DesignDirectNoSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("root-prefix split", writeRuns, static (path, profile) => MeasureScalar8Scalar8DesignRootPrefixSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("transform split", writeRuns, static (path, profile) => MeasureScalar8Scalar8DesignTransformSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("walked two-level no-split", writeRuns, static (path, profile) => MeasureScalar8Scalar8DesignWalkedTwoLevelNoSplit(path, profile), directory, profile),
            MeasureScalar8Scalar8DesignScenario("walked transform split", writeRuns, static (path, profile) => MeasureScalar8Scalar8DesignWalkedTransformSplit(path, profile), directory, profile)
        ];

        File.Delete(rangePath);
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(rangePath, options, CreateDesignPerfMetadata(51), DataKernelTelemetryOptions.EnabledOptions);
        RouterArenaReadCachePerfSetup setup = CreateScalar8Scalar8RouterArenaReadCachePerfSetup(session, profile);
        byte[] shelfBuffer = new byte[profile.ShelfExtentSize];
        const int sameRangeLength = 128;
        const int rangeStart = 32;
        const ulong rightPrefixBase = 0x0080_0000_0000_0000UL;
        ulong sameLowerKey = rightPrefixBase + rangeStart;
        ulong sameUpperKey = sameLowerKey + (ulong)(sameRangeLength - 1);
        ulong[] sameOutput = new ulong[sameRangeLength];
        Scalar8Scalar8RangeScoopPerfResult sameCached = MeasureScalar8Scalar8RangeScoopScenario(
            "same-shelf cached",
            session,
            setup.RootRouterOffset,
            profile,
            sameLowerKey,
            sameUpperKey,
            smallIterations,
            sameRangeLength,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            sameOutput,
            shelfBuffer,
            validationKind: 0);

        (RouterSnapshot wideRoot, _) = session.CreateRootRouterIndex(CreateHarnessSlot(3, "ss8normw", 0));
        ulong[] keys = new ulong[wideItemsPerShelf];
        ulong[] identities = new ulong[wideItemsPerShelf];
        const int startPrefix = 32;
        for (int shelfIndex = 0; shelfIndex < wideShelfCount; shelfIndex++)
        {
            byte prefix = checked((byte)(startPrefix + shelfIndex));
            ulong prefixBase = (ulong)prefix << 56;
            for (int i = 0; i < wideItemsPerShelf; i++)
            {
                keys[i] = prefixBase + (ulong)i;
                identities[i] = keys[i];
            }

            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(wideRoot.Offset, profile, keys, identities, [prefix]);
        }

        int wideRangeLength = checked(wideShelfCount * wideItemsPerShelf);
        ulong wideLowerKey = (ulong)(byte)startPrefix << 56;
        ulong wideUpperKey = ((ulong)(byte)(startPrefix + wideShelfCount - 1) << 56) + (ulong)(wideItemsPerShelf - 1);
        ulong[] wideOutput = new ulong[wideRangeLength];
        byte[] coalesceBuffer = new byte[checked(profile.ShelfExtentSize * wideShelfCount)];
        Scalar8Scalar8RangeScoopPerfResult wideUncached = MeasureScalar8Scalar8RangeScoopScenario(
            "wide-root uncached",
            session,
            wideRoot.Offset,
            profile,
            wideLowerKey,
            wideUpperKey,
            wideIterations,
            wideRangeLength,
            Scalar8Scalar8RouteReadPolicy.Uncached,
            wideOutput,
            shelfBuffer,
            validationKind: 3);

        Scalar8Scalar8RangeScoopPerfResult wideCoalesced = MeasureScalar8Scalar8RangeScoopCoalescedScenario(
            "wide-root coalesced cached",
            session,
            wideRoot.Offset,
            profile,
            wideLowerKey,
            wideUpperKey,
            wideIterations,
            wideRangeLength,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache,
            wideOutput,
            coalesceBuffer,
            validationKind: 3);

        Scalar8Scalar8RangeScoopPerfResult[] readResults = [sameCached, wideUncached, wideCoalesced];
        string reportPath = WriteScalar8Scalar8NormalizedCheckpointReport(artifactDirectory, writeRuns, smallIterations, wideIterations, profile, writeResults, readResults);
        Console.WriteLine("ss8-8 normalized checkpoint");
        Console.WriteLine($"writeRuns {writeRuns:N0}");
        Console.WriteLine($"smallIterations {smallIterations:N0}");
        Console.WriteLine($"wideIterations {wideIterations:N0}");
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Measures raw small positional `RandomAccess` read and write shapes that mirror current `SS8-8` routed operation sizes.<br/>
    /// The command pre-creates a rotating region file before timing so measured writes update existing offsets rather than measuring file creation or file extension.<br/>
    /// The resulting report is the fair small-I/O companion to the large sequential raw `DataKernel` baseline.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the small-I/O baseline report is written.</returns>
    private static int RunSmallIoBaseline(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "small-io-baseline.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int iterations = GetIntOption(args, "--iterations", 10000);
        int warmupIterations = GetIntOption(args, "--warmup-iterations", 1000);
        int regionCount = GetIntOption(args, "--regions", 1024);
        if (iterations <= 0 || warmupIterations < 0 || regionCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Small-I/O baseline iterations, warmup iterations, and regions must be valid positive values.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        SmallIoShape[] writeShapes =
        [
            new("write-32k-1call", [32768]),
            new("write-69632-1call", [69632]),
            new("write-69632-2call", [4096, 65536]),
            new("write-7078-30call", CreateEvenSegments(7078, 30)),
            new("write-16876-44call", CreateEvenSegments(16876, 44)),
            new("write-94042-44call", CreateEvenSegments(94042, 44))
        ];

        SmallIoShape[] readShapes =
        [
            new("read-36864-2call", [4096, 32768]),
            new("read-40968-5call", [4096, 4096, 4096, 4096, 24584]),
            new("read-69672-5call", [4096, 4096, 4096, 4096, 53288]),
            new("read-528448-33call", CreateEvenSegments(528448, 33)),
            new("read-532488-5call", [4096, 4096, 4096, 4096, 516104])
        ];

        int regionStride = GetMaxSmallIoShapeBytes(writeShapes, readShapes);
        PrepareSmallIoBaselineFile(path, regionStride, regionCount);
        byte[] buffer = CreatePattern(regionStride, 71);
        byte[] readBuffer = new byte[regionStride];
        SmallIoBaselineResult[] results = new SmallIoBaselineResult[writeShapes.Length + readShapes.Length];
        using Microsoft.Win32.SafeHandles.SafeFileHandle handle = File.OpenHandle(
            path,
            FileMode.Open,
            FileAccess.ReadWrite,
            FileShare.Read,
            FileOptions.RandomAccess);

        int resultIndex = 0;
        for (int i = 0; i < writeShapes.Length; i++)
        {
            results[resultIndex++] = MeasureSmallIoWriteShape(handle, writeShapes[i], buffer, iterations, warmupIterations, regionStride, regionCount);
        }

        for (int i = 0; i < readShapes.Length; i++)
        {
            results[resultIndex++] = MeasureSmallIoReadShape(handle, readShapes[i], readBuffer, iterations, warmupIterations, regionStride, regionCount);
        }

        string reportPath = WriteSmallIoBaselineReport(artifactDirectory, path, iterations, warmupIterations, regionCount, regionStride, results);
        Console.WriteLine("small I/O baseline");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"warmupIterations {warmupIterations:N0}");
        Console.WriteLine($"regions {regionCount:N0}");
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Compares raw `DataKernel` 16-byte item batches with `SS8-8` shelf batches using the same item count and commit cadence.<br/>
    /// This is the write-side parity benchmark for deciding whether the current shelf mutation path is reasonably close to raw generated-byte throughput.<br/>
    /// Each measured batch commits once, so the report shows item throughput, write amplification, and commit/write-call shape together.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the write-parity report is written.</returns>
    private static int RunScalar8Scalar8WriteParity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SS8-8WriteParity"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 1000);
        int warmupBatches = GetIntOption(args, "--warmup-batches", 50);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1800);
        if (batches <= 0 || warmupBatches < 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Write parity batches, warmup batches, and items per batch must be valid positive values.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        if (itemsPerBatch > profile.MaxItemCount)
        {
            throw new ArgumentOutOfRangeException(nameof(args), itemsPerBatch, "Write parity items per batch cannot exceed the profiled shelf capacity.");
        }

        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        int[] randomOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Random);
        DataKernelOptions options = new(
            AppendBufferSize: Math.Max(DefaultAppendBufferSize, profile.ShelfExtentSize),
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        Scalar8Scalar8WriteParityResult[] results =
        [
            MeasureDataKernelItemStreamWriteParity(Path.Combine(directory, "dk-16b-stream-sorted.lbdx"), "dk-16b-stream sorted", batches, warmupBatches, itemsPerBatch, sortedOrder, options),
            MeasureDataKernelItemStreamWriteParity(Path.Combine(directory, "dk-16b-stream-random.lbdx"), "dk-16b-stream random", batches, warmupBatches, itemsPerBatch, randomOrder, options),
