    /// <summary>
    /// Measures the routed public-wrapper `SS8-8` write path across the standard bulk-write cadence ladder.<br/>
    /// The ladder keeps total work near one million inserted items per row while varying commit size, so throughput, bytes/item, and writes/batch drift remain visible together.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed cadence-suite report is written.</returns>
    private static int RunScalar8Scalar8RoutedCadenceSuite(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SS8-8RoutedCadenceSuite"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int repeatCount = GetIntOption(args, "--repeat-count", 1);
        int commitGapCoalesceBytes = GetIntOption(args, "--commit-gap-coalesce-bytes", 512);
        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Routed cadence-suite prefix count must be between 1 and 256.");
        }

        if (repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), repeatCount, "Routed cadence-suite repeat count must be positive.");
        }

        if (commitGapCoalesceBytes < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), commitGapCoalesceBytes, "Routed cadence-suite commit gap coalescing bytes cannot be negative.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        DataKernelOptions options = CreateDesignPerfOptions(commitGapCoalesceBytes);
        Scalar8Scalar8RoutedCadenceDefinition[] cadences =
        [
            new("1000 x 1024", 1000, 50, 1024),
            new("10000 x 102", 10000, 200, 102),
            new("100000 x 10", 100000, 2000, 10)
        ];

        List<Scalar8Scalar8RoutedCadenceResult> rows = new(cadences.Length * 2);
        for (int i = 0; i < cadences.Length; i++)
        {
            Scalar8Scalar8RoutedCadenceDefinition cadence = cadences[i];
            int[] sortedOrder = CreateScalar8Scalar8OrderVector(cadence.ItemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
            int[] randomOrder = CreateScalar8Scalar8OrderVector(cadence.ItemsPerBatch, Scalar8Scalar8InsertOrder.Random);
            string cadenceDirectory = Path.Combine(directory, cadence.Name.Replace(' ', '-').Replace('x', 'X'));
            Directory.CreateDirectory(cadenceDirectory);
            rows.Add(new Scalar8Scalar8RoutedCadenceResult(
                cadence.Name,
                "sorted",
                cadence.WarmupBatches,
                MeasureRepeatedScalar8Scalar8RoutedBulkWrite(Path.Combine(cadenceDirectory, "ss8-8-routed-bulk-sorted.lbdx"), "public batch sorted", cadence.Batches, cadence.WarmupBatches, cadence.ItemsPerBatch, prefixCount, sortedOrder, options, repeatCount, profile)));
            rows.Add(new Scalar8Scalar8RoutedCadenceResult(
                cadence.Name,
                "random",
                cadence.WarmupBatches,
                MeasureRepeatedScalar8Scalar8RoutedBulkWrite(Path.Combine(cadenceDirectory, "ss8-8-routed-bulk-random.lbdx"), "public batch random", cadence.Batches, cadence.WarmupBatches, cadence.ItemsPerBatch, prefixCount, randomOrder, options, repeatCount, profile)));
        }

        string reportPath = WriteScalar8Scalar8RoutedCadenceSuiteReport(artifactDirectory, prefixCount, profile, repeatCount, commitGapCoalesceBytes, rows);
        Console.WriteLine("ss8-8 routed cadence suite");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine($"commitGapCoalesceBytes {commitGapCoalesceBytes:N0}");
        PrintScalar8Scalar8RoutedCadenceSuiteResults(rows);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

