    /// <summary>
    /// Measures a SQLite B-tree comparison workload shaped to match the current public `SS8-8` bulk-write and bulk-read probes.<br/>
    /// SQLite receives the same generated scalar keys, the same sorted/random insertion-order rows, and one SQL transaction per logical LibraDex batch.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the SQLite comparison report is written.</returns>
    private static int RunSqliteScalar8Scalar8Comparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SQLiteSS8-8Comparison"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
