                MeasureRepeatedSqliteScalar8Scalar16BlobWrite(Path.Combine(directory, "sqlite-ss8-16-random.db"), "sqlite ss8-16 random", batches, warmupBatches, itemsPerBatch, prefixCount, randomOrder, sqliteOptions, repeatCount),
