    /// <summary>
    /// Measures `FS32-8` routed range-read throughput against a matching SQLite `BLOB(32)`/integer primary-key table.<br/>
    /// The LibraDex row uses the same fixed-key data generator as the all-shape write-parity command, then scans prefix-shaped ranges over the persisted routed tree.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the read-parity report is written.</returns>
    private static int RunFixed32Scalar8ReadParity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "FS32-8ReadParity"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int iterations = GetIntOption(args, "--iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        int commitGapCoalesceBytes = GetIntOption(args, "--wide-commit-gap-coalesce-bytes", 16 * 1024);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (batches <= 0 || itemsPerBatch <= 0 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "FS32-8 read-parity batches, items per batch, iterations, and repeat count must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "FS32-8 read-parity prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        string libraPath = Path.Combine(directory, "fs32-8-read.lbdx");
        File.Delete(libraPath);
        Fixed32Scalar8Profile profile = Fixed32Scalar8Profile.Default64KiB;
        DataKernelOptions libraOptions = CreateDesignPerfOptions(commitGapCoalesceBytes);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        long rootOffset;
        using (LibraDexFileSession created = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(3281), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = created.CreateRootRouterIndex(CreateHarnessSlot(0, "f328read", 0));
            rootOffset = root.Offset;
            _ = RunFixed32Scalar8RoutedBulkWriteLoop(created, rootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, profile, includeAttribution: false);
        }

        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        Fixed32Scalar8ReadParityResult[] libraResults = new Fixed32Scalar8ReadParityResult[5];
        using (LibraDexFileSession opened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraResults[0] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            libraResults[1] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            libraResults[2] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            libraResults[3] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            libraResults[4] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        string sqlitePath = Path.Combine(directory, "sqlite-fs32-8-read.db");
        ResetSqliteScalar8Scalar8Files(sqlitePath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteFixed32Scalar8BlobSchema(connection);
            RunSqliteFixed32Scalar8BlobWriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        SqliteScalar8Scalar8ReadResult[] sqliteResults = new SqliteScalar8Scalar8ReadResult[5];
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteResults[0] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            sqliteResults[1] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            sqliteResults[2] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            sqliteResults[3] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            sqliteResults[4] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        string reportPath = WriteFixed32Scalar8ReadParityReport(
            artifactDirectory,
            batches,
            itemsPerBatch,
            prefixCount,
            iterations,
            repeatCount,
            commitGapCoalesceBytes,
            sqliteOptions,
            libraResults,
            sqliteResults);

        Console.WriteLine("fs32-8 read parity");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        PrintFixed32Scalar8ReadParityResults(libraResults, sqliteResults);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Sweeps `FS32-8` shelf sizes across routed bulk-write and routed range-read workloads.<br/>
    /// The command prioritizes logical read/write throughput while keeping bytes/item and per-range read bytes visible as secondary compactness and I/O diagnostics.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the size sweep report is written.</returns>
    private static int RunFixed32Scalar8SizeSweep(string[] args)
    {
        int[] shelfSizes = ParseIntList(GetOption(args, "--shelf-sizes", "32768,40960,49152,57344,65536"));
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "FS32-8SizeSweep"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int warmupBatches = GetIntOption(args, "--warmup-batches", 5);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int readIterations = GetIntOption(args, "--read-iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        int commitGapCoalesceBytes = GetIntOption(args, "--commit-gap-coalesce-bytes", 16 * 1024);
        if (shelfSizes.Length == 0 || batches <= 0 || warmupBatches < 0 || itemsPerBatch <= 0 || prefixCount <= 0 || prefixCount > 256 || readIterations <= 0 || repeatCount <= 0 || commitGapCoalesceBytes < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "FS32-8 size-sweep requires shelf sizes, positive write/read settings, prefix count 1-256, and non-negative coalescing bytes.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        int[] randomOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Random);
        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        DataKernelOptions options = CreateDesignPerfOptions(commitGapCoalesceBytes);
        Fixed32Scalar8SizeSweepRow[] rows = new Fixed32Scalar8SizeSweepRow[shelfSizes.Length];

        for (int i = 0; i < shelfSizes.Length; i++)
        {
            Fixed32Scalar8Profile profile = Fixed32Scalar8Profile.Create(shelfSizes[i]);
            string profileDirectory = Path.Combine(directory, profile.ShelfExtentSize.ToString(CultureInfo.InvariantCulture));
            Directory.CreateDirectory(profileDirectory);
            Scalar8Scalar8RoutedBulkWriteResult sortedWrite = MeasureRepeatedFixed32Scalar8RoutedBulkWrite(
                Path.Combine(profileDirectory, "fs32-8-sorted.lbdx"),
                "fs32 sorted",
                batches,
                warmupBatches,
                itemsPerBatch,
                prefixCount,
                sortedOrder,
                options,
                repeatCount,
                profile,
                includeAttribution: false);
            Scalar8Scalar8RoutedBulkWriteResult randomWrite = MeasureRepeatedFixed32Scalar8RoutedBulkWrite(
                Path.Combine(profileDirectory, "fs32-8-random.lbdx"),
                "fs32 random",
                batches,
                warmupBatches,
                itemsPerBatch,
                prefixCount,
                randomOrder,
                options,
                repeatCount,
                profile,
                includeAttribution: false);

            string readPath = Path.Combine(profileDirectory, "fs32-8-read.lbdx");
            File.Delete(readPath);
            long rootOffset;
            using (LibraDexFileSession created = LibraDexFileSession.Initialize(readPath, options, CreateDesignPerfMetadata(3282), DataKernelTelemetryOptions.EnabledOptions))
            {
                (RouterSnapshot root, _) = created.CreateRootRouterIndex(CreateHarnessSlot(0, "f328swp", 0));
                rootOffset = root.Offset;
                _ = RunFixed32Scalar8RoutedBulkWriteLoop(created, rootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, profile, includeAttribution: false);
            }

            Fixed32Scalar8ReadParityResult prefix0Read;
            Fixed32Scalar8ReadParityResult prefixSpanRead;
            using (LibraDexFileSession opened = LibraDexFileSession.Open(readPath, options, DataKernelTelemetryOptions.EnabledOptions))
            {
                prefix0Read = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, readIterations, identities, repeatCount);
                prefixSpanRead = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, readIterations, identities, repeatCount);
            }

            rows[i] = new Fixed32Scalar8SizeSweepRow(profile, sortedWrite, randomWrite, prefix0Read, prefixSpanRead);
        }

        string reportPath = WriteFixed32Scalar8SizeSweepReport(
            artifactDirectory,
            batches,
            warmupBatches,
            itemsPerBatch,
            prefixCount,
            readIterations,
            repeatCount,
            commitGapCoalesceBytes,
            rows);

        Console.WriteLine("fs32-8 size sweep");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"warmupBatches {warmupBatches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"readIterations {readIterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        PrintFixed32Scalar8SizeSweepRows(rows);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Validates that one LibraDex file can host multiple routed indexes over the same logical identity set without slot, router, or shelf interference.<br/>
    /// The first slice creates an `SS8-8` index and an `SS16-8` index in separate directory slots, writes the same 8-byte identities through different key projections, reopens the file, and verifies both route graphs independently.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the multi-index same-identities sanity report is written.</returns>
    private static int RunMultiIndexSameIdentitiesSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "multi-index-same-identities-sanity.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 8);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 256);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int commitGapCoalesceBytes = GetIntOption(args, "--commit-gap-coalesce-bytes", 16 * 1024);
        int scalar8Scalar8SlotIndex = GetIntOption(args, "--ss8-8-slot", 0);
        int scalar16Scalar8SlotIndex = GetIntOption(args, "--ss16-8-slot", 1);
        if (batches <= 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Multi-index same-identities batches and items per batch must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Multi-index same-identities prefix count must be between 1 and 256.");
        }

        if (scalar8Scalar8SlotIndex == scalar16Scalar8SlotIndex)
        {
            throw new ArgumentException("Multi-index same-identities sanity requires distinct index-directory slots.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions(commitGapCoalesceBytes);
        Scalar8Scalar8Profile scalar8Scalar8Profile = Scalar8Scalar8Profile.Default32KiB;
        Scalar16Scalar8Profile scalar16Scalar8Profile = Scalar16Scalar8Profile.Default32KiB;
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);

        MultiIndexSameIdentitiesResult result;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(218), DataKernelTelemetryOptions.EnabledOptions))
        {
            (Scalar8Scalar8IndexHandle scalar8Scalar8Handle, RouterSnapshot scalar8Scalar8Root, DataKernelCommitTelemetry scalar8Scalar8RootCommit) = session.CreateScalar8Scalar8RootRouterIndex(CreateHarnessSlot(scalar8Scalar8SlotIndex, "ss88same", 0));
            (RouterSnapshot scalar16Scalar8Root, DataKernelCommitTelemetry scalar16Scalar8RootCommit) = session.CreateRootRouterIndex(CreateHarnessSlot(scalar16Scalar8SlotIndex, "s168same", 0));
            if (scalar8Scalar8Root.Offset == scalar16Scalar8Root.Offset)
            {
                throw new InvalidDataException("Multi-index same-identities sanity created duplicate root-router offsets.");
            }

            using Scalar8Scalar8Index scalar8Scalar8Index = new(session, scalar8Scalar8Handle, scalar8Scalar8SlotIndex, "ss88same", ownsSession: false);
            RoutedBulkWriteLoopTelemetry scalar8Scalar8Telemetry = RunScalar8Scalar8RoutedBulkWriteLoopBatchMajor(
                scalar8Scalar8Index,
                batches,
                itemsPerBatch,
                prefixCount,
                sortedOrder,
                batchOffset: 0);
            RoutedBulkWriteLoopTelemetry scalar16Scalar8Telemetry = RunScalar16Scalar8RoutedBulkWriteLoop(
                session,
                scalar16Scalar8Root.Offset,
                batches,
                itemsPerBatch,
                prefixCount,
                sortedOrder,
                batchOffset: 0,
                scalar16Scalar8Profile,
                includeAttribution: false);

            long expectedIdentityChecksum = CalculateSameIdentityChecksum(batches, itemsPerBatch, prefixCount, sortedOrder);
            long finalLength = new FileInfo(path).Length;
            result = new MultiIndexSameIdentitiesResult(
                scalar8Scalar8SlotIndex,
                scalar16Scalar8SlotIndex,
                scalar8Scalar8Root.Offset,
                scalar16Scalar8Root.Offset,
                scalar8Scalar8RootCommit.WriteCallCount + scalar16Scalar8RootCommit.WriteCallCount,
                scalar8Scalar8RootCommit.BytesWritten + scalar16Scalar8RootCommit.BytesWritten,
                scalar8Scalar8Telemetry.CommitCount,
                scalar16Scalar8Telemetry.CommitCount,
                scalar8Scalar8Telemetry.WriteCallCount,
                scalar16Scalar8Telemetry.WriteCallCount,
                scalar8Scalar8Telemetry.BytesWritten,
                scalar16Scalar8Telemetry.BytesWritten,
                scalar8Scalar8Telemetry.SetLengthCallCount + scalar16Scalar8Telemetry.SetLengthCallCount,
                expectedIdentityChecksum,
                finalLength,
                0,
                0,
                0,
                0);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateMultiIndexDirectory(reopened, scalar8Scalar8SlotIndex, scalar16Scalar8SlotIndex, result.Scalar8Scalar8RootOffset, result.Scalar16Scalar8RootOffset);
            MultiIndexValidationCounts validation = ValidateMultiIndexSameIdentitiesReopen(
                reopened,
                result.Scalar8Scalar8RootOffset,
                result.Scalar16Scalar8RootOffset,
                scalar8Scalar8Profile,
                scalar16Scalar8Profile,
                batches,
                itemsPerBatch,
                prefixCount,
                sortedOrder);
            result = result with
            {
                Scalar8Scalar8DistinctShelves = validation.Scalar8Scalar8DistinctShelves,
                Scalar16Scalar8DistinctShelves = validation.Scalar16Scalar8DistinctShelves,
                Scalar8Scalar8ValidatedItems = validation.Scalar8Scalar8ValidatedItems,
                Scalar16Scalar8ValidatedItems = validation.Scalar16Scalar8ValidatedItems
            };
        }

        string reportPath = WriteMultiIndexSameIdentitiesSanityReport(artifactDirectory, path, batches, itemsPerBatch, prefixCount, commitGapCoalesceBytes, result);
        PrintMultiIndexSameIdentitiesSanityResult(result);
        Console.WriteLine($"multi-index same-identities sanity ok path={Path.GetFullPath(path)}");
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Validates that reopened index-directory slots still point at the expected independent root routers.<br/>
    /// This catches the core multi-index failure mode where a later slot rewrite accidentally drops or aliases an earlier index root.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="scalar8Scalar8SlotIndex">The expected `SS8-8` slot index.</param>
    /// <param name="scalar16Scalar8SlotIndex">The expected `SS16-8` slot index.</param>
    /// <param name="scalar8Scalar8RootOffset">The expected `SS8-8` root-router offset.</param>
    /// <param name="scalar16Scalar8RootOffset">The expected `SS16-8` root-router offset.</param>
    private static void ValidateMultiIndexDirectory(
        LibraDexFileSession session,
        int scalar8Scalar8SlotIndex,
        int scalar16Scalar8SlotIndex,
        long scalar8Scalar8RootOffset,
        long scalar16Scalar8RootOffset)
    {
        bool foundScalar8Scalar8 = false;
        bool foundScalar16Scalar8 = false;
        ReadOnlySpan<IndexDirectorySlotSnapshot> slots = session.IndexDirectory.ActiveSlots;
        for (int i = 0; i < slots.Length; i++)
        {
            IndexDirectorySlotSnapshot slot = slots[i];
            if (slot.SlotIndex == scalar8Scalar8SlotIndex)
            {
                foundScalar8Scalar8 = slot.RootRouterOffset == scalar8Scalar8RootOffset;
            }

            if (slot.SlotIndex == scalar16Scalar8SlotIndex)
            {
                foundScalar16Scalar8 = slot.RootRouterOffset == scalar16Scalar8RootOffset;
            }
        }

        if (!foundScalar8Scalar8 || !foundScalar16Scalar8)
        {
            throw new InvalidDataException("Multi-index same-identities sanity did not reopen both expected index-directory slots with their original root-router offsets.");
        }

        if (scalar8Scalar8RootOffset == scalar16Scalar8RootOffset)
        {
            throw new InvalidDataException("Multi-index same-identities sanity reopened aliased root-router offsets.");
        }
    }

    /// <summary>
    /// Reopens and validates both indexes by walking every generated key to the expected shape-local shelf and checking that the shared identity is present.<br/>
    /// The validation deliberately reads each shape through its own route walker so a wrong root, wrong shelf magic, or missing tuple fails independently.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="scalar8Scalar8RootOffset">The `SS8-8` root-router offset.</param>
    /// <param name="scalar16Scalar8RootOffset">The `SS16-8` root-router offset.</param>
    /// <param name="scalar8Scalar8Profile">The `SS8-8` shelf profile.</param>
    /// <param name="scalar16Scalar8Profile">The `SS16-8` shelf profile.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The reopen validation counts.</returns>
    private static MultiIndexValidationCounts ValidateMultiIndexSameIdentitiesReopen(
        LibraDexFileSession session,
        long scalar8Scalar8RootOffset,
        long scalar16Scalar8RootOffset,
        Scalar8Scalar8Profile scalar8Scalar8Profile,
        Scalar16Scalar8Profile scalar16Scalar8Profile,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order)
    {
        Dictionary<long, byte[]> scalar8Scalar8ShelfCache = [];
        Dictionary<long, byte[]> scalar16Scalar8ShelfCache = [];
        int validatedScalar8Scalar8 = 0;
        int validatedScalar16Scalar8 = 0;
        for (int batch = 0; batch < batches; batch++)
        {
            for (int i = 0; i < itemsPerBatch; i++)
            {
                ulong identity = CreateRoutedBulkWriteKey(batch, order[i], itemsPerBatch, prefixCount);
                ValidateMultiIndexScalar8Scalar8Tuple(session, scalar8Scalar8RootOffset, scalar8Scalar8Profile, scalar8Scalar8ShelfCache, identity);
                ValidateMultiIndexScalar16Scalar8Tuple(session, scalar16Scalar8RootOffset, scalar16Scalar8Profile, scalar16Scalar8ShelfCache, identity);
                validatedScalar8Scalar8++;
                validatedScalar16Scalar8++;
            }
        }

        return new MultiIndexValidationCounts(
            scalar8Scalar8ShelfCache.Count,
            scalar16Scalar8ShelfCache.Count,
            validatedScalar8Scalar8,
            validatedScalar16Scalar8);
    }

    /// <summary>
    /// Validates one generated identity in the reopened `SS8-8` index.<br/>
    /// The key projection for this anchor index is identity-as-key, so the same encoded scalar must be present as both tuple key and tuple identity.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="rootRouterOffset">The `SS8-8` root-router offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <param name="shelfCache">The validation shelf byte cache keyed by shelf file offset.</param>
    /// <param name="identity">The generated shared identity value.</param>
    private static void ValidateMultiIndexScalar8Scalar8Tuple(
        LibraDexFileSession session,
        long rootRouterOffset,
        Scalar8Scalar8Profile profile,
        Dictionary<long, byte[]> shelfCache,
        ulong identity)
    {
        Scalar8Scalar8RoutePathTarget pathTarget = session.WalkScalar8Scalar8RoutePathTarget(
            rootRouterOffset,
            identity,
            maxRouterHops: 8,
            Scalar8Scalar8RouteReadPolicy.PreferArenaCache);
        if (pathTarget.Target.Kind != Scalar8Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("Multi-index same-identities SS8-8 route did not terminate at an SS8-8 shelf.");
        }

        if (!shelfCache.TryGetValue(pathTarget.Target.Offset, out byte[]? shelfBytes))
        {
            shelfBytes = session.ReadScalar8Scalar8ShelfBytesForBatch(pathTarget.Target.Offset, profile);
            shelfCache[pathTarget.Target.Offset] = shelfBytes;
        }

        Scalar8Scalar8ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid || !shelf.Contains(identity, identity))
        {
            throw new InvalidDataException("Multi-index same-identities SS8-8 validation could not find the expected identity tuple.");
        }
    }

    /// <summary>
    /// Validates one generated identity in the reopened `SS16-8` index.<br/>
    /// The widened key projection derives a deterministic low key half from the shared identity while preserving the same 8-byte identity payload.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="rootRouterOffset">The `SS16-8` root-router offset.</param>
    /// <param name="profile">The `SS16-8` shelf profile.</param>
    /// <param name="shelfCache">The validation shelf byte cache keyed by shelf file offset.</param>
    /// <param name="identity">The generated shared identity value.</param>
    private static void ValidateMultiIndexScalar16Scalar8Tuple(
        LibraDexFileSession session,
        long rootRouterOffset,
        Scalar16Scalar8Profile profile,
        Dictionary<long, byte[]> shelfCache,
        ulong identity)
    {
        ulong keyLow = CreateSqliteScalar16Scalar16LowHalf(identity);
        Scalar16Scalar8RoutePathTarget pathTarget = session.WalkScalar16Scalar8RoutePathTarget(
            rootRouterOffset,
            identity,
            keyLow,
            maxRouterHops: 8);
        if (pathTarget.Target.Kind != Scalar16Scalar8RouteTargetKind.Shelf)
        {
            throw new InvalidDataException("Multi-index same-identities SS16-8 route did not terminate at an SS16-8 shelf.");
        }

        if (!shelfCache.TryGetValue(pathTarget.Target.Offset, out byte[]? shelfBytes))
        {
            shelfBytes = session.ReadScalar16Scalar8ShelfBytesForBatch(pathTarget.Target.Offset, profile);
            shelfCache[pathTarget.Target.Offset] = shelfBytes;
        }

        Scalar16Scalar8ReadOnly shelf = new(shelfBytes, profile);
        if (!shelf.IsValid || !shelf.Contains(identity, keyLow, identity))
        {
            throw new InvalidDataException("Multi-index same-identities SS16-8 validation could not find the expected identity tuple.");
        }
    }

    /// <summary>
    /// Calculates a deterministic checksum over the shared generated identity set.<br/>
    /// The checksum is intentionally independent of key projection so both indexes can be understood as covering the same logical identities.<br/>
    /// </summary>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The generated identity checksum.</returns>
    private static long CalculateSameIdentityChecksum(int batches, int itemsPerBatch, int prefixCount, int[] order)
    {
        long checksum = 0;
        for (int batch = 0; batch < batches; batch++)
        {
            for (int i = 0; i < itemsPerBatch; i++)
            {
                ulong identity = CreateRoutedBulkWriteKey(batch, order[i], itemsPerBatch, prefixCount);
                checksum += unchecked((long)((identity >> 32) ^ identity ^ (ulong)(i + 1)));
            }
        }

        return checksum;
    }

    /// <summary>
    /// Validates eight same-file indexes over the same generated identity set using two independent instances of each current physical shape.<br/>
    /// Creation, write, and reopen-validation orders are intentionally different from slot order so the test exercises index-directory slot replacement and root-router independence instead of sequential happy-path assumptions.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the eight-index same-identities sanity report is written.</returns>
    private static int RunMultiIndexEightSameIdentitiesSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "multi-index-same-identities-sanity.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 8);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 256);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int commitGapCoalesceBytes = GetIntOption(args, "--commit-gap-coalesce-bytes", 16 * 1024);
        if (batches <= 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Eight-index same-identities batches and items per batch must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Eight-index same-identities prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions(commitGapCoalesceBytes);
        Scalar8Scalar8Profile scalar8Scalar8Profile = Scalar8Scalar8Profile.Default32KiB;
        Scalar16Scalar8Profile scalar16Scalar8Profile = Scalar16Scalar8Profile.Default32KiB;
        Scalar8Scalar16Profile scalar8Scalar16Profile = Scalar8Scalar16Profile.Default32KiB;
        Scalar16Scalar16Profile scalar16Scalar16Profile = Scalar16Scalar16Profile.Default32KiB;
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        MultiIndexSameIdentitiesPlan[] plans = CreateEightIndexSameIdentitiesPlans();
        long rootCreateWrites = 0;
        long rootCreateBytes = 0;

        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(821), DataKernelTelemetryOptions.EnabledOptions))
        {
            int[] createOrder = [3, 0, 6, 1, 4, 7, 2, 5];
            for (int i = 0; i < createOrder.Length; i++)
            {
                MultiIndexSameIdentitiesPlan plan = plans[createOrder[i]];
                DataKernelCommitTelemetry rootCommit;
                if (plan.Shape == MultiIndexSameIdentitiesShape.SS88)
                {
                    (Scalar8Scalar8IndexHandle handle, RouterSnapshot root, DataKernelCommitTelemetry commit) = session.CreateScalar8Scalar8RootRouterIndex(CreateHarnessSlot(plan.SlotIndex, plan.Name, 0));
                    plan.Scalar8Scalar8Handle = handle;
                    plan.RootOffset = root.Offset;
                    rootCommit = commit;
                }
                else
                {
                    (RouterSnapshot root, DataKernelCommitTelemetry commit) = session.CreateRootRouterIndex(CreateHarnessSlot(plan.SlotIndex, plan.Name, 0));
                    plan.RootOffset = root.Offset;
                    rootCommit = commit;
                }

                rootCreateWrites += rootCommit.WriteCallCount;
                rootCreateBytes += rootCommit.BytesWritten;
            }

            ValidateDistinctEightIndexRoots(plans);

            int[] writeOrder = [6, 0, 3, 5, 1, 7, 4, 2];
            for (int i = 0; i < writeOrder.Length; i++)
            {
                MultiIndexSameIdentitiesPlan plan = plans[writeOrder[i]];
                plan.Telemetry = plan.Shape switch
                {
                    MultiIndexSameIdentitiesShape.SS88 => RunMultiIndexScalar8Scalar8Write(session, plan, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS168 => RunScalar16Scalar8RoutedBulkWriteLoop(session, plan.RootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, scalar16Scalar8Profile, includeAttribution: false),
                    MultiIndexSameIdentitiesShape.SS816 => RunScalar8Scalar16RoutedBulkWriteLoop(session, plan.RootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, scalar8Scalar16Profile, includeAttribution: false),
                    MultiIndexSameIdentitiesShape.SS1616 => RunScalar16Scalar16RoutedBulkWriteLoop(session, plan.RootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, scalar16Scalar16Profile, includeAttribution: false),
                    _ => throw new InvalidDataException($"Unsupported eight-index shape {plan.Shape}.")
                };
            }
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateEightIndexDirectory(reopened, plans);
            int[] validateOrder = [5, 2, 7, 4, 1, 6, 0, 3];
            for (int i = 0; i < validateOrder.Length; i++)
            {
                MultiIndexSameIdentitiesPlan plan = plans[validateOrder[i]];
                MultiIndexValidationCounts validation = plan.Shape switch
                {
                    MultiIndexSameIdentitiesShape.SS88 => ValidateEightIndexScalar8Scalar8Reopen(reopened, plan.RootOffset, scalar8Scalar8Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS168 => ValidateEightIndexScalar16Scalar8Reopen(reopened, plan.RootOffset, scalar16Scalar8Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS816 => ValidateEightIndexScalar8Scalar16Reopen(reopened, plan.RootOffset, scalar8Scalar16Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS1616 => ValidateEightIndexScalar16Scalar16Reopen(reopened, plan.RootOffset, scalar16Scalar16Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    _ => throw new InvalidDataException($"Unsupported eight-index validation shape {plan.Shape}.")
                };
                plan.ValidatedItems = validation.Scalar8Scalar8ValidatedItems;
                plan.DistinctShelves = validation.Scalar8Scalar8DistinctShelves;
            }
        }

        long identityChecksum = CalculateSameIdentityChecksum(batches, itemsPerBatch, prefixCount, sortedOrder);
        long finalLength = new FileInfo(path).Length;
        string reportPath = WriteMultiIndexEightSameIdentitiesSanityReport(
            artifactDirectory,
            path,
            batches,
            itemsPerBatch,
            prefixCount,
            commitGapCoalesceBytes,
            rootCreateWrites,
            rootCreateBytes,
            identityChecksum,
            finalLength,
            plans);
        PrintMultiIndexEightSameIdentitiesSanityResult(rootCreateWrites, rootCreateBytes, identityChecksum, finalLength, plans);
        Console.WriteLine($"multi-index same-identities sanity ok path={Path.GetFullPath(path)}");
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Creates the fixed eight-index same-identities validation plan.<br/>
    /// Slot order is stable for easy inspection, while callers use separate create/write/validate order arrays to exercise non-sequential behavior.<br/>
    /// </summary>
    /// <returns>The eight planned indexes.</returns>
    private static MultiIndexSameIdentitiesPlan[] CreateEightIndexSameIdentitiesPlans()
    {
        return
        [
            new(0, "ss88a", MultiIndexSameIdentitiesShape.SS88, 8),
            new(1, "s168a", MultiIndexSameIdentitiesShape.SS168, 8),
            new(2, "s816a", MultiIndexSameIdentitiesShape.SS816, 16),
            new(3, "s1616a", MultiIndexSameIdentitiesShape.SS1616, 16),
            new(4, "ss88b", MultiIndexSameIdentitiesShape.SS88, 8),
            new(5, "s168b", MultiIndexSameIdentitiesShape.SS168, 8),
            new(6, "s816b", MultiIndexSameIdentitiesShape.SS816, 16),
            new(7, "s1616b", MultiIndexSameIdentitiesShape.SS1616, 16)
        ];
    }

    /// <summary>
    /// Executes `SS8-8` routed bulk writes against one already-created same-file plan root.<br/>
    /// This wraps the internal index handle with the existing public batch object without taking ownership of the shared session.<br/>
    /// </summary>
    /// <param name="session">The shared LibraDex file session.</param>
    /// <param name="plan">The `SS8-8` plan with an initialized handle.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The routed write telemetry.</returns>
    private static RoutedBulkWriteLoopTelemetry RunMultiIndexScalar8Scalar8Write(
        LibraDexFileSession session,
        MultiIndexSameIdentitiesPlan plan,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order)
    {
        using Scalar8Scalar8Index index = new(session, plan.Scalar8Scalar8Handle, plan.SlotIndex, plan.Name, ownsSession: false);
        return RunScalar8Scalar8RoutedBulkWriteLoopBatchMajor(index, batches, itemsPerBatch, prefixCount, order, batchOffset: 0);
    }

    /// <summary>
    /// Validates all planned roots are non-zero and distinct.<br/>
    /// Root aliasing would mean separate slots are not actually independent index graphs.<br/>
    /// </summary>
    /// <param name="plans">The planned indexes.</param>
    private static void ValidateDistinctEightIndexRoots(ReadOnlySpan<MultiIndexSameIdentitiesPlan> plans)
    {
        HashSet<long> roots = [];
        for (int i = 0; i < plans.Length; i++)
        {
            if (plans[i].RootOffset == 0 || !roots.Add(plans[i].RootOffset))
            {
                throw new InvalidDataException("Eight-index same-identities sanity created a missing or duplicate root-router offset.");
            }
        }
    }

    /// <summary>
    /// Validates that every planned slot survived reopen with its expected root offset.<br/>
    /// The directory check is independent of route walking so slot publication errors fail with a direct message.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="plans">The planned indexes.</param>
    private static void ValidateEightIndexDirectory(LibraDexFileSession session, ReadOnlySpan<MultiIndexSameIdentitiesPlan> plans)
    {
        for (int planIndex = 0; planIndex < plans.Length; planIndex++)
        {
            bool found = false;
            ReadOnlySpan<IndexDirectorySlotSnapshot> slots = session.IndexDirectory.ActiveSlots;
            for (int slotIndex = 0; slotIndex < slots.Length; slotIndex++)
            {
                IndexDirectorySlotSnapshot slot = slots[slotIndex];
                if (slot.SlotIndex == plans[planIndex].SlotIndex && slot.RootRouterOffset == plans[planIndex].RootOffset)
                {
                    found = true;
                    break;
                }
            }

            if (!found)
            {
                throw new InvalidDataException($"Eight-index same-identities sanity did not reopen slot {plans[planIndex].SlotIndex} with its expected root-router offset.");
            }
        }
    }

    /// <summary>
    /// Validates one reopened `SS8-8` plan by routing every generated identity to an `SS8-8` shelf and checking tuple presence.<br/>
    /// The returned counts use the generic validation-count record's first fields so the report path can stay shape-agnostic.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="rootOffset">The plan root-router offset.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The validation counts.</returns>
    private static MultiIndexValidationCounts ValidateEightIndexScalar8Scalar8Reopen(
        LibraDexFileSession session,
        long rootOffset,
        Scalar8Scalar8Profile profile,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order)
    {
        Dictionary<long, byte[]> cache = [];
        int validated = 0;
        for (int batch = 0; batch < batches; batch++)
        {
            for (int i = 0; i < itemsPerBatch; i++)
            {
                ulong identity = CreateRoutedBulkWriteKey(batch, order[i], itemsPerBatch, prefixCount);
                ValidateMultiIndexScalar8Scalar8Tuple(session, rootOffset, profile, cache, identity);
                validated++;
            }
        }

        return new MultiIndexValidationCounts(cache.Count, 0, validated, 0);
    }

    /// <summary>
    /// Validates one reopened `SS16-8` plan by routing every generated identity to an `SS16-8` shelf and checking tuple presence.<br/>
    /// The widened key low half follows the same deterministic projection used by the routed write loop.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="rootOffset">The plan root-router offset.</param>
    /// <param name="profile">The `SS16-8` shelf profile.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The validation counts.</returns>
    private static MultiIndexValidationCounts ValidateEightIndexScalar16Scalar8Reopen(
        LibraDexFileSession session,
        long rootOffset,
        Scalar16Scalar8Profile profile,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order)
    {
        Dictionary<long, byte[]> cache = [];
        int validated = 0;
        for (int batch = 0; batch < batches; batch++)
        {
            for (int i = 0; i < itemsPerBatch; i++)
            {
                ulong identity = CreateRoutedBulkWriteKey(batch, order[i], itemsPerBatch, prefixCount);
                ValidateMultiIndexScalar16Scalar8Tuple(session, rootOffset, profile, cache, identity);
                validated++;
            }
        }

        return new MultiIndexValidationCounts(cache.Count, 0, validated, 0);
    }

    /// <summary>
    /// Validates one reopened `SS8-16` plan by routing every generated key to an `SS8-16` shelf and checking the 16-byte identity tuple.<br/>
    /// Key high is the generated 8-byte identity and identity low is the deterministic widened half used by the write loop.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="rootOffset">The plan root-router offset.</param>
    /// <param name="profile">The `SS8-16` shelf profile.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The validation counts.</returns>
    private static MultiIndexValidationCounts ValidateEightIndexScalar8Scalar16Reopen(
        LibraDexFileSession session,
        long rootOffset,
        Scalar8Scalar16Profile profile,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order)
    {
        Dictionary<long, byte[]> cache = [];
        int validated = 0;
        for (int batch = 0; batch < batches; batch++)
        {
            for (int i = 0; i < itemsPerBatch; i++)
            {
                ulong key = CreateRoutedBulkWriteKey(batch, order[i], itemsPerBatch, prefixCount);
                ulong identityLow = CreateSqliteScalar16Scalar16LowHalf(key);
                Scalar8Scalar16RoutePathTarget pathTarget = session.WalkScalar8Scalar16RoutePathTarget(rootOffset, key, maxRouterHops: 8);
                if (pathTarget.Target.Kind != Scalar8Scalar16RouteTargetKind.Shelf)
                {
                    throw new InvalidDataException("Eight-index same-identities SS8-16 route did not terminate at an SS8-16 shelf.");
                }

                if (!cache.TryGetValue(pathTarget.Target.Offset, out byte[]? shelfBytes))
                {
                    shelfBytes = session.ReadScalar8Scalar16ShelfBytesForBatch(pathTarget.Target.Offset, profile);
                    cache[pathTarget.Target.Offset] = shelfBytes;
                }

                Scalar8Scalar16ReadOnly shelf = new(shelfBytes, profile);
                if (!shelf.IsValid || !shelf.Contains(key, key, identityLow))
                {
                    throw new InvalidDataException("Eight-index same-identities SS8-16 validation could not find the expected identity tuple.");
                }

                validated++;
            }
        }

        return new MultiIndexValidationCounts(cache.Count, 0, validated, 0);
    }

    /// <summary>
    /// Validates one reopened `SS16-16` plan by routing every generated widened key to an `SS16-16` shelf and checking the 16-byte identity tuple.<br/>
    /// The current write loop uses the same high/low pair for key and identity, which is sufficient for same-file multi-shape isolation proof.<br/>
    /// </summary>
    /// <param name="session">The reopened file session.</param>
    /// <param name="rootOffset">The plan root-router offset.</param>
    /// <param name="profile">The `SS16-16` shelf profile.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <returns>The validation counts.</returns>
    private static MultiIndexValidationCounts ValidateEightIndexScalar16Scalar16Reopen(
        LibraDexFileSession session,
        long rootOffset,
        Scalar16Scalar16Profile profile,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order)
    {
        Dictionary<long, byte[]> cache = [];
        int validated = 0;
        for (int batch = 0; batch < batches; batch++)
        {
            for (int i = 0; i < itemsPerBatch; i++)
            {
                ulong keyHigh = CreateRoutedBulkWriteKey(batch, order[i], itemsPerBatch, prefixCount);
                ulong keyLow = CreateSqliteScalar16Scalar16LowHalf(keyHigh);
                Scalar16Scalar16RoutePathTarget pathTarget = session.WalkScalar16Scalar16RoutePathTarget(rootOffset, keyHigh, keyLow, maxRouterHops: 8);
                if (pathTarget.Target.Kind != Scalar16Scalar16RouteTargetKind.Shelf)
                {
                    throw new InvalidDataException("Eight-index same-identities SS16-16 route did not terminate at an SS16-16 shelf.");
                }

                if (!cache.TryGetValue(pathTarget.Target.Offset, out byte[]? shelfBytes))
                {
                    shelfBytes = session.ReadScalar16Scalar16ShelfBytesForBatch(pathTarget.Target.Offset, profile);
                    cache[pathTarget.Target.Offset] = shelfBytes;
                }

                Scalar16Scalar16ReadOnly shelf = new(shelfBytes, profile);
                if (!shelf.IsValid || !shelf.Contains(keyHigh, keyLow, keyHigh, keyLow))
                {
                    throw new InvalidDataException("Eight-index same-identities SS16-16 validation could not find the expected identity tuple.");
                }

                validated++;
            }
        }

        return new MultiIndexValidationCounts(cache.Count, 0, validated, 0);
    }

    /// <summary>
    /// Diagnoses routed shelf target locality for public bulk-read ranges over a public batch-built `SS8-8` tree.<br/>
    /// The command explains whether coalescing can help by reporting distinct shelf targets, contiguous shelf runs, router targets, and duplicate route-target spans.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the target-locality report is written.</returns>
    private static int RunScalar8Scalar8PublicReadTargets(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-public-read-targets.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        Scalar8Scalar8BulkWriteLocalityMode localityMode = ParseScalar8Scalar8BulkWriteLocalityMode(GetOption(args, "--locality-mode", "batch-major"));
        if (batches <= 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Public read-target batches and items per batch must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Public read-target prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        using (Scalar8Scalar8Index created = Indexes.SS88.Create(
            path,
            DataKernelBackingKind.File,
            name: "public-read-targets",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(94),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = RunScalar8Scalar8RoutedBulkWriteLoop(created, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, localityMode);
        }

        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        Scalar8Scalar8PublicReadTargetResult[] results = new Scalar8Scalar8PublicReadTargetResult[5];
        using (LibraDexFileSession session = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            Scalar8Scalar8IndexHandle handle = session.GetScalar8Scalar8IndexHandle(0);
            results[0] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix 0", 0, 0);
            results[1] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix middle", middlePrefix, middlePrefix);
            results[2] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix last", prefixCount - 1, prefixCount - 1);
            results[3] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix 0-2", 0, crossUpperPrefix);
            results[4] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix 0-last", 0, prefixCount - 1);
        }

        string reportPath = WriteScalar8Scalar8PublicReadTargetsReport(artifactDirectory, batches, itemsPerBatch, prefixCount, localityMode, results);
        Console.WriteLine("ss8-8 public read targets");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"localityMode {localityMode}");
        PrintScalar8Scalar8PublicReadTargetResults(results);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

