    /// <summary>
    /// Measures one direct root-to-shelf no-split insert mutation after deterministic setup.<br/>
    /// </summary>
    /// <param name="path">The sample file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured mutation sample.</returns>
    private static Scalar8Scalar8DesignPerfSample MeasureScalar8Scalar8DesignDirectNoSplit(string path, Scalar8Scalar8Profile profile)
    {
        const int itemCount = 512;
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(21), DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8pfdn", 0));
        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(root.Offset, 0x00, profile, itemCount);
        _ = session.GetAndResetReadTelemetry();
        ulong key = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(itemCount + 128));
        Stopwatch stopwatch = Stopwatch.StartNew();
        (long _, Scalar8Scalar8InsertResult insertResult, DataKernelCommitTelemetry commit) = session.InsertRoutedScalar8Scalar8NoSplit(root.Offset, 0x00, profile, key, key, allowDuplicateKeys: true);
        stopwatch.Stop();
        if (insertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Design perf direct no-split scenario did not take the no-split path.");
        }

        return CreateDesignPerfSample(stopwatch, session.GetAndResetReadTelemetry(), commit);
    }

    /// <summary>
    /// Measures one root-prefix-visible split mutation after deterministic setup.<br/>
    /// </summary>
    /// <param name="path">The sample file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured mutation sample.</returns>
    private static Scalar8Scalar8DesignPerfSample MeasureScalar8Scalar8DesignRootPrefixSplit(string path, Scalar8Scalar8Profile profile)
    {
        CreateRootPrefixSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(22), DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8pfrs", 0));
        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00, 0x80]);
        _ = session.GetAndResetReadTelemetry();
        const ulong rightPrefixBase = 0x8000_0000_0000_0000UL;
        ulong key = rightPrefixBase + 10_000UL;
        Stopwatch stopwatch = Stopwatch.StartNew();
        (
            _,
            long rightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult insertResult,
            DataKernelCommitTelemetry commit) = session.SplitRoutedScalar8Scalar8ByRootPrefix(root.Offset, 0x00, 0x80, profile, key, key);
        stopwatch.Stop();
        if (rightShelfOffset == 0 || insertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Design perf root-prefix split scenario did not take the root-prefix split path.");
        }

        return CreateDesignPerfSample(stopwatch, session.GetAndResetReadTelemetry(), commit);
    }

