    /// <summary>
    /// Measures one walked deeper transform split after deterministic child-router setup.<br/>
    /// This scenario reaches a full shelf below a child router and transforms that shelf into the next-depth router without dirtying the parent router.<br/>
    /// </summary>
    /// <param name="path">The sample file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured mutation sample.</returns>
    private static Scalar8Scalar8DesignPerfSample MeasureScalar8Scalar8DesignWalkedTransformSplit(string path, Scalar8Scalar8Profile profile)
    {
        CreateDeeperTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(26), DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8pfwt", 0));
        _ = session.CreateScalar8Scalar8ShelfBehindChildRouter(root.Offset, 0x00, 0x00, profile, keys, identities);
        _ = session.GetAndResetReadTelemetry();
        const ulong thirdByteRightBase = 0x0000_8000_0000_0000UL;
