            setupLength = GetFileLength(path);
            const ulong rightPrefixBase = 0x8000_0000_0000_0000UL;
            ulong insertedKey = rightPrefixBase + 10_000UL;
            (
                _,
                _,
                finalLeftCount,
                finalRightCount,
                _,
                commit) = session.SplitRoutedScalar8Scalar8ByRootPrefix(root.Offset, 0x00, 0x80, profile, insertedKey, insertedKey);
            finalLength = GetFileLength(path);
