        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(32), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8gstr", 0));
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
            setupLength = GetFileLength(path);
            const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
            ulong insertedKey = secondByteRightBase + 10_000UL;
            (
                _,
                _,
                _,
                finalLeftCount,
                finalRightCount,
                _,
                commit) = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x00, 0x80, profile, insertedKey, insertedKey);
            finalLength = GetFileLength(path);
        }

        return CreateScalar8Scalar8GrowthSlackResult(
            "transform split",
            setupLength,
            finalLength,
            routerCount: 2,
            shelfCount: 2,
            finalLeftCount,
            finalRightCount,
            profile,
            commit);
    }

    /// <summary>
    /// Measures growth and slack for a walked deeper `SS8-8` transmorphic split.<br/>
    /// This shape reuses a full shelf below a child router as the next-depth router and appends two replacement shelves.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured growth/slack result.</returns>
    private static Scalar8Scalar8GrowthSlackResult MeasureScalar8Scalar8WalkedTransformGrowthSlack(string path, Scalar8Scalar8Profile profile)
    {
        File.Delete(path);
        CreateDeeperTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        long setupLength;
        long finalLength;
        DataKernelCommitTelemetry commit;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(33), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8gswt", 0));
            _ = session.CreateScalar8Scalar8ShelfBehindChildRouter(root.Offset, 0x00, 0x00, profile, keys, identities);
            setupLength = GetFileLength(path);
            const ulong thirdByteRightBase = 0x0000_8000_0000_0000UL;
            ulong insertedKey = thirdByteRightBase + 10_000UL;
            Scalar8Scalar8RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar8(root.Offset, profile, insertedKey, insertedKey, allowDuplicateKeys: true, maxRouterHops: 8);
            if (result.Kind != Scalar8Scalar8RoutedInsertKind.WalkedShelfTransformSplit)
            {
                throw new InvalidDataException("Growth/slack walked transform scenario did not take the expected split path.");
            }

            commit = result.Commit;
            finalLength = GetFileLength(path);
        }

        int finalLeftCount = profile.MaxItemCount / 2;
        int finalRightCount = profile.MaxItemCount - finalLeftCount + 1;
        return CreateScalar8Scalar8GrowthSlackResult(
            "walked transform split",
            setupLength,
            finalLength,
            routerCount: 3,
            shelfCount: 2,
            finalLeftCount,
            finalRightCount,
            profile,
            commit);
    }

