    /// <summary>
    /// Validates walked parent-route refinement split shape after a full shelf behind a child router can be divided by the child router's key byte.<br/>
    /// The expected normal split shape rewrites the original full shelf, appends one new shelf, rewrites the parent router, and leaves the old shelf offset live as one split side.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the parent-route split sanity passes.</returns>
    private static int RunScalar8Scalar8ParentRouteSplitSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-parent-route-split-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeys = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        const ulong secondByteFarRightBase = 0x00C0_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8(secondByteRightBase + (ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexParentRouteSplit",
            DevCustomText: "ss8-8 parent route split",
            DevGuid: Guid.Parse("7031baeb-89cc-4a85-9b0a-5c6efbd88bb9"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 95);

        ulong transformInsertedKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8(secondByteRightBase + 10_000UL);
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8prspl", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss8-8 parent split root create", rootCommit);
        (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, encodedKeys, encodedIdentities, [0x00]);
        PrintCommit("ss8-8 parent split shelf link", linkCommit);
        ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile);

        (
            long childRouterOffset,
            _,
            long rightShelfOffset,
            _,
            int transformedRightCount,
            Scalar8Scalar8InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar8Scalar8ByShelfTransform(
                root.Offset,
                0x00,
                0x80,
                profile,
                transformInsertedKey,
                transformInsertedKey);
        if (childRouterOffset != sourceShelfOffset || transformResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Parent-route split setup transform did not reuse the source shelf offset.");
        }

        PrintCommit("ss8-8 parent split transform", transformCommit);
        ValidateScalar8Scalar8TransformCommit(transformCommit, profile);

        int fillCount = profile.MaxItemCount - transformedRightCount;
        for (int i = 0; i < fillCount; i++)
        {
            ulong key = Scalar8Scalar8Layout.EncodeUnsignedScalar8(secondByteFarRightBase + (ulong)i);
            Scalar8Scalar8RoutedInsertResult fill = session.InsertWalkedRoutedScalar8Scalar8(
                root.Offset,
                profile,
                key,
                key,
                allowDuplicateKeys: true,
                maxRouterHops: 8);
            if (fill.Kind != Scalar8Scalar8RoutedInsertKind.WalkedNoSplit || fill.PrimaryOffset != rightShelfOffset || fill.InsertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected parent-route setup no-split fill at {rightShelfOffset}, got {fill.Kind}/{fill.InsertResult} offset {fill.PrimaryOffset}.");
            }
        }

        ulong splitKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8(secondByteFarRightBase + 10_000UL);
        Scalar8Scalar8RoutedInsertResult split = session.InsertWalkedRoutedScalar8Scalar8(
            root.Offset,
            profile,
            splitKey,
            splitKey,
            allowDuplicateKeys: true,
            maxRouterHops: 8);
        if (split.Kind != Scalar8Scalar8RoutedInsertKind.WalkedParentRouteSplit || split.PrimaryOffset != childRouterOffset || split.LeftShelfOffset != rightShelfOffset || split.RightShelfOffset == 0 || split.InsertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected walked parent-route split preserving original shelf {rightShelfOffset}, got {split.Kind}/{split.InsertResult} primary {split.PrimaryOffset} left {split.LeftShelfOffset} right {split.RightShelfOffset}.");
        }

        PrintCommit("ss8-8 parent split commit", split.Commit);
        ValidateScalar8Scalar8RouteSplitCommit(split.Commit, profile);
        _ = session.GetAndResetReadTelemetry();
        ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(session, root.Offset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, transformedRightCount, transformInsertedKey, transformInsertedKey);
        _ = session.GetAndResetReadTelemetry();
        ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(session, root.Offset, 0x00, 0xC0, childRouterOffset, split.RightShelfOffset, profile, fillCount + 1, splitKey, splitKey);

        Console.WriteLine($"ss8-8-parent-route-split-sanity ok path={path} root={root.Offset} child={childRouterOffset} preserved={rightShelfOffset} appended={split.RightShelfOffset} size={profile.ShelfExtentSize} items={transformedRightCount}/{fillCount + 1}");
        return 0;
    }

