    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all walked decision outcomes validate.</returns>
    private static int RunScalar8Scalar16WalkedDecisionSanity(string[] args)
    {
        string basePath = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-16-walked-decision-sanity.lbdx"));
        string directory = Path.GetDirectoryName(basePath)!;
        string fileName = Path.GetFileNameWithoutExtension(basePath);
        Directory.CreateDirectory(directory);

        Scalar8Scalar16Profile profile = Scalar8Scalar16Profile.Default32KiB;
        string noSplitPath = Path.Combine(directory, fileName + "-nosplit.lbdx");
        string transformPath = Path.Combine(directory, fileName + "-transform.lbdx");
        string parentPath = Path.Combine(directory, fileName + "-parent.lbdx");
        File.Delete(noSplitPath);
        File.Delete(transformPath);
        File.Delete(parentPath);

        RunScalar8Scalar16WalkedDecisionNoSplit(noSplitPath, profile);
        RunScalar8Scalar16WalkedDecisionTransform(transformPath, profile);
        RunScalar8Scalar16WalkedDecisionParentRoute(parentPath, profile);

        Console.WriteLine($"ss8-16-walked-decision-sanity ok basePath={basePath} size={profile.ShelfExtentSize}");
        return 0;
