    /// <summary>
    /// Validates the unified walked `SS8-16` decision path when a full walked shelf can split by refining its parent router routes.<br/>
    /// The expected outcome is `WalkedParentRouteSplit`, preserving the old shelf offset as one split side and appending one shelf.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-16` shelf profile to validate.</param>
    private static void RunScalar8Scalar16WalkedDecisionParentRoute(string path, Scalar8Scalar16Profile profile)
    {
        CreateScalar8Scalar16TransformSplitVectors(profile, out ulong[] keys, out ulong[] identityHighs, out ulong[] identityLows, out int _, out int _);
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexS816DecisionParent",
            DevCustomText: "ss8-16 walked decision parent",
            DevGuid: Guid.Parse("ea0cae52-1711-4599-b04a-0643ccaa035d"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 100);

        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        const ulong secondByteFarRightBase = 0x00C0_0000_0000_0000UL;
        const ulong transformInsertedKey = secondByteRightBase + 10_000UL;
        const ulong transformInsertedIdentityHigh = 1;
        const ulong transformInsertedIdentityLow = 10_000UL;
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "s816wd2", 0));
        PrintCommit("ss8-16 decision parent root create", rootCommit);
        (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar16ShelfAndLinkRootRoutes(root.Offset, profile, keys, identityHighs, identityLows, [0x00]);
        PrintCommit("ss8-16 decision parent shelf link", linkCommit);
        ValidateScalar8Scalar16RouteLinkCommit(linkCommit, profile);

        (
            long childRouterOffset,
            _,
            long rightShelfOffset,
            _,
            int transformedRightCount,
            Scalar8Scalar16InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar8Scalar16ByShelfTransform(root.Offset, 0x00, 0x80, profile, transformInsertedKey, transformInsertedIdentityHigh, transformInsertedIdentityLow);
        if (childRouterOffset != sourceShelfOffset || transformResult != Scalar8Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException("Unified SS8-16 parent decision setup transform did not reuse the source shelf offset.");
        }

        PrintCommit("ss8-16 decision parent transform", transformCommit);
        ValidateScalar8Scalar16TransformCommit(transformCommit, profile);

        int fillCount = profile.MaxItemCount - transformedRightCount;
        for (int i = 0; i < fillCount; i++)
        {
            ulong key = secondByteFarRightBase + (ulong)i;
            (long fillShelfOffset, Scalar8Scalar16InsertResult fillResult, _) = session.InsertWalkedRoutedScalar8Scalar16NoSplit(
                root.Offset,
                profile,
                key,
                encodedIdentityHigh: 1,
                encodedIdentityLow: (ulong)i,
                allowDuplicateKeys: true,
                maxRouterHops: 8);
            if (fillShelfOffset != rightShelfOffset || fillResult != Scalar8Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException("Unified SS8-16 parent decision setup did not fill the expected shelf.");
            }
        }

        _ = session.GetAndResetReadTelemetry();
        const ulong splitKey = secondByteFarRightBase + 10_000UL;
        const ulong splitIdentityHigh = 1;
        const ulong splitIdentityLow = 10_000UL;
        Scalar8Scalar16RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar16(
            root.Offset,
            profile,
            splitKey,
            splitIdentityHigh,
            splitIdentityLow,
            allowDuplicateKeys: true,
            maxRouterHops: 8);
        if (result.Kind != Scalar8Scalar16RoutedInsertKind.WalkedParentRouteSplit || result.PrimaryOffset != childRouterOffset || result.LeftShelfOffset != rightShelfOffset || result.RightShelfOffset == 0 || result.InsertResult != Scalar8Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected unified SS8-16 walked parent-route decision preserving shelf {rightShelfOffset}, got {result.Kind}/{result.InsertResult} primary {result.PrimaryOffset} left {result.LeftShelfOffset} right {result.RightShelfOffset}.");
        }

        PrintRead("ss8-16 decision parent read", session.GetAndResetReadTelemetry());
        PrintCommit("ss8-16 decision parent commit", result.Commit);
        ValidateScalar8Scalar16RouteSplitCommit(result.Commit, profile);
        ValidateTwoLevelRoutedScalar8Scalar16ShelfShape(session, root.Offset, 0x00, 0xC0, childRouterOffset, result.RightShelfOffset, profile, fillCount + 1, splitKey, splitIdentityHigh, splitIdentityLow);
    }

    /// <summary>
    /// Validates the unified walked `SS16-16` insert decision path across no-split, transform split, and parent-route split outcomes.<br/>
    /// This is the shape-local orchestration parity check matching the other widened-shape caller contracts.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all walked decision outcomes validate.</returns>
    private static int RunScalar16Scalar16WalkedDecisionSanity(string[] args)
    {
        string basePath = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss16-16-walked-decision-sanity.lbdx"));
        string directory = Path.GetDirectoryName(basePath)!;
        string fileName = Path.GetFileNameWithoutExtension(basePath);
        Directory.CreateDirectory(directory);

        Scalar16Scalar16Profile profile = Scalar16Scalar16Profile.Default32KiB;
        string noSplitPath = Path.Combine(directory, fileName + "-nosplit.lbdx");
        string transformPath = Path.Combine(directory, fileName + "-transform.lbdx");
        string parentPath = Path.Combine(directory, fileName + "-parent.lbdx");
        File.Delete(noSplitPath);
        File.Delete(transformPath);
        File.Delete(parentPath);

        RunScalar16Scalar16WalkedDecisionNoSplit(noSplitPath, profile);
        RunScalar16Scalar16WalkedDecisionTransform(transformPath, profile);
        RunScalar16Scalar16WalkedDecisionParentRoute(parentPath, profile);

        Console.WriteLine($"ss16-16-walked-decision-sanity ok basePath={basePath} size={profile.ShelfExtentSize}");
        return 0;
    }

