    /// <summary>
    /// Validates classified route walking from a root router directly to an `SS8-8` shelf.<br/>
    /// Expected read shape is one full router page plus one 4-byte target classifier read.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile to validate.</param>
    private static void RunScalar8Scalar8RouteWalkerOneLevel(string path, Scalar8Scalar8Profile profile)
    {
        const int itemCount = 512;
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteWalkerOne",
            DevCustomText: "ss8-8 route walker one",
            DevGuid: Guid.Parse("882901dc-4987-41a0-8717-086ef362df05"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 11);

        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8walk1", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss8-8 walker one root create", rootCommit);
        (long shelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(root.Offset, 0x00, profile, itemCount);
        PrintCommit("ss8-8 walker one shelf link", linkCommit);
        ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile);
        _ = session.GetAndResetReadTelemetry();

        Scalar8Scalar8RouteTarget target = session.WalkScalar8Scalar8RouteTarget(root.Offset, Scalar8Scalar8Layout.EncodeUnsignedScalar8(128), maxRouterHops: 8);
