        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss16-16 walker one read", readTelemetry);
        if (readTelemetry.ReadCallCount != 2 || readTelemetry.BytesRead != RouterLayout.Size + sizeof(uint))
        {
            throw new InvalidDataException("One-level SS16-16 route walker should read one router page and one 4-byte classifier magic.");
        }
    }

    /// <summary>
    /// Validates classified route walking from a root router through one child router to an `SS16-16` shelf.<br/>
    /// Expected read shape is two full router pages plus two 4-byte target classifier reads.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS16-16` shelf profile to validate.</param>
    private static void RunScalar16Scalar16RouteWalkerTwoLevel(string path, Scalar16Scalar16Profile profile)
    {
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeyHighs = new ulong[profile.MaxItemCount];
        ulong[] encodedKeyLows = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentityHighs = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentityLows = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            encodedKeyHighs[index] = 0;
            encodedKeyLows[index] = (ulong)i;
            encodedIdentityHighs[index] = 0;
            encodedIdentityLows[index] = (ulong)i;
            index++;
        }

        const ulong secondByteRightBaseHigh = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            encodedKeyHighs[index] = secondByteRightBaseHigh;
            encodedKeyLows[index] = (ulong)i;
            encodedIdentityHighs[index] = 0;
            encodedIdentityLows[index] = (ulong)i;
            index++;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteWalkerTwo",
            DevCustomText: "ss16-16 route walker two",
            DevGuid: Guid.Parse("47d884c5-e8ca-42b4-b4ee-4c6c7e5679b6"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 21);

        ulong insertedKeyHigh = secondByteRightBaseHigh;
        const ulong insertedKeyLow = 10_000UL;
        const ulong insertedIdentityHigh = 1;
        const ulong insertedIdentityLow = 10_000UL;
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "s1616wlk2", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss16-16 walker two root create", rootCommit);
        (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar16Scalar16ShelfAndLinkRootRoutes(root.Offset, profile, encodedKeyHighs, encodedKeyLows, encodedIdentityHighs, encodedIdentityLows, [0x00]);
        PrintCommit("ss16-16 walker two shelf link", linkCommit);
        ValidateScalar16Scalar16RouteLinkCommit(linkCommit, profile);
        _ = session.GetAndResetReadTelemetry();

        (
            long childRouterOffset,
            _,
            long rightShelfOffset,
            _,
            _,
            Scalar16Scalar16InsertResult splitResult,
            DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar16Scalar16ByShelfTransform(
                root.Offset,
                0x00,
                0x80,
                profile,
                insertedKeyHigh,
                insertedKeyLow,
                insertedIdentityHigh,
                insertedIdentityLow);
        if (childRouterOffset != sourceShelfOffset || splitResult != Scalar16Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException("SS16-16 route walker two-level setup transform did not reuse the source shelf offset.");
        }

        PrintRead("ss16-16 walker two transform read", session.GetAndResetReadTelemetry());
        PrintCommit("ss16-16 walker two transform commit", transformCommit);
        ValidateScalar16Scalar16TransformCommit(transformCommit, profile);
        _ = session.GetAndResetReadTelemetry();

        Scalar16Scalar16RouteTarget target = session.WalkScalar16Scalar16RouteTarget(root.Offset, insertedKeyHigh, insertedKeyLow, maxRouterHops: 8);
        if (target.Kind != Scalar16Scalar16RouteTargetKind.Shelf || target.Offset != rightShelfOffset || target.RouterDepth != 1)
        {
            throw new InvalidDataException($"Expected two-level SS16-16 walker shelf target {rightShelfOffset}, got {target.Kind} offset {target.Offset} depth {target.RouterDepth}.");
        }

        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss16-16 walker two read", readTelemetry);
        if (readTelemetry.ReadCallCount != 4 || readTelemetry.BytesRead != (RouterLayout.Size * 2) + (sizeof(uint) * 2))
        {
            throw new InvalidDataException("Two-level SS16-16 route walker should read two router pages and two 4-byte classifier magics.");
        }
    }

    /// <summary>
    /// Validates the unified routed insert decision path when the incoming tuple fits in the existing routed shelf.<br/>
    /// The expected outcome is `NoSplit`, with one shelf rewrite and no router rewrite.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile to validate.</param>
    private static void RunScalar8Scalar8RoutedInsertDecisionNoSplit(string path, Scalar8Scalar8Profile profile)
    {
        const int itemCount = 512;
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
