    private static int RunScalar8Scalar8Perf(string[] args)
    {
        int[] shelfSizes = ParseIntList(GetOption(args, "--shelf-sizes", "16384,32768,65536"));
        int insertRuns = GetIntOption(args, "--insert-runs", 50);
        int sampleRuns = GetIntOption(args, "--sample-runs", 10);
        int lookupIterations = GetIntOption(args, "--lookup-iterations", 1_000_000);
        int rangeIterations = GetIntOption(args, "--range-iterations", 100_000);
        int rangeLength = GetIntOption(args, "--range-length", 128);
        int equalItemCountOverride = GetIntOption(args, "--equal-item-count", 0);
        int multiShelfCount = GetIntOption(args, "--multi-shelf-count", 256);
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));

        if (insertRuns <= 0 || sampleRuns <= 0 || lookupIterations <= 0 || rangeIterations <= 0 || rangeLength <= 0 || multiShelfCount <= 0)
        {
            Console.Error.WriteLine("ss8-8-perf requires positive iteration and range values.");
            return 1;
        }

        Scalar8Scalar8Profile[] profiles = new Scalar8Scalar8Profile[shelfSizes.Length];
        int smallestMaxItemCount = int.MaxValue;
        for (int i = 0; i < shelfSizes.Length; i++)
        {
            profiles[i] = Scalar8Scalar8Profile.Create(shelfSizes[i]);
            smallestMaxItemCount = Math.Min(smallestMaxItemCount, profiles[i].MaxItemCount);
        }

        int equalItemCount = equalItemCountOverride > 0 ? equalItemCountOverride : smallestMaxItemCount;
        if (equalItemCount <= 0 || equalItemCount > smallestMaxItemCount)
        {
            Console.Error.WriteLine($"equal item count {equalItemCount} must be between 1 and the smallest profile max item count {smallestMaxItemCount}.");
            return 1;
        }

        if (rangeLength > equalItemCount)
        {
            Console.Error.WriteLine($"range length {rangeLength} is larger than equal item count {equalItemCount}.");
            return 1;
        }

        WarmUpScalar8Scalar8Perf(shelfSizes, rangeLength);

        Scalar8Scalar8PerfVectors equalVectors = CreateScalar8Scalar8PerfVectors(equalItemCount, lookupIterations, rangeIterations, rangeLength);
        Scalar8Scalar8PerfResult[] equalResults = new Scalar8Scalar8PerfResult[profiles.Length];
        Scalar8Scalar8PerfResult[] fullResults = new Scalar8Scalar8PerfResult[profiles.Length];
        Scalar8Scalar8MultiShelfPerfResult[] multiShelfResults = new Scalar8Scalar8MultiShelfPerfResult[profiles.Length];
        for (int i = 0; i < profiles.Length; i++)
        {
            Scalar8Scalar8Profile profile = profiles[i];
            if (rangeLength > profile.MaxItemCount)
            {
                Console.Error.WriteLine($"range length {rangeLength} is larger than max item count {profile.MaxItemCount} for shelf size {profile.ShelfExtentSize}.");
                return 1;
            }

            equalResults[i] = MeasureScalar8Scalar8Profile(profile, equalItemCount, insertRuns, sampleRuns, equalVectors);
            Scalar8Scalar8PerfVectors fullVectors = CreateScalar8Scalar8PerfVectors(profile.MaxItemCount, lookupIterations, rangeIterations, rangeLength);
            fullResults[i] = MeasureScalar8Scalar8Profile(profile, profile.MaxItemCount, insertRuns, sampleRuns, fullVectors);
            multiShelfResults[i] = MeasureScalar8Scalar8MultiShelfProfile(profile, equalItemCount, multiShelfCount, sampleRuns, equalVectors);
        }

        Console.WriteLine("ss8-8 perf");
        Console.WriteLine($"insertRuns {insertRuns:N0}");
        Console.WriteLine($"sampleRuns {sampleRuns:N0}");
        Console.WriteLine($"equalItemCount {equalItemCount:N0}");
        Console.WriteLine($"multiShelfCount {multiShelfCount:N0}");
        Console.WriteLine($"lookupIterations {lookupIterations:N0}");
        Console.WriteLine($"rangeIterations {rangeIterations:N0}");
        Console.WriteLine($"rangeLength {rangeLength:N0}");
        Console.WriteLine();
        Console.WriteLine("equal-work results");
        PrintScalar8Scalar8PerfHeader();
        for (int i = 0; i < equalResults.Length; i++)
        {
            PrintScalar8Scalar8Perf(equalResults[i]);
        }

        Console.WriteLine();
        Console.WriteLine("full-capacity results");
        PrintScalar8Scalar8PerfHeader();
        for (int i = 0; i < fullResults.Length; i++)
        {
            PrintScalar8Scalar8Perf(fullResults[i]);
        }

        Console.WriteLine();
        Console.WriteLine("multi-shelf equal-work results");
        PrintScalar8Scalar8MultiShelfPerfHeader();
        for (int i = 0; i < multiShelfResults.Length; i++)
        {
            PrintScalar8Scalar8MultiShelfPerf(multiShelfResults[i]);
        }

        string reportPath = WriteScalar8Scalar8PerfReport(artifactDirectory, insertRuns, sampleRuns, equalItemCount, multiShelfCount, lookupIterations, rangeIterations, rangeLength, equalResults, fullResults, multiShelfResults);
        Console.WriteLine($"ss8-8 perf report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Runs a shelf-size breakpoint sweep for `SS8-8` cached read paths and DataKernel file-read paths.<br/>
    /// Cached read measurements operate on already-filled shelf bytes and isolate CPU/cache behavior.<br/>
    /// DataKernel measurements read shelf extents from a file into caller buffers and expose extent-size read throughput and syscall shape.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the sweep completes successfully; otherwise one.</returns>
    private static int RunScalar8Scalar8SizeSweep(string[] args)
    {
        int[] shelfSizes = ParseIntList(GetOption(args, "--shelf-sizes", "8192,12288,16384,24576,32768,49152,65536"));
        int[] rangeLengths = ParseIntList(GetOption(args, "--range-lengths", "1,16,128,512"));
        int sampleRuns = GetIntOption(args, "--sample-runs", 10);
        int lookupIterations = GetIntOption(args, "--lookup-iterations", 2_000_000);
        int rangeIterations = GetIntOption(args, "--range-iterations", 250_000);
        int multiShelfCount = GetIntOption(args, "--multi-shelf-count", 512);
        long dkTotalBytes = GetLongOption(args, "--dk-total-bytes", 1024L * 1024 * 1024);
        int dkRuns = GetIntOption(args, "--dk-runs", 5);
        string dataDirectory = GetOption(args, "--data-directory", Path.Combine(@"T:\LibraDex", "SS8-8SizeSweep"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));

        if (sampleRuns <= 0 || lookupIterations <= 0 || rangeIterations <= 0 || multiShelfCount <= 0 || dkTotalBytes <= 0 || dkRuns <= 0)
        {
            Console.Error.WriteLine("ss8-8-size-sweep requires positive run, iteration, shelf-count, and byte values.");
            return 1;
        }

        Scalar8Scalar8Profile[] profiles = new Scalar8Scalar8Profile[shelfSizes.Length];
        int smallestMaxItemCount = int.MaxValue;
        for (int i = 0; i < shelfSizes.Length; i++)
        {
            profiles[i] = Scalar8Scalar8Profile.Create(shelfSizes[i]);
            smallestMaxItemCount = Math.Min(smallestMaxItemCount, profiles[i].MaxItemCount);
        }

        int maxRangeLength = 0;
        for (int i = 0; i < rangeLengths.Length; i++)
        {
            maxRangeLength = Math.Max(maxRangeLength, rangeLengths[i]);
        }

        if (maxRangeLength <= 0 || maxRangeLength > smallestMaxItemCount)
        {
            Console.Error.WriteLine($"range lengths must be positive and no larger than the smallest profile max item count {smallestMaxItemCount}.");
            return 1;
        }

        Directory.CreateDirectory(dataDirectory);
        Directory.CreateDirectory(artifactDirectory);

        WarmUpScalar8Scalar8SizeSweep(profiles, smallestMaxItemCount, maxRangeLength);

        Scalar8Scalar8ReadSweepResult[] equalReadResults = new Scalar8Scalar8ReadSweepResult[profiles.Length * rangeLengths.Length];
        Scalar8Scalar8ReadSweepResult[] fullReadResults = new Scalar8Scalar8ReadSweepResult[profiles.Length * rangeLengths.Length];
        int equalReadIndex = 0;
        int fullReadIndex = 0;
        for (int profileIndex = 0; profileIndex < profiles.Length; profileIndex++)
        {
            Scalar8Scalar8Profile profile = profiles[profileIndex];
            byte[] equalSingleShelfBytes = CreateFilledScalar8Scalar8ShelfBytes(profile, smallestMaxItemCount);
            byte[] equalMultiShelfArena = CreateFilledScalar8Scalar8Arena(profile, smallestMaxItemCount, multiShelfCount);
            byte[] fullSingleShelfBytes = CreateFilledScalar8Scalar8ShelfBytes(profile, profile.MaxItemCount);
            byte[] fullMultiShelfArena = CreateFilledScalar8Scalar8Arena(profile, profile.MaxItemCount, multiShelfCount);
            for (int rangeIndex = 0; rangeIndex < rangeLengths.Length; rangeIndex++)
            {
                int rangeLength = rangeLengths[rangeIndex];
                Scalar8Scalar8PerfVectors equalVectors = CreateScalar8Scalar8PerfVectors(smallestMaxItemCount, lookupIterations, rangeIterations, rangeLength);
                Scalar8Scalar8PerfVectors fullVectors = CreateScalar8Scalar8PerfVectors(profile.MaxItemCount, lookupIterations, rangeIterations, rangeLength);
                equalReadResults[equalReadIndex++] = MeasureScalar8Scalar8ReadSweepProfile(profile, smallestMaxItemCount, multiShelfCount, sampleRuns, equalVectors, equalSingleShelfBytes, equalMultiShelfArena);
                fullReadResults[fullReadIndex++] = MeasureScalar8Scalar8ReadSweepProfile(profile, profile.MaxItemCount, multiShelfCount, sampleRuns, fullVectors, fullSingleShelfBytes, fullMultiShelfArena);
            }
        }

        Scalar8Scalar8DataKernelReadSweepResult[] dkResults = new Scalar8Scalar8DataKernelReadSweepResult[profiles.Length];
        for (int i = 0; i < profiles.Length; i++)
        {
            dkResults[i] = MeasureScalar8Scalar8DataKernelReadSweepProfile(profiles[i], dkTotalBytes, dkRuns, dataDirectory);
        }

        Console.WriteLine("ss8-8 size sweep");
        Console.WriteLine($"equalItemCount {smallestMaxItemCount:N0}");
        Console.WriteLine($"sampleRuns {sampleRuns:N0}");
        Console.WriteLine($"lookupIterations {lookupIterations:N0}");
        Console.WriteLine($"rangeIterations {rangeIterations:N0}");
        Console.WriteLine($"multiShelfCount {multiShelfCount:N0}");
        Console.WriteLine($"dkTotalBytes {dkTotalBytes:N0}");
        Console.WriteLine($"dkRuns {dkRuns:N0}");
        Console.WriteLine();
        Console.WriteLine("cached shelf-view equal-work read results");
        PrintScalar8Scalar8ReadSweepHeader();
        for (int i = 0; i < equalReadResults.Length; i++)
        {
            PrintScalar8Scalar8ReadSweep(equalReadResults[i]);
        }

        Console.WriteLine();
        Console.WriteLine("cached shelf-view full-capacity read results");
        PrintScalar8Scalar8ReadSweepHeader();
        for (int i = 0; i < fullReadResults.Length; i++)
        {
            PrintScalar8Scalar8ReadSweep(fullReadResults[i]);
        }

        Console.WriteLine();
        Console.WriteLine("datakernel file-read results");
        PrintScalar8Scalar8DataKernelReadSweepHeader();
        for (int i = 0; i < dkResults.Length; i++)
        {
            PrintScalar8Scalar8DataKernelReadSweep(dkResults[i]);
        }

        string reportPath = WriteScalar8Scalar8SizeSweepReport(
            artifactDirectory,
            smallestMaxItemCount,
            sampleRuns,
            lookupIterations,
            rangeIterations,
            multiShelfCount,
            dkTotalBytes,
            dkRuns,
            equalReadResults,
            fullReadResults,
            dkResults);
        Console.WriteLine($"ss8-8 size sweep report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    /// <summary>
    /// Runs correctness checks plus tiered performance checks and writes a timestamped validation report.<br/>
    /// This command is intentionally harness-level so reporting allocations and formatting do not leak into hot library paths.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when validation completed without fail-level drift; otherwise one.</returns>
    private static int RunValidate(string[] args)
    {
        string tier = GetOption(args, "--tier", "fast").ToLowerInvariant();
