    /// <summary>
    /// Writes the rotating `SS16-16` shelf-size sweep report.<br/>
    /// The report groups the validated walked-decision mutation outcomes by shelf profile and keeps 32 KiB visible as the current anchor.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="runs">The number of fresh-file samples per shelf-size/scenario pair.</param>
    /// <param name="profiles">The `SS16-16` profiles that were measured.</param>
    /// <param name="results">The measured rows in profile-major, scenario-minor order.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar16Scalar16SizeSweepReport(
        string artifactDirectory,
        int runs,
        Scalar16Scalar16Profile[] profiles,
        Scalar8Scalar8DesignPerfResult[] results)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss16-16-size-sweep-current.md");
        ArchiveCurrentReport(reportPath, "ss16-16-size-sweep");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# LibraDex SS16-16 Size Sweep - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Runs per shelf-size/scenario pair: `{runs}`");
        builder.AppendLine("- Shelf sizes use `Scalar16Scalar16Profile.Create(...)`; 32 KiB remains the current default anchor.");
        builder.AppendLine("- Each sample uses a fresh `.lbdx` file and deterministic setup.");
        builder.AppendLine("- Measured elapsed time covers only the target mutation call, not setup.");
        builder.AppendLine("- Scenario set covers the completed `SS16-16` unified walked-decision outcomes.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| shelf bytes | max items | anchor | scenario | avg ms | min/max/sd ms | reads | read bytes | writes | write bytes | write bytes/max item | setlen |");
        builder.AppendLine("|---:|---:|:---:|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        int resultIndex = 0;
        const int scenariosPerProfile = 3;
        for (int profileIndex = 0; profileIndex < profiles.Length; profileIndex++)
        {
            Scalar16Scalar16Profile profile = profiles[profileIndex];
            string anchor = profile.ShelfExtentSize == Scalar16Scalar16Profile.Default32KiB.ShelfExtentSize ? "yes" : "";
            for (int scenarioIndex = 0; scenarioIndex < scenariosPerProfile; scenarioIndex++)
            {
                Scalar8Scalar8DesignPerfResult result = results[resultIndex++];
                string spread = string.Create(CultureInfo.InvariantCulture, $"{result.MinMilliseconds:F4}/{result.MaxMilliseconds:F4}/{result.StandardDeviationMilliseconds:F4}");
                double writeBytesPerMaxItem = result.AverageBytesWritten / profile.MaxItemCount;
                builder.AppendLine(CultureInfo.InvariantCulture, $"| {profile.ShelfExtentSize} | {profile.MaxItemCount} | {anchor} | {result.Name} | {result.AverageMilliseconds:F4} | {spread} | {result.AverageReadCalls:F2} | {result.AverageBytesRead:F0} | {result.AverageWriteCalls:F2} | {result.AverageBytesWritten:F0} | {writeBytesPerMaxItem:F2} | {result.AverageSetLengthCalls:F2} |");
            }
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- `write bytes/max item` is a rough capacity-normalized mutation cost, not a bulk-write throughput result.");
        builder.AppendLine("- Larger shelves increase per-mutation rewrite bytes but also increase max items per shelf and can reduce split frequency.");
        builder.AppendLine("- This sweep is intended to decide whether `SS16-16` needs shelf-size follow-up before broader API or next-shape work.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating normalized `SS8-8` checkpoint report and archives the previous current report.<br/>
    /// The report converts current write and read samples into effective throughput plus percent-of-raw-baseline values.<br/>
    /// This is a decision aid rather than a replacement for syscall-shape tables because small structured operations are not pure streaming I/O.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="writeRuns">The number of fresh-file write samples per mutation scenario.</param>
    /// <param name="smallIterations">The number of same-shelf range read iterations.</param>
    /// <param name="wideIterations">The number of wide range read iterations.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by the measured scenarios.</param>
    /// <param name="writeResults">The measured routed mutation rows.</param>
    /// <param name="readResults">The measured range read rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8NormalizedCheckpointReport(
        string artifactDirectory,
        int writeRuns,
        int smallIterations,
        int wideIterations,
        Scalar8Scalar8Profile profile,
        Scalar8Scalar8DesignPerfResult[] writeResults,
        Scalar8Scalar8RangeScoopPerfResult[] readResults)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-normalized-checkpoint-current.md");
        ArchiveCurrentReport(reportPath, "ss8-8-normalized-checkpoint");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Normalized Checkpoint - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Max items per shelf: `{profile.MaxItemCount}`");
        builder.AppendLine($"- Write runs per scenario: `{writeRuns}`");
        builder.AppendLine($"- Same-shelf read iterations: `{smallIterations}`");
        builder.AppendLine($"- Wide read iterations: `{wideIterations}`");
        builder.AppendLine($"- Raw file reserve commit baseline: `{FileReserveCommitBaselineMiBs:F2} MiB/s`");
        builder.AppendLine($"- Raw file reserve read baseline: `{FileReserveReadBaselineMiBs:F2} MiB/s`");
        builder.AppendLine("- Write percentages are effective mutation throughput, not pure streaming write throughput.");
        builder.AppendLine("- Read percentages are effective bytes-read throughput and are most meaningful for wide/coalesced scoop paths.");
        builder.AppendLine();
        builder.AppendLine("## Write Normalization");
        builder.AppendLine();
        builder.AppendLine("| scenario | avg ms | writes | bytes/write | effective MiB/s | raw commit % | reads | bytes/read | setlen |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < writeResults.Length; i++)
        {
            Scalar8Scalar8DesignPerfResult result = writeResults[i];
            double effectiveMiBs = CalculateMiBs(result.AverageBytesWritten, result.AverageMilliseconds / 1000d);
            double baselinePercent = CalculateBaselinePercent(effectiveMiBs, FileReserveCommitBaselineMiBs);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.AverageMilliseconds:F4} | {result.AverageWriteCalls:F2} | {result.AverageBytesWritten:F0} | {effectiveMiBs:F2} | {FormatBaselinePercent(baselinePercent)} | {result.AverageReadCalls:F2} | {result.AverageBytesRead:F0} | {result.AverageSetLengthCalls:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Read Normalization");
        builder.AppendLine();
        builder.AppendLine("| scenario | identities/range | ns/identity | reads/range | bytes/range | bytes/identity | effective MiB/s | raw read % |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < readResults.Length; i++)
        {
            Scalar8Scalar8RangeScoopPerfResult result = readResults[i];
            double seconds = Math.Max(result.Elapsed.TotalSeconds, 0.000000001);
            double effectiveMiBs = CalculateMiBs(result.BytesRead, seconds);
            double baselinePercent = CalculateBaselinePercent(effectiveMiBs, FileReserveReadBaselineMiBs);
            double readsPerRange = (double)result.ReadCallCount / result.Iterations;
            double bytesPerRange = (double)result.BytesRead / result.Iterations;
            double bytesPerIdentity = result.IdentityCount == 0 ? 0 : (double)result.BytesRead / result.IdentityCount;
            double nsPerIdentity = result.IdentityCount == 0 ? 0 : result.Elapsed.TotalMilliseconds * 1_000_000d / result.IdentityCount;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.RangeLength} | {nsPerIdentity:F2} | {readsPerRange:F3} | {bytesPerRange:F0} | {bytesPerIdentity:F2} | {effectiveMiBs:F2} | {FormatBaselinePercent(baselinePercent)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- Wide coalesced range reads are the closest direct comparison to the raw read baseline because they move multi-megabyte contiguous spans with few read calls.");
        builder.AppendLine("- Small same-shelf reads are latency and fixed-shelf-byte dominated, so percent-of-raw-read is useful only as a drift signal.");
        builder.AppendLine("- Mutation rows should be judged first by write count, bytes written, and `SetLength=0`; effective MiB/s is a sanity check for unexpected collapse.");
        builder.AppendLine("- If wide coalesced reads remain near raw read speed and write syscall shape stays bounded, the current design remains viable enough to continue.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating raw small-I/O baseline report and archives the previous current report.<br/>
    /// The report keeps syscall count, operation bytes, and effective throughput together so `SS8-8` structured rows can be compared to similarly sized raw operations.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
