    /// <param name="iterations">The measured iterations per row.</param>
    /// <param name="warmupIterations">The warmup iterations per row.</param>
    /// <param name="regionCount">The number of rotating file regions.</param>
    /// <param name="regionStride">The byte stride between rotating regions.</param>
