    private static string WriteSmallIoBaselineReport(
        string artifactDirectory,
        string path,
        int iterations,
        int warmupIterations,
        int regionCount,
        int regionStride,
        SmallIoBaselineResult[] results)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "small-io-baseline-current.md");
        ArchiveCurrentReport(reportPath, "small-io-baseline");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# Small I/O Baseline - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Path: `{path}`");
        builder.AppendLine($"- Iterations per row: `{iterations}`");
        builder.AppendLine($"- Warmup iterations per row: `{warmupIterations}`");
        builder.AppendLine($"- Rotating regions: `{regionCount}`");
        builder.AppendLine($"- Region stride: `{regionStride}` bytes");
        builder.AppendLine("- Backing file is pre-created before timed rows; measured writes are positional rewrites within existing file length.");
        builder.AppendLine("- These rows are intended for small `SS8-8` operation fairness, not large sequential ceiling comparison.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | mode | calls/op | bytes/op | elapsed ms | us/op | MiB/s | calls/sec | checksum |");
        builder.AppendLine("|---|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            SmallIoBaselineResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.Mode} | {result.CallsPerOperation} | {result.BytesPerOperation} | {result.Elapsed.TotalMilliseconds:F3} | {result.MicrosecondsPerOperation:F3} | {result.MiBs:F2} | {result.CallsPerSecond:F2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- `write-32k-1call` is the fair raw peer for a no-split shelf rewrite.");
        builder.AppendLine("- `write-69632-2call` is the fair raw peer for the current split/transform write-call shape.");
        builder.AppendLine("- `write-7078-30call`, `write-16876-44call`, and `write-94042-44call` mirror the current routed public write cadences by approximate bytes and write calls per batch.");
        builder.AppendLine("- `read-40968-5call` and `read-69672-5call` mirror current routed small read byte/call shapes.");
        builder.AppendLine("- `read-532488-5call` mirrors the latest 16-shelf wide coalesced read shape.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

