    /// <summary>
    /// Writes the rotating routed `SS8-8` cadence-suite report and archives the previous current report.<br/>
    /// The suite keeps the standard large, medium, and tiny batch cadences in one file so batch-size sensitivity can be reviewed without manual report stitching.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="prefixCount">The number of root prefixes covered by each generated batch.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by the public wrapper.</param>
    /// <param name="repeatCount">The repeat samples per row.</param>
    /// <param name="commitGapCoalesceBytes">The DataKernel commit gap-coalescing threshold used by all rows.</param>
    /// <param name="rows">The measured cadence rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8RoutedCadenceSuiteReport(
        string artifactDirectory,
        int prefixCount,
        Scalar8Scalar8Profile profile,
        int repeatCount,
        int commitGapCoalesceBytes,
        IReadOnlyList<Scalar8Scalar8RoutedCadenceResult> rows)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-routed-cadence-suite-current.md");
        ArchiveCurrentReport(reportPath, "ss8-8-routed-cadence-suite");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Routed Cadence Suite - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Max items per shelf: `{profile.MaxItemCount}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Rows use `LibraDex.Indexes.SS88.Create` and `Scalar8Scalar8Batch`.");
        builder.AppendLine("- Cadences keep total measured inserts near one million while changing commit size.");
        builder.AppendLine($"- Raw commit baseline: `{FileReserveCommitBaselineMiBs:F2} MiB/s`");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| cadence | order | batches | warmup | items/batch | samples | items/sec | us/item | batches/sec | writes/batch | bytes/batch | bytes/item | MiB/s | raw commit % | setLength | checksum |");
        builder.AppendLine("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Count; i++)
        {
            Scalar8Scalar8RoutedCadenceResult row = rows[i];
            Scalar8Scalar8RoutedBulkWriteResult result = row.Result;
            double rawCommitPercent = CalculateBaselinePercent(result.MiBs, FileReserveCommitBaselineMiBs);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.CadenceName} | {row.OrderName} | {result.Batches} | {row.WarmupBatches} | {result.ItemsPerBatch} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {result.MicrosecondsPerItem:F3} | {result.BatchesPerSecond:F2} | {result.WritesPerBatch:F3} | {result.BytesPerBatch:F2} | {result.BytesPerItem:F2} | {result.MiBs:F2} | {FormatBaselinePercent(rawCommitPercent)} | {result.SetLengthCallCount} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Cadence Drift");
        builder.AppendLine();
        builder.AppendLine("| order | 1024 items/sec | 102 items/sec | 10 items/sec | 102 vs 1024 | 10 vs 1024 | 1024 B/item | 102 B/item | 10 B/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        AppendScalar8Scalar8RoutedCadenceDrift(builder, rows, "sorted");
        AppendScalar8Scalar8RoutedCadenceDrift(builder, rows, "random");

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- Use this report as the compact batch-size sensitivity check before making write-path policy changes.");
        builder.AppendLine("- A tiny-batch row that loses throughput while preserving the same bytes/item and writes/batch points to per-commit fixed overhead.");
        builder.AppendLine("- A tiny-batch row that inflates bytes/item or writes/batch points to publication shape rather than route or shelf CPU.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Appends one order-specific cadence drift row to the cadence-suite report.<br/>
    /// The row compares the `102` and `10` item commit cadences against the `1024` item cadence so fixed-per-commit overhead remains obvious.<br/>
    /// </summary>
    /// <param name="builder">The markdown report builder receiving the row.</param>
    /// <param name="rows">The measured cadence rows.</param>
    /// <param name="orderName">The order name to compare, normally `sorted` or `random`.</param>
    private static void AppendScalar8Scalar8RoutedCadenceDrift(
        StringBuilder builder,
        IReadOnlyList<Scalar8Scalar8RoutedCadenceResult> rows,
        string orderName)
    {
        Scalar8Scalar8RoutedBulkWriteResult large = FindScalar8Scalar8RoutedCadenceResult(rows, orderName, 1024);
        Scalar8Scalar8RoutedBulkWriteResult medium = FindScalar8Scalar8RoutedCadenceResult(rows, orderName, 102);
        Scalar8Scalar8RoutedBulkWriteResult tiny = FindScalar8Scalar8RoutedCadenceResult(rows, orderName, 10);
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {orderName} | {large.ItemsPerSecond:F2} | {medium.ItemsPerSecond:F2} | {tiny.ItemsPerSecond:F2} | {FormatPercentChange(medium.ItemsPerSecond, large.ItemsPerSecond)} | {FormatPercentChange(tiny.ItemsPerSecond, large.ItemsPerSecond)} | {large.BytesPerItem:F2} | {medium.BytesPerItem:F2} | {tiny.BytesPerItem:F2} |");
    }

    /// <summary>
    /// Finds one cadence-suite result by order name and items-per-batch.<br/>
    /// The lookup keeps report shaping simple while still failing loudly if the fixed cadence ladder changes without updating the drift table.<br/>
    /// </summary>
    /// <param name="rows">The measured cadence rows.</param>
    /// <param name="orderName">The order name to match.</param>
    /// <param name="itemsPerBatch">The cadence item count to match.</param>
    /// <returns>The matching routed bulk-write result.</returns>
    private static Scalar8Scalar8RoutedBulkWriteResult FindScalar8Scalar8RoutedCadenceResult(
        IReadOnlyList<Scalar8Scalar8RoutedCadenceResult> rows,
        string orderName,
        int itemsPerBatch)
    {
        for (int i = 0; i < rows.Count; i++)
        {
            Scalar8Scalar8RoutedCadenceResult row = rows[i];
            if (row.OrderName == orderName && row.Result.ItemsPerBatch == itemsPerBatch)
            {
                return row.Result;
            }
        }

        throw new InvalidDataException($"Missing SS8-8 routed cadence-suite row for order '{orderName}' with {itemsPerBatch} items per batch.");
    }

