        ArchiveCurrentReport(reportPath, "ss8-8-routed-write-attribution");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Routed Write Attribution - {timestamp} UTC");
