        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches per row: `{batches}`");
        builder.AppendLine($"- Warmup batches per row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Repeat samples per row: `{(results.Length == 0 ? 0 : results[0].SampleCount)}`");
        builder.AppendLine("- Rows use the same public `LibraDex.Indexes.SS88.Create` plus `Scalar8Scalar8Batch` path as `ss8-8-routed-bulk-write`.");
        builder.AppendLine("- Planned bytes describe structural mutations before DataKernel superseded-write elimination and contiguous write combining.");
        builder.AppendLine("- Written bytes and write calls describe the post-coalescing DataKernel commit publication shape.");
        builder.AppendLine();
        builder.AppendLine("## Timing");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | items/sec | us/item | insert ns/item | commit wall ns/item | DK commit ns/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {result.MicrosecondsPerItem:F3} | {result.InsertNsPerItem:F2} | {result.CommitWallNsPerItem:F2} | {result.DataKernelCommitNsPerItem:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Batch Commit CPU Breakdown");
        builder.AppendLine();
        builder.AppendLine("| scenario | dirty shelf flush ns/item | publication attribution ns/item | delta selection ns/item | delta staging ns/item | full shelf staging ns/item | split fallback full staging ns/item | DK commit call ns/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
