        builder.AppendLine();
        builder.AppendLine("## DataKernel Commit CPU Breakdown");
        builder.AppendLine();
        builder.AppendLine("| scenario | slice build ns/item | covered merge ns/item | group shape ns/item | buffer build ns/item | gap read ns/item | backing write ns/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.FileCommitSliceBuildNsPerItem:F2} | {result.FileCommitCoveredRangeMergeNsPerItem:F2} | {result.FileCommitGroupShapeNsPerItem:F2} | {result.FileCommitBufferBuildNsPerItem:F2} | {result.FileCommitGapReadNsPerItem:F2} | {result.FileCommitBackingWriteNsPerItem:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Cached Insert CPU Breakdown");
        builder.AppendLine();
        builder.AppendLine("| scenario | route-cache probe ns/item | root lookup ns/item | route walk ns/item | classify ns/item | shelf-cache lookup ns/item | shelf insert ns/item | append fast ns/item | append fast % | lower-bound ns/item | duplicate check ns/item | unique check ns/item | payload write ns/item | slot move ns/item | header write ns/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            double appendFastRate = result.CachedHandledCount == 0 ? 0 : result.ShelfAppendFastPathCount * 100d / result.CachedHandledCount;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.RouteCacheProbeNsPerItem:F2} | {result.RootLookupNsPerItem:F2} | {result.RouteWalkNsPerItem:F2} | {result.RouteTargetClassificationNsPerItem:F2} | {result.ShelfCacheLookupNsPerItem:F2} | {result.ShelfInsertNsPerItem:F2} | {result.ShelfAppendFastPathNsPerItem:F2} | {appendFastRate:F2}% | {result.ShelfLowerBoundNsPerItem:F2} | {result.ShelfDuplicateCheckNsPerItem:F2} | {result.ShelfUniqueCheckNsPerItem:F2} | {result.ShelfPayloadWriteNsPerItem:F2} | {result.ShelfSlotMoveNsPerItem:F2} | {result.ShelfHeaderWriteNsPerItem:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Route Walk CPU Breakdown");
        builder.AppendLine();
        builder.AppendLine("| scenario | direct view lookup ns/item | direct prefix ns/item | direct slot load ns/item | direct classify ns/item | direct router targets | direct shelf targets | non-direct read ns/item | non-direct prefix ns/item | non-direct lookup ns/item | non-direct classify ns/item | non-direct router targets | non-direct shelf targets |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.RouteWalkDirectViewLookupNsPerItem:F2} | {result.RouteWalkDirectPrefixNsPerItem:F2} | {result.RouteWalkDirectSlotLoadNsPerItem:F2} | {result.RouteWalkDirectTargetClassificationNsPerItem:F2} | {result.RouteWalkDirectRouterTargetCount} | {result.RouteWalkDirectShelfTargetCount} | {result.RouteWalkNonDirectRouterReadNsPerItem:F2} | {result.RouteWalkNonDirectPrefixNsPerItem:F2} | {result.RouteWalkNonDirectRouteLookupNsPerItem:F2} | {result.RouteWalkNonDirectTargetClassificationNsPerItem:F2} | {result.RouteWalkNonDirectRouterTargetCount} | {result.RouteWalkNonDirectShelfTargetCount} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Shelf Cache Lookup CPU Breakdown");
        builder.AppendLine();
        builder.AppendLine("| scenario | shelf probe ns/item | shelf-cache hits | shelf-cache misses | shelf read ns/item | snapshot clone ns/item | entry create ns/item | entry add ns/item | shelf-cache hit rate |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            long shelfCacheAttempts = result.ShelfCacheHitCount + result.ShelfCacheMissCount;
            double shelfCacheHitRate = shelfCacheAttempts == 0 ? 0 : result.ShelfCacheHitCount * 100d / shelfCacheAttempts;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.ShelfCacheProbeNsPerItem:F2} | {result.ShelfCacheHitCount} | {result.ShelfCacheMissCount} | {result.ShelfCacheReadNsPerItem:F2} | {result.ShelfCacheSnapshotCloneNsPerItem:F2} | {result.ShelfCacheEntryCreateNsPerItem:F2} | {result.ShelfCacheEntryAddNsPerItem:F2} | {shelfCacheHitRate:F2}% |");
        }

        builder.AppendLine();
        builder.AppendLine("## Structural Counts");
        builder.AppendLine();
        builder.AppendLine("| scenario | inserted | route creates | no split | normal splits | transform splits | shelf rewrites | shelf appends | router rewrites | same-shelf revisits | distinct rewritten shelves | max repeats/batch |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.InsertedCount} | {result.InitialRouteCreateCount} | {result.NoSplitCount} | {result.NormalSplitCount} | {result.TransformSplitCount} | {result.PlannedShelfRewriteCount} | {result.PlannedShelfAppendCount} | {result.PlannedRouterRewriteCount} | {result.SameShelfRewriteRevisitCount} | {result.DistinctShelfRewriteOffsets} | {result.MaxShelfRewriteCountInBatch} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Cached Path Counts");
        builder.AppendLine();
        builder.AppendLine("| scenario | attempts | handled | route-cache hits | route-cache misses | empty-route misses | non-shelf misses | full-shelf misses | handled rate | route-cache hit rate |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            double handledRate = result.CachedAttemptCount == 0 ? 0 : result.CachedHandledCount * 100d / result.CachedAttemptCount;
            double routeCacheHitRate = result.CachedAttemptCount == 0 ? 0 : result.RouteCacheHitCount * 100d / result.CachedAttemptCount;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.CachedAttemptCount} | {result.CachedHandledCount} | {result.RouteCacheHitCount} | {result.RouteCacheMissCount} | {result.CacheMissEmptyRouteCount} | {result.CacheMissNonShelfTargetCount} | {result.CacheMissFullShelfCount} | {handledRate:F2}% | {routeCacheHitRate:F2}% |");
        }

        builder.AppendLine();
        builder.AppendLine("## Byte Shape");
        builder.AppendLine();
        builder.AppendLine("| scenario | planned bytes/item | written bytes/item | planned bytes | written bytes/batch | staged segments/batch | writes/batch | deferred/batch | setLength |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.PlannedBytesPerItem:F2} | {result.WrittenBytesPerItem:F2} | {result.PlannedStagedBytes} | {result.WrittenBytesPerBatch:F2} | {result.StagedSegmentsPerBatch:F3} | {result.WritesPerBatch:F3} | {result.DeferredCommitRequestsPerBatch:F3} | {result.SetLengthCallCount} |");
        }

        builder.AppendLine();
        builder.AppendLine("## DataKernel Commit Gap Shape");
        builder.AppendLine();
        builder.AppendLine("| scenario | adjacent coalesces/batch | bridged gaps/batch | bridged gap B/batch | max bridged gap B | rejected gaps/batch | rejected gap B/batch | max rejected gap B | overlap breaks/batch |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.CoalescedAdjacentSegmentsPerBatch:F3} | {result.CoalescedGapsPerBatch:F3} | {result.CoalescedGapBytesPerBatch:F2} | {result.MaxCoalescedGapBytes} | {result.RejectedGapsPerBatch:F3} | {result.RejectedGapBytesPerBatch:F2} | {result.MaxRejectedGapBytes} | {result.OverlapBreaksPerBatch:F3} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Dirty Shelf Delta Candidate");
        builder.AppendLine();
        builder.AppendLine("| scenario | dirty shelves | full shelf B/item | raw changed B/item | delta candidate B/item | delta vs full | delta ranges/shelf | header B/shelf | slot B/shelf | item B/shelf | max delta B/shelf | full better/equal shelves |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            double fullBytesPerItem = result.ItemCount == 0 ? 0 : result.PublicationFullShelfBytes / (double)result.ItemCount;
            double rawChangedBytesPerItem = result.ItemCount == 0 ? 0 : result.PublicationRawChangedBytes / (double)result.ItemCount;
            double deltaCandidateBytesPerItem = result.ItemCount == 0 ? 0 : result.PublicationDeltaCandidateBytes / (double)result.ItemCount;
            double deltaVsFull = result.PublicationFullShelfBytes == 0 ? 0 : result.PublicationDeltaCandidateBytes * 100d / result.PublicationFullShelfBytes;
            double deltaRangesPerShelf = result.PublicationDirtyShelfCount == 0 ? 0 : result.PublicationDeltaCandidateRangeCount / (double)result.PublicationDirtyShelfCount;
            double headerBytesPerShelf = result.PublicationDirtyShelfCount == 0 ? 0 : result.PublicationHeaderDeltaBytes / (double)result.PublicationDirtyShelfCount;
            double slotBytesPerShelf = result.PublicationDirtyShelfCount == 0 ? 0 : result.PublicationSlotDeltaBytes / (double)result.PublicationDirtyShelfCount;
            double itemBytesPerShelf = result.PublicationDirtyShelfCount == 0 ? 0 : result.PublicationItemDeltaBytes / (double)result.PublicationDirtyShelfCount;
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.PublicationDirtyShelfCount} | {fullBytesPerItem:F2} | {rawChangedBytesPerItem:F2} | {deltaCandidateBytesPerItem:F2} | {deltaVsFull:F2}% | {deltaRangesPerShelf:F3} | {headerBytesPerShelf:F2} | {slotBytesPerShelf:F2} | {itemBytesPerShelf:F2} | {result.PublicationMaxDeltaCandidateBytesPerShelf} | {result.PublicationFullShelfBetterOrEqualCount} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Shelf-Local Delta Grouping Candidates");
        builder.AppendLine();
        builder.AppendLine("| scenario | dirty shelves | ungrouped ranges/shelf | ungrouped B/item | positive gaps/shelf | positive gap B/shelf | max gap B | 512 ranges/shelf | 512 B/item | 1024 ranges/shelf | 1024 B/item | 4096 ranges/shelf | 4096 B/item | 8192 ranges/shelf | 8192 B/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            double dirtyShelves = result.DeltaShelfCount;
            double ungroupedRangesPerShelf = dirtyShelves == 0 ? 0 : result.DeltaUngroupedSpanCount / dirtyShelves;
            double ungroupedBytesPerItem = result.ItemCount == 0 ? 0 : result.DeltaUngroupedBytes / (double)result.ItemCount;
            double positiveGapsPerShelf = dirtyShelves == 0 ? 0 : result.DeltaPositiveGapCount / dirtyShelves;
            double positiveGapBytesPerShelf = dirtyShelves == 0 ? 0 : result.DeltaPositiveGapBytes / dirtyShelves;
            double grouped512RangesPerShelf = dirtyShelves == 0 ? 0 : result.DeltaGrouped512SpanCount / dirtyShelves;
            double grouped512BytesPerItem = result.ItemCount == 0 ? 0 : result.DeltaGrouped512Bytes / (double)result.ItemCount;
            double grouped1024RangesPerShelf = dirtyShelves == 0 ? 0 : result.DeltaGrouped1024SpanCount / dirtyShelves;
            double grouped1024BytesPerItem = result.ItemCount == 0 ? 0 : result.DeltaGrouped1024Bytes / (double)result.ItemCount;
            double grouped4096RangesPerShelf = dirtyShelves == 0 ? 0 : result.DeltaGrouped4096SpanCount / dirtyShelves;
            double grouped4096BytesPerItem = result.ItemCount == 0 ? 0 : result.DeltaGrouped4096Bytes / (double)result.ItemCount;
            double grouped8192RangesPerShelf = dirtyShelves == 0 ? 0 : result.DeltaGrouped8192SpanCount / dirtyShelves;
            double grouped8192BytesPerItem = result.ItemCount == 0 ? 0 : result.DeltaGrouped8192Bytes / (double)result.ItemCount;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.DeltaShelfCount} | {ungroupedRangesPerShelf:F3} | {ungroupedBytesPerItem:F2} | {positiveGapsPerShelf:F3} | {positiveGapBytesPerShelf:F2} | {result.DeltaMaxPositiveGapBytes} | {grouped512RangesPerShelf:F3} | {grouped512BytesPerItem:F2} | {grouped1024RangesPerShelf:F3} | {grouped1024BytesPerItem:F2} | {grouped4096RangesPerShelf:F3} | {grouped4096BytesPerItem:F2} | {grouped8192RangesPerShelf:F3} | {grouped8192BytesPerItem:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| scenario | written bytes vs planned | commit wall share | same-shelf revisit rate |");
        builder.AppendLine("|---|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8WriteAttributionResult result = results[i];
            double writtenVsPlanned = result.PlannedBytesPerItem <= 0 ? 0 : result.WrittenBytesPerItem * 100d / result.PlannedBytesPerItem;
            double commitShare = result.MicrosecondsPerItem <= 0 ? 0 : (result.CommitWallNsPerItem / 1000d) * 100d / result.MicrosecondsPerItem;
            double revisitRate = result.PlannedShelfRewriteCount <= 0 ? 0 : result.SameShelfRewriteRevisitCount * 100d / result.PlannedShelfRewriteCount;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {writtenVsPlanned:F2}% | {commitShare:F2}% | {revisitRate:F2}% |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- If insert ns/item dominates after shelf-cache staging has collapsed, the next lower-layer question is route walking, route-target classification, cached-shelf lower-bound search, slot movement, or split construction CPU.");
        builder.AppendLine("- The cached insert CPU breakdown is instrumentation-heavy, so compare phase proportions first and absolute throughput second.");
        builder.AppendLine("- If route-cache hit rate is high and root lookup plus route walk remain high, the cache key is too narrow or cache probing is losing to route reuse.");
        builder.AppendLine("- If staged segments per batch is much lower than inserted items per batch, batch-local shelf caching is reducing physical staging pressure and the remaining gap is mostly CPU before commit.");
        builder.AppendLine("- Dirty shelf delta candidate estimates the practical three-region write shape: changed header span, changed slot span, and changed item-payload span.");
        builder.AppendLine("- If delta candidate bytes/item is far below full shelf bytes/item with only a few ranges per shelf, a physical delta publication path is the next byte-pressure candidate.");
        builder.AppendLine("- Same-shelf revisit rate remains a causal diagnostic: high revisit counts mean the workload repeatedly targets the same shelf, but cached staging should keep those revisits from becoming one full staged rewrite per item.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating public-wrapper bulk-read report and archives the previous current report.<br/>
    /// The report validates and measures `Scalar8Scalar8Index.ReadEncodedRange` over a tree created only through public batch writes.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The setup batch count.</param>
    /// <param name="itemsPerBatch">The setup items per batch.</param>
    /// <param name="prefixCount">The setup root-prefix count.</param>
    /// <param name="iterations">The measured read iterations per row.</param>
    /// <param name="localityMode">The public batch write ordering used during setup.</param>
    /// <param name="results">The measured public bulk-read rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8PublicBulkReadReport(
        string artifactDirectory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        Scalar8Scalar8BulkWriteLocalityMode localityMode,
        ReadOnlySpan<Scalar8Scalar8PublicBulkReadResult> results)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-public-bulk-read-current.md");
        ArchiveCurrentReport(reportPath, "ss8-8-public-bulk-read");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Public Bulk Read - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Setup batches: `{batches}`");
        builder.AppendLine($"- Setup items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Setup root prefixes: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per row: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{(results.Length == 0 ? 0 : results[0].SampleCount)}`");
        builder.AppendLine($"- Setup write locality mode: `{localityMode}`");
        builder.AppendLine("- Setup uses public `LibraDex.Indexes.SS88.Create` plus `Scalar8Scalar8Batch`.");
        builder.AppendLine("- Measurement reopens the file and reads through public `Scalar8Scalar8Index.ReadEncodedRange`.");
        builder.AppendLine($"- Raw read baseline: `{FileReserveReadBaselineMiBs:F2} MiB/s`");
        builder.AppendLine("- `ids/sec vs prev` and `ns/id vs prev` compare against the prior 250-batch public-wrapper checkpoint.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | iterations | range identities | elapsed ms | identities/sec | ids/sec vs prev | ns/identity | ns/id vs prev | reads/range | bytes/range | effective MiB/s | raw read % | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8PublicBulkReadResult result = results[i];
            double effectiveMiBs = CalculateMiBs(result.BytesPerRange * result.Iterations, result.Elapsed.TotalSeconds);
            double rawReadPercent = CalculateBaselinePercent(effectiveMiBs, FileReserveReadBaselineMiBs);
            double previousIdentitiesPerSecond = GetPreviousPublicReadIdentitiesPerSecond(result.Name);
            double previousNsPerIdentity = GetPreviousPublicReadNsPerIdentity(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.Iterations} | {result.RangeIdentityCount} | {result.Elapsed.TotalMilliseconds:F3} | {result.IdentitiesPerSecond:F2} | {FormatPercentChange(result.IdentitiesPerSecond, previousIdentitiesPerSecond)} | {result.NsPerIdentity:F2} | {FormatPercentChange(result.NsPerIdentity, previousNsPerIdentity)} | {result.ReadsPerRange:F3} | {result.BytesPerRange:F2} | {effectiveMiBs:F2} | {FormatBaselinePercent(rawReadPercent)} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| scenario | raw read % | identities/sec vs previous | ns/identity vs previous |");
        builder.AppendLine("|---|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8PublicBulkReadResult result = results[i];
            double effectiveMiBs = CalculateMiBs(result.BytesPerRange * result.Iterations, result.Elapsed.TotalSeconds);
            double rawReadPercent = CalculateBaselinePercent(effectiveMiBs, FileReserveReadBaselineMiBs);
            double previousIdentitiesPerSecond = GetPreviousPublicReadIdentitiesPerSecond(result.Name);
            double previousNsPerIdentity = GetPreviousPublicReadNsPerIdentity(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {FormatBaselinePercent(rawReadPercent)} | {FormatPercentChange(result.IdentitiesPerSecond, previousIdentitiesPerSecond)} | {FormatPercentChange(result.NsPerIdentity, previousNsPerIdentity)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- This probe verifies public range reads after a public bulk-write build and reopen boundary.");
        builder.AppendLine("- `identities/sec` and `ns/identity` are the headline read metrics.");
        builder.AppendLine("- `reads/range` and `bytes/range` diagnose route depth, shelf count, and coalescing behavior.");
        builder.AppendLine("- A positive `ids/sec vs prev` is desirable; a negative `ns/id vs prev` is desirable.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating typed unsigned routed `SS8-8` bulk-write comparison report and archives the previous current report.<br/>
    /// The report compares typed facade throughput and write shape against the current encoded public-wrapper median checkpoint.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The measured batch count per row.</param>
    /// <param name="warmupBatches">The warmup batch count per row.</param>
    /// <param name="itemsPerBatch">The logical items inserted per committed batch.</param>
    /// <param name="prefixCount">The number of root prefixes covered by each generated batch.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by the typed wrapper.</param>
    /// <param name="results">The measured typed routed bulk-write rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteUnsignedScalar8Scalar8RoutedBulkWriteReport(
        string artifactDirectory,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        Scalar8Scalar8Profile profile,
        Scalar8Scalar8RoutedBulkWriteResult[] results)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-typed-routed-bulk-write-current.md");
        ArchiveCurrentReport(reportPath, "ss8-8-typed-routed-bulk-write");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Typed Routed Bulk Write - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches per row: `{batches}`");
        builder.AppendLine($"- Warmup batches per row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Repeat samples per row: `{(results.Length == 0 ? 0 : results[0].SampleCount)}`");
        builder.AppendLine("- Rows use `LibraDex.Indexes.SS88.Unsigned.Create` and `UnsignedScalar8Scalar8Batch`.");
        builder.AppendLine("- `vs encoded` columns compare against the current encoded public-wrapper median checkpoint.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | items/sec | items/sec vs encoded | us/item | writes/batch | bytes/item | bytes/item vs encoded | setLength | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            double encodedItemsPerSecond = GetEncodedMedianPublicBulkWriteItemsPerSecond(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {FormatPercentChange(result.ItemsPerSecond, encodedItemsPerSecond)} | {result.MicrosecondsPerItem:F3} | {result.WritesPerBatch:F3} | {result.BytesPerItem:F2} | {FormatPercentChange(result.BytesPerItem, EncodedMedianPublicBulkWriteBytesPerItem)} | {result.SetLengthCallCount} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| scenario | items/sec vs encoded | bytes/item vs encoded |");
        builder.AppendLine("|---|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            double encodedItemsPerSecond = GetEncodedMedianPublicBulkWriteItemsPerSecond(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {FormatPercentChange(result.ItemsPerSecond, encodedItemsPerSecond)} | {FormatPercentChange(result.BytesPerItem, EncodedMedianPublicBulkWriteBytesPerItem)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- Typed rows should preserve byte/item, writes/batch, checksum, and `SetLength=0` when compared to encoded rows.");
        builder.AppendLine("- Throughput drift should be treated as typed facade overhead only when it persists across median repeat samples.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating typed unsigned public bulk-read comparison report and archives the previous current report.<br/>
    /// The report compares typed facade range-read throughput against the current encoded public-wrapper median checkpoint.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The setup batch count.</param>
