    /// <returns>The report path.</returns>
    private static string WriteUnsignedScalar8Scalar8PublicBulkReadReport(
        string artifactDirectory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        ReadOnlySpan<Scalar8Scalar8PublicBulkReadResult> results)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-typed-public-bulk-read-current.md");
