        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Typed Public Bulk Read - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Setup batches: `{batches}`");
        builder.AppendLine($"- Setup items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Setup root prefixes: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per sample: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{(results.Length == 0 ? 0 : results[0].SampleCount)}`");
        builder.AppendLine("- Setup and reads use public `LibraDex.Indexes.SS88.Unsigned` wrappers.");
        builder.AppendLine("- `vs encoded` columns compare against the current encoded public-wrapper median checkpoint.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | range identities | identities/sec | ids/sec vs encoded | ns/identity | ns/id vs encoded | reads/range | bytes/range | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8PublicBulkReadResult result = results[i];
            double encodedIdentitiesPerSecond = GetEncodedMedianPublicReadIdentitiesPerSecond(result.Name);
            double encodedNsPerIdentity = GetEncodedMedianPublicReadNsPerIdentity(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.RangeIdentityCount} | {result.IdentitiesPerSecond:F2} | {FormatPercentChange(result.IdentitiesPerSecond, encodedIdentitiesPerSecond)} | {result.NsPerIdentity:F2} | {FormatPercentChange(result.NsPerIdentity, encodedNsPerIdentity)} | {result.ReadsPerRange:F3} | {result.BytesPerRange:F2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| scenario | identities/sec vs encoded | ns/identity vs encoded |");
        builder.AppendLine("|---|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8PublicBulkReadResult result = results[i];
            double encodedIdentitiesPerSecond = GetEncodedMedianPublicReadIdentitiesPerSecond(result.Name);
            double encodedNsPerIdentity = GetEncodedMedianPublicReadNsPerIdentity(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {FormatPercentChange(result.IdentitiesPerSecond, encodedIdentitiesPerSecond)} | {FormatPercentChange(result.NsPerIdentity, encodedNsPerIdentity)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- Typed rows should preserve reads/range, bytes/range, and checksum when compared to encoded rows.");
        builder.AppendLine("- Throughput drift should be treated as typed facade overhead only when it persists across median repeat samples.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating public read-target locality report and archives the previous current report.<br/>
    /// The report is a diagnostic companion to public bulk-read perf and explains whether adjacent shelf coalescing has useful contiguous targets to combine.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The setup batch count.</param>
    /// <param name="itemsPerBatch">The setup items per batch.</param>
    /// <param name="prefixCount">The setup root-prefix count.</param>
    /// <param name="localityMode">The public batch write ordering used during setup.</param>
    /// <param name="results">The target-locality diagnostic rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8PublicReadTargetsReport(
        string artifactDirectory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        Scalar8Scalar8BulkWriteLocalityMode localityMode,
        ReadOnlySpan<Scalar8Scalar8PublicReadTargetResult> results)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-public-read-targets-current.md");
        ArchiveCurrentReport(reportPath, "ss8-8-public-read-targets");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Public Read Targets - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Setup batches: `{batches}`");
        builder.AppendLine($"- Setup items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Setup root prefixes: `{prefixCount}`");
        builder.AppendLine($"- Setup write locality mode: `{localityMode}`");
        builder.AppendLine("- Setup uses public `LibraDex.Indexes.SS88.Create` plus `Scalar8Scalar8Batch`.");
        builder.AppendLine("- Diagnostics reopen with `LibraDexFileSession` and enumerate route targets without reading shelf payloads.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| range | distinct shelves | contiguous runs | max run shelves | avg run shelves | duplicate target skips | router targets | max depth | first offsets |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8PublicReadTargetResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.DistinctShelfCount} | {result.ContiguousRunCount} | {result.MaxContiguousRunShelves} | {result.AverageContiguousRunShelves:F2} | {result.DuplicateTargetSkipCount} | {result.RouterTargetCount} | {result.MaxRouterDepth} | {result.FirstOffsets} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- `distinct shelves` is the number of unique shelf extents the range has to inspect in route order.");
        builder.AppendLine("- `contiguous runs` is the best case for the current adjacent-shelf coalescing reader.");
        builder.AppendLine("- If contiguous runs are close to distinct shelves, the issue is allocation locality or traversal flushing, not public wrapper overhead.");
        builder.AppendLine("- If contiguous runs are low but read telemetry stays high, the issue is likely the coalescing gate or traversal implementation.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating public bulk-build growth report and archives the previous current report.<br/>
    /// The report ties bulk-write bytes/item to final file length and live metadata/router/shelf bytes so structural counts stay diagnostic.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The setup batch count.</param>
    /// <param name="itemsPerBatch">The setup item count per batch.</param>
    /// <param name="prefixCount">The setup root-prefix count.</param>
    /// <param name="localityMode">The public batch write ordering used during setup.</param>
    /// <param name="result">The measured public growth result.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8PublicGrowthReport(
        string artifactDirectory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        Scalar8Scalar8BulkWriteLocalityMode localityMode,
        Scalar8Scalar8PublicGrowthResult result)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "ss8-8-public-growth-current.md");
        ArchiveCurrentReport(reportPath, "ss8-8-public-growth");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Public Growth - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Setup batches: `{batches}`");
        builder.AppendLine($"- Setup items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Setup root prefixes: `{prefixCount}`");
        builder.AppendLine($"- Repeat samples: `{result.SampleCount}`");
        builder.AppendLine($"- Setup write locality mode: `{localityMode}`");
        builder.AppendLine("- Setup uses public `LibraDex.Indexes.SS88.Create` plus `Scalar8Scalar8Batch`.");
        builder.AppendLine("- Diagnostics reopen with `LibraDexFileSession` and traverse unique live route targets from the index handle.");
        builder.AppendLine($"- Raw payload baseline: `{Scalar8Scalar8Layout.ItemSize}` bytes/item");
        builder.AppendLine($"- Raw shelf-capacity baseline: `{Scalar8Scalar8Layout.ItemSize + Scalar8Scalar8Layout.SlotSize}` bytes/slot");
        builder.AppendLine("- `vs prev` columns compare against the prior 250-batch public-wrapper growth checkpoint.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| samples | final bytes | live bytes | metadata | routers bytes | shelves bytes | overhead bytes | routers | shelves | items | capacity | occ % | free slots | free shelf bytes | file bytes/item | file vs raw 16B | file vs prev | live bytes/item | live vs raw 18B | live vs prev | overhead bytes/item | overhead vs prev | written bytes/item | written vs prev | writes/batch | writes vs prev | setLength | checksum |");
        builder.AppendLine("|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.SampleCount} | {result.FinalLength} | {result.LiveStructureBytes} | {result.MetadataBytes} | {result.RouterBytes} | {result.ShelfBytes} | {result.OverheadBytes} | {result.RouterCount} | {result.ShelfCount} | {result.ItemCount} | {result.ShelfCapacity} | {result.ShelfOccupancyPercent:F2} | {result.FreeItemSlots} | {result.ShelfFreeCapacityBytes} | {result.FileBytesPerItem:F2} | {FormatPercentDistance(result.FileBytesPerItem, Scalar8Scalar8Layout.ItemSize)} | {FormatPercentChange(result.FileBytesPerItem, PreviousPublicGrowthFileBytesPerItem)} | {result.LiveBytesPerItem:F2} | {FormatPercentDistance(result.LiveBytesPerItem, Scalar8Scalar8Layout.ItemSize + Scalar8Scalar8Layout.SlotSize)} | {FormatPercentChange(result.LiveBytesPerItem, PreviousPublicGrowthLiveBytesPerItem)} | {result.OverheadBytesPerItem:F2} | {FormatPercentChange(result.OverheadBytesPerItem, PreviousPublicGrowthOverheadBytesPerItem)} | {result.WrittenBytesPerItem:F2} | {FormatPercentChange(result.WrittenBytesPerItem, PreviousPublicGrowthWrittenBytesPerItem)} | {result.WritesPerBatch:F3} | {FormatPercentChange(result.WritesPerBatch, PreviousPublicGrowthWritesPerBatch)} | {result.SetLengthCallCount} | {result.Checksum} |");

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| metric | raw baseline distance | previous checkpoint distance |");
        builder.AppendLine("|---|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| file bytes/item | {FormatPercentDistance(result.FileBytesPerItem, Scalar8Scalar8Layout.ItemSize)} | {FormatPercentChange(result.FileBytesPerItem, PreviousPublicGrowthFileBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| live bytes/item | {FormatPercentDistance(result.LiveBytesPerItem, Scalar8Scalar8Layout.ItemSize + Scalar8Scalar8Layout.SlotSize)} | {FormatPercentChange(result.LiveBytesPerItem, PreviousPublicGrowthLiveBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| overhead bytes/item | n/a | {FormatPercentChange(result.OverheadBytesPerItem, PreviousPublicGrowthOverheadBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| written bytes/item | n/a | {FormatPercentChange(result.WrittenBytesPerItem, PreviousPublicGrowthWrittenBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| writes/batch | n/a | {FormatPercentChange(result.WritesPerBatch, PreviousPublicGrowthWritesPerBatch)} |");
        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- `file bytes/item` is the headline disk-footprint metric for the built public index.");
        builder.AppendLine("- `live bytes/item` includes superblock, index directory, live routers, and live shelves reachable from the index handle.");
        builder.AppendLine("- `overhead bytes` is final file length minus that live estimate; it includes reserved transformed-shelf router capacity and any format/setup slack.");
        builder.AppendLine("- Structural counts explain the footprint only when they connect to file bytes/item or raw-baseline-relative throughput.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Measures raw `DataKernel` writing of contiguous 16-byte logical item payloads with one commit per batch.<br/>
    /// The order vector controls generated key identity values so this row shares the same logical item sequence as `SS8-8` rows.<br/>
    /// </summary>
    /// <param name="path">The backing file path for the row.</param>
    /// <param name="name">The report row name.</param>
    /// <param name="batches">The measured batch count.</param>
    /// <param name="warmupBatches">The unmeasured warmup batch count.</param>
    /// <param name="itemsPerBatch">The number of 16-byte items per batch.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <param name="options">The `DataKernel` options.</param>
    /// <returns>The measured write-parity row.</returns>
    private static Scalar8Scalar8WriteParityResult MeasureDataKernelItemStreamWriteParity(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int[] order,
        DataKernelOptions options)
    {
        File.Delete(path);
        using DataKernel kernel = OpenKernel(DataKernelBackingKind.File, path, FileMode.Create, options, DataKernelTelemetryOptions.EnabledOptions);
        _ = RunDataKernelItemStreamWriteParityLoop(kernel, warmupBatches, itemsPerBatch, order);
        Stopwatch watch = Stopwatch.StartNew();
        WriteParityLoopTelemetry telemetry = RunDataKernelItemStreamWriteParityLoop(kernel, batches, itemsPerBatch, order);
        watch.Stop();
        return CreateWriteParityResult(name, batches, itemsPerBatch, watch.Elapsed, telemetry);
    }

    /// <summary>
    /// Measures raw `DataKernel` writing of contiguous fixed-width logical payload rows repeatedly and returns the median throughput sample.<br/>
    /// This gives every current shelf shape a raw append floor at its logical `(key, identity)` byte width without involving router or shelf code.<br/>
    /// </summary>
    /// <param name="path">The base backing file path.</param>
    /// <param name="name">The report row name.</param>
    /// <param name="batches">The measured batch count.</param>
    /// <param name="warmupBatches">The unmeasured warmup batch count.</param>
    /// <param name="itemsPerBatch">The number of payload rows per batch.</param>
    /// <param name="payloadBytes">The fixed logical payload bytes per row.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <param name="options">The `DataKernel` options.</param>
    /// <param name="repeatCount">The number of samples to collect.</param>
    /// <returns>The median raw payload-stream write row.</returns>
    private static Scalar8Scalar8WriteParityResult MeasureRepeatedDataKernelPayloadStreamWriteParity(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int payloadBytes,
        int[] order,
        DataKernelOptions options,
        int repeatCount)
    {
        Scalar8Scalar8WriteParityResult[] samples = new Scalar8Scalar8WriteParityResult[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureDataKernelPayloadStreamWriteParity(CreateRepeatPath(path, i), name, batches, warmupBatches, itemsPerBatch, payloadBytes, order, options);
        }

        return SelectMedianWriteParitySample(samples);
    }

    /// <summary>
    /// Measures one raw `DataKernel` contiguous fixed-width payload stream sample.<br/>
    /// The measured loop writes exactly `itemsPerBatch * payloadBytes` bytes per logical batch and commits once, matching the harness batch cadence without shelf/router work.<br/>
    /// </summary>
    /// <param name="path">The backing file path.</param>
    /// <param name="name">The report row name.</param>
    /// <param name="batches">The measured batch count.</param>
    /// <param name="warmupBatches">The unmeasured warmup batch count.</param>
    /// <param name="itemsPerBatch">The number of payload rows per batch.</param>
    /// <param name="payloadBytes">The fixed logical payload bytes per row.</param>
    /// <param name="order">The deterministic item order vector.</param>
    /// <param name="options">The `DataKernel` options.</param>
    /// <returns>The measured raw payload-stream write row.</returns>
    private static Scalar8Scalar8WriteParityResult MeasureDataKernelPayloadStreamWriteParity(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int payloadBytes,
        int[] order,
        DataKernelOptions options)
    {
        if (payloadBytes <= 0 || payloadBytes % sizeof(ulong) != 0)
        {
            throw new ArgumentOutOfRangeException(nameof(payloadBytes), payloadBytes, "Raw payload bytes must be a positive multiple of eight.");
        }

        File.Delete(path);
        using DataKernel kernel = OpenKernel(DataKernelBackingKind.File, path, FileMode.Create, options, DataKernelTelemetryOptions.EnabledOptions);
        _ = RunDataKernelPayloadStreamWriteParityLoop(kernel, warmupBatches, itemsPerBatch, payloadBytes, order);
        Stopwatch watch = Stopwatch.StartNew();
        WriteParityLoopTelemetry telemetry = RunDataKernelPayloadStreamWriteParityLoop(kernel, batches, itemsPerBatch, payloadBytes, order);
        watch.Stop();
        return CreateWriteParityResult(name, batches, itemsPerBatch, watch.Elapsed, telemetry);
    }

