        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureFixed32Scalar8ReadRange(session, rootRouterOffset, profile, name, batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, iterations, identities) with
