    {
        Console.WriteLine("| scenario | samples | iterations | range identities | identities/sec | ids/sec vs SS8-8 | ns/identity | ns/id vs SS8-8 | logical MiB/s | checksum |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
