    /// <summary>
    /// Opens a SQLite comparison connection and applies the requested journal and synchronous settings.<br/>
    /// The defaults are `WAL` plus `NORMAL`, which keeps one transaction commit per batch while avoiding a full fsync on every batch, matching the current `DataKernel` `FlushToDiskOnCommit=false` evidence more closely than `FULL` synchronous mode.<br/>
    /// </summary>
    /// <param name="path">The SQLite database path.</param>
    /// <param name="options">The SQLite comparison options.</param>
    /// <returns>The opened SQLite connection.</returns>
    private static SqliteConnection OpenSqliteScalar8Scalar8Connection(string path, SqliteScalar8Scalar8Options options)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        SqliteConnection connection = new($"Data Source={path};Mode=ReadWriteCreate;Cache=Shared");
        connection.Open();
        ExecuteSqliteScalar8Scalar8Pragma(connection, "journal_mode", options.JournalMode);
        ExecuteSqliteScalar8Scalar8Pragma(connection, "synchronous", options.Synchronous);
        ExecuteSqliteScalar8Scalar8Pragma(connection, "temp_store", "memory");
        ExecuteSqliteScalar8Scalar8NonQuery(connection, "PRAGMA wal_autocheckpoint=0;");
        return connection;
    }

    /// <summary>
    /// Creates the SQLite comparison table and index shape.<br/>
    /// `WITHOUT ROWID` keeps the primary-key B-tree as the table itself, avoiding an extra rowid B-tree that would not match LibraDex's identity-index role.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    private static void InitializeSqliteScalar8Scalar8Schema(SqliteConnection connection)
    {
        ExecuteSqliteScalar8Scalar8NonQuery(
            connection,
            "CREATE TABLE items(k INTEGER NOT NULL, i INTEGER NOT NULL, PRIMARY KEY(k, i)) WITHOUT ROWID;");
    }

    /// <summary>
    /// Creates the SQLite `SS16-16` BLOB comparison table and index shape.<br/>
    /// `WITHOUT ROWID` keeps the primary-key B-tree as the table itself, while fixed-length checks preserve the 16-byte key and 16-byte identity contract.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    private static void InitializeSqliteScalar16Scalar16BlobSchema(SqliteConnection connection)
    {
        ExecuteSqliteScalar8Scalar8NonQuery(
            connection,
            "CREATE TABLE items(k BLOB NOT NULL CHECK(length(k)=16), i BLOB NOT NULL CHECK(length(i)=16), PRIMARY KEY(k, i)) WITHOUT ROWID;");
    }

    /// <summary>
    /// Creates the SQLite `SS16-8` mixed-width comparison table and index shape.<br/>
    /// `WITHOUT ROWID` keeps the primary-key B-tree as the table itself, while the fixed-length key check preserves the 16-byte key contract.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    private static void InitializeSqliteScalar16Scalar8BlobSchema(SqliteConnection connection)
    {
        ExecuteSqliteScalar8Scalar8NonQuery(
            connection,
            "CREATE TABLE items(k BLOB NOT NULL CHECK(length(k)=16), i INTEGER NOT NULL, PRIMARY KEY(k, i)) WITHOUT ROWID;");
    }

    /// <summary>
    /// Creates the SQLite `SS8-16` mixed-width comparison table and index shape.<br/>
    /// `WITHOUT ROWID` keeps the primary-key B-tree as the table itself, while the fixed-length identity check preserves the 16-byte identity contract.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    private static void InitializeSqliteScalar8Scalar16BlobSchema(SqliteConnection connection)
    {
        ExecuteSqliteScalar8Scalar8NonQuery(
            connection,
            "CREATE TABLE items(k INTEGER NOT NULL, i BLOB NOT NULL CHECK(length(i)=16), PRIMARY KEY(k, i)) WITHOUT ROWID;");
    }

    /// <summary>
    /// Creates the SQLite `FS32-8` mixed-width comparison table and index shape.<br/>
    /// `WITHOUT ROWID` keeps the primary-key B-tree as the table itself, while the fixed-length key check preserves the 32-byte key contract.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    private static void InitializeSqliteFixed32Scalar8BlobSchema(SqliteConnection connection)
    {
        ExecuteSqliteScalar8Scalar8NonQuery(
            connection,
            "CREATE TABLE items(k BLOB NOT NULL CHECK(length(k)=32), i INTEGER NOT NULL, PRIMARY KEY(k, i)) WITHOUT ROWID;");
    }

    /// <summary>
    /// Executes a SQLite non-query command for comparison setup.<br/>
    /// Setup commands are outside measured loops so command allocation does not affect benchmark rows.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    /// <param name="sql">The SQL command to execute.</param>
    private static void ExecuteSqliteScalar8Scalar8NonQuery(SqliteConnection connection, string sql)
    {
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = sql;
        command.ExecuteNonQuery();
    }

    /// <summary>
    /// Applies one SQLite pragma using a restricted token value.<br/>
    /// This keeps command-line options ergonomic while preventing punctuation from becoming executable SQL in benchmark setup.<br/>
    /// </summary>
    /// <param name="connection">The open SQLite connection.</param>
    /// <param name="name">The pragma name.</param>
    /// <param name="value">The requested pragma value.</param>
    private static void ExecuteSqliteScalar8Scalar8Pragma(SqliteConnection connection, string name, string value)
    {
        string normalized = NormalizeSqliteScalar8Scalar8PragmaToken(value);
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = string.Create(CultureInfo.InvariantCulture, $"PRAGMA {name}={normalized};");
        _ = command.ExecuteScalar();
    }

    /// <summary>
    /// Normalizes a command-line pragma token for SQLite setup.<br/>
    /// Only letters, digits, underscores, and hyphens are accepted because the harness only needs simple enum-like SQLite pragma values.<br/>
    /// </summary>
    /// <param name="value">The raw token value.</param>
    /// <returns>The normalized lowercase SQLite pragma token.</returns>
    private static string NormalizeSqliteScalar8Scalar8PragmaToken(string value)
    {
        string trimmed = value.Trim().ToLowerInvariant().Replace("-", "_", StringComparison.Ordinal);
        for (int i = 0; i < trimmed.Length; i++)
        {
            char ch = trimmed[i];
            if (!char.IsAsciiLetterOrDigit(ch) && ch != '_')
            {
                throw new ArgumentOutOfRangeException(nameof(value), value, "SQLite pragma values for this harness must be simple tokens.");
            }
        }

        return trimmed;
    }

    /// <summary>
    /// Creates a fixed 16-byte big-endian SQLite BLOB for one `SS16-16` scalar value.<br/>
    /// SQLite compares BLOB values bytewise, so big-endian unsigned halves preserve the same ordering as the numeric high/low tuple.<br/>
    /// </summary>
    /// <param name="high">The high 64 bits of the scalar value.</param>
    /// <param name="low">The low 64 bits of the scalar value.</param>
    /// <returns>A new 16-byte BLOB value.</returns>
    private static byte[] CreateSqliteScalar16Scalar16Blob(ulong high, ulong low)
    {
        byte[] blob = new byte[16];
        WriteSqliteScalar16Scalar16BigEndianUInt64(blob, 0, high);
        WriteSqliteScalar16Scalar16BigEndianUInt64(blob, 8, low);
        return blob;
    }

    /// <summary>
    /// Creates a fixed 32-byte big-endian SQLite BLOB for one `FS32-8` fixed key.<br/>
    /// SQLite compares BLOB values bytewise, so big-endian unsigned lanes preserve the same ordering as the fixed-key tuple.<br/>
    /// </summary>
    /// <param name="key0">The first 64-bit fixed-key lane.</param>
    /// <param name="key1">The second 64-bit fixed-key lane.</param>
    /// <param name="key2">The third 64-bit fixed-key lane.</param>
    /// <param name="key3">The fourth 64-bit fixed-key lane.</param>
    /// <returns>A new 32-byte BLOB value.</returns>
    private static byte[] CreateSqliteFixed32Scalar8Blob(ulong key0, ulong key1, ulong key2, ulong key3)
    {
        byte[] blob = new byte[32];
        WriteSqliteScalar16Scalar16BigEndianUInt64(blob, 0, key0);
        WriteSqliteScalar16Scalar16BigEndianUInt64(blob, 8, key1);
        WriteSqliteScalar16Scalar16BigEndianUInt64(blob, 16, key2);
        WriteSqliteScalar16Scalar16BigEndianUInt64(blob, 24, key3);
        return blob;
    }

    /// <summary>
    /// Creates the deterministic low half used by SQLite `SS16-16` BLOB comparison values.<br/>
    /// The high half carries the existing routed prefix workload, while this mixed low half ensures SQLite compares full 16-byte values without changing prefix range selection.<br/>
    /// </summary>
    /// <param name="high">The generated high half.</param>
    /// <returns>The deterministic low half.</returns>
    private static ulong CreateSqliteScalar16Scalar16LowHalf(ulong high)
    {
        return unchecked((high << 17) ^ (high >> 23) ^ 0x9E37_79B9_7F4A_7C15UL);
    }

    /// <summary>
    /// Writes one unsigned 64-bit value into a span as big-endian bytes.<br/>
    /// This avoids platform-endianness dependencies in SQLite BLOB ordering tests.<br/>
    /// </summary>
    /// <param name="target">The target span.</param>
    /// <param name="offset">The starting byte offset.</param>
    /// <param name="value">The value to write.</param>
    private static void WriteSqliteScalar16Scalar16BigEndianUInt64(Span<byte> target, int offset, ulong value)
    {
        for (int i = 0; i < sizeof(ulong); i++)
        {
            target[offset + i] = (byte)(value >> ((sizeof(ulong) - 1 - i) * 8));
        }
    }

    /// <summary>
    /// Reads one unsigned 64-bit value from big-endian bytes.<br/>
    /// Returned SQLite identity BLOBs are decoded this way for deterministic validation and checksumming.<br/>
    /// </summary>
    /// <param name="source">The source bytes.</param>
    /// <param name="offset">The starting byte offset.</param>
    /// <returns>The decoded unsigned value.</returns>
    private static ulong ReadSqliteScalar16Scalar16BigEndianUInt64(ReadOnlySpan<byte> source, int offset)
    {
        ulong value = 0;
        for (int i = 0; i < sizeof(ulong); i++)
        {
            value = (value << 8) | source[offset + i];
        }

        return value;
    }

    /// <summary>
    /// Deletes a SQLite database and its common sidecar files before a fresh sample.<br/>
    /// WAL, shared-memory, and rollback-journal sidecars are included so repeated samples do not inherit storage or checkpoint state from earlier runs.<br/>
    /// </summary>
    /// <param name="path">The base SQLite database path.</param>
    private static void ResetSqliteScalar8Scalar8Files(string path)
    {
        File.Delete(path);
        File.Delete(path + "-wal");
        File.Delete(path + "-shm");
        File.Delete(path + "-journal");
    }

    /// <summary>
    /// Returns the SQLite storage footprint across the main database and common sidecar files.<br/>
    /// WAL mode can hold recently committed pages outside the main database, so sidecars are counted as part of the current file-backed footprint.<br/>
    /// </summary>
    /// <param name="path">The base SQLite database path.</param>
    /// <returns>The total byte length of existing SQLite files.</returns>
    private static long GetSqliteScalar8Scalar8StorageBytes(string path)
    {
        long total = 0;
        total += GetExistingFileLength(path);
        total += GetExistingFileLength(path + "-wal");
        total += GetExistingFileLength(path + "-shm");
        total += GetExistingFileLength(path + "-journal");
        return total;
    }

    /// <summary>
    /// Returns the length of an existing file or zero when the file is absent.<br/>
    /// This supports SQLite sidecar footprint accounting without treating absent sidecars as an error.<br/>
    /// </summary>
    /// <param name="path">The file path to inspect.</param>
    /// <returns>The file length, or zero when the file does not exist.</returns>
    private static long GetExistingFileLength(string path)
    {
        return File.Exists(path) ? new FileInfo(path).Length : 0;
    }

    /// <summary>
    /// Encodes an unsigned sortable scalar into SQLite's signed integer order.<br/>
    /// Flipping the high bit maps unsigned order onto signed `INTEGER` order, so SQLite B-tree comparisons match `SS8-8` unsigned scalar route and shelf ordering.<br/>
    /// </summary>
    /// <param name="value">The encoded unsigned scalar value.</param>
    /// <returns>The signed integer value to store in SQLite.</returns>
    private static long EncodeSqliteSortableUnsignedScalar8(ulong value)
    {
        return unchecked((long)(value ^ 0x8000_0000_0000_0000UL));
    }

    /// <summary>
    /// Decodes a SQLite signed integer value back to the unsigned sortable scalar identity.<br/>
    /// This is the inverse of `EncodeSqliteSortableUnsignedScalar8` and preserves byte-for-byte identity validation against LibraDex expected keys.<br/>
    /// </summary>
    /// <param name="value">The signed SQLite integer value.</param>
    /// <returns>The decoded unsigned scalar value.</returns>
    private static ulong DecodeSqliteSortableUnsignedScalar8(long value)
    {
        return unchecked((ulong)value) ^ 0x8000_0000_0000_0000UL;
    }

    /// <summary>
    /// Writes the rotating SQLite comparison report and archives the previous current report.<br/>
    /// The report compares SQLite's B-tree behavior against the current public encoded `SS8-8` median checkpoints for the same generated workload shape.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The measured write batch count and read setup batch count.</param>
    /// <param name="warmupBatches">The unmeasured write warmup batch count.</param>
    /// <param name="itemsPerBatch">The item count per batch.</param>
    /// <param name="prefixCount">The number of root-prefix buckets covered by generated keys.</param>
    /// <param name="iterations">The measured read iterations per sample.</param>
    /// <param name="options">The SQLite durability and journaling options.</param>
    /// <param name="writeResults">The measured SQLite write rows.</param>
    /// <param name="readResults">The measured SQLite read rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteSqliteScalar8Scalar8ComparisonReport(
        string artifactDirectory,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        SqliteScalar8Scalar8Options options,
        ReadOnlySpan<SqliteScalar8Scalar8WriteResult> writeResults,
        ReadOnlySpan<SqliteScalar8Scalar8ReadResult> readResults)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "sqlite-ss8-8-comparison-current.md");
        ArchiveCurrentReport(reportPath, "sqlite-ss8-8-comparison");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SQLite SS8-8 Comparison - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches per write row: `{batches}`");
        builder.AppendLine($"- Warmup batches per write row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per sample: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{(writeResults.Length == 0 ? 0 : writeResults[0].SampleCount)}`");
        builder.AppendLine($"- SQLite journal mode: `{options.JournalMode}`");
        builder.AppendLine($"- SQLite synchronous mode: `{options.Synchronous}`");
        builder.AppendLine("- SQLite schema: `CREATE TABLE items(k INTEGER NOT NULL, i INTEGER NOT NULL, PRIMARY KEY(k, i)) WITHOUT ROWID`.");
        builder.AppendLine("- SQLite stores order-preserving signed integer transforms of the same encoded unsigned `SS8-8` keys and identities.");
        builder.AppendLine("- Write rows use one explicit SQLite transaction per LibraDex logical batch.");
        builder.AppendLine("- Read rows reopen the SQLite database and use ordered range scans over the primary-key B-tree.");
        builder.AppendLine();
        builder.AppendLine("## Write Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | items/sec | items/sec vs SS8-8 | us/item | batches/sec | storage bytes | storage bytes/item | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < writeResults.Length; i++)
        {
            SqliteScalar8Scalar8WriteResult result = writeResults[i];
            double encodedItemsPerSecond = GetEncodedMedianPublicBulkWriteItemsPerSecond(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {FormatPercentChange(result.ItemsPerSecond, encodedItemsPerSecond)} | {result.MicrosecondsPerItem:F3} | {result.BatchesPerSecond:F2} | {result.StorageBytes} | {result.StorageBytesPerItem:F2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Read Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | iterations | range identities | identities/sec | ids/sec vs SS8-8 | ns/identity | ns/id vs SS8-8 | logical MiB/s | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < readResults.Length; i++)
        {
            SqliteScalar8Scalar8ReadResult result = readResults[i];
            double encodedIdentitiesPerSecond = GetEncodedMedianPublicReadIdentitiesPerSecond(result.Name);
            double encodedNsPerIdentity = GetEncodedMedianPublicReadNsPerIdentity(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.Iterations} | {result.RangeIdentityCount} | {result.IdentitiesPerSecond:F2} | {FormatPercentChange(result.IdentitiesPerSecond, encodedIdentitiesPerSecond)} | {result.NsPerIdentity:F2} | {FormatPercentChange(result.NsPerIdentity, encodedNsPerIdentity)} | {result.LogicalMiBs:F2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| scenario | throughput vs SS8-8 | latency/size vs SS8-8 |");
        builder.AppendLine("|---|---:|---:|");
        for (int i = 0; i < writeResults.Length; i++)
        {
            SqliteScalar8Scalar8WriteResult result = writeResults[i];
            double encodedItemsPerSecond = GetEncodedMedianPublicBulkWriteItemsPerSecond(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} items/sec | {FormatPercentChange(result.ItemsPerSecond, encodedItemsPerSecond)} | n/a |");
        }

        for (int i = 0; i < readResults.Length; i++)
        {
            SqliteScalar8Scalar8ReadResult result = readResults[i];
            double encodedIdentitiesPerSecond = GetEncodedMedianPublicReadIdentitiesPerSecond(result.Name);
            double encodedNsPerIdentity = GetEncodedMedianPublicReadNsPerIdentity(result.Name);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} read | {FormatPercentChange(result.IdentitiesPerSecond, encodedIdentitiesPerSecond)} | {FormatPercentChange(result.NsPerIdentity, encodedNsPerIdentity)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- This is a competitor guardrail, not a claim that SQLite and LibraDex have identical durability or feature scope.");
        builder.AppendLine("- `WAL` plus `NORMAL` keeps transaction commit boundaries explicit while avoiding full fsync on every batch, similar to the current `FlushToDiskOnCommit=false` LibraDex perf setup.");
        builder.AppendLine("- SQLite storage bytes include the main database and common sidecars because WAL mode can hold committed pages outside the main file.");
        builder.AppendLine("- Logical read MiB/s uses `16` payload bytes per returned identity; SQLite physical page-cache movement is not exposed by this harness.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating SQLite `SS16-16` BLOB comparison report and archives the previous current report.<br/>
    /// This report is a competitor guardrail for likely SQLite usage where 16-byte keys and identities are stored as fixed-width BLOB values.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The measured write batch count and read setup batch count.</param>
    /// <param name="warmupBatches">The unmeasured write warmup batch count.</param>
    /// <param name="itemsPerBatch">The item count per batch.</param>
    /// <param name="prefixCount">The number of root-prefix buckets covered by generated keys.</param>
    /// <param name="iterations">The measured read iterations per sample.</param>
    /// <param name="options">The SQLite durability and journaling options.</param>
    /// <param name="writeResults">The measured SQLite BLOB write rows.</param>
    /// <param name="readResults">The measured SQLite BLOB read rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteSqliteScalar16Scalar16BlobComparisonReport(
        string artifactDirectory,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        SqliteScalar8Scalar8Options options,
        ReadOnlySpan<SqliteScalar8Scalar8WriteResult> writeResults,
        ReadOnlySpan<SqliteScalar8Scalar8ReadResult> readResults)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "sqlite-ss16-16-comparison-current.md");
        ArchiveCurrentReport(reportPath, "sqlite-ss16-16-comparison");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SQLite SS16-16 BLOB Comparison - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches per write row: `{batches}`");
        builder.AppendLine($"- Warmup batches per write row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per sample: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{(writeResults.Length == 0 ? 0 : writeResults[0].SampleCount)}`");
        builder.AppendLine($"- SQLite journal mode: `{options.JournalMode}`");
        builder.AppendLine($"- SQLite synchronous mode: `{options.Synchronous}`");
        builder.AppendLine("- SQLite schema: `CREATE TABLE items(k BLOB NOT NULL CHECK(length(k)=16), i BLOB NOT NULL CHECK(length(i)=16), PRIMARY KEY(k, i)) WITHOUT ROWID`.");
        builder.AppendLine("- SQLite stores fixed 16-byte big-endian BLOBs so binary B-tree ordering matches unsigned high/low tuple ordering.");
        builder.AppendLine("- Write rows use one explicit SQLite transaction per logical batch.");
        builder.AppendLine("- Read rows reopen the SQLite database and use ordered range scans over the primary-key B-tree.");
        builder.AppendLine();
        builder.AppendLine("## Write Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | items/sec | us/item | batches/sec | storage bytes | storage bytes/item | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < writeResults.Length; i++)
        {
            SqliteScalar8Scalar8WriteResult result = writeResults[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {result.MicrosecondsPerItem:F3} | {result.BatchesPerSecond:F2} | {result.StorageBytes} | {result.StorageBytesPerItem:F2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Read Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | iterations | range identities | identities/sec | ns/identity | logical MiB/s | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < readResults.Length; i++)
        {
            SqliteScalar8Scalar8ReadResult result = readResults[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.Iterations} | {result.RangeIdentityCount} | {result.IdentitiesPerSecond:F2} | {result.NsPerIdentity:F2} | {result.LogicalMiBs:F2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- This is the likely SQLite parity shape for GUID-like 16-byte keys and identities.");
        builder.AppendLine("- `WAL` plus `NORMAL` keeps transaction commit boundaries explicit while avoiding full fsync on every batch.");
        builder.AppendLine("- SQLite storage bytes include the main database and common sidecars because WAL mode can hold committed pages outside the main file.");
        builder.AppendLine("- Logical read MiB/s uses `32` payload bytes per returned identity, matching the `SS16-16` key plus identity item width.");
        builder.AppendLine("- There is not yet a public LibraDex `SS16-16` bulk-write/read command, so this report does not calculate percent deltas against LibraDex.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating all-shape write-parity report and archives the previous current report.<br/>
    /// The report compares each current fixed scalar shelf shape against the likely SQLite write schema and a raw contiguous `DataKernel` payload floor for the same generated cadence.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The measured write batch count.</param>
    /// <param name="warmupBatches">The unmeasured write warmup batch count.</param>
    /// <param name="itemsPerBatch">The item count per batch.</param>
    /// <param name="prefixCount">The number of root-prefix buckets covered by generated keys.</param>
    /// <param name="repeatCount">The number of repeated samples per row.</param>
    /// <param name="scalar8Scalar8CommitGapCoalesceBytes">The `SS8-8` `DataKernel` commit gap coalescing setting.</param>
    /// <param name="wideCommitGapCoalesceBytes">The wider-shape `DataKernel` commit gap coalescing setting.</param>
    /// <param name="sqliteOptions">The SQLite durability and journaling options.</param>
    /// <param name="rows">The measured parity rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteAllShapeWriteParityReport(
        string artifactDirectory,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int repeatCount,
        int scalar8Scalar8CommitGapCoalesceBytes,
        int wideCommitGapCoalesceBytes,
        SqliteScalar8Scalar8Options sqliteOptions,
        ReadOnlySpan<AllShapeWriteParityRow> rows)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "all-shape-write-parity-current.md");
        ArchiveCurrentReport(reportPath, "all-shape-write-parity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# All-Shape Write Parity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches per write row: `{batches}`");
        builder.AppendLine($"- Warmup batches per write row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- `SS8-8` commit gap coalescing bytes: `{scalar8Scalar8CommitGapCoalesceBytes}`");
        builder.AppendLine($"- Wider-shape commit gap coalescing bytes: `{wideCommitGapCoalesceBytes}`");
        builder.AppendLine($"- SQLite journal mode: `{sqliteOptions.JournalMode}`");
        builder.AppendLine($"- SQLite synchronous mode: `{sqliteOptions.Synchronous}`");
        builder.AppendLine("- SQLite schemas use `WITHOUT ROWID` primary-key B-trees.");
        builder.AppendLine("- `SS8-8` SQLite uses `INTEGER` / `INTEGER`.");
        builder.AppendLine("- `SS16-8` SQLite uses fixed `BLOB(16)` / `INTEGER`.");
        builder.AppendLine("- `SS8-16` SQLite uses `INTEGER` / fixed `BLOB(16)`.");
        builder.AppendLine("- `SS16-16` SQLite uses fixed `BLOB(16)` / fixed `BLOB(16)`.");
        builder.AppendLine("- `FS32-8` SQLite uses fixed `BLOB(32)` / `INTEGER`.");
        builder.AppendLine("- Raw `DataKernel` rows write contiguous logical payloads of `16`, `24`, `32`, or `40` bytes/item with one commit per batch.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| shape | order | payload B | LibraDex items/sec | SQLite items/sec | raw DK items/sec | LibraDex/SQLite | LibraDex/raw | LibraDex B/item | SQLite storage B/item | raw DK B/item | LibraDex writes/batch | raw DK writes/batch | LibraDex setLength | SQLite storage bytes |");
        builder.AppendLine("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Length; i++)
        {
            AllShapeWriteParityRow row = rows[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Shape} | {row.OrderName} | {row.PayloadBytes} | {row.LibraDex.ItemsPerSecond:F2} | {row.Sqlite.ItemsPerSecond:F2} | {row.RawDataKernel.ItemsPerSecond:F2} | {FormatMultiplier(row.LibraDex.ItemsPerSecond, row.Sqlite.ItemsPerSecond)} | {FormatMultiplier(row.LibraDex.ItemsPerSecond, row.RawDataKernel.ItemsPerSecond)} | {row.LibraDex.BytesPerItem:F2} | {row.Sqlite.StorageBytesPerItem:F2} | {row.RawDataKernel.BytesPerItem:F2} | {row.LibraDex.WritesPerBatch:F3} | {row.RawDataKernel.WritesPerBatch:F3} | {row.LibraDex.SetLengthCallCount} | {row.Sqlite.StorageBytes} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Latency");
        builder.AppendLine();
        builder.AppendLine("| shape | order | LibraDex us/item | SQLite us/item | raw DK us/item | SQLite B/item vs raw payload | LibraDex written B/item vs raw payload |");
        builder.AppendLine("|---|---|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Length; i++)
        {
            AllShapeWriteParityRow row = rows[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Shape} | {row.OrderName} | {row.LibraDex.MicrosecondsPerItem:F3} | {row.Sqlite.MicrosecondsPerItem:F3} | {row.RawDataKernel.MicrosecondsPerItem:F3} | {FormatPercentDistance(row.Sqlite.StorageBytesPerItem, row.PayloadBytes)} | {FormatPercentDistance(row.LibraDex.BytesPerItem, row.PayloadBytes)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation Notes");
        builder.AppendLine();
        builder.AppendLine("- This is a write-side guardrail, not a read parity suite.");
        builder.AppendLine("- SQLite storage bytes include the main database and common sidecars because WAL mode can hold committed pages outside the main database.");
        builder.AppendLine("- Raw `DataKernel` rows are a contiguous append floor, not a shape implementation; they exist to keep router/shelf overhead visible.");
        builder.AppendLine("- `LibraDex/SQLite` greater than `1.00x` means the current routed shape inserted more logical items per second than the matching SQLite schema under the same transaction cadence.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    private static string WriteFixed32Scalar8ReadParityReport(
        string artifactDirectory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        int repeatCount,
        int commitGapCoalesceBytes,
