        ReadOnlySpan<SqliteScalar8Scalar8ReadResult> sqliteResults)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "fs32-8-read-parity-current.md");
        ArchiveCurrentReport(reportPath, "fs32-8-read-parity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# FS32-8 Read Parity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches used to build read fixture: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per row: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- `FS32-8` commit gap coalescing bytes during fixture build: `{commitGapCoalesceBytes}`");
        builder.AppendLine($"- SQLite journal mode: `{sqliteOptions.JournalMode}`");
        builder.AppendLine($"- SQLite synchronous mode: `{sqliteOptions.Synchronous}`");
        builder.AppendLine("- SQLite schema uses fixed `BLOB(32)` keys, integer identities, and a `WITHOUT ROWID` primary-key B-tree.");
        builder.AppendLine("- LibraDex reads use a harness-local routed range walker over persisted `FS32-8` shelves; this is not yet a public API surface.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | range identities | FS32 identities/sec | SQLite identities/sec | FS32/SQLite | FS32 ns/identity | SQLite ns/identity | FS32 reads/range | FS32 bytes/range |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < libraResults.Length; i++)
        {
            Fixed32Scalar8ReadParityResult libra = libraResults[i];
            SqliteScalar8Scalar8ReadResult sqlite = sqliteResults[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {libra.Name} | {libra.SampleCount} | {libra.RangeIdentityCount} | {libra.IdentitiesPerSecond:F2} | {sqlite.IdentitiesPerSecond:F2} | {FormatMultiplier(libra.IdentitiesPerSecond, sqlite.IdentitiesPerSecond)} | {libra.NsPerIdentity:F2} | {sqlite.NsPerIdentity:F2} | {libra.ReadsPerRange:F3} | {libra.BytesPerRange:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Diagnostics");
        builder.AppendLine();
        builder.AppendLine("| scenario | FS32 logical MiB/s | SQLite logical MiB/s | FS32 checksum | SQLite checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|");
        for (int i = 0; i < libraResults.Length; i++)
        {
            Fixed32Scalar8ReadParityResult libra = libraResults[i];
            SqliteScalar8Scalar8ReadResult sqlite = sqliteResults[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {libra.Name} | {libra.LogicalMiBs:F2} | {sqlite.LogicalMiBs:F2} | {libra.Checksum} | {sqlite.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation Notes");
        builder.AppendLine();
        builder.AppendLine("- This is a read-side guardrail for the physical `FS32-8` shape, not a dried public read API.");
        builder.AppendLine("- `FS32/SQLite` greater than `1.00x` means the harness-level routed `FS32-8` scan returned more identities per second than SQLite for the same prefix-shaped range.");
        builder.AppendLine("- Logical MiB/s counts returned 8-byte identities only; physical router and shelf read bytes are reported separately for LibraDex.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    private static string WriteFixed32Scalar8SizeSweepReport(
        string artifactDirectory,
        int batches,
        int warmupBatches,
