        StringBuilder builder = new();
        builder.AppendLine($"# FS32-8 Size Sweep - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Write batches per row: `{batches}`");
        builder.AppendLine($"- Warmup batches per write row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per row: `{readIterations}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Write rows use routed `FS32-8` bulk insertion with sorted and random item order.");
        builder.AppendLine("- Read rows use the harness-local routed `FS32-8` range walker over the sorted write fixture.");
        builder.AppendLine();
        builder.AppendLine("## Summary");
        builder.AppendLine();
        builder.AppendLine("| shelf bytes | max items | anchor | sorted write items/sec | random write items/sec | random write B/item | prefix 0 ids/sec | prefix 0 ns/id | prefix 0 bytes/range | prefix 0-2 ids/sec | prefix 0-2 ns/id | prefix 0-2 bytes/range |");
        builder.AppendLine("|---:|---:|:---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Length; i++)
        {
            Fixed32Scalar8SizeSweepRow row = rows[i];
            string anchor = row.Profile.ShelfExtentSize == Fixed32Scalar8Profile.Default64KiB.ShelfExtentSize ? "yes" : "";
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Profile.ShelfExtentSize} | {row.Profile.MaxItemCount} | {anchor} | {row.SortedWrite.ItemsPerSecond:F2} | {row.RandomWrite.ItemsPerSecond:F2} | {row.RandomWrite.BytesPerItem:F2} | {row.Prefix0Read.IdentitiesPerSecond:F2} | {row.Prefix0Read.NsPerIdentity:F2} | {row.Prefix0Read.BytesPerRange:F2} | {row.PrefixSpanRead.IdentitiesPerSecond:F2} | {row.PrefixSpanRead.NsPerIdentity:F2} | {row.PrefixSpanRead.BytesPerRange:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Write Detail");
        builder.AppendLine();
        builder.AppendLine("| shelf bytes | order | items/sec | us/item | writes/batch | bytes/item | MiB/s | checksum |");
        builder.AppendLine("|---:|---|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Length; i++)
        {
            Fixed32Scalar8SizeSweepRow row = rows[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Profile.ShelfExtentSize} | sorted | {row.SortedWrite.ItemsPerSecond:F2} | {row.SortedWrite.MicrosecondsPerItem:F3} | {row.SortedWrite.WritesPerBatch:F3} | {row.SortedWrite.BytesPerItem:F2} | {row.SortedWrite.MiBs:F2} | {row.SortedWrite.Checksum} |");
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Profile.ShelfExtentSize} | random | {row.RandomWrite.ItemsPerSecond:F2} | {row.RandomWrite.MicrosecondsPerItem:F3} | {row.RandomWrite.WritesPerBatch:F3} | {row.RandomWrite.BytesPerItem:F2} | {row.RandomWrite.MiBs:F2} | {row.RandomWrite.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- Larger shelves can reduce split and routing pressure but increase per-shelf read/write byte movement.");
        builder.AppendLine("- Prefer the smallest shelf size that materially improves write throughput without harming read latency.");
        builder.AppendLine("- Bytes/item and bytes/range are secondary diagnostics here; logical read/write throughput is the priority signal.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating multi-index same-identities sanity report and archives the previous current report.<br/>
    /// The report records the first structural proof that separate index-directory slots can host different shelf shapes over the same logical identities in one LibraDex file.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="path">The validated LibraDex file path.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="commitGapCoalesceBytes">The `DataKernel` commit gap coalescing setting.</param>
    /// <param name="result">The measured and validated sanity result.</param>
    /// <returns>The report path.</returns>
    private static string WriteMultiIndexSameIdentitiesSanityReport(
        string artifactDirectory,
        string path,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int commitGapCoalesceBytes,
        MultiIndexSameIdentitiesResult result)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "multi-index-same-identities-sanity-current.md");
        ArchiveCurrentReport(reportPath, "multi-index-same-identities-sanity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# Multi-Index Same-Identities Sanity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Path: `{Path.GetFullPath(path)}`");
        builder.AppendLine($"- Batches: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Slot `0` default shape: `SS8-8`, key equals identity.");
        builder.AppendLine("- Slot `1` default shape: `SS16-8`, key high equals identity and key low is deterministic.");
        builder.AppendLine("- Both indexes receive the same 8-byte identity set and are validated after reopening the file.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| index | slot | root offset | commits | writes | bytes | validated items | distinct shelves |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| SS8-8 | {result.Scalar8Scalar8SlotIndex} | {result.Scalar8Scalar8RootOffset} | {result.Scalar8Scalar8CommitCount} | {result.Scalar8Scalar8WriteCallCount} | {result.Scalar8Scalar8BytesWritten} | {result.Scalar8Scalar8ValidatedItems} | {result.Scalar8Scalar8DistinctShelves} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| SS16-8 | {result.Scalar16Scalar8SlotIndex} | {result.Scalar16Scalar8RootOffset} | {result.Scalar16Scalar8CommitCount} | {result.Scalar16Scalar8WriteCallCount} | {result.Scalar16Scalar8BytesWritten} | {result.Scalar16Scalar8ValidatedItems} | {result.Scalar16Scalar8DistinctShelves} |");
        builder.AppendLine();
        builder.AppendLine("## File Telemetry");
        builder.AppendLine();
        builder.AppendLine("| root create writes | root create bytes | setLength | identity checksum | final file bytes |");
        builder.AppendLine("|---:|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.RootCreateWriteCallCount} | {result.RootCreateBytesWritten} | {result.SetLengthCallCount} | {result.IdentityChecksum} | {result.FinalFileBytes} |");
        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- The index-directory retained both active slots after reopen.");
        builder.AppendLine("- Root-router offsets are distinct, so the two indexes do not alias the same route graph.");
        builder.AppendLine("- Each generated identity was found through both shape-local route walkers after reopen.");
        builder.AppendLine("- This is a structural sanity proof, not a multi-index performance benchmark.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Writes the rotating eight-index same-identities sanity report and archives the previous current report.<br/>
    /// This report supersedes the first two-index slice by proving two independent instances of every current shape can coexist in one file over the same generated identities.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="path">The validated LibraDex file path.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="commitGapCoalesceBytes">The `DataKernel` commit gap coalescing setting.</param>
    /// <param name="rootCreateWrites">The aggregate root-create write-call count.</param>
    /// <param name="rootCreateBytes">The aggregate root-create bytes written.</param>
    /// <param name="identityChecksum">The shared generated identity checksum.</param>
    /// <param name="finalFileBytes">The final file length.</param>
    /// <param name="plans">The validated index plans.</param>
    /// <returns>The report path.</returns>
    private static string WriteMultiIndexEightSameIdentitiesSanityReport(
        string artifactDirectory,
        string path,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int commitGapCoalesceBytes,
        long rootCreateWrites,
        long rootCreateBytes,
        long identityChecksum,
        long finalFileBytes,
        ReadOnlySpan<MultiIndexSameIdentitiesPlan> plans)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "multi-index-same-identities-sanity-current.md");
        ArchiveCurrentReport(reportPath, "multi-index-same-identities-sanity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# Multi-Index Same-Identities Sanity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Path: `{Path.GetFullPath(path)}`");
        builder.AppendLine($"- Batches: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Total indexes: `8`");
        builder.AppendLine("- Shape instances: two each of `SS8-8`, `SS16-8`, `SS8-16`, and `SS16-16`.");
        builder.AppendLine("- Identity lanes: four indexes with 8-byte identities and four indexes with 16-byte identities.");
        builder.AppendLine("- Create slot order: `3, 0, 6, 1, 4, 7, 2, 5`.");
        builder.AppendLine("- Write slot order: `6, 0, 3, 5, 1, 7, 4, 2`.");
        builder.AppendLine("- Validate slot order after reopen: `5, 2, 7, 4, 1, 6, 0, 3`.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| slot | shape | identity B | root offset | commits | writes | bytes | validated items | distinct shelves |");
        builder.AppendLine("|---:|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < plans.Length; i++)
        {
            MultiIndexSameIdentitiesPlan plan = plans[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {plan.SlotIndex} | {FormatMultiIndexShape(plan.Shape)} | {plan.IdentityBytes} | {plan.RootOffset} | {plan.Telemetry.CommitCount} | {plan.Telemetry.WriteCallCount} | {plan.Telemetry.BytesWritten} | {plan.ValidatedItems} | {plan.DistinctShelves} |");
        }

        builder.AppendLine();
        builder.AppendLine("## File Telemetry");
        builder.AppendLine();
        builder.AppendLine("| root create writes | root create bytes | identity checksum | final file bytes |");
        builder.AppendLine("|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {rootCreateWrites} | {rootCreateBytes} | {identityChecksum} | {finalFileBytes} |");
        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- The index-directory retained all eight active slots after reopen.");
        builder.AppendLine("- All eight root-router offsets are distinct.");
        builder.AppendLine("- Every generated identity was found through every shape-local route walker after reopen.");
        builder.AppendLine("- This remains structural sanity coverage, not a multi-index performance benchmark.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Formats a multi-index plan shape for console and markdown output.<br/>
    /// Keeping this in one helper prevents the enum names from leaking into artifacts.<br/>
    /// </summary>
    /// <param name="shape">The plan shape.</param>
    /// <returns>The display shape name.</returns>
    private static string FormatMultiIndexShape(MultiIndexSameIdentitiesShape shape)
    {
        return shape switch
        {
            MultiIndexSameIdentitiesShape.SS88 => "SS8-8",
            MultiIndexSameIdentitiesShape.SS168 => "SS16-8",
            MultiIndexSameIdentitiesShape.SS816 => "SS8-16",
            MultiIndexSameIdentitiesShape.SS1616 => "SS16-16",
            _ => throw new InvalidDataException($"Unknown multi-index shape {shape}.")
        };
    }

    /// <summary>
    /// Prints public read-target locality rows to the console.<br/>
