    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="insertRuns">The number of full insert passes per single-shelf sample.</param>
    /// <param name="sampleRuns">The number of measurement samples per profile.</param>
    /// <param name="equalItemCount">The controlled item count used for equal-work rows.</param>
    /// <param name="multiShelfCount">The number of shelves used for multi-shelf rows.</param>
    /// <param name="lookupIterations">The number of lower-bound lookups per sample.</param>
    /// <param name="rangeIterations">The number of range starts per sample.</param>
    /// <param name="rangeLength">The identities included in each range.</param>
    /// <param name="equalResults">The equal-work single-shelf results.</param>
    /// <param name="fullResults">The full-capacity single-shelf results.</param>
