        builder.AppendLine();
        builder.AppendLine($"- Insert runs per profile: `{insertRuns}`");
        builder.AppendLine($"- Measurement samples per profile: `{sampleRuns}`");
        builder.AppendLine($"- Equal-work item count: `{equalItemCount}`");
        builder.AppendLine($"- Multi-shelf count: `{multiShelfCount}`");
        builder.AppendLine($"- Lower-bound iterations per profile: `{lookupIterations}`");
        builder.AppendLine($"- Range iterations per profile: `{rangeIterations}`");
        builder.AppendLine($"- Range length: `{rangeLength}` identities");
        builder.AppendLine("- Equal-work results reuse the same insert order, lookup keys, and range starts across shelf sizes.");
        builder.AppendLine("- Full-capacity results fill each profile to its own maximum item count, so item count varies by shelf size.");
        builder.AppendLine("- Measurements are projected byte-view only and do not include DataKernel I/O.");
        builder.AppendLine();
