        AppendScalar8Scalar8PerfTable(builder, fullResults);
        builder.AppendLine();
        builder.AppendLine("## Multi-Shelf Equal-Work Results");
        builder.AppendLine();
        AppendScalar8Scalar8MultiShelfPerfTable(builder, multiShelfResults);
        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- Reported metric format is `mean [min..max] sd=sample-standard-deviation`.");
        builder.AppendLine("- Reverse insert is intentionally worst-case slot shifting.");
        builder.AppendLine("- Range walk sums identities from sorted slots; scoop also writes identities into a reusable caller buffer.");
        builder.AppendLine("- Equal-work rows are the better shelf-size timing comparison; full-capacity rows show profile economics and max-depth behavior.");
        builder.AppendLine("- Multi-shelf rows store shelves end-to-end in one byte arena and distribute reads across shelves.");
        builder.AppendLine("- These numbers are primitive shelf mechanics and should not be interpreted as full index throughput.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

