    /// <summary>
    /// Measures byte-native fixed tuple comparison against repeated lane projection for a prospective fixed 32-byte key and fixed 16-byte identity shape.<br/>
    /// The persisted tuple contract is treated as 48 contiguous bytes so this spike can compare implementation strategies without committing a new shelf layout.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all comparison strategies produce matching checksums.</returns>
    private static int RunFixedByteCompareSpike(string[] args)
    {
        int itemCount = GetIntOption(args, "--item-count", 262_144);
        int iterations = GetIntOption(args, "--iterations", 32);
        int repeatCount = GetIntOption(args, "--repeat-count", 5);
        if (itemCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), itemCount, "Item count must be positive.");
        }

        if (iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), iterations, "Iteration count must be positive.");
        }

        if (repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), repeatCount, "Repeat count must be positive.");
        }

        const int tupleSize = 48;
        byte[] target = new byte[tupleSize];
        FillDeterministicTuple(target, seed: 0x5A);

        FixedByteCompareSpikeResult[] results =
        [
            MeasureRepeatedFixedByteCompareSpike("mixed bytes", itemCount, iterations, repeatCount, target, FillMixedTuples),
            MeasureRepeatedFixedByteCompareSpike("early byte diff", itemCount, iterations, repeatCount, target, FillEarlyDiffTuples),
            MeasureRepeatedFixedByteCompareSpike("late byte diff", itemCount, iterations, repeatCount, target, FillLateDiffTuples),
            MeasureRepeatedFixedByteCompareSpike("equal bytes", itemCount, iterations, repeatCount, target, FillEqualTuples)
        ];

        Console.WriteLine("fixed-byte compare spike");
        Console.WriteLine($"itemCount {itemCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine("| pattern | strategy | compares/sec | ns/compare | checksum |");
        Console.WriteLine("|---|---|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            FixedByteCompareSpikeResult result = results[i];
            Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"| {result.Pattern} | span SequenceCompareTo | {result.SpanComparesPerSecond:F2} | {result.SpanNsPerCompare:F2} | {result.SpanChecksum} |"));
            Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"| {result.Pattern} | manual byte loop | {result.ManualComparesPerSecond:F2} | {result.ManualNsPerCompare:F2} | {result.ManualChecksum} |"));
            Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"| {result.Pattern} | projected ulong lanes | {result.ProjectedComparesPerSecond:F2} | {result.ProjectedNsPerCompare:F2} | {result.ProjectedChecksum} |"));
        }

        return 0;
    }

    /// <summary>
    /// Runs one fixed tuple comparison pattern multiple times and selects the median sample by span comparison latency.<br/>
    /// Each strategy sees the same persisted byte tuples so checksum equality proves the bytewise and projected orders agree for the generated data.<br/>
    /// </summary>
    /// <param name="pattern">The human-readable data pattern name.</param>
    /// <param name="itemCount">The number of 48-byte tuples in the source buffer.</param>
    /// <param name="iterations">The number of passes over the source buffer per sample.</param>
    /// <param name="repeatCount">The number of samples to collect.</param>
    /// <param name="target">The fixed 48-byte comparison target.</param>
    /// <param name="fill">The tuple-pattern writer.</param>
    /// <returns>The median comparison sample.</returns>
    private static FixedByteCompareSpikeResult MeasureRepeatedFixedByteCompareSpike(
        string pattern,
        int itemCount,
        int iterations,
        int repeatCount,
        ReadOnlySpan<byte> target,
        FixedByteCompareTupleFill fill)
    {
        const int tupleSize = 48;
        byte[] source = new byte[checked(itemCount * tupleSize)];
        fill(source, target);
        FixedByteCompareSpikeResult[] samples = new FixedByteCompareSpikeResult[repeatCount];
        for (int i = 0; i < samples.Length; i++)
        {
            samples[i] = MeasureFixedByteCompareSpike(pattern, source, target, iterations);
        }

        Array.Sort(samples, static (left, right) => left.SpanNsPerCompare.CompareTo(right.SpanNsPerCompare));
        return samples[samples.Length / 2];
    }

    /// <summary>
    /// Measures span byte comparison, manual byte comparison, and repeated big-endian lane projection over the same source tuples.<br/>
    /// The projected strategy intentionally rereads lanes from persisted bytes on every comparison to model the current fixed scalar shelf pattern.<br/>
    /// </summary>
    /// <param name="pattern">The human-readable data pattern name.</param>
    /// <param name="source">The source tuple bytes.</param>
    /// <param name="target">The fixed 48-byte comparison target.</param>
    /// <param name="iterations">The number of passes over the source buffer.</param>
    /// <returns>The measured comparison result.</returns>
    private static FixedByteCompareSpikeResult MeasureFixedByteCompareSpike(
        string pattern,
        ReadOnlySpan<byte> source,
        ReadOnlySpan<byte> target,
        int iterations)
    {
        const int tupleSize = 48;
        long compareCount = checked((source.Length / tupleSize) * (long)iterations);

        Stopwatch spanWatch = Stopwatch.StartNew();
        long spanChecksum = RunSpanCompareLoop(source, target, iterations);
        spanWatch.Stop();

        Stopwatch manualWatch = Stopwatch.StartNew();
        long manualChecksum = RunManualByteCompareLoop(source, target, iterations);
        manualWatch.Stop();

        Stopwatch projectedWatch = Stopwatch.StartNew();
        long projectedChecksum = RunProjectedLaneCompareLoop(source, target, iterations);
        projectedWatch.Stop();

        if (spanChecksum != manualChecksum || spanChecksum != projectedChecksum)
        {
            throw new InvalidDataException($"Fixed-byte compare spike checksum mismatch for pattern '{pattern}': span={spanChecksum}, manual={manualChecksum}, projected={projectedChecksum}.");
        }

        return new FixedByteCompareSpikeResult(
            pattern,
            CalculateComparesPerSecond(compareCount, spanWatch.Elapsed),
            CalculateNsPerCompare(compareCount, spanWatch.Elapsed),
            spanChecksum,
            CalculateComparesPerSecond(compareCount, manualWatch.Elapsed),
            CalculateNsPerCompare(compareCount, manualWatch.Elapsed),
            manualChecksum,
            CalculateComparesPerSecond(compareCount, projectedWatch.Elapsed),
            CalculateNsPerCompare(compareCount, projectedWatch.Elapsed),
            projectedChecksum);
    }

    /// <summary>
    /// Runs the runtime span comparison loop over 48-byte tuples.<br/>
    /// This models a byte-native implementation that delegates contiguous byte comparison to the runtime.<br/>
    /// </summary>
    private static long RunSpanCompareLoop(ReadOnlySpan<byte> source, ReadOnlySpan<byte> target, int iterations)
    {
        const int tupleSize = 48;
        long checksum = 0;
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            for (int offset = 0; offset < source.Length; offset += tupleSize)
            {
                checksum += Math.Sign(source.Slice(offset, tupleSize).SequenceCompareTo(target));
            }
        }

        return checksum;
    }

    /// <summary>
    /// Runs an explicit byte loop over 48-byte tuples.<br/>
    /// This models a simple byte-native implementation that avoids lane projection but keeps compare logic local to the shelf.<br/>
    /// </summary>
    private static long RunManualByteCompareLoop(ReadOnlySpan<byte> source, ReadOnlySpan<byte> target, int iterations)
    {
        const int tupleSize = 48;
        long checksum = 0;
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            for (int offset = 0; offset < source.Length; offset += tupleSize)
            {
                checksum += Math.Sign(CompareFixedBytes(source.Slice(offset, tupleSize), target));
            }
        }

        return checksum;
    }

    /// <summary>
    /// Runs a projected lane comparison loop over 48-byte tuples.<br/>
    /// This models the current scalar shelf implementation style where persisted bytes are projected to big-endian `ulong` values during comparison.<br/>
    /// </summary>
    private static long RunProjectedLaneCompareLoop(ReadOnlySpan<byte> source, ReadOnlySpan<byte> target, int iterations)
    {
        const int tupleSize = 48;
        ulong target0 = BinaryPrimitives.ReadUInt64BigEndian(target.Slice(0, 8));
        ulong target1 = BinaryPrimitives.ReadUInt64BigEndian(target.Slice(8, 8));
        ulong target2 = BinaryPrimitives.ReadUInt64BigEndian(target.Slice(16, 8));
        ulong target3 = BinaryPrimitives.ReadUInt64BigEndian(target.Slice(24, 8));
        ulong target4 = BinaryPrimitives.ReadUInt64BigEndian(target.Slice(32, 8));
        ulong target5 = BinaryPrimitives.ReadUInt64BigEndian(target.Slice(40, 8));
        long checksum = 0;
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            for (int offset = 0; offset < source.Length; offset += tupleSize)
            {
                checksum += Math.Sign(CompareProjectedLanes(source.Slice(offset, tupleSize), target0, target1, target2, target3, target4, target5));
            }
        }

        return checksum;
    }

    /// <summary>
    /// Compares two fixed 48-byte tuples byte by byte.<br/>
    /// The return value follows the same sign convention as `Span.SequenceCompareTo` while keeping the implementation easy to inspect.<br/>
    /// </summary>
    private static int CompareFixedBytes(ReadOnlySpan<byte> left, ReadOnlySpan<byte> right)
    {
        for (int i = 0; i < 48; i++)
        {
            int difference = left[i] - right[i];
            if (difference != 0)
            {
                return difference;
            }
        }

        return 0;
    }

    /// <summary>
    /// Compares one persisted 48-byte tuple to six precomputed target lanes by repeatedly projecting source bytes to big-endian `ulong` values.<br/>
    /// The lane order is byte-order preserving because both source and target lanes are read from the same canonical big-endian byte layout.<br/>
    /// </summary>
    private static int CompareProjectedLanes(
        ReadOnlySpan<byte> source,
        ulong target0,
        ulong target1,
        ulong target2,
        ulong target3,
        ulong target4,
        ulong target5)
    {
        int comparison = CompareUInt64(BinaryPrimitives.ReadUInt64BigEndian(source.Slice(0, 8)), target0);
        if (comparison != 0)
        {
            return comparison;
        }

        comparison = CompareUInt64(BinaryPrimitives.ReadUInt64BigEndian(source.Slice(8, 8)), target1);
        if (comparison != 0)
        {
            return comparison;
        }

        comparison = CompareUInt64(BinaryPrimitives.ReadUInt64BigEndian(source.Slice(16, 8)), target2);
        if (comparison != 0)
        {
            return comparison;
        }

        comparison = CompareUInt64(BinaryPrimitives.ReadUInt64BigEndian(source.Slice(24, 8)), target3);
        if (comparison != 0)
        {
            return comparison;
        }

        comparison = CompareUInt64(BinaryPrimitives.ReadUInt64BigEndian(source.Slice(32, 8)), target4);
        if (comparison != 0)
        {
            return comparison;
        }

        return CompareUInt64(BinaryPrimitives.ReadUInt64BigEndian(source.Slice(40, 8)), target5);
    }

    /// <summary>
    /// Compares two unsigned 64-bit values using the sign convention expected by tuple comparison helpers.<br/>
    /// </summary>
    private static int CompareUInt64(ulong left, ulong right)
    {
        if (left < right)
        {
            return -1;
        }

        return left > right ? 1 : 0;
    }

    /// <summary>
    /// Fills a single deterministic 48-byte tuple.<br/>
    /// The data is non-zero and non-repeating enough to avoid measuring special all-zero fast paths.<br/>
    /// </summary>
    private static void FillDeterministicTuple(Span<byte> target, int seed)
    {
        for (int i = 0; i < target.Length; i++)
        {
            target[i] = unchecked((byte)((seed + (i * 37) + (i >> 1)) & 0xFF));
        }
    }

    /// <summary>
    /// Fills source tuples with deterministic mixed bytes.<br/>
    /// Most comparisons differ in early key bytes, modeling ordinary sorted-key search probes with unrelated fixed keys.<br/>
    /// </summary>
    private static void FillMixedTuples(Span<byte> source, ReadOnlySpan<byte> target)
    {
        for (int offset = 0, tuple = 0; offset < source.Length; offset += 48, tuple++)
        {
            Span<byte> current = source.Slice(offset, 48);
            for (int i = 0; i < current.Length; i++)
            {
                current[i] = unchecked((byte)(target[i] + tuple + (i * 13)));
            }
        }
    }

    /// <summary>
    /// Fills source tuples so the first byte differs from the target.<br/>
    /// This models the best case for byte-native comparison because comparison exits immediately.<br/>
    /// </summary>
    private static void FillEarlyDiffTuples(Span<byte> source, ReadOnlySpan<byte> target)
    {
        for (int offset = 0, tuple = 0; offset < source.Length; offset += 48, tuple++)
        {
            target.CopyTo(source.Slice(offset, 48));
            source[offset] = unchecked((byte)(target[0] + 1 + (tuple & 0x7F)));
        }
    }

    /// <summary>
    /// Fills source tuples so only the final byte differs from the target.<br/>
    /// This models a worst case for byte-native comparison and an equal-key duplicate tie-breaker that reaches the identity tail.<br/>
    /// </summary>
    private static void FillLateDiffTuples(Span<byte> source, ReadOnlySpan<byte> target)
    {
        for (int offset = 0, tuple = 0; offset < source.Length; offset += 48, tuple++)
        {
            target.CopyTo(source.Slice(offset, 48));
            source[offset + 47] = unchecked((byte)(target[47] + 1 + (tuple & 0x7F)));
        }
    }

    /// <summary>
    /// Fills source tuples so every tuple equals the target.<br/>
    /// This models the full compare path used by exact tuple lookups and duplicate detection for an already-present tuple.<br/>
    /// </summary>
    private static void FillEqualTuples(Span<byte> source, ReadOnlySpan<byte> target)
    {
        for (int offset = 0; offset < source.Length; offset += 48)
        {
            target.CopyTo(source.Slice(offset, 48));
        }
    }

    /// <summary>
    /// Converts elapsed time into logical comparisons per second.<br/>
    /// </summary>
    private static double CalculateComparesPerSecond(long compareCount, TimeSpan elapsed)
    {
        return elapsed.TotalSeconds == 0 ? 0 : compareCount / elapsed.TotalSeconds;
    }

    /// <summary>
    /// Converts elapsed time into nanoseconds per logical comparison.<br/>
    /// </summary>
    private static double CalculateNsPerCompare(long compareCount, TimeSpan elapsed)
    {
        return compareCount == 0 ? 0 : elapsed.TotalMilliseconds * 1_000_000d / compareCount;
    }

    private readonly record struct FixedByteCompareSpikeResult(
        string Pattern,
        double SpanComparesPerSecond,
        double SpanNsPerCompare,
        long SpanChecksum,
        double ManualComparesPerSecond,
        double ManualNsPerCompare,
        long ManualChecksum,
        double ProjectedComparesPerSecond,
        double ProjectedNsPerCompare,
        long ProjectedChecksum);

    private delegate void FixedByteCompareTupleFill(Span<byte> source, ReadOnlySpan<byte> target);

    private static Scalar8Scalar8RoutedBulkWriteResult MeasureRepeatedFixed32Scalar16RoutedBulkWrite(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int[] order,
        DataKernelOptions options,
        int repeatCount,
        Fixed32Scalar16Profile profile,
        bool includeAttribution)
    {
        Scalar8Scalar8RoutedBulkWriteResult[] samples = new Scalar8Scalar8RoutedBulkWriteResult[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureFixed32Scalar16RoutedBulkWrite(CreateRepeatPath(path, i), name, batches, warmupBatches, itemsPerBatch, prefixCount, order, options, profile, includeAttribution) with
            {
                SampleCount = 1
            };
        }

        return SelectMedianRoutedBulkWriteSample(samples) with
        {
            SampleCount = repeatCount
        };
    }


    private static Scalar8Scalar8RoutedBulkWriteResult MeasureFixed32Scalar16RoutedBulkWrite(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int[] order,
        DataKernelOptions options,
        Fixed32Scalar16Profile profile,
        bool includeAttribution)
    {
        File.Delete(path);
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(3216), DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "f3216bulk", 0));
        _ = RunFixed32Scalar16RoutedBulkWriteLoop(session, root.Offset, warmupBatches, itemsPerBatch, prefixCount, order, batchOffset: 0, profile, includeAttribution);
        Stopwatch watch = Stopwatch.StartNew();
        RoutedBulkWriteLoopTelemetry telemetry = RunFixed32Scalar16RoutedBulkWriteLoop(session, root.Offset, batches, itemsPerBatch, prefixCount, order, warmupBatches, profile, includeAttribution);
        watch.Stop();
        return CreateRoutedBulkWriteResult(name, batches, itemsPerBatch, watch.Elapsed, telemetry);
    }


    private static RoutedBulkWriteLoopTelemetry RunFixed32Scalar16RoutedBulkWriteLoop(
        LibraDexFileSession session,
        long rootRouterOffset,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order,
        int batchOffset,
        Fixed32Scalar16Profile profile,
        bool includeAttribution)
    {
        RoutedBulkWriteLoopTelemetry telemetry = default;
        for (int batch = 0; batch < batches; batch++)
        {
            Dictionary<long, Fixed32Scalar16BatchShelfCacheEntry> dirtyShelves = [];
            Dictionary<Fixed32Scalar16BatchRouteCacheKey, Fixed32Scalar16RouteTarget> routeTargetCache = [];
            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            int logicalBatch = batchOffset + batch;
            for (int i = 0; i < itemsPerBatch; i++)
            {
                CreateFixed32Scalar16BulkWriteKey(logicalBatch, order[i], itemsPerBatch, prefixCount, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
                ulong identity = Fixed32Scalar16Layout.EncodeUnsignedScalar8(key0);
                byte rootPrefix = (byte)(key0 >> 56);
                Fixed32Scalar16RouteTarget target;
                if (TryGetCachedFixed32Scalar16RouteTarget(routeTargetCache, key0, key1, key2, key3, out target))
                {
                    telemetry.RouteTargetCacheHitCount++;
                }
                else
                {
                    telemetry.RouteTargetCacheMissCount++;
                    long rootLookupStart = includeAttribution ? Stopwatch.GetTimestamp() : 0;
                    if (session.FindRouterTarget(rootRouterOffset, rootPrefix) == 0)
                    {
                        telemetry.RootRouteCreateCount++;
                        _ = session.CreateFixed32Scalar16ShelfAndLinkRootRoute(rootRouterOffset, rootPrefix, profile, itemCount: 0);
                    }

                    if (includeAttribution)
                    {
                        telemetry.RootLookupTicks += Stopwatch.GetTimestamp() - rootLookupStart;
                    }

                    long routeWalkStart = includeAttribution ? Stopwatch.GetTimestamp() : 0;
                    Fixed32Scalar16RoutePathTarget pathTarget = session.WalkFixed32Scalar16RoutePathTarget(rootRouterOffset, key0, key1, key2, key3, maxRouterHops: 32);
                    if (includeAttribution)
                    {
                        telemetry.RouteWalkTicks += Stopwatch.GetTimestamp() - routeWalkStart;
                    }

                    telemetry.RouteWalkCount++;
                    target = pathTarget.Target;
                    if (target.Kind == Fixed32Scalar16RouteTargetKind.Shelf)
                    {
                        routeTargetCache[Fixed32Scalar16BatchRouteCacheKey.Create(key0, key1, key2, key3, target.RouterDepth)] = target;
                    }
                }

                bool insertedByCache = false;
                if (target.Kind == Fixed32Scalar16RouteTargetKind.Shelf)
                {
                    if (!dirtyShelves.TryGetValue(target.Offset, out Fixed32Scalar16BatchShelfCacheEntry? entry))
                    {
                        telemetry.ShelfCacheMissCount++;
                        byte[] shelfBytes = session.ReadFixed32Scalar16ShelfBytesForBatch(target.Offset, profile);
                        entry = new Fixed32Scalar16BatchShelfCacheEntry(shelfBytes);
                        dirtyShelves[target.Offset] = entry;
                    }
                    else
                    {
                        telemetry.ShelfCacheHitCount++;
                    }

                    long shelfInsertStart = includeAttribution ? Stopwatch.GetTimestamp() : 0;
                    Fixed32Scalar16 shelf = new(entry.Bytes, profile);
                    Fixed32Scalar16InsertResult cachedResult = shelf.InsertWithMutationBounds(key0, key1, key2, key3, identity, allowDuplicateKeys: true, out Fixed32Scalar16MutationBounds mutationBounds);
                    if (includeAttribution)
                    {
                        telemetry.ShelfInsertTicks += Stopwatch.GetTimestamp() - shelfInsertStart;
                    }

                    if (cachedResult == Fixed32Scalar16InsertResult.Inserted)
                    {
                        entry.Dirty = true;
                        entry.Include(mutationBounds);
                        insertedByCache = true;
                        telemetry.CachedInsertCount++;
                    }
                    else if (cachedResult == Fixed32Scalar16InsertResult.Full)
                    {
                        telemetry.CacheFullFallbackCount++;
                        session.StageFixed32Scalar16ShelfRewriteForBatch(target.Offset, profile, entry.Bytes);
                        telemetry.FullShelfStageCount++;
                        dirtyShelves.Remove(target.Offset);
                        routeTargetCache.Clear();
                    }
                    else
                    {
                        throw new InvalidDataException($"Expected FS32-16 cached routed bulk insert, got {cachedResult}.");
                    }
                }

                if (!insertedByCache)
                {
                    telemetry.WalkedFallbackCount++;
                    Fixed32Scalar16RoutedInsertResult result = session.InsertWalkedRoutedFixed32Scalar16(rootRouterOffset, profile, key0, key1, key2, key3, identity, allowDuplicateKeys: true, maxRouterHops: 32);
                    if (result.InsertResult != Fixed32Scalar16InsertResult.Inserted)
                    {
                        throw new InvalidDataException($"Expected FS32-16 routed bulk insert, got {result.Kind}/{result.InsertResult}.");
                    }

                    AddFixed32Scalar16RoutedBulkWriteFallback(result, ref telemetry);
                    routeTargetCache.Clear();
                }

                telemetry.InsertedCount++;
                telemetry.Checksum += unchecked((long)(key0 ^ key1 ^ key2 ^ key3 ^ identity ^ (ulong)(i + 1)));
            }

            foreach (KeyValuePair<long, Fixed32Scalar16BatchShelfCacheEntry> pair in dirtyShelves)
            {
                StageFixed32Scalar16ShelfDeltaRewrite(session, pair.Key, profile, pair.Value, ref telemetry);
            }

            (DataKernelCommitTelemetry commit, long deferredRequests) = durabilityBatch.Commit();
            foreach (KeyValuePair<long, Fixed32Scalar16BatchShelfCacheEntry> pair in dirtyShelves)
            {
                session.StoreFixed32Scalar16CleanShelfBytesForBatch(pair.Key, profile, pair.Value.Bytes);
            }

            telemetry.CommitCount++;
            telemetry.DeferredCommitRequests += deferredRequests;
            telemetry.WriteCallCount += commit.WriteCallCount;
            telemetry.BytesWritten += commit.BytesWritten;
            telemetry.SetLengthCallCount += commit.SetLengthCallCount;
        }

        return telemetry;
    }


    private static void StageFixed32Scalar16ShelfDeltaRewrite(
        LibraDexFileSession session,
        long shelfOffset,
        Fixed32Scalar16Profile profile,
        Fixed32Scalar16BatchShelfCacheEntry entry,
        ref RoutedBulkWriteLoopTelemetry telemetry)
    {
        if (!entry.Dirty)
        {
            return;
        }

        byte[] currentBytes = entry.Bytes;
        Fixed32Scalar16ReadOnly readOnly = new(currentBytes, profile);
        if (!readOnly.IsValid)
        {
            throw new InvalidDataException("The batch-local FS32-16 shelf cache attempted to stage invalid shelf bytes.");
        }

        ChangedSpan headerSpan = entry.GetHeaderSpan();
        ChangedSpan slotSpan = entry.GetSlotSpan();
        ChangedSpan itemSpan = entry.GetItemSpan();
        int deltaBytes = headerSpan.Length + slotSpan.Length + itemSpan.Length;
        if (deltaBytes <= 0)
        {
            return;
        }

        if (deltaBytes >= profile.ShelfExtentSize)
        {
            session.StageFixed32Scalar16ShelfRewriteForBatch(shelfOffset, profile, currentBytes);
            telemetry.FullShelfStageCount++;
            return;
        }

        telemetry.DeltaShelfStageCount++;
        AddScalar16Scalar16ChangedSpanAttribution(headerSpan, ref telemetry);
        AddScalar16Scalar16ChangedSpanAttribution(slotSpan, ref telemetry);
        AddScalar16Scalar16ChangedSpanAttribution(itemSpan, ref telemetry);
        StageFixed32Scalar16ShelfChangedSpan(session, shelfOffset, profile, currentBytes, headerSpan);
        StageFixed32Scalar16ShelfChangedSpan(session, shelfOffset, profile, currentBytes, slotSpan);
        StageFixed32Scalar16ShelfChangedSpan(session, shelfOffset, profile, currentBytes, itemSpan);
    }


    private static void StageFixed32Scalar16ShelfChangedSpan(
        LibraDexFileSession session,
        long shelfOffset,
        Fixed32Scalar16Profile profile,
        byte[] currentBytes,
        ChangedSpan span)
    {
        if (span.Length == 0)
        {
            return;
        }

        session.StageFixed32Scalar16ShelfSliceRewriteForBatch(
            shelfOffset,
            profile,
            span.Offset,
            currentBytes.AsSpan(span.Offset, span.Length));
    }


    private static bool TryGetCachedFixed32Scalar16RouteTarget(
        Dictionary<Fixed32Scalar16BatchRouteCacheKey, Fixed32Scalar16RouteTarget> cache,
        ulong key0,
        ulong key1,
        ulong key2,
        ulong key3,
        out Fixed32Scalar16RouteTarget target)
    {
        for (byte depth = 31; depth > 0; depth--)
        {
            if (cache.TryGetValue(Fixed32Scalar16BatchRouteCacheKey.CreateForDepth(key0, key1, key2, key3, depth), out target))
            {
                return true;
            }
        }

        return cache.TryGetValue(Fixed32Scalar16BatchRouteCacheKey.CreateForDepth(key0, key1, key2, key3, 0), out target);
    }


    private static void AddFixed32Scalar16RoutedBulkWriteFallback(
        Fixed32Scalar16RoutedInsertResult result,
        ref RoutedBulkWriteLoopTelemetry telemetry)
    {
        switch (result.Kind)
        {
            case Fixed32Scalar16RoutedInsertKind.WalkedNoSplit:
                telemetry.NoSplitFallbackCount++;
                break;
            case Fixed32Scalar16RoutedInsertKind.WalkedShelfTransformSplit:
                telemetry.TransformSplitFallbackCount++;
                break;
            case Fixed32Scalar16RoutedInsertKind.WalkedParentRouteSplit:
                telemetry.ParentRouteSplitFallbackCount++;
                break;
            case Fixed32Scalar16RoutedInsertKind.NoOp:
            case Fixed32Scalar16RoutedInsertKind.KeyConflict:
                break;
            default:
                throw new InvalidDataException($"Unknown FS32-16 routed bulk-write fallback kind {result.Kind}.");
        }
    }


    private sealed class Fixed32Scalar16BatchShelfCacheEntry
    {
        internal Fixed32Scalar16BatchShelfCacheEntry(byte[] bytes)
        {
            Bytes = bytes;
        }

        internal byte[] Bytes { get; }

        internal bool Dirty { get; set; }

        private int headerStart = int.MaxValue;
        private int headerEnd;
        private int slotStart = int.MaxValue;
        private int slotEnd;
        private int itemStart = int.MaxValue;
        private int itemEnd;

        internal void Include(Fixed32Scalar16MutationBounds bounds)
        {
            IncludeRange(ref headerStart, ref headerEnd, bounds.HeaderOffset, bounds.HeaderLength);
            IncludeRange(ref slotStart, ref slotEnd, bounds.SlotOffset, bounds.SlotLength);
            IncludeRange(ref itemStart, ref itemEnd, bounds.ItemOffset, bounds.ItemLength);
        }

        internal ChangedSpan GetHeaderSpan()
        {
            return GetSpan(headerStart, headerEnd);
        }

        internal ChangedSpan GetSlotSpan()
        {
            return GetSpan(slotStart, slotEnd);
        }

        internal ChangedSpan GetItemSpan()
        {
            return GetSpan(itemStart, itemEnd);
        }

        private static void IncludeRange(ref int start, ref int end, int offset, int length)
        {
            if (length <= 0)
            {
                return;
            }

            start = Math.Min(start, offset);
            end = Math.Max(end, checked(offset + length));
        }

        private static ChangedSpan GetSpan(int start, int end)
        {
            return start == int.MaxValue ? default : new ChangedSpan(start, end - start);
        }
    }


    private readonly record struct Fixed32Scalar16BatchRouteCacheKey(byte Depth, ulong Prefix0, ulong Prefix1, ulong Prefix2, ulong Prefix3)
    {
        internal static Fixed32Scalar16BatchRouteCacheKey Create(ulong key0, ulong key1, ulong key2, ulong key3, ushort routerDepth)
        {
            if (routerDepth > 31)
            {
                throw new InvalidDataException($"The FS32-16 route depth {routerDepth} cannot be cached for a 32-byte encoded fixed key.");
            }

            return CreateForDepth(key0, key1, key2, key3, (byte)routerDepth);
        }

        internal static Fixed32Scalar16BatchRouteCacheKey CreateForDepth(ulong key0, ulong key1, ulong key2, ulong key3, byte depth)
        {
            ExtractPrefix(key0, key1, key2, key3, depth, out ulong prefix0, out ulong prefix1, out ulong prefix2, out ulong prefix3);
            return new Fixed32Scalar16BatchRouteCacheKey(depth, prefix0, prefix1, prefix2, prefix3);
        }

        private static void ExtractPrefix(ulong key0, ulong key1, ulong key2, ulong key3, byte depth, out ulong prefix0, out ulong prefix1, out ulong prefix2, out ulong prefix3)
        {
            int prefixBits = (depth + 1) * 8;
            prefix0 = 0;
            prefix1 = 0;
            prefix2 = 0;
            prefix3 = 0;
            if (prefixBits <= 64)
            {
                prefix0 = key0 >> (64 - prefixBits);
                return;
            }

            prefix0 = key0;
            if (prefixBits <= 128)
            {
                int prefix1Bits = prefixBits - 64;
                prefix1 = key1 >> (64 - prefix1Bits);
                return;
            }

            prefix1 = key1;
            if (prefixBits <= 192)
            {
                int prefix2Bits = prefixBits - 128;
                prefix2 = key2 >> (64 - prefix2Bits);
                return;
            }

            prefix2 = key2;
            int prefix3Bits = prefixBits - 192;
            prefix3 = key3 >> (64 - prefix3Bits);
        }
    }


    private static void CreateFixed32Scalar16BulkWriteKey(
        int batch,
        int itemOrdinal,
        int itemsPerBatch,
        int prefixCount,
        out ulong key0,
        out ulong key1,
        out ulong key2,
        out ulong key3)
    {
        key0 = CreateRoutedBulkWriteKey(batch, itemOrdinal, itemsPerBatch, prefixCount);
        key1 = CreateSqliteScalar16Scalar16LowHalf(key0);
        key2 = unchecked((key1 << 29) ^ (key0 >> 11) ^ 0xD1B5_4A32_D192_ED03UL);
        key3 = unchecked((key2 << 7) ^ (key1 >> 19) ^ 0x94D0_49BB_1331_11EBUL);
    }


    private static SqliteScalar8Scalar8WriteResult MeasureRepeatedSqliteFixed32Scalar16BlobWrite(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int[] order,
        SqliteScalar8Scalar8Options options,
        int repeatCount)
    {
        SqliteScalar8Scalar8WriteResult[] samples = new SqliteScalar8Scalar8WriteResult[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureSqliteFixed32Scalar16BlobWrite(CreateRepeatPath(path, i), name, batches, warmupBatches, itemsPerBatch, prefixCount, order, options) with
            {
                SampleCount = 1
            };
        }

        return SelectMedianSqliteScalar8Scalar8WriteSample(samples) with
        {
            SampleCount = repeatCount
        };
    }


    private static SqliteScalar8Scalar8WriteResult MeasureSqliteFixed32Scalar16BlobWrite(
        string path,
        string name,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        int[] order,
        SqliteScalar8Scalar8Options options)
    {
        ResetSqliteScalar8Scalar8Files(path);
        using SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(path, options);
        InitializeSqliteFixed32Scalar16BlobSchema(connection);
        long warmupChecksum = RunSqliteFixed32Scalar16BlobWriteLoop(connection, warmupBatches, itemsPerBatch, prefixCount, order, batchOffset: 0);
        Stopwatch watch = Stopwatch.StartNew();
        long checksum = RunSqliteFixed32Scalar16BlobWriteLoop(connection, batches, itemsPerBatch, prefixCount, order, batchOffset: warmupBatches);
        watch.Stop();
        connection.Close();

        long measuredItems = (long)batches * itemsPerBatch;
        long totalItems = (long)(batches + warmupBatches) * itemsPerBatch;
        long storageBytes = GetSqliteScalar8Scalar8StorageBytes(path);
        double seconds = Math.Max(watch.Elapsed.TotalSeconds, 0.000000001d);
        return new SqliteScalar8Scalar8WriteResult(
            name,
            batches,
            warmupBatches,
            itemsPerBatch,
            measuredItems,
            totalItems,
            watch.Elapsed,
            measuredItems / seconds,
            watch.Elapsed.TotalMilliseconds * 1000d / measuredItems,
            batches / seconds,
            storageBytes,
            totalItems == 0 ? 0 : storageBytes / (double)totalItems,
            unchecked(checksum + warmupChecksum),
            1);
    }


    private static long RunSqliteFixed32Scalar16BlobWriteLoop(
        SqliteConnection connection,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int[] order,
        int batchOffset)
    {
        long checksum = 0;
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "INSERT INTO items(k, i) VALUES($k, $i);";
        SqliteParameter keyParameter = command.Parameters.Add("$k", SqliteType.Blob);
        SqliteParameter identityParameter = command.Parameters.Add("$i", SqliteType.Integer);
        for (int batch = 0; batch < batches; batch++)
        {
            using SqliteTransaction transaction = connection.BeginTransaction();
            command.Transaction = transaction;
            int logicalBatch = batchOffset + batch;
            for (int i = 0; i < itemsPerBatch; i++)
            {
                CreateFixed32Scalar16BulkWriteKey(logicalBatch, order[i], itemsPerBatch, prefixCount, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
                byte[] keyBlob = CreateSqliteFixed32Scalar8Blob(key0, key1, key2, key3);
                ulong identityLow = Fixed32Scalar16Layout.EncodeUnsignedScalar8(key0);
                byte[] identityBlob = CreateSqliteScalar16Scalar16Blob(0, identityLow);
                keyParameter.Value = keyBlob;
                identityParameter.Value = identityBlob;
                if (command.ExecuteNonQuery() != 1)
                {
                    throw new InvalidDataException("SQLite FS32-16 BLOB comparison insert did not affect exactly one row.");
                }

                checksum += unchecked((long)(key0 ^ key1 ^ key2 ^ key3 ^ identityLow ^ (ulong)(i + 1)));
            }

            transaction.Commit();
            command.Transaction = null;
        }

        return checksum;
    }


    private static void InitializeSqliteFixed32Scalar16BlobSchema(SqliteConnection connection)
    {
        ExecuteSqliteScalar8Scalar8NonQuery(
            connection,
            "CREATE TABLE items(k BLOB NOT NULL CHECK(length(k)=32), i BLOB NOT NULL CHECK(length(i)=16), PRIMARY KEY(k, i)) WITHOUT ROWID;");
    }


    private static int RunFixed32Scalar16ReadParity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "FS32-16ReadParity"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int iterations = GetIntOption(args, "--iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        int commitGapCoalesceBytes = GetIntOption(args, "--wide-commit-gap-coalesce-bytes", 16 * 1024);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (batches <= 0 || itemsPerBatch <= 0 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "FS32-16 read-parity batches, items per batch, iterations, and repeat count must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "FS32-16 read-parity prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        string libraPath = Path.Combine(directory, "fs32-16-read.lbdx");
        File.Delete(libraPath);
        Fixed32Scalar16Profile profile = Fixed32Scalar16Profile.Default64KiB;
        DataKernelOptions libraOptions = CreateDesignPerfOptions(commitGapCoalesceBytes);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        long rootOffset;
        using (LibraDexFileSession created = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(32161), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = created.CreateRootRouterIndex(CreateHarnessSlot(0, "f3216read", 0));
            rootOffset = root.Offset;
            _ = RunFixed32Scalar16RoutedBulkWriteLoop(created, rootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, profile, includeAttribution: false);
        }

        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        Fixed32Scalar16ReadParityResult[] libraResults = new Fixed32Scalar16ReadParityResult[5];
        using (LibraDexFileSession opened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraResults[0] = MeasureRepeatedFixed32Scalar16ReadRange(opened, rootOffset, profile, "fs32-16 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            libraResults[1] = MeasureRepeatedFixed32Scalar16ReadRange(opened, rootOffset, profile, "fs32-16 prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            libraResults[2] = MeasureRepeatedFixed32Scalar16ReadRange(opened, rootOffset, profile, "fs32-16 prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            libraResults[3] = MeasureRepeatedFixed32Scalar16ReadRange(opened, rootOffset, profile, "fs32-16 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            libraResults[4] = MeasureRepeatedFixed32Scalar16ReadRange(opened, rootOffset, profile, "fs32-16 prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        string sqlitePath = Path.Combine(directory, "sqlite-fs32-16-read.db");
        ResetSqliteScalar8Scalar8Files(sqlitePath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteFixed32Scalar16BlobSchema(connection);
            RunSqliteFixed32Scalar16BlobWriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        SqliteScalar8Scalar8ReadResult[] sqliteResults = new SqliteScalar8Scalar8ReadResult[5];
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteResults[0] = MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(connection, "sqlite fs32-16 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            sqliteResults[1] = MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(connection, "sqlite fs32-16 prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            sqliteResults[2] = MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(connection, "sqlite fs32-16 prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            sqliteResults[3] = MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(connection, "sqlite fs32-16 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            sqliteResults[4] = MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(connection, "sqlite fs32-16 prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        string reportPath = WriteFixed32Scalar16ReadParityReport(
            artifactDirectory,
            batches,
            itemsPerBatch,
            prefixCount,
            iterations,
            repeatCount,
            commitGapCoalesceBytes,
            sqliteOptions,
            libraResults,
            sqliteResults);

        Console.WriteLine("fs32-16 read parity");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        PrintFixed32Scalar16ReadParityResults(libraResults, sqliteResults);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


    private static void PrintFixed32Scalar16ReadParityResults(
        ReadOnlySpan<Fixed32Scalar16ReadParityResult> libraResults,
        ReadOnlySpan<SqliteScalar8Scalar8ReadResult> sqliteResults)
    {
        Console.WriteLine("| scenario | samples | FS32-16 ids/sec | SQLite ids/sec | FS32-16/SQLite | FS32-16 ns/id | SQLite ns/id | FS32-16 reads/range | FS32-16 bytes/range |");
        Console.WriteLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < libraResults.Length; i++)
        {
            Fixed32Scalar16ReadParityResult libra = libraResults[i];
            SqliteScalar8Scalar8ReadResult sqlite = sqliteResults[i];
            Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"| {libra.Name} | {libra.SampleCount} | {libra.IdentitiesPerSecond:F2} | {sqlite.IdentitiesPerSecond:F2} | {FormatMultiplier(libra.IdentitiesPerSecond, sqlite.IdentitiesPerSecond)} | {libra.NsPerIdentity:F2} | {sqlite.NsPerIdentity:F2} | {libra.ReadsPerRange:F3} | {libra.BytesPerRange:F2} |"));
        }
    }


    private static Fixed32Scalar16ReadParityResult MeasureRepeatedFixed32Scalar16ReadRange(
        LibraDexFileSession session,
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        string name,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int lowerPrefix,
        int upperPrefix,
        int iterations,
        Span<ulong> identities,
        int repeatCount)
    {
        Fixed32Scalar16ReadParityResult[] samples = new Fixed32Scalar16ReadParityResult[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureFixed32Scalar16ReadRange(session, rootRouterOffset, profile, name, batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, iterations, identities) with
            {
                SampleCount = 1
            };
        }

        return SelectMedianFixed32Scalar16ReadParitySample(samples) with
        {
            SampleCount = repeatCount
        };
    }


    private static Fixed32Scalar16ReadParityResult MeasureFixed32Scalar16ReadRange(
        LibraDexFileSession session,
        long rootRouterOffset,
        Fixed32Scalar16Profile profile,
        string name,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int lowerPrefix,
        int upperPrefix,
        int iterations,
        Span<ulong> identities)
    {
        int expectedCount = CountScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix);
        if (identities.Length < expectedCount)
        {
            throw new ArgumentException("The FS32-16 read identity buffer is too small for the requested range.", nameof(identities));
        }

        ulong[] expectedIdentities = CreateSortedScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, expectedCount);
        CreateFixed32Scalar16PrefixRangeBounds(lowerPrefix, upperPrefix, out ulong lower0, out ulong lower1, out ulong lower2, out ulong lower3, out ulong upper0, out ulong upper1, out ulong upper2, out ulong upper3);
        byte[] shelfScratch = new byte[profile.ShelfExtentSize];
        using RouteTargetKindCache targetKindCache = RouteTargetKindCache.Rent();
        long checksum = 0;
        long totalIdentities = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            int count = session.ReadFixed32Scalar16IdentityLowRange(
                rootRouterOffset,
                profile,
                lower0,
                lower1,
                lower2,
                lower3,
                upper0,
                upper1,
                upper2,
                upper3,
                maxRouterHops: 8,
                identities,
                shelfScratch,
                targetKindCache);
            if (count != expectedCount)
            {
                throw new InvalidDataException($"FS32-16 read {name} returned {count} identities; expected {expectedCount}.");
            }

            checksum += CheckScalar8Scalar8PublicBulkReadRange(identities, count, expectedIdentities);
            totalIdentities += count;
        }

        watch.Stop();
        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        double seconds = Math.Max(watch.Elapsed.TotalSeconds, 0.000000001d);
        return new Fixed32Scalar16ReadParityResult(
            name,
            iterations,
            expectedCount,
            totalIdentities,
            watch.Elapsed,
            totalIdentities / seconds,
            seconds * 1_000_000_000d / totalIdentities,
            CalculateMiBs((double)totalIdentities * Fixed32Scalar16Layout.IdentitySize, seconds),
            iterations == 0 ? 0 : readTelemetry.ReadCallCount / (double)iterations,
            iterations == 0 ? 0 : readTelemetry.BytesRead / (double)iterations,
            checksum,
            1);
    }


    private static void CreateFixed32Scalar16PrefixRangeBounds(
        int lowerPrefix,
        int upperPrefix,
        out ulong lower0,
        out ulong lower1,
        out ulong lower2,
        out ulong lower3,
        out ulong upper0,
        out ulong upper1,
        out ulong upper2,
        out ulong upper3)
    {
        lower0 = (ulong)(byte)lowerPrefix << 56;
        lower1 = 0;
        lower2 = 0;
        lower3 = 0;
        upper0 = ((ulong)(byte)upperPrefix << 56) | 0x00FF_FFFF_FFFF_FFFFUL;
        upper1 = ulong.MaxValue;
        upper2 = ulong.MaxValue;
        upper3 = ulong.MaxValue;
    }


    private static SqliteScalar8Scalar8ReadResult MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(
        SqliteConnection connection,
        string name,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int lowerPrefix,
        int upperPrefix,
        int iterations,
        Span<ulong> identities,
        int repeatCount)
    {
        SqliteScalar8Scalar8ReadResult[] samples = new SqliteScalar8Scalar8ReadResult[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureSqliteFixed32Scalar16BlobReadRange(connection, name, batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, iterations, identities) with
            {
                SampleCount = 1
            };
        }

        return SelectMedianSqliteScalar8Scalar8ReadSample(samples) with
        {
            SampleCount = repeatCount
        };
    }


    private static SqliteScalar8Scalar8ReadResult MeasureSqliteFixed32Scalar16BlobReadRange(
        SqliteConnection connection,
        string name,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int lowerPrefix,
        int upperPrefix,
        int iterations,
        Span<ulong> identities)
    {
        int expectedCount = CountScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix);
        if (identities.Length < expectedCount)
        {
            throw new ArgumentException("The SQLite FS32-16 read identity buffer is too small for the requested range.", nameof(identities));
        }

        ulong[] expectedIdentities = CreateSortedScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, expectedCount);
        CreateFixed32Scalar16PrefixRangeBounds(lowerPrefix, upperPrefix, out ulong lower0, out ulong lower1, out ulong lower2, out ulong lower3, out ulong upper0, out ulong upper1, out ulong upper2, out ulong upper3);
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;";
        command.Parameters.AddWithValue("$lower", CreateSqliteFixed32Scalar8Blob(lower0, lower1, lower2, lower3));
        command.Parameters.AddWithValue("$upper", CreateSqliteFixed32Scalar8Blob(upper0, upper1, upper2, upper3));

        long checksum = 0;
        long totalIdentities = 0;
        Stopwatch watch = Stopwatch.StartNew();
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            int count = 0;
            using (SqliteDataReader reader = command.ExecuteReader())
            {
                while (reader.Read())
                {
                    if (count >= identities.Length)
                    {
                        throw new InvalidDataException("SQLite FS32-16 read returned more identities than the reusable buffer can hold.");
                    }

                    byte[] identity = reader.GetFieldValue<byte[]>(0);
                    if (identity.Length != Fixed32Scalar16Layout.IdentitySize)
                    {
                        throw new InvalidDataException($"SQLite FS32-16 read returned an identity blob with {identity.Length} bytes.");
                    }

                    ulong identityHigh = ReadSqliteScalar16Scalar16BigEndianUInt64(identity, 0);
                    ulong identityLow = ReadSqliteScalar16Scalar16BigEndianUInt64(identity, sizeof(ulong));
                    if (identityHigh != 0)
                    {
                        throw new InvalidDataException($"SQLite FS32-16 read returned identity high lane {identityHigh}; expected zero for this deterministic 64-bit identity fixture.");
                    }

                    identities[count++] = identityLow;
                }
            }

            if (count != expectedCount)
            {
                throw new InvalidDataException($"SQLite FS32-16 read {name} returned {count} identities; expected {expectedCount}.");
            }

            checksum += CheckScalar8Scalar8PublicBulkReadRange(identities, count, expectedIdentities);
            totalIdentities += count;
        }

        watch.Stop();
        double seconds = Math.Max(watch.Elapsed.TotalSeconds, 0.000000001d);
        return new SqliteScalar8Scalar8ReadResult(
            name,
            iterations,
            expectedCount,
            totalIdentities,
            watch.Elapsed,
            totalIdentities / seconds,
            seconds * 1_000_000_000d / totalIdentities,
            CalculateMiBs((double)totalIdentities * Fixed32Scalar16Layout.IdentitySize, seconds),
            checksum,
            1);
    }


    private static string WriteFixed32Scalar16ReadParityReport(
        string artifactDirectory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        int repeatCount,
        int commitGapCoalesceBytes,
        SqliteScalar8Scalar8Options sqliteOptions,
        ReadOnlySpan<Fixed32Scalar16ReadParityResult> libraResults,
        ReadOnlySpan<SqliteScalar8Scalar8ReadResult> sqliteResults)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "fs32-16-read-parity-current.md");
        ArchiveCurrentReport(reportPath, "fs32-16-read-parity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# FS32-16 Read Parity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches used to build read fixture: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per row: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- `FS32-16` commit gap coalescing bytes during fixture build: `{commitGapCoalesceBytes}`");
        builder.AppendLine($"- SQLite journal mode: `{sqliteOptions.JournalMode}`");
        builder.AppendLine($"- SQLite synchronous mode: `{sqliteOptions.Synchronous}`");
        builder.AppendLine("- SQLite schema uses fixed `BLOB(32)` keys, fixed 16-byte identity blobs, and a `WITHOUT ROWID` primary-key B-tree.");
        builder.AppendLine("- LibraDex reads use a harness-local routed range walker over persisted `FS32-16` shelves; this is not yet a public API surface.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | range identities | FS32-16 identities/sec | SQLite identities/sec | FS32-16/SQLite | FS32-16 ns/identity | SQLite ns/identity | FS32-16 reads/range | FS32-16 bytes/range |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < libraResults.Length; i++)
        {
            Fixed32Scalar16ReadParityResult libra = libraResults[i];
            SqliteScalar8Scalar8ReadResult sqlite = sqliteResults[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {libra.Name} | {libra.SampleCount} | {libra.RangeIdentityCount} | {libra.IdentitiesPerSecond:F2} | {sqlite.IdentitiesPerSecond:F2} | {FormatMultiplier(libra.IdentitiesPerSecond, sqlite.IdentitiesPerSecond)} | {libra.NsPerIdentity:F2} | {sqlite.NsPerIdentity:F2} | {libra.ReadsPerRange:F3} | {libra.BytesPerRange:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Diagnostics");
        builder.AppendLine();
        builder.AppendLine("| scenario | FS32-16 logical MiB/s | SQLite logical MiB/s | FS32-16 checksum | SQLite checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|");
        for (int i = 0; i < libraResults.Length; i++)
        {
            Fixed32Scalar16ReadParityResult libra = libraResults[i];
            SqliteScalar8Scalar8ReadResult sqlite = sqliteResults[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {libra.Name} | {libra.LogicalMiBs:F2} | {sqlite.LogicalMiBs:F2} | {libra.Checksum} | {sqlite.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation Notes");
        builder.AppendLine();
        builder.AppendLine("- This is a read-side guardrail for the physical `FS32-16` shape, not a dried public read API.");
        builder.AppendLine("- `FS32-16/SQLite` greater than `1.00x` means the harness-level routed `FS32-16` scan returned more identities per second than SQLite for the same prefix-shaped range.");
        builder.AppendLine("- Logical MiB/s counts returned 16-byte identities; physical router and shelf read bytes are reported separately for LibraDex.");

        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    /// <summary>
    /// Sweeps routed range-read widths across the current fixed-width shelf shapes and matching SQLite schemas.<br/>
    /// The sweep reports SQLite parity, raw-read-baseline distance, and read amplification so range-scoop performance can be judged against more than one reference point.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the range-sweep report is written.</returns>
    private static int RunAllShapeReadRangeSweep(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "AllShapeReadRangeSweep"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int iterations = GetIntOption(args, "--iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        int wideCommitGapCoalesceBytes = GetIntOption(args, "--wide-commit-gap-coalesce-bytes", 16 * 1024);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (batches <= 0 || itemsPerBatch <= 0 || prefixCount <= 0 || prefixCount > 256 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "All-shape read range sweep requires positive batches, items, iterations, repeat count, and prefix count 1-256.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        DataKernelOptions options = CreateDesignPerfOptions(wideCommitGapCoalesceBytes);
        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        AllShapeReadRangeCase[] ranges = CreateAllShapeReadRangeCases(prefixCount);
        int maxRangeCount = batches * itemsPerBatch;
        ulong[] identities = new ulong[maxRangeCount];
        ulong[] identityLows = new ulong[maxRangeCount];
        List<AllShapeReadRangeSweepRow> rows = [];

        MeasureAllShapeReadRangeSweepSs88(directory, batches, itemsPerBatch, prefixCount, iterations, repeatCount, sortedOrder, options, sqliteOptions, ranges, identities, rows);
        MeasureAllShapeReadRangeSweepSs168(directory, batches, itemsPerBatch, prefixCount, iterations, repeatCount, sortedOrder, options, sqliteOptions, ranges, identities, rows);
        MeasureAllShapeReadRangeSweepSs816(directory, batches, itemsPerBatch, prefixCount, iterations, repeatCount, sortedOrder, options, sqliteOptions, ranges, identities, identityLows, rows);
        MeasureAllShapeReadRangeSweepSs1616(directory, batches, itemsPerBatch, prefixCount, iterations, repeatCount, sortedOrder, options, sqliteOptions, ranges, identities, identityLows, rows);
        MeasureAllShapeReadRangeSweepFs328(directory, batches, itemsPerBatch, prefixCount, iterations, repeatCount, sortedOrder, options, sqliteOptions, ranges, identities, rows);
        MeasureAllShapeReadRangeSweepFs3216(directory, batches, itemsPerBatch, prefixCount, iterations, repeatCount, sortedOrder, options, sqliteOptions, ranges, identities, rows);

        string reportPath = WriteAllShapeReadRangeSweepReport(
            artifactDirectory,
            batches,
            itemsPerBatch,
            prefixCount,
            iterations,
            repeatCount,
            wideCommitGapCoalesceBytes,
            sqliteOptions,
            rows);

        Console.WriteLine("all-shape read range sweep");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        PrintAllShapeReadRangeSweepRows(rows);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }

    private static AllShapeReadRangeCase[] CreateAllShapeReadRangeCases(int prefixCount)
    {
        int last = prefixCount - 1;
        List<AllShapeReadRangeCase> ranges =
        [
            new("prefix 0", 0, 0)
        ];

        int three = Math.Min(2, last);
        if (three > 0)
        {
            ranges.Add(new("prefix 0-2", 0, three));
        }

        int eight = Math.Min(7, last);
        if (eight > three)
        {
            ranges.Add(new($"prefix 0-{eight}", 0, eight));
        }

        if (last > eight)
        {
            ranges.Add(new($"prefix 0-{last}", 0, last));
        }

        return [.. ranges];
    }

    private static void MeasureAllShapeReadRangeSweepSs88(
        string directory,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int iterations,
        int repeatCount,
        int[] sortedOrder,
        DataKernelOptions options,
        SqliteScalar8Scalar8Options sqliteOptions,
        ReadOnlySpan<AllShapeReadRangeCase> ranges,
        ulong[] identities,
        List<AllShapeReadRangeSweepRow> rows)
    {
        string libraPath = Path.Combine(directory, "read-sweep-ss8-8.lbdx");
        File.Delete(libraPath);
        using (Scalar8Scalar8Index created = Indexes.SS88.Create(libraPath, DataKernelBackingKind.File, name: "read-sweep-ss8-8", options: options, developerMetadata: CreateDesignPerfMetadata(8801), telemetryOptions: DataKernelTelemetryOptions.EnabledOptions, shelfExtentSize: Scalar8Scalar8Profile.Default32KiB.ShelfExtentSize))
        {
            _ = RunScalar8Scalar8RoutedBulkWriteLoop(created, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        string sqlitePath = Path.Combine(directory, "read-sweep-sqlite-ss8-8.db");
        ResetSqliteScalar8Scalar8Files(sqlitePath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteScalar8Scalar8Schema(connection);
            RunSqliteScalar8Scalar8WriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        using Scalar8Scalar8Index opened = Indexes.SS88.Open(libraPath, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions);
        using SqliteConnection sqlite = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions);
        for (int i = 0; i < ranges.Length; i++)
        {
            AllShapeReadRangeCase range = ranges[i];
            Scalar8Scalar8PublicBulkReadResult libra = MeasureRepeatedScalar8Scalar8PublicBulkReadRange(opened, $"SS8-8 {range.Name}", batches, itemsPerBatch, prefixCount, range.LowerPrefix, range.UpperPrefix, iterations, enableCoalescing: true, identities, repeatCount);
            SqliteScalar8Scalar8ReadResult sql = MeasureRepeatedSqliteScalar8Scalar8ReadRange(sqlite, $"sqlite SS8-8 {range.Name}", batches, itemsPerBatch, prefixCount, range.LowerPrefix, range.UpperPrefix, iterations, identities, repeatCount);
            double libraLogicalMiBs = CalculateMiBs((double)libra.TotalIdentityCount * Scalar8Scalar8Layout.IdentitySize, Math.Max(libra.Elapsed.TotalSeconds, 0.000000001d));
            rows.Add(CreateAllShapeReadRangeSweepRow("SS8-8", 16, 8, range.Name, libra.RangeIdentityCount, libra.IdentitiesPerSecond, libra.NsPerIdentity, libra.ReadsPerRange, libra.BytesPerRange, libraLogicalMiBs, sql.IdentitiesPerSecond, sql.NsPerIdentity, sql.LogicalMiBs));
        }
    }

