        string sqlitePath = Path.Combine(directory, "read-sweep-sqlite-fs32-16.db");
        ResetSqliteScalar8Scalar8Files(sqlitePath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteFixed32Scalar16BlobSchema(connection);
            RunSqliteFixed32Scalar16BlobWriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        using LibraDexFileSession opened = LibraDexFileSession.Open(libraPath, options, DataKernelTelemetryOptions.EnabledOptions);
        using SqliteConnection sqlite = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions);
        for (int i = 0; i < ranges.Length; i++)
        {
            AllShapeReadRangeCase range = ranges[i];
            Fixed32Scalar16ReadParityResult libra = MeasureRepeatedFixed32Scalar16ReadRange(opened, rootOffset, profile, $"FS32-16 {range.Name}", batches, itemsPerBatch, prefixCount, range.LowerPrefix, range.UpperPrefix, iterations, identities, repeatCount);
            SqliteScalar8Scalar8ReadResult sql = MeasureRepeatedSqliteFixed32Scalar16BlobReadRange(sqlite, $"sqlite FS32-16 {range.Name}", batches, itemsPerBatch, prefixCount, range.LowerPrefix, range.UpperPrefix, iterations, identities, repeatCount);
            rows.Add(CreateAllShapeReadRangeSweepRow("FS32-16", 48, 16, range.Name, libra.RangeIdentityCount, libra.IdentitiesPerSecond, libra.NsPerIdentity, libra.ReadsPerRange, libra.BytesPerRange, libra.LogicalMiBs, sql.IdentitiesPerSecond, sql.NsPerIdentity, sql.LogicalMiBs));
        }
    }

    private static AllShapeReadRangeSweepSample MeasureRepeatedScalar16Scalar8ReadRange(LibraDexFileSession session, long rootRouterOffset, Scalar16Scalar8Profile profile, AllShapeReadRangeCase range, int batches, int itemsPerBatch, int prefixCount, int iterations, Span<ulong> identities, int repeatCount)
    {
        AllShapeReadRangeSweepSample[] samples = new AllShapeReadRangeSweepSample[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureScalar16Scalar8ReadRange(session, rootRouterOffset, profile, range, batches, itemsPerBatch, prefixCount, iterations, identities) with { SampleCount = 1 };
