    private static AllShapeReadRangeSweepSample MeasureScalar16Scalar8ReadRange(LibraDexFileSession session, long rootRouterOffset, Scalar16Scalar8Profile profile, AllShapeReadRangeCase range, int batches, int itemsPerBatch, int prefixCount, int iterations, Span<ulong> identities)
    {
        int expectedCount = CountScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, range.LowerPrefix, range.UpperPrefix);
        ulong[] expected = CreateSortedScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, range.LowerPrefix, range.UpperPrefix, expectedCount);
        CreateScalar16RangeBounds(range, out ulong lowerHigh, out ulong lowerLow, out ulong upperHigh, out ulong upperLow);
        byte[] shelfScratch = new byte[profile.ShelfExtentSize];
        using RouteTargetKindCache targetKindCache = RouteTargetKindCache.Rent();
        long checksum = 0;
        long total = 0;
        _ = session.GetAndResetReadTelemetry();
        Stopwatch watch = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++)
        {
            int count = session.ReadScalar16Scalar8IdentityRange(rootRouterOffset, profile, lowerHigh, lowerLow, upperHigh, upperLow, maxRouterHops: 8, identities, shelfScratch, targetKindCache);
            if (count != expectedCount)
            {
                throw new InvalidDataException($"SS16-8 range diagnostic for {range.Name}: expected {expectedCount}, actual {count}, root {DescribeScalar16Scalar8RouteTargets(session, rootRouterOffset, profile, range)}.");
            }

            checksum += CheckScalar8Scalar8PublicBulkReadRange(identities, count, expected);
            total += count;
        }

        watch.Stop();
        DataKernelReadTelemetry telemetry = session.GetAndResetReadTelemetry();
        return CreateAllShapeReadRangeSweepSample(range.Name, iterations, expectedCount, total, watch.Elapsed, Scalar16Scalar8Layout.IdentitySize, telemetry, checksum);
    }

    private static string DescribeScalar16Scalar8RouteTargets(LibraDexFileSession session, long rootRouterOffset, Scalar16Scalar8Profile profile, AllShapeReadRangeCase range)
    {
        RouterSnapshot root = session.ReadRouterSnapshot(rootRouterOffset);
        StringBuilder builder = new();
        builder.Append(CultureInfo.InvariantCulture, $"offset={rootRouterOffset}, depth={root.KeyDepth}, routes=");
        for (int prefix = range.LowerPrefix; prefix <= range.UpperPrefix; prefix++)
        {
            long targetOffset = session.FindRouterTarget(rootRouterOffset, (byte)prefix);
            builder.Append(CultureInfo.InvariantCulture, $"{prefix}:{targetOffset}");
            if (targetOffset != 0)
            {
                builder.Append('/');
                builder.Append(session.ClassifyScalar16Scalar8RouteTarget(targetOffset));
                builder.Append('/');
                builder.Append(DescribeFirstScalar16Scalar8Shelf(session, targetOffset, profile));
            }

            if (prefix < range.UpperPrefix)
            {
                builder.Append(',');
            }
        }

        return builder.ToString();
    }

    private static string DescribeFirstScalar16Scalar8Shelf(LibraDexFileSession session, long targetOffset, Scalar16Scalar8Profile profile)
    {
        Scalar16Scalar8RouteTargetKind kind = session.ClassifyScalar16Scalar8RouteTarget(targetOffset);
        if (kind == Scalar16Scalar8RouteTargetKind.Router)
        {
            RouterSnapshot router = session.ReadRouterSnapshot(targetOffset);
            for (int prefix = 0; prefix <= byte.MaxValue; prefix++)
            {
                long childOffset = session.FindRouterTarget(targetOffset, (byte)prefix);
                if (childOffset != 0)
                {
                    return $"childDepth={router.KeyDepth},p{prefix}->{DescribeFirstScalar16Scalar8Shelf(session, childOffset, profile)}";
                }
            }

            return $"childDepth={router.KeyDepth},empty";
        }

        if (kind != Scalar16Scalar8RouteTargetKind.Shelf)
        {
            return kind.ToString();
        }

        byte[] bytes = new byte[profile.ShelfExtentSize];
        session.ReadScalar16Scalar8ShelfForRangeScan(targetOffset, profile, bytes);
        Scalar16Scalar8ReadOnly shelf = new(bytes, profile);
        int count = shelf.ItemCount;
        if (count == 0)
        {
            return $"shelf={targetOffset},count=0";
        }

        ulong first = shelf.ReadKeyHighAt(0);
        ulong last = shelf.ReadKeyHighAt(count - 1);
        return string.Create(CultureInfo.InvariantCulture, $"shelf={targetOffset},count={count},first={first:X16},last={last:X16}");
    }

