        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureSqliteScalar16Scalar8BlobReadRange(connection, name, batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, iterations, identities) with { SampleCount = 1 };
