    {
        SqliteScalar8Scalar8ReadResult[] samples = new SqliteScalar8Scalar8ReadResult[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureSqliteScalar8Scalar16BlobReadRange(connection, name, batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, iterations, identityHighs) with { SampleCount = 1 };
        }

        return SelectMedianSqliteScalar8Scalar8ReadSample(samples) with { SampleCount = repeatCount };
    }

    private static SqliteScalar8Scalar8ReadResult MeasureSqliteScalar8Scalar16BlobReadRange(SqliteConnection connection, string name, int batches, int itemsPerBatch, int prefixCount, int lowerPrefix, int upperPrefix, int iterations, Span<ulong> identityHighs)
    {
        int expectedCount = CountScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix);
        ulong[] expected = CreateSortedScalar8Scalar8PublicBulkReadExpectedKeys(batches, itemsPerBatch, prefixCount, lowerPrefix, upperPrefix, expectedCount);
        CreateScalar8RangeBounds(new AllShapeReadRangeCase(name, lowerPrefix, upperPrefix), out ulong lower, out ulong upper);
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "SELECT i FROM items WHERE k >= $lower AND k <= $upper ORDER BY k, i;";
        command.Parameters.AddWithValue("$lower", EncodeSqliteSortableUnsignedScalar8(lower));
        command.Parameters.AddWithValue("$upper", EncodeSqliteSortableUnsignedScalar8(upper));
        long checksum = 0;
        long total = 0;
        Stopwatch watch = Stopwatch.StartNew();
        for (int iteration = 0; iteration < iterations; iteration++)
        {
            int count = 0;
            using SqliteDataReader reader = command.ExecuteReader();
            while (reader.Read())
            {
                byte[] identity = reader.GetFieldValue<byte[]>(0);
                identityHighs[count++] = ReadSqliteScalar16Scalar16BigEndianUInt64(identity, 0);
            }

            checksum += CheckScalar8Scalar8PublicBulkReadRange(identityHighs, count, expected);
            total += count;
        }

        watch.Stop();
        return CreateSqliteRangeReadResult(name, iterations, expectedCount, total, watch.Elapsed, Scalar8Scalar16Layout.IdentitySize, checksum);
    }

    private static void CreateScalar8RangeBounds(AllShapeReadRangeCase range, out ulong lower, out ulong upper)
    {
        lower = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(byte)range.LowerPrefix << 56);
        upper = Scalar8Scalar8Layout.EncodeUnsignedScalar8(((ulong)(byte)range.UpperPrefix << 56) | 0x00FF_FFFF_FFFF_FFFFUL);
    }

    private static void CreateScalar16RangeBounds(AllShapeReadRangeCase range, out ulong lowerHigh, out ulong lowerLow, out ulong upperHigh, out ulong upperLow)
    {
        lowerHigh = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(byte)range.LowerPrefix << 56);
        lowerLow = 0;
        upperHigh = Scalar8Scalar8Layout.EncodeUnsignedScalar8(((ulong)(byte)range.UpperPrefix << 56) | 0x00FF_FFFF_FFFF_FFFFUL);
        upperLow = ulong.MaxValue;
    }

    private static byte GetScalar16PrefixForHarness(ulong encodedHigh, ulong encodedLow, int keyDepth)
    {
        if ((uint)keyDepth >= Scalar16Scalar8Layout.KeySize)
        {
            throw new ArgumentOutOfRangeException(nameof(keyDepth), keyDepth, "SS16 scalar keys expose exactly sixteen routing bytes.");
        }

        if (keyDepth < sizeof(ulong))
        {
            int highShift = (sizeof(ulong) - 1 - keyDepth) * 8;
            return (byte)(encodedHigh >> highShift);
        }

        int lowDepth = keyDepth - sizeof(ulong);
        int lowShift = (sizeof(ulong) - 1 - lowDepth) * 8;
        return (byte)(encodedLow >> lowShift);
    }

    private static AllShapeReadRangeSweepSample CreateAllShapeReadRangeSweepSample(string name, int iterations, int rangeIdentityCount, long totalIdentities, TimeSpan elapsed, int identityBytes, DataKernelReadTelemetry telemetry, long checksum)
    {
        double seconds = Math.Max(elapsed.TotalSeconds, 0.000000001d);
        return new AllShapeReadRangeSweepSample(
            name,
            iterations,
            rangeIdentityCount,
            totalIdentities,
            elapsed,
            totalIdentities / seconds,
            seconds * 1_000_000_000d / totalIdentities,
            CalculateMiBs((double)totalIdentities * identityBytes, seconds),
            iterations == 0 ? 0 : telemetry.ReadCallCount / (double)iterations,
            iterations == 0 ? 0 : telemetry.BytesRead / (double)iterations,
            checksum,
            1);
    }

    private static SqliteScalar8Scalar8ReadResult CreateSqliteRangeReadResult(string name, int iterations, int rangeIdentityCount, long totalIdentities, TimeSpan elapsed, int identityBytes, long checksum)
    {
        double seconds = Math.Max(elapsed.TotalSeconds, 0.000000001d);
        return new SqliteScalar8Scalar8ReadResult(name, iterations, rangeIdentityCount, totalIdentities, elapsed, totalIdentities / seconds, seconds * 1_000_000_000d / totalIdentities, CalculateMiBs((double)totalIdentities * identityBytes, seconds), checksum, 1);
    }

    private static AllShapeReadRangeSweepSample SelectMedianAllShapeReadRangeSweepSample(ReadOnlySpan<AllShapeReadRangeSweepSample> samples)
    {
        AllShapeReadRangeSweepSample[] sorted = samples.ToArray();
        Array.Sort(sorted, static (left, right) => left.NsPerIdentity.CompareTo(right.NsPerIdentity));
        return sorted[sorted.Length / 2];
    }

    private static AllShapeReadRangeSweepRow CreateAllShapeReadRangeSweepRow(string shape, int payloadBytes, int identityBytes, string rangeName, int rangeIdentityCount, double libraIdentitiesPerSecond, double libraNsPerIdentity, double libraReadsPerRange, double libraBytesPerRange, double libraLogicalMiBs, double sqliteIdentitiesPerSecond, double sqliteNsPerIdentity, double sqliteLogicalMiBs)
    {
        double usefulBytesPerRange = rangeIdentityCount * (double)identityBytes;
        return new AllShapeReadRangeSweepRow(
            shape,
            rangeName,
            payloadBytes,
            identityBytes,
            rangeIdentityCount,
            libraIdentitiesPerSecond,
            sqliteIdentitiesPerSecond,
            libraNsPerIdentity,
            sqliteNsPerIdentity,
            libraReadsPerRange,
            libraBytesPerRange,
            usefulBytesPerRange == 0 ? 0 : libraBytesPerRange / usefulBytesPerRange,
            libraLogicalMiBs,
            sqliteLogicalMiBs,
            CalculateBaselinePercent(CalculateMiBs(libraBytesPerRange, libraNsPerIdentity * rangeIdentityCount / 1_000_000_000d), FileReserveReadBaselineMiBs));
    }

    private static void PrintAllShapeReadRangeSweepRows(IReadOnlyList<AllShapeReadRangeSweepRow> rows)
    {
        Console.WriteLine("| shape | range | ids | LibraDex ids/sec | SQLite ids/sec | LD/SQLite | ns/id | reads/range | B/range | amp | raw read % |");
        Console.WriteLine("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Count; i++)
        {
            AllShapeReadRangeSweepRow row = rows[i];
            Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"| {row.Shape} | {row.RangeName} | {row.RangeIdentityCount} | {row.LibraDexIdentitiesPerSecond:F2} | {row.SqliteIdentitiesPerSecond:F2} | {FormatMultiplier(row.LibraDexIdentitiesPerSecond, row.SqliteIdentitiesPerSecond)} | {row.LibraDexNsPerIdentity:F2} | {row.LibraDexReadsPerRange:F3} | {row.LibraDexBytesPerRange:F2} | {row.ReadAmplification:F2}x | {FormatBaselinePercent(row.RawReadBaselinePercent)} |"));
        }
    }

    private static string WriteAllShapeReadRangeSweepReport(string artifactDirectory, int batches, int itemsPerBatch, int prefixCount, int iterations, int repeatCount, int commitGapCoalesceBytes, SqliteScalar8Scalar8Options sqliteOptions, IReadOnlyList<AllShapeReadRangeSweepRow> rows)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "all-shape-read-range-sweep-current.md");
        ArchiveCurrentReport(reportPath, "all-shape-read-range-sweep");
        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# All-Shape Read Range Sweep - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches used to build each fixture: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Prefix count: `{prefixCount}`");
        builder.AppendLine($"- Read iterations per row: `{iterations}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- Commit gap coalescing during fixture build: `{commitGapCoalesceBytes}`");
        builder.AppendLine($"- SQLite journal mode: `{sqliteOptions.JournalMode}`");
        builder.AppendLine($"- SQLite synchronous mode: `{sqliteOptions.Synchronous}`");
        builder.AppendLine($"- Raw file reserve read baseline: `{FileReserveReadBaselineMiBs:F2} MiB/s`");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| shape | range | payload B | identity B | range identities | LibraDex ids/sec | SQLite ids/sec | LibraDex/SQLite | LibraDex ns/id | SQLite ns/id | reads/range | bytes/range | read amplification | logical MiB/s | raw read % |");
        builder.AppendLine("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Count; i++)
        {
            AllShapeReadRangeSweepRow row = rows[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Shape} | {row.RangeName} | {row.PayloadBytes} | {row.IdentityBytes} | {row.RangeIdentityCount} | {row.LibraDexIdentitiesPerSecond:F2} | {row.SqliteIdentitiesPerSecond:F2} | {FormatMultiplier(row.LibraDexIdentitiesPerSecond, row.SqliteIdentitiesPerSecond)} | {row.LibraDexNsPerIdentity:F2} | {row.SqliteNsPerIdentity:F2} | {row.LibraDexReadsPerRange:F3} | {row.LibraDexBytesPerRange:F2} | {row.ReadAmplification:F2}x | {row.LibraDexLogicalMiBs:F2} | {FormatBaselinePercent(row.RawReadBaselinePercent)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation Notes");
        builder.AppendLine();
        builder.AppendLine("- `LibraDex/SQLite` greater than `1.00x` means the routed shelf scan returned more identities per second than the matching SQLite schema for the same prefix range.");
        builder.AppendLine("- Read amplification is physical LibraDex bytes read per useful identity byte returned.");
        builder.AppendLine("- Raw read percent compares effective physical bytes/range throughput against the harness file-reserve read baseline.");
        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }

    private readonly record struct AllShapeReadRangeCase(string Name, int LowerPrefix, int UpperPrefix);

    private readonly record struct AllShapeReadRangeSweepSample(
        string Name,
        int Iterations,
        int RangeIdentityCount,
        long TotalIdentityCount,
        TimeSpan Elapsed,
        double IdentitiesPerSecond,
        double NsPerIdentity,
        double LogicalMiBs,
        double ReadsPerRange,
        double BytesPerRange,
        long Checksum,
        int SampleCount);

    private readonly record struct AllShapeReadRangeSweepRow(
        string Shape,
        string RangeName,
        int PayloadBytes,
        int IdentityBytes,
        int RangeIdentityCount,
        double LibraDexIdentitiesPerSecond,
        double SqliteIdentitiesPerSecond,
        double LibraDexNsPerIdentity,
        double SqliteNsPerIdentity,
        double LibraDexReadsPerRange,
        double LibraDexBytesPerRange,
        double ReadAmplification,
        double LibraDexLogicalMiBs,
        double SqliteLogicalMiBs,
        double RawReadBaselinePercent);
}
